.cr-card-infographic .cr-credit-badge{background:rgba(20,184,166,.12);border-color:rgba(20,184,166,.28);color:#2DD4BF}
.cf-credit-pill{font-size:11px;font-weight:700;padding:4px 11px;border-radius:20px;letter-spacing:.04em;border:1px solid transparent;flex-shrink:0}
.cf-credit-pill--ugc        {background:rgba(255,94,58,.12);border-color:rgba(255,94,58,.28);color:#FF5E3A}
.cf-credit-pill--campaign   {background:rgba(167,139,250,.12);border-color:rgba(167,139,250,.28);color:#A78BFA}
