.cf-credit-pill--text       {background:color-mix(in srgb, var(--green) 12%, transparent);border-color:color-mix(in srgb, var(--green) 28%, transparent);color:var(--green)}
.cf-credit-pill--web        {background:rgba(34,211,238,.12);border-color:rgba(34,211,238,.28);color:#22D3EE}
.cf-credit-pill--email      {background:rgba(34,197,94,.12);border-color:rgba(34,197,94,.28);color:#22C55E}
