/* ── Campaign — #A78BFA ── */
.cr-card-campaign{background:linear-gradient(140deg,#1C1428,#181420);border-color:rgba(167,139,250,.2);box-shadow:inset 0 0 60px rgba(167,139,250,.06)}
.cr-card-campaign::before{background:radial-gradient(ellipse at 20% 120%,rgba(167,139,250,.16) 0%,transparent 60%)}
.cr-card-campaign:hover{border-color:rgba(167,139,250,.42);box-shadow:0 16px 48px rgba(167,139,250,.12),inset 0 0 60px rgba(167,139,250,.1)}
