/* ── Brand AI — #F59E0B ── */
.cr-card-ai{background:linear-gradient(140deg,#221C08,#1A1710);border-color:rgba(245,158,11,.2);box-shadow:inset 0 0 60px rgba(245,158,11,.06)}
