.cr-card-ai .cr-card-tag{color:rgba(245,158,11,.65)}
.cr-card-ai .cr-card-title{color:rgba(255,255,255,.92)}
.cr-card-ai .cr-card-desc{color:rgba(255,255,255,.44)}
.cr-card-ai .cr-card-chip{background:rgba(245,158,11,.08);color:rgba(245,158,11,.6);border:1px solid rgba(245,158,11,.14)}
.cr-card-ai .cr-card-arrow svg{stroke:#F59E0B}

/* Horizon strip */
.cr-horizon{animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .2s both}
.cr-horizon-hd{font-size:10px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:12px}
.cr-horizon-list{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.cr-hor-item{background:var(--surface);border:1px dashed var(--border);border-radius:14px;padding:20px;display:flex;align-items:center;gap:14px;opacity:.65;cursor:default}
.cr-hor-ico{width:34px;height:34px;border-radius:9px;border:1px solid transparent;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.cr-hor-ico svg{width:16px;height:16px;fill:none;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.cr-hor-shoots .cr-hor-ico{background:#030D0D;border-color:rgba(0,168,150,.2)}
.cr-hor-shoots .cr-hor-ico svg{stroke:#00A896}
.cr-hor-video .cr-hor-ico{background:#0D0700;border-color:rgba(249,115,22,.2)}
.cr-hor-video .cr-hor-ico svg{stroke:#F97316;color:#F97316}
.cr-hor-motion .cr-hor-ico{background:#07040E;border-color:rgba(120,80,220,.2)}
.cr-hor-motion .cr-hor-ico svg{stroke:#7850DC}
.cr-hor-title{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:3px}
.cr-hor-sub{font-size:11px;color:var(--muted)}
.cr-hor-badge{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);padding:2px 7px;border-radius:4px;border:1px solid var(--border);margin-left:auto;flex-shrink:0}

@media(max-width:900px){
  .cr-grid{grid-template-columns:repeat(2,1fr)}
  .cr-horizon-list{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:540px){
  .cr-outer{padding:0 20px 60px}
  .cr-grid{grid-template-columns:1fr 1fr}
  .cr-horizon-list{grid-template-columns:1fr}
  .cr-headline{font-size:clamp(30px,8vw,40px)}
}

/* ── CREATE WORKSPACE ─────────────────────────────────────── */
#page-create-workspace{display:none;flex-direction:column}
#page-create-workspace.active{display:flex;height:100vh}
.cws-header{background:var(--surface);border-bottom:1px solid var(--border);padding:0 28px;height:52px;display:flex;align-items:center;gap:14px;flex-shrink:0}
.cws-back{display:flex;align-items:center;gap:6px;font-size:13px;color:var(--muted);cursor:pointer;transition:color var(--t)}
.cws-back:hover{color:var(--charcoal)}
.cws-back svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8}
.cws-type-badge{display:flex;align-items:center;gap:6px;background:var(--bg2);border-radius:20px;padding:4px 12px;font-size:12px;font-weight:600;color:var(--c2)}
.cws-type-badge svg{width:14px;height:14px;fill:none;stroke-width:1.8}

/* ── ASSISTANT page (kept, not in sidebar) ──────────────────── */
#page-aichat{display:none;flex-direction:column}
#page-aichat.active{display:flex;height:100%;overflow:hidden}
.chat-shell{display:flex;flex-direction:column;height:100%;min-height:0;max-width:780px;margin:0 auto;width:100%;padding:0 24px}
.chat-feed{flex:1;min-height:0;overflow-y:auto;padding:24px 0 16px;display:flex;flex-direction:column;gap:20px}
.chat-feed.feed-welcome{justify-content:center;overflow:hidden;padding:0 0 16px}
.chat-welcome{text-align:center;padding:0 20px 24px;max-width:480px;margin:0 auto;width:100%}
.chat-welcome-icon{width:56px;height:56px;background:var(--glt);border-radius:16px;display:flex;align-items:center;justify-content:center;margin:0 auto 20px}
.chat-welcome-icon svg{width:28px;height:28px;color:var(--green)}
.chat-welcome h2{font-family:'Instrument Serif',serif;font-size:28px;color:var(--charcoal);letter-spacing:-.4px;margin-bottom:10px}
.chat-welcome p{font-size:14px;color:var(--muted);line-height:1.7;margin-bottom:16px}
.chat-welcome-sub{font-size:12px;color:var(--m2);margin-bottom:20px!important}
.chat-suggestions{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}
.chat-sug{background:var(--surface);border:1px solid var(--border);border-radius:20px;padding:7px 16px;font-size:13px;color:var(--c2);cursor:pointer;transition:all var(--t)}
.chat-sug:hover{background:var(--bg2);border-color:var(--b2)}
/* Assistant starter prompts — full-sentence chips */
.chat-suggestions.ast-starters{flex-direction:column;align-items:stretch;gap:6px}
.chat-suggestions.ast-starters .chat-sug{border-radius:10px;text-align:left;line-height:1.5;padding:10px 16px;font-size:13px}
.ast-clear-row{display:flex;align-items:center;justify-content:space-between;padding:8px 0 16px;margin-bottom:4px;border-bottom:1px solid var(--border)}
.ast-hist-label{font-size:11px;color:var(--muted);letter-spacing:.04em}
.ast-clear-btn{font-size:11px;color:var(--muted);background:none;border:none;cursor:pointer;padding:0;text-decoration:underline;text-underline-offset:2px}
.ast-clear-btn:hover{color:var(--charcoal)}
.ast-memory-notice{font-size:12px;color:var(--muted);text-align:center;padding:12px 16px;background:var(--surface);border:1px solid var(--border);border-radius:10px;margin:8px 0}
.ast-memory-notice button{background:none;border:none;cursor:pointer;font-size:12px;color:var(--gm);font-weight:500;padding:0;margin-left:4px}
.ast-memory-notice button:hover{text-decoration:underline}
.chat-msg{display:flex;gap:12px;align-items:flex-start;max-width:100%}
.chat-msg.user{justify-content:flex-end}
.chat-bubble{border-radius:18px;padding:12px 16px;font-size:14px;line-height:1.6;max-width:72%}
.user-bubble{background:var(--green);color:#000;border-radius:18px 18px 4px 18px}
.ai-bubble{background:var(--surface);border:1px solid var(--border);border-radius:4px 18px 18px 18px;max-width:80%;padding:16px 18px}
.chat-ai-avatar{width:30px;height:30px;border-radius:8px;background:var(--green);display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:2px}
.chat-ai-avatar svg{width:16px;height:16px;color:#fff}
.chat-result-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.9px;color:var(--m2);margin-bottom:12px}
.chat-text-response{font-size:14px;line-height:1.7;color:var(--t1);white-space:pre-wrap;word-break:break-word}
.chat-visual{border-radius:14px;overflow:hidden;padding:32px 24px;text-align:center;margin:4px 0;min-height:160px;display:flex;flex-direction:column;justify-content:center;gap:8px}
.cv-brand{font-size:10px;color:rgba(255,255,255,.45);text-transform:uppercase;letter-spacing:1.5px}
.cv-hl{font-family:'Instrument Serif',serif;font-size:22px;color:#fff;letter-spacing:-.4px;line-height:1.2}
.cv-sub{font-size:12px;color:rgba(255,255,255,.65);line-height:1.5}
.cv-cta{display:inline-block;background:rgba(255,255,255,.15);color:#fff;border:1px solid rgba(255,255,255,.25);border-radius:8px;padding:7px 18px;font-size:12px;font-weight:500;margin-top:6px;align-self:center}
.chat-ig{border-radius:14px;padding:22px;display:flex;flex-direction:column;gap:10px;min-height:140px;justify-content:space-between}
.cig-top{display:flex;align-items:center;gap:8px}
.cig-dot{width:28px;height:28px;border-radius:7px;background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600;color:#fff}
.cig-name{font-size:12px;color:rgba(255,255,255,.8);font-weight:500}
.cig-hl{font-family:'Instrument Serif',serif;font-size:20px;color:#fff;letter-spacing:-.3px;line-height:1.2}
.cig-body{font-size:12px;color:rgba(255,255,255,.7);line-height:1.5}
.cig-cta{background:#fff;color:var(--green);border:none;border-radius:6px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;align-self:flex-start}
.chat-list{display:flex;flex-direction:column;gap:8px}
.chat-list-item{display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-bottom:1px solid var(--border)}
.chat-list-item:last-child{border-bottom:none}
.chat-list-num{width:22px;height:22px;border-radius:50%;background:var(--glt);color:var(--gm);font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px}
.chat-list-item span:last-child{font-size:13px;color:var(--charcoal);line-height:1.55}
.chat-copy{display:flex;flex-direction:column;gap:10px}
.chat-copy-block{background:var(--bg2);border-radius:10px;padding:12px 14px}
.chat-copy-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.8px;color:var(--m2);margin-bottom:5px}
.chat-copy-text{font-size:13px;color:var(--charcoal);line-height:1.6}
.chat-actions{margin-top:12px;display:flex;gap:8px}
.chat-typing{display:flex;gap:4px;align-items:center;padding:6px 0}
.chat-typing span{width:7px;height:7px;border-radius:50%;background:var(--m2);animation:typing 1.2s infinite}
.chat-typing span:nth-child(2){animation-delay:.2s}
.chat-typing span:nth-child(3){animation-delay:.4s}
@keyframes typing{0%,60%,100%{opacity:.3;transform:translateY(0)}30%{opacity:1;transform:translateY(-4px)}}
.chat-input-area{padding:20px 0 32px;flex-shrink:0}
.chat-controls{display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap}
.chat-ctrl-sel{background:var(--surface);border:1px solid var(--border);border-radius:20px;padding:5px 12px;font-size:12px;color:var(--c2);cursor:pointer;appearance:none;outline:none;font-family:'Geist',sans-serif}
.chat-ctrl-sel:focus{border-color:var(--gm)}
.chat-input-box{display:flex;align-items:flex-end;gap:10px;background:var(--surface);border:1.5px solid var(--border);border-radius:18px;padding:12px 12px 12px 18px;box-shadow:0 2px 12px rgba(0,0,0,.05);transition:border-color var(--t),box-shadow var(--t)}
.chat-input-box:focus-within{border-color:var(--gm);box-shadow:0 4px 20px color-mix(in srgb, var(--green) 10%, transparent)}
.chat-input-box textarea{flex:1;background:none;border:none;outline:none;resize:none;font-size:14px;color:var(--charcoal);line-height:1.55;max-height:120px;min-height:24px;overflow-y:auto}
.chat-input-box textarea::placeholder{color:var(--m2)}
.chat-send{width:36px;height:36px;border-radius:10px;background:var(--green);border:none;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;transition:background var(--t);align-self:flex-end}
.chat-send:hover{background:var(--gm)}
.chat-send svg{width:16px;height:16px;fill:none;stroke:#fff;stroke-width:2}


/* ═══ STUDIO ═══════════════════════════════════════════════════ */
#page-studio{display:none;padding:0}
#page-studio.active{display:block}

.bb-hub{width:100%}
.st-outer{padding:0 32px 40px}

/* Compact hero bar */
.st-hero-bar{
  display:flex;
  align-items:center;
  padding:22px 0 20px;
  border-bottom:1px solid var(--border);
  animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) both;
  flex-shrink:0;
}
.st-hbar-info{display:flex;flex-direction:column;gap:8px;min-width:0}
.st-hbar-title-row{display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.st-eyebrow{display:flex;align-items:center;gap:8px}
.st-eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--border);flex-shrink:0;transition:background .3s,box-shadow .3s}
.st-eyebrow-dot.active{background:var(--green);box-shadow:0 0 0 3px color-mix(in srgb, var(--green) 20%, transparent);animation:dashDotPulse 2.5s ease-in-out infinite}
.st-eyebrow-txt{font-size:11px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.st-headline{font-family:'Instrument Serif',serif;font-size:clamp(22px,2.6vw,32px);font-weight:400;color:var(--charcoal);letter-spacing:-.8px;line-height:1.05;margin:0}
.st-headline em{font-style:italic;color:var(--green)}
.st-level-badge{display:inline-flex;align-items:center;padding:4px 11px;border-radius:20px;border:1px solid var(--border);background:var(--surface);flex-shrink:0}
.st-level-badge-txt{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);transition:color .5s}

/* Intelligence Level card */
.st-il-card{background:linear-gradient(160deg,var(--surface) 60%,color-mix(in srgb, var(--green) 3%, transparent));border:1px solid color-mix(in srgb, var(--green) 10%, transparent);border-radius:20px;padding:24px;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .06s both}
.st-il-hd{display:flex;flex-direction:column;align-items:center;margin-bottom:20px}
.st-il-num{font-family:'Instrument Serif',serif;font-size:54px;color:var(--charcoal);letter-spacing:-2px;line-height:1}
.st-il-lbl{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--m2);margin-top:6px}
.st-il-msg{font-size:13px;color:var(--charcoal);line-height:1.6;margin:0 0 16px}
.st-il-bar-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px}
.st-il-bar-lbl{font-size:11px;font-weight:500;color:var(--muted)}
.st-il-bar-val{font-size:11px;font-weight:700;color:var(--green)}
.st-il-bar-track{height:3px;background:var(--border);border-radius:2px;overflow:hidden;margin-bottom:16px}
.st-il-bar-fill{height:100%;background:var(--green);border-radius:2px;transition:width 1.2s cubic-bezier(.16,1,.3,1);box-shadow:0 0 8px color-mix(in srgb, var(--green) 35%, transparent)}
.st-il-attrs{display:flex;flex-wrap:wrap;gap:6px}
.st-il-attr{font-size:11px;font-weight:500;color:var(--muted);background:var(--bg2);border:1px solid var(--border);border-radius:6px;padding:4px 9px;line-height:1}

/* Sections */
.st-section{margin-bottom:20px;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .12s both}
.st-section-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.st-section-label{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--m2)}
.st-section-acts{display:flex;align-items:center;gap:8px}
.st-act-btn{display:inline-flex;align-items:center;gap:6px;padding:6px 13px;border-radius:8px;border:1px solid var(--border);background:var(--surface);font-size:12px;font-weight:600;color:var(--muted);cursor:pointer;transition:border-color .18s,color .18s,background .18s}
.st-act-btn svg{width:13px;height:13px;flex-shrink:0;stroke:currentColor;fill:none}
.st-act-btn:hover{border-color:var(--b2);color:var(--charcoal)}
.st-act-btn.st-act-primary{border-color:color-mix(in srgb, var(--green) 30%, transparent);color:var(--green);background:color-mix(in srgb, var(--green) 6%, transparent)}
.st-act-btn.st-act-primary:hover{border-color:var(--green);background:color-mix(in srgb, var(--green) 12%, transparent)}

/* BrandCore preview grid — auto-fill on wide canvas */
.st-bc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px}
.st-bc-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:18px 16px;min-height:110px;display:flex;flex-direction:column}
.st-bc-card-label{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--m2);margin-bottom:10px;flex-shrink:0}
.st-bc-card-body{flex:1;display:flex;flex-direction:column;justify-content:center}
.st-bc-swatches{display:flex;gap:5px;flex-wrap:wrap}
.st-bc-swatch{width:22px;height:22px;border-radius:6px;border:1px solid rgba(255,255,255,.08);flex-shrink:0}
.st-bc-font{font-size:13px;color:var(--charcoal);font-weight:500}
.st-bc-tags{display:flex;gap:4px;flex-wrap:wrap}
.st-bc-tag{font-size:10px;padding:2px 7px;border-radius:4px;background:rgba(255,255,255,.06);border:1px solid var(--border);color:var(--muted)}
.st-bc-promise{font-size:11px;color:var(--muted);line-height:1.55}
.st-bc-empty{text-align:center;padding:48px 24px;background:var(--surface);border:1px dashed var(--b2);border-radius:16px}
.st-bc-empty-ico svg{width:32px;height:32px;stroke:var(--m2);margin-bottom:12px}
.st-bc-empty-ttl{font-size:15px;font-weight:600;color:var(--charcoal);margin-bottom:6px}
.st-bc-empty-sub{font-size:13px;color:var(--muted);line-height:1.6;max-width:320px;margin:0 auto}

/* Quick Access Row */
.st-quickrow{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:0;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .28s both}
.st-qcard{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:20px;display:flex;align-items:center;gap:14px;cursor:pointer;transition:border-color .18s,background .18s,transform .22s cubic-bezier(.16,1,.3,1)}
.st-qcard:hover{transform:translateY(-2px);border-color:var(--b2);box-shadow:0 6px 20px rgba(0,0,0,.1)}
.st-qcard-ico{width:38px;height:38px;border-radius:10px;background:var(--bg3);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.st-qcard-ico svg{width:17px;height:17px;stroke:var(--muted);fill:none}
.st-qcard-body{flex:1}
.st-qcard-title{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:3px}
.st-qcard-sub{font-size:11px;color:var(--muted)}
.st-qcard-arr{width:14px;height:14px;stroke:var(--m2);flex-shrink:0;opacity:0;transform:translateX(-3px);transition:opacity .18s,transform .18s}
.st-qcard:hover .st-qcard-arr{opacity:1;transform:translateX(0)}

/* Panel overlay — fixed over full app */
.sh-panel-view{position:fixed;inset:0;z-index:800;display:flex;flex-direction:column;background:var(--bg)}
.sh-panel-view.hidden{display:none}
.sh-panel-header{display:flex;align-items:center;gap:16px;padding:14px 24px;background:var(--surface);border-bottom:1px solid var(--border);flex-shrink:0}
.sh-back-btn{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:500;color:var(--muted);background:none;border:none;cursor:pointer;padding:6px 10px;border-radius:8px;transition:color .2s,background .2s}
.sh-back-btn:hover{color:var(--charcoal);background:var(--bg2)}
.sh-back-btn svg{width:14px;height:14px;stroke:currentColor}
.sh-panel-title{font-size:15px;font-weight:600;color:var(--charcoal)}
.studio-panel{display:none;flex:1;overflow-y:auto}
.studio-panel.active{display:flex;flex-direction:column}

/* ── Saved ── */
.saved-panel{padding:24px}
.asset-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}
.acard{background:var(--surface);border:1px solid var(--border);border-radius:var(--rl);overflow:hidden;transition:all var(--t);position:relative}
.acard:hover{box-shadow:var(--shm)}
.acard:hover .aov{opacity:1}
.ath{height:90px;display:flex;align-items:center;justify-content:center;background:var(--bg2)}
.ameta{padding:9px 11px}
.a-name{font-size:11px;font-weight:500;color:var(--charcoal);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.a-info{font-size:10px;color:var(--muted);margin-top:2px}
.aov{position:absolute;inset:0;background:rgba(0,0,0,.58);display:flex;align-items:center;justify-content:center;gap:6px;opacity:0;transition:opacity var(--t);border-radius:var(--rl)}
.aov-btn{width:30px;height:30px;border-radius:7px;border:none;background:rgba(255,255,255,.14);color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.aov-btn:hover{background:rgba(255,255,255,.26)}
.aov-btn svg{width:13px;height:13px}

/* ── Brand Check — New Design ── */
.bc-idle{display:flex;flex-direction:column;align-items:center;gap:16px;padding:44px 24px 32px;text-align:center}
.bc-idle-ico{width:64px;height:64px;border-radius:18px;background:color-mix(in srgb, var(--green) 6%, transparent);border:1px solid color-mix(in srgb, var(--green) 18%, transparent);display:flex;align-items:center;justify-content:center;box-shadow:0 0 40px color-mix(in srgb, var(--green) 10%, transparent);color:var(--gm)}
.bc-idle-ttl{font-size:17px;font-weight:600;color:var(--charcoal);letter-spacing:-.2px}
.bc-idle-sub{font-size:13px;color:var(--muted);line-height:1.6;max-width:320px}

.bc-analyzing{display:flex;flex-direction:column;gap:0}
.bc-analyze-hd{display:flex;flex-direction:column;align-items:center;gap:10px;padding:28px 24px 20px;text-align:center}
.bc-analyze-orb{width:44px;height:44px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb, var(--green) 25%, transparent) 0%,transparent 70%);border:1.5px solid color-mix(in srgb, var(--green) 40%, transparent);animation:bcOrb 1.8s ease-in-out infinite}
@keyframes bcOrb{0%,100%{box-shadow:0 0 16px color-mix(in srgb, var(--green) 15%, transparent)}50%{box-shadow:0 0 36px color-mix(in srgb, var(--green) 45%, transparent)}}
.bc-analyze-ttl{font-size:14px;font-weight:600;color:var(--charcoal);letter-spacing:-.15px}
.bc-analyze-sub{font-size:12px;color:var(--muted)}

.bc-steps{display:flex;flex-direction:column}
.bc-step{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--border);opacity:.28;transition:opacity .2s ease}
.bc-step:last-child{border-bottom:none}
.bc-step-active{opacity:1!important}
.bc-step-done{opacity:.65!important}
.bc-step-icon{width:18px;height:18px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.bc-step-spinner{width:14px;height:14px;border:2px solid var(--border);border-top-color:var(--gm);border-radius:50%;animation:spin .65s linear infinite}
.bc-step-ck{width:18px;height:18px;border-radius:50%;background:color-mix(in srgb, var(--green) 12%, transparent);border:1px solid color-mix(in srgb, var(--green) 35%, transparent);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.bc-step-lbl{font-size:13px;color:var(--charcoal);flex:1}
.bc-step-active .bc-step-lbl{font-weight:500;color:var(--gm)}

/* Brand Check results */
.bc-score-block{display:flex;align-items:center;gap:20px;padding:20px 0 20px;border-bottom:1px solid var(--border);margin-bottom:4px}
.bc-score-ring{width:92px;height:92px;border-radius:50%;border:3px solid var(--gm);display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0}
.bc-score-num{font-family:'Instrument Serif',serif;font-size:32px;color:var(--charcoal);line-height:1;letter-spacing:-1px}
.bc-score-num span{font-size:14px;color:var(--muted)}
.bc-score-lbl{font-size:9px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin-top:2px}
.bc-score-meta{display:flex;flex-direction:column;gap:4px;flex:1}
.bc-score-level{font-size:19px;font-weight:700;letter-spacing:-.3px;line-height:1}
.bc-score-level-sub{font-size:11px;color:var(--muted);margin-bottom:4px}
.bc-reanalyze-btn{align-self:flex-start;margin-top:4px}

.bc-section{margin-top:16px}
.bc-section-hd{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:700;color:var(--c2);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px}
.bc-section-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0}
.bc-dot-str{background:var(--green)}
.bc-dot-opp{background:#F59E0B}
.bc-dot-rec{background:var(--green)}
.bc-item{display:flex;align-items:flex-start;gap:9px;padding:8px 0;border-bottom:1px solid var(--border)}
.bc-item:last-child{border-bottom:none}
.bc-item span{font-size:13px;color:var(--charcoal);line-height:1.5}
.bc-rec-item{align-items:flex-start}
.bc-rec-num{flex-shrink:0;width:18px;height:18px;border-radius:50%;background:rgba(129,140,248,.12);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);font-size:10px;font-weight:700;color:var(--green);display:flex;align-items:center;justify-content:center;margin-top:1px}
.bc-summary{margin-top:16px;padding:14px 16px;background:var(--bg2);border-radius:var(--rl);font-size:13px;color:var(--muted);line-height:1.65;font-style:italic;border-left:2px solid color-mix(in srgb, var(--green) 30%, transparent)}

/* ── Brand Check (legacy) ── */
.check-outer{padding:24px;display:flex;flex-direction:column;gap:16px}
.up-zone{border:2px dashed var(--b2);border-radius:var(--rx);padding:56px 24px;text-align:center;cursor:pointer;transition:all var(--t);background:var(--surface);display:flex;flex-direction:column;align-items:center;gap:14px}
.up-zone:hover,.up-zone.drag-over{border-color:var(--gm);background:var(--gpale)}
.up-zone svg{width:42px;height:42px;color:var(--m2)}
.up-zone h3{font-size:16px;font-weight:600;color:var(--charcoal);letter-spacing:-.2px}
.up-zone p{font-size:13px;color:var(--muted)}
.ck-or-divider{display:flex;align-items:center;gap:12px;color:var(--muted);font-size:12px;font-weight:500;text-transform:uppercase;letter-spacing:.6px}
.ck-or-divider::before,.ck-or-divider::after{content:'';flex:1;height:1px;background:var(--border)}
.ck-manual-btn{width:100%;padding:18px 20px;font-size:14px;font-weight:500;border-radius:var(--rx);border:1.5px solid var(--border);background:var(--surface);color:var(--charcoal);cursor:pointer;transition:border-color var(--t),background var(--t),color var(--t);display:flex;align-items:center;justify-content:center;gap:10px;letter-spacing:-.1px}
.ck-manual-btn svg{width:18px;height:18px;flex-shrink:0;stroke:currentColor}
.ck-manual-btn:hover{border-color:var(--gm);background:var(--gpale);color:var(--gm)}
.ck-preview-wrap{background:var(--surface);border:1px solid var(--border);border-radius:var(--rl);padding:16px;display:flex;align-items:center;gap:14px}
.ck-preview-thumb{width:72px;height:72px;border-radius:10px;overflow:hidden;flex-shrink:0;background:var(--bg3);position:relative}
.ck-preview-thumb img{width:100%;height:100%;object-fit:cover;display:block}
.ck-preview-ph{width:100%;height:100%;display:none;align-items:center;justify-content:center;position:absolute;inset:0}
.ck-preview-meta{flex:1}
.ck-preview-name{font-size:13px;font-weight:500;color:var(--charcoal);margin-bottom:3px}
.ck-preview-sub{font-size:11px;color:var(--muted)}
.ck-actions-row{display:flex;gap:8px;align-items:center}
.check-result-wrap{display:flex;flex-direction:column;gap:0}
.scd{background:var(--surface);border:1px solid var(--border);border-radius:var(--rx);padding:24px}
.big-s{font-family:'Instrument Serif',serif;font-size:64px;color:var(--charcoal);line-height:1;letter-spacing:-2px}
.big-s span{font-size:28px;color:var(--m2)}
.s-desc{font-size:12px;color:var(--muted);margin-top:4px;margin-bottom:16px}
.sbars{display:flex;flex-direction:column;gap:9px}
.sbar-row{display:flex;align-items:center;gap:10px}
.sbar-name{font-size:11px;color:var(--charcoal);width:120px;flex-shrink:0}
.sbar-track{flex:1;height:4px;background:var(--bg3);border-radius:2px;overflow:hidden}
.sbar-fill{height:100%;border-radius:2px;transition:width .6s ease}
.sbar-val{font-size:11px;font-weight:600;color:var(--c2);width:30px;text-align:right;flex-shrink:0}
.ck-items{display:flex;flex-direction:column}
.ck-row{display:flex;align-items:flex-start;gap:9px;padding:9px 0;border-bottom:1px solid var(--border)}
.ck-row:last-child{border-bottom:none}
.ck-dot{width:6px;height:6px;border-radius:50%;flex-shrink:0;margin-top:4px}
.ck-dot.p{background:var(--green)}.ck-dot.w{background:#F59E0B}.ck-dot.f{background:#EF4444}
.ck-txt p{font-size:12px;color:var(--charcoal);line-height:1.45}
.ck-txt small{font-size:11px;color:var(--muted)}

/* ── Campaigns ── */
.camp-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--rl);padding:16px;cursor:pointer;transition:all var(--t);margin-bottom:10px}
.camp-card:hover{transform:translateY(-2px);box-shadow:var(--shm);border-color:var(--b2)}
.camp-name{font-size:14px;font-weight:600;color:var(--charcoal);margin-bottom:3px}
.camp-meta{font-size:12px;color:var(--muted);margin-bottom:8px}
.camp-pb{height:3px;background:var(--bg3);border-radius:2px;overflow:hidden}
.camp-pf{height:100%;background:var(--green);border-radius:2px;transition:width .4s ease}
.camp-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:4px}
.camp-detail-card{background:var(--bg2);border-radius:var(--r);padding:12px 14px}
.camp-detail-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.7px;color:var(--m2);margin-bottom:4px}
.camp-detail-val{font-size:13px;color:var(--charcoal);line-height:1.5}
.camp-asset-row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:4px}
.camp-asset-thumb{width:48px;height:48px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;cursor:pointer;transition:transform var(--t)}
.camp-asset-thumb:hover{transform:scale(1.08)}
.camp-preview-grid{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:4px}
.camp-preview-item{display:flex;flex-direction:column;align-items:center}
.camp-preview-frame:hover{opacity:.85}
.camp-detail-actions{display:flex;gap:8px;flex-wrap:wrap;padding-top:16px;border-top:1px solid var(--border);margin-top:16px}
.nc-asset-pick{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:var(--r);border:1.5px solid var(--border);cursor:pointer;transition:all var(--t);margin-bottom:6px}
.nc-asset-pick:hover{border-color:var(--gm);background:var(--gpale)}
.nc-asset-pick.selected{border-color:var(--gm);background:var(--gpale)}

@media(max-width:900px){
  .st-canvas{grid-template-columns:1fr}
  .st-intel-col{order:-1}
}
@media(max-width:640px){
  .st-quickrow{grid-template-columns:1fr}
}
@media(max-width:540px){
  .st-outer{padding:64px 20px 40px}
  .st-bc-grid{grid-template-columns:repeat(2,1fr)}
}


/* ═══ BRAND CORE ═══════════════════════════════════════════════ */
#page-brandcore{padding:28px 32px;max-width:1000px}
.ph{margin-bottom:28px}
.ph-ttl{font-family:'Instrument Serif',serif;font-size:24px;color:var(--charcoal);letter-spacing:-.3px;margin-bottom:3px}
.ph-sub{font-size:13px;color:var(--muted);line-height:1.5}
.bcs{background:var(--surface);border:1px solid var(--border);border-radius:var(--rl);padding:20px;margin-bottom:16px}
.bcs-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}
.bcs-ttl{font-size:14px;font-weight:600;color:var(--charcoal)}
.sw-list{display:flex;gap:10px;flex-wrap:wrap}
.sw-card{cursor:pointer;transition:transform var(--t);display:flex;flex-direction:column;align-items:center;gap:5px}
.sw-card:hover{transform:translateY(-2px)}
.sw-blk{width:52px;height:44px;border-radius:9px;border:1px solid rgba(0,0,0,.06)}
.sw-name{font-size:10px;font-weight:500;color:var(--c2)}.sw-hex{font-size:10px;color:var(--m2)}
.frow{display:flex;align-items:center;gap:16px;padding:12px 0;border-bottom:1px solid var(--border)}
.frow:last-child{border-bottom:none}
.f-ptxt{flex:1}.f-role{font-size:11px;font-weight:600;color:var(--m2);text-transform:uppercase;letter-spacing:.6px;margin-bottom:3px}
.f-demo{font-size:22px;color:var(--charcoal);line-height:1}.f-meta{font-size:11px;color:var(--muted);margin-top:3px}
.tag{display:inline-flex;align-items:center;gap:4px;background:var(--glt);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);color:var(--gm);font-size:12px;padding:4px 10px;border-radius:20px;margin:3px}
.tag-r{background:var(--err-bg);border-color:#FECACA;color:var(--err-c)}
/* Legacy logo placeholders — kept for compatibility */
.logo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.lcard{background:var(--bg2);border:1px solid var(--border);border-radius:var(--rl);padding:20px;text-align:center}
.lcard-dk{background:var(--charcoal);border-color:#333}
.l-prev{width:52px;height:52px;border-radius:12px;background:var(--green);display:flex;align-items:center;justify-content:center;font-family:'Instrument Serif',serif;font-size:18px;color:#000;margin:0 auto 10px}
.l-lbl{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.7px;color:var(--m2)}
.lcard-dk .l-lbl{color:rgba(255,255,255,.4)}

/* ── Logo management cards ──────────────────────────────────── */
.logo-mgmt-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:14px;
  margin-top:4px;
}
.logo-mgmt-card{
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--rx);
  overflow:hidden;
  display:flex;
  flex-direction:column;
}
.lmc-preview{
  aspect-ratio:1 / 1;
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--bg2);
  border-bottom:1px solid var(--border);
  padding:14px;
  overflow:hidden;
}
.lmc-img{
  max-width:100%;
  max-height:100%;
  object-fit:contain;
  border-radius:4px;
  display:block;
}
.lmc-empty{
  aspect-ratio:1 / 1;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:8px;
  color:var(--muted);
  cursor:pointer;
  background:var(--bg2);
  border-bottom:1px solid var(--border);
  transition:background var(--t),color var(--t);
}
.lmc-empty:hover{background:var(--glt);color:var(--gm)}
.lmc-empty span{font-size:11.5px;font-weight:500}
.lmc-footer{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:9px 11px;
  gap:6px;
}
.lmc-lbl{
  font-size:11.5px;
  font-weight:600;
  color:var(--charcoal);
  flex:1;
  min-width:0;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.lmc-actions{display:flex;gap:5px;flex-shrink:0;align-items:center}
.lmc-remove-btn{
  width:26px;height:26px;padding:0;
  border-radius:50%;
  background:none;
  border:1px solid var(--border);
  color:var(--muted);
  font-size:10px;
  cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  transition:all var(--t);
  flex-shrink:0;
}
.lmc-remove-btn:hover{
  background:var(--err-bg,#FEF2F2);
  border-color:#FECACA;
  color:var(--err-c,#DC2626);
}

/* AI logo result */
.logo-ai-result{padding:16px 0 0}
.logo-ai-img{
  width:100%;
  border-radius:var(--rx);
  border:1px solid var(--border);
  display:block;
  margin-bottom:14px;
  background:var(--bg2);
}
.logo-ai-save-row{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
  padding:12px 14px;
  background:var(--bg2);
  border:1px solid var(--border);
  border-radius:var(--rx);
}
.logo-ai-save-lbl{
  font-size:12px;
  font-weight:600;
  color:var(--muted);
  margin-right:2px;
}

/* ═══ IDEAS (was: INSPIRATION) ══════════════════════════════════ */
#page-inspiration{display:none;padding:0}
#page-inspiration.active{display:block}

.id-outer{width:100%}
.id-cont{max-width:1040px;margin:0 auto;padding:0 40px 80px}

/* Hero */
.id-hero{position:relative;padding:44px 0 36px;overflow:hidden;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) both;text-align:center}
.id-hero-aura{position:absolute;top:-60px;left:50%;width:600px;height:400px;transform:translateX(-50%);background:radial-gradient(ellipse at center,color-mix(in srgb, var(--green) 3.5%, transparent) 0%,transparent 65%);pointer-events:none}
.id-eyebrow{display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:16px}
.id-eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 0 3px color-mix(in srgb, var(--green) 20%, transparent);animation:dashDotPulse 2.5s ease-in-out infinite;flex-shrink:0}
.id-eyebrow-txt{font-size:11px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.id-headline{font-family:'Instrument Serif',serif;font-size:clamp(36px,5vw,58px);font-weight:400;color:var(--charcoal);letter-spacing:-1.8px;line-height:1.05;margin-bottom:14px}
.id-headline em{font-style:italic;color:var(--green)}
.id-sub{font-size:14px;color:var(--muted);line-height:1.7;max-width:440px;margin:0 auto}

/* Filter tabs */
.id-filter-row{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;margin-bottom:14px;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .08s both}
.id-filt{padding:7px 16px;border-radius:20px;border:1px solid var(--border);background:var(--surface);font-size:12px;font-weight:600;color:var(--muted);cursor:pointer;transition:border-color .18s,color .18s,background .18s}
.id-filt:hover{border-color:var(--b2);color:var(--charcoal)}
.id-filt.id-filt-active{border-color:color-mix(in srgb, var(--green) 40%, transparent);color:var(--green);background:color-mix(in srgb, var(--green) 7%, transparent)}

/* Curation note */
.id-curation-note{display:flex;align-items:center;justify-content:center;gap:6px;margin-bottom:24px;font-size:11px;color:var(--m2);animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .12s both}
.id-curation-note svg{width:12px;height:12px;flex-shrink:0}

/* Concept card grid */
.id-concept-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .16s both}

/* Concept card */
.id-concept-card{border-radius:18px;overflow:hidden;cursor:pointer;border:1px solid var(--border);display:flex;flex-direction:column;transition:transform .28s cubic-bezier(.16,1,.3,1),box-shadow .28s,border-color .28s}
.id-concept-card:hover{transform:translateY(-4px);box-shadow:0 20px 52px rgba(0,0,0,.26);border-color:rgba(255,255,255,.1)}

/* Card thumbnail */
.id-card-thumb{height:148px;position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;padding:14px 18px;flex-shrink:0}
.id-card-thumb::after{content:'';position:absolute;inset:0;background:linear-gradient(to bottom,transparent 30%,rgba(0,0,0,.62) 100%);pointer-events:none;z-index:1}
.id-thumb-glow{position:absolute;width:140px;height:140px;border-radius:50%;top:-50px;right:-30px;filter:blur(48px);opacity:.28;pointer-events:none;z-index:0;transition:opacity .3s}
.id-concept-card:hover .id-thumb-glow{opacity:.42}
.id-thumb-lbl{font-size:9px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.4);position:relative;z-index:2;margin-bottom:5px}
.id-thumb-hl{font-family:'Instrument Serif',serif;font-size:17px;font-weight:400;color:rgba(255,255,255,.88);line-height:1.25;position:relative;z-index:2}

/* Card body */
.id-card-body{background:var(--surface);padding:15px 18px 17px;flex:1;display:flex;flex-direction:column;gap:5px}
.id-card-cat{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase}
.id-card-title{font-size:13px;font-weight:700;color:var(--charcoal);letter-spacing:-.15px;line-height:1.3}
.id-card-desc{font-size:11px;color:var(--muted);line-height:1.65;flex:1}
.id-card-foot{display:flex;align-items:center;justify-content:space-between;margin-top:10px;padding-top:10px;border-top:1px solid var(--border)}
.id-card-use{font-size:11px;font-weight:600;color:var(--muted);transition:color .18s}
.id-concept-card:hover .id-card-use{color:var(--charcoal)}
.id-card-arr{width:12px;height:12px;stroke:var(--m2);fill:none;opacity:.4;flex-shrink:0;transition:opacity .18s,transform .18s}
.id-concept-card:hover .id-card-arr{opacity:.75;transform:translateX(3px)}

/* Panel overlay (preserved — fixed like Studio) */
.id-panel-view{position:fixed;inset:0;z-index:800;display:flex;flex-direction:column;background:var(--bg)}
.id-panel-view.hidden{display:none}
.id-panel-header{display:flex;align-items:center;gap:16px;padding:14px 24px;background:var(--surface);border-bottom:1px solid var(--border);flex-shrink:0}
.id-back-btn{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:500;color:var(--muted);background:none;border:none;cursor:pointer;padding:6px 10px;border-radius:8px;transition:color .2s,background .2s}
.id-back-btn:hover{color:var(--charcoal);background:var(--bg2)}
.id-back-btn svg{width:14px;height:14px;stroke:currentColor}
.id-panel-title{font-size:15px;font-weight:600;color:var(--charcoal)}
.id-panel-content{flex:1;overflow-y:auto;padding:32px 32px 48px}
.id-ideas-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px;max-width:1040px;margin:0 auto}
.id-idea-card{background:var(--surface);border:1.5px solid var(--border);border-radius:16px;padding:20px 22px 22px;display:flex;flex-direction:column;gap:9px;transition:border-color .2s ease,box-shadow .2s ease}
.id-idea-card:hover{border-color:var(--b2);box-shadow:0 4px 20px rgba(0,0,0,.07)}
.id-idea-label{font-size:15px;font-weight:700;color:var(--charcoal);letter-spacing:-.2px;line-height:1.25}
.id-idea-desc{font-size:12.5px;color:var(--muted);line-height:1.65;flex:1}
.id-idea-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:4px}
.id-cta-primary{background:var(--green);color:#fff;border:none;border-radius:20px;padding:7px 16px;font-size:12px;font-weight:600;cursor:pointer;transition:background .2s,transform .15s;pointer-events:all !important;white-space:nowrap}
.id-cta-primary:hover{background:var(--green);transform:scale(1.03)}
.id-cta-secondary{background:var(--bg2);color:var(--charcoal);border:1.5px solid var(--border);border-radius:20px;padding:7px 16px;font-size:12px;font-weight:500;cursor:pointer;transition:background .2s,transform .15s;pointer-events:all !important;white-space:nowrap}
.id-cta-secondary:hover{background:var(--bg3);transform:scale(1.03)}


/* ── Inspiration V1: section layout ──────────────────────────── */
.id-section{margin-bottom:48px;animation:dashFadeUp .45s cubic-bezier(.22,1,.36,1) both}
.id-section+.id-section{animation-delay:.06s}
.id-section-hdr{display:flex;align-items:center;gap:10px;margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid var(--border)}
.id-section-emoji{font-size:16px;line-height:1;flex-shrink:0}
.id-section-lbl{font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}
.id-section-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}

/* ── Use This Inspiration button ──────────────────────────────── */
.id-card-cta{display:block;width:100%;margin-top:12px;padding:9px 14px;background:color-mix(in srgb, var(--green) 8%, transparent);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);border-radius:10px;color:color-mix(in srgb, var(--green) 75%, transparent);font-size:11.5px;font-weight:600;text-align:center;cursor:pointer;transition:background .18s,border-color .18s,color .18s;pointer-events:none;letter-spacing:.01em}
.id-concept-card:hover .id-card-cta{background:color-mix(in srgb, var(--green) 16%, transparent);border-color:color-mix(in srgb, var(--green) 45%, transparent);color:var(--green)}

@media(max-width:900px){.id-section-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:540px){.id-section-grid{grid-template-columns:1fr}}
@media(max-width:860px){.id-concept-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:540px){
  .id-cont{padding:0 20px 60px}
  .id-hero{padding:56px 0 28px}
  .id-concept-grid{grid-template-columns:1fr}
  .id-filter-row{gap:6px}
  .id-panel-content{padding:20px}
}


/* ═══ SIDEBAR USAGE INDICATOR ══════════════════════════════════ */
.sb-usage-wrap{padding:4px 8px 2px}
.sb-plan-row{margin-bottom:5px}
.sb-plan-label{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;border-radius:20px;padding:2px 9px}
.sb-plan-free    {background:var(--bg2);color:var(--muted)}
.sb-plan-starter {background:var(--glt);color:var(--gm)}
.sb-plan-creator     {background:#EEF5FF;color:#2563EB}
.sb-plan-professional{background:#FFF0E6;color:#C45511}
.usage-badge{display:inline-block;font-size:11px;font-weight:500;border-radius:20px;padding:3px 10px;letter-spacing:.01em}
.usage-badge-ok   {background:var(--glt);color:var(--gm)}
.usage-badge-low  {background:var(--warn-bg);color:var(--warn-c)}
.usage-badge-empty{background:var(--err-bg);color:var(--err-c)}

/* ═══ USAGE LIMIT IN-FEED MESSAGE ══════════════════════════════ */
.usage-limit-msg{margin:8px 0}
.usage-limit-inner{
  display:flex;align-items:center;gap:14px;
  background:var(--warn-bg);
  border:1px solid rgba(146,64,14,.18);
  border-radius:var(--rl);
  padding:16px 18px;
}
.usage-limit-icon{width:26px;height:26px;flex-shrink:0;color:var(--warn-c)}
.usage-limit-icon svg{width:26px;height:26px}
.usage-limit-text{flex:1;min-width:0}
.usage-limit-title{font-size:13px;font-weight:600;color:var(--warn-c);margin-bottom:3px}
.usage-limit-sub{font-size:12px;color:var(--charcoal);line-height:1.55}
.usage-limit-cta{flex-shrink:0}

/* ═══ SOFT PAYWALL ══════════════════════════════════════════════ */
#softPaywallModal{
  position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.72);
  display:flex;align-items:center;justify-content:center;
  backdrop-filter:blur(4px);
  opacity:0;transition:opacity 0.28s ease;
}
#softPaywallModal.sp-visible{opacity:1;}
.sp-card{
  position:relative;width:400px;max-width:calc(100vw - 32px);
  background:#0E0E0E;border:1px solid rgba(255,255,255,0.08);
  border-radius:16px;overflow:hidden;
  box-shadow:0 24px 64px rgba(0,0,0,0.6);
  transform:translateY(10px);transition:transform 0.28s ease;
}
#softPaywallModal.sp-visible .sp-card{transform:translateY(0);}
.sp-accent-bar{height:3px;background:linear-gradient(90deg,var(--green) 0%,color-mix(in srgb, var(--green) 25%, transparent) 100%);}
.sp-body{padding:28px 28px 24px;}
.sp-close{
  position:absolute;top:14px;right:14px;width:28px;height:28px;
  background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.1);
  border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;
  color:rgba(255,255,255,0.45);transition:background 0.18s,color 0.18s;
}
.sp-close:hover{background:rgba(255,255,255,0.12);color:#fff;}
.sp-close svg{width:12px;height:12px;}
.sp-title{font-size:20px;font-weight:700;color:#fff;letter-spacing:-0.3px;margin-bottom:6px;}
.sp-sub{font-size:14px;color:rgba(255,255,255,0.45);margin-bottom:22px;line-height:1.5;}
.sp-progress-section{
  background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);
  border-radius:10px;padding:16px;margin-bottom:22px;
}
.sp-progress-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;}
.sp-progress-label{font-size:11px;font-weight:600;color:rgba(255,255,255,0.35);text-transform:uppercase;letter-spacing:0.7px;}
.sp-progress-pct{font-size:11px;font-weight:700;color:var(--green);}
.sp-progress-track{height:4px;background:rgba(255,255,255,0.08);border-radius:2px;overflow:hidden;margin-bottom:14px;}
.sp-progress-fill{height:100%;width:0;background:var(--green);border-radius:2px;transition:width 0.55s cubic-bezier(.4,0,.2,1);}
.sp-progress-list{display:flex;flex-direction:column;gap:8px;}
.sp-progress-item{display:flex;align-items:center;gap:10px;font-size:13px;}
.sp-done .sp-item-label{color:rgba(255,255,255,0.85);}
.sp-locked .sp-item-label{color:rgba(255,255,255,0.3);}
.sp-item-icon{width:16px;height:16px;flex-shrink:0;display:flex;align-items:center;justify-content:center;}
.sp-item-icon svg{width:14px;height:14px;}
.sp-cta-primary{
  width:100%;padding:13px;background:var(--green);color:#080808;
  border:none;border-radius:8px;font-size:14px;font-weight:700;letter-spacing:-0.1px;
  cursor:pointer;margin-bottom:10px;transition:opacity 0.18s;
}
.sp-cta-primary:hover{opacity:0.86;}
.sp-cta-secondary{
  width:100%;padding:10px;background:transparent;color:rgba(255,255,255,0.38);
  border:none;border-radius:8px;font-size:13px;cursor:pointer;transition:color 0.18s;
}
.sp-cta-secondary:hover{color:rgba(255,255,255,0.65);}

/* ── Upgrade reminder bar ─────────────────────────────────────── */
#upgradeBar{
  position:fixed;bottom:0;left:0;right:0;z-index:8888;
  background:#0E0E0E;border-top:1px solid color-mix(in srgb, var(--green) 18%, transparent);
  padding:13px 20px;display:flex;align-items:center;justify-content:space-between;
  transform:translateY(100%);transition:transform 0.28s ease;
}
#upgradeBar.upgrade-bar-visible{transform:translateY(0);}
.upgrade-bar-inner{display:flex;align-items:center;gap:6px;font-size:13px;color:rgba(255,255,255,0.5);}
.upgrade-bar-link{
  background:none;border:none;color:var(--green);font-size:13px;font-weight:600;
  cursor:pointer;padding:0;text-decoration:underline;text-underline-offset:2px;
}
.upgrade-bar-link:hover{opacity:0.75;}
.upgrade-bar-dismiss{
  background:none;border:none;color:rgba(255,255,255,0.28);font-size:18px;line-height:1;
  cursor:pointer;padding:0 2px;transition:color 0.18s;
}
.upgrade-bar-dismiss:hover{color:rgba(255,255,255,0.6);}

/* ═══ TEAM PAGE ══════════════════════════════════════════════════ */
#page-team{display:none;padding:0}
#page-team.active{display:flex;flex-direction:column;height:100%}
.tm-outer{display:flex;flex-direction:column;height:100%;padding:22px 32px 14px;gap:14px;overflow-y:auto}

/* Compact header */
.tm-hdr{display:flex;align-items:center;justify-content:space-between;flex-shrink:0;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) both}
.tm-hdr-left{display:flex;flex-direction:column;gap:6px}
.tm-eyebrow{display:flex;align-items:center;gap:7px}
.tm-eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 0 3px color-mix(in srgb, var(--green) 20%, transparent);animation:dashDotPulse 2.5s ease-in-out infinite;flex-shrink:0}
.tm-eyebrow span{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.tm-hdr-title{font-family:'Instrument Serif',serif;font-size:clamp(20px,2.4vw,28px);font-weight:400;color:var(--charcoal);letter-spacing:-.6px;line-height:1.1;margin:0}
.tm-hdr-title em{font-style:italic;color:var(--green)}
.tm-hdr-stats{display:flex;gap:24px;align-items:center}
.tm-hdr-stat{display:flex;flex-direction:column;align-items:flex-end;gap:1px}
.tm-stat-val{font-family:'Instrument Serif',serif;font-size:20px;color:var(--charcoal);letter-spacing:-.6px;line-height:1}
.tm-stat-lbl{font-size:9px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.tm-stat-status{font-family:'Geist',sans-serif;font-size:13px;font-weight:700;color:var(--green);letter-spacing:0}

/* Section base */
.tm-section{background:var(--surface);border:1px solid var(--border);border-radius:18px;padding:20px}
.tm-section-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.tm-section-title{font-size:13px;font-weight:700;color:var(--charcoal);letter-spacing:-.2px}
.tm-section-sub{font-size:11px;color:var(--muted);margin-top:2px}

/* Projects — primary centerpiece */
.tm-projects-section{flex-shrink:0;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .08s both}
.tm-proj-list{display:flex;flex-direction:column;gap:8px}
.tm-proj-row{display:flex;align-items:center;gap:16px;background:var(--bg);border:1px solid var(--border);border-radius:12px;padding:14px 18px;transition:border-color .18s,transform .22s cubic-bezier(.16,1,.3,1)}
.tm-proj-row:hover{border-color:color-mix(in srgb, var(--green) 18%, transparent);transform:translateX(3px)}
.tm-proj-type{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;padding:3px 9px;border-radius:20px;flex-shrink:0}
.tm-proj-name{font-size:13px;font-weight:700;color:var(--charcoal);letter-spacing:-.2px;flex:1;min-width:0}
.tm-proj-meta{font-size:11px;color:var(--muted);flex-shrink:0;white-space:nowrap}
.tm-proj-bar-wrap{width:80px;flex-shrink:0}
.tm-proj-bar{height:2px;border-radius:2px;background:var(--border)}
.tm-proj-fill{height:100%;border-radius:2px;transition:width 1s cubic-bezier(.16,1,.3,1)}
.tm-proj-empty{padding:28px 20px;text-align:center}
.tm-proj-empty strong{display:block;font-size:13px;font-weight:700;color:var(--charcoal);margin-bottom:4px}
.tm-proj-empty span{font-size:12px;color:var(--muted)}

/* Lower grid — members + activity */
.tm-lower{display:grid;grid-template-columns:1fr 1fr;gap:14px;flex-shrink:0;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .16s both}
.tm-lower-panel{display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--border);border-radius:18px;padding:20px}

/* Invite button */
.tm-invite-btn{display:flex;align-items:center;gap:6px;padding:7px 14px;border-radius:20px;border:1px solid color-mix(in srgb, var(--green) 30%, transparent);background:color-mix(in srgb, var(--green) 6%, transparent);color:var(--green);font-size:11px;font-weight:600;cursor:pointer;transition:border-color .18s,background .18s;flex-shrink:0}
.tm-invite-btn:hover{border-color:color-mix(in srgb, var(--green) 50%, transparent);background:color-mix(in srgb, var(--green) 10%, transparent)}
.tm-invite-btn svg{width:11px;height:11px}

/* Member rows */
.tm-member-list{display:flex;flex-direction:column;flex:1}
.tm-member-row{display:flex;align-items:center;gap:11px;padding:10px 0;border-bottom:1px solid var(--border)}
.tm-member-row:last-child{border-bottom:none}
.tm-mavatar{width:30px;height:30px;border-radius:50%;background:color-mix(in srgb, var(--green) 10%, transparent);color:var(--green);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;letter-spacing:-.5px;flex-shrink:0}
.tm-mavatar-self{background:rgba(167,139,250,.1);color:#A78BFA}
.tm-minfo{flex:1;min-width:0}
.tm-mname{font-size:12px;font-weight:600;color:var(--charcoal);letter-spacing:-.15px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tm-memail{font-size:10px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tm-mbadge{font-size:9px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:2px 8px;border-radius:20px;flex-shrink:0}
.tm-mbadge-admin{background:color-mix(in srgb, var(--green) 10%, transparent);color:var(--green);border:1px solid color-mix(in srgb, var(--green) 20%, transparent)}
.tm-mbadge-editor{background:#EEF5FF;color:#2563EB;border:1px solid #BFDBFE}
.tm-mbadge-member{background:var(--bg2);color:var(--muted);border:1px solid var(--border)}
.tm-mbadge-viewer{background:var(--bg2);color:var(--muted);border:1px solid var(--border)}
.tm-mremove{width:20px;height:20px;border-radius:50%;background:none;border:1px solid var(--border);cursor:pointer;display:flex;align-items:center;justify-content:center;color:var(--muted);transition:all .18s;flex-shrink:0}
.tm-mremove:hover{background:rgba(239,68,68,.08);border-color:#FECACA;color:#DC2626}
.tm-invite-row{display:flex;align-items:center;gap:11px;padding:10px 0;cursor:pointer;opacity:.55;transition:opacity .18s}
.tm-invite-row:hover{opacity:1}
.tm-invite-row-icon{width:30px;height:30px;border-radius:50%;background:none;border:1.5px dashed var(--border);display:flex;align-items:center;justify-content:center;color:var(--muted);flex-shrink:0}
.tm-invite-row-txt{font-size:12px;font-weight:600;color:var(--muted)}

/* Activity */
.tm-activity{display:flex;flex-direction:column;flex:1}
.tm-act-item{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--border)}
.tm-act-item:last-child{border-bottom:none}
.tm-act-dot{width:6px;height:6px;border-radius:50%;flex-shrink:0}
.tm-act-body{flex:1;font-size:11px;color:var(--charcoal);line-height:1.4}
.tm-act-body strong{font-weight:600}
.tm-act-time{font-size:10px;color:var(--muted);white-space:nowrap}
.tm-act-empty{display:flex;align-items:center;justify-content:center;flex:1;padding:20px;text-align:center;font-size:12px;color:var(--muted);line-height:1.6}

@media(max-width:800px){.tm-lower{grid-template-columns:1fr}}
@media(max-width:620px){
  .tm-outer{padding:16px 16px 8px}
  .tm-hdr{flex-direction:column;align-items:flex-start;gap:10px}
  .tm-hdr-stats{gap:16px}
  .tm-proj-bar-wrap{display:none}
}

/* ═══ GUIDED FLOW SYSTEM ════════════════════════════════════════ */

.flow-pg{
  padding:40px 28px 80px;
  max-width:640px;
  width:100%;
  margin:0 auto;
}
/* Center the builder page's scroll area */
#page-builder.active{
  display:flex;
  flex-direction:column;
  align-items:center;
  overflow-y:auto;
}

/* Topbar */
.flow-topbar{
  display:flex;align-items:center;justify-content:space-between;
  margin-bottom:32px;
}
.flow-back-btn{
  background:none;border:1px solid var(--border);border-radius:var(--rx);
  padding:7px 14px;font-size:13px;color:var(--charcoal);
  cursor:pointer;transition:all var(--t);flex-shrink:0;
}
.flow-back-btn:hover{border-color:var(--gm);color:var(--gm);background:var(--glt)}
.flow-brand-pill{
  display:inline-flex;align-items:center;gap:6px;
  background:var(--glt);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius:20px;padding:5px 13px;
  font-size:12.5px;font-weight:600;color:var(--gm);
}
.flow-brand-pill::before{
  content:"";width:8px;height:8px;border-radius:50%;
  background:var(--gm);flex-shrink:0;
}

/* AI Guide bubble */
.flow-guide{
  display:flex;align-items:flex-start;gap:14px;
  margin-bottom:28px;
  padding:20px 22px;
  background:var(--bg2);
  border:1px solid var(--border);
  border-radius:var(--rx);
}
.flow-guide-avatar{
  width:40px;height:40px;border-radius:50%;
  background:#f4f5f3;
  border:1px solid var(--border);
  display:flex;align-items:center;justify-content:center;
  overflow:hidden;flex-shrink:0;
}
.flow-guide-logo{
  width:26px;height:26px;object-fit:contain;display:block;
}
.flow-guide-content{flex:1;min-width:0}
.flow-guide-label{
  font-size:10.5px;font-weight:600;text-transform:uppercase;
  letter-spacing:.07em;color:var(--gm);margin-bottom:5px;
}
.flow-guide-message{
  font-size:15.5px;font-weight:500;color:var(--charcoal);
  line-height:1.45;transition:opacity .15s;
}

/* Progress dots */
.flow-progress{
  display:flex;gap:6px;margin-bottom:28px;
  align-items:center;flex-wrap:wrap;
}
.flow-dot{
  width:7px;height:7px;border-radius:50%;
  background:var(--border);transition:all .3s;
}
.flow-dot.done{background:var(--gm);opacity:.4}
.flow-dot.active{background:var(--gm);width:22px;border-radius:4px}

/* History strip */
.flow-history{display:flex;flex-direction:column;gap:0;margin-bottom:4px}
.flow-hist-item{
  display:flex;align-items:center;gap:10px;
  padding:7px 10px;border-radius:8px;
  cursor:pointer;transition:background .15s;
}
.flow-hist-item:hover{background:var(--bg2)}
.flow-hist-q{
  font-size:12px;color:var(--muted);flex:1;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.flow-hist-a{
  font-size:12px;font-weight:600;color:var(--charcoal);
  background:var(--bg2);border-radius:20px;padding:3px 10px;
  white-space:nowrap;max-width:180px;
  overflow:hidden;text-overflow:ellipsis;flex-shrink:0;
}

/* Step area */
.flow-step-wrap{margin-bottom:16px}
.flow-step{animation:flowStepIn .22s ease both}
@keyframes flowStepIn{
  from{opacity:0;transform:translateY(9px)}
  to{opacity:1;transform:none}
}

/* Flow option buttons (tall cards) */
.flow-options{display:flex;flex-direction:column;gap:9px}
.flow-options-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.flow-option{
  display:flex;align-items:center;gap:12px;
  padding:14px 17px;
  border:1.5px solid var(--border);border-radius:var(--rx);
  background:var(--surface);cursor:pointer;
  transition:border-color .16s,background .16s,color .16s;
  font-size:14px;font-weight:500;color:var(--charcoal);
  text-align:left;width:100%;
}
.flow-option:hover{border-color:var(--gm);background:var(--glt);color:var(--gm)}
.flow-option.active{border-color:var(--gm);background:var(--gm);color:#000}
.flow-option-check{
  width:18px;height:18px;border-radius:50%;
  border:1.5px solid currentColor;
  display:flex;align-items:center;justify-content:center;
  flex-shrink:0;opacity:.45;transition:opacity .16s;
}
.flow-option.active .flow-option-check{
  opacity:1;background:rgba(255,255,255,.22);border-color:transparent;
}
.flow-option-label{flex:1}

/* Text/textarea inputs in flow */
.flow-input-wrap{margin-top:2px}
.flow-helper-text{
  font-size:12px;color:var(--muted);line-height:1.55;
  margin-bottom:8px;font-style:italic;
}
.flow-inp{
  width:100%;padding:13px 16px;
  border-radius:var(--rx);border:1.5px solid var(--border);
  background:var(--surface);font-size:14px;color:var(--charcoal);
  transition:border-color .18s;outline:none;
  font-family:inherit;box-sizing:border-box;
}
.flow-inp:focus{border-color:var(--gm)}
.flow-inp::placeholder{color:var(--muted)}
textarea.flow-inp{min-height:90px;resize:vertical}

/* Flow nav */
.flow-nav{display:flex;align-items:center;gap:10px;margin-top:14px}
.flow-nav-back{
  background:none;border:1px solid var(--border);border-radius:var(--rx);
  padding:10px 18px;font-size:13px;color:var(--muted);
  cursor:pointer;transition:all .18s;flex-shrink:0;
}
.flow-nav-back:hover{border-color:var(--charcoal);color:var(--charcoal)}
.flow-nav-continue{flex:1;padding:11px;font-size:14px;font-weight:600}

/* Generating state */
.flow-generating{
  display:flex;flex-direction:column;align-items:center;
  gap:16px;padding:56px 20px;text-align:center;
}
.flow-generating-icon{
  width:56px;height:56px;background:var(--gm);border-radius:50%;
  display:flex;align-items:center;justify-content:center;color:#fff;
  animation:flowPulse 1.9s ease-in-out infinite;
}
@keyframes flowPulse{
  0%,100%{transform:scale(1);box-shadow:0 0 0 0 color-mix(in srgb, var(--green) 30%, transparent)}
  50%{transform:scale(1.07);box-shadow:0 0 0 14px color-mix(in srgb, var(--green) 0%, transparent)}
}
.flow-generating-text{font-size:15px;font-weight:600;color:var(--charcoal)}
.flow-generating-sub{font-size:13px;color:var(--muted);margin-top:-4px}

/* ── BrandCore review panel (image flow step 3) ─────────────── */
.flow-brandcore-panel{
  background:var(--surface);
  border:1.5px solid var(--border);
  border-radius:var(--rx);
  padding:18px 20px;
  display:flex;
  flex-direction:column;
  gap:14px;
}
.flow-brandcore-empty{
  align-items:center;
  text-align:center;
  padding:32px 24px;
  border-style:dashed;
  opacity:.75;
}
.fbp-empty-icon{color:var(--muted);margin-bottom:8px;display:flex;justify-content:center}
.fbp-empty-title{font-size:13.5px;font-weight:600;color:var(--charcoal);margin-bottom:6px}
.fbp-empty-sub{font-size:12.5px;color:var(--muted);line-height:1.65;max-width:280px}
.fbp-header{display:flex;align-items:center;gap:12px}
.fbp-icon{
  width:32px;height:32px;
  background:var(--glt);border-radius:9px;
  display:flex;align-items:center;justify-content:center;
  flex-shrink:0;color:var(--gm);
}
.fbp-brand-name{font-size:14px;font-weight:700;color:var(--charcoal);letter-spacing:-.2px}
.fbp-sub{font-size:11.5px;color:var(--muted);margin-top:2px}
.fbp-rows{display:flex;flex-direction:column;gap:10px;border-top:1px solid var(--border);padding-top:14px}
.fbp-row{display:flex;align-items:center;gap:14px}
.fbp-row-label{
  font-size:10.5px;font-weight:600;text-transform:uppercase;
  letter-spacing:.07em;color:var(--muted);
  width:72px;flex-shrink:0;
}
.fbp-row-value{font-size:13px;color:var(--charcoal);line-height:1.4}
.fbp-colors{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.fbp-swatch{
  width:22px;height:22px;border-radius:6px;
  border:1px solid rgba(0,0,0,.09);
  flex-shrink:0;cursor:default;
}
.fbp-note{
  font-size:11.5px;color:var(--muted);line-height:1.65;
}
.fbp-footer{
  border-top:1px solid var(--border);padding-top:12px;
  display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;
}
.fbp-edit-link{
  font-size:11.5px;color:var(--gm);text-decoration:none;font-weight:500;white-space:nowrap;
}
.fbp-edit-link:hover{text-decoration:underline}

/* ── Upload step ───────────────────────────────────────── */
.flow-upload-step{display:flex;flex-direction:column;gap:12px}
.flow-upload-types{display:flex;flex-direction:column;gap:8px}
.flow-upload-type-btn{
  display:flex;flex-direction:column;gap:2px;
  width:100%;text-align:left;
  background:var(--surface);border:1.5px solid var(--border);
  border-radius:var(--rx);padding:11px 14px;cursor:pointer;
  transition:border-color .15s,background .15s;
}
.flow-upload-type-btn:hover{border-color:var(--gm);background:var(--glt)}
.flow-upload-type-btn.active{border-color:var(--gm);background:var(--glt)}
.fut-label{font-size:13.5px;font-weight:600;color:var(--charcoal)}
.fut-hint{font-size:12px;color:var(--muted);margin-top:1px}
.flow-upload-area{
  border:1.5px dashed var(--border);border-radius:var(--rx);
  padding:28px 20px;text-align:center;cursor:pointer;
  display:flex;flex-direction:column;align-items:center;gap:6px;
  transition:border-color .15s,background .15s;
}
.flow-upload-area:hover{border-color:var(--gm);background:var(--glt)}
.fua-label{font-size:13.5px;font-weight:600;color:var(--charcoal)}
.fua-hint{font-size:12px;color:var(--muted)}
.flow-upload-done{
  display:flex;align-items:center;gap:10px;
  background:var(--glt);border:1.5px solid var(--gm);
  border-radius:var(--rx);padding:10px 14px;
}
.fud-check{
  width:24px;height:24px;border-radius:50%;background:var(--gm);
  color:#fff;display:flex;align-items:center;justify-content:center;flex-shrink:0;
}
.fud-info{flex:1;font-size:13px;font-weight:600;color:var(--charcoal)}
.fud-remove{
  font-size:12px;color:var(--muted);background:none;border:none;
  cursor:pointer;padding:2px 4px;text-decoration:underline;
}
.fud-remove:hover{color:var(--charcoal)}

/* Keep legacy builder classes used by result/ad/campaign rendering */
.builder-section{margin-bottom:22px}
.builder-lbl{
  font-size:12px;font-weight:600;text-transform:uppercase;
  letter-spacing:.06em;color:var(--muted);margin-bottom:10px;
  display:flex;align-items:center;gap:8px;
}
.builder-opt{font-weight:400;text-transform:none;letter-spacing:0;font-size:11.5px;color:var(--muted);opacity:.7}
.builder-req{font-weight:500;text-transform:none;letter-spacing:0;font-size:11px;color:var(--err-c,#DC2626);opacity:.85}
.b-pills{display:flex;flex-wrap:wrap;gap:8px}
.b-pill{
  padding:7px 16px;border-radius:20px;font-size:13px;font-weight:500;
  border:1.5px solid var(--border);background:var(--surface);
  color:var(--charcoal);cursor:pointer;transition:all var(--t);user-select:none;
}
.b-pill:hover{border-color:var(--gm);color:var(--gm);background:var(--glt)}
.b-pill.active{border-color:var(--gm);background:var(--gm);color:#000}

/* ── Image builder brand preview ── */
.builder-section--brand{border-top:1px solid var(--border);padding-top:18px;margin-top:4px}
.img-brand-preview{
  background:var(--bg2);border:1px solid var(--border);border-radius:10px;padding:14px 16px;
}
.img-brand-preview--empty{
  font-size:13px;color:var(--muted);text-align:center;padding:14px 16px;
  border:1px dashed var(--border);border-radius:10px;
}
.img-brand-preview--empty a{color:var(--gm);text-decoration:none}
.ibp-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.ibp-title{font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
.ibp-edit{font-size:12px;color:var(--gm);text-decoration:none;font-weight:500}
.ibp-edit:hover{text-decoration:underline}
.ibp-rows{display:flex;flex-direction:column;gap:5px}
.ibp-row{display:flex;gap:10px;align-items:baseline;font-size:13px}
.ibp-lbl{color:var(--dim);min-width:52px;font-size:12px}
.ibp-val{color:var(--charcoal);line-height:1.4}

.builder-result-wrap{
  margin-top:28px;
  border:1px solid var(--border);border-radius:var(--rx);
  overflow:hidden;
  background:var(--surface);
}
.builder-result-bar{
  display:flex;align-items:center;justify-content:space-between;
  padding:12px 16px;border-bottom:1px solid var(--border);
  background:var(--bg2);
}
.builder-result-label{
  font-size:12px;font-weight:600;text-transform:uppercase;
  letter-spacing:.06em;color:var(--muted);
}
.builder-result-actions{display:flex;gap:8px}
.builder-result-body{padding:20px}

/* Image result */
.builder-result-img{
  width:100%;border-radius:calc(var(--rx) - 2px);
  display:block;
}

/* Text result */
.builder-result-text{
  font-size:14.5px;line-height:1.7;color:var(--charcoal);
  white-space:pre-wrap;
}

/* ── Web: brand confirmation panel ──────────────────────────── */
.wbc-panel{
  padding:24px 0 8px;
  max-width:560px;
}
.wbc-title{font-size:17px;font-weight:700;color:var(--text);margin-bottom:4px}
.wbc-sub{font-size:13px;color:var(--muted);margin-bottom:20px;line-height:1.5}
.wbc-logo-wrap{margin-bottom:20px}
.wbc-logo-img{max-height:48px;max-width:180px;object-fit:contain;display:block}
.wbc-logo-empty{
  font-size:13px;font-weight:600;color:var(--muted);
  padding:10px 14px;border:1px dashed var(--border);border-radius:6px;
  display:inline-block;
}
.wbc-cols{display:flex;gap:32px;flex-wrap:wrap;margin-bottom:24px}
.wbc-section{flex:1;min-width:180px}
.wbc-section-label{
  font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;
  color:var(--muted);margin-bottom:12px;
}
.wbc-color-row{
  display:flex;align-items:center;gap:10px;
  margin-bottom:8px;cursor:pointer;
}
.wbc-swatch-wrap{position:relative;flex-shrink:0}
.wbc-swatch{
  width:28px;height:28px;border-radius:6px;
  border:1px solid rgba(255,255,255,.12);
  pointer-events:none;
}
.wbc-color-inp{
  position:absolute;inset:0;opacity:0;cursor:pointer;
  width:100%;height:100%;border:none;padding:0;
}
.wbc-color-info{display:flex;flex-direction:column;gap:1px}
.wbc-color-label{font-size:12px;font-weight:600;color:var(--text)}
.wbc-color-hex{font-size:11px;color:var(--muted);font-family:monospace}
.wbc-font-row{
  display:flex;flex-direction:column;gap:2px;
  margin-bottom:10px;
}
.wbc-font-role{font-size:11px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.05em}
.wbc-font-name{font-size:14px;color:var(--text)}
.wbc-actions{display:flex;gap:10px;padding-top:4px}
.wbc-section-full{margin-bottom:20px}
.wbc-section-sub{font-size:12px;color:var(--muted);margin-bottom:12px}

/* ── Web: section picker ─────────────────────────────────── */
.wbs-grid{display:flex;flex-wrap:wrap;gap:8px}
.wbs-item{
  display:flex;align-items:center;gap:6px;
  padding:6px 12px;border-radius:20px;
  border:1px solid var(--border);background:var(--bg2);
  cursor:pointer;user-select:none;
  font-size:12.5px;font-weight:500;color:var(--muted);
  transition:background .12s,border-color .12s,color .12s;
}
.wbs-item:hover{border-color:var(--green);color:var(--green)}
.wbs-item-on{
  background:var(--green);border-color:var(--green);color:#000;
}
.wbs-item-on:hover{background:var(--gm);border-color:var(--gm);color:#000}
.wbs-item-locked{cursor:default;opacity:.75}
.wbs-check{display:none}
.wbs-lock{
  font-size:10px;font-weight:700;text-transform:uppercase;
  letter-spacing:.04em;opacity:.7;
}

/* ── Web: edit mode indicator ────────────────────────────── */
.bwr-editbar{
  padding:8px 16px;font-size:12px;font-weight:600;
  color:#92400E;background:#FEF3C7;
  border-bottom:1px solid #FDE68A;
}
.bwr-btn-edit{border-color:var(--green);color:var(--green)}
.bwr-btn-edit:hover{background:var(--green);color:#fff}
.bwr-btn-done{border-color:#BFA07A;background:#BFA07A;color:#fff}
.bwr-btn-done:hover{background:#a88a60;border-color:#a88a60}

/* ── Web: result area ─────────────────────────────────────── */
.builder-web-result{display:flex;flex-direction:column;gap:0}
.bwr-toolbar{
  display:flex;align-items:center;justify-content:space-between;
  padding:10px 16px;border-bottom:1px solid var(--border);
  background:var(--bg2);
}
.bwr-label{font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
.bwr-actions{display:flex;gap:8px}
.bwr-btn{
  font-size:12px;font-weight:600;padding:6px 14px;
  border-radius:6px;border:1px solid var(--border);
  background:var(--surface);color:var(--text);cursor:pointer;
  transition:background .15s,border-color .15s;
}
.bwr-btn:hover{background:var(--bg2);border-color:var(--accent)}
.bwr-btn-zip{border-color:var(--accent);color:var(--accent)}
.bwr-btn-zip:hover{background:var(--accent);color:#fff}
.bwr-frame{
  width:100%;height:560px;border:none;
  background:#fff;display:block;
}
/* ── Web: publish guide ─────────────────────────────────── */
.bwr-publish{
  padding:20px 20px 16px;
  border-top:1px solid var(--border);
  background:var(--bg2);
}
.bwr-publish-title{
  font-size:13px;font-weight:700;color:var(--text);
  margin-bottom:10px;
}
.bwr-publish-steps{
  margin:0;padding-left:18px;
  display:flex;flex-direction:column;gap:6px;
}
.bwr-publish-steps li{
  font-size:12.5px;color:var(--muted);line-height:1.5;
}
.bwr-publish-steps li strong{color:var(--text)}

/* ── Image composite (visual + text overlay) ─────────────────── */
.img-composite{
  display:flex;
  flex-direction:column;
  border-radius:calc(var(--rx) - 2px);
  overflow:hidden;
}

/* Format frames — correct aspect ratios */
.img-frame{
  position:relative;
  overflow:hidden;
  width:100%;
  background:var(--bg2);
}
.img-frame-1x1  { aspect-ratio:1/1; }
.img-frame-4x5  { aspect-ratio:4/5; }
.img-frame-9x16 { aspect-ratio:9/16; max-width:340px; margin:0 auto; }
.img-frame-16x9 { aspect-ratio:16/9; }

.img-bg-layer{
  width:100%;
  height:100%;
  object-fit:cover;
  display:block;
}

/* Text overlay layer */
.img-text-layer{
  position:absolute;
  inset:0;
  display:flex;
  flex-direction:column;
  justify-content:flex-end;
  padding:22px 24px;
  transition:opacity .2s;
}
.img-text-inner{
  display:flex;
  flex-direction:column;
  gap:5px;
}

/* ── Light text (default) ── */
.img-txt-light .img-text-layer{
  background:linear-gradient(to top,rgba(0,0,0,.55) 0%,rgba(0,0,0,.18) 55%,transparent 100%);
}
.img-txt-light .itl-headline,
.img-txt-light .itl-subtext,
.img-txt-light .itl-cta { color:#fff; }

/* ── Dark text ── */
.img-txt-dark .img-text-layer{
  background:linear-gradient(to top,rgba(255,255,255,.62) 0%,rgba(255,255,255,.18) 55%,transparent 100%);
}
.img-txt-dark .itl-headline,
.img-txt-dark .itl-subtext,
.img-txt-dark .itl-cta { color:#18181A; }

/* ── Bold text style ── */
.img-txt-bold .itl-headline{
  font-family:'Geist',sans-serif;
  font-size:clamp(18px,3.8vw,32px);
  font-weight:800;
  letter-spacing:-.02em;
  line-height:1.05;
  text-transform:uppercase;
}
.img-txt-bold .itl-subtext{
  font-size:clamp(11px,1.8vw,14px);
  font-weight:500;
  opacity:.9;
  line-height:1.4;
}
.img-txt-bold .itl-cta{
  font-size:clamp(10px,1.5vw,12px);
  font-weight:700;
  letter-spacing:.1em;
  text-transform:uppercase;
  margin-top:6px;
}

/* ── Minimal text style ── */
.img-txt-minimal .itl-headline{
  font-family:'Geist',sans-serif;
  font-size:clamp(16px,3vw,26px);
  font-weight:300;
  letter-spacing:.05em;
  line-height:1.25;
}
.img-txt-minimal .itl-subtext{
  font-size:clamp(10px,1.5vw,12px);
  font-weight:400;
  opacity:.72;
  letter-spacing:.04em;
}
.img-txt-minimal .itl-cta{
  font-size:clamp(10px,1.4vw,11px);
  font-weight:500;
  letter-spacing:.14em;
  text-transform:uppercase;
  margin-top:6px;
}

/* ── Editorial text style ── */
.img-txt-editorial .itl-headline{
  font-family:'Instrument Serif',serif;
  font-size:clamp(18px,4vw,34px);
  font-weight:400;
  font-style:italic;
  line-height:1.15;
  letter-spacing:-.005em;
}
.img-txt-editorial .itl-subtext{
  font-family:'Geist',sans-serif;
  font-size:clamp(10px,1.5vw,12px);
  font-weight:400;
  letter-spacing:.07em;
  text-transform:uppercase;
  opacity:.78;
}
.img-txt-editorial .itl-cta{
  font-family:'Geist',sans-serif;
  font-size:clamp(10px,1.4vw,12px);
  font-weight:500;
  letter-spacing:.05em;
  margin-top:6px;
}

/* ── Clean text style ── */
.img-txt-clean .itl-headline{
  font-family:'Geist',sans-serif;
  font-size:clamp(16px,3.2vw,28px);
  font-weight:600;
  letter-spacing:-.01em;
  line-height:1.2;
}
.img-txt-clean .itl-subtext{
  font-size:clamp(11px,1.6vw,13px);
  font-weight:400;
  opacity:.84;
  line-height:1.5;
}
.img-txt-clean .itl-cta{
  font-size:clamp(10px,1.5vw,12px);
  font-weight:600;
  letter-spacing:.03em;
  margin-top:6px;
}

/* ── Premium text style ── */
.img-txt-premium .itl-headline{
  font-family:'Instrument Serif',serif;
  font-size:clamp(18px,3.8vw,32px);
  font-weight:400;
  letter-spacing:.02em;
  line-height:1.2;
}
.img-txt-premium .itl-subtext{
  font-family:'Geist',sans-serif;
  font-size:clamp(10px,1.5vw,11px);
  font-weight:400;
  letter-spacing:.08em;
  text-transform:uppercase;
  opacity:.78;
}
.img-txt-premium .itl-cta{
  font-family:'Geist',sans-serif;
  font-size:clamp(10px,1.4vw,11px);
  font-weight:600;
  letter-spacing:.08em;
  text-transform:uppercase;
  margin-top:6px;
}

/* Composite control bar */
.img-composite-bar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:9px 14px;
  border-top:1px solid var(--border);
  background:var(--bg2);
  flex-wrap:wrap;
  gap:8px;
}
.img-toggle-label{
  display:flex;
  align-items:center;
  gap:7px;
  font-size:12.5px;
  color:var(--charcoal);
  cursor:pointer;
  user-select:none;
}
.img-toggle-label input{cursor:pointer;accent-color:var(--gm)}
.img-color-row{display:flex;align-items:center;gap:7px}
.img-bar-lbl{font-size:12px;color:var(--muted)}
.icb{
  padding:4px 13px;
  border-radius:20px;
  font-size:12px;
  font-weight:500;
  border:1.5px solid var(--border);
  background:var(--surface);
  color:var(--charcoal);
  cursor:pointer;
  transition:all var(--t);
}
.icb.active{border-color:var(--gm);background:var(--gm);color:#000}
.icb:hover:not(.active){border-color:var(--gm);color:var(--gm)}

/* Required label in builder */
.builder-req{
  font-weight:500;
  text-transform:none;
  letter-spacing:0;
  font-size:11px;
  color:var(--err-c,#DC2626);
  opacity:.85;
}

/* Ad result */
.builder-ad-result{display:flex;flex-direction:column;gap:16px}
.builder-ad-result img{
  width:100%;border-radius:calc(var(--rx) - 2px);
  display:block;margin-bottom:4px;
}
.bar-title{font-size:10.5px;font-weight:600;text-transform:uppercase;letter-spacing:.07em;color:var(--gm);margin-bottom:4px}
.bar-headline{font-size:18px;font-weight:700;color:var(--charcoal);line-height:1.3}
.bar-body{font-size:14px;color:var(--charcoal);line-height:1.65;opacity:.85}
.bar-cta-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:4px}
.bar-cta{
  padding:8px 20px;border-radius:20px;font-size:13px;font-weight:600;
  background:var(--gm);color:#000;display:inline-block;
}

/* Campaign variation cards */
.camp-variations{display:flex;flex-direction:column;gap:20px}
.camp-var-card{border:1px solid var(--border);border-radius:var(--rx);overflow:hidden;background:var(--surface)}
.cvcard-img-wrap{width:100%}
.cvcard-img{width:100%;display:block}
.cvcard-body{padding:16px 18px;display:flex;flex-direction:column;gap:8px}
.cvcard-num{font-size:10.5px;font-weight:600;text-transform:uppercase;letter-spacing:.07em;color:var(--gm)}
.cvcard-title{font-size:13px;font-weight:700;color:var(--charcoal)}
.cvcard-headline{font-size:16px;font-weight:700;color:var(--charcoal);line-height:1.3}
.cvcard-text{font-size:13.5px;color:var(--charcoal);line-height:1.65;opacity:.85}
.cvcard-cta-row{display:flex;margin-top:4px}
.cvcard-cta{padding:7px 18px;border-radius:20px;font-size:13px;font-weight:600;background:var(--gm);color:#000;display:inline-block}

/* Campaign result (legacy) */
.builder-campaign-result{display:flex;flex-direction:column;gap:20px}
.bcr-title{font-size:17px;font-weight:700;color:var(--charcoal);margin-bottom:4px}
.bcr-message{font-size:14px;color:var(--charcoal);line-height:1.65;opacity:.85}
.bcr-body{font-size:13.5px;color:var(--charcoal);line-height:1.7;white-space:pre-wrap}

/* Loading — terminal code writer */
.code-loader{
  background:#0A0A0A;border:1px solid color-mix(in srgb, var(--green) 14%, transparent);
  border-radius:10px;overflow:hidden;
  font-family:'JetBrains Mono','Fira Code','Courier New',monospace;
  margin:12px 0;
}
.cl-header{
  display:flex;align-items:center;gap:7px;padding:10px 14px;
  background:#111;border-bottom:1px solid rgba(255,255,255,0.06);
}
.cl-dot{width:10px;height:10px;border-radius:50%}
.cl-red{background:#FF5F56}.cl-yellow{background:#FFBD2E}.cl-green{background:#27C93F}
.cl-title{
  font-size:11px;color:rgba(255,255,255,0.28);margin-left:6px;letter-spacing:0.3px;
  font-family:'Geist',system-ui,sans-serif;
}
.cl-body{padding:18px 20px;display:flex;flex-direction:column;gap:11px;min-height:160px}
/* Base line styles — items are injected by JS, start invisible */
.cl-line,.cl-micro{
  display:flex;align-items:flex-start;gap:10px;
  opacity:1;transition:opacity 0.22s ease;
}
.cl-line.cl-enter,.cl-micro.cl-enter{
  opacity:0;transform:translateX(-4px);
  transition:opacity 0.24s ease,transform 0.24s ease;
}
/* Active step (currently running) */
.cl-line-active .cl-prompt{color:var(--green)}
/* Completed step */
.cl-line-done{opacity:0.48!important}
.cl-line-done .cl-prompt{color:color-mix(in srgb, var(--green) 55%, transparent)!important;font-size:11px}
.cl-prompt{color:var(--green);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;user-select:none}
.cl-text{color:rgba(255,255,255,0.75);font-size:12.5px;line-height:1.5}
/* Animated dots on active step */
.cl-dots{color:color-mix(in srgb, var(--green) 70%, transparent);font-size:12px;letter-spacing:2px;margin-left:2px}
.cl-dots::after{
  content:'';animation:clDotsCycle 1.4s steps(4,end) infinite;
}
@keyframes clDotsCycle{
  0%  {content:''}
  25% {content:'.'}
  50% {content:'..'}
  75% {content:'...'}
  100%{content:''}
}
/* Micro-update lines */
.cl-micro{gap:8px}
.cl-micro-prompt{color:rgba(255,255,255,0.2);font-size:11px;flex-shrink:0;margin-top:1px;user-select:none}
.cl-micro-text{color:rgba(255,255,255,0.32);font-size:11.5px;font-style:italic}
/* Blinking cursor */
.cl-cursor{
  display:inline-block;width:7px;height:13px;background:var(--green);border-radius:1px;
  animation:clBlink 1.05s step-end infinite;vertical-align:middle;margin-left:2px;
}
@keyframes clBlink{0%,100%{opacity:1}50%{opacity:0}}

/* Error */
.builder-error{
  padding:20px;text-align:center;
  font-size:13.5px;color:var(--err-c,#DC2626);
  background:var(--err-bg,#FEF2F2);border-radius:calc(var(--rx) - 2px);
}

/* ═══ SETTINGS ══════════════════════════════════════════════════ */
#page-settings{display:none;padding:0}
#page-settings.active{display:block}
.se-outer{max-width:1040px;margin:0 auto;padding:44px 40px 80px}

/* Settings hero */
.se-hero{padding:44px 0 36px;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) both}
.se-hero-eyebrow{display:flex;align-items:center;gap:8px;margin-bottom:16px}
.se-hero-dot{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 0 3px color-mix(in srgb, var(--green) 18%, transparent);flex-shrink:0;animation:dashDotPulse 2.5s ease-in-out infinite}
.se-hero-eyebrow span{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.se-headline{font-family:'Instrument Serif',serif;font-size:clamp(30px,4vw,46px);font-weight:400;color:var(--charcoal);letter-spacing:-1.4px;line-height:1.05;margin-bottom:10px}
.se-hero-sub{font-size:14px;color:var(--muted);line-height:1.6;max-width:400px}

/* Layout */
.se-layout{display:grid;grid-template-columns:156px 1fr;gap:24px;align-items:start;animation:dashFadeUp .5s cubic-bezier(.22,1,.36,1) .06s both}
.se-content{min-width:0}

/* Nav */
.se-nav{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:12px;position:sticky;top:20px}
.se-nav-group{margin-bottom:0}
.se-nav-group+.se-nav-group{margin-top:6px;padding-top:10px;border-top:1px solid var(--border)}
.se-nav-label{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--charcoal);padding:4px 10px 7px;opacity:.6;cursor:default;pointer-events:none;user-select:none}
.snav-item{padding:9px 12px;border-radius:10px;font-size:13px;color:var(--muted);cursor:pointer;transition:background .15s,color .15s;margin-bottom:1px;line-height:1.3}
.snav-item:hover{background:var(--bg2);color:var(--charcoal)}
.snav-item.active{background:var(--gpale);color:var(--green);font-weight:600}

/* Panels */
.spanel{display:none}.spanel.active{display:block}
.se-panel-hd{padding-bottom:22px;border-bottom:1px solid var(--border);margin-bottom:28px}
.se-panel-eyebrow{font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);opacity:.5;margin-bottom:10px;display:none}
.se-panel-title{font-family:'Geist',system-ui,-apple-system,sans-serif;font-size:20px;font-weight:700;color:var(--charcoal);letter-spacing:-.03em;line-height:1.15;margin-bottom:7px}
.se-panel-sub{font-size:13px;color:var(--muted);line-height:1.65;max-width:460px}

/* Cards */
.se-card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:24px;margin-bottom:12px}
.se-card-title{font-size:13px;font-weight:700;color:var(--charcoal);letter-spacing:-.15px;margin-bottom:10px}
.se-card-help{font-size:12px;color:var(--muted);line-height:1.6;margin-top:-4px}
.se-input-row{display:flex;align-items:center;gap:10px;margin-top:12px}
.se-input-row .inp{max-width:280px}
.se-theme-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}

/* AI card */
.se-card-ai{background:linear-gradient(135deg,color-mix(in srgb, var(--green) 3%, transparent) 0%,color-mix(in srgb, var(--green) 1%, transparent) 100%);border-color:color-mix(in srgb, var(--green) 10%, transparent)}
.se-ai-insight{display:flex;align-items:flex-start;gap:10px;padding:12px;background:var(--bg);border:1px solid var(--border);border-radius:10px}
.se-ai-insight-dot{width:6px;height:6px;border-radius:50%;background:var(--green);flex-shrink:0;margin-top:4px}
.se-ai-insight-body{font-size:12px;color:var(--muted);line-height:1.6}

/* Danger zone */
.se-danger-zone{border:1px solid rgba(239,68,68,.2);background:rgba(254,242,242,.5);border-radius:16px;padding:24px}
.se-danger-title{font-size:13px;font-weight:700;color:#DC2626;margin-bottom:6px}
.se-danger-desc{font-size:12px;color:#7F1D1D;margin-bottom:16px;line-height:1.65}

/* ═══ CONFIGURATOR BAR (Image / Ads / Campaign / Video) ════════ */
.img-cfg{
  border-top:1px solid var(--border);
  padding:14px 20px 12px;
  background:var(--surface);
  display:flex;
  flex-direction:column;
  gap:10px;
}
.img-cfg-row{
  display:flex;
  align-items:center;
  gap:12px;
  flex-wrap:wrap;
}
.img-cfg-lbl{
  font-size:11px;
  font-weight:600;
  color:var(--muted);
  text-transform:uppercase;
  letter-spacing:.06em;
  min-width:44px;
  flex-shrink:0;
}
.img-type-pills,
.img-format-pills{
  display:flex;
  gap:6px;
  flex-wrap:wrap;
}
.img-pill{
  font-size:12px;
  font-weight:500;
  color:var(--muted);
  background:var(--bg2);
  border:1px solid var(--border);
  border-radius:20px;
  padding:4px 13px;
  cursor:pointer;
  transition:all .14s ease;
  line-height:1.5;
  white-space:nowrap;
}
.img-pill:hover{
  color:var(--charcoal);
  border-color:var(--b2);
  background:var(--bg3);
}
.img-pill.active{
  color:#fff;
  background:var(--green);
  border-color:var(--green);
}
.img-pill-hint{
  font-size:10px;
  opacity:.6;
  margin-left:2px;
}

/* ═══ YOUR PLAN SECTION ════════════════════════════════════════ */
.plan-status-bar{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r);padding:14px 16px;margin-bottom:20px;display:flex;flex-direction:column;gap:8px}
.plan-status-left{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.plan-status-badge{background:var(--green);color:#000;font-size:11px;font-weight:600;padding:3px 10px;border-radius:20px;letter-spacing:.2px}
.plan-status-renew{font-size:13px;color:var(--muted)}
.plan-status-pending{display:flex;align-items:center;gap:6px;font-size:12px;background:var(--warn-bg);color:var(--warn-c);border-radius:8px;padding:8px 12px;flex-wrap:wrap}
.plan-status-pending svg{flex-shrink:0}
.plan-cancel-btn{background:none;border:1px solid currentColor;border-radius:6px;color:inherit;font-size:11px;padding:2px 8px;cursor:pointer;margin-left:auto;line-height:1.4}
.plan-cancel-btn:hover{opacity:.7}
.plan-credits-block{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r);padding:16px 18px;margin-bottom:20px}
.plan-credits-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.plan-credits-label{font-size:13px;font-weight:600;color:var(--charcoal)}
.plan-credits-count{font-size:13px;font-weight:700;color:var(--gm);font-variant-numeric:tabular-nums}
.plan-credits-bar{height:6px;background:var(--bg3);border-radius:4px;overflow:hidden;margin-bottom:8px}
.plan-credits-fill{height:100%;border-radius:4px;transition:width .4s ease}
.plan-credits-sub{font-size:11px;color:var(--muted);line-height:1.4}

/* ── Plan Usage block ──────────────────────────────────────── */
.plan-usage-block{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r);padding:18px 20px;margin-bottom:20px}
.plan-usage-title{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:16px}
.plan-usage-row{display:flex;align-items:center;gap:10px;margin-bottom:12px}
.plan-usage-row:last-of-type{margin-bottom:0}
.plan-usage-row-lbl{font-size:12px;color:var(--c2);flex:0 0 120px;white-space:nowrap}
.plan-usage-row-right{flex:1;display:flex;align-items:center;gap:10px;min-width:0}
.plan-usage-bar{flex:1;height:5px;background:var(--bg3);border-radius:3px;overflow:hidden}
.plan-usage-fill{height:100%;border-radius:3px;transition:width .5s ease}
.plan-usage-count{font-size:12px;font-weight:600;color:var(--charcoal);font-variant-numeric:tabular-nums;white-space:nowrap;flex:0 0 44px;text-align:right}
.plan-usage-meta{margin-top:16px;padding-top:14px;border-top:1px solid var(--border);display:flex;flex-wrap:wrap;gap:10px}
.plan-usage-meta-item{display:flex;flex-direction:column;gap:2px;flex:1;min-width:80px}
.plan-usage-meta-lbl{font-size:10px;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}
.plan-usage-meta-val{font-size:13px;font-weight:600;color:var(--gm)}

.plan-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:4px}
.plan-card{background:var(--surface);border:1.5px solid var(--border);border-radius:var(--rl);padding:24px 20px 18px;display:flex;flex-direction:column;gap:14px;transition:border-color var(--t),box-shadow var(--t);position:relative}
.plan-card--current{border-color:var(--green);box-shadow:0 0 0 1px var(--green)}
.plan-card--pending{border-color:var(--gm);border-style:dashed}
.plan-card--popular{border-color:var(--green);box-shadow:0 0 0 1px var(--green)}
.plan-card--agency{border-style:dashed;opacity:.8}
.plan-price-cs{font-size:16px;font-weight:600;color:var(--muted);letter-spacing:-.2px}
.plan-popular-tag{position:absolute;top:-11px;left:50%;transform:translateX(-50%);background:var(--green);color:#000;font-size:10px;font-weight:700;padding:3px 12px;border-radius:20px;white-space:nowrap;letter-spacing:.3px}
.plan-card-head{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:24px}
.plan-card-name{font-size:15px;font-weight:600;color:var(--charcoal)}
.plan-badge{font-size:10px;font-weight:600;padding:3px 8px;border-radius:20px;white-space:nowrap}
.plan-badge--current{background:var(--glt);color:var(--green)}
.plan-badge--pending{background:var(--warn-bg);color:var(--warn-c)}
.plan-card-price{display:flex;align-items:baseline;gap:3px}
.plan-price-num{font-family:'Instrument Serif',serif;font-size:26px;color:var(--charcoal);letter-spacing:-.5px}
.plan-price-per{font-size:12px;color:var(--muted)}
.plan-features{list-style:none;display:flex;flex-direction:column;gap:7px;flex:1}
.plan-features li{display:flex;align-items:flex-start;gap:7px;font-size:12px;color:var(--c2);line-height:1.45}
.plan-features svg{flex-shrink:0;margin-top:1px;stroke:var(--gm)}
.plan-card-action{margin-top:auto}
.plan-card-action .btn{width:100%;justify-content:center}
.plan-free-row{background:var(--surface);border:1.5px solid var(--border);border-radius:var(--rl);padding:14px 20px;display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:12px;flex-wrap:wrap}
.plan-free-row--current{border-color:var(--green);box-shadow:0 0 0 1px var(--green)}
.plan-free-row--pending{border-color:var(--gm);border-style:dashed}
.plan-free-info{flex:1;min-width:0}
.plan-free-name{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:3px}
.plan-free-feats{font-size:11px;color:var(--muted);line-height:1.5}
.plan-free-right{display:flex;align-items:center;gap:12px;flex-shrink:0}
.plan-free-price{font-family:'Instrument Serif',serif;font-size:20px;color:var(--charcoal)}
@media(max-width:1040px){.plan-cards{grid-template-columns:1fr 1fr}}
@media(max-width:640px){.plan-cards{grid-template-columns:1fr}}

/* ── MOBILE HEADER BAR (desktop: hidden; mobile: fixed strip at top) ── */
#mobileBar{
  display:none;position:fixed;top:0;left:0;right:0;
  height:56px;z-index:1001;
  background:var(--surface);border-bottom:1px solid var(--border);
  align-items:center;padding:0 8px;
}
.mb-wordmark{
  flex:1;display:flex;align-items:center;justify-content:center;
  gap:8px;padding-right:44px;pointer-events:none;user-select:none;
}
.mb-wordmark img{width:20px;height:20px;object-fit:contain;display:block}
.mb-name{font-size:12px;font-weight:700;letter-spacing:.1em;color:var(--charcoal);text-transform:uppercase;line-height:1}

/* ── HAMBURGER BUTTON (lives inside #mobileBar on mobile) ──────── */
#sbToggle{
  display:none;
  width:44px;height:44px;border-radius:10px;
  background:none;border:none;
  align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;
}
#sbToggle svg{width:18px;height:18px;stroke:var(--charcoal);fill:none;stroke-width:1.8;stroke-linecap:round}

/* ── SIDEBAR OVERLAY ──────────────────────────────────────────── */
#sbOverlay{
  display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:998;
}
#sbOverlay.active{display:block}

/* ── TABLET / MOBILE BREAKPOINT ─────────────────────────────── */
@media(max-width:768px){
  /* ── 1. Show mobile bar + hamburger ── */
  #mobileBar{display:flex}
  #sbToggle{display:flex}

  /* ── 3. Sidebar off-canvas drawer — starts below the 56px mobile bar ── */
  .sb{
    position:fixed;left:-220px;top:56px;height:calc(100vh - 56px);z-index:999;
    width:200px;min-width:200px;
    transition:left .25s ease;
    box-shadow:var(--shl);
  }
  .sb.sb-open{left:0}

  /* ── 4. Logo area: clean padding, no hamburger clearance needed ── */
  .sb-logo{
    display:flex;
    align-items:center;
    padding:14px 16px;
  }
  .sb-logo .logo{gap:8px}

  /* ── 5. Remove the green identity card in drawer mode — the rounded
          dark-green box clips and splits against the drawer edge at mobile
          widths, making it look broken. Replace with flat unstyled text. ── */
  .sb-identity{
    background:none;
    border-radius:0;
    padding:6px 4px 2px;
    margin:0;
  }
  .sb-identity-name{color:var(--charcoal)}
  .sb-identity-sub{color:var(--muted)}
  .sb-signout{color:var(--muted)}

  /* Override any icon-only rules from the old 480px block */
  .sb .logo-name,.ni span{display:initial}
  .ni{padding:9px 10px;justify-content:flex-start}

  /* Main content fills full width */
  .mc{width:100%}
  .page{padding-top:0}

  /* Dashboard — page-level scroll, no nested overflow */
  #page-dashboard.active{height:auto;min-height:100%}
  #page-dashboard .dash-outer{padding:64px 20px 60px;height:auto}
  .dash-col-item{overflow:visible;height:auto}
  .dash-col-item>div:not(.dash-section-hd){overflow-y:visible;flex:none;height:auto}

  /* Create */
  .cr-outer{padding:0 20px 60px}
  .cr-hero{padding:64px 0 40px}
  #page-create-workspace{padding:64px 20px 40px}

  /* Studio */
  #page-studio .st-outer{padding-top:64px}
  /* BrandCore scroll container — clear mobile bar + 28px breathing room */
  .bcp-scroll{padding-top:calc(56px + env(safe-area-inset-top,0px) + 28px)}
  #page-inspiration .ph{padding-top:64px}

  /* Brand Assistant — just needs extra top space */
  .chat-shell{padding:0 12px}
  #page-aichat .chat-shell{padding-top:64px}

  /* Settings */
  #page-settings .se-outer{padding-top:64px}
  .se-layout{grid-template-columns:1fr}
  .se-nav{position:static;display:flex;flex-direction:row;flex-wrap:wrap;gap:4px;padding:10px;border-radius:12px}
  .se-nav-group{display:contents}
  .se-nav-label{display:none}
  .snav-item{padding:6px 11px;font-size:12px;border-radius:8px;margin-bottom:0}

  /* Plan cards — single column */
  .plan-cards{grid-template-columns:1fr}
  .plan-status-bar{flex-direction:column;align-items:flex-start;gap:8px}
  .plan-free-row{flex-direction:column;align-items:flex-start;gap:8px}
  .plan-free-right{width:100%;justify-content:space-between}

  /* Studio panel — slide in from right, clear hamburger */
  .sh-panel-view:not(.hidden){animation:spSlideIn 0.24s cubic-bezier(.22,.68,0,1.2) both}
  @keyframes spSlideIn{from{transform:translateX(22px);opacity:0}to{transform:translateX(0);opacity:1}}
  .sh-panel-header{padding-top:calc(56px + env(safe-area-inset-top,0px) + 18px);padding-bottom:18px} /* clear bar + safe area, balanced below */
  .sh-back-btn{min-height:44px;padding:10px 14px;font-size:14px}
  .sh-back-btn svg{width:16px;height:16px}
  .studio-panel.active{padding-bottom:env(safe-area-inset-bottom,24px)}

  /* Studio page tab bar */
  .studio-tabs,.tabs-row{overflow-x:auto;flex-wrap:nowrap;-webkit-overflow-scrolling:touch}

  /* Ideas page */
  #page-inspiration .id-cont{padding-top:64px}
  .id-concept-grid{grid-template-columns:1fr}
  .sh-cards{grid-template-columns:1fr}

  /* Team page */
  #page-team .tm-outer{padding-top:64px}
  .check-panel{grid-template-columns:1fr}
}

/* ── SMALL MOBILE ────────────────────────────────────────────── */
@media(max-width:480px){
  .sb{width:200px;min-width:200px}
  .sb .logo-name,.sb-identity,.ni span{display:initial}
  .ni{padding:9px 10px;justify-content:flex-start}
  .create-h1{font-size:24px}
  .snav-item{font-size:11px;padding:4px 8px}
  .plan-popular-tag{font-size:9px;padding:2px 7px}
}

/* ── THEME PICKER ─────────────────────────────────────────────── */
.theme-pick{
  border:2px solid var(--border);
  border-radius:var(--rl);
  padding:12px;
  cursor:pointer;
  transition:all var(--t);
}
.theme-pick:hover{border-color:var(--b2)}
.theme-pick.active{border-color:var(--green);background:var(--gpale)}
.theme-prev{
  display:flex;gap:6px;
  border-radius:8px;overflow:hidden;
  height:60px;margin-bottom:8px;
}
.theme-prev-light{background:#F6F3EE}
.theme-prev-dark{background:#0F0F10}
.tp-sidebar{width:30%;background:#FFF;border-right:1px solid #E0DAD1}
.tp-sidebar-dark{background:#18181A;border-right-color:#2C2C2E}
.tp-content{flex:1;padding:6px;display:flex;flex-direction:column;gap:4px}
.tp-card{height:16px;background:#FFF;border-radius:4px;border:1px solid #E0DAD1}
.tp-card-dark{background:#1A1A1C;border-color:#2C2C2E}
.theme-pick-label{font-size:12px;font-weight:600;color:var(--c2);text-align:center}

/* ── ACCENT COLOR PICKER ───────────────────────────────────── */
.accent-grid{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}
.accent-swatch{
  width:34px;height:34px;border-radius:50%;border:2.5px solid transparent;
  cursor:pointer;transition:transform .16s,box-shadow .16s,border-color .16s;
  outline:none;box-shadow:0 2px 6px rgba(0,0,0,.14);
  display:flex;align-items:center;justify-content:center;
}
.accent-swatch:hover{transform:scale(1.13)}
.accent-swatch.active{
  border-color:var(--charcoal);
  box-shadow:0 0 0 3px rgba(0,0,0,.1),0 2px 6px rgba(0,0,0,.14);
}
.accent-swatch.active::after{
  content:'';width:8px;height:8px;border-radius:50%;background:#fff;
  box-shadow:0 1px 2px rgba(0,0,0,.3);
}

.logo-mk img {
  width: 44px;
  height: 44px;
  object-fit: contain;
  display: block;
}
/* ── CANCEL PLAN SECTION ────────────────────────────────────── */
.plan-cancel-section{
  display:flex;align-items:center;justify-content:space-between;
  gap:16px;padding:16px 20px;margin-top:12px;
  border:1px solid var(--border);border-radius:10px;
  background:var(--surface);
}
.plan-cancel-section-title{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:2px}
.plan-cancel-section-sub{font-size:12px;color:var(--muted)}
/* Was a hardcoded light background (#fff9f9) with no dark-mode override --
   .btn-g's text (var(--c2)) and .plan-cancel-confirm-text (var(--charcoal))
   both flip to near-white in dark mode, so on the always-light card that
   rendered as white-on-white. Reuses the existing theme-aware danger
   tokens (--err-bg/--err-c, already defined for both themes in :root /
   body.dark-mode) instead of a bespoke color, so both themes stay legible. */
.plan-cancel-confirm{
  padding:16px 20px;margin-top:8px;
  border:1px solid color-mix(in srgb, var(--err-c) 30%, transparent);
  border-radius:10px;
  background:var(--err-bg);
}
.plan-cancel-confirm-title{font-size:14px;font-weight:700;color:var(--charcoal);margin-bottom:4px}
.plan-cancel-confirm-text{font-size:13px;color:var(--charcoal);margin-bottom:12px;line-height:1.5}
.plan-cancel-confirm-btns{display:flex;gap:8px}
.btn-danger{
  background:#e53935;color:#fff;border:none;
}
.btn-danger:hover{background:#c62828}

/* ── EMAIL VERIFICATION BANNER ──────────────────────────────── */
.verify-banner{
  position:fixed;bottom:0;left:0;right:0;z-index:7999;
  background:#78350f;color:#fef3c7;
  display:flex;align-items:center;gap:12px;
  padding:11px 20px;font-size:13px;line-height:1.4;
  border-top:1px solid rgba(0,0,0,.15);
}
.verify-banner-icon{flex-shrink:0;opacity:.85}
.verify-banner-text{flex:1}
.verify-banner-resend{
  flex-shrink:0;
  background:rgba(255,255,255,.15);
  color:#fef3c7;
  border:1px solid rgba(255,255,255,.3);
  border-radius:7px;
  font-size:12px;font-weight:600;
  cursor:pointer;
  padding:5px 13px;
  white-space:nowrap;
  transition:background .15s;
}
.verify-banner-resend:hover:not(:disabled){background:rgba(255,255,255,.25)}
.verify-banner-resend:disabled{opacity:.55;cursor:not-allowed}
.verify-banner-close{
  flex-shrink:0;background:none;border:none;
  color:rgba(254,243,199,.65);cursor:pointer;
  padding:4px;display:flex;align-items:center;
  border-radius:5px;transition:color .15s;
}
.verify-banner-close:hover{color:#fef3c7}
@media(max-width:600px){
  .verify-banner{flex-wrap:wrap;gap:8px;padding:12px 16px 14px}
  .verify-banner-text{font-size:12px;min-width:0}
}

/* ════════════════════════════════════════════════════════════
   AI CONVERSATION FLOW OVERLAY
   ════════════════════════════════════════════════════════════ */

/* ── Overlay backdrop ── */
.cf-overlay{
  position:fixed;inset:0;z-index:9800;
  display:flex;align-items:center;justify-content:center;
  background:rgba(10,12,10,.72);
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
  transition:opacity 0.28s ease;
  padding:16px;
}

/* ── Panel ── */
.cf-panel{
  width:100%;max-width:620px;
  background:var(--surface);
  border-radius:18px;
  border:1px solid var(--border);
  box-shadow:0 24px 72px rgba(0,0,0,.16),0 8px 24px rgba(0,0,0,.10);
  display:flex;flex-direction:column;
  max-height:calc(100vh - 48px);
  overflow:hidden;
}

/* ── Top bar ── */
.cf-topbar{
  display:flex;align-items:center;gap:10px;
  padding:18px 20px 14px;
  border-bottom:1px solid var(--border);
  flex-shrink:0;
}
.cf-close-btn{ margin-left:auto; }
.cf-type-pill{
  display:flex;align-items:center;gap:7px;
  background:var(--gpale);
  border:1px solid var(--glt);
  border-radius:20px;
  padding:5px 12px 5px 10px;
  color:var(--gm);
}
.cf-type-icon{ display:flex;align-items:center;flex-shrink:0; }
.cf-type-label{ font-size:12.5px;font-weight:600;letter-spacing:.02em; }
.cf-close-btn{
  display:flex;align-items:center;justify-content:center;
  width:30px;height:30px;border-radius:50%;
  background:none;border:none;cursor:pointer;
  color:var(--muted);transition:background .14s,color .14s;
}
.cf-close-btn:hover{ background:var(--bg2);color:var(--charcoal); }

/* ── Progress track ── */
.cf-progress-track{
  height:2px;background:var(--border);flex-shrink:0;
}
.cf-progress-fill{
  height:100%;background:var(--gm);
  transition:width 0.45s cubic-bezier(.4,0,.2,1);
  width:0%;
}

/* ── Brand Core bar ── */
.cf-brand-bar{
  display:flex;align-items:center;gap:7px;
  padding:8px 20px;
  background:color-mix(in srgb, var(--green) 3.5%, transparent);
  border-bottom:1px solid color-mix(in srgb, var(--green) 8%, transparent);
  flex-shrink:0;overflow:hidden;
}
.cf-brand-bar-dot{
  width:6px;height:6px;border-radius:50%;
  background:var(--green);box-shadow:0 0 0 2px color-mix(in srgb, var(--green) 18%, transparent);
  flex-shrink:0;animation:dashDotPulse 2.5s ease-in-out infinite;
}
.cf-brand-bar-label{
  font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  color:color-mix(in srgb, var(--green) 55%, transparent);flex-shrink:0;
}
.cf-brand-bar-name{
  font-size:11.5px;font-weight:700;color:rgba(255,255,255,.72);flex-shrink:0;
}
.cf-brand-bar-sep{color:rgba(255,255,255,.18);flex-shrink:0;}
.cf-brand-bar-detail{
  font-size:11px;color:rgba(255,255,255,.28);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}

/* ── History area ── */
.cf-history{
  flex-shrink:0;
  max-height:160px;overflow-y:auto;
  padding:0 28px;
  display:flex;flex-direction:column;gap:8px;
  scrollbar-width:none;
}
.cf-history:empty{ padding:0; }
.cf-history:not(:empty){ padding-top:20px; }
.cf-history::-webkit-scrollbar{ display:none; }

.cf-hist-item{
  display:flex;align-items:baseline;flex-wrap:wrap;gap:5px;
  padding:8px 12px;
  background:var(--sf2);
  border:1px solid var(--border);
  border-radius:9px;
  animation:cfHistIn .28s ease both;
}
@keyframes cfHistIn{
  from{opacity:0;transform:translateY(-5px)}
  to{opacity:1;transform:translateY(0)}
}
.cf-hist-q{
  font-size:11.5px;color:var(--muted);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  max-width:220px;
}
.cf-hist-sep{
  font-size:11px;color:var(--b2);flex-shrink:0;
}
.cf-hist-a{
  font-size:12px;font-weight:600;color:var(--gm);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  max-width:200px;
}

/* ── Stage ── */
.cf-stage{
  flex:1;display:flex;flex-direction:column;
  padding:28px 28px 24px;
  gap:24px;overflow:hidden;
  justify-content:center;
  min-height:260px;
}

/* ── Question block ── */
.cf-question-block{
  display:flex;align-items:flex-start;gap:14px;
  will-change:opacity,transform;
}
.cf-avatar{
  flex-shrink:0;
  width:38px;height:38px;
  border-radius:50%;
  background:var(--gpale);
  border:1px solid var(--glt);
  display:flex;align-items:center;justify-content:center;
  margin-top:2px;
}
.cf-avatar img{ border-radius:50%; }
.cf-question-content{ flex:1;min-width:0; }

.cf-question-text{
  font-size:22px;font-weight:700;line-height:1.3;
  color:var(--charcoal);
  letter-spacing:-.02em;
  min-height:1.3em;
}

/* Blinking cursor while AI types */
.cf-typing::after{
  content:"|";
  display:inline-block;
  margin-left:1px;
  color:var(--gm);
  animation:cfBlink .55s step-end infinite;
}
@keyframes cfBlink{
  0%,100%{opacity:1}
  50%{opacity:0}
}

.cf-question-desc{
  margin-top:7px;
  font-size:13.5px;color:var(--muted);
  line-height:1.5;
  opacity:0;
  transition:opacity 0.35s ease;
}

/* ── Options grid ── */
.cf-options{
  display:flex;flex-wrap:wrap;gap:9px;
  will-change:opacity,transform;
}

.cf-opt{
  padding:10px 18px;
  border:1.5px solid var(--border);
  border-radius:30px;
  background:var(--surface);
  color:var(--charcoal);
  font-size:13.5px;font-weight:500;
  cursor:pointer;
  transition:border-color .14s,background .14s,color .14s,transform .1s;
  animation:cfOptIn .3s ease both;
  white-space:nowrap;
}
@keyframes cfOptIn{
  from{opacity:0;transform:translateY(6px)}
  to{opacity:1;transform:translateY(0)}
}
.cf-opt:hover:not(:disabled){
  border-color:var(--gm);
  background:var(--gpale);
  color:var(--gm);
  transform:translateY(-1px);
}
.cf-opt-selected{
  border-color:var(--gm)!important;
  background:var(--gm)!important;
  color:#000!important;
}
.cf-opt:disabled:not(.cf-opt-selected){
  opacity:.35;cursor:not-allowed;transform:none;
}

/* ── Card-style options (website type selection) ── */
.cf-opts-cards{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:10px;
}
.cf-opt-card{
  background:rgba(255,255,255,0.03);
  border:1.5px solid var(--border);
  border-radius:12px;
  padding:16px 18px;
  text-align:left;cursor:pointer;
  display:flex;flex-direction:column;gap:6px;
  transition:border-color .2s,background .2s;
  font-family:'Geist',sans-serif;
}
.cf-opt-card:hover{
  border-color:color-mix(in srgb, var(--green) 30%, transparent);
  background:color-mix(in srgb, var(--green) 4%, transparent);
}
.cf-opt-card.cf-opt-selected{
  border-color:var(--green)!important;
  background:color-mix(in srgb, var(--green) 8%, transparent)!important;
}
.cf-opt-card:disabled:not(.cf-opt-selected){opacity:.35;cursor:not-allowed}
.cf-opt-card-label{
  font-size:13px;font-weight:600;color:var(--charcoal);letter-spacing:-.1px;
}
.cf-opt-card-desc{
  font-size:11.5px;color:var(--muted);line-height:1.45;
}

/* ── Avatar picker grid ─────────────────────────────────────── */
.cf-avatar-grid-wrap{
  width:100%;
  display:flex;
  flex-direction:column;
  align-items:stretch;
  gap:12px;
  min-height:100px;
}

/* ── Format bar (locked indicator) ── */
.cf-fmt-bar{
  display:flex;
  align-items:center;
  gap:10px;
  padding:8px 12px;
  border:1.5px solid var(--border);
  border-radius:10px;
  background:rgba(255,255,255,.02);
  flex-shrink:0;
}
.cf-fmt-bar-label{
  font-size:11px;
  color:var(--muted);
  font-weight:500;
  white-space:nowrap;
}
.cf-fmt-bar-active{
  display:flex;
  align-items:center;
  gap:6px;
  font-size:12.5px;
  font-weight:600;
  color:var(--charcoal);
}
.cf-fmt-bar-ratio{
  font-size:10px;
  font-weight:700;
  color:var(--green);
  letter-spacing:.05em;
  background:color-mix(in srgb, var(--green) 10%, transparent);
  padding:2px 5px;
  border-radius:4px;
}
.cf-fmt-bar-note{
  font-size:11px;
  color:var(--muted);
  margin-left:auto;
  white-space:nowrap;
}

/* ── Format tabs (reserved for future multi-format support) ── */
.cf-fmt-tabs{ display:flex; gap:6px; flex-shrink:0; }
.cf-fmt-tab{
  flex:1; display:flex; flex-direction:column; align-items:center;
  gap:3px; padding:9px 6px 8px; border:1.5px solid var(--border);
  border-radius:10px; background:rgba(255,255,255,.03); color:var(--muted);
  font-family:inherit; cursor:pointer;
  transition:border-color .14s, background .14s, color .14s;
}
.cf-fmt-tab:hover{ border-color:color-mix(in srgb, var(--green) 30%, transparent); background:color-mix(in srgb, var(--green) 4%, transparent); color:var(--charcoal); }
.cf-fmt-tab-active{ border-color:var(--green)!important; background:color-mix(in srgb, var(--green) 8%, transparent)!important; color:var(--charcoal)!important; }
.cf-fmt-ratio{ font-size:10px; font-weight:700; letter-spacing:.04em; color:inherit; opacity:.7; }
.cf-fmt-tab-active .cf-fmt-ratio{ color:var(--green); opacity:1; }
.cf-fmt-label{ font-size:12px; font-weight:600; color:inherit; letter-spacing:-.01em; }
.cf-avatar-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:10px;
  max-height:400px;
  overflow-y:auto;
  padding:2px 2px 6px;
  scrollbar-width:thin;
  width:100%;
}
.cf-avatar-grid::-webkit-scrollbar{ width:4px; }
.cf-avatar-grid::-webkit-scrollbar-track{ background:transparent; }
.cf-avatar-grid::-webkit-scrollbar-thumb{ background:var(--border); border-radius:2px; }

.cf-avatar-card{
  background:rgba(255,255,255,.03);
  border:1.5px solid var(--border,#2a2a2a);
  border-radius:12px;
  overflow:hidden;
  cursor:pointer;
  padding:0;
  display:flex;
  flex-direction:column;
  align-items:stretch;
  text-align:center;
  transition:border-color .15s, background .15s, box-shadow .15s, transform .12s;
  position:relative;
}
.cf-avatar-card:hover{
  border-color:color-mix(in srgb, var(--green) 40%, transparent);
  background:rgba(255,255,255,.06);
  transform:translateY(-2px);
  box-shadow:0 4px 16px rgba(0,0,0,.18);
}
.cf-avatar-card.cf-avatar-selected{
  border-color:var(--green)!important;
  background:color-mix(in srgb, var(--green) 8%, transparent)!important;
  box-shadow:0 0 0 3px color-mix(in srgb, var(--green) 15%, transparent)!important;
}
.cf-avatar-card:disabled:not(.cf-avatar-selected){opacity:.3;cursor:not-allowed;transform:none}

/* ── Thumbnail — shared by img, video, nothumb ── */
.cf-avatar-thumb{
  width:100%;
  aspect-ratio:3/4;
  object-fit:cover;
  object-position:top center;
  display:block;
  background:var(--bg2,#1a1a1a);
}
.cf-avatar-nothumb{
  width:100%;
  aspect-ratio:3/4;
  background:var(--bg2,#1a1a1a);
  display:flex;
  align-items:center;
  justify-content:center;
  color:var(--muted,#555);
}

/* Play-hint dot shown on cards that have a video preview */
.cf-avatar-play-hint{
  position:absolute;
  top:7px;right:7px;
  width:7px;height:7px;
  border-radius:50%;
  background:var(--green);
  opacity:.7;
  pointer-events:none;
}
.cf-avatar-card:hover .cf-avatar-play-hint{ opacity:0; }

.cf-avatar-name{
  font-size:11px;
  font-weight:500;
  color:var(--charcoal,#ccc);
  padding:7px 5px;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  display:block;
  line-height:1;
}

/* ── "Create Your Creator" card ── */
.cf-avatar-create{ border-style:dashed; }
.cf-avatar-create-thumb{
  width:100%;
  aspect-ratio:3/4;
  background:var(--bg2,#1a1a1a);
  display:flex;
  align-items:center;
  justify-content:center;
  color:var(--muted,#555);
  transition:color .15s;
}
.cf-avatar-create:hover .cf-avatar-create-thumb{ color:var(--gm); }

/* ── Loading / error states ── */
.cf-avatar-loading{
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  padding:36px 20px;
  color:var(--muted,#888);
  font-size:13px;
  gap:4px;
  width:100%;
}
.cf-avatar-err{
  color:#EF4444;
  font-size:12.5px;
  text-align:center;
  padding:20px 0;
  margin:0;
  width:100%;
}
@media(max-width:480px){
  .cf-avatar-grid{grid-template-columns:repeat(2,1fr);max-height:320px;}
}
@media(max-width:480px){
  .cf-opts-cards{grid-template-columns:1fr}
}

/* ── Voice picker ───────────────────────────────────────────── */
.cf-voice-picker-wrap{width:100%;display:flex;flex-direction:column;gap:10px;min-height:100px}
.cf-voice-tabs{display:flex;gap:6px;flex-shrink:0}
.cf-voice-tab{flex:1;padding:9px 10px;border:1.5px solid var(--border);border-radius:10px;background:rgba(255,255,255,.03);font-size:13px;font-weight:600;color:var(--muted);font-family:inherit;cursor:pointer;transition:border-color .14s,background .14s,color .14s;text-align:center}
.cf-voice-tab:hover{border-color:color-mix(in srgb, var(--green) 30%, transparent);background:color-mix(in srgb, var(--green) 4%, transparent);color:var(--charcoal)}
.cf-voice-tab-active{border-color:var(--green)!important;background:color-mix(in srgb, var(--green) 8%, transparent)!important;color:var(--charcoal)!important}
/* Grid — 2 columns so cards stay a manageable width */
.cf-voice-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;max-height:420px;overflow-y:auto;padding:2px 2px 6px;scrollbar-width:thin}
.cf-voice-grid::-webkit-scrollbar{width:4px}
.cf-voice-grid::-webkit-scrollbar-track{background:transparent}
.cf-voice-grid::-webkit-scrollbar-thumb{background:var(--border);border-radius:2px}
/* Card — vertical flex column, no overflow:hidden, no absolute children */
.cf-voice-card{display:flex;flex-direction:column;gap:10px;background:rgba(255,255,255,.03);border:1.5px solid var(--border,#2a2a2a);border-radius:12px;padding:14px;transition:border-color .14s,background .14s,box-shadow .14s;box-sizing:border-box}
.cf-voice-card:hover{border-color:color-mix(in srgb, var(--green) 25%, transparent);background:rgba(255,255,255,.05)}
.cf-voice-card.cf-voice-selected{border-color:var(--green)!important;background:color-mix(in srgb, var(--green) 6%, transparent)!important;box-shadow:0 0 0 2px color-mix(in srgb, var(--green) 10%, transparent)!important}
/* Top — name + meta */
.cf-voice-top{display:flex;flex-direction:column;gap:3px}
.cf-voice-name{font-size:13px;font-weight:700;color:var(--charcoal);letter-spacing:-.15px;line-height:1.35;word-break:break-word}
.cf-voice-meta{font-size:11px;color:var(--muted);line-height:1.4}
/* Preview button — full width, always contained */
.cf-voice-play-btn{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;box-sizing:border-box;padding:7px 10px;border-radius:8px;border:1px solid var(--border);background:rgba(255,255,255,.04);color:var(--muted);font-size:12px;font-weight:600;cursor:pointer;transition:border-color .14s,color .14s,background .14s;font-family:inherit;line-height:1;flex-shrink:0}
.cf-voice-play-btn:hover{border-color:color-mix(in srgb, var(--green) 40%, transparent);color:var(--charcoal);background:color-mix(in srgb, var(--green) 6%, transparent)}
.cf-voice-play-btn.cf-voice-play-active{border-color:var(--green);color:var(--green);background:color-mix(in srgb, var(--green) 8%, transparent)}
/* Select button — full width, always contained */
.cf-voice-select-btn{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;box-sizing:border-box;padding:8px 10px;border-radius:8px;border:1.5px solid var(--border);background:rgba(255,255,255,.04);color:var(--muted);font-size:12px;font-weight:600;cursor:pointer;transition:border-color .14s,color .14s,background .14s;font-family:inherit;line-height:1;flex-shrink:0;margin-top:auto}
.cf-voice-select-btn:hover{border-color:color-mix(in srgb, var(--green) 40%, transparent);color:var(--charcoal);background:color-mix(in srgb, var(--green) 6%, transparent)}
.cf-voice-selected .cf-voice-select-btn{border-color:var(--green);background:color-mix(in srgb, var(--green) 12%, transparent);color:var(--green)}
.cf-voice-empty{grid-column:1/-1;text-align:center;padding:28px;font-size:13px;color:var(--muted)}
@media(max-width:480px){.cf-voice-grid{grid-template-columns:1fr}}

/* ── Free-text input ── */
.cf-free-input{
  display:flex;flex-direction:column;gap:12px;
  will-change:opacity,transform;
}
.cf-textarea{
  width:100%;padding:12px 14px;
  border:1.5px solid var(--border);
  border-radius:12px;
  background:var(--sf2);
  color:var(--charcoal);
  font-size:14px;line-height:1.55;
  resize:none;
  transition:border-color .15s;
  min-height:86px;
}
.cf-textarea:focus{
  outline:none;border-color:var(--gm);
  background:var(--surface);
}
.cf-input-row{
  display:flex;align-items:center;justify-content:flex-end;gap:10px;
}
.cf-skip-btn{
  background:none;border:none;cursor:pointer;
  font-size:13px;color:var(--muted);
  padding:8px 4px;
  transition:color .14s;
}
.cf-skip-btn:hover{ color:var(--charcoal); }
.cf-continue-btn{
  display:flex;align-items:center;gap:7px;
  padding:10px 20px;
  background:var(--gm);border:none;
  border-radius:24px;color:#000;
  font-size:13.5px;font-weight:600;
  cursor:pointer;
  transition:background .14s,transform .1s;
}
.cf-continue-btn:hover{ background:var(--green);transform:translateY(-1px); }
.cf-continue-btn:active{ transform:translateY(0); }

/* ── Prompt Preview step ─────────────────────────────────────── */
.cf-preview-panel{
  display:flex;flex-direction:column;gap:12px;width:100%;
}

/* Brand Core Applied panel */
.cf-pv-bc-panel{
  border-radius:10px;padding:11px 14px;
  border:1px solid transparent;
}
.cf-pv-bc-ok{
  background:rgba(159,232,31,.06);
  border-color:rgba(159,232,31,.18);
}
.cf-pv-bc-partial{
  background:rgba(251,146,60,.05);
  border-color:rgba(251,146,60,.18);
}
.cf-pv-bc-none{
  background:rgba(255,255,255,.03);
  border-color:var(--border);
}
.cf-pv-bc-hdr{
  display:flex;align-items:center;gap:6px;
  font-size:12px;font-weight:700;letter-spacing:.03em;
  margin-bottom:8px;
}
.cf-pv-bc-ok    .cf-pv-bc-hdr{ color:var(--gm); }
.cf-pv-bc-partial .cf-pv-bc-hdr{ color:rgba(251,146,60,.9); }
.cf-pv-bc-none  .cf-pv-bc-hdr{ color:var(--muted); }
.cf-pv-bc-sub{
  font-size:11.5px;color:var(--muted);margin:0;
}
.cf-pv-bc-checks{
  display:flex;flex-wrap:wrap;gap:6px 10px;
}
.cf-pv-bc-ck{
  display:inline-flex;align-items:center;gap:4px;
  font-size:11px;font-weight:500;
}
.cf-pv-bc-ck-ok   { color:var(--gm); }
.cf-pv-bc-ck-miss { color:rgba(251,146,60,.8); }

/* Logo Source (motion graphics) */
.cf-pv-logo-section{
  display:flex;flex-direction:column;gap:7px;
}
.cf-pv-logo-label{
  font-size:11px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;
  color:var(--muted);
}
.cf-pv-logo-opts{
  display:flex;flex-direction:column;gap:6px;
}
.cf-pv-logo-opt{
  display:flex;align-items:center;gap:9px;
  cursor:pointer;padding:8px 11px;
  border-radius:8px;border:1px solid var(--border);
  background:transparent;
  font-size:13px;color:var(--charcoal);
  transition:border-color .15s,background .15s;
  user-select:none;
}
.cf-pv-logo-opt:has(input:checked){
  border-color:var(--gm);
  background:rgba(159,232,31,.05);
}
.cf-pv-logo-opt-dis{
  opacity:.45;cursor:default;
}
.cf-pv-logo-opt input[type="radio"]{
  display:none;
}
.cf-pv-logo-dot{
  width:14px;height:14px;border-radius:50%;
  border:2px solid var(--border);flex-shrink:0;
  position:relative;transition:border-color .14s;
}
.cf-pv-logo-opt:has(input:checked) .cf-pv-logo-dot{
  border-color:var(--gm);
}
.cf-pv-logo-opt:has(input:checked) .cf-pv-logo-dot::after{
  content:'';position:absolute;
  top:50%;left:50%;transform:translate(-50%,-50%);
  width:6px;height:6px;border-radius:50%;
  background:var(--gm);
}
.cf-pv-logo-thumb{
  width:22px;height:22px;object-fit:contain;border-radius:4px;flex-shrink:0;
}
.cf-pv-logo-hint{
  color:var(--muted);font-size:11px;
}

/* Editable prompt textarea */
.cf-pv-prompt-wrap{
  display:flex;flex-direction:column;gap:6px;
}
.cf-pv-prompt-lbl{
  font-size:11px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;
  color:var(--muted);
  display:flex;align-items:center;gap:8px;
}
.cf-pv-prompt-hint{
  font-size:10.5px;font-weight:400;letter-spacing:0;text-transform:none;
  color:var(--m2);
}
.cf-pv-ta{
  width:100%;padding:11px 13px;
  border:1.5px solid var(--border);
  border-radius:10px;
  background:var(--sf2);
  color:var(--charcoal);
  font-size:12.5px;line-height:1.6;
  resize:vertical;
  transition:border-color .15s,background .15s;
  min-height:120px;
  font-family:inherit;
}
.cf-pv-ta:focus{
  outline:none;border-color:var(--gm);
  background:var(--surface);
}

/* Generate button */
.cf-pv-gen-btn{
  display:inline-flex;align-items:center;justify-content:center;gap:8px;
  padding:12px 26px;
  background:var(--gm);border:none;
  border-radius:26px;color:#000;
  font-size:14px;font-weight:700;
  cursor:pointer;
  transition:background .14s,transform .1s,box-shadow .14s;
  align-self:flex-start;
  box-shadow:0 0 0 0 rgba(159,232,31,0);
}
.cf-pv-gen-btn:hover{
  background:var(--green);
  transform:translateY(-1px);
  box-shadow:0 4px 18px rgba(159,232,31,.22);
}
.cf-pv-gen-btn:active{ transform:translateY(0);box-shadow:none; }

/* Dark mode overrides for preview */
body.dark-mode .cf-pv-ta{
  background:var(--sf2);border-color:var(--border);color:var(--charcoal);
}
body.dark-mode .cf-pv-ta:focus{ background:var(--surface); }
body.dark-mode .cf-pv-logo-opt{ background:transparent;border-color:var(--border);color:var(--charcoal); }

/* ── Dark mode overrides ── */
body.dark-mode .cf-panel{ background:var(--surface);border-color:var(--border); }
body.dark-mode .cf-topbar{ border-color:var(--border); }
body.dark-mode .cf-type-pill{ background:var(--gpale);border-color:var(--glt); }
body.dark-mode .cf-close-btn:hover{ background:var(--bg2); }
body.dark-mode .cf-hist-item{ background:var(--sf2);border-color:var(--border); }
body.dark-mode .cf-opt{ background:var(--surface);border-color:var(--border);color:var(--charcoal); }
body.dark-mode .cf-opt:hover:not(:disabled){ background:var(--gpale);border-color:var(--gm); }
body.dark-mode .cf-textarea{ background:var(--sf2);border-color:var(--border);color:var(--charcoal); }
body.dark-mode .cf-textarea:focus{ background:var(--surface); }

/* ── Mobile ── */
@media(max-width:600px){
  .cf-panel{ border-radius:14px;max-height:calc(100vh - 24px); }
  .cf-topbar{ padding:16px 18px 12px; }
  .cf-stage{ padding:20px 18px 20px; }
  .cf-history{ padding-left:18px;padding-right:18px; }
  .cf-question-text{ font-size:19px; }
  .cf-hist-q{ max-width:140px; }
  .cf-hist-a{ max-width:130px; }
}

/* ════════════════════════════════════════════════════════════
   MOBILE UX — iOS SAFE AREA + INPUT ZOOM + SCROLL FIXES
   ════════════════════════════════════════════════════════════ */

/* Fill iOS status bar with app background color */
html{ background:#0B0B0B; }

/* ── Mobile bar: grow to fill notch / Dynamic Island ── */
@supports(padding-top:env(safe-area-inset-top)){
  @media(max-width:768px){
    #mobileBar{
      height:calc(56px + env(safe-area-inset-top));
      padding-top:env(safe-area-inset-top);
    }
    .sb{
      top:calc(56px + env(safe-area-inset-top));
      height:calc(100vh - 56px - env(safe-area-inset-top));
    }
  }
}

/* ── Sidebar bottom: lift above home indicator bar ── */
@supports(padding-bottom:env(safe-area-inset-bottom)){
  .sb-bottom{
    padding-bottom:calc(20px + env(safe-area-inset-bottom));
  }
}

/* ── Auth overlay: push content below the status bar ── */
@supports(padding-top:env(safe-area-inset-top)){
  #authOverlay{
    padding-top:calc(24px + env(safe-area-inset-top)) !important;
  }
}

/* ── iOS input zoom fix — font-size must be ≥ 16px on mobile ── */
@media(max-width:768px){
  .inp,
  input[type="text"],
  input[type="email"],
  input[type="password"],
  input[type="search"],
  input[type="tel"],
  input[type="url"],
  select,
  textarea{
    font-size:16px !important;
  }
  /* Keep cf-textarea readable but still above 16px threshold */
  .cf-textarea{ font-size:16px !important; }
}


/* ── Inspiration page: make scrollable on mobile ── */
@media(max-width:768px){
  #page-inspiration.active{
    overflow-y:auto !important;
    -webkit-overflow-scrolling:touch;
  }
  .id-outer{
    height:auto;
    min-height:100%;
    justify-content:flex-start;
    padding-top:80px;
    padding-bottom:40px;
  }
}

/* ── Create page: add safe-area top spacing ── */
@media(max-width:768px){
  @supports(padding-top:env(safe-area-inset-top)){
    #page-create.active,
    #page-create-workspace.active{
      padding-top:calc(64px + env(safe-area-inset-top));
    }
  }
}

