.gcm-type-chip svg{ margin-top:2px;flex-shrink:0; }
.gcm-type-chip:hover{
  border-color:color-mix(in srgb, var(--green) 35%, transparent);
  color:rgba(240,237,230,0.85);
}
.gcm-type-chip-on{
  background:color-mix(in srgb, var(--green) 12%, transparent);
  border-color:color-mix(in srgb, var(--green) 45%, transparent);
  color:var(--green);
}
.gcm-chip-label{
  display:flex;flex-direction:column;gap:2px;
  font-size:13px;font-weight:600;line-height:1.2;
}
.gcm-chip-desc{
  font-size:11px;font-weight:400;
  color:rgba(240,237,230,0.38);line-height:1.3;
}
.gcm-type-chip-on .gcm-chip-desc{ color:color-mix(in srgb, var(--green) 65%, transparent); }

/* Campaign ad-count selector */
.gcm-count-row{
  display:flex;align-items:center;gap:12px;
  padding:10px 14px;margin-bottom:14px;
  background:color-mix(in srgb, var(--green) 6%, transparent);
  border:1px solid color-mix(in srgb, var(--green) 18%, transparent);
  border-radius:10px;
}
.gcm-count-label{
  font-size:12.5px;font-weight:600;
  color:rgba(240,237,230,0.65);flex:1;
}
.gcm-count-opts{ display:flex;gap:6px; }
.gcm-count-btn{
  width:36px;height:30px;border-radius:7px;
  border:1px solid rgba(255,255,255,0.12);
  background:rgba(255,255,255,0.05);
  color:rgba(240,237,230,0.55);
  font-size:13px;font-weight:600;font-family:inherit;
  cursor:pointer;transition:background .12s,border-color .12s,color .12s;
}
.gcm-count-btn:hover{ border-color:color-mix(in srgb, var(--green) 40%, transparent);color:var(--green); }
.gcm-count-btn-on{
  background:color-mix(in srgb, var(--green) 18%, transparent);
  border-color:color-mix(in srgb, var(--green) 55%, transparent);
  color:var(--green);
}

.gcm-input{
  width:100%;background:rgba(255,255,255,0.06);
  border:1px solid rgba(255,255,255,0.10);
  border-radius:10px;padding:13px 16px;
  font-size:15px;color:#F0EDE6;outline:none;
  font-family:inherit;box-sizing:border-box;
  transition:border-color 0.2s,background 0.2s;
  margin-bottom:12px;display:block;
}
.gcm-input::placeholder{ color:rgba(240,237,230,0.3); }
.gcm-input:focus{
  border-color:color-mix(in srgb, var(--green) 45%, transparent);
  background:rgba(255,255,255,0.08);
}

.gcm-gen-btn{
  display:flex;align-items:center;justify-content:center;gap:8px;
  width:100%;padding:14px;border-radius:10px;
  background:var(--gm,var(--gm));color:#0B0B0B;
  font-size:14px;font-weight:700;border:none;cursor:pointer;
  font-family:inherit;transition:opacity 0.15s;margin-bottom:16px;
}
.gcm-gen-btn:hover{ opacity:0.88; }
.gcm-gen-btn:disabled{ opacity:0.5;cursor:not-allowed; }

.gcm-result-img{
  width:100%;border-radius:12px;overflow:hidden;
  background:rgba(255,255,255,0.04);
  border:1px solid rgba(255,255,255,0.07);
  min-height:80px;display:flex;align-items:center;justify-content:center;
  margin-bottom:16px;
}
.gcm-result-img img{ width:100%;display:block;border-radius:12px; }

/* Guest campaign variation cards */
.gcm-camp-list{display:flex;flex-direction:column;gap:12px;}
.gcm-camp-card{border-radius:12px;overflow:hidden;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.08);}
.gcm-camp-img{width:100%;display:block;}
.gcm-camp-body{padding:14px 16px;display:flex;flex-direction:column;gap:6px;}
.gcm-camp-num{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--gm,var(--gm));}
.gcm-camp-headline{font-size:15px;font-weight:700;color:#f0ede6;line-height:1.3;}
.gcm-camp-text{font-size:13px;color:rgba(240,237,230,0.72);line-height:1.6;}
.gcm-camp-cta-row{margin-top:4px;}
.gcm-camp-cta{display:inline-block;padding:6px 16px;border-radius:20px;font-size:12px;font-weight:600;background:var(--gm,var(--gm));color:#0B0B0B;}

.gcm-footer{
  text-align:center;font-size:11.5px;color:rgba(240,237,230,0.22);
}

/* In-modal soft gate — appears over result bottom after generation */
.gcm-gate{
  position:relative;z-index:5;
  margin-top:-110px;padding:110px 0 0;
  background:linear-gradient(to bottom,transparent 0%,#141414 38%);
  animation:gcGateFadeIn 0.5s ease both;
}
@keyframes gcGateFadeIn{
  from{opacity:0;transform:translateY(6px)}
  to{opacity:1;transform:translateY(0)}
}
.gcm-gate-card{
  background:#141414;padding:20px 4px 4px;text-align:center;
}
.gcm-gate-title{
  font-size:17px;font-weight:600;color:#f0ede6;margin:0 0 8px;
}
.gcm-gate-sub{
  font-size:13px;color:rgba(240,237,230,0.52);margin:0 0 20px;line-height:1.5;
}
.gcm-gate-actions{display:flex;flex-direction:column;gap:10px;}
.gcm-gate-primary{
  width:100%;padding:13px 20px;border-radius:10px;
  background:var(--gm,var(--gm));color:#0B0B0B;
  font-size:14px;font-weight:700;border:none;cursor:pointer;
  font-family:inherit;transition:opacity 0.15s;
}
.gcm-gate-primary:hover{opacity:0.88;}
.gcm-gate-ghost{
  background:transparent;border:none;
  color:rgba(240,237,230,0.4);font-size:13px;
  cursor:pointer;padding:6px;font-family:inherit;
  transition:color 0.15s;
}
.gcm-gate-ghost:hover{color:rgba(240,237,230,0.72);}

/* Shared loading animation */
.gl-generating{
  display:flex;flex-direction:column;align-items:center;gap:14px;
  padding:40px 24px;color:rgba(240,237,230,0.45);font-size:13px;
}
.gl-gen-dots{ display:flex;gap:7px; }
.gl-gen-dots span{
  width:8px;height:8px;border-radius:50%;
  background:color-mix(in srgb, var(--green) 60%, transparent);
  animation:glDotBounce 1.1s infinite ease-in-out;
}
.gl-gen-dots span:nth-child(2){ animation-delay:0.18s; }
.gl-gen-dots span:nth-child(3){ animation-delay:0.36s; }
@keyframes glDotBounce{
  0%,80%,100%{ transform:translateY(0);opacity:0.4; }
  40%{ transform:translateY(-8px);opacity:1; }
}

