  font-family:inherit;transition:opacity 0.15s;
}
.gg-signup-btn:hover{ opacity:0.88; }
.gg-login-link{
  width:100%;padding:12px;border-radius:10px;
  background:rgba(255,255,255,0.05);color:rgba(240,237,230,0.65);
  font-size:13px;font-weight:500;border:1px solid rgba(255,255,255,0.08);
  cursor:pointer;font-family:inherit;transition:background 0.15s,color 0.15s;
}
