#ggSignup,#ggLogin{ padding:28px 28px 30px; }
.gg-back-btn{
  display:flex;align-items:center;gap:6px;
  font-size:12px;color:rgba(240,237,230,0.4);
  background:none;border:none;cursor:pointer;
