  flex-shrink:0;margin-top:1px;
}
.ob-feat-name{
  font-size:14px;font-weight:600;color:#F0EDE6;margin-bottom:3px;
}
.ob-feat-desc{
  font-size:12.5px;color:rgba(240,237,230,0.42);line-height:1.5;
}

/* ════════════════════════════════════════════════════════════
   GUEST CREATE SECONDARY RESULT
   ════════════════════════════════════════════════════════════ */
.gcm-secondary{
  margin-top:14px;
  padding:14px 16px;
