}

/* ════════════════════════════════════════════════════════════
   GUEST GATE — no #ggMain, forms only
   ════════════════════════════════════════════════════════════ */
#guestGate{
  position:fixed;inset:0;z-index:9600;
  display:none;align-items:center;justify-content:center;
  background:rgba(8,8,8,0.88);backdrop-filter:blur(16px);
  padding:20px;
}
.gg-panel{
  background:#141414;border:1px solid rgba(255,255,255,0.09);
  border-radius:18px;width:100%;max-width:420px;
