  box-shadow:0 24px 80px rgba(0,0,0,0.7);
  padding:28px 28px 32px;
}

/* ════════════════════════════════════════════════════════════
   GUIDE TOUR — corner orb, spotlight, tooltips
   ════════════════════════════════════════════════════════════ */

#obCornerOrb {
  position: fixed; bottom: 32px; right: 32px;
  width: 50px; height: 50px; border-radius: 50%;
  background: radial-gradient(circle at 38% 36%, #2D6A4F, #0E2B1D);
  display: flex; align-items: center; justify-content: center;
  z-index: 9100; opacity: 0;
  transform: scale(0.5) translateY(20px);
  transition: opacity 0.45s ease, transform 0.45s cubic-bezier(.22,.68,0,1.4);
  cursor: default;
  box-shadow: 0 0 30px rgba(82,183,136,0.22), 0 4px 20px rgba(0,0,0,0.5);
  animation: obCornerPulse 3.5s ease-in-out infinite;
  pointer-events: none;
}
#obCornerOrb.ob-orb-visible { opacity: 1; transform: scale(1) translateY(0); }
@keyframes obCornerPulse {
  0%,100% { box-shadow: 0 0 30px rgba(82,183,136,0.22), 0 4px 20px rgba(0,0,0,0.5); }
  55% { box-shadow: 0 0 50px rgba(82,183,136,0.38), 0 0 0 10px rgba(82,183,136,0), 0 4px 20px rgba(0,0,0,0.5); }
}

#gtSpot {
  position: fixed;
  z-index: 9200;
  pointer-events: none;
  border-radius: 12px;
  box-shadow: 0 0 0 9999px rgba(12,15,13,0.72);
  border: 1.5px solid rgba(82,183,136,0.5);
  display: none;
  opacity: 0;
  transition: opacity 0.38s ease,
              top    0.4s cubic-bezier(.22,.68,0,1.2),
              left   0.4s cubic-bezier(.22,.68,0,1.2),
              width  0.4s cubic-bezier(.22,.68,0,1.2),
              height 0.4s cubic-bezier(.22,.68,0,1.2);
}
#gtSpot.gt-on { opacity: 1; }

#gtTip {
  position: fixed;
  z-index: 9201;
  width: 290px;
  background: #ffffff;
  border: 1px solid rgba(0,0,0,0.07);
  border-radius: 18px;
  padding: 18px 20px 20px;
  box-shadow: 0 4px 32px rgba(0,0,0,0.13), 0 1px 4px rgba(0,0,0,0.05);
  display: none;
  opacity: 0;
  transform: translateY(10px) scale(0.97);
  transition: opacity 0.35s ease, transform 0.35s cubic-bezier(.22,.68,0,1.2);
  font-family: 'Geist', -apple-system, sans-serif;
}
#gtTip.gt-on {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.gt-tip-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}
.gt-tip-icon {
  width: 26px; height: 26px;
  background: #fff;
  border: 1px solid rgba(0,0,0,.1);
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
  padding: 4px;
  box-shadow: 0 1px 3px rgba(0,0,0,.08);
}
.gt-tip-step {
  font-size: 11px;
  font-weight: 600;
  color: #52B788;
  letter-spacing: 0.06em;
  flex: 1;
}
.gt-tip-close {
  width: 22px; height: 22px;
  border-radius: 50%;
  background: rgba(0,0,0,0.05);
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #999;
  flex-shrink: 0;
  transition: background 0.2s, color 0.2s;
}
.gt-tip-close:hover { background: rgba(0,0,0,0.1); color: #333; }
.gt-tip-title {
  font-size: 15px;
  font-weight: 700;
  color: #18181A;
  margin: 0 0 7px;
  line-height: 1.35;
}
.gt-tip-body {
  font-size: 13px;
  color: #666;
  line-height: 1.6;
  margin: 0 0 16px;
}
.gt-tip-btn {
  width: 100%;
  padding: 11px 16px;
  background: linear-gradient(135deg, #1A4229, #2D6A4F);
  color: #fff;
  font-size: 13.5px;
  font-weight: 600;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-family: 'Geist', sans-serif;
  transition: transform 0.18s, box-shadow 0.18s;
  box-shadow: 0 3px 14px rgba(26,66,41,0.4);
}
.gt-tip-btn:hover { transform: translateY(-1px); box-shadow: 0 6px 20px rgba(26,66,41,0.52); }
.gt-tip-btn:active { transform: translateY(0); }

#gtOrbMsg {
  position: fixed;
  bottom: 94px;
  right: 24px;
  z-index: 9203;
  display: none;
  align-items: center;
  gap: 8px;
  background: #0C0F0D;
  color: rgba(240,237,230,0.9);
  font-size: 13px;
  font-family: 'Geist', -apple-system, sans-serif;
  padding: 9px 14px;
  border-radius: 12px 12px 4px 12px;
  max-width: 230px;
  line-height: 1.45;
  pointer-events: none;
  opacity: 0;
  transform: translateY(6px) scale(0.97);
  transition: opacity 0.35s ease, transform 0.35s cubic-bezier(.22,.68,0,1.2);
  box-shadow: 0 4px 20px rgba(0,0,0,0.3);
}
#gtOrbMsg.gt-on {
  opacity: 1;
  transform: translateY(0) scale(1);
}
#gtOrbMsg::after {
  content: '';
  position: absolute;
  bottom: -6px;
  right: 16px;
  border: 6px solid transparent;
  border-top-color: #0C0F0D;
  border-bottom: none;
}
.gt-orb-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #52B788;
  flex-shrink: 0;
  animation: obMsgDot 1.5s ease-in-out infinite;
}
@keyframes obMsgDot {
  0%,100% { opacity: 0.4; transform: scale(0.85); }
  50%      { opacity: 1;   transform: scale(1.15); }
}

#gtBd {
  position: fixed;
  inset: 0;
  background: rgba(12,15,13,0.78);
  z-index: 9199;
  display: none;
  opacity: 0;
  transition: opacity 0.35s ease;
}
#gtBd.gt-on { opacity: 1; }

#gtTip.gt-centered { width: 340px; }
#gtTip.gt-centered:not(.gt-on) {
  transform: translate(-50%, -50%) scale(0.97) !important;
  opacity: 0;
}
#gtTip.gt-centered.gt-on {
  transform: translate(-50%, -50%) scale(1) !important;
  opacity: 1;
}

.gt-tip-bullets {
  list-style: none;
  margin: -4px 0 16px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.gt-tip-bullets li {
  font-size: 12px;
  color: #555;
  line-height: 1.4;
  padding: 5px 9px;
  background: rgba(82,183,136,0.07);
  border-radius: 7px;
  border-left: 2px solid rgba(82,183,136,0.4);
}
.gt-tip-bullets li strong { color: #1A4229; font-weight: 600; }
.gt-tip-bullets li span   { color: #888; }

.gt-progress-dots {
  display: flex;
  justify-content: center;
  gap: 5px;
  margin-top: 14px;
}
.gt-pdot {
  width: 5px; height: 5px;
  border-radius: 50%;
  background: rgba(0,0,0,0.12);
  transition: background 0.3s ease, transform 0.3s ease;
}
.gt-pdot.gt-pdot-on     { background: rgba(82,183,136,0.45); }
.gt-pdot.gt-pdot-active { background: #52B788; transform: scale(1.35); }

#gtSkipBtn {
  display: block;
  width: 100%;
  margin-top: 8px;
  padding: 6px;
  background: none;
  border: none;
  color: #bbb;
  font-size: 12px;
  font-family: 'Geist', sans-serif;
  cursor: pointer;
  text-align: center;
  transition: color 0.2s;
}
#gtSkipBtn:hover { color: #777; }

/* ── Paywall modal plan cards ───────────────────────────────── */
.pw-feat{
  display:flex;align-items:flex-start;gap:8px;
  font-size:12px;color:var(--charcoal,#18181A);line-height:1.6;
  padding:2px 0;
}
.pw-feat::before{
  content:"";display:block;flex-shrink:0;
  width:6px;height:6px;border-radius:50%;
  background:var(--gm,var(--gm));margin-top:5px;
}
.pw-plan-btn{
  width:100%;justify-content:center;font-size:13px;
}
.pw-plan-btn:disabled{
  opacity:0.55;cursor:default;
  background:var(--bg2,#EEE9E1) !important;
  color:var(--muted,#888) !important;
  border-color:var(--border,rgba(0,0,0,.1)) !important;
  box-shadow:none !important;
}

/* ── UGC Video Test ─────────────────────────────────────────── */
.ugc-wrap{ padding:0 32px 48px; }
.ugc-card{ background:var(--bg2,#F4EFE7);border-radius:16px;padding:24px;max-width:640px;display:flex;flex-direction:column;gap:16px; }
.ugc-label{ font-size:11px;font-weight:700;letter-spacing:.06em;color:var(--muted,#888);text-transform:uppercase;display:block;margin-bottom:6px; }
.ugc-textarea{ width:100%;box-sizing:border-box;min-height:120px;resize:vertical;font-size:14px;line-height:1.65;padding:12px 14px;border:1.5px solid var(--border,rgba(0,0,0,.1));border-radius:10px;background:var(--bg,#FAF6F0);font-family:inherit;color:var(--charcoal,#18181A);outline:none;transition:border-color .15s; }
.ugc-textarea:focus{ border-color:var(--gm,var(--gm)); }
.ugc-selects{ display:grid;grid-template-columns:1fr 1fr;gap:12px; }
.ugc-field{ display:flex;flex-direction:column; }
.ugc-sel{ width:100%; }
.ugc-result{ max-width:640px;margin-top:4px; }
.ugc-status-row{ display:flex;align-items:center;gap:10px;font-size:13px;color:var(--muted,#888);padding:14px 0; }
.ugc-spinner{ width:16px!important;height:16px!important;border-width:2.5px!important;flex-shrink:0; }
.ugc-status-ok{ font-size:13px;color:#22c55e;font-weight:600;padding:14px 0; }
.ugc-status-err{ font-size:13px;color:#EF4444;padding:14px 0;line-height:1.5; }
@media(max-width:600px){ .ugc-wrap{ padding:0 16px 48px; } .ugc-selects{ grid-template-columns:1fr; } }

/* ── UGC Creator Overlay ─────────────────────────────────────── */
.uc-panel{ max-width:680px; }
.uc-body{ padding:24px 24px 20px;overflow-y:auto;flex:1;display:flex;flex-direction:column;gap:0; }
.uc-ai-row{ display:flex;align-items:flex-start;gap:10px;margin-bottom:20px; }
.uc-ai-msg{ font-size:14px;font-weight:500;color:var(--charcoal,#18181A);line-height:1.55;padding-top:3px; }
.uc-fields{ display:flex;flex-direction:column;gap:14px;margin-bottom:24px; }
.uc-grid-2{ display:grid;grid-template-columns:1fr 1fr;gap:12px; }
.uc-footer{ display:flex;align-items:center;gap:10px;padding-top:4px; }
.uc-main-btn{ display:flex;align-items:center;gap:7px;padding:10px 20px; }
.uc-script-ta{ min-height:140px;resize:vertical;line-height:1.65;font-size:13.5px;font-family:inherit; }
.uc-status-wrap{ padding:20px 0; }
.uc-video-el{ width:100%;height:auto;border-radius:14px;display:block;box-shadow:0 8px 40px rgba(0,0,0,.22); }
.uc-creator-grid{ display:grid;grid-template-columns:repeat(3,1fr);gap:8px; }
.uc-creator-card{ background:var(--bg2);border:1.5px solid var(--border,#2a2a2a);border-radius:10px;padding:12px 10px;cursor:pointer;text-align:left;transition:border-color .15s,background .15s;display:flex;flex-direction:column;gap:3px;width:100%; }
.uc-creator-card:hover{ border-color:#5a5a5a; }
.uc-creator-active{ border-color:var(--green)!important;background:color-mix(in srgb, var(--green) 6%, transparent)!important; }
.uc-creator-name{ font-size:13px;font-weight:600;color:var(--charcoal,#f0f0f0); }
.uc-creator-sub{ font-size:11px;color:var(--muted,#888); }

/* Background selection pills */
.uc-bg-grid{ display:flex;flex-wrap:wrap;gap:7px; }
.uc-bg-pill{ background:var(--bg3,#1a1a1a);border:1.5px solid var(--border,#2a2a2a);border-radius:8px;padding:7px 13px;font-size:12px;font-weight:500;color:var(--muted,#888);cursor:pointer;transition:border-color .15s,color .15s,background .15s;white-space:nowrap; }
.uc-bg-pill:hover{ border-color:#5a5a5a;color:var(--charcoal,#f0f0f0); }
.uc-bg-pill-active{ border-color:var(--green)!important;color:var(--charcoal,#f0f0f0)!important;background:color-mix(in srgb, var(--green) 7%, transparent)!important; }

/* Script mode toggle */
.uc-script-mode-row{ display:grid;grid-template-columns:1fr 1fr;gap:8px; }
.uc-script-opt{ background:var(--bg2,#141414);border:1.5px solid var(--border,#2a2a2a);border-radius:10px;padding:11px 13px;cursor:pointer;text-align:left;transition:border-color .15s,background .15s;display:flex;flex-direction:column;gap:3px;width:100%; }
.uc-script-opt:hover{ border-color:#5a5a5a; }
.uc-script-opt-active{ border-color:var(--green)!important;background:color-mix(in srgb, var(--green) 6%, transparent)!important; }
.uc-sopt-title{ font-size:13px;font-weight:600;color:var(--charcoal,#f0f0f0); }
.uc-sopt-desc{ font-size:11px;color:var(--muted,#888);line-height:1.4; }

@media(max-width:520px){ .uc-grid-2{ grid-template-columns:1fr; } .uc-creator-grid{ grid-template-columns:1fr; } .uc-script-mode-row{ grid-template-columns:1fr; } .uc-panel{ max-width:100%; } }

/* ── UGC Result — video frame + format variants ─────────────── */
.uc-video-frame{ display:flex;justify-content:center;align-items:flex-start;width:100%;margin:0 auto; }
.uc-fmt-vertical { max-width:300px; }
.uc-fmt-square   { max-width:420px; }
.uc-fmt-landscape{ max-width:100%; }

/* Download hint */
.uc-dl-hint{ font-size:11.5px;color:var(--muted,#666);text-align:center;margin:10px 0 0;letter-spacing:0.01em; }

/* Result action row */
.uc-action-row{ display:flex;justify-content:center;margin-top:16px; }

/* ── Char counter (cfOverlay textarea steps) ────────────────── */
.cf-char-counter{ font-size:11px;color:var(--muted,#666);text-align:right;margin:5px 0 2px;transition:color .2s; }
.cf-char-counter.cf-char-warn{ color:#f59e0b; }

/* ═══════════════════════════════════════════════════════════════
   PAYWALL MODAL — premium dark
   ═══════════════════════════════════════════════════════════════ */
.pw-modal{
  /* Sized for exactly three cards (Agency removed) -- was 1160px for four.
     max-width keeps it fluid on anything narrower than the modal itself. */
  width:900px;max-width:calc(100vw - 32px);padding:0;overflow:visible;
  background:#0D0D0D;border:1px solid rgba(255,255,255,.1);
  border-radius:24px;box-shadow:0 40px 100px rgba(0,0,0,.85);
}
.pw-close-btn{
  position:absolute;top:16px;right:16px;width:32px;height:32px;
  border-radius:50%;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);
  cursor:pointer;display:flex;align-items:center;justify-content:center;z-index:2;
  color:rgba(255,255,255,.5);transition:background .15s,color .15s;
}
.pw-close-btn:hover{background:rgba(255,255,255,.12);color:#fff;}
.pw-header{
  padding:32px 32px 24px;text-align:center;
  border-bottom:1px solid rgba(255,255,255,.07);
}
.pw-eyebrow{
  display:inline-flex;align-items:center;gap:7px;
  background:color-mix(in srgb, var(--green) 8%, transparent);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius:20px;padding:4px 13px;margin-bottom:14px;
  font-size:10px;font-weight:700;letter-spacing:.1em;color:var(--green);text-transform:uppercase;
}
.pw-eyebrow-dot{width:5px;height:5px;border-radius:50%;background:var(--green);flex-shrink:0;}
.pw-title{
  font-family:'Instrument Serif',serif;font-size:26px;font-weight:400;
  color:#F0F0F0;letter-spacing:-.6px;margin:0 0 8px;line-height:1.15;
}
.pw-title em{font-style:italic;color:var(--green);}
.pw-sub{font-size:13px;color:rgba(240,240,240,.38);margin:0;line-height:1.55;}
.pw-grid{
  /* Three equal columns, centered as one group -- grid's default
     align-items:stretch already gives every card equal height and keeps
     buttons aligned regardless of feature-list length, no extra rules needed. */
  padding:24px 24px 18px;display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;
  max-width:820px;margin:0 auto;
}
.pw-card{
  background:#111111;border:1px solid rgba(255,255,255,.09);
  border-radius:16px;padding:22px 18px;display:flex;flex-direction:column;
  transition:border-color .15s;
}
.pw-card:hover{border-color:rgba(255,255,255,.18);}
.pw-card-featured{
  border-color:color-mix(in srgb, var(--green) 30%, transparent)!important;background:#0F1A0A;
  position:relative;
}
.pw-card-featured:hover{border-color:color-mix(in srgb, var(--green) 55%, transparent)!important;}
.pw-featured-badge{
  position:absolute;top:-10px;left:50%;transform:translateX(-50%);
  background:var(--green);color:#000;font-size:9px;font-weight:800;
  letter-spacing:.1em;text-transform:uppercase;padding:3px 12px;border-radius:20px;white-space:nowrap;
}
.pw-card-name{
  font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:rgba(240,240,240,.4);margin-bottom:10px;
}
.pw-price-row{display:flex;align-items:baseline;gap:3px;margin-bottom:6px;}
.pw-price{
  font-family:'Instrument Serif',serif;font-size:36px;
  color:#F0F0F0;letter-spacing:-1px;line-height:1;
}
.pw-period{font-size:12px;color:rgba(240,240,240,.35);}
.pw-card-desc{font-size:12.5px;color:rgba(240,240,240,.35);line-height:1.5;margin-bottom:14px;}
.pw-card-divider{height:1px;background:rgba(255,255,255,.07);margin-bottom:14px;}
.pw-feats-list{list-style:none;display:flex;flex-direction:column;gap:7px;flex:1;margin-bottom:18px;}
.pw-feats-list .pw-feat{
  display:flex;align-items:flex-start;gap:8px;
  font-size:12px;color:rgba(240,240,240,.55);line-height:1.45;
}
.pw-feats-list .pw-feat::before{
  content:"";display:block;flex-shrink:0;
  width:5px;height:5px;border-radius:50%;
  background:var(--green);margin-top:4px;opacity:.7;
}
/* Free plan card — excluded items (Autopilot, higher limits, premium
   features) render muted with an X instead of the green dot, so what the
   Free plan doesn't include reads as informative, not as an error. */
.pw-feats-list .pw-feat-excluded{ color:rgba(240,240,240,.3); }
.pw-feats-list .pw-feat-excluded::before{
  content:"\2715"; width:auto; height:auto; border-radius:0; background:none;
  font-size:10px; line-height:1; margin-top:2px; opacity:.5; color:rgba(240,240,240,.4);
}
.pw-card-free{ border-color:rgba(255,255,255,.14); }
.pw-card-free:hover{ border-color:rgba(255,255,255,.24); }
.pw-btn{
  width:100%;padding:11px 0;font-size:13px;font-weight:700;
  border-radius:30px;border:none;cursor:pointer;font-family:inherit;
  transition:background .15s,transform .1s,box-shadow .15s;letter-spacing:-.05px;
}
.pw-btn-primary{background:var(--green);color:#000;}
.pw-btn-primary:hover:not(:disabled){background:var(--gm);transform:translateY(-1px);box-shadow:0 5px 16px color-mix(in srgb, var(--green) 22%, transparent);}
.pw-btn-outline{background:rgba(255,255,255,.07);color:#F0F0F0;border:1px solid rgba(255,255,255,.13);}
.pw-btn-outline:hover:not(:disabled){background:rgba(255,255,255,.12);}
.pw-btn:disabled{opacity:.45;cursor:not-allowed;}
.pw-footer{
  padding:14px 24px 18px;text-align:center;
  border-top:1px solid rgba(255,255,255,.07);
  display:flex;flex-direction:column;align-items:center;gap:6px;
}
.pw-skip-btn{
  background:none;border:none;font-size:12.5px;color:rgba(240,240,240,.3);
  cursor:pointer;font-family:inherit;transition:color .15s;padding:4px 8px;
}
.pw-skip-btn:hover{color:rgba(240,240,240,.6);}
.pw-footer-note{font-size:11px;color:rgba(240,240,240,.18);}
/* Tablet: three balanced columns all the way down to the mobile bottom-
   sheet breakpoint (768px, handled separately below) -- three cards never
   split unevenly across two columns. Mobile behaviour below is unchanged. */
@media(max-width:580px){.pw-grid{grid-template-columns:1fr;}}

/* ═══════════════════════════════════════════════════════════════
   INTEGRATIONS PANEL
   ═══════════════════════════════════════════════════════════════ */
.int-row{display:flex;align-items:flex-start;gap:16px;}
.int-icon{flex-shrink:0;width:40px;height:40px;border-radius:10px;overflow:hidden;}
.int-info{flex:1;min-width:0;}
.int-name{font-size:14px;font-weight:600;color:var(--text);margin-bottom:4px;}
.int-desc{font-size:12.5px;color:var(--text-2);line-height:1.5;}
.int-action{flex-shrink:0;display:flex;align-items:flex-start;}
.int-connected{
  margin-top:20px;padding-top:16px;
  border-top:1px solid rgba(0,0,0,.06);
  display:flex;flex-direction:column;gap:8px;
}
body.dark-mode .int-connected{border-color:rgba(255,255,255,.07);}
.int-field-row{display:flex;align-items:center;gap:12px;font-size:13px;}
.int-field-label{color:var(--text-2);min-width:110px;flex-shrink:0;}
.int-field-val{color:var(--text);font-weight:500;}
.int-status-dot{
  display:inline-block;width:7px;height:7px;border-radius:50%;
  background:#22C55E;margin-right:6px;flex-shrink:0;vertical-align:middle;
}
.int-status-warn{background:#F59E0B;}
.int-account-row{display:flex;flex-direction:column;gap:2px;padding:10px 12px;border-radius:10px;background:var(--surface-2,rgba(0,0,0,.04));margin-bottom:6px;cursor:pointer;border:1px solid transparent;transition:background .12s,border-color .12s;}
.int-account-row:hover:not(.int-account-selected){background:var(--bg2,rgba(0,0,0,.07));}
body.dark-mode .int-account-row{background:rgba(255,255,255,.05);}
body.dark-mode .int-account-row:hover:not(.int-account-selected){background:rgba(255,255,255,.08);}
.int-account-selected{background:var(--gpale,color-mix(in srgb, var(--green) 7%, transparent))!important;border-color:color-mix(in srgb, var(--green) 30%, transparent)!important;}
body.dark-mode .int-account-selected{background:color-mix(in srgb, var(--green) 8%, transparent)!important;}
.int-account-row-inner{display:flex;align-items:flex-start;gap:10px;}
.int-account-check{width:16px;height:16px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:var(--gm,var(--green));margin-top:2px;}
.int-account-name{font-size:13px;font-weight:500;color:var(--text);}
.int-account-id{font-size:12px;color:var(--text-2);}
.int-account-meta{font-size:11px;color:var(--text-2);}
.int-account-active-badge{display:inline-block;font-size:10px;font-weight:600;background:var(--gpale,color-mix(in srgb, var(--green) 12%, transparent));color:var(--gm,var(--green));border-radius:20px;padding:1px 8px;margin-left:6px;vertical-align:middle;letter-spacing:.01em;}
.int-account-type-badge{display:inline-block;font-size:10px;font-weight:600;border-radius:20px;padding:1px 8px;margin-left:6px;vertical-align:middle;letter-spacing:.01em;}
.int-account-type-client{background:rgba(99,179,237,.12);color:#63b3ed;}
.int-account-type-mcc{background:rgba(237,137,54,.12);color:#ed8935;}
.int-account-row-mcc{cursor:default!important;opacity:.8;}
.int-account-row-mcc:hover{background:var(--surface-2,rgba(0,0,0,.04))!important;}
body.dark-mode .int-account-row-mcc:hover{background:rgba(255,255,255,.05)!important;}
.int-account-mcc-warn{font-size:11px;color:#ed8935;margin-top:3px;}

/* ── INTEGRATIONS PAGE ──────────────────────────────────────── */
.intg-page{max-width:720px;margin:0 auto;padding:48px 24px 80px;}
.intg-hdr{margin-bottom:36px;}
.intg-title{font-size:22px;font-weight:700;color:var(--charcoal,#111);margin:0 0 10px;letter-spacing:-.01em;}
.intg-sub{font-size:14px;color:var(--muted);line-height:1.65;max-width:520px;margin:0;}
.intg-section-label{font-size:11px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin-bottom:12px;}
.intg-card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:20px 24px;margin-bottom:10px;transition:border-color .15s;}
.intg-card-top{display:flex;align-items:center;gap:16px;}
.intg-card-logo{width:44px;height:44px;flex-shrink:0;display:flex;align-items:center;justify-content:center;border-radius:10px;overflow:hidden;}
.intg-card-body{flex:1;min-width:0;}
.intg-card-name{font-size:14px;font-weight:600;color:var(--charcoal,#111);}
body.dark-mode .intg-card-name{color:var(--text,#e8e8e8);}
.intg-card-desc{font-size:13px;color:var(--muted);margin-top:3px;line-height:1.5;}
.intg-card-coming{opacity:.65;}
.intg-card-info{margin-top:20px;padding-top:20px;border-top:1px solid var(--border);}
@media(max-width:600px){.intg-page{padding:32px 16px 80px;}.intg-card{padding:16px;}.intg-card-top{flex-wrap:wrap;gap:12px;}}

/* ── ADS DASHBOARD ──────────────────────────────────────────── */
.ads-page{max-width:1160px;margin:0 auto;padding:36px 24px 80px;}
.ads-hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:28px;flex-wrap:wrap;}
.ads-title{font-size:22px;font-weight:700;color:var(--charcoal,#111);margin:0 0 6px;letter-spacing:-.01em;}
body.dark-mode .ads-title{color:var(--text,#e8e8e8);}
.ads-account-bar{display:inline-flex;align-items:center;gap:4px;font-size:13px;}
.ads-account-name{font-weight:500;color:var(--charcoal,#111);}
body.dark-mode .ads-account-name{color:var(--text,#e8e8e8);}
.ads-account-id{color:var(--muted);}
/* Date pills */
.ads-date-row{display:flex;gap:6px;flex-shrink:0;}
.ads-date-pill{padding:5px 14px;border-radius:20px;font-size:12px;font-weight:500;border:1px solid var(--border);background:transparent;color:var(--muted);cursor:pointer;transition:background .12s,color .12s,border-color .12s;}
.ads-date-pill:hover{border-color:var(--gm);color:var(--charcoal);}
.ads-date-pill.active{background:var(--gm,var(--green));color:#000;border-color:var(--gm,var(--green));}
/* Empty state */
.ads-empty{text-align:center;padding:80px 24px;}
.ads-empty-ico{width:56px;height:56px;border-radius:16px;background:var(--bg2);display:flex;align-items:center;justify-content:center;margin:0 auto 20px;color:var(--muted);}
.ads-empty-title{font-size:18px;font-weight:600;color:var(--charcoal);margin-bottom:8px;}
body.dark-mode .ads-empty-title{color:var(--text);}
.ads-empty-sub{font-size:14px;color:var(--muted);margin-bottom:24px;max-width:360px;margin-left:auto;margin-right:auto;line-height:1.6;}
/* Loading */
@keyframes ads-spin{to{transform:rotate(360deg);}}
.ads-loading-wrap{display:flex;align-items:center;gap:12px;padding:48px 0;color:var(--muted);font-size:14px;}
.ads-spinner{width:20px;height:20px;border:2px solid var(--border);border-top-color:var(--gm,var(--green));border-radius:50%;animation:ads-spin .7s linear infinite;flex-shrink:0;}
/* KPI cards */
.ads-kpis{display:grid;grid-template-columns:repeat(auto-fill,minmax(148px,1fr));gap:12px;margin-bottom:28px;}
.ads-kpi{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:18px 16px;}
.ads-kpi-val{font-size:26px;font-weight:800;color:var(--charcoal,#111);letter-spacing:-.03em;line-height:1;margin-bottom:7px;}
body.dark-mode .ads-kpi-val{color:var(--text,#e8e8e8);}
.ads-kpi-lbl{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);font-weight:600;}
.ads-kpi-accent{border-color:color-mix(in srgb, var(--green) 30%, transparent);background:var(--gpale,color-mix(in srgb, var(--green) 7%, transparent));}
.ads-kpi-accent .ads-kpi-val{color:var(--gm,var(--green));}
/* Section */
.ads-section{margin-bottom:24px;}
.ads-section-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;}
.ads-section-title{font-size:13px;font-weight:700;color:var(--charcoal,#111);letter-spacing:-.01em;}
body.dark-mode .ads-section-title{color:var(--text);}
/* Table */
.ads-table-wrap{overflow-x:auto;border-radius:14px;border:1px solid var(--border);}
.ads-table{width:100%;border-collapse:collapse;font-size:13px;min-width:640px;}
.ads-table th{padding:10px 14px;text-align:left;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);border-bottom:1px solid var(--border);background:var(--bg);white-space:nowrap;}
.ads-table th.ads-num,.ads-table td.ads-num{text-align:right;}
.ads-table td{padding:11px 14px;border-bottom:1px solid var(--border);color:var(--charcoal,#111);vertical-align:middle;}
body.dark-mode .ads-table td{color:var(--text);}
.ads-table tbody tr:last-child td{border-bottom:none;}
.ads-table tbody tr{cursor:pointer;transition:background .1s;}
.ads-table tbody tr:hover{background:var(--bg2);}
.ads-table .ads-name{font-weight:500;max-width:220px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
/* Back button */
.ads-back-btn{display:inline-flex;align-items:center;gap:6px;font-size:13px;color:var(--muted);padding:6px 0;cursor:pointer;border:none;background:none;margin-bottom:8px;}
.ads-back-btn:hover{color:var(--charcoal);}
body.dark-mode .ads-back-btn:hover{color:var(--text);}
.ads-detail-title{font-size:18px;font-weight:700;color:var(--charcoal);margin:12px 0 20px;letter-spacing:-.01em;}
body.dark-mode .ads-detail-title{color:var(--text);}
/* Oriven Score card */
.ads-score-card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:16px 24px;margin-bottom:10px;}
.ads-score-wrap{display:flex;align-items:flex-start;gap:28px;flex-wrap:wrap;}
.ads-score-ring-wrap{position:relative;flex-shrink:0;width:120px;height:120px;}
.ads-score-num{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:800;color:var(--charcoal,#111);letter-spacing:-.03em;}
body.dark-mode .ads-score-num{color:var(--text);}
.ads-score-track{fill:none;stroke:var(--border);stroke-width:10;}
.ads-score-fill{fill:none;stroke:var(--green);stroke-width:10;stroke-linecap:round;transform:rotate(-90deg);transform-origin:50% 50%;transition:stroke-dashoffset .7s cubic-bezier(.4,0,.2,1);}
.ads-score-info-title{font-size:15px;font-weight:700;color:var(--charcoal);margin-bottom:3px;}
body.dark-mode .ads-score-info-title{color:var(--text);}
.ads-score-sub{font-size:12px;color:var(--muted);margin-bottom:14px;}
/* AI cards */
.ads-ai-card{background:var(--surface);border:1px solid color-mix(in srgb, var(--green) 18%, transparent);border-radius:16px;padding:14px 22px;margin-bottom:10px;position:relative;overflow:hidden;}
/* Sits directly under the new KPI ring / chart modules — a faint top
   gradient marks it as the dashboard's final "intelligence layer" without
   touching its own analysis logic, endpoint, or button. */
.ads-ai-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg, transparent, color-mix(in srgb, var(--green) 55%, transparent), transparent);}
.ads-card-hd{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:4px;flex-wrap:wrap;}
/* AI Analysis header: the button sits beside the title specifically (not
   top-aligned against the whole two-line title+subtitle block), so its
   vertical center matches the title's regardless of their differing
   heights -- confirmed via direct measurement that top-alignment alone
   left the button ~2px lower than the title's center. */
.ads-card-hd-title-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:2px;}
.ads-card-title{font-size:14px;font-weight:700;color:var(--charcoal);margin-bottom:2px;}
body.dark-mode .ads-card-title{color:var(--text);}
.ads-card-sub{font-size:12px;color:var(--muted);line-height:1.5;margin-bottom:0;}
/* Findings grid */
.ads-findings{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:12px;margin-top:16px;}
.ads-finding{background:var(--bg);border:1px solid var(--border);border-radius:12px;padding:16px;}
.ads-finding-hd{display:flex;align-items:flex-start;gap:10px;margin-bottom:8px;}
.ads-finding-ico{width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.ads-finding-title{font-size:13px;font-weight:600;color:var(--charcoal);}
body.dark-mode .ads-finding-title{color:var(--text);}
.ads-finding-sev{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;margin-top:2px;}
.ads-finding-detail{font-size:13px;color:var(--muted);line-height:1.5;margin-bottom:8px;}
.ads-finding-action{font-size:12px;color:var(--charcoal);font-weight:500;padding-top:8px;border-top:1px solid var(--border);line-height:1.4;}
body.dark-mode .ads-finding-action{color:var(--text);}
/* Recommendations */
.ads-recs-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:16px;}
.ads-rec-title{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-bottom:10px;}
.ads-rec-list{list-style:none;margin:0;padding:0;}
.ads-rec-item{padding:8px 0;border-bottom:1px solid var(--border);font-size:13px;color:var(--charcoal);line-height:1.4;}
body.dark-mode .ads-rec-item{color:var(--text);}
.ads-rec-item:last-child{border-bottom:none;}
.ads-rec-badge{display:inline-block;font-size:9px;font-weight:700;border-radius:4px;padding:2px 5px;margin-right:5px;vertical-align:middle;letter-spacing:.03em;}
.ads-rec-broad{background:#dbeafe;color:#1e40af;}
.ads-rec-phrase{background:#fef3c7;color:#92400e;}
.ads-rec-exact{background:#d1fae5;color:#065f46;}
.ads-rec-neg{background:#fee2e2;color:#991b1b;}
body.dark-mode .ads-rec-broad{background:rgba(96,165,250,.2);color:#93c5fd;}
body.dark-mode .ads-rec-phrase{background:rgba(245,158,11,.2);color:#fcd34d;}
body.dark-mode .ads-rec-exact{background:rgba(52,211,153,.2);color:#6ee7b7;}
body.dark-mode .ads-rec-neg{background:rgba(239,68,68,.2);color:#fca5a5;}
/* Campaign info bar */
.ads-camp-info-bar{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px;}
.ads-camp-chip{display:inline-block;font-size:11px;font-weight:500;color:var(--muted);background:var(--surface-2,rgba(0,0,0,.05));border:1px solid var(--border);border-radius:6px;padding:3px 9px;white-space:nowrap;}

/* Clickable ad rows */
.ads-ad-row{cursor:pointer;transition:background .1s;}
.ads-ad-row:hover{background:var(--bg2,rgba(0,0,0,.04));}
.ads-ad-row-active{background:color-mix(in srgb, var(--green) 6%, transparent)!important;outline:1px solid color-mix(in srgb, var(--green) 25%, transparent);}

/* Ad preview panel */
.ads-ad-preview{background:var(--surface,#fff);border:1px solid var(--border);border-radius:14px;padding:20px;margin:12px 0 20px;animation:ads-slide-in .18s ease;}
body.dark-mode .ads-ad-preview{background:var(--surface-dark,#1a1a1a);}
@keyframes ads-slide-in{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:translateY(0)}}
.ads-ad-preview-inner{display:flex;flex-direction:column;gap:0;}
.ads-ad-preview-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;}
.ads-ad-type-badge{display:inline-block;font-size:10px;font-weight:700;background:rgba(96,165,250,.12);color:#60a5fa;border-radius:5px;padding:2px 7px;letter-spacing:.04em;}
.ads-ad-url-row{display:flex;align-items:center;gap:6px;margin:10px 0;padding:8px 10px;background:var(--bg2,rgba(0,0,0,.04));border-radius:8px;overflow:hidden;}
.ads-ad-url-link{font-size:12px;color:var(--muted);word-break:break-all;text-decoration:none;}
.ads-ad-url-link:hover{color:var(--charcoal);text-decoration:underline;}

/* Creative sections */
.ads-creative-section{margin-top:16px;padding-top:14px;border-top:1px solid var(--border);}
.ads-creative-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:8px;}
.ads-creative-list{display:flex;flex-direction:column;gap:4px;}
.ads-creative-item{display:flex;align-items:baseline;gap:8px;font-size:13px;color:var(--charcoal);line-height:1.45;padding:4px 0;}
body.dark-mode .ads-creative-item{color:var(--text);}
.ads-creative-idx{flex-shrink:0;width:18px;height:18px;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;background:var(--surface-2,rgba(0,0,0,.06));border-radius:50%;color:var(--muted);}

/* Google Search Ad simulation */
.ads-google-sim{background:var(--bg,#fff);border:1px solid var(--border);border-radius:10px;padding:14px 16px;max-width:560px;}
body.dark-mode .ads-google-sim{background:rgba(255,255,255,.04);}
.ads-google-sim-label{display:inline-block;font-size:10px;font-weight:700;color:#188038;border:1px solid #188038;border-radius:4px;padding:1px 5px;margin-bottom:6px;letter-spacing:.02em;}
.ads-google-sim-url{font-size:13px;color:#202124;margin-bottom:2px;word-break:break-all;}
body.dark-mode .ads-google-sim-url{color:var(--muted);}
.ads-google-sim-headline{font-size:18px;font-weight:400;color:#1a0dab;line-height:1.3;margin-bottom:4px;}
body.dark-mode .ads-google-sim-headline{color:#8ab4f8;}
.ads-google-sim-desc{font-size:13px;color:#4d5156;line-height:1.5;}
body.dark-mode .ads-google-sim-desc{color:var(--muted);}

/* Ad performance insight bar */
.ads-ad-insight{margin-top:14px;font-size:12px;color:var(--muted);background:var(--surface-2,rgba(0,0,0,.04));border-radius:8px;padding:8px 12px;border-left:3px solid var(--border);}

/* Responsive */
@media(max-width:768px){
  .ads-page{padding:24px 16px 80px;}
  .ads-kpis{grid-template-columns:repeat(2,1fr);}
  .ads-recs-grid{grid-template-columns:1fr;}
  .ads-findings{grid-template-columns:1fr;}
  .ads-score-wrap{gap:16px;}
  .ads-google-sim{max-width:100%;}
  .ads-google-sim-headline{font-size:15px;}
}

/* ═══════════════════════════════════════════════════════════════
   AD INSPECTOR — right-side drawer
   ═══════════════════════════════════════════════════════════════ */

/* Backdrop overlay */
.ads-inspector-overlay{position:fixed;inset:0;background:rgba(0,0,0,0);z-index:1000;pointer-events:none;transition:background .25s ease;}
.ads-inspector-overlay.open{background:rgba(0,0,0,.45);pointer-events:all;}

/* Drawer */
.ads-inspector{position:fixed;top:0;right:0;bottom:0;width:500px;max-width:100vw;background:var(--surface);border-left:1px solid var(--border);z-index:1001;display:flex;flex-direction:column;transform:translateX(100%);transition:transform .28s cubic-bezier(.22,1,.36,1);overflow:hidden;box-shadow:-8px 0 32px rgba(0,0,0,.12);}
.ads-inspector.open{transform:translateX(0);}

/* Header */
.ads-insp-hd{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:18px 20px 16px;border-bottom:1px solid var(--border);flex-shrink:0;}
.ads-insp-title{font-size:13px;font-weight:700;color:var(--charcoal);letter-spacing:-.01em;margin-bottom:6px;}
body.dark-mode .ads-insp-title{color:var(--text);}
.ads-insp-meta{display:flex;align-items:center;gap:6px;flex-wrap:wrap;}
.ads-insp-close{width:28px;height:28px;flex-shrink:0;display:flex;align-items:center;justify-content:center;border:none;background:var(--bg2,rgba(0,0,0,.05));border-radius:7px;cursor:pointer;color:var(--muted);transition:background .12s,color .12s;}
.ads-insp-close:hover{background:var(--border);color:var(--charcoal);}
body.dark-mode .ads-insp-close:hover{color:var(--text);}

/* Scrollable body */
.ads-insp-body{flex:1;overflow-y:auto;padding:20px;}

/* Section */
.ads-insp-sec{margin-bottom:24px;padding-bottom:24px;border-bottom:1px solid var(--border);}
.ads-insp-sec:last-child{border-bottom:none;margin-bottom:0;padding-bottom:0;}
.ads-insp-sec-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin-bottom:14px;}

/* Google Search Ad simulation (inspector version — more accurate) */
.ads-gsim{background:var(--bg,#fff);border:1px solid var(--border);border-radius:12px;padding:16px 18px;}
body.dark-mode .ads-gsim{background:rgba(255,255,255,.035);}
.ads-gsim-sponsored{display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:600;color:#188038;margin-bottom:5px;}
.ads-gsim-sponsored-dot{width:6px;height:6px;border-radius:50%;background:#188038;flex-shrink:0;}
.ads-gsim-url{font-size:14px;color:#202124;line-height:1.3;margin-bottom:1px;word-break:break-word;}
body.dark-mode .ads-gsim-url{color:rgba(255,255,255,.7);}
.ads-gsim-breadcrumb{font-size:12px;color:#5f6368;margin-bottom:8px;word-break:break-word;}
body.dark-mode .ads-gsim-breadcrumb{color:var(--muted);}
.ads-gsim-headline{font-size:20px;font-weight:400;color:#1a0dab;line-height:1.3;margin-bottom:5px;}
body.dark-mode .ads-gsim-headline{color:#8ab4f8;}
.ads-gsim-desc{font-size:13px;color:#4d5156;line-height:1.55;}
body.dark-mode .ads-gsim-desc{color:var(--muted);}

/* Asset lists (headlines / descriptions) */
.ads-insp-asset-hd{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:16px 0 8px;}
.ads-insp-asset-note{font-size:10px;font-weight:400;text-transform:none;letter-spacing:0;color:var(--muted);opacity:.7;}
.ads-insp-asset-list{display:flex;flex-direction:column;}
.ads-insp-asset-row{display:flex;align-items:baseline;gap:9px;font-size:13px;color:var(--charcoal);line-height:1.45;padding:6px 0;border-bottom:1px solid var(--border);}
.ads-insp-asset-row:last-child{border-bottom:none;}
body.dark-mode .ads-insp-asset-row{color:var(--text);}
.ads-insp-asset-num{flex-shrink:0;width:18px;height:18px;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;background:var(--bg2,rgba(0,0,0,.06));border-radius:50%;color:var(--muted);}

/* Final URL chip */
.ads-insp-url-chip{display:flex;align-items:flex-start;gap:8px;margin-top:14px;padding:10px 12px;background:var(--bg2,rgba(0,0,0,.04));border-radius:8px;}
.ads-insp-url-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);white-space:nowrap;padding-top:2px;}
.ads-insp-url-val{font-size:12px;color:var(--muted);word-break:break-all;text-decoration:none;}
.ads-insp-url-val:hover{color:var(--gm);text-decoration:underline;}

/* Info grid (Ad Information section) */
.ads-insp-info-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.ads-insp-info-cell{background:var(--bg2,rgba(0,0,0,.03));border:1px solid var(--border);border-radius:10px;padding:10px 12px;}
.ads-insp-info-cell.full{grid-column:1/-1;}
.ads-insp-info-lbl{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:3px;}
.ads-insp-info-val{font-size:12px;font-weight:500;color:var(--charcoal);word-break:break-all;line-height:1.4;}
body.dark-mode .ads-insp-info-val{color:var(--text);}

/* Performance stats grid */
.ads-insp-perf-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}
.ads-insp-stat{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:13px 12px;}
.ads-insp-stat.accent{border-color:color-mix(in srgb, var(--green) 25%, transparent);background:color-mix(in srgb, var(--green) 5%, transparent);}
.ads-insp-stat-val{font-size:20px;font-weight:800;color:var(--charcoal);letter-spacing:-.03em;line-height:1;margin-bottom:5px;}
body.dark-mode .ads-insp-stat-val{color:var(--text);}
.ads-insp-stat.accent .ads-insp-stat-val{color:var(--gm,var(--green));}
.ads-insp-stat-lbl{font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);font-weight:600;}
.ads-insp-insight{margin-top:12px;font-size:12px;color:var(--muted);background:var(--surface-2,rgba(0,0,0,.04));border-radius:8px;padding:9px 12px;border-left:3px solid var(--border);line-height:1.5;}

/* Keywords table inside inspector */
.ads-insp-kw-wrap{overflow-x:auto;border-radius:10px;border:1px solid var(--border);}
.ads-insp-kw-table{width:100%;border-collapse:collapse;font-size:12px;min-width:300px;}
.ads-insp-kw-table th{padding:8px 10px;text-align:left;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);border-bottom:1px solid var(--border);background:var(--bg);white-space:nowrap;}
.ads-insp-kw-table th.r,.ads-insp-kw-table td.r{text-align:right;}
.ads-insp-kw-table td{padding:9px 10px;border-bottom:1px solid var(--border);color:var(--charcoal);vertical-align:middle;}
body.dark-mode .ads-insp-kw-table td{color:var(--text);}
.ads-insp-kw-table tbody tr:last-child td{border-bottom:none;}
.ads-insp-kw-name{font-weight:500;max-width:160px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}

/* Responsive */
@media(max-width:768px){
  .ads-inspector{width:100vw;border-left:none;border-top:1px solid var(--border);top:auto;height:85vh;}
  .ads-insp-perf-grid{grid-template-columns:repeat(2,1fr);}
  .ads-insp-info-grid{grid-template-columns:1fr 1fr;}
}

/* ── Platform tabs ───────────────────────────────────────────── */
.ads-ptabs{display:flex;gap:0;border-bottom:1px solid var(--border);margin-bottom:24px;}
.ads-ptab{display:flex;align-items:center;gap:8px;padding:9px 18px;font-size:13px;font-weight:500;color:var(--muted);background:none;border:none;border-bottom:2px solid transparent;cursor:pointer;transition:color .15s,border-color .15s;margin-bottom:-1px;white-space:nowrap;letter-spacing:-.01em;}
.ads-ptab:hover{color:var(--charcoal);}
body.dark-mode .ads-ptab:hover{color:var(--text);}
.ads-ptab.active{color:var(--gm,var(--green));border-bottom-color:var(--gm,var(--green));}
.ads-ptab-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0;opacity:.55;}
.ads-ptab.active .ads-ptab-dot{opacity:1;}
/* Meta ad creative preview */
.meta-ad-preview{border:1px solid var(--border);border-radius:12px;overflow:hidden;margin-bottom:16px;}
.meta-ad-preview-img{width:100%;max-height:200px;object-fit:cover;display:block;background:var(--border);}
.meta-ad-preview-body{padding:12px 14px;}
.meta-ad-preview-headline{font-size:14px;font-weight:700;color:var(--charcoal);line-height:1.3;margin-bottom:4px;}
body.dark-mode .meta-ad-preview-headline{color:var(--text);}
.meta-ad-preview-text{font-size:12px;color:var(--muted);line-height:1.5;}
.meta-ad-preview-cta{display:inline-block;margin-top:10px;padding:7px 14px;background:var(--gm,var(--green));color:#000;border-radius:7px;font-size:12px;font-weight:700;}

/* Hard paywall mode — close button and skip button hidden */
#modal-paywall.pw-hard .pw-close-btn,
#modal-paywall.pw-hard .pw-skip-btn { display:none !important; }

/* Flow step indicator in paywall (shown in hard mode only) */
.pw-flow-steps{
  display:none; align-items:center; gap:8px;
  justify-content:center; margin-bottom:20px;
}
#modal-paywall.pw-hard .pw-flow-steps{ display:flex; }
.pw-flow-step{
  font-size:11px; font-weight:600; letter-spacing:.06em; text-transform:uppercase;
  color:rgba(240,240,240,.28); display:flex; align-items:center; gap:5px;
}
.pw-flow-step.pw-flow-done{ color:color-mix(in srgb, var(--green) 70%, transparent); }
.pw-flow-step.pw-flow-active{ color:#fff; }
.pw-flow-sep{ font-size:10px; color:rgba(240,240,240,.18); }

/* Flow step indicator in onboarding overlay */
.ob-flow-steps{
  display:flex; align-items:center; gap:8px; justify-content:center;
  margin-bottom:24px;
}
.ob-flow-step{
  font-size:11px; font-weight:600; letter-spacing:.06em; text-transform:uppercase;
  color:rgba(240,240,240,.28); display:flex; align-items:center; gap:5px;
}
.ob-flow-step.ob-flow-done{ color:color-mix(in srgb, var(--green) 70%, transparent); }
.ob-flow-step.ob-flow-active{ color:#fff; }
.ob-flow-sep{ font-size:10px; color:rgba(240,240,240,.18); }

/* ═══════════════════════════════════════════════════════════════
   SPOTLIGHT ONBOARDING SYSTEM
   ═══════════════════════════════════════════════════════════════ */

/* Spotlight ring — positioned over the spotlit nav item.
   The massive box-shadow dims everything outside the ring while
   the transparent interior lets the nav item show through. */
#ob-ring{
  display:none;
  position:fixed;
  /* Above .orv-sb (z-index:9200 !important) — otherwise the sidebar would
     render above the ring's dimming box-shadow and never actually dim. */
  z-index:9300;
  background:transparent;
  pointer-events:none;
  opacity:0;
  border-radius:12px;
  transition:opacity .3s ease,
             top .35s cubic-bezier(.4,0,.2,1),
             left .35s cubic-bezier(.4,0,.2,1),
             width .35s cubic-bezier(.4,0,.2,1),
             height .35s cubic-bezier(.4,0,.2,1);
  box-shadow:0 0 0 9999px rgba(0,0,0,.78),
             0 0 0 2px color-mix(in srgb, var(--green) 75%, transparent),
             0 0 22px color-mix(in srgb, var(--green) 18%, transparent);
}

/* Full-screen backdrop for the final CTA step (no spotlight target) */
#ob-backdrop{
  display:none;
  position:fixed;inset:0;
  background:rgba(0,0,0,.82);
  z-index:9300;
  pointer-events:auto;
  opacity:0;
  transition:opacity .3s ease;
}

/* Tooltip card */
#ob-tooltip{
  display:none;
  position:fixed;
  z-index:9301;
  width:290px;
  max-width:calc(100vw - 32px);
  background:#111;
  border:1px solid rgba(255,255,255,.1);
  border-radius:16px;
  padding:20px 20px 16px;
  opacity:0;
  transition:opacity .22s ease;
  box-shadow:0 16px 56px rgba(0,0,0,.7),0 0 0 1px rgba(255,255,255,.05);
  pointer-events:auto;
}
#ob-tooltip.ob-tt-center{ width:420px; max-width:calc(100vw - 40px); }

/* Left-pointing arrow on tooltip (hidden in centered mode).
   --ob-arrow-top is set dynamically by _obRender() so the arrow
   always points at the nav item's centre even when the card is
   shifted to stay inside the viewport. */
#ob-tooltip{ --ob-arrow-top: 18px; }
#ob-tooltip.ob-tt-arrow::before{
  content:'';position:absolute;left:-8px;top:var(--ob-arrow-top);
  width:0;height:0;
  border-top:8px solid transparent;
  border-bottom:8px solid transparent;
  border-right:8px solid rgba(255,255,255,.1);
}
#ob-tooltip.ob-tt-arrow::after{
  content:'';position:absolute;left:-7px;top:var(--ob-arrow-top);
  width:0;height:0;
  border-top:8px solid transparent;
  border-bottom:8px solid transparent;
  border-right:8px solid #111;
}

.ob-tt-top{ display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;gap:12px; }
.ob-tt-section{ font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--green); }
.ob-tt-skip{
  background:none;border:none;color:rgba(255,255,255,.32);font-size:11px;font-family:inherit;
  cursor:pointer;padding:2px 0;transition:color .15s;flex-shrink:0;
}
.ob-tt-skip:hover{ color:rgba(255,255,255,.6); }
.ob-tt-title{ font-size:16px;font-weight:600;color:#fff;line-height:1.35;margin:0 0 10px; }
.ob-tt-title em{ font-style:italic;color:var(--green); }
.ob-tt-desc{ font-size:13px;color:rgba(240,240,240,.44);line-height:1.65;margin:0 0 20px; }
.ob-tt-nav{ display:flex;align-items:center;justify-content:space-between;gap:12px; }
.ob-tt-progress{ display:flex;flex-direction:column;gap:5px; }
.ob-tt-steplabel{ font-size:10.5px;font-weight:500;color:rgba(255,255,255,.32); }
.ob-tt-dots{ display:flex;gap:5px;align-items:center; }
.ob-tt-dot{ display:inline-block;width:5px;height:5px;border-radius:50%;background:rgba(255,255,255,.2);transition:background .2s,transform .2s; }
.ob-tt-dot.ob-tt-dot-active{ background:var(--green);transform:scale(1.4); }
.ob-tt-btns{ display:flex;gap:8px;align-items:center; }
.ob-tt-back{
  background:none;border:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,.5);
  border-radius:8px;padding:7px 14px;font-size:13px;font-family:inherit;cursor:pointer;
  transition:border-color .15s,color .15s;
}
.ob-tt-back:hover{ border-color:rgba(255,255,255,.28);color:rgba(255,255,255,.8); }
.ob-tt-next{
  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);color:#fff;
  border-radius:8px;padding:7px 16px;font-size:13px;font-family:inherit;
  cursor:pointer;font-weight:500;transition:background .15s;
}
.ob-tt-next:hover{ background:rgba(255,255,255,.14); }
.ob-tt-next.ob-tt-cta{ background:var(--green);color:#000;border-color:var(--green);font-weight:600; }
.ob-tt-next.ob-tt-cta:hover{ background:var(--gm); }
/* Interactive-wait frames (Generate / Publish) — no click to fire, just a
   quiet status instead of a disabled-looking button. */
.ob-tt-next.ob-tt-waiting{
  background:none;border:1px dashed rgba(255,255,255,.18);color:rgba(255,255,255,.4);
  cursor:default;font-weight:400;font-style:italic;
}
.ob-tt-next.ob-tt-waiting:hover{ background:none; }

/* ── Legacy overlay styles (kept as dead code — elements removed) ─ */
#onboardingOverlay{
  position:fixed;inset:0;z-index:8000;
  background:rgba(0,0,0,.88);backdrop-filter:blur(8px);
  display:flex;align-items:center;justify-content:center;
  padding:24px;
}
.ob-tour-skip{
  position:absolute;top:20px;right:24px;
  background:none;border:none;font-size:12px;color:rgba(255,255,255,.28);
  cursor:pointer;font-family:inherit;transition:color .15s;letter-spacing:.02em;
}
.ob-tour-skip:hover{color:rgba(255,255,255,.6);}
.ob-tour-card{
  width:100%;max-width:500px;background:#111111;
  border:1px solid rgba(255,255,255,.09);border-radius:24px;
  padding:40px 36px 32px;position:relative;
  box-shadow:0 32px 80px rgba(0,0,0,.7);
}
/* Steps: hidden by default, shown when .ob-active */
.ob-step{display:none;flex-direction:column;align-items:flex-start;animation:obFadeIn .35s ease;}
.ob-step.ob-active{display:flex;}
.ob-step.ob-exit{animation:obFadeOut .25s ease forwards;}
@keyframes obFadeIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@keyframes obFadeOut{from{opacity:1;transform:translateY(0)}to{opacity:0;transform:translateY(-10px)}}
/* Tour icon */
.ob-tour-icon{
  width:52px;height:52px;border-radius:14px;
  display:flex;align-items:center;justify-content:center;
  margin-bottom:22px;flex-shrink:0;
}
.ob-tour-icon svg{width:24px;height:24px;}
.ob-icon-dashboard{background:color-mix(in srgb, var(--green) 10%, transparent);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);color:var(--green);}
.ob-icon-create{background:rgba(167,139,250,.1);border:1px solid rgba(167,139,250,.2);color:#A78BFA;}
.ob-icon-studio{background:rgba(59,130,246,.1);border:1px solid rgba(59,130,246,.2);color:#3B82F6;}
.ob-icon-inspiration{background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.2);color:#F59E0B;}
.ob-icon-settings{background:rgba(156,163,175,.1);border:1px solid rgba(156,163,175,.15);color:#9CA3AF;}
.ob-icon-team{background:rgba(167,139,250,.1);border:1px solid rgba(167,139,250,.2);color:#A78BFA;}
/* Tour text */
.ob-tour-section{
  font-size:10.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:color-mix(in srgb, var(--green) 70%, transparent);margin-bottom:8px;
}
.ob-tour-title{
  font-family:'Instrument Serif',serif;font-size:26px;font-weight:400;
  color:#F0F0F0;letter-spacing:-.5px;line-height:1.2;margin-bottom:12px;
}
.ob-tour-title em{font-style:italic;color:var(--green);}
.ob-tour-desc{font-size:14px;color:rgba(240,240,240,.42);line-height:1.65;margin-bottom:28px;}
/* Navigation */
.ob-tour-nav{display:flex;align-items:center;justify-content:space-between;}
.ob-dots{display:flex;gap:6px;align-items:center;}
.ob-dot{
  width:6px;height:6px;border-radius:50%;
  background:rgba(255,255,255,.15);transition:background .2s,transform .2s;
}
.ob-dot.ob-dot-active{background:var(--green);transform:scale(1.3);}
.ob-tour-btns{display:flex;gap:10px;align-items:center;}
.ob-back-btn{
  background:none;border:none;font-size:13px;color:rgba(255,255,255,.3);
  cursor:pointer;font-family:inherit;transition:color .15s;padding:0;
}
.ob-back-btn:hover{color:rgba(255,255,255,.65);}
.ob-next-btn{
  padding:10px 24px;background:var(--green);color:#000;
  font-size:13px;font-weight:700;border-radius:30px;border:none;
  cursor:pointer;font-family:inherit;transition:background .15s,transform .1s,box-shadow .15s;
  letter-spacing:-.05px;
}
.ob-next-btn:hover{background:var(--gm);transform:translateY(-1px);box-shadow:0 5px 14px color-mix(in srgb, var(--green) 22%, transparent);}
.ob-next-btn.ob-finish{background:#F0F0F0;color:#0A0A0A;}
.ob-next-btn.ob-finish:hover{background:#fff;}

/* Navigation hint — subtle cue below the tour card */
.ob-nav-hint{
  margin-top:14px;
  text-align:center;
  font-size:11px;
  font-weight:500;
  letter-spacing:.06em;
  color:rgba(240,240,240,.28);
  user-select:none;
  pointer-events:none;
}
.ob-hint-mobile{ display:none; }
.ob-hint-desktop{ display:inline; }
@media(max-width:767px){
  .ob-hint-desktop{ display:none; }
  .ob-hint-mobile{ display:inline; }
}

/* ═══════════════════════════════════════════════════════════════
   BRANDCORE AI WIZARD
   ═══════════════════════════════════════════════════════════════ */
.bcw-overlay{
  position:fixed;inset:0;z-index:8500;
  background:rgba(0,0,0,.92);backdrop-filter:blur(10px);
  display:flex;align-items:center;justify-content:center;
  padding:24px;opacity:0;transition:opacity .28s ease;
}
.bcw-panel{
  width:100%;max-width:560px;background:#111111;
  border:1px solid rgba(255,255,255,.1);border-radius:24px;
  display:flex;flex-direction:column;min-height:480px;
  box-shadow:0 32px 80px rgba(0,0,0,.7);position:relative;overflow:hidden;
}
.bcw-header{
  display:flex;align-items:center;justify-content:space-between;
  padding:20px 24px 0;
}
.bcw-logo{
  display:flex;align-items:center;gap:8px;
  font-size:12.5px;font-weight:700;color:rgba(240,240,240,.5);letter-spacing:.02em;
}
.bcw-close{
  width:28px;height:28px;border-radius:50%;background:rgba(255,255,255,.07);
  border:1px solid rgba(255,255,255,.1);cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  color:rgba(255,255,255,.4);transition:background .15s,color .15s;
}
.bcw-close:hover{background:rgba(255,255,255,.13);color:#fff;}
.bcw-progress{
  display:flex;align-items:center;gap:12px;padding:16px 24px 0;
}
.bcw-prog-track{flex:1;height:2px;background:rgba(255,255,255,.08);border-radius:2px;overflow:hidden;}
.bcw-prog-fill{height:100%;background:var(--green);border-radius:2px;transition:width .35s ease;}
.bcw-prog-lbl{font-size:11px;color:rgba(240,240,240,.25);letter-spacing:.04em;white-space:nowrap;}
.bcw-content{flex:1;padding:32px 28px 20px;position:relative;}
.bcw-step{display:none;flex-direction:column;animation:bcwIn .3s ease;}
.bcw-step.bcw-step-active{display:flex;}
@keyframes bcwIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
.bcw-step-eyebrow{
  font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:color-mix(in srgb, var(--green) 65%, transparent);margin-bottom:10px;
}
.bcw-step-q{
  font-family:'Instrument Serif',serif;font-size:24px;color:#F0F0F0;
  letter-spacing:-.5px;line-height:1.2;margin-bottom:8px;
}
.bcw-step-q em{font-style:italic;color:var(--green);}
.bcw-step-sub{font-size:13px;color:rgba(240,240,240,.38);line-height:1.6;margin-bottom:22px;}
.bcw-inp{
  background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);
  border-radius:12px;padding:13px 16px;font-size:14px;color:#F0F0F0;
  font-family:inherit;outline:none;width:100%;box-sizing:border-box;
  transition:border-color .15s,background .15s;
}
.bcw-inp:focus{border-color:color-mix(in srgb, var(--green) 40%, transparent);background:rgba(255,255,255,.07);}
.bcw-inp::placeholder{color:rgba(240,240,240,.18);}
.bcw-textarea{resize:none;}
.bcw-pills{display:flex;flex-wrap:wrap;gap:8px;}
.bcw-pill{
  padding:8px 16px;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.1);border-radius:20px;
  font-size:13px;color:rgba(240,240,240,.65);cursor:pointer;
  transition:background .15s,border-color .15s,color .15s;
}
.bcw-pill:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.2);}
.bcw-pill.bcw-pill-sel{background:color-mix(in srgb, var(--green) 12%, transparent);border-color:color-mix(in srgb, var(--green) 45%, transparent);color:var(--green);}
.bcw-nav{
  display:flex;align-items:center;justify-content:space-between;
  padding:16px 24px 22px;border-top:1px solid rgba(255,255,255,.07);
}
.bcw-back-btn{
  background:none;border:none;font-size:13px;color:rgba(255,255,255,.28);
  cursor:pointer;font-family:inherit;transition:color .15s;padding:0;
}
.bcw-back-btn:hover{color:rgba(255,255,255,.65);}
.bcw-next-btn{
  padding:11px 28px;background:var(--green);color:#000;
  font-size:13.5px;font-weight:700;border-radius:30px;border:none;
  cursor:pointer;font-family:inherit;letter-spacing:-.05px;
  transition:background .15s,transform .1s,box-shadow .15s;
}
.bcw-next-btn:hover{background:var(--gm);transform:translateY(-1px);box-shadow:0 5px 16px color-mix(in srgb, var(--green) 25%, transparent);}
.bcw-generate{background:#F0F0F0;color:#0A0A0A;}
.bcw-generate:hover{background:#fff;}

/* ═══════════════════════════════════════════════════════════════
   BRANDCORE MANUAL SETUP — expanded modal
   ═══════════════════════════════════════════════════════════════ */
.bcs-section{margin-bottom:22px;padding-bottom:22px;border-bottom:1px solid var(--border);}
.bcs-section:last-of-type{border-bottom:none;margin-bottom:0;padding-bottom:0;}
.bcs-section-label{
  font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:var(--muted);margin-bottom:12px;
}
.bcs-color-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
.bcs-color-row{display:flex;align-items:center;gap:8px;}
.bcs-color-inp{flex:1;}
.bcs-color-swatch{
  width:32px;height:32px;border-radius:8px;flex-shrink:0;
  border:1px solid rgba(0,0,0,.08);background:transparent;transition:background .15s;
}
.bcs-grid-2{display:grid;grid-template-columns:1fr 1fr;gap:10px;}

/* ═══════════════════════════════════════════════════════════════
   BRANDCORE PROFILE PAGE
   ═══════════════════════════════════════════════════════════════ */

/* ── Scroll container ─────────────────────────────────────────── */
.bcp-scroll{height:100%;overflow-y:auto;padding:0;}

/* ── Empty state ──────────────────────────────────────────────── */
.bcp-empty{
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  min-height:70vh;padding:48px 32px;text-align:center;
}
.bcp-empty-orb{
  width:72px;height:72px;border-radius:50%;
  background:color-mix(in srgb, var(--green) 8%, transparent);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);
  display:flex;align-items:center;justify-content:center;margin-bottom:24px;
}
.bcp-empty-title{
  font-family:'Instrument Serif',serif;font-size:28px;font-weight:400;
  color:var(--charcoal);letter-spacing:-.5px;margin-bottom:10px;line-height:1.2;
}
.bcp-empty-title em{font-style:italic;color:var(--green);}
.bcp-empty-sub{font-size:14px;color:var(--muted);line-height:1.65;max-width:420px;margin-bottom:28px;}
.bcp-empty-actions{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;}
.bcp-btn-primary{
  padding:12px 28px;background:var(--green);color:#000;font-size:14px;font-weight:700;
  border-radius:30px;border:none;cursor:pointer;font-family:inherit;
  display:flex;align-items:center;gap:8px;
  transition:background .15s,transform .1s,box-shadow .15s;letter-spacing:-.05px;
}
.bcp-btn-primary:hover{background:var(--gm);transform:translateY(-1px);box-shadow:0 5px 16px color-mix(in srgb, var(--green) 22%, transparent);}
.bcp-btn-ghost{
  padding:12px 28px;background:transparent;color:var(--charcoal);font-size:14px;font-weight:600;
  border-radius:30px;border:1px solid var(--border);cursor:pointer;font-family:inherit;
  transition:background .15s,border-color .15s;
}
.bcp-btn-ghost:hover{background:var(--bg2);border-color:var(--b2);}

/* ── Profile layout ───────────────────────────────────────────── */
.bcp-profile{max-width:900px;margin:0 auto;padding:32px 32px 64px;}
@media(max-width:680px){.bcp-profile{padding:20px 16px 48px;}}

/* ── Brand Header ─────────────────────────────────────────────── */
.bcp-header{
  display:flex;align-items:flex-start;justify-content:space-between;
  gap:24px;margin-bottom:48px;flex-wrap:wrap;
}
.bcp-hdr-left{flex:1;min-width:200px;}
.bcp-eyebrow{
  display:inline-flex;align-items:center;gap:7px;margin-bottom:12px;
  font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--muted);
}
.bcp-eyebrow-dot{
  width:6px;height:6px;border-radius:50%;background:var(--border);
  transition:background .3s;
}
.bcp-eyebrow-dot.active{background:var(--green);box-shadow:0 0 0 3px color-mix(in srgb, var(--green) 15%, transparent);}
.bcp-brand-name{
  font-family:'Instrument Serif',serif;font-size:44px;font-weight:400;
  color:var(--charcoal);letter-spacing:-1.2px;line-height:1;margin-bottom:10px;
}
@media(max-width:500px){.bcp-brand-name{font-size:32px;}}
.bcp-brand-tagline{
  font-size:15px;color:var(--muted);font-weight:400;line-height:1.5;
  font-style:italic;
}
.bcp-hdr-right{display:flex;flex-direction:column;align-items:flex-end;gap:16px;}
.bcp-score-block{text-align:right;}
.bcp-score-num{
  font-family:'Instrument Serif',serif;font-size:48px;font-weight:400;
  color:var(--green);letter-spacing:-1.5px;line-height:1;margin-bottom:4px;
}
.bcp-score-lbl{font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:10px;}
.bcp-score-bar-track{
  width:160px;height:3px;background:var(--border);border-radius:3px;overflow:hidden;
  margin-left:auto;margin-bottom:8px;
}
.bcp-score-bar-fill{height:100%;background:var(--green);border-radius:3px;transition:width .6s cubic-bezier(.4,0,.2,1);}
.bcp-score-msg{font-size:11.5px;color:var(--muted);line-height:1.5;max-width:180px;text-align:right;}
.bcp-hdr-actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end;}
.bcp-action-btn{
  display:flex;align-items:center;gap:6px;padding:8px 16px;
  background:var(--bg2);border:1px solid var(--border);border-radius:20px;
  font-size:12px;font-weight:600;color:var(--charcoal);cursor:pointer;
  font-family:inherit;transition:background .15s,border-color .15s,transform .1s;
}
.bcp-action-btn:hover{background:var(--bg3);border-color:var(--b2);}
.bcp-action-btn-primary{
  background:var(--green);color:#000;border-color:var(--green);
}
.bcp-action-btn-primary:hover{background:var(--gm);border-color:var(--gm);transform:translateY(-1px);}

/* ── Logo empty state ───────────────────────────────────────── */
.bcp-logo-empty{
  padding:32px 24px;text-align:center;
  border:1.5px dashed var(--border);border-radius:14px;
}
.bcp-logo-empty-msg{font-size:14px;font-weight:600;color:var(--charcoal);margin-bottom:6px;}
.bcp-logo-empty-sub{font-size:13px;color:var(--muted);line-height:1.55;margin-bottom:20px;}
.bcp-logo-empty-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;}

/* ── Regenerate choice modal ────────────────────────────────── */
.bcp-regen-choice{
  display:flex;align-items:flex-start;gap:16px;padding:18px 20px;
  background:var(--bg2);border:1px solid var(--border);border-radius:14px;
  cursor:pointer;text-align:left;font-family:inherit;width:100%;
  transition:background .15s,border-color .15s;
}
.bcp-regen-choice:hover{background:var(--bg3);border-color:var(--b2);}
.bcp-regen-ai:hover{border-color:color-mix(in srgb, var(--green) 40%, transparent);background:color-mix(in srgb, var(--green) 4%, transparent);}
.bcp-regen-choice-icon{
  width:36px;height:36px;border-radius:10px;display:flex;align-items:center;
  justify-content:center;flex-shrink:0;background:var(--bg3);color:var(--muted);
}
.bcp-regen-ai .bcp-regen-choice-icon{background:color-mix(in srgb, var(--green) 10%, transparent);color:var(--green);}
.bcp-regen-choice-body{flex:1;}
.bcp-regen-choice-title{font-size:14px;font-weight:700;color:var(--charcoal);margin-bottom:4px;}
.bcp-regen-choice-sub{font-size:12.5px;color:var(--muted);line-height:1.5;}

/* ── Section wrapper ──────────────────────────────────────────── */
.bcp-section{margin-bottom:40px;}
.bcp-section-half{flex:1;min-width:240px;}
.bcp-row-2{display:flex;gap:20px;margin-bottom:40px;flex-wrap:wrap;}
.bcp-row-2 .bcp-section{margin-bottom:0;}
.bcp-section-hd{
  display:flex;align-items:center;justify-content:space-between;
  margin-bottom:16px;
}
.bcp-section-label{
  font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--muted);
}
.bcp-section-act{
  font-size:12px;font-weight:600;color:var(--muted);
  background:none;border:none;cursor:pointer;font-family:inherit;
  padding:4px 0;transition:color .15s;
}
.bcp-section-act:hover{color:var(--charcoal);}
.bcp-empty-field{font-size:13px;color:var(--muted);font-style:italic;}

/* ── Color System ─────────────────────────────────────────────── */
.bcp-colors{display:flex;gap:12px;flex-wrap:wrap;}
.bcp-color-chip{
  display:flex;flex-direction:column;border-radius:14px;overflow:hidden;
  border:1px solid var(--border);cursor:pointer;transition:transform .15s,border-color .15s;
  min-width:120px;flex:1;max-width:160px;
}
.bcp-color-chip:hover{transform:translateY(-2px);border-color:var(--b2);}
.bcp-color-swatch{
  height:90px;display:flex;align-items:flex-end;padding:8px 10px;
  transition:height .15s;
}
.bcp-color-hex{font-size:10.5px;font-weight:700;letter-spacing:.04em;opacity:.85;}
.bcp-color-meta{padding:10px 11px;background:var(--bg2);}
.bcp-color-role{font-size:11.5px;font-weight:600;color:var(--charcoal);margin-bottom:3px;}
.bcp-color-exp{font-size:10.5px;color:var(--muted);line-height:1.4;}
.bcp-color-add{
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;
  min-width:80px;max-width:80px;height:130px;border:1.5px dashed var(--border);
  border-radius:14px;cursor:pointer;color:var(--muted);font-size:11.5px;font-weight:600;
  transition:border-color .15s,color .15s;
}
.bcp-color-add:hover{border-color:var(--b2);color:var(--charcoal);}

/* ── Typography ───────────────────────────────────────────────── */
.bcp-typo-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;}
@media(max-width:540px){.bcp-typo-grid{grid-template-columns:1fr;}}
.bcp-typo-card{
  background:var(--bg2);border:1px solid var(--border);
  border-radius:14px;padding:22px 20px;
}
.bcp-typo-role{
  font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:var(--muted);margin-bottom:12px;
}
.bcp-typo-sample{
  font-size:22px;color:var(--charcoal);line-height:1.2;margin-bottom:10px;
  font-weight:400;
}
.bcp-typo-name{font-size:13px;font-weight:700;color:var(--charcoal);margin-bottom:6px;}
.bcp-typo-reason{font-size:12px;color:var(--muted);line-height:1.5;}

/* ── Brand Personality chips ──────────────────────────────────── */
.bcp-personality{display:flex;gap:10px;flex-wrap:wrap;}
.bcp-chip{
  padding:11px 22px;border-radius:30px;font-size:14px;font-weight:700;
  letter-spacing:-.2px;border:1px solid;
}
.bcp-chip-a{background:color-mix(in srgb, var(--green) 10%, transparent);border-color:color-mix(in srgb, var(--green) 30%, transparent);color:var(--green);}
.bcp-chip-b{background:rgba(167,139,250,.1);border-color:rgba(167,139,250,.3);color:#A78BFA;}
.bcp-chip-c{background:rgba(59,130,246,.1);border-color:rgba(59,130,246,.3);color:#3B82F6;}
.bcp-chip-d{background:rgba(245,158,11,.1);border-color:rgba(245,158,11,.3);color:#F59E0B;}

/* ── Tone of Voice quote ──────────────────────────────────────── */
.bcp-tone-card{
  background:var(--bg2);border:1px solid var(--border);border-radius:14px;
  padding:22px 22px 22px 28px;border-left:3px solid var(--green);
}
.bcp-quote{
  font-family:'Geist',system-ui,-apple-system,sans-serif;font-size:14px;font-style:normal;font-weight:400;
  color:var(--charcoal);line-height:1.65;
}

/* ── Positioning statement ────────────────────────────────────── */
.bcp-statement-card{
  background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:24px 28px;
}
.bcp-statement{
  font-family:'Geist',system-ui,-apple-system,sans-serif;font-size:14px;font-weight:400;
  color:var(--charcoal);line-height:1.65;letter-spacing:-.01em;
}

/* ── Target Audience ──────────────────────────────────────────── */
.bcp-audience-card{
  background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:20px 22px;
}
.bcp-audience-text{font-size:14px;color:var(--charcoal);line-height:1.65;}

/* ── Visual Direction ─────────────────────────────────────────── */
.bcp-visual-block{
  background:var(--bg2);border:1px solid var(--border);border-radius:14px;
  padding:20px 22px;margin-bottom:14px;
}
.bcp-visual-desc{font-size:14px;color:var(--charcoal);line-height:1.65;}

/* ── Moodboard ────────────────────────────────────────────────── */
.bcp-moodboard{
  border:1.5px dashed var(--border);border-radius:14px;padding:18px 20px;
}
.bcp-mood-label{
  font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  color:var(--muted);margin-bottom:14px;
}
.bcp-mood-grid{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px;}
.bcp-mood-item{position:relative;width:90px;height:90px;border-radius:10px;overflow:hidden;}
.bcp-mood-img{width:100%;height:100%;object-fit:cover;}
.bcp-mood-remove{
  position:absolute;top:4px;right:4px;background:rgba(0,0,0,.6);color:#fff;
  border:none;border-radius:50%;width:18px;height:18px;font-size:10px;cursor:pointer;
  display:flex;align-items:center;justify-content:center;line-height:1;padding:0;
}
.bcp-mood-add{
  display:flex;align-items:center;gap:7px;font-size:13px;font-weight:600;
  color:var(--muted);background:none;border:none;cursor:pointer;font-family:inherit;
  transition:color .15s;padding:0;
}
.bcp-mood-add:hover{color:var(--charcoal);}

/* ── Logo System ──────────────────────────────────────────────── */
.bcp-logos{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:16px;}
.bcp-logo-slot{
  display:flex;flex-direction:column;border:1px solid var(--border);
  border-radius:14px;overflow:hidden;min-width:160px;flex:1;max-width:220px;
}
.bcp-logo-preview{
  height:110px;background:var(--bg2);display:flex;align-items:center;
  justify-content:center;cursor:pointer;position:relative;overflow:hidden;
}
.bcp-logo-img{max-width:80%;max-height:80%;object-fit:contain;}
.bcp-logo-overlay{
  position:absolute;inset:0;background:rgba(0,0,0,.5);display:flex;
  align-items:center;justify-content:center;font-size:12px;font-weight:600;
  color:#fff;opacity:0;transition:opacity .2s;
}
.bcp-logo-preview:hover .bcp-logo-overlay{opacity:1;}
.bcp-logo-upload{
  height:110px;background:var(--bg2);display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:7px;cursor:pointer;
  color:var(--muted);font-size:12px;font-weight:600;transition:background .15s;
}
.bcp-logo-upload:hover{background:var(--bg3);}
.bcp-logo-footer{padding:12px 14px;}
.bcp-logo-name{font-size:12.5px;font-weight:700;color:var(--charcoal);margin-bottom:3px;}
.bcp-logo-hint{font-size:11px;color:var(--muted);line-height:1.4;margin-bottom:8px;}
.bcp-logo-remove{
  font-size:11px;color:var(--muted);background:none;border:none;cursor:pointer;
  padding:0;font-family:inherit;transition:color .15s;
}
.bcp-logo-remove:hover{color:#EF4444;}
.bcp-logo-desc-block{
  background:var(--bg2);border:1px solid var(--border);border-radius:12px;padding:14px 16px;
}
.bcp-logo-desc-lbl{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:6px;}
.bcp-logo-desc-txt{font-size:13px;color:var(--charcoal);line-height:1.55;}

/* ── Quick row at bottom ──────────────────────────────────────── */
.bcp-quick-row{margin-top:12px;}
.bcp-quick-card{
  display:flex;align-items:center;gap:14px;padding:16px 18px;
  background:var(--bg2);border:1px solid var(--border);border-radius:14px;
  cursor:pointer;transition:background .15s,border-color .15s;
}
.bcp-quick-card:hover{background:var(--bg3);border-color:var(--b2);}
.bcp-quick-ico{
  width:36px;height:36px;border-radius:10px;background:var(--bg3);
  display:flex;align-items:center;justify-content:center;color:var(--muted);flex-shrink:0;
}
.bcp-quick-body{flex:1;}
.bcp-quick-title{font-size:13.5px;font-weight:600;color:var(--charcoal);}
.bcp-quick-sub{font-size:12px;color:var(--muted);margin-top:2px;}
.cf-char-counter.cf-char-over{ color:#EF4444;font-weight:600; }


/* ══════════════════════════════════════════════════════════════
   PUBLIC PAGES — Landing · Login · Signup · Plan
   All styles scoped to body.public-page or prefixed .lp- .au- .pl-
   ══════════════════════════════════════════════════════════════ */

/* Override app body rules for public pages */
body.public-page {
  display: block; /* override app body's display:flex — public pages need normal block flow for vertical scroll */
  height: auto;
  min-height: 100vh;
  overflow-x: hidden;
  overflow-y: auto;
  display: block;
}

/* ═══════════════════════════════════════════════════════════════
   ORIVEN — Landing Page
   ═══════════════════════════════════════════════════════════════ */

:root {
  --lp-bg:       #0A0A0A;
  --lp-bg2:      #111111;
  --lp-bg3:      #161616;
  --lp-surface:  #141414;
  --lp-border:   rgba(255,255,255,.08);
  --lp-border2:  rgba(255,255,255,.05);
  --lp-green:    var(--green);
  --lp-green-d:  color-mix(in srgb, var(--green) 10%, transparent);
  --lp-white:    #F0F0F0;
  --lp-muted:    rgba(240,240,240,.45);
  --lp-muted2:   rgba(240,240,240,.25);
  --lp-r:        16px;
  --lp-rl:       20px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

/* ── Scene stage ────────────────────────────────────────────── */
#lp-stage {
  position: fixed;
  inset: 0;
  background: var(--lp-bg);
  overflow: hidden;
  z-index: 1;
}
.lp-scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  will-change: transform, opacity;
  overflow: hidden;
}
.lp-scene.is-current {
  opacity: 1;
  pointer-events: auto;
}
/* Scene-level inner wrapper */
.lp-si {
  width: 100%;
  max-width: 1200px;
  padding: 0 80px;
  margin: 0 auto;
}

/* ── Progress dots (right edge) ─────────────────────────────── */
#lp-progress {
  position: fixed;
  right: 28px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
}
.lp-pg-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(255,255,255,.15);
  cursor: pointer;
  transition: background .25s, height .25s, border-radius .25s;
}
.lp-pg-dot.is-on {
  background: var(--lp-green);
  height: 18px;
  border-radius: 3px;
}

body.public-page {
  background: var(--lp-bg);
  color: var(--lp-white);
  font-family: 'Geist', system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }

/* ── Utilities ─────────────────────────────────────────────────── */
.lp-container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 28px;
}
.lp-section-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--lp-muted);
  margin-bottom: 18px;
}
.lp-section-eyebrow-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--lp-green);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 18%, transparent);
  flex-shrink: 0;
}
.lp-section-title {
  font-family: 'Instrument Serif', serif;
  font-size: clamp(32px, 4vw, 48px);
  font-weight: 400;
  color: var(--lp-white);
  letter-spacing: -1.2px;
  line-height: 1.08;
  margin-bottom: 16px;
}
.lp-section-title em { font-style: italic; color: var(--lp-green); }
.lp-section-sub {
  font-size: 16px;
  color: var(--lp-muted);
  line-height: 1.7;
  max-width: 560px;
}

/* ── Buttons ───────────────────────────────────────────────────── */
.lp-cta-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  background: var(--lp-green);
  color: #000;
  font-size: 14px;
  font-weight: 700;
  border-radius: 40px;
  border: none;
  cursor: pointer;
  transition: background .18s, transform .18s, box-shadow .18s;
  letter-spacing: -.1px;
  white-space: nowrap;
  font-family: inherit;
}
button.lp-cta-btn { cursor:pointer; border:none; }
.lp-cta-btn:hover {
  background: var(--gm);
  transform: translateY(-1px);
  box-shadow: 0 8px 28px color-mix(in srgb, var(--green) 28%, transparent);
}
.lp-cta-btn-lg { padding: 15px 32px; font-size: 15px; }
.lp-ghost-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 12px 20px;
  background: transparent;
  color: var(--lp-muted);
  font-size: 14px;
  font-weight: 500;
  border-radius: 40px;
  border: 1px solid var(--lp-border);
  cursor: pointer;
  transition: color .18s, border-color .18s, background .18s;
  font-family: inherit;
  white-space: nowrap;
}
.lp-ghost-btn:hover { color: var(--lp-white); border-color: rgba(255,255,255,.18); background: rgba(255,255,255,.04); }

/* ── Navigation ────────────────────────────────────────────────── */
.lp-nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 200;
  height: 64px;
  display: flex;
  align-items: center;
  background: rgba(10,10,10,.82);
  /* Final Polish — was blur(20px). A position:fixed element blurring
     everything scrolling underneath it inside a custom-scroll container
     is a real, well-documented cause of scroll compositing cost/jank,
     independent of any JS scroll listener. Backdrop blur itself is kept
     (not removed -- it's part of the intended look), just reduced to a
     noticeably cheaper radius; still reads as frosted glass. */
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255,255,255,.06);
  transition: background .3s, border-color .3s;
}
.lp-nav.lp-nav-scrolled {
  background: rgba(10,10,10,.95);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--lp-border);
}
.lp-nav-inner {
  max-width: 1320px; /* Redesign: was 1100px — wider desktop layout */
  margin: 0 auto;
  padding: 0 28px;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0;
}
.lp-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  margin-right: auto;
}
.lp-logo-img { width: 52px; height: 52px; object-fit: contain; }
.lp-logo-txt {
  font-size: 16px;
  font-weight: 700;
  color: var(--lp-white);
  letter-spacing: -.3px;
}
.lp-nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}
.lp-nav-link {
  padding: 7px 13px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  color: var(--lp-muted);
  transition: color .15s, background .15s;
}
.lp-nav-link:hover { color: var(--lp-white); background: rgba(255,255,255,.05); }
.lp-nav-right {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
}
.lp-nav-login {
  font-size: 13px;
  font-weight: 500;
  color: var(--lp-muted);
  padding: 7px 13px;
  border-radius: 8px;
  transition: color .15s;
}
.lp-nav-login:hover { color: var(--lp-white); }
.lp-nav .lp-cta-btn { padding: 9px 20px; font-size: 13px; }
.lp-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  margin-left: 8px;
}
.lp-hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--lp-white);
  border-radius: 2px;
  transition: transform .2s, opacity .2s;
}
.lp-hamburger.open span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
.lp-hamburger.open span:nth-child(2) { opacity: 0; }
.lp-hamburger.open span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }
.lp-mobile-menu {
  position: fixed;
  inset: 0;
  background: rgba(8,8,8,.98);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  z-index: 400;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-6%);
  transition: opacity .3s ease, visibility .3s ease, transform .38s cubic-bezier(.16,1,.3,1);
}
.lp-mobile-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

/* ── Hero ──────────────────────────────────────────────────────── */
.lp-hero {
  padding: 0 80px;
  position: relative;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.lp-hero::before {
  content: '';
  position: absolute;
  top: -20%; left: 50%;
  transform: translateX(-50%);
  width: 800px; height: 600px;
  background: radial-gradient(ellipse, color-mix(in srgb, var(--green) 7%, transparent) 0%, transparent 70%);
  pointer-events: none;
}
.lp-hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--lp-muted);
  margin-bottom: 28px;
  padding: 6px 14px;
  border: 1px solid var(--lp-border);
  border-radius: 40px;
  background: rgba(255,255,255,.03);
}
.lp-hero-eyebrow-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--lp-green);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 20%, transparent);
  animation: lpPulse 2.5s ease-in-out infinite;
  flex-shrink: 0;
}
.lp-hero-h1 {
  font-family: 'Instrument Serif', serif;
  font-size: clamp(44px, 7vw, 84px);
  font-weight: 400;
  color: var(--lp-white);
  letter-spacing: -2.5px;
  line-height: 1.02;
  margin-bottom: 24px;
  max-width: 860px;
  margin-left: auto;
  margin-right: auto;
}
.lp-hero-h1 em { font-style: italic; color: var(--lp-green); }
.lp-hero-sub {
  font-size: 18px;
  color: var(--lp-muted);
  line-height: 1.7;
  max-width: 520px;
  margin: 0 auto 36px;
}
.lp-hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}
.lp-hero-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 12px;
  color: var(--lp-muted2);
}
.lp-note-dot { opacity: .35; }

/* ── Browser Frame Mockup ──────────────────────────────────────── */
.lp-mockup-section {
  padding: 20px 28px 100px;
  position: relative;
}
.lp-mockup-section::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 300px;
  background: linear-gradient(to bottom, transparent, var(--lp-bg));
  pointer-events: none;
}
.lp-browser {
  max-width: 940px;
  margin: 0 auto;
  border-radius: 14px;
  border: 1px solid var(--lp-border);
  background: var(--lp-bg2);
  box-shadow: 0 40px 120px rgba(0,0,0,.7), 0 0 0 1px rgba(255,255,255,.04);
  overflow: hidden;
  transform: perspective(1200px) rotateX(3deg);
  transform-origin: top center;
}
.lp-browser-chrome {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 16px;
  background: var(--lp-bg3);
  border-bottom: 1px solid var(--lp-border);
}
.lp-browser-dots { display: flex; gap: 6px; }
.lp-browser-dots span {
  width: 10px; height: 10px;
  border-radius: 50%;
}
.lp-browser-dots span:nth-child(1) { background: #FF5F57; }
.lp-browser-dots span:nth-child(2) { background: #FEBC2E; }
.lp-browser-dots span:nth-child(3) { background: #28C840; }
.lp-browser-url {
  flex: 1;
  margin: 0 auto;
  max-width: 280px;
  background: rgba(255,255,255,.06);
  border-radius: 6px;
  padding: 4px 12px;
  font-size: 11px;
  color: var(--lp-muted2);
  text-align: center;
  font-family: 'Geist Mono', monospace;
  letter-spacing: .02em;
}
/* App UI inside browser */
.lp-app-ui {
  display: grid;
  grid-template-columns: 52px 1fr;
  height: 420px;
  overflow: hidden;
}
.lp-app-sidebar {
  background: var(--lp-bg2);
  border-right: 1px solid var(--lp-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 14px 0;
  gap: 6px;
}
.lp-sb-logo {
  width: 28px; height: 28px;
  border-radius: 8px;
  background: var(--lp-green);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
}
.lp-sb-logo svg { width: 14px; height: 14px; stroke: #000; fill: none; stroke-width: 2; }
.lp-sb-icon {
  width: 34px; height: 34px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,.28);
  transition: background .15s, color .15s;
}
.lp-sb-icon svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
.lp-sb-icon.active { background: color-mix(in srgb, var(--green) 12%, transparent); color: var(--lp-green); }
.lp-sb-sep { flex: 1; }
/* Dashboard content */
.lp-app-content { padding: 20px; display: flex; flex-direction: column; gap: 14px; overflow: hidden; }
.lp-app-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.lp-app-title-row { display: flex; flex-direction: column; gap: 3px; }
.lp-app-eyebrow {
  display: flex; align-items: center; gap: 6px;
  font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: rgba(255,255,255,.3);
}
.lp-app-eyebrow-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--lp-green); flex-shrink: 0; }
.lp-app-h { font-family: 'Instrument Serif', serif; font-size: 22px; color: var(--lp-white); letter-spacing: -1px; font-weight: 400; }
.lp-app-h em { font-style: italic; color: var(--lp-green); }
.lp-app-level-badge {
  padding: 4px 10px;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  background: color-mix(in srgb, var(--green) 6%, transparent);
  font-size: 10px;
  font-weight: 600;
  color: var(--lp-muted);
  letter-spacing: .04em;
}
/* Metric cards row */
.lp-app-metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.lp-app-metric {
  background: rgba(255,255,255,.03);
  border: 1px solid var(--lp-border);
  border-radius: 12px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.lp-app-metric-val {
  font-family: 'Instrument Serif', serif;
  font-size: 26px;
  color: var(--lp-white);
  letter-spacing: -1px;
  line-height: 1;
}
.lp-app-metric-lbl { font-size: 10px; color: rgba(255,255,255,.3); font-weight: 500; letter-spacing: .02em; }
.lp-app-metric-bar { height: 2px; background: var(--lp-border); border-radius: 2px; overflow: hidden; margin-top: 4px; }
.lp-app-metric-fill { height: 100%; background: var(--lp-green); border-radius: 2px; }
/* Quick cards row */
.lp-app-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.lp-app-card {
  background: rgba(255,255,255,.03);
  border: 1px solid var(--lp-border);
  border-radius: 10px;
  padding: 12px 13px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.lp-app-card-ico {
  width: 28px; height: 28px;
  border-radius: 8px;
  background: var(--lp-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.lp-app-card-ico svg { width: 12px; height: 12px; fill: none; stroke: rgba(255,255,255,.4); stroke-width: 1.6; stroke-linecap: round; }
.lp-app-card-body { min-width: 0; }
.lp-app-card-ttl { font-size: 11px; font-weight: 600; color: var(--lp-white); letter-spacing: -.1px; }
.lp-app-card-sub { font-size: 9px; color: rgba(255,255,255,.3); }
/* Activity feed */
.lp-app-feed { display: flex; flex-direction: column; gap: 6px; }
.lp-app-feed-hd { font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.22); margin-bottom: 4px; }
.lp-app-feed-item {
  display: flex; align-items: center; gap: 8px;
  padding: 7px 10px;
  background: rgba(255,255,255,.02);
  border: 1px solid rgba(255,255,255,.04);
  border-radius: 8px;
}
.lp-app-feed-dot { width: 5px; height: 5px; border-radius: 50%; flex-shrink: 0; }
.lp-app-feed-txt { font-size: 10px; color: rgba(255,255,255,.4); flex: 1; }
.lp-app-feed-time { font-size: 9px; color: rgba(255,255,255,.2); }

/* ═══════════════════════════════════════════════════════════════
   SCENE 1 — HERO (two-column)
   ═══════════════════════════════════════════════════════════════ */
.lp-s-hero-left { max-width: 520px; }
.lp-s-eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
  color: var(--lp-muted); margin-bottom: 28px;
  padding: 6px 14px; border: 1px solid var(--lp-border); border-radius: 40px;
  background: rgba(255,255,255,.03);
}
.lp-s-eyebrow-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--lp-green); }
.lp-s-h1 {
  font-size: clamp(38px, 4.5vw, 60px);
  font-weight: 700; color: var(--lp-white);
  line-height: 1.08; letter-spacing: -2px; margin-bottom: 22px;
}
.lp-s-h1 em { font-style: italic; color: var(--lp-green); font-family: 'Instrument Serif', serif; font-weight: 400; }
.lp-s-sub { font-size: 16px; color: var(--lp-muted); line-height: 1.7; margin-bottom: 36px; max-width: 440px; }
.lp-s-actions { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 20px; }
.lp-s-note { font-size: 12px; color: rgba(255,255,255,.22); display: flex; gap: 10px; align-items: center; }

/* Hero right: app preview */
.lp-s-hero-right { flex: 1; min-width: 0; }
.lp-s-prev-frame {
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,.08);
  overflow: hidden;
  background: #111;
  box-shadow: 0 40px 80px rgba(0,0,0,.5), 0 0 0 1px rgba(255,255,255,.04);
  transform: perspective(1200px) rotateY(-4deg) rotateX(2deg);
  transition: transform .5s ease;
}
.lp-s-prev-frame:hover { transform: perspective(1200px) rotateY(-1deg) rotateX(0deg); }
.lp-s-prev-body {
  display: flex;
  height: 360px;
}
.lp-s-prev-sidebar {
  width: 52px;
  background: #0d0d0d;
  border-right: 1px solid rgba(255,255,255,.06);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 0;
  gap: 6px;
}
.lp-s-sb-logo {
  width: 28px; height: 28px;
  background: var(--lp-green);
  border-radius: 7px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 12px;
}
.lp-s-sb-dot {
  width: 28px; height: 28px; border-radius: 7px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.06);
  display: flex; align-items: center; justify-content: center;
}
.lp-s-sb-dot svg { width: 13px; height: 13px; opacity: .3; }
.lp-s-sb-dot.active { background: color-mix(in srgb, var(--green) 10%, transparent); border-color: color-mix(in srgb, var(--green) 20%, transparent); }
.lp-s-sb-dot.active svg { opacity: .8; }

.lp-s-prev-main {
  flex: 1; padding: 18px 16px; overflow: hidden;
}
.lp-s-prev-hdr { font-size: 11px; color: rgba(255,255,255,.3); margin-bottom: 14px; letter-spacing: .04em; }
.lp-s-tool-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;
}
.lp-s-tool {
  padding: 12px 10px;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 10px;
  display: flex; flex-direction: column; gap: 5px;
}
.lp-s-tool-ico {
  width: 26px; height: 26px; border-radius: 7px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 2px;
}
.lp-s-tool-ico svg { width: 12px; height: 12px; }
.lp-s-tool-name { font-size: 10px; font-weight: 600; color: rgba(255,255,255,.7); letter-spacing: -.1px; }
.lp-s-tool-sub { font-size: 9px; color: rgba(255,255,255,.28); }
.lp-s-prev-pulse {
  margin-top: 14px;
  padding: 10px 12px;
  background: color-mix(in srgb, var(--green) 5%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 12%, transparent);
  border-radius: 10px;
  display: flex; align-items: center; gap: 10px;
}
.lp-s-pulse-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--lp-green);
  flex-shrink: 0;
  animation: lpPulse 2s infinite;
}
@keyframes lpPulse { 0%,100%{opacity:1} 50%{opacity:.35} }
.lp-s-pulse-txt { font-size: 10px; color: color-mix(in srgb, var(--green) 60%, transparent); }

/* ═══════════════════════════════════════════════════════════════
   SCENE 2 — AI SYSTEMS
   ═══════════════════════════════════════════════════════════════ */
.lp-s-ai {
  width: 100%; max-width: 1100px; padding: 0 80px; margin: 0 auto;
  display: grid; grid-template-columns: 1fr auto 1fr; gap: 0; align-items: center;
}
.lp-s-ai-eyebrow {
  font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
  color: var(--lp-muted); margin-bottom: 20px; text-align: center;
}
.lp-s-ai-title {
  font-size: clamp(34px, 4vw, 52px); font-weight: 700; color: var(--lp-white);
  letter-spacing: -2px; line-height: 1.06; margin-bottom: 12px; text-align: center;
}
.lp-s-ai-title em { font-style: italic; color: var(--lp-green); font-family: 'Instrument Serif', serif; font-weight: 400; }
.lp-s-ai-sub { font-size: 15px; color: var(--lp-muted); text-align: center; max-width: 420px; margin: 0 auto; }
.lp-s-ai-hdr { grid-column: 1 / -1; text-align: center; margin-bottom: 64px; }

/* Providers column */
.lp-s-ai-providers { display: flex; flex-direction: column; gap: 12px; }
.lp-s-ai-provider {
  padding: 14px 20px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 14px;
  background: rgba(255,255,255,.03);
  display: flex; align-items: center; gap: 12px;
  backdrop-filter: blur(8px);
  transition: border-color .3s, background .3s;
}
.lp-s-ai-provider:hover { border-color: color-mix(in srgb, var(--green) 20%, transparent); background: color-mix(in srgb, var(--green) 4%, transparent); }
.lp-s-ai-pico {
  width: 34px; height: 34px; border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 800; letter-spacing: -.5px;
  flex-shrink: 0;
}
.lp-s-ai-pname { font-size: 13px; font-weight: 600; color: var(--lp-white); letter-spacing: -.2px; }
.lp-s-ai-psub { font-size: 10px; color: var(--lp-muted); margin-top: 1px; }

/* Center ORIVEN hub */
.lp-s-ai-center {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 0 40px; gap: 16px;
}
.lp-s-ai-hub {
  width: 88px; height: 88px; border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--green) 18%, transparent) 0%, color-mix(in srgb, var(--green) 4%, transparent) 60%, transparent 100%);
  border: 1px solid color-mix(in srgb, var(--green) 25%, transparent);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 0 40px color-mix(in srgb, var(--green) 12%, transparent);
}
.lp-s-ai-hub img { width: 44px; height: 44px; object-fit: contain; }
.lp-s-ai-arrow {
  width: 1px; height: 24px;
  background: linear-gradient(to bottom, color-mix(in srgb, var(--green) 30%, transparent), transparent);
}
.lp-s-ai-arrow.flip { transform: rotate(180deg); }

/* Outputs column */
