  overflow-y: auto;
}
.lp-scene-footer .lp-footer {
  width: 100%;
  margin: auto 0;
}

/* ── [data-in] entrance animation targets ────────────────────── */
[data-in] {
  opacity: 0;
}

/* ── Mobile landing: each scene must fit within the viewport ─── */
/* No internal scrolling. Users swipe between scenes, not inside them. */
/* If content doesn't fit, we reduce spacing/fonts or hide non-essentials. */
@media (max-width: 820px) {
  /* Scenes lock to viewport — no internal scroll */
  .lp-scene {
    overflow: hidden;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    padding: 60px 0 0;
  }

  /* ── Hero ──────────────────────────────────────────────────── */
  .lp-hero { grid-template-columns: 1fr; gap: 0; padding: 16px 20px 0; align-items: flex-start; }
  .lp-s-hero-right { display: none; }
  .lp-s-eyebrow { margin-bottom: 14px; font-size: 10px; padding: 5px 11px; }
  .lp-s-h1 { font-size: clamp(26px, 7.5vw, 42px); letter-spacing: -1.8px; margin-bottom: 10px; }
  .lp-s-sub { font-size: 14px; line-height: 1.5; margin-bottom: 18px; }
  .lp-s-actions { gap: 10px; flex-wrap: wrap; }
  .lp-ghost-btn { display: none; }
  .lp-s-note { margin-top: 12px; font-size: 11px; }

  /* ── AI Systems ─────────────────────────────────────────────── */
  .lp-s-ai { grid-template-columns: 1fr; padding: 0 20px; gap: 18px; }
  .lp-s-ai-center { flex-direction: row; padding: 0; gap: 10px; }
  .lp-s-ai-hub { width: 48px; height: 48px; }
  .lp-s-ai-hdr { margin-bottom: 20px; }
  .lp-s-ai-providers { gap: 6px; }
  .lp-s-ai-provider { padding: 8px 11px; }

  /* ── Testimonials ────────────────────────────────────────────── */
  .lp-s-testi { padding: 0 20px; }
  .lp-s-testi-hdr { margin-bottom: 18px; }
  .lp-tc-arrow { display: none; }
  .lp-tc-card { width: calc(100% / 5); }
  .lp-s-testi-grid { grid-template-columns: 1fr; gap: 10px; }

  /* ── Pricing — compact 3-column, no feature lists ────────────── */
  .lp-s-pricing { padding: 0 14px; width: 100%; max-width: none; }
  .lp-s-pricing-hdr { margin-bottom: 14px; text-align: left; }
  .lp-s-pricing-eyebrow { margin-bottom: 6px; }
  .lp-s-pricing-title { font-size: clamp(20px, 5.5vw, 28px); }
  .lp-s-pricing-sub { display: none; }
  .lp-pricing-grid { grid-template-columns: repeat(2, 1fr); gap: 6px; }
  .lp-plan { padding: 14px 10px; }
  .lp-plan-tag { font-size: 8px; padding: 2px 8px; top: -8px; }
  .lp-plan-name { font-size: 10px; letter-spacing: .06em; margin-bottom: 6px; }
  .lp-plan-price { margin-bottom: 8px; }
  .lp-plan-price-num { font-size: 22px; letter-spacing: -1px; }
  .lp-plan-price-period { font-size: 10px; }
  .lp-plan-desc { display: none; }
  .lp-plan-features { display: none; }
  .lp-plan-divider { margin-bottom: 8px; }
  .lp-plan-cta { padding: 9px 6px; font-size: 11px; }

  /* ── FAQ — first 3 questions only, no open answers ───────────── */
  .lp-s-faq { padding: 0 20px; width: 100%; max-width: none; }
  .lp-s-faq-hdr { margin-bottom: 14px; }
  .lp-s-faq-title { font-size: clamp(20px, 5.5vw, 28px); }
  .lp-faq-item:nth-child(n+4) { display: none; }
  .lp-faq-a { display: none !important; }
  .lp-faq-q { padding: 11px 0; font-size: 13px; }

  /* ── About ───────────────────────────────────────────────────── */
  .lp-s-about { grid-template-columns: 1fr; gap: 22px; padding: 0 20px; }

  /* ── Process ─────────────────────────────────────────────────── */
  .lp-s-proc { padding: 0 20px; }
  .lp-s-proc-eyebrow { margin-bottom: 10px; }
  .lp-s-proc-title { font-size: clamp(22px, 6vw, 30px); margin-bottom: 20px; }
  .lp-s-proc-steps { grid-template-columns: 1fr; gap: 10px; }
  .lp-s-proc-step { border-top: 1px solid rgba(255,255,255,.08); padding-top: 16px; }
  .lp-s-proc-num { font-size: 30px; margin-bottom: 8px; opacity: .45; }
  .lp-s-proc-step-h { font-size: 15px; margin-bottom: 0; }
  .lp-s-proc-step-p { display: none; }
  .lp-proc-step { height: auto; padding: 56px 0; }

  /* ── Contact + Footer ────────────────────────────────────────── */
  /* Suppress inner wrap's own scroll so outer scene overflow:hidden wins */
  .lp-s-contact-wrap { overflow: hidden; }
  .lp-s-contact-wrap .lp-s-contact { padding: 28px 20px 20px; min-height: 0; flex: none; }
  .lp-s-contact-title { font-size: clamp(26px, 7vw, 40px); margin-bottom: 10px; }
  .lp-s-contact-eyebrow { margin-bottom: 10px; }
  .lp-s-contact-sub { font-size: 13px; margin-bottom: 18px; }
  .lp-s-contact-actions { flex-direction: column; align-items: center; gap: 10px; }
  /* Compact footer */
  .lp-footer-top { padding: 16px 0 12px; }
  .lp-footer-grid { grid-template-columns: 1fr 1fr; gap: 18px; padding: 0 20px; }
  .lp-footer-brand { grid-column: 1 / -1; }
  .lp-footer-tagline { display: none; }
  .lp-footer-bottom { padding: 10px 20px; }
  .lp-footer-sep { display: none; }
  .lp-footer-copy:not(:first-child) { display: none; }

  /* ── General ─────────────────────────────────────────────────── */
  .lp-s-prev-frame { transform: scale(1); }
  #lp-progress { display: none; }
}

/* ── Features ──────────────────────────────────────────────────── */
.lp-features {
  padding: 100px 28px;
  background: var(--lp-bg2);
  border-top: 1px solid var(--lp-border);
