.lp-how-step-title { font-size: 16px; font-weight: 700; color: var(--lp-white); letter-spacing: -.3px; }
.lp-how-step-desc { font-size: 13px; color: var(--lp-muted); line-height: 1.65; max-width: 240px; margin: 0 auto; }

