}
.lp-plan-tag-agency {
  background: rgba(160,160,200,.18);
  color: rgba(200,200,230,.75);
  border: 1px solid rgba(160,160,200,.25);
}
.lp-plan-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--lp-muted);
  letter-spacing: .06em;
  text-transform: uppercase;
  margin-bottom: 10px;
}
.lp-plan-price {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 4px;
}
.lp-plan-price-num {
