  font-size: 38px;
  color: var(--lp-white);
  letter-spacing: -1.5px;
  line-height: 1;
}
.lp-plan-price-period { font-size: 12px; color: var(--lp-muted); }
.lp-plan-desc { font-size: 12px; color: var(--lp-muted); line-height: 1.5; margin-bottom: 14px; }
.lp-plan-divider { height: 1px; background: var(--lp-border); margin-bottom: 14px; }
.lp-plan-features { list-style: none; padding: 0; margin: 0 0 16px; display: flex; flex-direction: column; gap: 7px; flex: 1; }
.lp-plan-feat {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 12px;
  color: var(--lp-muted);
  line-height: 1.4;
}
.lp-plan-feat-check {
  width: 14px; height: 14px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--green) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 18%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
}
.lp-plan-feat-check svg { width: 7px; height: 7px; fill: none; stroke: var(--lp-green); stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
.lp-plan-cta { width: 100%; justify-content: center; margin-top: auto; }
.lp-plan-cta-outline {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px;
  border-radius: 40px;
  border: 1px solid var(--lp-border);
  background: transparent;
  color: var(--lp-muted);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color .18s, color .18s, background .18s;
  font-family: inherit;
  text-decoration: none;
  margin-top: auto;
}
.lp-plan-cta-outline:hover { border-color: rgba(255,255,255,.2); color: var(--lp-white); background: rgba(255,255,255,.04); }
.lp-plan-cta-agency {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px;
  border-radius: 40px;
  border: 1px solid rgba(160,160,200,.3);
  background: rgba(160,160,200,.06);
  color: rgba(200,200,230,.7);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color .18s, color .18s, background .18s;
  font-family: inherit;
  text-decoration: none;
  margin-top: auto;
}
.lp-plan-cta-agency:hover { border-color: rgba(160,160,200,.5); color: rgba(220,220,245,.9); background: rgba(160,160,200,.1); }

/* Pricing responsive */
@media (max-width: 1100px) {
  .lp-pricing-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 580px) {
  .lp-pricing-grid { grid-template-columns: 1fr; }
  .lp-pricing { padding: 60px 20px; }
}

/* ── FAQ ───────────────────────────────────────────────────────── */
.lp-faq { padding: 100px 28px; }
.lp-faq-inner { max-width: 720px; margin: 0 auto; }
.lp-faq-hd { text-align: center; margin-bottom: 48px; }
.lp-faq-list { display: flex; flex-direction: column; gap: 0; }
.lp-faq-item {
  border-bottom: 1px solid var(--lp-border);
}
.lp-faq-item:first-child { border-top: 1px solid var(--lp-border); }
.lp-faq-q {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 0;
  cursor: pointer;
  font-size: 15px;
  font-weight: 600;
  color: var(--lp-white);
  letter-spacing: -.2px;
  user-select: none;
}
.lp-faq-q:hover { color: var(--lp-white); }
.lp-faq-icon {
  width: 22px; height: 22px;
  border-radius: 50%;
  border: 1px solid var(--lp-border);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  color: var(--lp-muted);
  transition: transform .22s, background .18s, border-color .18s;
}
.lp-faq-icon svg { width: 10px; height: 10px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.lp-faq-item.open .lp-faq-icon { transform: rotate(45deg); background: var(--lp-green-d); border-color: color-mix(in srgb, var(--green) 30%, transparent); color: var(--lp-green); }
.lp-faq-a {
  display: none;
  font-size: 14px;
  color: var(--lp-muted);
  line-height: 1.75;
  padding-bottom: 20px;
}
.lp-faq-item.open .lp-faq-a { display: block; }

/* ── Final CTA ─────────────────────────────────────────────────── */
.lp-final {
  padding: 120px 28px;
  text-align: center;
  background: var(--lp-bg2);
  border-top: 1px solid var(--lp-border);
  position: relative;
  overflow: hidden;
}
.lp-final::before {
  content: '';
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 600px; height: 400px;
  background: radial-gradient(ellipse, color-mix(in srgb, var(--green) 8%, transparent) 0%, transparent 70%);
  pointer-events: none;
}
.lp-final-h {
  font-family: 'Instrument Serif', serif;
  font-size: clamp(36px, 5vw, 60px);
  font-weight: 400;
  color: var(--lp-white);
  letter-spacing: -1.8px;
  line-height: 1.06;
  margin-bottom: 20px;
  position: relative;
}
.lp-final-h em { font-style: italic; color: var(--lp-green); }
.lp-final-sub {
  font-size: 16px;
  color: var(--lp-muted);
  max-width: 420px;
  margin: 0 auto 36px;
  line-height: 1.7;
}
.lp-final-actions { display: flex; align-items: center; justify-content: center; gap: 12px; flex-wrap: wrap; }
.lp-final-note { margin-top: 20px; font-size: 12px; color: var(--lp-muted2); }

/* ── Footer ────────────────────────────────────────────────────── */
.lp-footer { border-top: 1px solid var(--lp-border); }
.lp-footer-top { padding: 36px 0 24px; }
.lp-footer-grid { max-width: 1100px; margin: 0 auto; padding: 0 28px; display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 36px; }
.lp-footer-brand { display: flex; flex-direction: column; }
.lp-footer-logo { display: flex; align-items: center; gap: 9px; margin-bottom: 14px; }
.lp-footer-logo img { width: 32px; height: 32px; object-fit: contain; }
.lp-footer-logo-txt { font-size: 15px; font-weight: 700; color: var(--lp-white); letter-spacing: -.3px; }
.lp-footer-tagline { font-size: 13px; color: var(--lp-muted); line-height: 1.65; max-width: 210px; }
.lp-footer-col { display: flex; flex-direction: column; }
.lp-footer-col-hd { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--lp-muted2); margin-bottom: 14px; }
.lp-footer-link { font-size: 13.5px; color: var(--lp-muted); transition: color .15s; margin-bottom: 9px; width: fit-content; }
.lp-footer-link:hover { color: var(--lp-white); }
.lp-footer-bottom { border-top: 1px solid var(--lp-border2); padding: 18px 0; }
.lp-footer-bottom-inner { max-width: 1100px; margin: 0 auto; padding: 0 28px; display: flex; align-items: center; }
.lp-footer-copy { font-size: 12px; color: var(--lp-muted2); }
.lp-footer-sep { font-size: 12px; color: var(--lp-muted2); margin: 0 8px; }
.lp-footer-email { transition: color .15s; }
.lp-footer-email:hover { color: var(--lp-white); }

/* ── Animations ────────────────────────────────────────────────── */
@keyframes lpPulse {
  0%, 100% { box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 20%, transparent); }
  50%       { box-shadow: 0 0 0 5px color-mix(in srgb, var(--green) 6%, transparent); }
}
@keyframes lpFadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}
.lp-fade-in { opacity: 0; transition: opacity .6s ease, transform .6s cubic-bezier(.16,1,.3,1); transform: translateY(20px); }
.lp-fade-in.visible { opacity: 1; transform: translateY(0); }
.lp-hero-eyebrow,
.lp-hero-h1,
.lp-hero-sub,
.lp-hero-actions,
.lp-hero-note { animation: lpFadeUp .7s cubic-bezier(.16,1,.3,1) both; }
.lp-hero-eyebrow { animation-delay: .05s; }
.lp-hero-h1      { animation-delay: .12s; }
.lp-hero-sub     { animation-delay: .20s; }
.lp-hero-actions { animation-delay: .28s; }
.lp-hero-note    { animation-delay: .36s; }

/* ── Responsive ────────────────────────────────────────────────── */
@media(max-width:900px){
  .lp-nav-links { display: none; }
  .lp-hamburger { display: flex; }
  .lp-features-grid { grid-template-columns: 1fr 1fr; }
  .lp-how-steps { grid-template-columns: 1fr; gap: 40px; }
  .lp-how-steps::before { display: none; }
  .lp-about-inner { grid-template-columns: 1fr; gap: 48px; }
  .lp-testi-grid { grid-template-columns: 1fr 1fr; }
  .lp-pricing-grid { grid-template-columns: repeat(2, 1fr); }
  .lp-app-ui { height: 300px; }
  .lp-browser { transform: none; }
  .lp-footer-grid { grid-template-columns: 1fr 1fr 1fr; gap: 28px; }
}
@media(max-width:600px){
  .lp-hero { padding: 120px 20px 60px; }
  .lp-features-grid { grid-template-columns: 1fr; }
  .lp-testi-grid { grid-template-columns: 1fr; }
  .lp-about-stats-row { grid-template-columns: 1fr; }
  .lp-footer-grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .lp-footer-brand { grid-column: 1 / -1; }
  .lp-app-ui { height: 240px; }
  .lp-app-cards { grid-template-columns: 1fr 1fr; }
}

/* ═══════════════════════════════════════════════════════════════
   INTERACTIVE PREVIEW
   ═══════════════════════════════════════════════════════════════ */
.lp-preview-section { padding: 0 28px 100px; position: relative; }
.lp-preview-section::after { content:''; position:absolute; bottom:0; left:0; right:0; height:260px; background:linear-gradient(to bottom,transparent,var(--lp-bg)); pointer-events:none; }
.lp-prev-frame { max-width:940px; margin:0 auto; border-radius:14px; border:1px solid var(--lp-border); background:#0D0D0D; box-shadow:0 40px 120px rgba(0,0,0,.75),0 0 0 1px rgba(255,255,255,.04); overflow:hidden; transform:perspective(1200px) rotateX(2deg); transform-origin:top center; }
.lp-prev-chrome { display:flex; align-items:center; gap:12px; padding:10px 16px; background:#0A0A0A; border-bottom:1px solid var(--lp-border); }
.lp-prev-app { display:grid; grid-template-columns:178px 1fr; height:480px; }

/* Sidebar */
.lp-prev-sidebar { background:#0D0D0D; border-right:1px solid var(--lp-border); display:flex; flex-direction:column; padding:14px 10px; }
.lp-prev-sb-top { margin-bottom:20px; padding-left:4px; }
.lp-prev-sb-logo { display:flex; align-items:center; gap:8px; }
.lp-prev-nav { display:flex; flex-direction:column; gap:2px; flex:1; }
.lp-prev-nav-item { display:flex; align-items:center; gap:9px; padding:8px 10px; border-radius:9px; cursor:pointer; color:rgba(255,255,255,.3); font-size:12px; font-weight:500; transition:background .14s,color .14s; user-select:none; }
.lp-prev-nav-item svg { width:14px; height:14px; flex-shrink:0; stroke:currentColor; fill:none; stroke-width:1.6; stroke-linecap:round; stroke-linejoin:round; }
.lp-prev-nav-item:hover { background:rgba(255,255,255,.05); color:rgba(255,255,255,.6); }
.lp-prev-active { background:color-mix(in srgb, var(--green) 10%, transparent)!important; color:var(--green)!important; }
.lp-prev-active svg { stroke:var(--green); }
