.lp-prev-screen::-webkit-scrollbar { display:none; }
.lp-prev-screen-active { opacity:1!important; pointer-events:auto!important; }

/* Screen sub-components */
.lp-ps-header { margin-bottom:16px; }
.lp-ps-eyebrow { display:flex; align-items:center; gap:6px; font-size:9px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:rgba(255,255,255,.28); margin-bottom:5px; }
.lp-ps-dot { width:5px; height:5px; border-radius:50%; background:var(--green); flex-shrink:0; }
.lp-ps-title { font-family:'Instrument Serif',serif; font-size:21px; color:#F0F0F0; letter-spacing:-.7px; font-weight:400; line-height:1.1; }
.lp-ps-title em { font-style:italic; color:var(--green); }
.lp-ps-badge { display:inline-flex; align-items:center; padding:3px 9px; border-radius:20px; border:1px solid color-mix(in srgb, var(--green) 18%, transparent); background:color-mix(in srgb, var(--green) 6%, transparent); font-size:10px; font-weight:600; color:rgba(240,240,240,.45); margin-top:7px; letter-spacing:.04em; }
.lp-ps-metrics { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; margin-bottom:10px; }
