.lp-ps-bar { height:2px; background:rgba(255,255,255,.07); border-radius:2px; overflow:hidden; margin-top:8px; }
.lp-ps-bar-fill { height:100%; background:var(--green); border-radius:2px; }
.lp-ps-quickrow { display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:12px; }
.lp-ps-qcard { display:flex; align-items:center; gap:10px; background:rgba(255,255,255,.03); border:1px solid rgba(255,255,255,.06); border-radius:10px; padding:11px 12px; cursor:pointer; transition:border-color .14s; }
.lp-ps-qcard:hover { border-color:color-mix(in srgb, var(--green) 20%, transparent); }
.lp-ps-qcard-ico { width:26px; height:26px; border-radius:7px; background:rgba(255,255,255,.06); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
.lp-ps-qcard-ico svg { width:12px; height:12px; fill:none; stroke:rgba(255,255,255,.4); stroke-width:1.5; stroke-linecap:round; }
.lp-ps-qcard-ttl { font-size:12px; font-weight:600; color:#F0F0F0; letter-spacing:-.1px; }
.lp-ps-qcard-sub { font-size:10px; color:rgba(255,255,255,.3); }
.lp-ps-qcard-arr { margin-left:auto; font-size:13px; color:rgba(255,255,255,.2); }
.lp-ps-feed-hd { font-size:9px; font-weight:700; letter-spacing:.08em; text-transform:uppercase; color:rgba(255,255,255,.2); margin-bottom:6px; }
.lp-ps-feed { display:flex; flex-direction:column; gap:4px; }
.lp-ps-feed-item { display:flex; align-items:center; gap:8px; padding:7px 10px; background:rgba(255,255,255,.02); border:1px solid rgba(255,255,255,.04); border-radius:7px; }
.lp-ps-feed-dot { width:5px; height:5px; border-radius:50%; flex-shrink:0; }
.lp-ps-feed-txt { flex:1; font-size:10px; color:rgba(255,255,255,.4); }
.lp-ps-feed-time { font-size:9px; color:rgba(255,255,255,.2); }

/* Create screen */
.lp-ps-tool-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }
.lp-ps-tool { display:flex; flex-direction:column; gap:6px; background:rgba(255,255,255,.03); border:1px solid rgba(255,255,255,.06); border-radius:10px; padding:13px 12px; cursor:pointer; transition:border-color .14s,background .14s; }
.lp-ps-tool:hover:not(.lp-ps-tool-soon) { border-color:rgba(255,255,255,.12); background:rgba(255,255,255,.05); }
