.lp-ps-tool-ttl { font-size:12px; font-weight:700; color:#F0F0F0; letter-spacing:-.1px; display:flex; align-items:center; gap:5px; }
.lp-ps-tool-sub { font-size:10px; color:rgba(255,255,255,.3); }
.lp-ps-soon-tag { font-size:8px; font-weight:700; letter-spacing:.08em; text-transform:uppercase; padding:1px 5px; border-radius:20px; background:rgba(255,255,255,.08); color:rgba(255,255,255,.35); }

/* Studio screen */
.lp-ps-st-tabs { display:flex; gap:4px; margin-bottom:14px; }
.lp-ps-tab { padding:6px 12px; border-radius:20px; font-size:11px; font-weight:600; color:rgba(255,255,255,.32); cursor:pointer; border:1px solid transparent; transition:all .14s; }
.lp-ps-tab.active { background:color-mix(in srgb, var(--green) 10%, transparent); border-color:color-mix(in srgb, var(--green) 20%, transparent); color:var(--green); }
