.lp-ps-bc-tag { display:inline-flex; padding:2px 7px; border-radius:20px; background:rgba(255,255,255,.06); border:1px solid rgba(255,255,255,.08); font-size:9px; font-weight:600; color:rgba(255,255,255,.45); }

