.lp-ps-filter-row { display:flex; gap:5px; margin-bottom:12px; }
.lp-ps-filter { padding:5px 11px; border-radius:20px; font-size:11px; font-weight:600; color:rgba(255,255,255,.32); border:1px solid rgba(255,255,255,.07); cursor:pointer; transition:all .14s; }
