.lp-ps-idea-body { background:rgba(255,255,255,.03); padding:7px 10px; }
.lp-ps-idea-cat { font-size:9px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; margin-bottom:2px; }
.lp-ps-idea-title { font-size:11px; font-weight:600; color:rgba(255,255,255,.75); }

