.lp-ps-avatar { width:28px; height:28px; border-radius:50%; background:color-mix(in srgb, var(--green) 12%, transparent); color:var(--green); display:flex; align-items:center; justify-content:center; font-size:10px; font-weight:700; flex-shrink:0; font-family:'Geist',sans-serif; }
