.lp-ps-invite-row { display:flex; align-items:center; gap:10px; padding:10px 0; cursor:pointer; opacity:.5; transition:opacity .14s; }
.lp-ps-invite-row:hover { opacity:1; }
.lp-ps-invite-ico { width:28px; height:28px; border-radius:50%; border:1.5px dashed rgba(255,255,255,.14); display:flex; align-items:center; justify-content:center; font-size:14px; color:rgba(255,255,255,.28); flex-shrink:0; }
