/* ── Preview explain panel ──────────────────────────────────── */
/* Layout: panel left + preview right */
.lp-prev-layout { display:grid; grid-template-columns:210px 1fr; gap:28px; align-items:start; }
.lp-prev-right { min-width:0; }
/* Left feature spotlight panel */
.lp-prev-panel { background:color-mix(in srgb, var(--green) 3%, transparent); border:1px solid color-mix(in srgb, var(--green) 10%, transparent); border-radius:18px; padding:18px 12px; position:sticky; top:80px; }
.lp-prev-panel-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.1em; color:color-mix(in srgb, var(--green) 40%, transparent); padding:0 8px; margin-bottom:10px; }
.lp-prev-panel-item { padding:9px 8px; border-radius:10px; cursor:pointer; transition:background .14s; }
.lp-prev-panel-item:hover:not(.lp-prev-panel-active) { background:rgba(255,255,255,.04); }
.lp-prev-panel-active { background:color-mix(in srgb, var(--green) 9%, transparent); }
.lp-prev-panel-name { font-size:12px; font-weight:600; color:rgba(255,255,255,.5); transition:color .14s; line-height:1.2; }
