.lp-prev-panel-desc { font-size:11px; color:rgba(255,255,255,.38); line-height:1.5; max-height:0; overflow:hidden; opacity:0; transition:max-height .22s ease,opacity .18s ease,margin-top .18s ease; margin-top:0; }
.lp-prev-panel-active .lp-prev-panel-desc { max-height:80px; opacity:1; margin-top:4px; }
.lp-prev-panel-badge { font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:.08em; color:color-mix(in srgb, var(--green) 50%, transparent); background:color-mix(in srgb, var(--green) 7%, transparent); border:1px solid color-mix(in srgb, var(--green) 14%, transparent); border-radius:10px; padding:2px 6px; display:inline-flex; margin-top:5px; }
@media(max-width:860px) { .lp-prev-layout { grid-template-columns:1fr; } .lp-prev-panel { display:none; } }

/* ── Signup modal ───────────────────────────────────────────── */
.lp-signup-modal { position:fixed; inset:0; background:rgba(0,0,0,.72); backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px); z-index:500; display:flex; align-items:center; justify-content:center; opacity:0; pointer-events:none; transition:opacity .22s ease; }
.lp-signup-modal.open { opacity:1; pointer-events:auto; }
.lp-signup-box { background:#141414; border:1px solid rgba(255,255,255,.1); border-radius:20px; padding:36px 32px; max-width:360px; width:calc(100% - 40px); text-align:center; position:relative; }
.lp-signup-modal.open .lp-signup-box { animation:lpFadeUp .3s cubic-bezier(.16,1,.3,1) both; }
.lp-signup-close { position:absolute; top:14px; right:14px; width:28px; height:28px; border-radius:50%; background:rgba(255,255,255,.06); border:1px solid rgba(255,255,255,.08); display:flex; align-items:center; justify-content:center; cursor:pointer; color:rgba(255,255,255,.4); transition:color .14s; }
.lp-signup-close:hover { color:rgba(255,255,255,.8); }
.lp-signup-close svg { width:10px; height:10px; fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; }
.lp-signup-logo { margin-bottom:16px; display:flex; justify-content:center; }
.lp-signup-title { font-family:'Instrument Serif',serif; font-size:22px; color:#F0F0F0; letter-spacing:-.6px; margin-bottom:10px; font-weight:400; line-height:1.2; }
.lp-signup-sub { font-size:13px; color:rgba(240,240,240,.45); line-height:1.65; margin-bottom:24px; }
.lp-signup-note { margin-top:14px; font-size:11px; color:rgba(240,240,240,.25); }

/* ═══════════════════════════════════════════════════════════════
   TESTIMONIALS CAROUSEL
   ═══════════════════════════════════════════════════════════════ */
.lp-testi-set { display:none; }
.lp-testi-set.active { display:grid; grid-template-columns:repeat(3,1fr); gap:16px; animation:lpCarouselIn .38s cubic-bezier(.16,1,.3,1) both; }
@keyframes lpCarouselIn { from { opacity:0; transform:translateX(16px); } to { opacity:1; transform:translateX(0); } }
.lp-testi-controls { display:flex; align-items:center; justify-content:center; gap:14px; margin-top:36px; }
.lp-testi-btn { width:38px; height:38px; border-radius:50%; border:1px solid var(--lp-border); background:rgba(255,255,255,.04); display:flex; align-items:center; justify-content:center; cursor:pointer; color:rgba(240,240,240,.4); transition:border-color .15s,color .15s,background .15s; }
.lp-testi-btn:hover { border-color:rgba(255,255,255,.18); color:var(--lp-white); background:rgba(255,255,255,.07); }
.lp-testi-btn svg { width:14px; height:14px; fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }
.lp-testi-dots { display:flex; gap:7px; align-items:center; }
.lp-testi-dot { width:6px; height:6px; border-radius:50%; background:rgba(255,255,255,.18); transition:background .22s,transform .22s; cursor:pointer; }
.lp-testi-dot.active { background:var(--green); transform:scale(1.35); }

/* ── Logo sizing update ─────────────────────────────────────── */
.lp-logo-img { width:52px; height:52px; object-fit:contain; }

/* ── Enhanced scroll animations ─────────────────────────────── */
.lp-stagger > * { opacity:0; transform:translateY(18px); transition:opacity .55s cubic-bezier(.16,1,.3,1), transform .55s cubic-bezier(.16,1,.3,1); }
.lp-stagger.visible > *:nth-child(1) { opacity:1; transform:none; transition-delay:.04s; }
.lp-stagger.visible > *:nth-child(2) { opacity:1; transform:none; transition-delay:.1s; }
.lp-stagger.visible > *:nth-child(3) { opacity:1; transform:none; transition-delay:.16s; }
.lp-stagger.visible > *:nth-child(4) { opacity:1; transform:none; transition-delay:.22s; }
.lp-stagger.visible > *:nth-child(5) { opacity:1; transform:none; transition-delay:.28s; }
.lp-stagger.visible > *:nth-child(6) { opacity:1; transform:none; transition-delay:.34s; }
.lp-slide-left { opacity:0; transform:translateX(-28px); transition:opacity .6s cubic-bezier(.16,1,.3,1), transform .6s cubic-bezier(.16,1,.3,1); }
.lp-slide-right { opacity:0; transform:translateX(28px); transition:opacity .6s cubic-bezier(.16,1,.3,1), transform .6s cubic-bezier(.16,1,.3,1); }
.lp-slide-left.visible, .lp-slide-right.visible { opacity:1; transform:none; }
.lp-reveal-left  { opacity:0; transform:translateX(-44px); transition:opacity .85s cubic-bezier(.16,1,.3,1), transform .9s cubic-bezier(.16,1,.3,1); }
.lp-reveal-right { opacity:0; transform:translateX( 44px); transition:opacity .85s cubic-bezier(.16,1,.3,1), transform .9s cubic-bezier(.16,1,.3,1); }
.lp-reveal-left.visible, .lp-reveal-right.visible { opacity:1; transform:none; }
@keyframes lpFadeIn { from { opacity:0; transform:translateY(6px); } to { opacity:1; transform:translateY(0); } }

/* ── Preview responsive ─────────────────────────────────────── */
@media(max-width:860px){
  .lp-prev-app { grid-template-columns:48px 1fr; }
  .lp-prev-nav-item span, .lp-prev-sb-logo span { display:none; }
  .lp-prev-nav-item { justify-content:center; padding:8px; }
  .lp-prev-sb-top { padding-left:0; display:flex; justify-content:center; }
  .lp-ps-tool-grid { grid-template-columns:repeat(2,1fr); }
