  .lp-prev-app { height:360px; }
  .lp-testi-set.active { grid-template-columns:1fr; }
  .lp-ps-tool-grid { grid-template-columns:1fr 1fr; }
  .lp-ps-metrics { grid-template-columns:repeat(3,1fr); }
