/* ── Process — fullscreen snap scenes ───────────────────────── */
.lp-proc-step {
  position: relative;
  height: 100vh;
  display: flex;
  align-items: center;
  background: var(--lp-bg);
  overflow: hidden;
  border-top: 1px solid rgba(255,255,255,.05);
  scroll-snap-align: start;
}
/* Persistent eyebrow */
.lp-proc-eyebrow {
  position: absolute;
  top: 36px;
  left: 64px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.2);
  z-index: 2;
}
/* Inner content — animated on entrance */
.lp-proc-inner {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 48px;
  transition: opacity .7s cubic-bezier(.16,1,.3,1), transform .75s cubic-bezier(.16,1,.3,1);
  will-change: transform, opacity;
}
/* Hidden before entering viewport */
.lp-proc-step:not(.lp-in) .lp-proc-inner { opacity: 0; }
.lp-proc-step[data-enter="left"]:not(.lp-in) .lp-proc-inner  { transform: translateX(-52px); }
.lp-proc-step[data-enter="right"]:not(.lp-in) .lp-proc-inner { transform: translateX(52px); }
/* Visible */
.lp-proc-step.lp-in .lp-proc-inner { opacity: 1; transform: none; }

.lp-proc-text { max-width: 520px; }
.lp-proc-kicker {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: rgba(255,255,255,.22);
  margin-bottom: 20px;
}
.lp-proc-h {
  font-size: clamp(52px, 7vw, 88px);
  font-weight: 700;
  color: var(--lp-white);
  line-height: 1.04;
  letter-spacing: -2.5px;
  margin-bottom: 28px;
  font-family: 'Geist', sans-serif;
}
.lp-proc-h em {
  font-style: italic;
  color: var(--lp-green);
  font-family: 'Instrument Serif', serif;
  font-weight: 400;
}
.lp-proc-body {
  font-size: 16px;
  color: var(--lp-muted);
  line-height: 1.78;
  max-width: 420px;
}
/* Large background step number */
.lp-proc-numvis {
  font-size: clamp(120px, 18vw, 240px);
  font-weight: 800;
  font-family: 'Instrument Serif', serif;
  color: rgba(255,255,255,.03);
  letter-spacing: -8px;
  line-height: 1;
  user-select: none;
  flex-shrink: 0;
}
/* Progress dots */
.lp-proc-dots {
  position: absolute;
  bottom: 36px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  align-items: center;
}
.lp-proc-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.2);
  background: transparent;
  transition: width .25s, border-radius .25s, background .25s, border-color .25s;
}
.lp-proc-dot-on {
  width: 20px;
  border-radius: 3px;
  background: var(--lp-green);
  border-color: var(--lp-green);
}
/* Mobile: stack as normal content */
@media (max-width: 820px) {
  /* Disable snap scroll entirely on mobile — touch scroll feels better */
  html { scroll-snap-type: none; }
  .lp-snap { scroll-snap-align: none; min-height: auto; display: block; }
  .lp-hero.lp-snap { display: flex; } /* hero keeps its flex centering */

  .lp-proc-step {
    height: auto;
    padding: 80px 0;
    scroll-snap-align: none;
  }
  .lp-proc-step:not(.lp-in) .lp-proc-inner,
  .lp-proc-step.lp-in .lp-proc-inner { opacity: 1; transform: none; }
  .lp-proc-inner { padding: 0 28px; flex-direction: column; align-items: flex-start; gap: 0; }
  .lp-proc-h { font-size: clamp(40px, 12vw, 60px); letter-spacing: -1.5px; }
  .lp-proc-numvis { display: none; }
  .lp-proc-eyebrow { left: 28px; }
  .lp-proc-dots { display: none; }
}
/* Reduced motion: show statically */
@media (prefers-reduced-motion: reduce) {
  .lp-proc-step { height: auto; padding: 80px 0; scroll-snap-align: none; }
  .lp-proc-step:not(.lp-in) .lp-proc-inner,
  .lp-proc-step.lp-in .lp-proc-inner { opacity: 1; transform: none; }
  .lp-proc-inner { padding: 0 80px; }
  .lp-proc-dots { display: none; }
}

/* ── Footer scroll-to-top ───────────────────────────────────── */
.lp-scroll-top{margin-left:auto;flex-shrink:0;width:32px;height:32px;border-radius:50%;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);display:flex;align-items:center;justify-content:center;cursor:pointer;color:rgba(240,240,240,.35);transition:border-color .18s,color .18s,background .18s,transform .18s}
