.lp-scroll-top svg{width:12px;height:12px}

/* ── Nav active state underline ─────────────────────────────── */
.lp-nav-link{position:relative}
.lp-nav-link::after{content:'';position:absolute;bottom:-3px;left:0;height:1.5px;width:0;background:var(--green);border-radius:2px;transition:width .35s cubic-bezier(.16,1,.3,1)}
.lp-nav-link.lp-nav-active{color:var(--lp-white)}
