/* ── Nav hover description ───────────────────────────────────── */
.lp-nav-tip {
  position: absolute;
  top: calc(100% + 14px);
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  white-space: nowrap;
  font-size: 11px;
  font-weight: 400;
  color: rgba(240,240,240,.45);
  letter-spacing: .02em;
  opacity: 0;
  pointer-events: none;
