/* ── Auth views (Login / Signup) ──────────────────────────────────── */
.au-view-wrap { min-height: 100vh; display: flex; flex-direction: column; background: #0A0A0A; }
.au-nav { position: fixed; top: 0; left: 0; right: 0; height: 68px; display: flex; align-items: center; padding: 0 32px; z-index: 10; justify-content: flex-start; }
.au-nav-logo { display: flex; align-items: center; text-decoration: none; }
.au-nav-logo img { height: 56px; width: auto; display: block; }
@media (max-width: 768px) { .au-nav { padding: 0 20px; height: 62px; } .au-nav-logo img { height: 46px; } }
@media (max-width: 480px) { .au-nav { padding: 0 16px; } .au-nav-logo img { height: 40px; } }
.au-page { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 88px 24px 48px; }
.au-card { width: 100%; max-width: 420px; background: #111111; border: 1px solid rgba(255,255,255,.08); border-radius: 20px; padding: 36px 32px; box-shadow: 0 24px 80px rgba(0,0,0,.5); }
.au-title { font-family: 'Geist', system-ui, -apple-system, sans-serif; font-size: 26px; color: #F0F0F0; letter-spacing: -.7px; font-weight: 600; margin-bottom: 6px; line-height: 1.1; }
.au-sub { font-size: 13px; color: rgba(240,240,240,.38); margin-bottom: 28px; line-height: 1.5; }
.au-field { display: flex; flex-direction: column; gap: 5px; margin-bottom: 12px; }
.au-label { font-size: 11px; font-weight: 700; letter-spacing: .04em; color: rgba(240,240,240,.45); text-transform: uppercase; }
.au-input { background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.09); border-radius: 10px; padding: 11px 14px; font-size: 14px; color: #F0F0F0; font-family: inherit; outline: none; transition: border-color .15s; width: 100%; box-sizing: border-box; }
.au-input:focus { border-color: color-mix(in srgb, var(--green) 40%, transparent); background: rgba(255,255,255,.07); }
.au-input::placeholder { color: rgba(240,240,240,.2); }
.au-input.au-err { border-color: rgba(239,68,68,.45) !important; }
/* Edge/IE's native password-reveal icon (::-ms-reveal) renders dark by
   default and is nearly invisible against this dark input background --
   there's no custom show/hide toggle built in this app to restyle
   directly, this is the browser's own UA-rendered control, only reachable
   via this non-standard pseudo-element. filter is the only way to
   recolor it (color/fill aren't honored here); invert flips it to a
   crisp white without touching the input's own background/border/size. */
.au-input::-ms-reveal { filter: invert(100%); }
.au-error { font-size: 12.5px; color: #EF4444; margin-bottom: 14px; display: none; line-height: 1.55; padding: 10px 13px; background: rgba(239,68,68,.08); border-radius: 8px; border: 1px solid rgba(239,68,68,.18); }
.au-btn { width: 100%; padding: 13px; background: var(--green); color: #000; font-size: 14px; font-weight: 700; border-radius: 40px; border: none; cursor: pointer; margin-top: 10px; font-family: inherit; transition: background .15s, transform .15s, box-shadow .15s; letter-spacing: -.1px; }
.au-btn:hover:not(:disabled) { background: var(--gm); transform: translateY(-1px); box-shadow: 0 6px 20px color-mix(in srgb, var(--green) 22%, transparent); }
.au-btn:disabled { opacity: .55; cursor: not-allowed; transform: none; box-shadow: none; }
.au-divider { height: 1px; background: rgba(255,255,255,.07); margin: 22px 0; }
.au-footer { text-align: center; font-size: 13px; color: rgba(240,240,240,.32); }
.au-footer a { color: color-mix(in srgb, var(--green) 75%, transparent); text-decoration: none; font-weight: 600; }
.au-footer a:hover { color: var(--green); }
.au-terms { text-align: center; font-size: 11px; color: rgba(240,240,240,.2); margin-top: 14px; line-height: 1.5; }
.au-dev-link { display: none; text-align: center; margin-top: 16px; }
.au-dev-link a { font-size: 11.5px; color: color-mix(in srgb, var(--green) 40%, transparent); text-decoration: none; letter-spacing: .02em; }
.au-dev-link a:hover { color: color-mix(in srgb, var(--green) 70%, transparent); }

/* ── Plan selection page ─────────────────────────────────────────── */
.pl-view-wrap { min-height: 100vh; display: flex; flex-direction: column; background: #0A0A0A; }
.pl-nav { position: fixed; top: 0; left: 0; right: 0; height: 60px; display: flex; align-items: center; justify-content: space-between; padding: 0 28px; z-index: 10; }
.pl-nav-logo { display: flex; align-items: center; gap: 10px; text-decoration: none; }
.pl-nav-logo img { width: 40px; height: 40px; object-fit: contain; }
.pl-nav-step { font-size: 12px; color: rgba(240,240,240,.3); letter-spacing: .03em; }
.pl-page { flex: 1; display: flex; flex-direction: column; align-items: center; padding: 96px 24px 64px; }
.pl-eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: rgba(240,240,240,.35); margin-bottom: 16px; }
.pl-eyebrow-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 15%, transparent); }
.pl-title { font-family: 'Instrument Serif', serif; font-size: 38px; color: #F0F0F0; letter-spacing: -.8px; font-weight: 400; text-align: center; line-height: 1.1; margin-bottom: 12px; }
.pl-title em { font-style: italic; color: var(--green); }
.pl-sub { font-size: 14px; color: rgba(240,240,240,.38); text-align: center; margin-bottom: 52px; line-height: 1.6; max-width: 440px; }
.pl-steps { display: flex; align-items: center; gap: 8px; margin-bottom: 48px; }
.pl-step { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; }
.pl-step-num { width: 22px; height: 22px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 700; }
.pl-step.done .pl-step-num { background: var(--green); color: #000; }
.pl-step.done .pl-step-lbl { color: rgba(240,240,240,.5); }
.pl-step.active .pl-step-num { background: color-mix(in srgb, var(--green) 15%, transparent); border: 1px solid color-mix(in srgb, var(--green) 40%, transparent); color: var(--green); }
.pl-step.active .pl-step-lbl { color: #F0F0F0; }
.pl-step.idle .pl-step-num { background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.08); color: rgba(240,240,240,.3); }
