.pl-card { background: #111111; border: 1px solid rgba(255,255,255,.08); border-radius: 20px; padding: 28px 24px 24px; display: flex; flex-direction: column; position: relative; transition: border-color .2s, transform .15s; }
.pl-card:hover { border-color: rgba(255,255,255,.16); transform: translateY(-2px); }
.pl-card.pl-popular { border-color: color-mix(in srgb, var(--green) 28%, transparent); background: #121812; }
.pl-card.pl-popular:hover { border-color: color-mix(in srgb, var(--green) 50%, transparent); }
.pl-tag { position: absolute; top: -11px; left: 50%; transform: translateX(-50%); background: var(--green); color: #000; font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; padding: 3px 12px; border-radius: 20px; white-space: nowrap; }
.pl-card-name { font-size: 13px; font-weight: 700; color: rgba(240,240,240,.55); letter-spacing: .04em; text-transform: uppercase; margin-bottom: 12px; }
.pl-price { display: flex; align-items: baseline; gap: 3px; margin-bottom: 6px; }
.pl-price-num { font-family: 'Instrument Serif', serif; font-size: 44px; color: #F0F0F0; letter-spacing: -1.5px; line-height: 1; }
.pl-price-period { font-size: 13px; color: rgba(240,240,240,.35); font-weight: 400; }
.pl-card-desc { font-size: 13px; color: rgba(240,240,240,.38); line-height: 1.55; margin-bottom: 20px; }
.pl-divider { height: 1px; background: rgba(255,255,255,.07); margin-bottom: 18px; }
.pl-feats { list-style: none; display: flex; flex-direction: column; gap: 9px; margin-bottom: 24px; flex: 1; }
.pl-feat { display: flex; align-items: flex-start; gap: 9px; font-size: 13px; color: rgba(240,240,240,.65); line-height: 1.4; }
.pl-feat-chk { width: 16px; height: 16px; border-radius: 50%; background: color-mix(in srgb, var(--green) 12%, transparent); border: 1px solid color-mix(in srgb, var(--green) 25%, transparent); display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 1px; }
.pl-feat-chk svg { width: 8px; height: 8px; stroke: var(--green); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; fill: none; }
.pl-btn { width: 100%; padding: 13px; font-size: 14px; font-weight: 700; border-radius: 40px; border: none; cursor: pointer; font-family: inherit; transition: background .15s, transform .15s, box-shadow .15s; letter-spacing: -.1px; text-align: center; }
.pl-btn-primary { background: var(--green); color: #000; }
.pl-btn-primary:hover:not(:disabled) { background: var(--gm); transform: translateY(-1px); box-shadow: 0 6px 20px color-mix(in srgb, var(--green) 22%, transparent); }
.pl-btn-outline { background: rgba(255,255,255,.06); color: #F0F0F0; border: 1px solid rgba(255,255,255,.12); }
.pl-btn-outline:hover:not(:disabled) { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.2); }
.pl-btn:disabled { opacity: .5; cursor: not-allowed; transform: none !important; }
.pl-spinner { display: inline-block; width: 14px; height: 14px; border: 2px solid rgba(0,0,0,.2); border-top-color: #000; border-radius: 50%; animation: plSpin .6s linear infinite; vertical-align: middle; margin-right: 6px; }
.pl-spinner-w { display: inline-block; width: 14px; height: 14px; border: 2px solid rgba(255,255,255,.15); border-top-color: rgba(255,255,255,.7); border-radius: 50%; animation: plSpin .6s linear infinite; vertical-align: middle; margin-right: 6px; }
@keyframes plSpin { to { transform: rotate(360deg); } }
.pl-error { font-size: 12.5px; color: #EF4444; margin-top: 16px; padding: 10px 13px; background: rgba(239,68,68,.08); border-radius: 8px; border: 1px solid rgba(239,68,68,.18); display: none; text-align: center; max-width: 900px; width: 100%; }
.pl-note { font-size: 12px; color: rgba(240,240,240,.25); text-align: center; margin-top: 28px; }
.pl-note a { color: color-mix(in srgb, var(--green) 50%, transparent); text-decoration: none; }
.pl-note a:hover { color: var(--green); }
#plAuthCheck { position: fixed; inset: 0; background: #0A0A0A; display: flex; align-items: center; justify-content: center; z-index: 100; }
.pl-auth-spin { width: 32px; height: 32px; border: 2.5px solid color-mix(in srgb, var(--green) 15%, transparent); border-top-color: var(--green); border-radius: 50%; animation: plSpin .7s linear infinite; }

/* ══════════════════════════════════════════════════════════════
   INSPIRATION LAYOUT REFINEMENT
   These rules override earlier inspiration styles via cascade order.
   ══════════════════════════════════════════════════════════════ */

/* ── Section ─────────────────────────────────────────────────── */
.id-section {
  margin-bottom: 56px;
}

.id-section-hdr {
  margin-bottom: 20px;
  padding-bottom: 14px;
}

.id-section-emoji {
  font-size: 17px;
}

.id-section-lbl {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .04em;
}

/* ── Section grid: horizontal scroll row ─────────────────────── */
.id-section-grid {
  display: flex;
  flex-wrap: nowrap;
  gap: 18px;
  overflow-x: auto;
  padding-bottom: 14px;
  scroll-snap-type: x proximity;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-x: contain;
}
.id-section-grid::-webkit-scrollbar {
  height: 3px;
}
.id-section-grid::-webkit-scrollbar-track {
  background: transparent;
}
.id-section-grid::-webkit-scrollbar-thumb {
  background: var(--b2);
  border-radius: 2px;
}

/* ── Card: fixed width, equal height via flex row ────────────── */
.id-concept-card {
  flex: 0 0 300px;
  min-width: 300px;
  scroll-snap-align: start;
}

/* ── Card thumbnail ──────────────────────────────────────────── */
.id-card-thumb {
  height: 152px;
}

/* ── Card body: spacious, flex column with CTA at bottom ─────── */
.id-card-body {
  padding: 20px 22px 22px;
  gap: 0;
}

/* ── Visual hierarchy ────────────────────────────────────────── */
.id-card-cat {
  font-size: 10px;
  letter-spacing: .08em;
  margin-bottom: 8px;
}

.id-card-title {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -.3px;
  line-height: 1.28;
  margin-bottom: 10px;
}

.id-card-desc {
  font-size: 12px;
  line-height: 1.7;
  flex: 1;
  margin-bottom: 0;
}

/* ── Use This Inspiration: anchored to card bottom ───────────── */
.id-card-cta {
  display: block;
  width: 100%;
  margin-top: 18px;
  padding: 10px 16px;
  font-size: 12px;
  font-weight: 600;
  background: color-mix(in srgb, var(--green) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 22%, transparent);
  border-radius: 10px;
  color: color-mix(in srgb, var(--green) 70%, transparent);
  text-align: center;
  cursor: pointer;
  transition: background .18s, border-color .2s, color .18s;
  pointer-events: none;
  letter-spacing: .01em;
  flex-shrink: 0;
}

.id-concept-card:hover .id-card-cta {
  background: color-mix(in srgb, var(--green) 16%, transparent);
  border-color: color-mix(in srgb, var(--green) 50%, transparent);
  color: var(--green);
}

/* ── Filter row: centered pill group ─────────────────────────── */
.id-filter-row {
  gap: 10px;
  margin-bottom: 28px;
}

.id-filt {
  padding: 8px 18px;
  font-size: 12.5px;
}

/* ── Responsive ──────────────────────────────────────────────── */
@media(max-width:640px) {
  .id-concept-card {
    flex: 0 0 272px;
    min-width: 272px;
  }
  .id-card-title {
    font-size: 14px;
  }
}

/* ══ Inspiration grid fix: responsive 3→2→1 column layout ══════ */
.id-section-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:18px;
  overflow-x:visible;
}
.id-concept-card{
  flex:none;
  min-width:0;
  width:100%;
  scroll-snap-align:unset;
}
@media(max-width:860px){.id-section-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:540px){.id-section-grid{grid-template-columns:1fr}}


/* ══ Inspiration: wide cards, auto-responsive grid ═════════════
   auto-fill + minmax(300px,1fr) keeps cards at 300px+ and wraps
   automatically: 3 cols desktop → 2 tablet → 1 mobile.
   No fixed breakpoints needed. No horizontal overflow. ══════ */
.id-section-grid{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(300px,1fr));
  gap:18px;
  overflow-x:visible;
}

/* Cards fill their grid cell; no fixed flex-width override */
.id-concept-card{
  flex:none;
  min-width:0;
  width:100%;
}

/* ══ Inspiration root fix: idFeed is a section container, not a card grid ══
   .id-concept-grid on #idFeed used to lay out individual cards.
   Now inspiration.js renders sections inside idFeed, so the outer grid
   must be a single-column stack. The card grid lives inside .id-section-grid. */

/* 1. Override the outer feed container to stack sections vertically */
#idFeed.id-concept-grid{
  display:flex;
  flex-direction:column;
  gap:0;
  grid-template-columns:none;
  animation:none;
}

/* 2. Section grid: 3-col on desktop, responsive below */
.id-section-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:20px;
  width:100%;
  overflow-x:visible;
}

/* 3. Cards fill their grid cell — no fixed flex or min-width override */
.id-concept-card{
  flex:none;
  min-width:0;
  width:100%;
}

/* 4. Responsive breakpoints for the section card grid */
@media(max-width:860px){.id-section-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:520px){.id-section-grid{grid-template-columns:1fr}}

/* ══ Six Core Systems section ════════════════════════════════════ */
.lp-feats-6{
  max-width:1100px;margin:0 auto;
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:1px;
  background:var(--lp-border);
  border:1px solid var(--lp-border);
  border-radius:var(--lp-rl);
  overflow:hidden
}

/* Business plan badge on Team card */
.lp-feat-badge{
  display:inline-flex;
  align-items:center;
  font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:color-mix(in srgb, var(--green) 75%, transparent);
  background:color-mix(in srgb, var(--green) 8%, transparent);
  border:1px solid color-mix(in srgb, var(--green) 20%, transparent);
  padding:3px 9px;border-radius:20px;
  width:fit-content
}

/* Tablet: 2 columns */
@media(max-width:860px){.lp-feats-6{grid-template-columns:repeat(2,1fr)}}
/* Mobile: single column */
@media(max-width:520px){.lp-feats-6{grid-template-columns:1fr}}

/* ══ Five systems: single 5-col row, compact cards ═════════════ */
.lp-feats-5{
  grid-template-columns:repeat(5,1fr);
}
.lp-feats-5 .lp-feat:nth-child(1),
.lp-feats-5 .lp-feat:nth-child(2),
.lp-feats-5 .lp-feat:nth-child(3),
.lp-feats-5 .lp-feat:nth-child(4),
.lp-feats-5 .lp-feat:nth-child(5){
  grid-column:auto;
  padding:22px 18px;
  gap:10px;
}
.lp-feats-5 .lp-feat-ico{width:34px;height:34px;border-radius:8px}
.lp-feats-5 .lp-feat-ico svg{width:15px;height:15px}
.lp-feats-5 .lp-feat-title{font-size:13.5px}
.lp-feats-5 .lp-feat-desc{font-size:12px;line-height:1.6}
.lp-feats-5 .lp-feat-tag{font-size:9px;padding-top:4px}

@media(max-width:900px){
  .lp-feats-5{grid-template-columns:repeat(3,1fr)}
  .lp-feats-5 .lp-feat:nth-child(1),
  .lp-feats-5 .lp-feat:nth-child(2),
  .lp-feats-5 .lp-feat:nth-child(3),
  .lp-feats-5 .lp-feat:nth-child(4),
  .lp-feats-5 .lp-feat:nth-child(5){grid-column:auto}
}
@media(max-width:560px){.lp-feats-5{grid-template-columns:1fr}}

