/* ── Poster Generator card — Soft Violet #C084FC ────────────────── */
.cr-card-poster{background:linear-gradient(140deg,#120A1E,#0E0818);border-color:rgba(192,132,252,.2);box-shadow:inset 0 0 60px rgba(192,132,252,.05)}
.cr-card-poster::before{background:radial-gradient(ellipse at 20% 120%,rgba(192,132,252,.14) 0%,transparent 60%)}
.cr-card-poster:hover{border-color:rgba(192,132,252,.4);box-shadow:0 16px 48px rgba(192,132,252,.1),inset 0 0 60px rgba(192,132,252,.08)}
.cr-card-poster .cr-card-ico{background:#0C0418;border-color:rgba(192,132,252,.25)}
.cr-card-poster .cr-card-ico svg{stroke:#C084FC}
.cr-card-poster .cr-card-tag{color:rgba(192,132,252,.65)}
.cr-card-poster .cr-card-title{color:rgba(255,255,255,.92)}
.cr-card-poster .cr-card-desc{color:rgba(255,255,255,.44)}
.cr-card-poster .cr-card-chip{background:rgba(192,132,252,.09);color:rgba(192,132,252,.6);border:1px solid rgba(192,132,252,.14)}
.cr-card-poster .cr-card-arrow svg{stroke:#C084FC}
.cr-card-infographic{background:linear-gradient(140deg,#071A1A,#051414);border-color:rgba(20,184,166,.2);box-shadow:inset 0 0 60px rgba(20,184,166,.05)}
.cr-card-infographic::before{background:radial-gradient(ellipse at 20% 120%,rgba(20,184,166,.14) 0%,transparent 60%)}
.cr-card-infographic:hover{border-color:rgba(20,184,166,.4);box-shadow:0 16px 48px rgba(20,184,166,.1),inset 0 0 60px rgba(20,184,166,.08)}
.cr-card-infographic .cr-card-ico{background:#031010;border-color:rgba(20,184,166,.25)}
.cr-card-infographic .cr-card-ico svg{stroke:#2DD4BF}
.cr-card-infographic .cr-card-tag{color:rgba(20,184,166,.65)}
.cr-card-infographic .cr-card-title{color:rgba(255,255,255,.92)}
.cr-card-infographic .cr-card-desc{color:rgba(255,255,255,.44)}
.cr-card-infographic .cr-card-chip{background:rgba(20,184,166,.09);color:rgba(20,184,166,.6);border:1px solid rgba(20,184,166,.14)}
.cr-card-infographic .cr-card-arrow svg{stroke:#2DD4BF}

/* ── Email result renderer ──────────────────────────────────────── */
.builder-email-result{border:1px solid var(--border);border-radius:14px;overflow:hidden}
.ber-toolbar{background:var(--surface);padding:10px 16px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}
.ber-label{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.ber-dl-btn{font-size:11px;font-weight:600;padding:5px 12px;border-radius:6px;border:1px solid var(--border);background:transparent;color:var(--charcoal);cursor:pointer;transition:background .15s}
.ber-dl-btn:hover{background:var(--border)}
.ber-frame-wrap{background:#f0f0f0;padding:20px;display:flex;justify-content:center}
.ber-frame{width:600px;max-width:100%;height:620px;border:none;border-radius:6px;box-shadow:0 2px 24px rgba(0,0,0,.12)}

/* ── Deck result renderer ───────────────────────────────────────── */
.builder-deck-result{display:flex;flex-direction:column;gap:12px}
.deck-slide{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:20px 24px}
.ds-num{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:8px}
.ds-title{font-size:20px;font-weight:700;letter-spacing:-.4px;color:var(--charcoal);margin-bottom:10px;line-height:1.2}
.ds-content{font-size:13px;line-height:1.75;color:var(--charcoal);white-space:pre-wrap}
/* NOTE: .ds-* rules below are superseded by the visual deck system — kept for fallback */
.ds-notes{margin-top:12px;padding-top:12px;border-top:1px solid var(--border);font-size:12px;color:var(--muted);line-height:1.6}
.ds-notes-lbl{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;display:block;margin-bottom:4px;opacity:.6}

/* ══ Deck result: visual slide cards ════════════════════════════ */
.deck-result-wrap{display:flex;flex-direction:column;gap:20px}
.deck-slides-list{display:flex;flex-direction:column;gap:16px}
.deck-slide-wrap{display:flex;flex-direction:column}
.dcs-meta{display:flex;align-items:center;gap:8px;margin-bottom:6px}
.dcs-num{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}
.dcs-layout{font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;padding:2px 7px;border-radius:4px;background:rgba(255,255,255,.06);color:rgba(255,255,255,.3)}

/* ── Slide canvas (16:9 ratio) ──────────────────────────────────── */
.slide-canvas{width:100%;aspect-ratio:16/9;border-radius:10px;overflow:hidden;position:relative;background:#10101a;box-shadow:0 4px 24px rgba(0,0,0,.35)}

/* ── Decorative glow blobs ──────────────────────────────────────── */
.sc-deco{position:absolute;border-radius:50%;pointer-events:none}
.sc-deco-1{width:35%;height:70%;top:-20%;right:-10%;background:radial-gradient(circle,rgba(var(--dar,99),var(--dag,102),var(--dab,241),.2) 0%,transparent 70%)}
.sc-deco-2{width:20%;height:40%;bottom:-5%;left:-5%;background:radial-gradient(circle,rgba(var(--dar,99),var(--dag,102),var(--dab,241),.1) 0%,transparent 70%)}

/* ── Slide number badge ─────────────────────────────────────────── */
.sc-badge{position:absolute;bottom:4%;right:3%;font-size:10px;font-weight:700;letter-spacing:.06em;color:rgba(255,255,255,.18)}

/* ── Title slide ────────────────────────────────────────────────── */
.slide-canvas-title{background:linear-gradient(135deg,#0c0c1a,#150a28);display:flex;align-items:center;justify-content:center}
.slide-canvas-title .sc-deco-1{background:radial-gradient(circle,rgba(var(--dar,99),var(--dag,102),var(--dab,241),.28) 0%,transparent 65%)}
.sc-title-wrap{position:relative;z-index:1;text-align:center;padding:0 8%;width:100%}
.sc-eyebrow{font-size:clamp(8px,1vw,11px);font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--dac,#6366F1);margin-bottom:.6em;opacity:.85}
.sc-title{font-size:clamp(18px,3.8vw,44px);font-weight:800;color:#fff;line-height:1.08;letter-spacing:-.03em}
.sc-subtitle{font-size:clamp(10px,1.4vw,17px);color:rgba(255,255,255,.52);margin-top:.7em;line-height:1.4}

/* ── Content slide ──────────────────────────────────────────────── */
.slide-canvas-content{background:linear-gradient(160deg,#12121e,#0e0e18)}
.slide-canvas-content::after{content:'';position:absolute;top:0;left:0;width:4px;height:100%;background:linear-gradient(to bottom,var(--dac,#6366F1),transparent)}

/* ── Stats slide ────────────────────────────────────────────────── */
.slide-canvas-stats{background:linear-gradient(160deg,#0a0a18,#12101e)}

/* ── Feature slide ──────────────────────────────────────────────── */
.slide-canvas-feature{background:linear-gradient(160deg,#0f0f1c,#10101a)}
.slide-canvas-feature::after{content:'';position:absolute;top:0;left:0;width:4px;height:100%;background:linear-gradient(to bottom,var(--dac,#6366F1),transparent)}

/* ── Quote slide ────────────────────────────────────────────────── */
.slide-canvas-quote{background:linear-gradient(135deg,#0c0c1a,#1a0a28);display:flex;align-items:center;justify-content:center}

/* ── Closing slide ──────────────────────────────────────────────── */
.slide-canvas-closing{background:linear-gradient(135deg,#0c0c1a,#150a28);display:flex;align-items:center;justify-content:center}
.slide-canvas-closing .sc-deco-1{background:radial-gradient(circle,rgba(var(--dar,99),var(--dag,102),var(--dab,241),.28) 0%,transparent 65%)}

/* ── Shared inner layout ────────────────────────────────────────── */
.sc-inner{position:relative;z-index:1;padding:7% 8% 7% 9%;height:100%;box-sizing:border-box;display:flex;flex-direction:column}
.sc-slide-title{font-size:clamp(13px,2.2vw,24px);font-weight:700;color:#fff;letter-spacing:-.02em;margin-bottom:.55em;line-height:1.15}

/* ── Bullet list ────────────────────────────────────────────────── */
.sc-bullets{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:.4em;flex:1}
.sc-bullets li{font-size:clamp(9px,1.25vw,14px);color:rgba(255,255,255,.72);padding-left:1.2em;position:relative;line-height:1.45}
.sc-bullets li::before{content:'';position:absolute;left:0;top:.5em;width:.44em;height:.44em;border-radius:50%;background:var(--dac,#6366F1)}
.sc-body-text{font-size:clamp(9px,1.2vw,14px);color:rgba(255,255,255,.62);line-height:1.65;flex:1}

/* ── Stats layout ───────────────────────────────────────────────── */
.sc-metrics-row{display:flex;gap:3%;align-items:stretch;flex:1;margin-top:.5em}
.sc-metric{flex:1;text-align:center;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:8px;padding:5% 3%;display:flex;flex-direction:column;justify-content:center}
.sc-metric-val{font-size:clamp(16px,3vw,38px);font-weight:800;color:var(--dac,#6366F1);letter-spacing:-.03em;line-height:1;margin-bottom:.25em}
.sc-metric-lbl{font-size:clamp(7px,.9vw,11px);font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.38)}
.sc-metric-note{font-size:clamp(7px,.9vw,11px);color:rgba(255,255,255,.32);margin-top:.6em;line-height:1.5}

/* ── Feature layout ─────────────────────────────────────────────── */
.sc-feat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(28%,1fr));gap:2.5%;flex:1;margin-top:.5em;align-content:start}
.sc-feat-card{background:rgba(255,255,255,.04);border:1px solid rgba(var(--dar,99),var(--dag,102),var(--dab,241),.2);border-radius:7px;padding:5% 6%;font-size:clamp(8px,1.05vw,12px);font-weight:600;color:rgba(255,255,255,.72);line-height:1.4}

/* ── Quote layout ───────────────────────────────────────────────── */
.sc-quote-wrap{position:relative;z-index:1;padding:0 10%;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%}
.sc-qmark{font-size:clamp(40px,7vw,80px);color:var(--dac,#6366F1);opacity:.3;line-height:.8;margin-bottom:.1em;font-family:Georgia,serif}
.sc-quote-text{font-size:clamp(11px,1.7vw,20px);font-style:italic;color:rgba(255,255,255,.84);line-height:1.5;max-width:80%}
.sc-attr{margin-top:.8em;font-size:clamp(8px,1vw,13px);color:rgba(255,255,255,.38);letter-spacing:.04em}

/* ── Closing layout ─────────────────────────────────────────────── */
.sc-closing-wrap{position:relative;z-index:1;text-align:center;padding:0 10%;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%}
.sc-closing-title{font-size:clamp(16px,3vw,38px);font-weight:800;color:#fff;letter-spacing:-.02em;line-height:1.1;margin-bottom:.4em}
.sc-closing-body{font-size:clamp(9px,1.2vw,15px);color:rgba(255,255,255,.52);line-height:1.5;margin-bottom:.8em;max-width:72%}
.sc-cta{display:inline-block;background:var(--dac,#6366F1);color:#fff;font-size:clamp(9px,1.1vw,14px);font-weight:700;padding:.55em 1.6em;border-radius:6px;letter-spacing:.03em}

/* ── Speaker notes strip ────────────────────────────────────────── */
.dcs-notes{background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.06);border-top:none;border-radius:0 0 8px 8px;padding:8px 14px;font-size:11px;line-height:1.6;color:rgba(255,255,255,.35)}
.dcs-notes-lbl{display:inline-block;font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.2);margin-right:.6em}

/* ── Deck info panel ────────────────────────────────────────────── */
.deck-info-panel{background:rgba(255,255,255,.028);border:1px solid rgba(255,255,255,.07);border-radius:12px;padding:16px 20px;margin-top:4px}
.dip-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.45);margin-bottom:6px}
.dip-body{font-size:12px;line-height:1.65;color:rgba(255,255,255,.32);margin-bottom:10px}
.dip-roadmap{display:flex;align-items:center;gap:10px;border-top:1px solid rgba(255,255,255,.06);padding-top:8px}
.dip-lbl{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.22);white-space:nowrap}
.dip-list{font-size:11px;color:rgba(255,255,255,.28)}

/* ══ Email info panel ════════════════════════════════════════════ */
.ber-info-panel{margin-top:12px;background:rgba(255,255,255,.028);border:1px solid rgba(255,255,255,.07);border-radius:12px;padding:16px 20px}
.ber-info-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.45);margin-bottom:8px}
.ber-info-steps{margin:0 0 12px 0;padding-left:18px}
.ber-info-steps li{font-size:12px;line-height:1.65;color:rgba(255,255,255,.35);margin-bottom:4px}
.ber-info-steps li strong{color:rgba(255,255,255,.52);font-weight:600}
.ber-info-coming{display:flex;align-items:center;gap:10px;border-top:1px solid rgba(255,255,255,.06);padding-top:8px}
.bic-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.22);white-space:nowrap}
.bic-list{font-size:11px;color:rgba(255,255,255,.28)}

/* ══ Poster result renderer ══════════════════════════════════════ */
.poster-result-wrap{border:1px solid var(--border);border-radius:14px;overflow:hidden}
.pr-toolbar{background:var(--surface);padding:10px 16px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}
.pr-label{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
