.pr-dl-btn:hover{background:var(--border)}
.pr-frame-wrap{background:#1a1a1a;padding:24px;display:flex;justify-content:center;overflow-x:auto}
.pr-frame{width:794px;max-width:100%;height:1123px;border:none;border-radius:4px;box-shadow:0 4px 32px rgba(0,0,0,.45);display:block}
.infographic-result-wrap{border:1px solid var(--border);border-radius:14px;overflow:hidden}
.ir-toolbar{background:var(--surface);padding:10px 16px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}
.ir-label{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.ir-dl-btn{font-size:11px;font-weight:600;padding:5px 12px;border-radius:6px;border:1px solid var(--border);background:transparent;color:var(--charcoal);cursor:pointer;transition:background .15s}
.ir-dl-btn:hover{background:var(--border)}
.ir-frame-wrap{background:#1a1a1a;padding:24px;display:flex;justify-content:center;overflow-x:auto}
.ir-frame{width:794px;max-width:100%;height:1123px;border:none;border-radius:4px;box-shadow:0 4px 32px rgba(0,0,0,.45);display:block}

/* ── Page transition overlay ─────────────────────────────────── */
#lpTransitionOverlay{
  position:fixed;inset:0;z-index:99999;
  background:#0A0A0A;
  opacity:0;pointer-events:none;
  transition:opacity .2s ease;
}
#lpTransitionOverlay.lp-t-in{opacity:1;pointer-events:all}
#lpTransitionOverlay::after{
  content:'';position:absolute;inset:0;
  background:radial-gradient(ellipse at 50% 50%,color-mix(in srgb, var(--green) 6%, transparent) 0%,transparent 55%);
  opacity:0;transition:opacity .2s ease;
}
#lpTransitionOverlay.lp-t-in::after{opacity:1}

/* ══════════════════════════════════════════════════════════════
   LEGAL PAGES — /terms /privacy /refund-policy /cookie-policy
                  /security /contact /about
   ══════════════════════════════════════════════════════════════ */
.lp-legal-wrap{min-height:100vh;display:flex;flex-direction:column;background:var(--lp-bg)}
.lp-legal-nav{padding:0 28px;height:64px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--lp-border);flex-shrink:0}
.lp-legal-nav-logo{display:flex;align-items:center;gap:9px;text-decoration:none}
.lp-legal-nav-logo img{width:30px;height:30px;object-fit:contain}
.lp-legal-nav-logo span{font-size:14px;font-weight:700;color:var(--lp-white);letter-spacing:-.2px}
.lp-legal-nav-back{font-size:13px;color:var(--lp-muted);transition:color .15s;display:flex;align-items:center;gap:6px}
.lp-legal-nav-back:hover{color:var(--lp-white)}
.lp-legal-content{flex:1;padding:60px 28px 80px}
.lp-legal-inner{max-width:720px;margin:0 auto}
.lp-legal-header{margin-bottom:48px;padding-bottom:32px;border-bottom:1px solid var(--lp-border)}
.lp-legal-header h1{font-family:'Instrument Serif',serif;font-size:40px;font-weight:400;color:var(--lp-white);letter-spacing:-.5px;line-height:1.1;margin-bottom:8px}
.lp-legal-date{font-size:13px;color:var(--lp-muted2)}
.lp-legal-section{margin-bottom:36px}
.lp-legal-section h2{font-size:15px;font-weight:700;color:var(--lp-white);letter-spacing:-.2px;margin-bottom:10px}
.lp-legal-section p{font-size:14px;color:var(--lp-muted);line-height:1.8;margin-bottom:8px}
.lp-legal-section ul,.lp-legal-section ol{padding-left:20px;display:flex;flex-direction:column;gap:6px;margin-top:8px}
.lp-legal-section li{font-size:14px;color:var(--lp-muted);line-height:1.75}
.lp-legal-highlight{background:color-mix(in srgb, var(--green) 4%, transparent);border:1px solid color-mix(in srgb, var(--green) 12%, transparent);border-radius:12px;padding:18px 20px;margin:16px 0}
.lp-legal-highlight p{font-size:14px;color:var(--lp-muted);line-height:1.75;margin:0}
.lp-legal-email{color:var(--green);font-weight:600}
.lp-legal-email:hover{color:var(--lp-white)}
.lp-legal-footer{padding:20px 28px;border-top:1px solid var(--lp-border)}
.lp-legal-footer-inner{max-width:720px;margin:0 auto;font-size:12px;color:var(--lp-muted2)}
/* Contact page */
.lp-contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:16px 0}
.lp-contact-card{background:var(--lp-bg2);border:1px solid var(--lp-border);border-radius:14px;padding:22px 24px}
.lp-contact-card-lbl{font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--lp-muted2);margin-bottom:8px}
.lp-contact-card-val{font-size:14px;color:var(--lp-white);line-height:1.6}
.lp-contact-card-val a{color:var(--green);transition:color .15s}
.lp-contact-card-val a:hover{color:var(--lp-white)}
/* About page */
.lp-about-stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:20px 0}
.lp-about-stat{background:var(--lp-bg2);border:1px solid var(--lp-border);border-radius:14px;padding:22px 24px;text-align:center}
.lp-about-stat-num{font-family:'Instrument Serif',serif;font-size:36px;font-weight:400;color:var(--green);letter-spacing:-.5px;line-height:1}
.lp-about-stat-lbl{font-size:12px;color:var(--lp-muted2);margin-top:6px}
@media(max-width:600px){
  .lp-legal-header h1{font-size:30px}
  .lp-contact-grid{grid-template-columns:1fr}
  .lp-about-stat-row{grid-template-columns:1fr}
}

/* ── Creative Infrastructure marquee section ────────────────── */
.lp-infra {
  padding: 48px 0 72px;
  border-top: 1px solid var(--lp-border);
  overflow: hidden;
}

/* Marquee wrapper — clips the infinite track */
.lp-mq-wrap {
  overflow: hidden;
  margin-bottom: 14px;
}
.lp-mq-wrap:last-child { margin-bottom: 0; }

/* Track — one long flex row, sized to content */
.lp-mq-track {
  display: flex;
  align-items: center;
  gap: 12px;
  width: max-content;
  will-change: transform;
}

/* Animations */
@keyframes lpMqRtl {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
@keyframes lpMqLtr {
  from { transform: translateX(-50%); }
  to   { transform: translateX(0); }
}
.lp-mq-rtl { animation: lpMqRtl 65s linear infinite; }
.lp-mq-ltr { animation: lpMqLtr 120s linear infinite; }

/* Pill base */
.lp-mq-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 46px;
  padding: 0 22px;
  border-radius: 100px;
  border: 1px solid var(--lp-border);
  background: rgba(255,255,255,.03);
  font-size: 14px;
  font-weight: 500;
  color: var(--lp-white);
  white-space: nowrap;
  flex-shrink: 0;
  letter-spacing: -.01em;
  transition: border-color .18s;
  cursor: default;
  user-select: none;
}
.lp-mq-pill:hover { border-color: rgba(255,255,255,.22); }

/* Systems pills — slightly elevated surface, icon in green */
.lp-mq-pill-sys {
  background: rgba(255,255,255,.04);
  border-color: rgba(255,255,255,.1);
}
.lp-mq-pill-sys:hover { border-color: var(--lp-green); }

/* Sparkle icon */
.lp-mq-icon {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  color: var(--lp-green);
  opacity: 0.7;
}

/* Accessibility: respect reduced motion */
@media (prefers-reduced-motion: reduce) {
  .lp-mq-rtl,
  .lp-mq-ltr { animation-play-state: paused; }
}

/* ── Infra header + flow separator ─────────────────────────── */
.lp-infra-hdr {
  text-align:center;
  padding:0 24px 44px;
  max-width:560px;
  margin:0 auto;
}
.lp-infra-title {
