}

/* ══════════════════════════════════════════════════════════════
   VIDEO ADS — Yellow/Gold identity
   Distinct from all other Oriven tools (green = brand/visuals/UGC)
   ══════════════════════════════════════════════════════════════ */

/* ── Create card ──────────────────────────────────────────────── */
.cr-card-videoads {
  background: linear-gradient(140deg, #191508, #15120a);
  border-color: rgba(240,180,41,.22);
}
.cr-card-videoads .cr-card-ico {
  background: rgba(240,180,41,.09);
  border-radius: 11px;
  border: 1px solid rgba(240,180,41,.18);
}
.cr-card-videoads .cr-card-ico svg { stroke: #F0B429; fill: none; }
.cr-card-videoads .cr-card-chip {
  background: rgba(240,180,41,.09);
  color: rgba(240,180,41,.85);
}
.cr-card-videoads:hover { border-color: rgba(240,180,41,.45); box-shadow: 0 0 0 1px rgba(240,180,41,.12); }

/* ── Overlay panel ────────────────────────────────────────────── */
.va-panel {
  max-width: 560px;
  width: 100%;
}

/* Topbar pill override — gold instead of green */
.va-panel .cf-type-pill { border-color: rgba(240,180,41,.25); background: rgba(240,180,41,.06); }
.va-panel .cf-type-icon svg { stroke: #F0B429; }
.va-panel .cf-type-label { color: #F0B429; }

/* Back button */
.va-back-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  border-radius: 7px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all .14s;
}
.va-back-btn:hover { color: var(--text); border-color: rgba(240,180,41,.4); }
.va-topbar-right { display: flex; align-items: center; gap: 8px; }

/* ── Shared phase wrapper ─────────────────────────────────────── */
.va-phase {
  padding: 24px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ── Phase 1: Mode selection ──────────────────────────────────── */
.va-phase-header { margin-bottom: 20px; }
.va-phase-title {
  font-size: 16px;
  font-weight: 650;
  color: var(--text);
  letter-spacing: -.35px;
  margin: 0 0 4px;
}
.va-phase-sub {
  font-size: 13px;
  color: var(--muted);
  margin: 0;
}
.va-modes { display: flex; flex-direction: column; gap: 10px; }
.va-mode-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1px solid var(--border);
  border-radius: 12px;
  cursor: pointer;
  background: var(--bg2, #111);
  transition: border-color .14s, background .14s;
  position: relative;
}
.va-mode-card:hover {
  border-color: rgba(240,180,41,.42);
  background: rgba(240,180,41,.04);
}
.va-mode-card.va-mode-recommended { border-color: rgba(240,180,41,.28); }
.va-mode-icon {
  width: 38px;
  height: 38px;
  border-radius: 9px;
  background: rgba(240,180,41,.09);
  border: 1px solid rgba(240,180,41,.18);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.va-mode-icon svg { stroke: #F0B429; }
.va-mode-body { flex: 1; min-width: 0; }
.va-mode-name {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -.2px;
}
.va-mode-desc {
  font-size: 12px;
  color: var(--muted);
  margin-top: 2px;
  line-height: 1.5;
}
.va-mode-badge {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .4px;
  color: #F0B429;
  background: rgba(240,180,41,.10);
  border: 1px solid rgba(240,180,41,.22);
  padding: 3px 8px;
  border-radius: 20px;
  white-space: nowrap;
  flex-shrink: 0;
}
.va-mode-arrow {
  color: var(--muted);
  flex-shrink: 0;
  opacity: .5;
  transition: opacity .14s, transform .14s;
}
.va-mode-card:hover .va-mode-arrow { opacity: 1; transform: translateX(2px); }

/* ── Phase 2: Forms ───────────────────────────────────────────── */
.va-form { display: flex; flex-direction: column; gap: 18px; }
.va-form-row { display: flex; flex-direction: column; gap: 7px; }
.va-label {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -.1px;
}
.va-input,
.va-textarea {
  width: 100%;
  background: var(--bg2, #111);
  border: 1px solid var(--border);
  border-radius: 9px;
  padding: 10px 13px;
  font-size: 13.5px;
  color: var(--text);
  font-family: inherit;
  box-sizing: border-box;
  transition: border-color .14s;
  outline: none;
  resize: vertical;
}
.va-input:focus,
.va-textarea:focus { border-color: rgba(240,180,41,.5); box-shadow: 0 0 0 3px rgba(240,180,41,.08); }
.va-input::placeholder,
.va-textarea::placeholder { color: var(--muted); opacity: .6; }
.va-input-hint {
  font-size: 11.5px;
  color: var(--muted);
  margin: 0;
  line-height: 1.5;
}

/* Pill selectors */
.va-pill-select {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.va-pill-opt {
  padding: 6px 13px;
  border-radius: 20px;
  background: var(--bg2, #111);
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: all .14s;
  font-family: inherit;
}
.va-pill-opt:hover {
  color: var(--text);
  border-color: rgba(240,180,41,.35);
}
.va-pill-opt.active {
  background: rgba(240,180,41,.10);
  border-color: rgba(240,180,41,.45);
  color: #F0B429;
  font-weight: 600;
}

/* Presets row */
.va-presets-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.va-preset-btn {
  padding: 5px 11px;
  border-radius: 7px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: 12px;
  cursor: pointer;
  transition: all .14s;
  font-family: inherit;
}
.va-preset-btn:hover {
  border-color: rgba(240,180,41,.35);
  color: var(--text);
  background: rgba(240,180,41,.05);
}

/* Generate CTA */
.va-form-actions { margin-top: 4px; }
.va-generate-btn {
  width: 100%;
  padding: 13px 20px;
  background: #F0B429;
  color: #0A0A0A;
  font-size: 14px;
  font-weight: 700;
  font-family: inherit;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  letter-spacing: -.2px;
  transition: background .14s, opacity .14s;
}
.va-generate-btn:hover { background: #F7C24A; }
.va-generate-btn:active { opacity: .88; }

/* ── Phase 3: Generation status ───────────────────────────────── */
.va-body {
  padding: 20px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.va-status-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 28px 0 12px;
  text-align: center;
}
.va-spinner { margin-bottom: 4px; }
.va-spinner .spin {
  width: 36px;
  height: 36px;
  border-width: 2.5px;
  border-color: rgba(240,180,41,.20);
  border-top-color: #F0B429;
  border-style: solid;
  border-radius: 50%;
  animation: spin .9s linear infinite;
  margin: 0 auto;
}
.va-status-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -.3px;
}
.va-status-error { color: #f87171; }
.va-status-sub {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.65;
  max-width: 320px;
}
.va-audio-note {
  font-size: 11.5px;
  color: var(--muted);
  background: rgba(255,255,255,.03);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 12px;
  text-align: center;
  max-width: 320px;
}
.va-video-frame {
  border-radius: 10px;
  overflow: hidden;
  background: #000;
  aspect-ratio: 16 / 9;
  width: 100%;
}
.va-video-el {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}
.va-dl-hint {
  font-size: 12px;
  color: var(--muted);
  text-align: center;
  margin: 6px 0 0;
}

/* ══════════════════════════════════════════════════════════════
   PRODUCT SHOOTS — Red identity
   Distinct from all other tools (green=brand, gold=video, red=shoots)
   ══════════════════════════════════════════════════════════════ */

/* ── Create card ──────────────────────────────────────────────── */
.cr-card-shoots {
  background: linear-gradient(140deg, #1a0808, #150505);
  border-color: rgba(232,64,64,.22);
}
.cr-card-shoots .cr-card-ico {
  background: rgba(232,64,64,.09);
  border-radius: 11px;
  border: 1px solid rgba(232,64,64,.18);
}
.cr-card-shoots .cr-card-ico svg { stroke: #E84040; fill: none; }
.cr-card-shoots .cr-card-chip {
  background: rgba(232,64,64,.09);
  color: rgba(232,64,64,.85);
}
.cr-card-shoots:hover { border-color: rgba(232,64,64,.45); box-shadow: 0 0 0 1px rgba(232,64,64,.12); }

/* ── Result overlay ───────────────────────────────────────────── */
.ps-panel {
  max-width: 600px;
  width: 100%;
}
.ps-panel .cf-type-pill { border-color: rgba(232,64,64,.25); background: rgba(232,64,64,.06); }
.ps-panel .cf-type-icon svg { stroke: #E84040; }
.ps-panel .cf-type-label { color: #E84040; }

.ps-body {
  padding: 24px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.ps-status-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 28px 0 12px;
  text-align: center;
}
.ps-spinner { margin-bottom: 4px; }
.ps-spinner .spin {
  width: 36px;
  height: 36px;
  border-width: 2.5px;
  border-color: rgba(232,64,64,.20);
  border-top-color: #E84040;
  border-style: solid;
  border-radius: 50%;
  animation: spin .9s linear infinite;
  margin: 0 auto;
}
.ps-status-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -.3px;
}
.ps-status-error { color: #f87171; }
.ps-status-sub {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.65;
  max-width: 320px;
}

/* Image result grid */
.ps-result-wrap { display: flex; flex-direction: column; gap: 12px; }
.ps-image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 12px;
}
.ps-image-item {
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  background: #000;
  aspect-ratio: 1;
}
.ps-image-item.ps-ratio-landscape { aspect-ratio: 16 / 9; }
.ps-image-item.ps-ratio-portrait  { aspect-ratio: 4 / 5; }
.ps-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.ps-dl-btn {
  position: absolute;
  bottom: 8px;
  right: 8px;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  background: rgba(0,0,0,.75);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 7px;
  color: #fff;
  font-size: 11px;
  font-weight: 500;
  text-decoration: none;
  backdrop-filter: blur(4px);
  opacity: 0;
  transition: opacity .15s;
}
.ps-image-item:hover .ps-dl-btn { opacity: 1; }
.ps-dl-hint {
  font-size: 12px;
  color: var(--muted);
  text-align: center;
  margin: 0;
}


/* ═══════════════════════════════════════════════════════════════
   CREATE PAGE — Card Grid
   ═══════════════════════════════════════════════════════════════ */

.cr2-wrap {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 28px 24px 80px;
}

/* ── No Brand Core ─────────────────────────────────────────────── */
.cr2-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 72px 24px;
}

.cr2-empty-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--green) 6%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 15%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}
.cr2-empty-icon svg { stroke: color-mix(in srgb, var(--green) 60%, transparent); }

.cr2-empty-h {
  font-size: 22px;
  font-weight: 700;
  color: rgba(255,255,255,.88);
  letter-spacing: -.4px;
  margin: 0 0 10px;
  max-width: 380px;
  line-height: 1.25;
}

.cr2-empty-sub {
  font-size: 14px;
  color: rgba(255,255,255,.35);
  margin: 0 0 28px;
  line-height: 1.55;
}

.cr2-empty-pillars {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  margin-bottom: 36px;
}
.cr2-empty-pillars span {
  padding: 5px 14px;
  border-radius: 20px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  font-size: 12px;
  color: rgba(255,255,255,.38);
  font-weight: 500;
}

.cr2-empty-btn {
  padding: 13px 34px;
  border-radius: 100px;
  background: var(--green);
  color: #0A0A0C;
  font-size: 14px;
  font-weight: 700;
  border: none;
  cursor: pointer;
  letter-spacing: .01em;
  transition: opacity .15s, transform .18s cubic-bezier(.16,1,.3,1);
}
.cr2-empty-btn:hover { opacity: .88; transform: translateY(-2px); }

/* ── Brand Core header bar ─────────────────────────────────────── */
.cr2-brand-bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  background: color-mix(in srgb, var(--green) 3%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 10%, transparent);
  border-radius: 16px;
  padding: 22px 24px;
  margin-bottom: 36px;
}

.cr2-brand-main { flex: 1; min-width: 0; }

.cr2-brand-eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 9px;
  flex-wrap: wrap;
}

.cr2-brand-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 18%, transparent);
  flex-shrink: 0;
  animation: dashDotPulse 2.5s ease-in-out infinite;
}

.cr2-brand-status-txt {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 62%, transparent);
}

.cr2-bc-badge {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: rgba(255,255,255,.28);
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 20px;
  padding: 2px 9px;
}

.cr2-brand-name {
  font-size: 26px;
  font-weight: 700;
  color: rgba(255,255,255,.92);
  letter-spacing: -.5px;
  margin-bottom: 9px;
  line-height: 1.1;
}

.cr2-brand-desc {
  font-size: 13px;
  color: rgba(255,255,255,.28);
  line-height: 1.65;
  margin: 0;
  max-width: 560px;
}

.cr2-brand-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
  flex-shrink: 0;
  padding-top: 3px;
}
.cr2-upd-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: rgba(255,255,255,.18);
}
.cr2-upd-val {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255,255,255,.45);
}

/* ── Tools section ─────────────────────────────────────────────── */
.cr2-tools { margin-bottom: 48px; }

.cr2-section-h {
  font-size: 16px;
  font-weight: 700;
  color: rgba(255,255,255,.6);
  letter-spacing: -.2px;
  margin: 0 0 16px;
}

/* ── Card grid ─────────────────────────────────────────────────── */
.cr2-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

/* ── Cards ─────────────────────────────────────────────────────── */
.cr2-card {
  display: flex;
  flex-direction: column;
  gap: 9px;
  background: rgba(255,255,255,.025);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 14px;
  padding: 18px;
  cursor: pointer;
  text-align: left;
  transition: background .2s, border-color .2s, box-shadow .2s, transform .22s cubic-bezier(.16,1,.3,1);
}
.cr2-card:not(.cr2-card-soon):hover {
  background: rgba(255,255,255,.046);
  border-color: color-mix(in srgb, var(--green) 20%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--green) 7%, transparent), 0 8px 28px rgba(0,0,0,.22);
  transform: translateY(-2px);
}

.cr2-card-ico {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.07);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background .2s, border-color .2s;
}
.cr2-card-ico svg {
  width: 18px;
  height: 18px;
  stroke: rgba(255,255,255,.42);
  transition: stroke .2s;
}
.cr2-card:not(.cr2-card-soon):hover .cr2-card-ico {
  background: color-mix(in srgb, var(--green) 7%, transparent);
  border-color: color-mix(in srgb, var(--green) 20%, transparent);
}
.cr2-card:not(.cr2-card-soon):hover .cr2-card-ico svg { stroke: color-mix(in srgb, var(--green) 82%, transparent); }

.cr2-card-title {
  font-size: 14px;
  font-weight: 700;
  color: rgba(255,255,255,.78);
  letter-spacing: -.2px;
  transition: color .2s;
}
.cr2-card:not(.cr2-card-soon):hover .cr2-card-title { color: rgba(255,255,255,.96); }

.cr2-card-desc {
  font-size: 12px;
  color: rgba(255,255,255,.28);
  line-height: 1.5;
  flex: 1;
  transition: color .2s;
}
.cr2-card:not(.cr2-card-soon):hover .cr2-card-desc { color: rgba(255,255,255,.42); }

.cr2-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 2px;
  padding-top: 10px;
  border-top: 1px solid rgba(255,255,255,.05);
}

.cr2-powered {
  font-size: 10.5px;
  color: rgba(255,255,255,.18);
  font-weight: 500;
  transition: color .2s;
}
.cr2-powered .cr2-brand-ref {
  color: color-mix(in srgb, var(--green) 38%, transparent);
  font-weight: 600;
  transition: color .2s;
}
.cr2-card:not(.cr2-card-soon):hover .cr2-powered { color: rgba(255,255,255,.26); }
.cr2-card:not(.cr2-card-soon):hover .cr2-powered .cr2-brand-ref { color: color-mix(in srgb, var(--green) 68%, transparent); }

.cr2-credits {
  font-size: 10.5px;
  font-weight: 600;
  color: rgba(255,255,255,.22);
  opacity: 0;
  transition: opacity .18s;
  white-space: nowrap;
}
.cr2-card:not(.cr2-card-soon):hover .cr2-credits { opacity: 1; }

/* ── Coming Soon section ───────────────────────────────────────── */
.cr2-coming { padding-top: 4px; }

.cr2-coming-hd { margin-bottom: 16px; }

.cr2-coming-title {
  font-size: 14px;
  font-weight: 700;
  color: rgba(255,255,255,.32);
  letter-spacing: -.15px;
  margin: 0 0 4px;
}

.cr2-coming-sub {
  font-size: 12px;
  color: rgba(255,255,255,.18);
  margin: 0;
  line-height: 1.5;
}

.cr2-card-soon {
  opacity: .4;
  cursor: default;
  pointer-events: none;
}

.cr2-soon-badge {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: rgba(255,255,255,.25);
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 20px;
  padding: 3px 10px;
}
.cr2-exp-badge {
  display: inline-block;
  vertical-align: middle;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .07em;
