/* ══════════════════════════════════════════════════════════════════
   MOBILE & TABLET RESPONSIVE OVERHAUL
   Supplements the existing mobile blocks — no duplication intended.
   ══════════════════════════════════════════════════════════════════ */

/* ── Global: prevent horizontal overflow on all viewports ──────── */
html { overflow-x: hidden; }
body { overflow-x: hidden; max-width: 100%; }

/* ── #mobileBar and .mb-wordmark CSS is defined in the main hamburger block ── */

/* ══ TABLET LANDSCAPE (≤1024px) ════════════════════════════════════ */
@media (max-width: 1024px) {
  .dash-outer { padding: 20px 24px 14px; }
}

/* ══ MOBILE (≤768px) — additions to existing 768px block ══════════ */
@media (max-width: 768px) {

  /* ── Overflow prevention ── */
  .app, .mc, .page { overflow-x: hidden; }

  /* ── Create page: top clearance for mobile bar ── */
  .cr2-wrap { padding-top: 64px; }

  /* ── Paywall modal: full viewport height safety ── */
  .pw-modal {
    max-height: 90vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    border-radius: 20px;
  }
  .pw-header { padding: 24px 20px 18px; }
  .pw-grid   { padding: 16px 16px 12px; }

  /* ── Auth overlay: scrollable on small screens ── */
  #authOverlay {
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    align-items: flex-start;
  }

  /* ── All modals: bottom-sheet on mobile ── */
  .mbk {
    align-items: flex-end;
  }
  .modal {
    width: 100% !important;
    max-width: 100% !important;
    margin: 0;
    border-radius: 20px 20px 0 0;
    max-height: 92vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 24px;
  }

  /* ── Touch targets: 44px minimum for all interactive controls ── */
  .btn, .btn-primary, .btn-outline, .btn-ghost,
  .pw-btn, .au-btn { min-height: 44px; }
  .ob-tt-next, .ob-tt-back { min-height: 40px; }

  /* ── Brand assistant: use full width ── */
  .chat-outer { padding: 0 8px; }

  /* ── Onboarding tooltip: crisp on mobile (bottom-sheet via JS) ── */
  #ob-tooltip { border-radius: 20px; }

  /* ── Landing page: hero actions stack vertically on mobile ── */
  .lp-s-actions { flex-direction: column; gap: 10px; }
  .lp-s-actions .lp-cta-btn,
  .lp-s-actions .lp-ghost-btn { width: 100%; justify-content: center; }

  /* ── Landing page: hamburger touch target 44px ── */
  .lp-hamburger { padding: 11px; }

  /* ── Dashboard: stack hero band on mobile ── */
  .dash-hero-band { grid-template-columns: 1fr; }
  .dash-lower     { grid-template-columns: 1fr; }

  /* ── Settings: ensure nav items have touch targets ── */
  .snav-item { min-height: 36px; display: flex; align-items: center; }

}

/* ══ SMALL MOBILE (≤480px) ═════════════════════════════════════════ */
@media (max-width: 480px) {

  /* ── Create page: tight on small phones ── */
  .cr2-wrap { padding: 64px 12px 60px; }

  /* ── Dashboard: single-column stats on small phones ── */
  .dash-stats-row { grid-template-columns: 1fr; }

  /* ── Paywall: compact header ── */
  .pw-title  { font-size: 20px; }
  .pw-sub    { font-size: 12px; }
  .pw-card   { padding: 18px 14px; }

  /* ── Plan popular tag: already tiny at 480px via existing CSS ── */

  /* ── Onboarding tooltip: tighter on small phones ── */
  #ob-tooltip { padding: 16px 16px 14px; }
  .ob-tt-title { font-size: 15px; }
  .ob-tt-desc  { font-size: 13px; }
  .ob-tt-dot   { width: 5px; height: 5px; }

  /* ── Dashboard hero band ── */
  .dash-hero-band { padding: 16px; }

  /* ── Settings nav: wrap more aggressively ── */
  .snav-item { font-size: 11px; padding: 4px 8px; }

  /* ── Modal: tighter padding ── */
  .modal { padding: 20px 16px 24px; }

  /* ── Auth form: full bleed on tiny screens ── */
  .au-inner { padding: 24px 16px; }

}

/* ══ VERY SMALL (≤375px) ═══════════════════════════════════════════ */
@media (max-width: 375px) {

  /* ── Onboarding dots: scale down ── */
  .ob-tt-dots { gap: 4px; }
  .ob-tt-dot  { width: 4px; height: 4px; }
  .ob-tt-next { font-size: 13px; padding: 8px 12px; }
  .ob-tt-back { font-size: 13px; }

  /* ── Plan card compact ── */
  .pw-card { padding: 16px 12px; }
  .pw-plan-name { font-size: 15px; }

}

/* ══ SAFE-AREA SUPPORT (supplements existing @supports blocks) ═════ */
@supports (padding-top: env(safe-area-inset-top)) {
  @media (max-width: 768px) {
    /* Auth overlay pushed below notch */
    #authOverlay { padding-top: calc(env(safe-area-inset-top) + 24px) !important; }
    /* Mobile bar and sidebar safe-area handled in the main safe-area block above */
  }
}

@supports (padding-bottom: env(safe-area-inset-bottom)) {
  @media (max-width: 768px) {
    .modal       { padding-bottom: calc(env(safe-area-inset-bottom) + 24px); }
    .mc          { padding-bottom: env(safe-area-inset-bottom); }
    #ob-tooltip  { bottom: calc(env(safe-area-inset-bottom) + 80px) !important; }
  }
}

