.bb-metric-lbl{font-size:10.5px;color:var(--muted)}

/* Sections */
.bb-section{display:flex;flex-direction:column;gap:14px}
.bb-section-hd{display:flex;align-items:center}
.bb-section-label{font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--muted2,rgba(255,255,255,.3))}

/* Snapshot */
.bb-snapshot{display:flex;flex-wrap:wrap;gap:8px}
.bb-snapshot-empty{font-size:13px;color:var(--muted);padding:20px 24px;background:var(--surface);border:1px solid var(--border);border-radius:14px;width:100%}
.bb-snapshot-cta{color:var(--gm);cursor:pointer;font-weight:500}
.bb-snapshot-cta:hover{text-decoration:underline}
.bb-know-chip{display:inline-flex;align-items:center;gap:7px;padding:8px 13px;border-radius:11px;background:var(--surface);border:1px solid var(--border);font-size:12px;color:var(--charcoal)}
.bb-know-chip-dot{width:6px;height:6px;border-radius:50%;flex-shrink:0}
.bb-know-chip-dot.filled{background:var(--gm)}
.bb-know-chip-dot.empty{background:rgba(255,255,255,.15)}
.bb-know-chip-lbl{color:var(--muted);font-size:10px;font-weight:600;letter-spacing:.04em;text-transform:uppercase}
.bb-know-chip-val{font-weight:500;max-width:120px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bb-know-swatches{display:flex;gap:4px;align-items:center}
.bb-know-swatch{width:15px;height:15px;border-radius:50%;border:1px solid rgba(255,255,255,.12)}

/* Actions */
.bb-actions{display:flex;flex-direction:column;gap:8px}
.bb-action-item{display:flex;align-items:center;gap:14px;background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px 16px;cursor:pointer;transition:border-color .2s,transform .18s}
.bb-action-item:hover{border-color:var(--gm);transform:translateX(3px)}
.bb-action-ico{width:32px;height:32px;border-radius:9px;background:color-mix(in srgb, var(--green) 8%, transparent);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.bb-action-ico svg{width:13px;height:13px;stroke:var(--gm);fill:none;stroke-width:1.5;stroke-linecap:round}
.bb-action-body{flex:1;min-width:0}
.bb-action-title{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:2px}
.bb-action-desc{font-size:11px;color:var(--muted);line-height:1.4}
.bb-action-arrow{color:var(--muted);font-size:15px;opacity:.35;flex-shrink:0}

/* Coming soon grid */
.bb-coming-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.bb-coming-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:18px;opacity:.6}
.bb-coming-hd{display:flex;align-items:center;gap:9px;margin-bottom:8px;font-size:13px;font-weight:600;color:var(--charcoal)}
.bb-coming-hd svg{stroke:var(--muted);flex-shrink:0}
.bb-coming-badge{margin-left:auto;font-size:8.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:2px 8px;border-radius:20px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);color:var(--muted2,rgba(255,255,255,.35));flex-shrink:0}
.bb-coming-card p{font-size:11.5px;color:var(--muted);line-height:1.6;margin:0}

/* Mobile */
@media(max-width:768px){
  .bb-outer{padding:calc(56px + env(safe-area-inset-top,0px) + 28px) 16px 48px;gap:28px}
  .bb-top-row{grid-template-columns:1fr}
  .bb-health-card{display:flex;align-items:center;gap:20px;text-align:left}
  .bb-health-score-wrap{flex-shrink:0}
  .bb-coming-grid{grid-template-columns:1fr}
  .sb-section{padding-top:10px}
}


/* =================================================================
   ORIVEN 2.0 — BRAND SUB-PAGES (.bsp-*)
   Shared layout for Positioning / Audience / Tov / Identity
   ================================================================= */

#page-positioning,#page-audience,#page-tov,#page-identity{display:none;overflow-y:auto}
#page-positioning.active,#page-audience.active,#page-tov.active,#page-identity.active{display:block}

.bsp-outer{max-width:800px;margin:0 auto;padding:40px 32px 64px}

/* Breadcrumb + top-right edit button */
.bsp-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}
.bsp-breadcrumb{display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--muted)}
.bsp-bc-link{cursor:pointer;color:var(--muted);transition:color .15s}
.bsp-bc-link:hover{color:var(--charcoal)}
.bsp-bc-sep{opacity:.4}
.bsp-edit-btn{
  font-size:11px;font-weight:600;color:var(--muted);
  background:var(--surface);border:1px solid var(--border);
  border-radius:8px;padding:6px 12px;cursor:pointer;
  transition:border-color .15s,color .15s;
}
.bsp-edit-btn:hover{border-color:rgba(255,255,255,.18);color:var(--charcoal)}

.bsp-title{
  font-family:'Instrument Serif',serif;font-size:clamp(28px,3.5vw,44px);
  font-weight:400;color:var(--charcoal);letter-spacing:-1.2px;margin-bottom:10px;
}
.bsp-desc{font-size:13.5px;color:var(--muted);line-height:1.65;margin-bottom:32px;max-width:520px}

/* Body content area */
.bsp-body{display:flex;flex-direction:column;gap:16px}

/* Generic field card */
.bsp-card{
  background:var(--surface);border:1px solid var(--border);
  border-radius:16px;padding:24px 26px;
  transition:border-color .2s;
}
.bsp-card:hover{border-color:rgba(255,255,255,.14)}
.bsp-card-lbl{
  font-size:9.5px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--muted2,rgba(255,255,255,.3));margin-bottom:10px;
}
.bsp-card-val{font-size:15px;color:var(--charcoal);line-height:1.65;font-weight:400}
.bsp-card-val.large{font-size:18px;font-weight:500;letter-spacing:-.3px;line-height:1.5}

/* Two-column card grid */
.bsp-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.bsp-grid .bsp-card{margin:0}

/* Tag list (tone traits, personality) */
.bsp-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:4px}
.bsp-tag{
  display:inline-flex;align-items:center;
  font-size:12.5px;font-weight:500;color:var(--charcoal);
  background:var(--bg);border:1px solid var(--border);
  border-radius:20px;padding:6px 14px;
}
.bsp-tag.accent{background:color-mix(in srgb, var(--green) 8%, transparent);border-color:color-mix(in srgb, var(--green) 25%, transparent);color:var(--gm)}

/* Color palette row */
.bsp-colors{display:flex;flex-direction:column;gap:10px}
.bsp-color-row{
  display:flex;align-items:center;gap:14px;
  background:var(--bg);border-radius:12px;padding:12px 14px;
}
.bsp-color-swatch{
  width:40px;height:40px;border-radius:10px;flex-shrink:0;
  border:1px solid rgba(255,255,255,.12);
  box-shadow:0 2px 8px rgba(0,0,0,.25);
}
.bsp-color-info{flex:1;min-width:0}
.bsp-color-name{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:1px}
.bsp-color-hex{font-size:11px;color:var(--muted);font-family:monospace;letter-spacing:.04em}
.bsp-color-role{
  font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  color:var(--muted2,rgba(255,255,255,.3));padding:3px 8px;
  background:rgba(255,255,255,.06);border-radius:20px;flex-shrink:0;
}

/* Typography rows */
.bsp-fonts{display:flex;flex-direction:column;gap:10px}
.bsp-font-row{
  background:var(--bg);border-radius:12px;padding:16px 18px;
  display:flex;align-items:baseline;gap:14px;flex-wrap:wrap;
}
.bsp-font-sample{font-size:22px;color:var(--charcoal);letter-spacing:-.4px;flex:1;min-width:120px}
.bsp-font-meta{display:flex;flex-direction:column;gap:2px;flex-shrink:0}
.bsp-font-name{font-size:12px;font-weight:600;color:var(--charcoal)}
.bsp-font-role{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}

/* Logo display */
.bsp-logos{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.bsp-logo-box{
  background:var(--bg);border:1px solid var(--border);
  border-radius:14px;padding:20px;
  display:flex;flex-direction:column;align-items:center;gap:10px;min-height:100px;
}
.bsp-logo-img{max-width:100%;max-height:60px;object-fit:contain}
.bsp-logo-lbl{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}

/* Do / Don't tone rules */
.bsp-rules{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.bsp-rule-col{display:flex;flex-direction:column;gap:8px}
.bsp-rule-hd{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;margin-bottom:4px}
.bsp-rule-hd.do{color:var(--gm)}
.bsp-rule-hd.dont{color:#f87171}
.bsp-rule-item{
  font-size:12.5px;color:var(--charcoal);line-height:1.5;
  padding:10px 12px;border-radius:10px;
  background:var(--bg);border-left:3px solid transparent;
}
.bsp-rule-item.do{border-color:var(--gm)}
.bsp-rule-item.dont{border-color:#f87171}

/* Empty state */
.bsp-empty{
  display:flex;flex-direction:column;align-items:center;text-align:center;
  padding:64px 32px;gap:14px;
}
.bsp-empty-icon{
  width:56px;height:56px;border-radius:16px;
  background:var(--surface);border:1px solid var(--border);
  display:flex;align-items:center;justify-content:center;margin-bottom:4px;
}
.bsp-empty-icon svg{width:26px;height:26px;stroke:var(--muted)}
.bsp-empty-title{font-size:16px;font-weight:600;color:var(--charcoal)}
.bsp-empty-sub{font-size:13px;color:var(--muted);max-width:360px;line-height:1.6}
.bsp-empty-btn{
  margin-top:6px;font-size:13px;font-weight:600;
  background:var(--gm);color:#111;
  border:none;border-radius:10px;padding:10px 22px;cursor:pointer;
  transition:opacity .15s;
}
.bsp-empty-btn:hover{opacity:.88}

/* Mobile */
@media(max-width:768px){
  .bsp-outer{padding:calc(56px + env(safe-area-inset-top,0px) + 24px) 16px 48px}
  .bsp-grid{grid-template-columns:1fr}
  .bsp-rules{grid-template-columns:1fr}
  .bsp-logos{grid-template-columns:1fr 1fr}
  .bsp-title{font-size:clamp(26px,7vw,38px)}
}


/* =================================================================
   ORIVEN 2.0 — INTELLIGENCE PAGES (.intel-*)
   Market Research + Opportunities
   ================================================================= */

#page-market,#page-opportunities{display:none;overflow-y:auto}
#page-market.active,#page-opportunities.active{display:block}

.intel-outer{max-width:860px;margin:0 auto;padding:40px 32px 64px}

/* Generate button (top-right of header) */
.intel-gen-btn{
  display:inline-flex;align-items:center;gap:7px;
  font-size:12px;font-weight:600;
  background:var(--gm);color:#111;
  border:none;border-radius:10px;padding:8px 16px;cursor:pointer;
  transition:opacity .15s,transform .12s;
}
.intel-gen-btn:hover{opacity:.88;transform:translateY(-1px)}
.intel-gen-btn svg{width:12px;height:12px;stroke:#111}
.intel-gen-btn:disabled{opacity:.4;cursor:default;transform:none}

/* ── Prompt / empty state ─────────────────────────────────────── */
.intel-prompt{padding:48px 0;display:flex;justify-content:center}
.intel-prompt-inner{
  max-width:420px;text-align:center;
  display:flex;flex-direction:column;align-items:center;gap:14px;
}
.intel-prompt-icon{
  width:64px;height:64px;border-radius:18px;
  background:var(--surface);border:1px solid var(--border);
  display:flex;align-items:center;justify-content:center;margin-bottom:4px;
}
.intel-prompt-icon svg{width:32px;height:32px;stroke:var(--muted)}
.intel-prompt-title{font-size:17px;font-weight:600;color:var(--charcoal)}
.intel-prompt-sub{font-size:13px;color:var(--muted);line-height:1.65}
.intel-prompt-btn{
  margin-top:6px;font-size:13px;font-weight:600;
  background:var(--gm);color:#111;
  border:none;border-radius:10px;padding:10px 22px;cursor:pointer;
  transition:opacity .15s;
}
.intel-prompt-btn:hover{opacity:.88}

/* ── Loading state ────────────────────────────────────────────── */
.intel-loading{
  display:flex;flex-direction:column;align-items:center;
  gap:16px;padding:80px 0;
}
.intel-loading-ring{
  width:32px;height:32px;border-radius:50%;
  border:2.5px solid rgba(255,255,255,.08);
  border-top-color:var(--gm);
  animation:spin .8s linear infinite;
}
.intel-loading-text{font-size:14px;color:var(--muted)}
.intel-loading-dots::after{
  content:"";animation:loadDots 1.4s steps(4,end) infinite;
}
@keyframes loadDots{
  0%{content:""}25%{content:"."}50%{content:".."}75%{content:"..."}100%{content:""}
}

/* ── Results shell ────────────────────────────────────────────── */
.intel-results{display:flex;flex-direction:column;gap:28px}
.intel-meta-row{
  display:flex;align-items:center;justify-content:space-between;
  margin-bottom:-8px;
}
.intel-meta-ts{font-size:11.5px;color:var(--muted)}
.intel-regen-btn{
  font-size:11px;font-weight:600;color:var(--muted);
  background:none;border:1px solid var(--border);
  border-radius:8px;padding:5px 11px;cursor:pointer;
  transition:border-color .15s,color .15s;
}
.intel-regen-btn:hover{border-color:rgba(255,255,255,.2);color:var(--charcoal)}

/* Section label */
.intel-section{display:flex;flex-direction:column;gap:12px}
.intel-section-label{
  font-size:9.5px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--muted2,rgba(255,255,255,.3));
}

/* ── Market overview band ─────────────────────────────────────── */
.intel-market-band{
  display:grid;grid-template-columns:repeat(4,1fr);gap:10px;
}
.intel-mkt-tile{
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:18px 16px;
}
.intel-mkt-tile-lbl{font-size:9.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:8px}
.intel-mkt-tile-val{font-size:14px;font-weight:600;color:var(--charcoal);line-height:1.3}
.intel-mkt-tile-val.pill{
  display:inline-block;font-size:11px;padding:3px 10px;border-radius:20px;
  background:color-mix(in srgb, var(--green) 10%, transparent);border:1px solid color-mix(in srgb, var(--green) 25%, transparent);color:var(--gm);
}

/* ── Trend grid (2-col) ───────────────────────────────────────── */
.intel-trend-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.intel-trend-card{
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:18px 20px;
}
.intel-trend-hd{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  margin-bottom:10px;
}
.intel-trend-title{font-size:13px;font-weight:600;color:var(--charcoal)}
.intel-impact{
  font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  padding:2px 7px;border-radius:20px;flex-shrink:0;
}
.intel-impact.high{background:color-mix(in srgb, var(--green) 10%, transparent);border:1px solid color-mix(in srgb, var(--green) 25%, transparent);color:var(--gm)}
.intel-impact.medium{background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.25);color:#fbbf24}
.intel-impact.low{background:rgba(255,255,255,.05);border:1px solid var(--border);color:var(--muted)}
.intel-trend-desc{font-size:12px;color:var(--muted);line-height:1.6}

/* ── Segment list ─────────────────────────────────────────────── */
.intel-seg-list{display:flex;flex-direction:column;gap:10px}
.intel-seg-row{
  display:flex;align-items:flex-start;gap:14px;
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:16px 18px;
}
.intel-seg-fit{
  flex-shrink:0;font-size:9px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  padding:4px 10px;border-radius:20px;margin-top:1px;
}
.intel-seg-fit.strong{background:color-mix(in srgb, var(--green) 10%, transparent);border:1px solid color-mix(in srgb, var(--green) 25%, transparent);color:var(--gm)}
.intel-seg-fit.medium{background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.25);color:#fbbf24}
.intel-seg-fit.weak{background:rgba(255,255,255,.05);border:1px solid var(--border);color:var(--muted)}
.intel-seg-body{flex:1;min-width:0}
.intel-seg-name{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:4px}
.intel-seg-desc{font-size:12px;color:var(--muted);line-height:1.55}

/* ── Competitive card ─────────────────────────────────────────── */
.intel-comp-card{
  background:var(--surface);border:1px solid var(--border);
  border-radius:16px;padding:22px 24px;
  display:flex;flex-direction:column;gap:14px;
}
.intel-comp-row{display:flex;align-items:center;gap:12px}
.intel-comp-intensity{
  font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  padding:3px 9px;border-radius:20px;
}
.intel-comp-intensity.high{background:rgba(239,68,68,.1);border:1px solid rgba(239,68,68,.25);color:#ef4444}
.intel-comp-intensity.medium{background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.25);color:#fbbf24}
.intel-comp-intensity.low{background:color-mix(in srgb, var(--green) 10%, transparent);border:1px solid color-mix(in srgb, var(--green) 25%, transparent);color:var(--gm)}
.intel-comp-lbl{font-size:11px;font-weight:600;color:var(--muted)}
.intel-comp-dynamics{font-size:13px;color:var(--charcoal);line-height:1.65}
.intel-comp-whitespace{
  background:color-mix(in srgb, var(--green) 6%, transparent);border:1px solid color-mix(in srgb, var(--green) 18%, transparent);
  border-radius:10px;padding:12px 14px;
  font-size:12.5px;color:var(--charcoal);line-height:1.55;
}
.intel-comp-ws-lbl{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--gm);margin-bottom:5px}

/* ── Summary card ─────────────────────────────────────────────── */
.intel-summary-card{
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:20px 24px;
  font-size:14px;color:var(--charcoal);line-height:1.7;
}

/* ── Opportunity list ─────────────────────────────────────────── */
.intel-opp-list{display:flex;flex-direction:column;gap:12px}
.intel-opp-card{
  background:var(--surface);border:1px solid var(--border);
  border-radius:16px;padding:20px 22px;
  transition:border-color .2s;
}
.intel-opp-card:hover{border-color:rgba(255,255,255,.14)}
.intel-opp-hd{
  display:flex;align-items:flex-start;gap:12px;margin-bottom:12px;
}
.intel-opp-num{
  width:24px;height:24px;border-radius:50%;flex-shrink:0;
  background:color-mix(in srgb, var(--green) 10%, transparent);border:1px solid color-mix(in srgb, var(--green) 25%, transparent);
  display:flex;align-items:center;justify-content:center;
  font-size:10px;font-weight:700;color:var(--gm);
}
.intel-opp-title{font-size:14px;font-weight:600;color:var(--charcoal);flex:1}
.intel-opp-cat{
  flex-shrink:0;font-size:9px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;
  padding:3px 9px;border-radius:20px;
  background:rgba(255,255,255,.06);border:1px solid var(--border);color:var(--muted);
}
.intel-opp-desc{font-size:13px;color:var(--muted);line-height:1.6;margin-bottom:10px}
.intel-opp-why{
  font-size:12px;color:var(--charcoal);line-height:1.55;
  border-left:2px solid var(--gm);padding-left:12px;margin-bottom:14px;
}
.intel-opp-meta{
  display:flex;align-items:center;gap:10px;flex-wrap:wrap;
}
.intel-opp-badge{
  display:inline-flex;align-items:center;gap:5px;
  font-size:10px;font-weight:600;color:var(--muted);
}
.intel-opp-badge-dot{width:6px;height:6px;border-radius:50%;}
.intel-opp-badge-dot.high{background:var(--gm)}
.intel-opp-badge-dot.medium{background:#fbbf24}
.intel-opp-badge-dot.low{background:rgba(255,255,255,.25)}
.intel-opp-divider{flex:1}
.intel-opp-action{
  background:color-mix(in srgb, var(--green) 8%, transparent);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius:10px;padding:10px 14px;
  font-size:12px;color:var(--charcoal);line-height:1.5;
}
.intel-opp-action-lbl{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--gm);margin-bottom:4px}

/* Mobile */
@media(max-width:768px){
  .intel-outer{padding:calc(56px + env(safe-area-inset-top,0px) + 24px) 16px 48px}
  .intel-market-band{grid-template-columns:1fr 1fr}
  .intel-trend-grid{grid-template-columns:1fr}
}


/* =================================================================
   ORIVEN 2.0 — MONITOR PAGES + DAILY BRIEF
   ================================================================= */

#page-website,#page-health,#page-alerts{display:none;overflow-y:auto}
#page-website.active,#page-health.active,#page-alerts.active{display:block}

/* ── URL input row ───────────────────────────────────────────── */
.mon-url-row{display:flex;gap:10px;margin-bottom:28px;align-items:center}
.mon-url-input{
  flex:1;height:42px;background:var(--surface);border:1px solid var(--border);
  border-radius:11px;padding:0 14px;font-size:14px;color:var(--charcoal);
  outline:none;transition:border-color .2s;
}
.mon-url-input:focus{border-color:rgba(255,255,255,.25)}
.mon-url-input::placeholder{color:var(--muted)}

/* ── Score band ──────────────────────────────────────────────── */
.mon-score-band{
  display:flex;align-items:center;gap:24px;
  background:var(--surface);border:1px solid var(--border);
  border-radius:18px;padding:24px 28px;margin-bottom:4px;
}
.mon-score-ring{position:relative;width:80px;height:80px;flex-shrink:0}
.mon-score-ring-svg{width:80px;height:80px}
.mon-score-ring-bg{fill:none;stroke:rgba(255,255,255,.06);stroke-width:4}
.mon-score-ring-fill{
  fill:none;stroke-width:4;stroke-linecap:round;
  transition:stroke-dashoffset .8s cubic-bezier(.36,.07,.19,.97);
  transform:rotate(-90deg);transform-origin:50% 50%;
}
.mon-score-ring-num{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  font-size:16px;font-weight:700;color:var(--charcoal);
}
.mon-score-body{flex:1;min-width:0}
.mon-score-grade{
  font-size:36px;font-weight:700;color:var(--charcoal);letter-spacing:-1px;margin-bottom:4px;
}
.mon-score-label{font-size:12px;font-weight:600;color:var(--muted);margin-bottom:2px}
.mon-score-url{font-size:12px;color:var(--muted);font-family:monospace;opacity:.7}

/* ── Generic list (strengths / recs) ─────────────────────────── */
.mon-list{display:flex;flex-direction:column;gap:8px}
.mon-list-item{
  display:flex;align-items:flex-start;gap:10px;
  background:var(--surface);border:1px solid var(--border);
  border-radius:12px;padding:13px 15px;
  font-size:13px;color:var(--charcoal);line-height:1.55;
}
.mon-list-item::before{
  content:"✓";color:var(--gm);font-weight:700;font-size:11px;
  flex-shrink:0;margin-top:1px;
}
.mon-list-action .mon-list-item::before{content:"→";color:var(--muted)}

/* ── Issues list ─────────────────────────────────────────────── */
.mon-issues{display:flex;flex-direction:column;gap:10px}
.mon-issue{
  background:var(--surface);border:1px solid var(--border);
  border-radius:13px;padding:14px 16px;
  display:flex;gap:14px;align-items:flex-start;
}
.mon-issue-sev{
  flex-shrink:0;font-size:9px;font-weight:700;letter-spacing:.08em;
  text-transform:uppercase;padding:3px 8px;border-radius:20px;margin-top:1px;
}
.mon-issue-sev.high{background:rgba(239,68,68,.1);border:1px solid rgba(239,68,68,.25);color:#ef4444}
.mon-issue-sev.medium{background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.25);color:#fbbf24}
.mon-issue-sev.low{background:rgba(255,255,255,.06);border:1px solid var(--border);color:var(--muted)}
.mon-issue-body{flex:1;min-width:0}
.mon-issue-area{font-size:12px;font-weight:700;color:var(--charcoal);margin-bottom:3px}
.mon-issue-desc{font-size:12px;color:var(--muted);line-height:1.55}

/* ── Brand Health pillars ─────────────────────────────────────── */
.health-overview{
  display:grid;grid-template-columns:160px 1fr;gap:20px;
  background:var(--surface);border:1px solid var(--border);
  border-radius:18px;padding:24px 26px;margin-bottom:24px;
  align-items:center;
}
.health-ring-wrap{display:flex;flex-direction:column;align-items:center;gap:8px}
.health-ring-svg{width:88px;height:88px}
.health-ring-bg{fill:none;stroke:rgba(255,255,255,.06);stroke-width:4}
.health-ring-fill{
  fill:none;stroke-width:4;stroke-linecap:round;
  transition:stroke-dashoffset .8s ease;
  transform:rotate(-90deg);transform-origin:50% 50%;
}
.health-ring-num{font-size:20px;font-weight:700;color:var(--charcoal)}
.health-ring-lbl{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.health-score-title{font-size:17px;font-weight:600;color:var(--charcoal);margin-bottom:4px}
.health-score-sub{font-size:13px;color:var(--muted);line-height:1.55;margin-bottom:14px}
.health-score-btn{
  font-size:12px;font-weight:600;color:var(--gm);
  background:color-mix(in srgb, var(--green) 8%, transparent);border:1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius:9px;padding:7px 14px;cursor:pointer;transition:opacity .15s;
}
.health-score-btn:hover{opacity:.8}

.health-pillars{display:flex;flex-direction:column;gap:10px}
.health-pillar{
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:16px 18px;
}
.health-pillar-hd{
  display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;
}
.health-pillar-name{font-size:13px;font-weight:600;color:var(--charcoal)}
.health-pillar-pct{font-size:13px;font-weight:700;color:var(--charcoal)}
.health-pillar-bar-bg{
  height:5px;border-radius:20px;background:rgba(255,255,255,.07);overflow:hidden;
}
.health-pillar-bar{
  height:100%;border-radius:20px;
  transition:width .7s cubic-bezier(.36,.07,.19,.97);
}
.health-pillar-status{
  font-size:11px;color:var(--muted);margin-top:6px;
}

/* ── Alerts page ─────────────────────────────────────────────── */
.alerts-empty{
  display:flex;flex-direction:column;align-items:center;
  gap:12px;padding:64px 0;text-align:center;
}
.alerts-empty-icon{
  width:52px;height:52px;border-radius:14px;
  background:var(--surface);border:1px solid var(--border);
  display:flex;align-items:center;justify-content:center;
}
.alerts-empty-icon svg{stroke:var(--gm)}
.alerts-empty-title{font-size:16px;font-weight:600;color:var(--charcoal)}
.alerts-empty-sub{font-size:13px;color:var(--muted);max-width:300px;line-height:1.6}
.alerts-list{display:flex;flex-direction:column;gap:10px}
.alert-item{
  display:flex;align-items:flex-start;gap:14px;
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:16px 18px;
  transition:border-color .2s;
}
.alert-item.high{border-left:3px solid #ef4444}
.alert-item.medium{border-left:3px solid #fbbf24}
.alert-item.low{border-left:3px solid rgba(255,255,255,.15)}
.alert-icon{
  width:32px;height:32px;border-radius:9px;
  display:flex;align-items:center;justify-content:center;flex-shrink:0;
}
.alert-icon.high{background:rgba(239,68,68,.1)}
.alert-icon.medium{background:rgba(251,191,36,.08)}
.alert-icon.low{background:rgba(255,255,255,.05)}
.alert-icon svg{width:14px;height:14px}
.alert-icon.high svg{stroke:#ef4444}
.alert-icon.medium svg{stroke:#fbbf24}
.alert-icon.low svg{stroke:var(--muted)}
.alert-body{flex:1;min-width:0}
.alert-title{font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:3px}
.alert-desc{font-size:12px;color:var(--muted);line-height:1.5}
.alert-action{
  font-size:11.5px;font-weight:600;color:var(--gm);cursor:pointer;
  background:none;border:none;padding:0;margin-top:8px;display:block;
}
.alert-action:hover{text-decoration:underline}
.alert-ts{font-size:10px;color:var(--muted);opacity:.6;flex-shrink:0;margin-top:2px}

/* ── Brand Brain: Daily Brief ────────────────────────────────── */
.bb-brief-gen-btn{
  display:inline-flex;align-items:center;gap:5px;
  font-size:10.5px;font-weight:600;color:var(--muted);
  background:var(--surface);border:1px solid var(--border);
  border-radius:8px;padding:5px 10px;cursor:pointer;
  transition:border-color .15s,color .15s;
}
.bb-brief-gen-btn:hover{border-color:rgba(255,255,255,.2);color:var(--charcoal)}
.bb-brief-gen-btn:disabled{opacity:.4;cursor:default}
.bb-brief-gen-btn svg{flex-shrink:0}
.bb-brief-prompt{
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:16px 20px;
  display:flex;align-items:center;justify-content:space-between;gap:16px;
  font-size:13px;color:var(--muted);
}
.bb-brief-prompt button{
  font-size:12px;font-weight:600;color:var(--gm);
  background:none;border:none;cursor:pointer;white-space:nowrap;
}
.bb-brief-prompt button:hover{text-decoration:underline}
.bb-brief-loading{
  display:flex;align-items:center;gap:10px;
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:16px 20px;
  font-size:13px;color:var(--muted);
}
.bb-brief-loading-ring{
  width:16px;height:16px;border-radius:50%;
  border:2px solid rgba(255,255,255,.1);border-top-color:var(--gm);
  animation:spin .7s linear infinite;flex-shrink:0;
}
.bb-brief-result{
  background:var(--surface);border:1px solid var(--border);
  border-radius:14px;padding:20px 22px;
  display:flex;flex-direction:column;gap:14px;
}
.bb-brief-date{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.bb-brief-headline{
  font-size:15px;font-weight:600;color:var(--charcoal);line-height:1.45;
}
.bb-brief-items{display:flex;flex-direction:column;gap:8px}
.bb-brief-item{
  display:flex;align-items:flex-start;gap:10px;
  padding:10px 12px;border-radius:10px;background:var(--bg);
}
.bb-brief-item-type{
  flex-shrink:0;font-size:8.5px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;
  padding:2px 7px;border-radius:20px;margin-top:1px;
}
.bb-brief-item-type.insight{background:rgba(96,165,250,.1);border:1px solid rgba(96,165,250,.25);color:#60a5fa}
.bb-brief-item-type.action{background:color-mix(in srgb, var(--green) 10%, transparent);border:1px solid color-mix(in srgb, var(--green) 25%, transparent);color:var(--gm)}
.bb-brief-item-type.alert{background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.25);color:#fbbf24}
.bb-brief-item-body{flex:1;min-width:0}
.bb-brief-item-title{font-size:12.5px;font-weight:600;color:var(--charcoal);margin-bottom:2px}
.bb-brief-item-body-text{font-size:12px;color:var(--muted);line-height:1.5}
.bb-brief-focus{
  border-top:1px solid var(--border);padding-top:14px;
  font-size:13px;font-weight:500;color:var(--charcoal);line-height:1.5;
  display:flex;gap:10px;align-items:flex-start;
}
.bb-brief-focus::before{
  content:"Today:";font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:var(--gm);white-space:nowrap;margin-top:2px;
}

/* ── Brand Brain: Explore grid ────────────────────────────────── */
.bb-explore-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.bb-explore-card{
  display:flex;align-items:center;gap:12px;
  background:var(--surface);border:1px solid var(--border);
  border-radius:13px;padding:14px 16px;cursor:pointer;
  transition:border-color .2s,transform .15s;
}
.bb-explore-card:hover{border-color:rgba(255,255,255,.15);transform:translateX(2px)}
.bb-explore-ico{
  width:32px;height:32px;border-radius:9px;
  background:var(--bg);border:1px solid var(--border);
  display:flex;align-items:center;justify-content:center;flex-shrink:0;
}
.bb-explore-ico svg{stroke:var(--muted)}
.bb-explore-body{flex:1;min-width:0}
.bb-explore-name{font-size:12.5px;font-weight:600;color:var(--charcoal);margin-bottom:1px}
.bb-explore-desc{font-size:11px;color:var(--muted);line-height:1.4}
.bb-explore-arrow{color:var(--muted);font-size:16px;opacity:.35;flex-shrink:0}

/* ── Alert dot in nav ─────────────────────────────────────────── */
.sb-alert-dot{
  width:6px;height:6px;border-radius:50%;
  background:#ef4444;margin-left:auto;flex-shrink:0;
  animation:dashDotPulse 2s ease-in-out infinite;
}

/* ── Mobile ───────────────────────────────────────────────────── */
@media(max-width:768px){
  .mon-url-row{flex-direction:column;align-items:stretch}
  .health-overview{grid-template-columns:1fr}
  .health-ring-wrap{flex-direction:row;gap:16px}
  .bb-explore-grid{grid-template-columns:1fr}
  .bb-brief-prompt{flex-direction:column;align-items:flex-start;gap:8px}
}


/* =================================================================
   ORIVEN 2.0 — COMPETITOR INTELLIGENCE (standalone page)
   ================================================================= */

#page-competitor{display:none;overflow-y:auto}
#page-competitor.active{display:block}

.ci-page-outer{
  max-width:900px;margin:0 auto;
  padding:40px 32px 64px;
}

@media(max-width:768px){
  .ci-page-outer{padding:calc(56px + env(safe-area-inset-top,0px) + 24px) 16px 48px}
}


/* ═══════════════════════════════════════════════════════════
   HERO: BRAND BRAIN VISUALIZATION
   ═══════════════════════════════════════════════════════════ */

.lp-s-hero-right{
  display:flex;
  align-items:center;
  justify-content:center;
  flex:0 0 auto;
}

/* ── Brand Brain visualization container ──────────────── */
.bb-viz{
  position:relative;
  width:520px;
  height:580px;
  flex-shrink:0;
}

/* SVG canvas (lines + particles) */
.bb-viz-svg{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  pointer-events:none;
}

/* Connection lines */
.bb-viz-line{
  stroke:color-mix(in srgb, var(--green) 9%, transparent);
  stroke-width:.8;
  stroke-dasharray:3 9;
  animation:bbLineDash 10s linear infinite;
}

@keyframes bbLineDash{
  to{ stroke-dashoffset:-44; }
}

/* Inbound particles */
.bb-viz-ptc{
  fill:color-mix(in srgb, var(--green) 85%, transparent);
  filter:drop-shadow(0 0 3px color-mix(in srgb, var(--green) 60%, transparent));
}

/* ── Hub (center) ─────────────────────────────────────── */
.bb-viz-hub{
  position:absolute;
  left:50%;
  top:220px;
  width:128px;
  height:128px;
  transform:translate(-50%,-50%);
  z-index:4;
}

.bb-viz-hub-ring{
  position:absolute;
  inset:0;
  border-radius:50%;
  border:1px solid color-mix(in srgb, var(--green) 16%, transparent);
  animation:bbSpin 22s linear infinite;
}
.bb-viz-hub-ring::before{
  content:'';
  position:absolute;
  top:-2.5px;left:50%;
  width:5px;height:5px;
  border-radius:50%;
  background:color-mix(in srgb, var(--green) 70%, transparent);
  transform:translateX(-50%);
  box-shadow:0 0 5px color-mix(in srgb, var(--green) 60%, transparent), 0 0 10px color-mix(in srgb, var(--green) 30%, transparent);
}
.bb-viz-hub-ring-2{
  inset:9px;
  border-color:color-mix(in srgb, var(--green) 8%, transparent);
  animation:bbCounterSpin 34s linear infinite;
}
.bb-viz-hub-ring-2::before{
  width:3px;height:3px;
  background:color-mix(in srgb, var(--green) 45%, transparent);
  box-shadow:0 0 3px color-mix(in srgb, var(--green) 40%, transparent);
}

.bb-viz-hub-pulse{
  position:absolute;
  inset:0;
  border-radius:50%;
  border:1px solid color-mix(in srgb, var(--green) 40%, transparent);
  animation:bbPulse 7s ease-out infinite;
  pointer-events:none;
}
.bb-viz-hub-pulse-2{ animation-delay:3.5s; }

.bb-viz-hub-core{
  position:absolute;
  inset:16px;
  border-radius:50%;
  background:rgba(8,8,8,.96);
  border:1px solid color-mix(in srgb, var(--green) 28%, transparent);
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:2px;
  box-shadow:
    0 0 30px color-mix(in srgb, var(--green) 14%, transparent) inset,
    0 0 0 10px color-mix(in srgb, var(--green) 4%, transparent),
    0 0 60px color-mix(in srgb, var(--green) 6%, transparent);
}

.bb-viz-hub-icon{
  color:color-mix(in srgb, var(--green) 85%, transparent);
  line-height:1;
  margin-bottom:1px;
}

.bb-viz-hub-name{
  font-size:8px;
  font-weight:600;
  letter-spacing:.07em;
  color:rgba(255,255,255,.45);
  text-transform:uppercase;
}

.bb-viz-hub-score{
  font-size:22px;
  font-weight:700;
  color:var(--green);
  letter-spacing:-.02em;
  line-height:1;
  text-shadow:0 0 24px color-mix(in srgb, var(--green) 55%, transparent);
}

.bb-viz-hub-live{
  display:flex;
  align-items:center;
  gap:4px;
  font-size:8px;
  color:rgba(255,255,255,.35);
  margin-top:2px;
}
.bb-viz-hub-live-dot{
  width:5px;height:5px;
  border-radius:50%;
  background:var(--green);
  box-shadow:0 0 4px var(--green);
  animation:bbLivePulse 2s ease-in-out infinite;
}

/* ── Satellite nodes ──────────────────────────────────── */
.bb-viz-node{
  position:absolute;
  width:114px;
  background:rgba(10,10,10,.90);
  border:1px solid rgba(255,255,255,.07);
  border-radius:10px;
  padding:9px 11px;
  backdrop-filter:blur(12px);
  transition:border-color .4s, box-shadow .4s;
  z-index:3;
}
.bb-viz-node.bb-node-active{
  border-color:color-mix(in srgb, var(--green) 30%, transparent);
  box-shadow:0 0 20px color-mix(in srgb, var(--green) 9%, transparent), 0 0 0 1px color-mix(in srgb, var(--green) 8%, transparent);
}

/* 6-node hexagonal positions (hub at left:260px, top:220px) */
.bb-viz-n0{ left:203px; top:35px; }
.bb-viz-n1{ left:341px; top:113px; }
.bb-viz-n2{ left:341px; top:269px; }
.bb-viz-n3{ left:203px; top:347px; }
.bb-viz-n4{ left:65px;  top:269px; }
.bb-viz-n5{ left:65px;  top:113px; }

.bb-viz-node-hd{
  display:flex;
  align-items:center;
  gap:5px;
  margin-bottom:5px;
  position:relative;
}

.bb-viz-node-ico{
  width:20px;height:20px;
  border-radius:5px;
  background:color-mix(in srgb, var(--green) 8%, transparent);
  display:flex;align-items:center;justify-content:center;
  color:color-mix(in srgb, var(--green) 70%, transparent);
  flex-shrink:0;
}
.bb-node-active .bb-viz-node-ico{
  background:color-mix(in srgb, var(--green) 15%, transparent);
  color:var(--green);
}

.bb-viz-node-name{
  font-size:9px;
  font-weight:600;
  color:rgba(255,255,255,.6);
  line-height:1.2;
  flex:1;
}
.bb-node-active .bb-viz-node-name{
  color:rgba(255,255,255,.88);
}

.bb-viz-node-status{
  font-size:8px;
  color:color-mix(in srgb, var(--green) 55%, transparent);
  line-height:1.3;
  min-height:11px;
  transition:opacity .3s;
}
.bb-viz-node-status.bb-status-changing{
  opacity:0;
}

.bb-viz-node-ping{
  width:6px;height:6px;
  border-radius:50%;
  background:transparent;
  position:absolute;
  top:0;right:0;
  transition:background .3s;
}
.bb-node-active .bb-viz-node-ping{
  background:var(--green);
  box-shadow:0 0 6px var(--green);
  animation:bbNodePing 1.5s ease-out;
}

/* ── Live evolution panel ─────────────────────────────── */
.bb-evo-panel{
  position:absolute;
  left:60px;
  top:428px;
  width:400px;
  background:rgba(10,10,10,.88);
  border:1px solid color-mix(in srgb, var(--green) 14%, transparent);
  border-radius:12px;
  padding:12px 16px 14px;
  backdrop-filter:blur(14px);
  box-shadow:0 0 40px color-mix(in srgb, var(--green) 6%, transparent);
  z-index:4;
}

.bb-evo-hd{
  display:flex;
  align-items:center;
  gap:10px;
  margin-bottom:10px;
}

.bb-evo-scan{
  flex:1;
  height:3px;
  background:color-mix(in srgb, var(--green) 8%, transparent);
  border-radius:2px;
  overflow:hidden;
}
.bb-evo-scan-bar{
  height:100%;
  width:40%;
  background:color-mix(in srgb, var(--green) 55%, transparent);
  border-radius:2px;
  animation:bbEvoScan 2.8s ease-in-out infinite;
}
@keyframes bbEvoScan{
  0%   { width:0%;   opacity:.6; }
  60%  { width:100%; opacity:1;  }
  100% { width:100%; opacity:0;  }
}

.bb-evo-label{
  font-size:10px;
  color:rgba(255,255,255,.5);
  font-weight:500;
  white-space:nowrap;
  transition:opacity .3s;
}
.bb-evo-label.bb-evo-changing{ opacity:0; }

.bb-evo-live{
  display:flex;
  align-items:center;
  gap:4px;
  font-size:9px;
  font-weight:600;
  color:color-mix(in srgb, var(--green) 70%, transparent);
  flex-shrink:0;
}
.bb-evo-live-dot{
  width:5px;height:5px;
  border-radius:50%;
  background:var(--green);
  box-shadow:0 0 4px var(--green);
  animation:bbLivePulse 2s ease-in-out infinite;
}

.bb-evo-body{
  transition:opacity .3s;
}
