/* ── Keyframe animations ──────────────────────────────── */
@keyframes bbSpin{
  to{ transform:rotate(360deg); }
}
@keyframes bbCounterSpin{
  to{ transform:rotate(-360deg); }
}
@keyframes bbPulse{
  0%  { transform:scale(1);   opacity:.5; }
  80% { transform:scale(1.65);opacity:0;  }
