/* ══════════════════════════════════════════════════════
   AMBIENT INTELLIGENCE LAYER — site-wide ambient activity
   Nodes and lines injected randomly per page load by JS.
   ══════════════════════════════════════════════════════ */
.amb-layer{
  position:absolute;
  inset:0;
  pointer-events:none;
  overflow:hidden;
  z-index:0;
}

/* Pulsing ambient node ─────────────────────────────── */
.amb-nd{
  position:absolute;
  border-radius:50%;
  background:color-mix(in srgb, var(--green) 30%, transparent);
  transform:translate(-50%,-50%);
  animation:ambNdPulse 5s ease-in-out infinite both;
}
@keyframes ambNdPulse{
  0%,100%{
    opacity:.25;
    transform:translate(-50%,-50%) scale(1);
    box-shadow:none;
  }
  50%{
    opacity:.65;
    transform:translate(-50%,-50%) scale(1.7);
    box-shadow:0 0 7px color-mix(in srgb, var(--green) 22%, transparent);
  }
}

/* Fading ambient connection line ───────────────────── */
.amb-ln{
  position:absolute;
  height:1px;
  transform-origin:left center;
  background:linear-gradient(
    90deg,
    transparent 0%,
    color-mix(in srgb, var(--green) 11%, transparent) 20%,
    color-mix(in srgb, var(--green) 18%, transparent) 50%,
    color-mix(in srgb, var(--green) 11%, transparent) 80%,
    transparent 100%
  );
  animation:ambLnFade 9s ease-in-out infinite both;
}
@keyframes ambLnFade{
  0%,100%{ opacity:0; }
  25%,75%{ opacity:1; }
}

/* ── AI Systems scene: animated arrow dots ────────── */
/* The arrow is 1×24px. A glowing dot travels along it. */
.lp-s-ai-arrow{
  position:relative;
}
.lp-s-ai-arrow::after{
  content:'';
  position:absolute;
  left:50%;
  top:0%;
  width:4px; height:4px;
  border-radius:50%;
  background:color-mix(in srgb, var(--green) 85%, transparent);
  box-shadow:0 0 5px color-mix(in srgb, var(--green) 55%, transparent);
  transform:translate(-50%,-50%);
  animation:aiArrowDot 2.8s ease-in-out infinite;
}
.lp-s-ai-arrow.flip::after{
  animation-direction:reverse;
}
@keyframes aiArrowDot{
  0%  { top:0%;   opacity:0; }
  15% { opacity:.9; }
  85% { opacity:.9; }
  100%{ top:100%; opacity:0; }
}

/* ── AI Systems: output dot pulse (staggered) ──────── */
.lp-s-ai-out-dot{
  animation:aiOutDotPulse 3.5s ease-in-out infinite;
}
.lp-s-ai-output:nth-child(2) .lp-s-ai-out-dot{ animation-delay:.55s; }
.lp-s-ai-output:nth-child(3) .lp-s-ai-out-dot{ animation-delay:1.1s; }
.lp-s-ai-output:nth-child(4) .lp-s-ai-out-dot{ animation-delay:1.65s; }
.lp-s-ai-output:nth-child(5) .lp-s-ai-out-dot{ animation-delay:2.2s; }
.lp-s-ai-output:nth-child(6) .lp-s-ai-out-dot{ animation-delay:2.75s; }
@keyframes aiOutDotPulse{
  0%,100%{ opacity:.35; transform:scale(1); }
  50%    { opacity:.9;  transform:scale(1.35); box-shadow:0 0 6px color-mix(in srgb, var(--green) 45%, transparent); }
}

/* ── About: pillar dot ambient pulse ───────────────── */
.lp-about-pillar-dot{
  animation:pillarDotPulse 4.5s ease-in-out infinite;
}
.lp-about-pillar:nth-child(2) .lp-about-pillar-dot{ animation-delay:1.1s; }
.lp-about-pillar:nth-child(3) .lp-about-pillar-dot{ animation-delay:2.2s; }
.lp-about-pillar:nth-child(4) .lp-about-pillar-dot{ animation-delay:3.3s; }
@keyframes pillarDotPulse{
  0%,100%{ opacity:.55; transform:scale(1); }
  50%    { opacity:1;   transform:scale(1.4); box-shadow:0 0 5px color-mix(in srgb, var(--green) 50%, transparent); }
}

/* ── Process: step number ambient glow ─────────────── */
.lp-s-proc-num{
  animation:procNumGlow 6s ease-in-out infinite;
}
.lp-s-proc-step:nth-child(2) .lp-s-proc-num{ animation-delay:1.5s; }
.lp-s-proc-step:nth-child(3) .lp-s-proc-num{ animation-delay:3.0s; }
.lp-s-proc-step:nth-child(4) .lp-s-proc-num{ animation-delay:4.5s; }
@keyframes procNumGlow{
  0%,100%{ text-shadow:none; opacity:.6; }
  50%    { text-shadow:0 0 16px color-mix(in srgb, var(--green) 35%, transparent); opacity:1; }
}

