.ncc-modal {
  width: 580px;
  max-width: 96vw;
  padding: 32px 36px 28px;
  position: relative;
  max-height: 88vh;
  overflow-y: auto;
  /* Always dark — matches the campaign type overlay */
  background: #141416 !important;
  color: #F0F0F0;
  border: 1px solid rgba(255,255,255,.08);
  /* Override CSS variables for all children so form fields, labels,
     borders, etc. render correctly regardless of body theme */
  --bg: #0A0A0A;
  --bg2: #1E1E21;
  --bg3: #252528;
  --surface: #1F1F21;
  --charcoal: rgba(255,255,255,.92);
  --c2: rgba(255,255,255,.75);
  --muted: rgba(255,255,255,.45);
  --m2: rgba(255,255,255,.3);
  --border: rgba(255,255,255,.08);
  --b2: rgba(255,255,255,.12);
  --gm: var(--green);
}

.ncc-close {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 28px;
  height: 28px;
  border-radius: 7px;
  background: var(--bg2,#F6F3EE);
  border: 1px solid var(--border,rgba(0,0,0,.08));
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--muted,#888);
  transition: background .14s;
}
.ncc-close:hover { background: var(--border,rgba(0,0,0,.08)); }
.dark-mode .ncc-close { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.1); }

/* Step bar */
.ncc-stepbar {
  display: flex;
  align-items: center;
  gap: 0;
  margin-bottom: 28px;
}
.ncc-stepdot {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg2,#F6F3EE);
  border: 1.5px solid var(--border,rgba(0,0,0,.1));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted,#888);
  flex-shrink: 0;
  transition: background .2s, border-color .2s, color .2s;
}
.ncc-stepdot-on {
  background: var(--gm,#1A4229);
  border-color: var(--gm,#1A4229);
  color: #fff;
}
.ncc-stepdot-done {
  background: rgba(26,66,41,.1);
  border-color: rgba(26,66,41,.3);
  color: var(--gm,#1A4229);
}
.dark-mode .ncc-stepdot-on { background: var(--green); border-color: var(--green); color: #000; }
.dark-mode .ncc-stepdot-done { background: color-mix(in srgb, var(--green) 10%, transparent); border-color: color-mix(in srgb, var(--green) 30%, transparent); color: var(--green); }

.ncc-stepline {
  flex: 1;
  height: 1.5px;
  background: var(--border,rgba(0,0,0,.08));
}

.ncc-hd {
  font-size: 18px;
  font-weight: 700;
  color: var(--charcoal,#18181A);
  letter-spacing: -.02em;
  margin-bottom: 20px;
}
.dark-mode .ncc-hd { color: #f0f0f0; }

.ncc-sub {
  font-size: 13px;
  color: var(--muted,#888);
  margin: -12px 0 18px;
}

/* Step 1 */
.ncc-start-opts {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}
.ncc-start-opt {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 18px;
  border-radius: 12px;
  border: 1.5px solid var(--border,rgba(0,0,0,.08));
  cursor: pointer;
  transition: border-color .14s, background .14s;
}
.ncc-start-opt:hover { border-color: var(--gm,#1A4229); }
.ncc-start-sel { border-color: var(--gm,#1A4229); background: rgba(26,66,41,.04); }
.dark-mode .ncc-start-opt:hover { border-color: color-mix(in srgb, var(--green) 50%, transparent); }
.dark-mode .ncc-start-sel { border-color: color-mix(in srgb, var(--green) 50%, transparent); background: color-mix(in srgb, var(--green) 4%, transparent); }

.ncc-start-opt-ico {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--bg2,#F6F3EE);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--gm,#1A4229);
}
.dark-mode .ncc-start-opt-ico { background: rgba(255,255,255,.06); color: var(--green); }
.ncc-start-opt-ico svg { width: 16px; height: 16px; }

.ncc-start-opt-name { font-size: 14px; font-weight: 600; color: var(--charcoal,#18181A); margin-bottom: 3px; }
.dark-mode .ncc-start-opt-name { color: #f0f0f0; }
.ncc-start-opt-sub { font-size: 12px; color: var(--muted,#888); }

.ncc-tpl-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 14px;
}
.ncc-tpl-card {
  padding: 10px 12px;
  border-radius: 9px;
  border: 1px solid var(--border,rgba(0,0,0,.08));
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  color: var(--charcoal,#18181A);
  background: var(--bg2,#F6F3EE);
  text-align: center;
  transition: border-color .14s, background .14s;
}
.ncc-tpl-card:hover { border-color: var(--gm,#1A4229); }
.ncc-tpl-sel { border-color: var(--gm,#1A4229); background: rgba(26,66,41,.06); font-weight: 700; }
.dark-mode .ncc-tpl-card { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.8); }
.dark-mode .ncc-tpl-card:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.dark-mode .ncc-tpl-sel { border-color: color-mix(in srgb, var(--green) 50%, transparent); }

/* Step 2 */
.ncc-desc { min-height: 110px; resize: vertical; }

/* Step 3 */
.ncc-mod-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.ncc-mod-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding: 14px 10px;
  border-radius: 11px;
  border: 1.5px solid var(--border,rgba(0,0,0,.08));
  cursor: pointer;
  transition: border-color .14s, background .14s;
  text-align: center;
  font-size: 12px;
  font-weight: 500;
  color: var(--muted,#888);
  position: relative;
}
.ncc-mod-item input { position: absolute; opacity: 0; width: 0; height: 0; }
.ncc-mod-item:hover { border-color: var(--gm,#1A4229); color: var(--charcoal,#18181A); }
.ncc-mod-checked { border-color: var(--gm,#1A4229); background: rgba(26,66,41,.04); color: var(--gm,#1A4229); font-weight: 600; }
.dark-mode .ncc-mod-item { border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.4); }
.dark-mode .ncc-mod-item:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); color: rgba(255,255,255,.8); }
.dark-mode .ncc-mod-checked { border-color: color-mix(in srgb, var(--green) 50%, transparent); background: color-mix(in srgb, var(--green) 6%, transparent); color: var(--green); }

.ncc-mod-ico {
  width: 28px;
  height: 28px;
  border-radius: 7px;
  background: var(--bg2,#F6F3EE);
  display: flex;
  align-items: center;
  justify-content: center;
}
.ncc-mod-checked .ncc-mod-ico { background: rgba(26,66,41,.1); }
.dark-mode .ncc-mod-ico { background: rgba(255,255,255,.06); }
.dark-mode .ncc-mod-checked .ncc-mod-ico { background: color-mix(in srgb, var(--green) 10%, transparent); }
.ncc-mod-ico svg { width: 13px; height: 13px; stroke: var(--muted,#888); }
.ncc-mod-checked .ncc-mod-ico svg { stroke: var(--gm,#1A4229); }
.dark-mode .ncc-mod-checked .ncc-mod-ico svg { stroke: var(--green); }

/* Step 4 Review */
.ncc-review-card {
  background: var(--bg2,#F6F3EE);
  border: 1px solid var(--border,rgba(0,0,0,.08));
  border-radius: 14px;
  padding: 20px 22px;
  margin-bottom: 20px;
}
.dark-mode .ncc-review-card { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); }
.ncc-rv-row { display: flex; gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--border,rgba(0,0,0,.06)); }
.ncc-rv-row:last-child { border-bottom: none; padding-bottom: 0; }
.ncc-rv-lbl { font-size: 11px; font-weight: 600; color: var(--muted,#888); text-transform: uppercase; letter-spacing: .06em; min-width: 72px; padding-top: 1px; }
.ncc-rv-val { font-size: 13px; color: var(--charcoal,#18181A); flex: 1; line-height: 1.5; }
.dark-mode .ncc-rv-val { color: #e0e0e0; }
.ncc-rv-desc { color: var(--muted,#888); font-size: 12px; }
.ncc-rv-mod {
  display: inline-block;
  background: rgba(26,66,41,.06);
  border: 1px solid rgba(26,66,41,.14);
  border-radius: 5px;
  padding: 2px 7px;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--gm,#1A4229);
  margin: 2px 3px 2px 0;
}
.dark-mode .ncc-rv-mod { background: color-mix(in srgb, var(--green) 7%, transparent); border-color: color-mix(in srgb, var(--green) 18%, transparent); color: var(--green); }

.ncc-gen-btn {
  width: 100%;
  padding: 14px;
  background: var(--gm,#1A4229);
  color: #fff;
  border: none;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  font-family: inherit;
  transition: opacity .15s, transform .12s;
  letter-spacing: -.01em;
}
.ncc-gen-btn:hover { opacity: .88; transform: translateY(-1px); }
.dark-mode .ncc-gen-btn,
.ncc-modal .ncc-gen-btn { background: var(--green); color: #000; }
.ncc-gen-btn svg { width: 15px; height: 15px; }

.ncc-gen-note { font-size: 11.5px; color: var(--muted,#888); text-align: center; margin: 10px 0 0; }

/* Footer nav */
.ncc-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 24px;
  padding-top: 18px;
  border-top: 1px solid var(--border,rgba(0,0,0,.07));
}
.ncc-btn-back, .ncc-btn-next {
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background .14s, border-color .14s;
}
.ncc-btn-back {
  background: none;
  border: 1px solid var(--border,rgba(0,0,0,.1));
  color: var(--muted,#888);
}
.ncc-btn-back:hover { background: var(--bg2,#F6F3EE); }
.ncc-btn-next {
  background: var(--gm,#1A4229);
  border: 1px solid transparent;
  color: #fff;
}
.ncc-btn-next:hover { opacity: .88; }
.dark-mode .ncc-btn-next,
.ncc-modal .ncc-btn-next { background: var(--green); color: #000; }
.dark-mode .ncc-btn-back,
.ncc-modal .ncc-btn-back { border-color: rgba(255,255,255,.12); color: rgba(255,255,255,.5); }
.dark-mode .ncc-btn-back:hover,
.ncc-modal .ncc-btn-back:hover { background: rgba(255,255,255,.05); }

