#camp-gen-overlay {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(0,0,0,.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
}

.cgo-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  max-width: 420px;
  width: 100%;
}

.cgo-orb {
  position: relative;
  width: 72px;
  height: 72px;
  margin-bottom: 28px;
}
.cgo-orb-ring {
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--green) 30%, transparent);
  animation: cgoRing 2.4s linear infinite;
}
@keyframes cgoRing {
  0%  { transform: rotate(0deg) scale(1);   opacity: .6; }
  50% { transform: rotate(180deg) scale(1.06); opacity: 1; }
  100%{ transform: rotate(360deg) scale(1);   opacity: .6; }
}
.cgo-orb-img {
  position: absolute;
  inset: 10px;
  object-fit: contain;
  border-radius: 12px;
  background: #fff;
  padding: 6px;
}

.cgo-title {
  font-size: 22px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -.02em;
  margin-bottom: 4px;
}

.cgo-camp-name {
  font-size: 13px;
  color: rgba(255,255,255,.5);
  margin-bottom: 32px;
}

.cgo-steps {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 28px;
  max-height: 240px;
  overflow: hidden;
}

.cgo-step {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255,255,255,.05);
  color: rgba(255,255,255,.25);
  font-size: 13px;
  transition: color .3s;
}
.cgo-step:last-child { border-bottom: none; }

.cgo-step-ico {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.15);
  flex-shrink: 0;
  transition: background .3s, border-color .3s;
}

.cgo-step-active {
  color: rgba(255,255,255,.9);
}
.cgo-step-active .cgo-step-ico {
  border-color: var(--green);
  background: color-mix(in srgb, var(--green) 12%, transparent);
  animation: cgoPulse .8s ease-in-out infinite alternate;
}
@keyframes cgoPulse {
  from { box-shadow: 0 0 0 0 color-mix(in srgb, var(--green) 40%, transparent); }
  to   { box-shadow: 0 0 0 5px color-mix(in srgb, var(--green) 0%, transparent); }
}

.cgo-step-done {
  color: rgba(255,255,255,.45);
}
.cgo-step-done .cgo-step-ico {
  background: color-mix(in srgb, var(--green) 15%, transparent);
  border-color: color-mix(in srgb, var(--green) 50%, transparent);
}
.cgo-step-done .cgo-step-ico::after {
  content: 'âœ“';
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  font-size: 9px;
  color: var(--green);
}

.cgo-bar-track {
  width: 100%;
  height: 3px;
  background: rgba(255,255,255,.1);
  border-radius: 2px;
  overflow: hidden;
  margin-bottom: 14px;
}
.cgo-bar-fill {
  height: 100%;
  background: var(--green);
  border-radius: 2px;
  transition: width .5s ease;
}

.cgo-note {
  font-size: 12px;
  color: rgba(255,255,255,.4);
}

