}
@media(max-width:640px){
  .camp-hub-recent-row,
  .camp-card-grid { grid-template-columns: 1fr; }
  .cws { flex-direction: column; }
  .cws-sb { width: 100%; height: auto; border-right: none; border-bottom: 1px solid var(--border,rgba(0,0,0,.08)); }
  .ncc-tpl-grid { grid-template-columns: repeat(2,1fr); }
  .cws-ov-grid { grid-template-columns: 1fr; }
}

/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   ORIVEN 3.0 â€” DESIGN SYSTEM, ANIMATIONS & MOBILE
   Part 3/4
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

/* â”€â”€ Ambient canvas â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
#appAmbient {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 1;
}

/* â”€â”€ Page transitions â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.page.active {
  animation: pageIn .22s ease both;
}
@keyframes pageIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* â”€â”€ Global micro-interactions â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Button press */
button:active:not(:disabled) {
  transform: scale(.97);
  transition: transform .08s ease;
}

/* Input focus glow */
input[type="text"]:focus,
input[type="email"]:focus,
input[type="password"]:focus,
input[type="number"]:focus,
textarea:focus,
select:focus {
  outline: none;
  /* Premium Motion System — was a hardcoded dark-green unrelated to the
     actual accent (and to dark mode's own color-mix(in srgb, var(--green) NaN%, transparent) below);
     both now derive from var(--green) so focus rings follow whichever
     Accent Color is active and match between themes. */
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 16%, transparent);
  border-color: color-mix(in srgb, var(--green) 45%, transparent) !important;
  transition: box-shadow var(--orv-t, .16s), border-color var(--orv-t, .16s);
}
.dark-mode input[type="text"]:focus,
.dark-mode input[type="email"]:focus,
.dark-mode input[type="password"]:focus,
.dark-mode input[type="number"]:focus,
.dark-mode textarea:focus,
.dark-mode select:focus {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 14%, transparent);
  border-color: color-mix(in srgb, var(--green) 40%, transparent) !important;
}

/* Card hover lift â€” applied universally to common card classes */
.camp-card,
.camp-recent-card,
.ncc-start-opt,
.cws-ov-card,
.lp-tmpl-card,
.lp-s-mod-card {
  transition: border-color .16s, transform .14s, box-shadow .14s;
  will-change: transform;
}

/* Loading button state */
.btn-loading {
  position: relative;
  color: transparent !important;
  pointer-events: none;
}
.btn-loading::after {
  content: '';
  position: absolute;
  width: 16px;
  height: 16px;
  top: 50%;
  left: 50%;
  margin: -8px 0 0 -8px;
  border: 2px solid rgba(255,255,255,.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: btnSpinO .7s linear infinite;
}
@keyframes btnSpinO { to { transform: rotate(360deg); } }

/* â”€â”€ REDESIGNED CAMPAIGN GENERATION OVERLAY â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
#camp-gen-overlay {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(8,8,10,.92);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 24px;
  transition: opacity .3s;
}
#camp-gen-overlay.cgo-entering {
  opacity: 0;
}

.cgo-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 400px;
  gap: 0;
}

/* Orb */
.cgo-orb {
  position: relative;
  width: 64px;
  height: 64px;
  margin-bottom: 22px;
}
.cgo-orb-ring {
  position: absolute;
  inset: -10px;
  border-radius: 50%;
  border: 1.5px solid color-mix(in srgb, var(--green) 25%, transparent);
  animation: cgoRing 2.8s linear infinite;
}
.cgo-orb-ring::before {
  content: '';
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--green) 12%, transparent);
  animation: cgoRing 4s linear infinite reverse;
}
@keyframes cgoRing {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
.cgo-orb-img {
  position: absolute;
  inset: 8px;
  border-radius: 14px;
  background: rgba(255,255,255,.06);
  padding: 7px;
  object-fit: contain;
}

/* Header */
.cgo-header {
  text-align: center;
  margin-bottom: 20px;
}
.cgo-title {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -.02em;
  margin-bottom: 4px;
}
.cgo-camp-name {
  font-size: 13px;
  color: rgba(255,255,255,.4);
}

/* Progress bar */
.cgo-bar-track {
  width: 100%;
  height: 2px;
  background: rgba(255,255,255,.08);
  border-radius: 2px;
  overflow: hidden;
  margin-bottom: 24px;
}
.cgo-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, color-mix(in srgb, var(--green) 60%, transparent), var(--green));
  border-radius: 2px;
  transition: width .6s cubic-bezier(.4,0,.2,1);
}

/* Module list */
.cgo-modules {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 20px;
}

.cgo-mod-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 14px;
  border-radius: 9px;
  border: 1px solid transparent;
  transition: background .25s, border-color .25s, opacity .25s;
  opacity: .35;
}

.cgo-mod-status-ico {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.2);
  flex-shrink: 0;
  transition: border-color .3s, background .3s;
}

.cgo-mod-name {
  font-size: 13px;
  color: rgba(255,255,255,.7);
  flex: 1;
}

.cgo-mod-badge {
  font-size: 11px;
  color: rgba(255,255,255,.3);
  font-weight: 500;
  white-space: nowrap;
}

/* Queued state */
.cgo-mod-queued {
  opacity: .3;
}

/* Generating state */
.cgo-mod-gen {
  opacity: 1;
  background: color-mix(in srgb, var(--green) 4%, transparent);
  border-color: color-mix(in srgb, var(--green) 12%, transparent);
}
.cgo-mod-gen .cgo-mod-status-ico {
  border-color: var(--green);
  background: color-mix(in srgb, var(--green) 10%, transparent);
  animation: cgoModPulse 1s ease-in-out infinite alternate;
}
@keyframes cgoModPulse {
  from { box-shadow: 0 0 0 0 color-mix(in srgb, var(--green) 50%, transparent); }
  to   { box-shadow: 0 0 0 4px color-mix(in srgb, var(--green) 0%, transparent); }
}
.cgo-mod-gen .cgo-mod-name { color: rgba(255,255,255,.95); }
.cgo-mod-gen .cgo-mod-badge { color: var(--green); font-weight: 600; }

/* Done state */
.cgo-mod-done {
  opacity: .65;
}
.cgo-mod-done .cgo-mod-status-ico {
  border-color: color-mix(in srgb, var(--green) 50%, transparent);
  background: color-mix(in srgb, var(--green) 12%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
}
.cgo-mod-done .cgo-mod-status-ico::after {
  content: '';
  display: block;
  width: 6px;
  height: 4px;
  border-left: 1.5px solid var(--green);
  border-bottom: 1.5px solid var(--green);
  transform: rotate(-45deg) translate(0.5px, -0.5px);
}
.cgo-mod-done .cgo-mod-badge {
  color: color-mix(in srgb, var(--green) 60%, transparent);
  font-weight: 600;
}

/* AI label */
.cgo-ai-label {
  font-size: 12px;
  color: rgba(255,255,255,.3);
  text-align: center;
  min-height: 18px;
  transition: opacity .3s;
}

/* ── Generation error state ── */
.cgo-error-state {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  z-index: 10;
  padding: 32px;
  text-align: center;
}
.cgo-error-ico {
  font-size: 32px;
  line-height: 1;
  margin-bottom: 4px;
}
.cgo-error-title {
  font-size: 17px;
  font-weight: 600;
  color: #F0F0F0;
}
.cgo-error-sub {
  font-size: 13px;
  color: rgba(240,240,240,.5);
  max-width: 280px;
  line-height: 1.45;
}
.cgo-error-btns {
  display: flex;
  gap: 10px;
  margin-top: 6px;
}
.cgo-retry-btn {
  padding: 9px 20px;
  background: var(--green);
  color: #0D0D0F;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity .15s;
}
.cgo-retry-btn:hover { opacity: .85; }
.cgo-dismiss-btn {
  padding: 9px 20px;
  background: rgba(255,255,255,.08);
  color: rgba(255,255,255,.7);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background .15s;
}
.cgo-dismiss-btn:hover { background: rgba(255,255,255,.13); }

/* â”€â”€ MOBILE BOTTOM NAVIGATION â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
#mobileBottomNav {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1002;
  background: var(--surface, #fff);
  border-top: 1px solid var(--border, rgba(0,0,0,.08));
  padding: 0 8px;
  padding-bottom: env(safe-area-inset-bottom, 0px);
  height: calc(56px + env(safe-area-inset-bottom, 0px));
  align-items: center;
  justify-content: space-around;
  box-shadow: 0 -1px 20px rgba(0,0,0,.06);
}
.dark-mode #mobileBottomNav {
  background: #111113;
  border-color: rgba(255,255,255,.07);
  box-shadow: 0 -1px 20px rgba(0,0,0,.3);
}

.mbn-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 6px 12px;
  background: none;
  border: none;
  cursor: pointer;
  border-radius: 10px;
  transition: background .14s;
  color: var(--muted, #888);
  font-family: inherit;
  min-width: 56px;
}
.mbn-item:active { transform: scale(.93); }
.mbn-item svg {
  width: 22px;
  height: 22px;
  transition: stroke .14s;
}
.mbn-item span {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .02em;
  transition: color .14s;
}
.mbn-item.mbn-active { color: var(--gm, #1A4229); }
.dark-mode .mbn-item.mbn-active { color: var(--green); }

/* Create button â€” center floating */
.mbn-create-btn {
  width: 44px;
  height: 44px;
  min-width: 44px;
  border-radius: 14px;
  background: var(--gm, #1A4229);
  color: #fff;
  padding: 0;
  box-shadow: 0 4px 14px rgba(26,66,41,.35);
  margin-bottom: 2px;
}
.dark-mode .mbn-create-btn { background: var(--green); color: #000; box-shadow: 0 4px 14px color-mix(in srgb, var(--green) 25%, transparent); }
.mbn-create-btn svg { width: 18px; height: 18px; }

@media (max-width: 768px) {
  #mobileBottomNav { display: flex; }

  /* Push page content up so bottom nav doesn't cover it */
  .mc {
    padding-bottom: calc(56px + env(safe-area-inset-bottom, 0px));
  }

  /* Hide hamburger button â€” bottom nav replaces sidebar access */
  #sbToggle { display: none !important; }

  /* Workspace on mobile â€” stack vertically */
  .cws { flex-direction: column; }
  .cws-sb {
    width: 100%;
    height: auto;
    border-right: none;
    border-bottom: 1px solid var(--border, rgba(0,0,0,.07));
    flex-shrink: 0;
  }
  .cws-nav {
    display: flex;
    flex-direction: row;
    overflow-x: auto;
    padding: 8px 10px;
    gap: 4px;
    scrollbar-width: none;
  }
  .cws-nav::-webkit-scrollbar { display: none; }
  .cws-nav-item {
    white-space: nowrap;
    flex-shrink: 0;
    padding: 6px 12px;
    font-size: 12px;
  }
  .cws-sb-bot { display: none; }
  .cws-main-inner { padding: 20px 16px; }

  /* Campaign hub on mobile */
  .camp-hub { padding: 16px 16px 24px; }
  .camp-hub-recent-row { grid-template-columns: 1fr; }
  .camp-card-grid { grid-template-columns: 1fr; }
  .camp-hub-hdr { flex-direction: column; align-items: flex-start; }

  /* New campaign modal on mobile */
  .ncc-modal { padding: 24px 20px 20px; }
  .ncc-tpl-grid { grid-template-columns: repeat(2, 1fr); }
  .ncc-mod-grid { grid-template-columns: repeat(2, 1fr); }

  /* Generation overlay on mobile */
  .cgo-inner { max-width: 100%; }
  .cgo-modules { max-height: 220px; overflow-y: auto; }

  /* Overview grid on mobile */
  .cws-ov-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .cws-ov-grid { grid-template-columns: 1fr; }
  .cgo-modules { max-height: 180px; }
}

/* â”€â”€ Typography polish â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Ensure consistent heading hierarchy across app pages */
.camp-hub-title,
.cws-mod-title,
.cws-ov-name {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: -.025em;
}

/* Body text comfort */
.cws-strat-body,
.cws-email-body,
.cws-post-caption,
.camp-card-goal {
  line-height: 1.65;
}

/* Muted labels consistent weight */
.camp-card-date,
.cws-nav-done,
.cgo-ai-label,
.cgo-camp-name {
  font-weight: 400;
}

/* â”€â”€ Progress bar animated fill (global) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.camp-card-prog-fill,
.cws-progress-fill,
.cws-ov-prog-fill {
  transition: width .7s cubic-bezier(.4,0,.2,1);
}

/* â”€â”€ Reduced motion overrides â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
@media (prefers-reduced-motion: reduce) {
  .page.active { animation: none; }
  .cgo-orb-ring, .cgo-mod-gen .cgo-mod-status-ico,
  .camp-card, .camp-recent-card, .ncc-start-opt,
  .cws-ov-card { animation: none !important; transition: none !important; }
  .camp-card-prog-fill,
  .cws-progress-fill,
  .cws-ov-prog-fill { transition: none; }
}

/* â”€â”€ Scrollbar polish â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.cws-main::-webkit-scrollbar,
.cws-nav::-webkit-scrollbar,
.ncc-modal::-webkit-scrollbar {
  width: 4px;
}
.cws-main::-webkit-scrollbar-track,
.ncc-modal::-webkit-scrollbar-track { background: transparent; }
.cws-main::-webkit-scrollbar-thumb,
.ncc-modal::-webkit-scrollbar-thumb {
  background: rgba(0,0,0,.12);
  border-radius: 4px;
}
.dark-mode .cws-main::-webkit-scrollbar-thumb,
.dark-mode .ncc-modal::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,.1);
}

/* â”€â”€ Focus visible (accessibility) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
button:focus-visible,
a:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--gm, #1A4229);
  outline-offset: 2px;
  border-radius: 4px;
}
.dark-mode button:focus-visible,
.dark-mode a:focus-visible,
.dark-mode [tabindex]:focus-visible {
  outline-color: var(--green);
}

/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   ORIVEN 3.0 â€” PART 4/4 ADDITIONS
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

/* Module header title + version meta */
.cws-mod-title-wrap {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.cws-mod-meta {
  font-size: 11px;
