}

/* Danger action button */
.cws-act-danger {
  color: #c0392b;
  border-color: rgba(192, 57, 43, .2);
}
.cws-act-danger:hover {
  border-color: #c0392b;
  color: #c0392b;
  background: rgba(192,57,43,.04);
}
.dark-mode .cws-act-danger {
  color: #ff6b6b;
  border-color: rgba(255,107,107,.2);
}
.dark-mode .cws-act-danger:hover {
  border-color: rgba(255,107,107,.5);
  background: rgba(255,107,107,.04);
}

/* Opportunities nav item hidden from sidebar */
.ni[data-page="opportunities"] { display: none !important; }

/* Target audience field spacing */
#nccAudience {
