    radial-gradient(ellipse 55% 35% at 85% 8%,  color-mix(in srgb, var(--green) 5%, transparent) 0%, transparent 60%),
    radial-gradient(ellipse 90% 50% at 50% 95%, rgba(10,15,25,.9)    0%, transparent 75%),
    #08080A !important;
}

/* ── Hero preview showcase ───────────────────────────────────────── */
.lp-hero-previews {
  width: 100%;
  overflow: hidden;
  margin-top: 52px;
  mask-image:
    linear-gradient(to right, transparent 0%, black 9%, black 91%, transparent 100%);
  -webkit-mask-image:
    linear-gradient(to right, transparent 0%, black 9%, black 91%, transparent 100%);
}
.lp-preview-rail {
  display: flex;
  gap: 16px;
  width: max-content;
  padding: 14px 100px 40px;
  will-change: transform;
}
.lp-pv-card {
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,.07);
  background: rgba(14,14,18,.95);
  box-shadow: 0 20px 60px rgba(0,0,0,.55), 0 0 0 1px rgba(255,255,255,.04);
  overflow: hidden;
  flex-shrink: 0;
  color: rgba(255,255,255,.75);
  font-family: inherit;
  transition: transform 0.35s cubic-bezier(0.34,1.56,0.64,1), box-shadow 0.35s ease;
}
.lp-pv-card:hover {
  transform: translateY(-8px) scale(1.02) !important;
  box-shadow: 0 32px 80px rgba(0,0,0,.6), 0 0 0 1px color-mix(in srgb, var(--green) 14%, transparent) !important;
}

/* Meta Ad card */
.lp-pv-meta-ad { width: 255px; }
.lp-pv-ma-header {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 14px 10px;
}
.lp-pv-ma-av {
  width: 30px; height: 30px; border-radius: 50%;
  background: linear-gradient(135deg, var(--green) 0%, var(--green-text) 100%);
  flex-shrink: 0;
}
.lp-pv-ma-brand { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.9); }
.lp-pv-ma-tag   { font-size: 10px; color: rgba(255,255,255,.32); margin-top: 1px; }
.lp-pv-ma-img {
  width: 100%; height: 126px;
  background: linear-gradient(140deg, #0f2027 0%, #203a43 50%, #2c5364 100%);
  display: flex; align-items: center; justify-content: center;
  position: relative;
}
.lp-pv-ma-img::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to bottom, transparent 55%, rgba(14,14,18,.85));
}
.lp-pv-ma-img-text {
  font-size: 14px; font-weight: 700; color: rgba(255,255,255,.95);
  text-align: center; line-height: 1.4; letter-spacing: -.3px;
  z-index: 1; padding: 0 16px;
}
.lp-pv-ma-copy { padding: 11px 14px 7px; }
.lp-pv-ma-headline {
  font-size: 12px; font-weight: 600; color: rgba(255,255,255,.9);
  line-height: 1.4; margin-bottom: 4px;
}
.lp-pv-ma-desc { font-size: 10px; color: rgba(255,255,255,.4); line-height: 1.5; }
.lp-pv-ma-cta {
  margin: 10px 14px 14px;
  background: #1877F2; color: #fff;
  font-size: 12px; font-weight: 600;
  padding: 8px 0; border-radius: 8px; text-align: center;
}

/* Landing Page card */
.lp-pv-landing { width: 305px; }
.lp-pv-lp-chrome {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 12px;
  background: rgba(255,255,255,.04);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.lp-pv-lp-dots { display: flex; gap: 5px; }
.lp-pv-lp-dots span { width: 8px; height: 8px; border-radius: 50%; }
.lp-pv-lp-dots span:nth-child(1) { background: #ff5f56; }
.lp-pv-lp-dots span:nth-child(2) { background: #ffbd2e; }
.lp-pv-lp-dots span:nth-child(3) { background: #27c93f; }
.lp-pv-lp-url {
  flex: 1; background: rgba(255,255,255,.06); border-radius: 5px;
  padding: 3px 8px; font-size: 9px; color: rgba(255,255,255,.3); text-align: center;
}
.lp-pv-lp-content { padding: 16px 18px 20px; }
.lp-pv-lp-nav { display: flex; align-items: center; gap: 8px; margin-bottom: 18px; }
.lp-pv-lp-logo {
  width: 56px; height: 5px;
  background: rgba(255,255,255,.18); border-radius: 3px;
}
.lp-pv-lp-navlinks { display: flex; gap: 6px; margin-left: auto; }
.lp-pv-lp-navlinks span {
  width: 22px; height: 4px;
  background: rgba(255,255,255,.08); border-radius: 2px;
}
.lp-pv-lp-hero { text-align: center; padding: 12px 0 16px; }
.lp-pv-lp-h1 {
  font-size: 16px; font-weight: 700; color: rgba(255,255,255,.9);
  line-height: 1.35; letter-spacing: -.4px; margin-bottom: 14px;
}
.lp-pv-lp-cta {
  display: inline-block;
  background: linear-gradient(135deg, var(--green), var(--gm));
  color: #000; font-size: 11px; font-weight: 700;
  padding: 7px 20px; border-radius: 8px;
}

/* Email card */
.lp-pv-email { width: 250px; }
.lp-pv-em-header {
  padding: 11px 14px 10px;
  border-bottom: 1px solid rgba(255,255,255,.06);
  background: rgba(255,255,255,.02);
}
.lp-pv-em-from    { font-size: 10px; color: rgba(255,255,255,.3); margin-bottom: 3px; }
.lp-pv-em-subject { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.85); line-height: 1.4; }
.lp-pv-em-body    { padding: 11px 14px 14px; }
.lp-pv-em-greeting { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.8); margin-bottom: 7px; }
.lp-pv-em-text     { font-size: 10px; color: rgba(255,255,255,.42); line-height: 1.6; margin-bottom: 11px; }
.lp-pv-em-cta {
  display: inline-block;
  background: color-mix(in srgb, var(--green) 10%, transparent); color: var(--green);
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  font-size: 10px; font-weight: 600;
  padding: 5px 12px; border-radius: 6px; margin-bottom: 11px;
}
.lp-pv-em-divider  { height: 1px; background: rgba(255,255,255,.06); margin-bottom: 9px; }
.lp-pv-em-feat-row { display: flex; align-items: center; gap: 6px; font-size: 10px; color: rgba(255,255,255,.5); padding: 2px 0; }
.lp-pv-em-chk      { color: var(--green); }

/* UGC / Video card */
.lp-pv-ugc { width: 185px; }
.lp-pv-ugc-bg {
  height: 305px;
  background: linear-gradient(160deg, #1a0533 0%, #2d1b69 50%, #11998e 100%);
  position: relative;
  display: flex; align-items: center; justify-content: center;
}
.lp-pv-ugc-play { font-size: 26px; opacity: .55; color: rgba(255,255,255,.8); position: relative; z-index: 1; }
.lp-pv-ugc-overlay {
  position: absolute; bottom: 0; left: 0; right: 0;
  padding: 10px 12px;
  background: linear-gradient(to top, rgba(0,0,0,.8), transparent);
  z-index: 2;
}
.lp-pv-ugc-user    { font-size: 11px; font-weight: 700; color: #fff; margin-bottom: 3px; }
.lp-pv-ugc-caption { font-size: 10px; color: rgba(255,255,255,.72); margin-bottom: 7px; }
.lp-pv-ugc-actions { display: flex; gap: 10px; }
.lp-pv-ugc-action  { font-size: 10px; color: rgba(255,255,255,.65); display: flex; align-items: center; gap: 3px; }

/* Strategy / Plan card */
.lp-pv-strategy { width: 270px; padding: 16px; }
.lp-pv-st-header { margin-bottom: 14px; }
.lp-pv-st-badge {
  display: inline-flex; align-items: center;
  background: color-mix(in srgb, var(--green) 10%, transparent); color: var(--green);
  border: 1px solid color-mix(in srgb, var(--green) 18%, transparent);
  font-size: 9px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  padding: 3px 8px; border-radius: 5px; margin-bottom: 6px;
}
.lp-pv-st-title { font-size: 12px; font-weight: 700; color: rgba(255,255,255,.9); letter-spacing: -.2px; line-height: 1.35; }
.lp-pv-st-body  { display: flex; flex-direction: column; gap: 7px; }
.lp-pv-st-item  { display: flex; align-items: flex-start; gap: 8px; font-size: 10px; color: rgba(255,255,255,.52); line-height: 1.5; }
.lp-pv-st-dot   { width: 5px; height: 5px; border-radius: 50%; background: color-mix(in srgb, var(--green) 45%, transparent); margin-top: 4px; flex-shrink: 0; }
.lp-pv-st-bar   { margin-top: 10px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,.06); }
.lp-pv-st-bar-label { font-size: 9px; color: rgba(255,255,255,.3); margin-bottom: 5px; text-transform: uppercase; letter-spacing: .06em; }
.lp-pv-st-bar-track { height: 4px; background: rgba(255,255,255,.08); border-radius: 2px; overflow: hidden; }
.lp-pv-st-bar-fill  { height: 100%; background: linear-gradient(90deg, var(--green-text), var(--green)); border-radius: 2px; }
.lp-pv-st-bar-pct   { font-size: 10px; color: var(--green); font-weight: 600; margin-top: 5px; text-align: right; }

/* ── Pricing: tighter layout, identical card spacing ────────────── */
.lp-pricing-grid {
  display: grid !important;
  grid-template-columns: repeat(4, 1fr) !important;
  gap: 14px !important;
}
.lp-plan { border-radius: 14px !important; }

/* ── Reviews: breathing room ─────────────────────────────────────── */
.lp-reviews-grid { gap: 16px !important; }
.lp-s-tcard      { padding: 24px 22px !important; border-radius: 14px !important; }

/* ── Mobile responsive for preview rail + pricing ────────────────── */
@media (max-width: 768px) {
  .lp-hero-previews { margin-top: 36px; }
  .lp-preview-rail  { padding: 8px 32px 24px; gap: 12px; }
  .lp-pv-card       { transform: scale(0.82); transform-origin: top left; }
  .lp-pricing-grid  { grid-template-columns: 1fr 1fr !important; gap: 12px !important; }
  .lp-reviews-grid  { grid-template-columns: 1fr !important; }
}
@media (max-width: 480px) {
  .lp-pricing-grid { grid-template-columns: 1fr !important; }
}

/* ══════════════════════════════════════════════════════════════════
   LP WORLD-CLASS REFINEMENT — Prompt 4
   ══════════════════════════════════════════════════════════════════ */

/* ── Hero layout: always column ──────────────────────────────────── */
.lp-hero {
  flex-direction: column !important;
  align-items: center !important;
}

/* ── Hero typing prompt demo ──────────────────────────────────────── */
.lp-hero-prompt {
  width: 100%;
  max-width: 600px;
  margin: 44px auto 0;
  padding: 0 24px;
  box-sizing: border-box;
}
.lp-hero-prompt-inner {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 14px;
  padding: 18px 20px;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}
.lp-hero-prompt-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  min-height: 24px;
}
.lp-hero-prompt-label {
  font-size: 10px;
  font-weight: 700;
  color: rgba(255,255,255,.28);
  text-transform: uppercase;
  letter-spacing: .12em;
  flex-shrink: 0;
}
.lp-hero-prompt-body {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
}
.lp-hero-prompt-text {
  font-size: 14px;
  color: rgba(255,255,255,.82);
  line-height: 1.5;
}
.lp-hero-prompt-cursor {
  display: inline-block;
  width: 1.5px;
  height: 17px;
  background: var(--green);
  border-radius: 1px;
  animation: lpCursorBlink 0.85s step-end infinite;
  margin-left: 1px;
  vertical-align: middle;
  flex-shrink: 0;
}
@keyframes lpCursorBlink {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0; }
}
.lp-hero-prompt-outputs {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.lp-pv-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 600;
  color: var(--green);
  background: color-mix(in srgb, var(--green) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 18%, transparent);
  border-radius: 20px;
  padding: 3px 10px;
  letter-spacing: .01em;
}
.lp-pv-tag::before {
  content: '✓';
  font-size: 9px;
}

/* ── Preview depth layer (behind the front rail) ─────────────────── */
.lp-hero-previews { position: relative !important; }
.lp-preview-back {
  position: absolute;
  top: 44px;
  left: 0;
  display: flex;
  gap: 20px;
  padding: 0 100px;
  will-change: transform;
  pointer-events: none;
  z-index: 0;
  opacity: 0;
  transition: opacity 0.9s ease 0.15s;
}
.lp-preview-back.lp-back-visible { opacity: 1; }
.lp-preview-rail { position: relative; z-index: 1; }
.lp-pv-ghost {
  width: 210px;
  height: 225px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--green) 1.8%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 5.5%, transparent);
  flex-shrink: 0;
  backdrop-filter: blur(2px);
}
.lp-pv-ghost--tall { height: 295px; }
.lp-pv-ghost--wide { width: 270px; }

/* Preserve enough height in the previews container for back layer */
.lp-hero-previews { min-height: 380px; }

/* ── Campaign Builder large mockup ─────────────────────────────── */
.lp-cb {
  width: 100%;
  max-width: 900px;
  margin: 0 auto 56px;
  border-radius: 18px;
  border: 1px solid rgba(255,255,255,.08);
  background: rgba(10,10,14,.97);
  box-shadow: 0 40px 100px rgba(0,0,0,.65), 0 0 0 1px rgba(255,255,255,.04);
  overflow: hidden;
}
.lp-cb-chrome {
  display: flex;
  align-items: center;
  padding: 11px 16px;
  border-bottom: 1px solid rgba(255,255,255,.06);
  background: rgba(255,255,255,.015);
  gap: 10px;
}
.lp-cb-chrome-dots { display: flex; gap: 5px; flex-shrink: 0; }
.lp-cb-chrome-dots span { width: 9px; height: 9px; border-radius: 50%; }
.lp-cb-chrome-dots span:nth-child(1) { background: #ff5f56; }
.lp-cb-chrome-dots span:nth-child(2) { background: #ffbd2e; }
.lp-cb-chrome-dots span:nth-child(3) { background: #27c93f; }
.lp-cb-chrome-title {
  font-size: 11.5px; font-weight: 600; color: rgba(255,255,255,.42);
  flex: 1; text-align: center;
}
.lp-cb-chrome-status {
  display: flex; align-items: center; gap: 6px;
  font-size: 10px; color: rgba(255,255,255,.3); flex-shrink: 0;
}
.lp-cb-status-pulse {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--green);
  animation: lpPulseDot 1.8s ease-in-out infinite;
}
@keyframes lpPulseDot {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.3; }
}

.lp-cb-body { display: flex; min-height: 310px; }

.lp-cb-sidebar {
  width: 180px;
  flex-shrink: 0;
  border-right: 1px solid rgba(255,255,255,.06);
  display: flex; flex-direction: column;
}
.lp-cb-sb-head {
  padding: 16px 14px 13px;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.lp-cb-sb-label {
  font-size: 9px; text-transform: uppercase; letter-spacing: .08em;
  color: rgba(255,255,255,.22); margin-bottom: 4px;
}
.lp-cb-sb-name {
  font-size: 12px; font-weight: 600; color: rgba(255,255,255,.78); line-height: 1.3;
}
.lp-cb-sb-items { padding: 10px 8px; display: flex; flex-direction: column; gap: 1px; }
.lp-cb-it {
  display: flex; align-items: center; gap: 7px;
  padding: 6px 8px; border-radius: 7px;
  font-size: 11px; color: rgba(255,255,255,.35);
}
.lp-cb-it--done { color: rgba(255,255,255,.65); }
.lp-cb-it--active { background: color-mix(in srgb, var(--green) 7%, transparent); color: rgba(255,255,255,.9); }
.lp-cb-it-dot {
  width: 5px; height: 5px; border-radius: 50%;
  background: rgba(255,255,255,.14); flex-shrink: 0;
}
.lp-cb-it--done   .lp-cb-it-dot { background: color-mix(in srgb, var(--green) 75%, transparent); }
.lp-cb-it--active .lp-cb-it-dot { background: var(--green); animation: lpPulseDot 1.5s ease-in-out infinite; }
.lp-cb-it-lbl { flex: 1; font-size: 11px; }
.lp-cb-it-st { font-size: 9px; color: rgba(255,255,255,.22); }
.lp-cb-it--done   .lp-cb-it-st { color: color-mix(in srgb, var(--green) 45%, transparent); }
.lp-cb-it--active .lp-cb-it-st { color: var(--green); }

.lp-cb-main { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.lp-cb-tabs {
  display: flex; border-bottom: 1px solid rgba(255,255,255,.06); padding: 0 18px;
}
.lp-cb-tab {
  padding: 11px 14px; font-size: 11.5px; color: rgba(255,255,255,.35);
  cursor: default; position: relative; white-space: nowrap;
}
.lp-cb-tab--active { color: rgba(255,255,255,.88); }
.lp-cb-tab--active::after {
  content: ''; position: absolute; bottom: -1px; left: 0; right: 0;
  height: 1.5px; background: var(--green); border-radius: 1px;
}
.lp-cb-content {
  flex: 1; padding: 20px 18px;
  display: flex; flex-direction: column; gap: 16px;
}
.lp-cb-ads { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.lp-cb-ad {
  border-radius: 10px; border: 1px solid rgba(255,255,255,.07);
  background: rgba(255,255,255,.022); overflow: hidden;
}
.lp-cb-ad-img {
  height: 72px;
  background: linear-gradient(140deg, #0f2027 0%, #203a43 55%, #2c5364 100%);
}
.lp-cb-ad-img--b {
  background: linear-gradient(140deg, #1a0533 0%, #2d1b69 55%, #11998e 100%);
}
.lp-cb-ad-body { padding: 10px 12px; }
.lp-cb-ad-head {
  font-size: 11px; font-weight: 600; color: rgba(255,255,255,.82);
  line-height: 1.4; margin-bottom: 3px;
}
.lp-cb-ad-copy {
  font-size: 9.5px; color: rgba(255,255,255,.36); line-height: 1.5; margin-bottom: 8px;
}
.lp-cb-ad-cta {
  display: inline-block; background: #1877F2; color: #fff;
  font-size: 9.5px; font-weight: 600; padding: 4px 10px; border-radius: 5px;
}
.lp-cb-metrics {
  display: flex; gap: 28px;
  padding-top: 14px; border-top: 1px solid rgba(255,255,255,.06);
}
.lp-cb-metric-v {
  font-size: 20px; font-weight: 700; letter-spacing: -.02em;
  color: rgba(255,255,255,.88); margin-bottom: 2px;
}
.lp-cb-metric-l {
  font-size: 9.5px; text-transform: uppercase; letter-spacing: .06em;
  color: rgba(255,255,255,.28);
}

/* ── How It Works: visual chips per step ─────────────────────────── */
.lp-step-visual { margin-top: 24px; display: flex; justify-content: center; }
.lp-step-bp-chip {
  display: flex; align-items: center; gap: 10px;
  background: rgba(255,255,255,.045);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 12px; padding: 10px 14px;
  width: 100%; max-width: 216px;
}
.lp-step-bp-av {
  width: 26px; height: 26px; border-radius: 50%;
  background: linear-gradient(135deg, var(--green) 0%, var(--green-text) 100%);
  flex-shrink: 0;
}
.lp-step-bp-nm  { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.8); margin-bottom: 4px; }
.lp-step-bp-bars { display: flex; gap: 3px; }
.lp-step-bp-bars span { height: 3px; border-radius: 2px; background: rgba(255,255,255,.18); }
.lp-step-bp-b1 { width: 32px; }
.lp-step-bp-b2 { width: 22px; }
.lp-step-bp-b3 { width: 14px; }
.lp-step-bp-ck { color: var(--green); font-size: 14px; margin-left: auto; flex-shrink: 0; }

.lp-step-mods { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; max-width: 240px; }
.lp-step-mod {
  font-size: 10px; padding: 4px 10px;
  border-radius: 20px; border: 1px solid rgba(255,255,255,.1);
  color: rgba(255,255,255,.28);
}
.lp-step-mod--on {
  background: color-mix(in srgb, var(--green) 8%, transparent);
  border-color: color-mix(in srgb, var(--green) 22%, transparent);
  color: var(--green);
}

.lp-step-ready {
  display: flex; align-items: center; gap: 12px;
  background: color-mix(in srgb, var(--green) 7%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 18%, transparent);
  border-radius: 12px; padding: 12px 16px;
}
.lp-step-ready-ico { font-size: 18px; color: var(--green); }
.lp-step-ready-t { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.85); margin-bottom: 2px; }
.lp-step-ready-s { font-size: 10px; color: rgba(255,255,255,.38); }

/* ── Mobile responsive additions ─────────────────────────────────── */
@media (max-width: 768px) {
  .lp-hero-prompt { margin-top: 32px; padding: 0 16px; }
  .lp-hero-prompt-text { font-size: 13px; }
  .lp-cb { border-radius: 12px; }
  .lp-cb-sidebar { display: none; }
  .lp-cb-ads { grid-template-columns: 1fr; gap: 10px; }
  .lp-cb-metrics { gap: 16px; }
  .lp-pv-tag { font-size: 9px; padding: 2px 8px; }
  .lp-hero-previews { min-height: auto; }
  .lp-preview-back { display: none; }
  .lp-step-bp-chip, .lp-step-mods, .lp-step-ready { max-width: 200px; }
}
@media (max-width: 480px) {
  .lp-hero-prompt-outputs { gap: 5px; }
  .lp-cb-chrome-status { display: none; }
}

/* ═══════════════════════════════════════════════════════════════════
