.cs-badge--blue { background: rgba(96,165,250,.10); color: #60A5FA; border: 1px solid rgba(96,165,250,.18); }
.cs-badge--dim  { background: rgba(255,255,255,.05); color: rgba(255,255,255,.36); border: 1px solid rgba(255,255,255,.09); }

/* ── Meta Ad Generator ───────────────────────────────────────────── */
.cs-gen { width: 920px; }
.cs-gen-top {
  display: flex; align-items: center;
  padding: 11px 18px;
  background: rgba(255,255,255,.025);
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.cs-gen-bc { font-size: 11px; color: rgba(255,255,255,.28); }
