}
.cs-gen-brand-name { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.80); }
.cs-gen-brand-tag  { font-size: 9px; color: color-mix(in srgb, var(--green) 62%, transparent); margin-top: 1px; }
.cs-gen-brand-ck   { color: var(--green); font-size: 13px; margin-left: auto; }
.cs-gen-right { padding: 18px 18px; display: flex; flex-direction: column; }
.cs-gen-tabs {
  display: flex; border-bottom: 1px solid rgba(255,255,255,.06); margin-bottom: 14px;
}
.cs-gen-tab {
  padding: 7px 13px; font-size: 11px; color: rgba(255,255,255,.30); position: relative;
}
.cs-gen-tab--active { color: rgba(255,255,255,.85); }
.cs-gen-tab--active::after {
  content: ''; position: absolute; bottom: -1px; left: 0; right: 0;
  height: 1.5px; background: var(--green);
}
.cs-gen-output { display: flex; gap: 14px; flex: 1; }
.cs-gen-ad {
  width: 192px; flex-shrink: 0;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 11px; overflow: hidden;
  background: rgba(255,255,255,.02);
}
.cs-gen-ad-hd { display: flex; align-items: center; gap: 7px; padding: 9px 10px; }
.cs-gen-ad-av {
  width: 24px; height: 24px; border-radius: 50%; flex-shrink: 0;
  background: linear-gradient(135deg, var(--green) 0%, var(--green-text) 100%);
}
.cs-gen-ad-brand  { font-size: 10.5px; font-weight: 600; color: rgba(255,255,255,.76); }
.cs-gen-ad-sp     { font-size: 9px; color: rgba(255,255,255,.28); }
.cs-gen-ad-img {
  width: 100%; height: 96px;
  background: linear-gradient(145deg, #0d1f2d 0%, #19384a 55%, #0c2233 100%);
  display: flex; align-items: center; justify-content: center; padding: 0 12px;
}
.cs-gen-ad-img-txt {
  font-size: 13px; font-weight: 700; color: rgba(255,255,255,.92);
  text-align: center; line-height: 1.45;
}
.cs-gen-ad-copy { padding: 9px 10px; }
.cs-gen-ad-hl   { font-size: 10.5px; font-weight: 600; color: rgba(255,255,255,.80); line-height: 1.4; margin-bottom: 4px; }
.cs-gen-ad-body { font-size: 9.5px; color: rgba(255,255,255,.38); line-height: 1.5; margin-bottom: 8px; }
.cs-gen-ad-cta {
  display: block; margin: 0 10px 10px;
  background: #1877F2; color: #fff;
  font-size: 10.5px; font-weight: 600;
