}
.cs-gen-metrics {
  flex: 1; border-left: 1px solid rgba(255,255,255,.06);
  padding-left: 14px;
  display: flex; flex-direction: column; justify-content: center; gap: 14px;
}
.cs-gen-metric-v {
  font-size: 22px; font-weight: 700; letter-spacing: -.02em;
  color: rgba(255,255,255,.88); margin-bottom: 2px;
}
.cs-gen-metric-l {
  font-size: 9.5px; text-transform: uppercase; letter-spacing: .07em;
  color: rgba(255,255,255,.28);
}

/* ── Brand Profile Editor ────────────────────────────────────────── */
.cs-brand { width: 920px; }
.cs-brand-top {
  display: flex; align-items: center;
  padding: 11px 18px;
  background: rgba(255,255,255,.025);
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.cs-brand-title { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.76); }
.cs-brand-save {
  margin-left: auto; font-size: 10.5px; font-weight: 600; color: #000;
  background: linear-gradient(135deg, var(--green) 0%, var(--green-text) 100%);
  padding: 6px 12px; border-radius: 7px;
}
.cs-brand-body { display: flex; min-height: 360px; }
.cs-brand-nav {
  width: 158px; flex-shrink: 0;
  border-right: 1px solid rgba(255,255,255,.06);
  padding: 14px 8px;
  display: flex; flex-direction: column; gap: 1px;
}
.cs-brand-nav-item {
  padding: 7px 10px; font-size: 11.5px;
  color: rgba(255,255,255,.33); border-radius: 7px;
}
.cs-brand-nav-item--active { background: color-mix(in srgb, var(--green) 7%, transparent); color: rgba(255,255,255,.82); }
.cs-brand-content { flex: 1; padding: 18px 22px; min-width: 0; }
.cs-brand-sec {
  font-size: 9px; text-transform: uppercase; letter-spacing: .1em;
  color: rgba(255,255,255,.25); margin-bottom: 12px;
}
.cs-brand-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.cs-brand-field--full { grid-column: 1 / -1; }
.cs-brand-lbl { font-size: 10px; color: rgba(255,255,255,.30); margin-bottom: 4px; }
.cs-brand-inp {
  font-size: 12.5px; color: rgba(255,255,255,.76);
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 8px; padding: 8px 11px;
}
.cs-brand-textarea {
  font-size: 11px; color: rgba(255,255,255,.58); line-height: 1.6;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 8px; padding: 9px 11px;
}
.cs-brand-tags { display: flex; flex-wrap: wrap; gap: 7px; }
.cs-brand-tag {
  font-size: 10.5px; padding: 4px 12px; border-radius: 20px;
  border: 1px solid rgba(255,255,255,.09); color: rgba(255,255,255,.28);
}
.cs-brand-tag--on {
  background: color-mix(in srgb, var(--green) 8%, transparent); border-color: color-mix(in srgb, var(--green) 20%, transparent); color: var(--green);
}
.cs-brand-ai-chips { display: flex; flex-wrap: wrap; gap: 7px; }
.cs-brand-ai-chip {
  font-size: 10.5px; padding: 5px 11px; border-radius: 8px;
