}

/* ── Mobile: disable scroll animation, show screens statically ───── */
@media (max-width: 860px) {
  .cs-scene  { height: auto; }
  .cs-pin    { position: relative; height: auto; padding: 48px 16px 56px; flex-direction: column; gap: 28px; }
  .cs-intro  { position: relative; padding-top: 0; }
  .cs-screen { transform: none !important; opacity: 1 !important; width: 100% !important; overflow-x: auto; }
  .cs-dash, .cs-gen, .cs-brand { width: 700px; }
  .cs-dash-nav, .cs-brand-nav { display: none; }
  .cs-gen-left { display: none; }
}
@media (max-width: 520px) {
  .cs-dash, .cs-gen, .cs-brand { width: 540px; }
}

/* ═══════════════════════════════════════════════════════════════════
   CAMPAIGN JOURNEY — One continuous live demo experience
   Prompt 6: Product builds itself as visitor scrolls
   ═══════════════════════════════════════════════════════════════════ */

/* Hide previous CS scenes and intermediate sections */
#cs-dashboard, #cs-generator, #cs-brand { display: none !important; }
.lp-scene[data-index="1"],
.lp-scene[data-index="2"],
.lp-scene[data-index="3"] { display: none !important; }
.lp-nav-link[data-scene="1"],
.lp-nav-link[data-scene="2"],
.lp-nav-link[data-scene="3"] { display: none !important; }

/* ── Journey scroll container ────────────────────────────────────── */
.cj-wrap {
  position: relative;
  height: 1200vh;
}
.cj-pin {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

/* ── App window ──────────────────────────────────────────────────── */
.cj-window {
  width: 920px;
  height: 560px;
  background: #0C0C10;
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 14px;
  overflow: hidden;
  box-shadow:
    0 80px 160px rgba(0,0,0,.78),
    0 0 0 1px rgba(255,255,255,.04) inset,
    0 0 80px color-mix(in srgb, var(--green) 3%, transparent);
  will-change: transform, opacity;
  transform-origin: center center;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  opacity: 0;
  transform: scale(0.38);
}

/* ── Chrome bar ──────────────────────────────────────────────────── */
.cj-chrome {
  display: flex;
  align-items: center;
  height: 42px;
  padding: 0 16px;
  background: rgba(255,255,255,.025);
  border-bottom: 1px solid rgba(255,255,255,.07);
  flex-shrink: 0;
  gap: 14px;
}
.cj-chrome-dots { display: flex; gap: 6px; }
.cj-chrome-dot {
  width: 11px; height: 11px; border-radius: 50%;
}
.cj-chrome-dot--r { background: #FF5F57; }
.cj-chrome-dot--y { background: #FFBD2E; }
.cj-chrome-dot--g { background: #28CA40; }
.cj-chrome-title {
  flex: 1; text-align: center;
  font-size: 11.5px; font-weight: 500;
  color: rgba(255,255,255,.45);
  transition: color 0.35s ease;
}
.cj-chrome-badge {
  font-size: 10px; font-weight: 600;
  padding: 3px 9px; border-radius: 20px;
  min-width: 62px; text-align: center;
  transition: all 0.35s ease;
  opacity: 0;
}
.cj-chrome-badge--building {
  opacity: 1;
  background: rgba(251,191,36,.10);
  color: #FBBF24;
  border: 1px solid rgba(251,191,36,.20);
}
.cj-chrome-badge--ready {
  opacity: 1;
  background: color-mix(in srgb, var(--green) 10%, transparent);
  color: var(--green);
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
}

/* ── Body: sidebar + panels ──────────────────────────────────────── */
.cj-body { display: flex; flex: 1; overflow: hidden; }

.cj-sidebar {
  width: 158px; flex-shrink: 0;
  border-right: 1px solid rgba(255,255,255,.06);
  padding: 12px 8px;
  display: flex; flex-direction: column; gap: 1px;
}
.cj-sidebar-section {
  font-size: 9px; text-transform: uppercase; letter-spacing: .1em;
  color: rgba(255,255,255,.20); padding: 8px 10px 5px;
}
.cj-nav-item {
  padding: 7px 10px; font-size: 11.5px;
  color: rgba(255,255,255,.30); border-radius: 7px;
  transition: background 0.25s ease, color 0.25s ease;
}
.cj-nav-item--active {
  background: color-mix(in srgb, var(--green) 7%, transparent);
  color: rgba(255,255,255,.85);
}
.cj-nav-item--done { color: rgba(255,255,255,.46); }
.cj-nav-item--done::after { content: ' \2713'; font-size: 9px; color: var(--green); }

/* ── Panel system ────────────────────────────────────────────────── */
.cj-main { flex: 1; position: relative; overflow: hidden; }
.cj-panel {
  position: absolute; inset: 0;
  padding: 22px 24px;
  opacity: 0;
  transform: translateX(14px);
  transition: opacity 0.38s ease, transform 0.38s ease;
  pointer-events: none;
  overflow-y: auto;
}
.cj-panel--active {
  opacity: 1; transform: translateX(0); pointer-events: auto;
}
.cj-panel--out {
  opacity: 0; transform: translateX(-14px);
}
.cj-p-head {
  font-size: 14px; font-weight: 700; letter-spacing: -.02em;
  color: rgba(255,255,255,.88); margin-bottom: 18px;
}

