}
.cj-think-step--active .cj-think-ico {
  background: rgba(251,191,36,.07); border: 1px solid rgba(251,191,36,.18);
}
.cj-think-spin {
  width: 10px; height: 10px; border-radius: 50%;
  border: 1.5px solid rgba(251,191,36,.28);
