}
@keyframes cjSpin { to { transform: rotate(360deg); } }

/* ── Strategy Panel ──────────────────────────────────────────────── */
.cj-strategy-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.cj-s-card {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 10px; padding: 13px 14px;
}
.cj-s-card--wide { grid-column: 1 / -1; }
.cj-s-card-lbl {
  font-size: 9px; text-transform: uppercase; letter-spacing: .1em;
  color: rgba(255,255,255,.26); margin-bottom: 7px;
}
.cj-s-card-val { font-size: 12px; color: rgba(255,255,255,.70); line-height: 1.55; }

/* ── Meta Ads Panel ──────────────────────────────────────────────── */
.cj-meta-layout { display: grid; grid-template-columns: 196px 1fr; gap: 16px; }
.cj-meta-ad-card {
  border: 1px solid rgba(255,255,255,.08); border-radius: 11px;
  overflow: hidden; background: rgba(255,255,255,.02);
}
.cj-meta-ad-hd { display: flex; align-items: center; gap: 7px; padding: 9px 10px; }
.cj-meta-av {
  width: 24px; height: 24px; border-radius: 50%; flex-shrink: 0;
  background: linear-gradient(135deg, var(--green) 0%, var(--green-text) 100%);
}
.cj-meta-brand { font-size: 10.5px; font-weight: 600; color: rgba(255,255,255,.78); }
.cj-meta-sp    { font-size: 9px; color: rgba(255,255,255,.28); }
.cj-meta-img {
  width: 100%; height: 98px;
  background: linear-gradient(150deg, #0a1628 0%, #172440 55%, #0d1c34 100%);
  display: flex; align-items: center; justify-content: center; padding: 0 12px;
}
.cj-meta-img-txt { font-size: 13.5px; font-weight: 700; color: rgba(255,255,255,.92); text-align: center; line-height: 1.4; }
.cj-meta-copy { padding: 9px 10px; }
.cj-meta-hl   { font-size: 10.5px; font-weight: 600; color: rgba(255,255,255,.80); line-height: 1.4; margin-bottom: 4px; }
.cj-meta-body { font-size: 9.5px; color: rgba(255,255,255,.36); line-height: 1.5; margin-bottom: 8px; }
.cj-meta-btn  {
  display: block; margin: 0 10px 10px;
  background: #1877F2; color: #fff;
  font-size: 10.5px; font-weight: 600;
  padding: 7px 0; border-radius: 7px; text-align: center;
}
/* Meta sidebar */
.cj-meta-sidebar { padding-top: 2px; }
.cj-meta-sb-lbl {
  font-size: 9px; text-transform: uppercase; letter-spacing: .1em;
  color: rgba(255,255,255,.24); margin-bottom: 10px;
}
.cj-meta-var {
  padding: 9px 11px; border-radius: 9px;
  border: 1px solid rgba(255,255,255,.06);
  margin-bottom: 7px; background: rgba(255,255,255,.02);
}
.cj-meta-var--on {
  background: color-mix(in srgb, var(--green) 5%, transparent); border-color: color-mix(in srgb, var(--green) 14%, transparent);
}
.cj-meta-var-name  { font-size: 11.5px; font-weight: 600; color: rgba(255,255,255,.75); margin-bottom: 2px; }
.cj-meta-var-angle { font-size: 10px; color: rgba(255,255,255,.34); }
.cj-meta-kpis { display: flex; gap: 14px; margin-top: 14px; padding-top: 12px; border-top: 1px solid rgba(255,255,255,.06); }
.cj-meta-kpi-v { font-size: 20px; font-weight: 700; letter-spacing: -.02em; color: rgba(255,255,255,.88); margin-bottom: 2px; }
.cj-meta-kpi-l { font-size: 9px; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.28); }

/* ── Landing Page Panel ──────────────────────────────────────────── */
.cj-lp-preview {
  border: 1px solid rgba(255,255,255,.07); border-radius: 11px;
  overflow: hidden; background: rgba(255,255,255,.015);
}
.cj-lp-topbar {
  display: flex; align-items: center;
  padding: 10px 16px;
  border-bottom: 1px solid rgba(255,255,255,.06);
  background: rgba(255,255,255,.02);
}
.cj-lp-brand   { font-size: 12px; font-weight: 700; letter-spacing: .04em; color: rgba(255,255,255,.82); }
.cj-lp-topbtn  {
  margin-left: auto; font-size: 10.5px; font-weight: 600;
  color: #000; background: var(--green); padding: 5px 12px; border-radius: 6px;
}
.cj-lp-hero    { padding: 26px 24px 20px; border-bottom: 1px solid rgba(255,255,255,.05); }
.cj-lp-h1 {
  font-size: 20px; font-weight: 700; letter-spacing: -.03em;
  color: rgba(255,255,255,.90); line-height: 1.2; margin-bottom: 10px;
}
.cj-lp-sub  { font-size: 12px; color: rgba(255,255,255,.46); line-height: 1.55; margin-bottom: 16px; }
.cj-lp-cta  {
  display: inline-block; font-size: 12px; font-weight: 600;
  color: #000; background: var(--green); padding: 9px 20px; border-radius: 8px;
}
.cj-lp-feats { display: flex; }
.cj-lp-feat  {
  flex: 1; padding: 12px 10px;
  font-size: 10.5px; font-weight: 600; color: rgba(255,255,255,.50);
  border-right: 1px solid rgba(255,255,255,.05); text-align: center;
}
.cj-lp-feat:last-child { border-right: none; }

/* ── Campaign Ready Panel ────────────────────────────────────────── */
.cj-dc-modules {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; margin-bottom: 18px;
}
.cj-dc-mod {
  background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.07);
  border-radius: 10px; padding: 11px 12px;
  display: flex; flex-direction: column; gap: 4px;
}
.cj-dc-mod--done {
  background: color-mix(in srgb, var(--green) 4%, transparent); border-color: color-mix(in srgb, var(--green) 12%, transparent);
}
.cj-dc-ico {
  font-size: 10px; width: 20px; height: 20px; border-radius: 50%;
  background: rgba(255,255,255,.05); color: rgba(255,255,255,.25);
  display: flex; align-items: center; justify-content: center; margin-bottom: 6px;
}
.cj-dc-mod--done .cj-dc-ico {
  background: color-mix(in srgb, var(--green) 12%, transparent); color: var(--green);
  border: 1px solid color-mix(in srgb, var(--green) 22%, transparent);
}
.cj-dc-name   { font-size: 11.5px; font-weight: 600; color: rgba(255,255,255,.76); }
.cj-dc-detail { font-size: 10px; color: rgba(255,255,255,.30); }
.cj-dc-publish {
  display: flex; align-items: center; padding: 14px 16px;
  background: color-mix(in srgb, var(--green) 5%, transparent); border: 1px solid color-mix(in srgb, var(--green) 14%, transparent); border-radius: 11px;
}
.cj-dc-publish-label { font-size: 13px; font-weight: 600; color: var(--green); }
.cj-dc-publish-btn {
  margin-left: auto; font-size: 12px; font-weight: 600; color: #000;
  background: linear-gradient(135deg, var(--green) 0%, var(--green-text) 100%);
  padding: 9px 20px; border-radius: 8px;
}

/* ── Brand Profile Panel ─────────────────────────────────────────── */
.cj-bp-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 14px; }
.cj-bp-field--wide { grid-column: 1 / -1; }
.cj-bp-lbl {
  font-size: 9px; text-transform: uppercase; letter-spacing: .1em;
  color: rgba(255,255,255,.24); margin-bottom: 6px;
}
.cj-bp-row { display: flex; align-items: center; gap: 8px; }
.cj-bp-inp {
  flex: 1; background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.08);
  border-radius: 8px; padding: 7px 11px; font-size: 11.5px;
  color: rgba(255,255,255,.16); line-height: 1.45;
  transition: color 0.42s ease, border-color 0.42s ease, background 0.42s ease;
}
.cj-bp-field--filled .cj-bp-inp {
  color: rgba(255,255,255,.78); border-color: color-mix(in srgb, var(--green) 14%, transparent);
  background: color-mix(in srgb, var(--green) 2%, transparent);
}
.cj-bp-ck {
  width: 20px; height: 20px; border-radius: 50%; flex-shrink: 0;
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.09);
  color: transparent; font-size: 9px;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.42s ease, border-color 0.42s ease, color 0.42s ease;
}
.cj-bp-field--filled .cj-bp-ck {
  background: color-mix(in srgb, var(--green) 12%, transparent); border-color: color-mix(in srgb, var(--green) 25%, transparent); color: var(--green);
}
.cj-bp-tags {
  flex: 1; display: flex; gap: 5px; align-items: center; flex-wrap: wrap;
  background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.08);
  border-radius: 8px; padding: 5px 11px; min-height: 34px;
  transition: border-color 0.42s ease;
}
.cj-bp-field--filled .cj-bp-tags { border-color: color-mix(in srgb, var(--green) 14%, transparent); }
.cj-bp-tag {
  font-size: 10px; padding: 3px 9px; border-radius: 20px;
  background: color-mix(in srgb, var(--green) 8%, transparent); border: 1px solid color-mix(in srgb, var(--green) 18%, transparent); color: var(--green);
  opacity: 0; transform: scale(0.80);
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.cj-bp-field--filled .cj-bp-tag { opacity: 1; transform: scale(1); }
.cj-bp-colors {
  flex: 1; display: flex; gap: 7px; align-items: center;
  background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.08);
  border-radius: 8px; padding: 6px 11px; min-height: 34px;
  transition: border-color 0.42s ease;
}
.cj-bp-field--filled .cj-bp-colors { border-color: color-mix(in srgb, var(--green) 14%, transparent); }
.cj-bp-color {
  width: 18px; height: 18px; border-radius: 50%; border: 1.5px solid rgba(255,255,255,.18);
  opacity: 0; transform: scale(0.60);
  transition: opacity 0.35s ease, transform 0.35s ease;
}
.cj-bp-field--filled .cj-bp-color { opacity: 1; transform: scale(1); }
.cj-bp-complete {
  display: flex; align-items: center; gap: 10px; padding: 12px 16px;
  border-radius: 10px; background: color-mix(in srgb, var(--green) 6%, transparent); border: 1px solid color-mix(in srgb, var(--green) 14%, transparent);
  font-size: 12px; font-weight: 600; color: rgba(255,255,255,.70);
  opacity: 0; transform: translateY(8px);
  transition: opacity 0.4s ease, transform 0.4s ease;
}
.cj-bp-complete--visible { opacity: 1; transform: translateY(0); }
.cj-bp-complete-ico { color: var(--green); font-size: 15px; }

/* ── Product Images Panel ─────────────────────────────────────────── */
.cj-images-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; }
.cj-img-card {
  border-radius: 10px; overflow: hidden;
  border: 1px solid rgba(255,255,255,.07); background: rgba(255,255,255,.02);
}
.cj-img-preview { height: 88px; width: 100%; }
.cj-img-preview--1 { background: linear-gradient(135deg,#0e1a30 0%,#1e2e50 55%,#0a1220 100%); }
.cj-img-preview--2 { background: linear-gradient(145deg,#0a1a20 0%,#1a3040 60%,#081418 100%); }
.cj-img-preview--3 { background: linear-gradient(135deg,#141e14 0%,#243a24 50%,#0e180e 100%); }
.cj-img-preview--4 { background: linear-gradient(135deg,#1e1408 0%,#3a2810 50%,#140e06 100%); }
.cj-img-preview--5 { background: linear-gradient(135deg,#0c0c1e 0%,#181830 50%,#080810 100%); }
.cj-img-preview--6 { background: linear-gradient(135deg,#1a0a18 0%,#2e1230 50%,#100810 100%); }
.cj-img-label { padding: 7px 10px; font-size: 10.5px; color: rgba(255,255,255,.44); }

/* ── Social Content Panel ─────────────────────────────────────────── */
.cj-social-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; }
.cj-social-card {
  border-radius: 10px; border: 1px solid rgba(255,255,255,.07);
  background: rgba(255,255,255,.02); padding: 12px;
}
.cj-social-card--ig { border-color: rgba(225,48,108,.14); }
.cj-social-card--li { border-color: rgba(10,102,194,.14); }
.cj-social-card--tt { border-color: rgba(255,0,80,.10); }
.cj-social-hd { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.cj-social-platform { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: rgba(255,255,255,.50); }
.cj-social-card--ig .cj-social-platform { color: #E1306C; }
.cj-social-card--li .cj-social-platform { color: #0A66C2; }
.cj-social-card--tt .cj-social-platform { color: #FF0050; }
.cj-social-status {
  font-size: 9px; padding: 2px 8px; border-radius: 20px;
  background: color-mix(in srgb, var(--green) 8%, transparent); border: 1px solid color-mix(in srgb, var(--green) 16%, transparent); color: var(--green);
}
.cj-social-img {
  height: 66px; border-radius: 7px; margin-bottom: 9px;
  background: linear-gradient(135deg,#0d1824 0%,#1e2e40 100%);
}
.cj-social-caption { font-size: 10.5px; color: rgba(255,255,255,.55); line-height: 1.55; margin-bottom: 7px; }
.cj-social-tags    { font-size: 10px; color: rgba(255,255,255,.28); }
.cj-social-title   { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.78); margin-bottom: 8px; line-height: 1.4; }
.cj-social-body    { font-size: 10.5px; color: rgba(255,255,255,.50); line-height: 1.55; }
.cj-social-script  { display: flex; flex-direction: column; gap: 8px; }
.cj-social-line    { font-size: 10.5px; color: rgba(255,255,255,.52); line-height: 1.5; }
.cj-social-ts      { color: color-mix(in srgb, var(--green) 68%, transparent); font-size: 9px; font-weight: 600; margin-right: 6px; }

/* ── Scroll-reveal system ────────────────────────────────────────── */
.cj-reveal-item {
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.38s ease, transform 0.38s ease;
}
.cj-reveal-item.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

/* ── Brand Profile: Logo field special ───────────────────────────── */
.cj-bp-logo-val { display: flex; align-items: center; gap: 8px; }
.cj-bp-logo-sq  {
  width: 22px; height: 22px; border-radius: 5px; flex-shrink: 0;
  background: linear-gradient(135deg,#4169E1 0%,#1e2a4a 100%);
  opacity: 0; transform: scale(0.7);
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.cj-bp-logo-nm  { font-size: 11px; color: rgba(255,255,255,.20); transition: color 0.4s ease; }
.cj-bp-field--filled .cj-bp-logo-sq { opacity: 1; transform: scale(1); }
.cj-bp-field--filled .cj-bp-logo-nm { color: rgba(255,255,255,.68); }

/* ── Thinking Panel ──────────────────────────────────────────────── */
.cj-think-wrap { display: flex; flex-direction: column; gap: 0; }
.cj-think-step {
  display: flex; align-items: center; gap: 12px;
  padding: 13px 16px;
  border-bottom: 1px solid rgba(255,255,255,.04);
  opacity: 0; transform: translateY(8px);
  transition: opacity 0.35s ease, transform 0.35s ease;
}
.cj-think-step.is-revealed { opacity: 1; transform: translateY(0); }
.cj-think-ico {
  width: 24px; height: 24px; border-radius: 50%; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 11px;
}
.cj-think-step--done .cj-think-ico  { background: color-mix(in srgb, var(--green) 10%, transparent); border: 1px solid color-mix(in srgb, var(--green) 22%, transparent); color: var(--green); }
.cj-think-step--spin .cj-think-ico  { background: rgba(251,191,36,.08); border: 1px solid rgba(251,191,36,.20); }
.cj-think-step--done .cj-think-txt  { color: rgba(255,255,255,.75); }
.cj-think-step--spin .cj-think-txt  { color: rgba(255,255,255,.50); }
.cj-think-txt { font-size: 12.5px; }
.cj-think-spin {
  width: 10px; height: 10px; border-radius: 50%;
  border: 1.5px solid rgba(251,191,36,.28); border-top-color: #FBBF24;
  animation: cjSpin 0.85s linear infinite;
}
@keyframes cjSpin { to { transform: rotate(360deg); } }

/* ── Strategy Panel: chart bars ──────────────────────────────────── */
.cj-s-card {
  padding: 13px; border-radius: 10px;
  border: 1px solid rgba(255,255,255,.07); background: rgba(255,255,255,.02);
}
.cj-s-card-hd   { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; }
.cj-s-card-lbl  { font-size: 9px; text-transform: uppercase; letter-spacing: .1em; color: rgba(255,255,255,.32); }
.cj-s-tag       { font-size: 9px; padding: 2px 7px; border-radius: 20px; background: color-mix(in srgb, var(--green) 8%, transparent); border: 1px solid color-mix(in srgb, var(--green) 16%, transparent); color: var(--green); }
.cj-s-card-val  { font-size: 11.5px; color: rgba(255,255,255,.68); line-height: 1.5; margin-bottom: 10px; }
.cj-s-bar-wrap  { display: flex; align-items: center; gap: 8px; }
.cj-s-bar-track { flex: 1; height: 3px; background: rgba(255,255,255,.06); border-radius: 2px; overflow: hidden; }
.cj-s-bar-fill  { height: 100%; background: linear-gradient(90deg,color-mix(in srgb, var(--green) 50%, transparent) 0%,var(--green) 100%); border-radius: 2px; }
.cj-s-bar-pct   { font-size: 9px; color: rgba(255,255,255,.30); flex-shrink: 0; width: 28px; text-align: right; }
.cj-s-card--wide { grid-column: 1 / -1; }

/* ── Meta Ads Panel ──────────────────────────────────────────────── */
.cj-meta-perf {
  display: flex; gap: 8px; margin-top: 12px;
  padding-top: 12px; border-top: 1px solid rgba(255,255,255,.05);
}
.cj-meta-perf-card {
  flex: 1; padding: 10px 12px; border-radius: 8px;
  background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.07);
}
.cj-meta-perf-lbl { font-size: 9px; text-transform: uppercase; letter-spacing: .08em; color: rgba(255,255,255,.28); margin-bottom: 4px; }
.cj-meta-perf-val { font-size: 16px; font-weight: 700; color: rgba(255,255,255,.82); }
.cj-meta-perf-sub { font-size: 9px; color: color-mix(in srgb, var(--green) 65%, transparent); margin-top: 2px; }

/* ── LP Builder Panel ────────────────────────────────────────────── */
.cj-lpb-wrap { display: flex; flex-direction: column; gap: 6px; }
.cj-lpb-block {
  border-radius: 8px; border: 1px solid rgba(255,255,255,.07);
  background: rgba(255,255,255,.02); overflow: hidden;
}
.cj-lpb-tag  {
  display: inline-block; font-size: 9px; text-transform: uppercase; letter-spacing: .08em;
  padding: 3px 8px; border-radius: 0 0 6px 0;
  background: color-mix(in srgb, var(--green) 8%, transparent); border-right: 1px solid color-mix(in srgb, var(--green) 14%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--green) 14%, transparent);
  color: color-mix(in srgb, var(--green) 70%, transparent); margin-bottom: 6px;
}
.cj-lpb-nav  { display: flex; gap: 16px; padding: 8px 14px; align-items: center; }
.cj-lpb-logo { font-size: 11px; font-weight: 700; color: rgba(255,255,255,.80); }
.cj-lpb-link { font-size: 10px; color: rgba(255,255,255,.35); }
.cj-lpb-navbtn { margin-left: auto; font-size: 10px; padding: 4px 12px; border-radius: 20px; background: color-mix(in srgb, var(--green) 12%, transparent); border: 1px solid color-mix(in srgb, var(--green) 22%, transparent); color: var(--green); }
.cj-lpb-hero { padding: 14px; }
.cj-lpb-h1   { font-size: 14px; font-weight: 700; color: rgba(255,255,255,.85); margin-bottom: 5px; line-height: 1.3; }
.cj-lpb-sub  { font-size: 10.5px; color: rgba(255,255,255,.45); margin-bottom: 10px; }
.cj-lpb-cta  { display: inline-block; font-size: 10px; padding: 5px 14px; border-radius: 20px; background: color-mix(in srgb, var(--green) 15%, transparent); border: 1px solid color-mix(in srgb, var(--green) 25%, transparent); color: var(--green); }
.cj-lpb-feats { display: flex; gap: 6px; padding: 10px 14px; }
.cj-lpb-feat  { font-size: 10px; padding: 4px 10px; border-radius: 20px; background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.08); color: rgba(255,255,255,.52); }
.cj-lpb-price { padding: 10px 14px; display: flex; gap: 8px; }
.cj-lpb-plan  { flex: 1; padding: 10px; border-radius: 8px; border: 1px solid rgba(255,255,255,.08); }
.cj-lpb-plan-n { font-size: 10px; font-weight: 600; color: rgba(255,255,255,.70); margin-bottom: 4px; }
.cj-lpb-plan-p { font-size: 14px; font-weight: 700; color: rgba(255,255,255,.85); }
.cj-lpb-plan--hl { border-color: color-mix(in srgb, var(--green) 20%, transparent); background: color-mix(in srgb, var(--green) 4%, transparent); }
.cj-lpb-footer { padding: 8px 14px; display: flex; justify-content: space-between; align-items: center; }
.cj-lpb-footer-l { font-size: 10px; font-weight: 600; color: rgba(255,255,255,.55); }
.cj-lpb-footer-links { display: flex; gap: 12px; }
.cj-lpb-footer-link  { font-size: 9.5px; color: rgba(255,255,255,.25); }

/* ── Email Campaign Panel ─────────────────────────────────────────── */
.cj-email-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.cj-email-seq-lbl { font-size: 9px; text-transform: uppercase; letter-spacing: .1em; color: rgba(255,255,255,.28); }
.cj-email-total   { font-size: 9px; padding: 2px 8px; border-radius: 20px; background: color-mix(in srgb, var(--green) 8%, transparent); border: 1px solid color-mix(in srgb, var(--green) 16%, transparent); color: var(--green); }
.cj-email-list { display: flex; flex-direction: column; gap: 7px; }
.cj-email-row {
  display: flex; align-items: center; gap: 12px; padding: 11px 14px;
  border-radius: 10px; background: rgba(255,255,255,.02); border: 1px solid rgba(255,255,255,.06);
  transition: border-color 0.3s ease;
}
.cj-email-row:hover { border-color: rgba(255,255,255,.12); }
.cj-email-day {
  min-width: 42px; text-align: center; font-size: 9px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .06em; color: rgba(255,255,255,.32);
  padding: 4px 0;
}
.cj-email-row--d1 .cj-email-day { color: var(--green); }
.cj-email-divider { width: 1px; height: 32px; background: rgba(255,255,255,.08); flex-shrink: 0; }
.cj-email-content { flex: 1; min-width: 0; }
.cj-email-subject  { font-size: 12px; font-weight: 500; color: rgba(255,255,255,.78); margin-bottom: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cj-email-preview  { font-size: 10.5px; color: rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cj-email-stat { flex-shrink: 0; text-align: right; }
.cj-email-stat-v { font-size: 14px; font-weight: 700; color: rgba(255,255,255,.78); line-height: 1; }
.cj-email-stat-l { font-size: 9px; color: rgba(255,255,255,.28); margin-top: 2px; }
.cj-email-badge {
  flex-shrink: 0; font-size: 9px; padding: 3px 9px; border-radius: 20px;
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.09);
  color: rgba(255,255,255,.40); white-space: nowrap;
}
.cj-email-badge--hl { background: color-mix(in srgb, var(--green) 8%, transparent); border-color: color-mix(in srgb, var(--green) 18%, transparent); color: var(--green); }

/* ── Dashboard: enhanced publish button ──────────────────────────── */
.cj-dc-publish {
  margin-top: 16px; padding: 16px 20px; border-radius: 12px;
  background: color-mix(in srgb, var(--green) 7%, transparent); border: 1px solid color-mix(in srgb, var(--green) 16%, transparent);
  display: flex; align-items: center; justify-content: space-between;
  opacity: 0; transform: translateY(8px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.cj-dc-publish.is-revealed { opacity: 1; transform: translateY(0); }

/* ── Mobile: static, stacked ─────────────────────────────────────── */
@media (max-width: 860px) {
  .cj-wrap { height: auto; }
  .cj-pin  { position: relative; height: auto; padding: 40px 12px 48px; }
  .cj-window {
    width: 100%; height: auto; border-radius: 12px;
    transform: none !important; opacity: 1 !important;
  }
  .cj-sidebar { display: none; }
  .cj-main { min-height: 400px; }
  .cj-panel { position: relative; opacity: 1 !important; transform: none !important; pointer-events: auto; }
  .cj-panel:not(.cj-panel--active) { display: none; }
  .cj-strategy-grid { grid-template-columns: 1fr; }
  .cj-meta-layout   { grid-template-columns: 1fr; }
  .cj-dc-modules    { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .cj-dc-modules { grid-template-columns: 1fr 1fr; }
  .cj-lp-feats   { flex-wrap: wrap; }
  .cj-lp-feat    { flex: 0 0 50%; border-bottom: 1px solid rgba(255,255,255,.05); }
}
/* ═══════════════════════════════════════════════════════════════════
   ORIVEN — CINEMATIC ZOOM EXPERIENCE
   ═══════════════════════════════════════════════════════════════════ */

/* ── Stage & pin ──────────────────────────────────────────────────── */
#zz-stage {
  position: relative;
  height: 900vh;
  background: #07070A;
}
#zz-pin {
  position: sticky;
  top: 0;
  height: 100vh;
  overflow: hidden;
  background: #07070A;
}

/* ── Hero text ────────────────────────────────────────────────────── */
#zz-hero {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding-top: 13vh;
  text-align: center;
  z-index: 10;
  pointer-events: none;
}
.zz-h1 {
  font-size: clamp(32px, 4.4vw, 68px);
  font-weight: 700;
  letter-spacing: -.03em;
  line-height: 1.1;
  color: #fff;
  margin: 0 0 24px;
}

/* ── Scroll indicator ─────────────────────────────────────────────── */
.zz-scroll-ind {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  pointer-events: none;
  animation: zz-float 2.4s ease-in-out infinite;
}
.zz-scroll-txt {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: rgba(255,255,255,.38);
}
.zz-scroll-arrow {
  width: 20px;
  height: 32px;
  border: 1.5px solid rgba(255,255,255,.22);
  border-radius: 10px;
  position: relative;
}
.zz-scroll-arrow::after {
  content: '';
  position: absolute;
  top: 5px;
  left: 50%;
  transform: translateX(-50%);
  width: 3px;
  height: 6px;
  background: rgba(255,255,255,.55);
  border-radius: 2px;
  animation: zz-scroll-dot 2.4s ease-in-out infinite;
}
@keyframes zz-float {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(5px); }
}
@keyframes zz-scroll-dot {
  0%, 100% { opacity: 1; transform: translateX(-50%) translateY(0); }
  70%       { opacity: 0; transform: translateX(-50%) translateY(8px); }
}

/* ── MacBook wrap (zoom host) ─────────────────────────────────────── */
#zz-mb-wrap {
  position: absolute;
  top: 64px; left: 0; right: 0; bottom: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transform: scale(0.46);
  transform-origin: center center;
  will-change: transform;
}

/* ── MacBook chassis ──────────────────────────────────────────────── */
#zz-mb {
  width: 860px;
  flex-shrink: 0;
  filter: drop-shadow(0 40px 80px rgba(0,0,0,.75)) drop-shadow(0 8px 24px rgba(0,0,0,.55));
}

/* Lid (display housing) */
#zz-lid {
  background: linear-gradient(160deg,
    #323234 0%,
    #252527 15%,
    #1e1e20 45%,
    #1c1c1e 70%,
    #222224 90%,
    #2a2a2c 100%
  );
  border-radius: 16px 16px 6px 6px;
  padding: 14px 14px 18px;
  position: relative;
  transform-origin: center bottom;
  will-change: transform;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.16),
    inset 0 0 0 1px rgba(255,255,255,.06),
    inset 0 -1px 0 rgba(0,0,0,.6);
}
/* Machined edge highlight on lid top */
#zz-lid::before {
  content: '';
  position: absolute;
  top: 0; left: 12px; right: 12px;
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,.28) 20%, rgba(255,255,255,.35) 50%, rgba(255,255,255,.28) 80%, transparent 100%);
  border-radius: 1px;
}
/* Camera housing / notch */
#zz-notch {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 120px;
  height: 11px;
  background: #0e0e10;
  border-radius: 0 0 10px 10px;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: inset 0 1px 3px rgba(0,0,0,.8);
}
#zz-cam {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #1a1a1c;
  border: 1px solid rgba(255,255,255,.07);
  position: relative;
}
#zz-cam::after {
  content: '';
  position: absolute;
  inset: 1.5px;
  border-radius: 50%;
  background: rgba(255,255,255,.04);
}
/* Screen bezel + display */
#zz-screen {
  background: #050508;
  border-radius: 6px;
  overflow: hidden;
  aspect-ratio: 16 / 10;
  position: relative;
  box-shadow:
    inset 0 0 0 1px rgba(0,0,0,.9),
    inset 0 1px 2px rgba(0,0,0,.6);
}
/* Subtle screen glare — no z-index so #mb-app paints on top */
#zz-screen::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 30%;
  background: linear-gradient(180deg, rgba(255,255,255,.012) 0%, transparent 100%);
  pointer-events: none;
}

/* Hinge strip */
#zz-hinge {
  height: 5px;
  background: linear-gradient(180deg, #0a0a0c 0%, #161618 50%, #1e1e20 100%);
  margin: 0 28px;
  box-shadow: 0 1px 4px rgba(0,0,0,.6);
}

/* Keyboard deck */
#zz-body {
  background: linear-gradient(175deg,
    #3a3a3c 0%,
    #323234 20%,
    #2c2c2e 60%,
    #282828 100%
  );
  border-radius: 0 0 13px 13px;
  padding: 12px 12px 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.08),
    0 2px 0 rgba(0,0,0,.7);
}
/* Keyboard */
#zz-kb {
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 100%;
}
.zz-kbr {
  display: flex;
  gap: 3px;
  justify-content: center;
  align-items: center;
}
.zzmk {
  height: 9px;
  width: 46px;
  background: linear-gradient(175deg, #3c3c3e 0%, #2c2c2e 100%);
  border-radius: 2.5px;
  border: 1px solid rgba(0,0,0,.55);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.06),
    0 1px 0 rgba(0,0,0,.4);
  flex-shrink: 0;
}
.zzmk-w   { width: 60px; }   /* Tab, \ */
.zzmk-xl  { width: 86px; }   /* Caps Lock, Return */
.zzmk-sh  { width: 110px; }  /* Shift (both) */
.zzmk-del { width: 72px; }   /* Delete */
.zzmk-cmd { width: 74px; }   /* Command */
.zzmk-sm  { width: 36px; }   /* fn, Ctrl, arrows */
.zzmk-sp  { width: 270px; }  /* Spacebar */
/* Trackpad */
#zz-tp {
  width: 220px;
  height: 90px;
  background: rgba(0,0,0,.18);
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 10px;
  box-shadow:
    inset 0 1px 3px rgba(0,0,0,.35),
    inset 0 0 0 1px rgba(0,0,0,.2);
}

/* ── MacBook app (inside screen) ──────────────────────────────────── */
#mb-app {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  background: #0A0A0D;
  overflow: hidden;
  font-family: 'Geist', system-ui, sans-serif;
}

/* Cinematic layout */
#mba-layout { display: none; }
#mba-content {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.mba-pg {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s ease;
}
.mba-pg.mba-pg-on {
  opacity: 1;
  pointer-events: all;
}

/* ── Cinematic Scenes ──────────────────────────────────────────────── */

/* Continue button — always at bottom center of scene */
.sc-next {
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  padding: 5px 16px 5px 14px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 20px;
  font-size: 8px;
  font-weight: 600;
  color: rgba(255,255,255,.55);
  letter-spacing: .06em;
  cursor: pointer;
  z-index: 20;
  white-space: nowrap;
  user-select: none;
  transition: background .2s, border-color .2s, color .2s;
}
.sc-next:hover {
  background: color-mix(in srgb, var(--green) 10%, transparent);
  border-color: color-mix(in srgb, var(--green) 30%, transparent);
  color: var(--green);
}

/* Shared scene utilities */
.sc-c {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  padding: 20px 22px;
  box-sizing: border-box;
  text-align: center;
}
.sc-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--green);
  opacity: .9;
  margin-bottom: 12px;
}
.sc-h1 {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -.03em;
  color: #fff;
  line-height: 1.12;
  margin: 0 0 10px;
}
.sc-h2 {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -.025em;
  color: #fff;
  line-height: 1.15;
  margin: 0;
}
.sc-sub {
  font-size: 9px;
  color: rgba(255,255,255,.5);
  line-height: 1.55;
  margin: 0;
}
.sc-sub-sm { font-size: 8.5px; margin-top: 10px; }
.sc-green-line {
  width: 40px;
  height: 2px;
  background: var(--green);
  border-radius: 2px;
  margin-top: 14px;
}
.sc-scene-top {
  padding: 14px 18px 8px;
  flex-shrink: 0;
}

/* S1: Title */
#sc-title {
  background: radial-gradient(ellipse at 60% 30%, rgba(65,105,225,.18) 0%, transparent 65%),
              radial-gradient(ellipse at 20% 80%, color-mix(in srgb, var(--green) 8%, transparent) 0%, transparent 50%);
}
#sc-title .sc-ew {
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 80%, transparent);
  margin-bottom: 14px;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity .5s ease, transform .5s ease;
}
#sc-title .sc-h1 {
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .5s ease .1s, transform .5s ease .1s;
}
#sc-title .sc-sub {
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .5s ease .2s, transform .5s ease .2s;
}
#sc-title .sc-green-line {
  opacity: 0;
  transform: scaleX(0);
  transition: opacity .4s ease .35s, transform .4s ease .35s;
}
#sc-title.sc-revealed .sc-ew,
#sc-title.sc-revealed .sc-h1,
#sc-title.sc-revealed .sc-sub { opacity: 1; transform: translateY(0); }
#sc-title.sc-revealed .sc-green-line { opacity: 1; transform: scaleX(1); }

/* S2: Problem */
#sc-problem {
  position: relative;
}
.sc-problem-top {
  position: absolute;
  top: 14px;
  left: 0; right: 0;
  text-align: center;
}
.sc-problem-top .sc-label { display: block; margin-bottom: 4px; }
.sc-problem-top .sc-h2 { font-size: 11px; }
.sc-tool {
  position: absolute;
  padding: 5px 9px;
  background: rgba(255,255,255,.055);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 6px;
  font-size: 9px;
  font-weight: 600;
  color: rgba(255,255,255,.55);
  opacity: 0;
  transition: opacity .4s ease, transform .4s ease;
}
#sc-problem.sc-revealed .sc-tool { opacity: 1; }

/* S3: Solution */
#sc-solution { background: radial-gradient(ellipse at 50% 50%, rgba(65,105,225,.12) 0%, transparent 70%); }
.sc-oriven-card {
  position: relative;
  width: 140px;
  height: 80px;
  background: rgba(255,255,255,.05);
  border: 1px solid color-mix(in srgb, var(--green) 25%, transparent);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 10px auto;
  overflow: hidden;
  opacity: 0;
  transform: scale(.9);
  transition: opacity .5s ease, transform .5s ease;
}
.sc-oc-glow {
  position: absolute;
  inset: -30px;
  background: radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--green) 15%, transparent) 0%, transparent 65%);
  pointer-events: none;
}
.sc-oc-logo {
  font-size: 14px;
  font-weight: 900;
  letter-spacing: .15em;
  color: var(--green);
  margin-bottom: 4px;
}
.sc-oc-tag {
  font-size: 7.5px;
  color: rgba(255,255,255,.42);
  letter-spacing: .04em;
}
#sc-solution.sc-revealed .sc-oriven-card { opacity: 1; transform: scale(1); }

/* S4: Flow */
#sc-flow { background: rgba(0,0,0,0); }
.sc-flow {
  display: flex;
  flex-direction: column;
  gap: 0;
  width: 100%;
  max-width: 170px;
}
.sc-fi {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 6px 10px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 6px;
  opacity: 0;
  transform: translateX(-8px);
  transition: opacity .35s ease, transform .35s ease;
}
.sc-fi-last { border-color: color-mix(in srgb, var(--green) 25%, transparent); background: color-mix(in srgb, var(--green) 5%, transparent); }
.sc-fn { font-size: 7px; font-weight: 800; color: color-mix(in srgb, var(--green) 70%, transparent); margin-bottom: 2px; }
.sc-ft { font-size: 9.5px; font-weight: 700; color: #fff; }
.sc-fd { font-size: 8px; color: rgba(255,255,255,.38); margin-top: 1px; }
.sc-fa { font-size: 9px; color: rgba(255,255,255,.2); text-align: center; padding: 2px 0; }
#sc-flow.sc-revealed .sc-fi { opacity: 1; transform: translateX(0); }
#sc-flow.sc-revealed .sc-fi:nth-child(1) { transition-delay: 0s; }
#sc-flow.sc-revealed .sc-fi:nth-child(3) { transition-delay: .07s; }
#sc-flow.sc-revealed .sc-fi:nth-child(5) { transition-delay: .14s; }
#sc-flow.sc-revealed .sc-fi:nth-child(7) { transition-delay: .21s; }
#sc-flow.sc-revealed .sc-fi:nth-child(9) { transition-delay: .28s; }

/* S5: Strategy */
.sc-strat-grid {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 0 14px 14px;
  flex: 1;
  overflow: hidden;
}
.sc-strat-card {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 10px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 7px;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .35s ease, transform .35s ease;
}
.sc-si { font-size: 11px; flex-shrink: 0; margin-top: 1px; }
.sc-strat-body { display: flex; flex-direction: column; gap: 2px; flex: 1; min-width: 0; }
.sc-st { font-size: 8.5px; font-weight: 700; color: #fff; }
.sc-sb { font-size: 7.5px; color: rgba(255,255,255,.42); line-height: 1.4; }
.sc-strat-bar { display: flex; align-items: center; gap: 5px; margin-top: 4px; flex-shrink: 0; }
.sc-strat-fill {
  height: 2px;
  width: 40px;
  background: rgba(255,255,255,.08);
  border-radius: 2px;
  position: relative;
}
.sc-strat-fill::after {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: var(--fw, 80%);
  background: var(--green);
  border-radius: 2px;
}
.sc-strat-bar span { font-size: 7px; font-weight: 700; color: color-mix(in srgb, var(--green) 80%, transparent); }
#sc-strategy.sc-revealed .sc-strat-card { opacity: 1; transform: translateY(0); }
#sc-strategy.sc-revealed .sc-strat-card:nth-child(1) { transition-delay: 0s; }
#sc-strategy.sc-revealed .sc-strat-card:nth-child(2) { transition-delay: .07s; }
#sc-strategy.sc-revealed .sc-strat-card:nth-child(3) { transition-delay: .14s; }
#sc-strategy.sc-revealed .sc-strat-card:nth-child(4) { transition-delay: .21s; }
#sc-strategy.sc-revealed .sc-strat-card:nth-child(5) { transition-delay: .28s; }

/* S6: Creation */
.sc-create-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 0 14px 14px;
  flex: 1;
}
.sc-create-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 10px 8px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 8px;
  opacity: 0;
  transform: translateY(8px) scale(.97);
  transition: opacity .35s ease, transform .35s ease;
}
.sc-cc-status {
  font-size: 10px;
  color: var(--cc, #4169E1);
  font-weight: 800;
  line-height: 1;
  margin-bottom: 4px;
}
.sc-cc-t { font-size: 9.5px; font-weight: 700; color: #fff; }
.sc-cc-s { font-size: 7.5px; color: rgba(255,255,255,.38); margin-top: 1px; }
#sc-create.sc-revealed .sc-create-card { opacity: 1; transform: translateY(0) scale(1); }
#sc-create.sc-revealed .sc-create-card:nth-child(1) { transition-delay: 0s; }
#sc-create.sc-revealed .sc-create-card:nth-child(2) { transition-delay: .06s; }
#sc-create.sc-revealed .sc-create-card:nth-child(3) { transition-delay: .12s; }
#sc-create.sc-revealed .sc-create-card:nth-child(4) { transition-delay: .18s; }
#sc-create.sc-revealed .sc-create-card:nth-child(5) { transition-delay: .24s; }
#sc-create.sc-revealed .sc-create-card:nth-child(6) { transition-delay: .30s; }

/* S7: Consistency */
.sc-cw {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 12px 0 8px;
}
.sc-cl, .sc-cr {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.sc-cb {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 8.5px;
  color: rgba(255,255,255,.65);
}
.sc-cbd {
  width: 7px;
  height: 7px;
