.sc-qt { font-size: 8.5px; color: rgba(255,255,255,.68); line-height: 1.5; margin-bottom: 5px; }
.sc-qn { font-size: 7.5px; color: rgba(255,255,255,.35); }
#sc-reviews.sc-revealed .sc-quote { opacity: 1; transform: translateX(0); }
#sc-reviews.sc-revealed .sc-quote:nth-child(1) { transition-delay: 0s; }
#sc-reviews.sc-revealed .sc-quote:nth-child(2) { transition-delay: .1s; }
#sc-reviews.sc-revealed .sc-quote:nth-child(3) { transition-delay: .2s; }

/* S10: Pricing */
.sc-pg {
