}
.sc-pc-n { font-size: 8.5px; font-weight: 600; color: rgba(255,255,255,.55); margin-bottom: 5px; }
.sc-pc-p { font-size: 20px; font-weight: 900; color: #fff; letter-spacing: -.04em; line-height: 1; margin-bottom: 4px; }
.sc-pc-p span { font-size: 9px; font-weight: 500; color: rgba(255,255,255,.35); }
.sc-pc-d { font-size: 7.5px; color: rgba(255,255,255,.32); }
#sc-pricing.sc-revealed .sc-price-card { opacity: 1; transform: translateY(0) !important; }
#sc-pricing.sc-revealed .sc-price-card:nth-child(1) { transition-delay: 0s; }
#sc-pricing.sc-revealed .sc-price-card:nth-child(2) { transition-delay: .1s; }
#sc-pricing.sc-revealed .sc-price-card:nth-child(3) { transition-delay: .2s; }

/* S11: FAQ */
.sc-faq-wrap {
  flex: 1;
  overflow-y: auto;
  padding: 0 16px 14px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.08) transparent;
}

/* S12: Final */
#sc-final {
  background: radial-gradient(ellipse at 50% 40%, color-mix(in srgb, var(--green) 12%, transparent) 0%, transparent 65%);
