  font-weight: 600;
  border-radius: 30px;
  text-decoration: none;
  cursor: pointer;
}
#sc-final.sc-revealed .sc-final-logo { opacity: 1; }
#sc-final.sc-revealed .sc-fh2 { opacity: 1; transform: translateY(0); }
#sc-final.sc-revealed .sc-fbtns { opacity: 1; transform: translateY(0); }

/* Additional scene utility classes */
.sc-stat {
  margin-top: 10px;
  font-size: 7.5px;
