}

/* ── Ambient floating elements around laptop ──────────────────────── */
#zz-ambient {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  overflow: visible;
}

/* Crystal shards */
.zz-shard {
  position: absolute;
  width: 14px;
  height: 22px;
  background: linear-gradient(140deg, color-mix(in srgb, var(--green) 35%, transparent) 0%, rgba(65,105,225,.25) 100%);
  clip-path: polygon(50% 0%, 92% 38%, 70% 100%, 30% 100%, 8% 38%);
  animation: zz-shard-float var(--ss,6s) ease-in-out infinite;
  animation-delay: var(--sd, 0s);
  opacity: 0.55;
  filter: blur(0.3px);
}
@keyframes zz-shard-float {
  0%,100% { transform: translateY(0) rotate(-2deg); }
  50%      { transform: translateY(-14px) rotate(6deg); }
}

/* Holographic side panels */
.zz-holo-panel {
  position: absolute;
  width: 80px;
  height: 52px;
  background: linear-gradient(135deg, rgba(65,105,225,.07) 0%, color-mix(in srgb, var(--green) 5%, transparent) 100%);
  border: 1px solid color-mix(in srgb, var(--green) 10%, transparent);
  border-radius: 5px;
  animation: zz-holo-float var(--hs,8s) ease-in-out infinite;
  animation-delay: var(--hd, 0s);
  overflow: hidden;
}
.zz-holo-panel::before {
  content: '';
  position: absolute;
  left: 0; right: 0;
  height: 1px;
  background: color-mix(in srgb, var(--green) 18%, transparent);
  animation: zz-scan 3.5s linear infinite;
}
.zz-holo-panel::after {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, transparent 0px, transparent 4px, color-mix(in srgb, var(--green) 4%, transparent) 4px, color-mix(in srgb, var(--green) 4%, transparent) 5px);
}
@keyframes zz-holo-float {
  0%,100% { transform: translateY(0) rotate(-0.5deg); opacity: 0.6; }
  50%      { transform: translateY(-10px) rotate(0.5deg); opacity: 0.85; }
}
@keyframes zz-scan {
  0%   { top: -1px; }
  100% { top: 100%; }
}

/* Particle dots */
.zz-dot {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--green) 75%, transparent);
  box-shadow: 0 0 5px color-mix(in srgb, var(--green) 50%, transparent), 0 0 10px color-mix(in srgb, var(--green) 20%, transparent);
  animation: zz-dot-pulse 4s ease-in-out infinite;
  animation-delay: var(--dd, 0s);
}
@keyframes zz-dot-pulse {
  0%,100% { transform: scale(1);   opacity: 0.55; }
  50%      { transform: scale(1.8); opacity: 1; }
}

/* Glow orbs */
.zz-orb {
  position: absolute;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(65,105,225,.1) 0%, transparent 70%);
  animation: zz-orb-breathe var(--os,10s) ease-in-out infinite;
  animation-delay: var(--od, 0s);
}
@keyframes zz-orb-breathe {
  0%,100% { transform: scale(1);   opacity: 0.7; }
  50%      { transform: scale(1.25); opacity: 1; }
}

/* ── FAQ ───────────────────────────────────────────────────────────── */
.mba-faq-list { display: flex; flex-direction: column; }
.mba-faq-item { border-bottom: 1px solid rgba(255,255,255,.055); }
.mba-faq-q {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 2px;
  font-size: 10px;
  font-weight: 500;
  color: rgba(255,255,255,.72);
  cursor: pointer;
  gap: 8px;
  user-select: none;
}
.mba-faq-q:hover { color: #fff; }
.mba-faq-ico {
  width: 16px; height: 16px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 50%;
}
.mba-faq-ico svg {
  width: 8px;
  height: 8px;
  stroke: rgba(255,255,255,.45);
  stroke-width: 1.5;
  fill: none;
  transition: transform .3s;
}
.mba-faq-open .mba-faq-ico svg { transform: rotate(45deg); stroke: var(--green); }
.mba-faq-a {
  font-size: 9.5px;
  color: rgba(255,255,255,.5);
  line-height: 1.55;
  max-height: 0;
  overflow: hidden;
  transition: max-height .3s ease, padding .3s;
  padding: 0 2px;
}
.mba-faq-open .mba-faq-a { max-height: 120px; padding: 0 2px 9px; }

/* ── Contact ───────────────────────────────────────────────────────── */
.mba-cta-blk { margin-bottom: 20px; }
.mba-cta-h2 { font-size: 16px; font-weight: 700; letter-spacing: -.02em; color: #fff; margin: 0 0 8px; }
.mba-cta-sub { font-size: 10px; color: rgba(255,255,255,.45); line-height: 1.55; margin-bottom: 12px; }
.mba-cta-btns { display: flex; gap: 7px; flex-wrap: wrap; }
.mba-cta-p, .mba-cta-g {
