}
.mba-cta-p { background: var(--green); color: #0a0a0a; }
.mba-cta-g { border: 1px solid rgba(255,255,255,.16); color: rgba(255,255,255,.65); }
.mba-ftr { border-top: 1px solid rgba(255,255,255,.06); padding-top: 16px; }
.mba-ftr-grid { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 16px; margin-bottom: 16px; }
.mba-ftr-logo { font-size: 9px; font-weight: 800; letter-spacing: .1em; color: rgba(255,255,255,.42); margin-bottom: 4px; }
.mba-ftr-tag { font-size: 9px; color: rgba(255,255,255,.28); line-height: 1.5; }
.mba-ftr-hd { font-size: 8px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.25); margin-bottom: 5px; }
.mba-ftr-lnk { display: block; font-size: 9px; color: rgba(255,255,255,.38); text-decoration: none; margin-bottom: 4px; }
.mba-ftr-bar { font-size: 8.5px; color: rgba(255,255,255,.2); border-top: 1px solid rgba(255,255,255,.05); padding-top: 10px; }

/* ── MacBook pointer-events: enabled after zoom ──────────────────── */
#zz-mb-wrap.zz-ready { pointer-events: auto; }
#zz-mb-wrap { pointer-events: none; }

/* ══════════════════════════════════════════════════════════════════
   MOBILE
   ══════════════════════════════════════════════════════════════════ */
@media (max-width: 768px) {
  #zz-stage { height: auto; min-height: 100vh; }
  #zz-pin { position: relative; height: auto; }
  #zz-hero { position: relative; padding: 16vh 20px 20px; height: auto; z-index: 10; }
