}

/* ── Virtual cursor ────────────────────────────────────────────────── */
#zz-cursor {
  position: absolute;
  z-index: 999;
  pointer-events: none;
  opacity: 0;
  left: 50%;
  top: 50%;
  transform: translate(-1px, -1px);
  transition: opacity .5s ease,
              left .72s cubic-bezier(.22,.68,0,1.1),
              top  .72s cubic-bezier(.22,.68,0,1.1);
  line-height: 0;
}
#zz-cursor.zz-cursor-vis { opacity: 1; }
#zz-cursor svg { width: 13px; height: 19px; display: block; }
.zz-cr {
  position: absolute;
  top: -5px; left: -5px;
  width: 22px; height: 22px;
  border: 1.5px solid rgba(255,255,255,.7);
  border-radius: 50%;
  transform: scale(0);
  opacity: 0;
}
.zz-cr.zz-cr-anim { animation: zz-click-ring .55s cubic-bezier(.22,.68,0,1) forwards; }
@keyframes zz-click-ring {
  0%   { transform: scale(0);   opacity: .85; }
  60%  { transform: scale(1.8); opacity: .4; }
  100% { transform: scale(2.8); opacity: 0; }
}

/* ── MacBook ambient scene ─────────────────────────────────────────── */
#zz-mb-wrap::before {
  content: '';
  position: absolute;
  inset: 5% 5%;
  background: radial-gradient(ellipse at 50% 40%, rgba(90,90,200,.07) 0%, transparent 70%);
  pointer-events: none;
  z-index: -1;
}
/* Desk/surface reflection below the laptop */
#zz-mb-wrap::after {
  content: '';
  position: absolute;
  bottom: -12px;
  left: 8%; right: 8%;
  height: 28px;
  background: radial-gradient(ellipse, rgba(255,255,255,.055) 0%, transparent 80%);
  filter: blur(6px);
  pointer-events: none;
}

/* ── Final Hero (post-close CTA) ──────────────────────────────────── */
#zz-final-hero {
  position: absolute;
  bottom: 10%;
  left: 0; right: 0;
  text-align: center;
  z-index: 8;
  pointer-events: none;
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 1.1s ease, transform 1.1s ease;
}
#zz-final-hero.zz-fh-vis {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}
.zz-fh-inner { padding: 0 24px; }
.zz-fh-kicker {
