}
.ov-gen-spark {
  color: var(--green);
  font-size: .75em;
  flex-shrink: 0;
  opacity: .8;
}
.ov-gen-text { flex: 1; text-align: left; }
.ov-gen-cursor {
  width: 2px;
  height: 1.05em;
  background: var(--green);
  flex-shrink: 0;
  border-radius: 1px;
  animation: ov-blink 1s step-end infinite;
}
@keyframes ov-blink {
  0%,100%{ opacity:1; }
  50%{ opacity:0; }
}
.ov-gen-hint {
  font-size: 13px;
  color: rgba(255,255,255,.22);
