  grid-template-columns: repeat(3,1fr);
  gap: 14px;
  width: 100%;
}
.ov-fa {
  padding: 22px 20px;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 16px;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .4s ease, transform .4s ease, border-color .4s;
}
.ov-fa.ov-vis {
  opacity: 1;
  transform: translateY(0);
  border-color: color-mix(in srgb, var(--green) 14%, transparent);
}
.ov-fa-icon { font-size:22px; color:color-mix(in srgb, var(--green) 55%, transparent); margin-bottom:10px; line-height:1; }
.ov-fa-name { font-size:14px; font-weight:700; color:#fff; margin-bottom:5px; letter-spacing:-.01em; }
.ov-fa-detail { font-size:11px; color:rgba(255,255,255,.32); line-height:1.5; }
.ov-full-caption {
  font-size: 16px;
  color: rgba(255,255,255,.4);
  opacity: 0;
  transition: opacity .6s ease;
  text-align: center;
  letter-spacing: -.01em;
}
.ov-full-caption.ov-vis { opacity: 1; }

/* ── Hero ──────────────────────────────────────────────────────────── */
#ov-hero {
  position: relative;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: #07070A;
}
#ov-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
#ov-hero-content {
  position: relative;
  z-index: 2;
  padding: 0 24px;
  max-width: 880px;
}
.ov-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 24px;
}
.ov-h1 {
  font-size: clamp(38px, 5.8vw, 80px);
  font-weight: 800;
  letter-spacing: -.04em;
  line-height: 1.04;
  color: #fff;
  margin: 0 0 24px;
}
.ov-hero-sub {
  font-size: clamp(15px, 1.4vw, 19px);
  color: rgba(255,255,255,.48);
  line-height: 1.65;
  margin: 0 0 44px;
}
.ov-hero-desc {
  font-size: clamp(15px, 1.3vw, 17px);
  color: rgba(255,255,255,.46);
  line-height: 1.7;
  max-width: 520px;
  margin: 0 auto 36px;
}
.ov-hero-btns {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}
.ov-btn-primary {
  display: inline-flex;
  align-items: center;
  padding: 15px 32px;
  background: var(--green);
  color: #0a0a0a;
  font-size: 15px;
  font-weight: 700;
  border-radius: 50px;
  text-decoration: none;
  letter-spacing: -.01em;
  transition: transform .15s ease, box-shadow .15s ease;
  cursor: pointer;
}
.ov-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 10px 30px color-mix(in srgb, var(--green) 30%, transparent); }
.ov-btn-ghost {
  display: inline-flex;
  align-items: center;
  padding: 15px 32px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  color: rgba(255,255,255,.65);
  font-size: 15px;
  font-weight: 600;
  border-radius: 50px;
  text-decoration: none;
  transition: background .15s, border-color .15s;
  cursor: pointer;
}
.ov-btn-ghost:hover { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.22); }
.ov-scroll-cue {
  position: absolute;
  bottom: 36px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: rgba(255,255,255,.28);
  font-size: 10px;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.ov-scroll-bar {
  width: 1px;
  height: 48px;
  background: linear-gradient(to bottom, rgba(255,255,255,.3), transparent);
  animation: ov-sb-pulse 2.2s ease-in-out infinite;
}
@keyframes ov-sb-pulse {
  0%,100%{ transform:scaleY(1); opacity:.4; }
  50%{ transform:scaleY(1.2); opacity:1; }
}

/* ── Chapter scaffold ──────────────────────────────────────────────── */
#lp-stage { background: #07070A; }
.ov-ch {
  position: relative;
  height: 200vh;
}
#ch-2, #ch-3, #ch-7 { height: 220vh; }
.ov-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 72px 24px 24px;
  background: #07070A;
}
.ov-ch-label {
  position: absolute;
  top: 28px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: rgba(255,255,255,.28);
  white-space: nowrap;
}
.ov-ch-n { color: var(--green); opacity: .7; }

/* ── Ch 1: The Idea ────────────────────────────────────────────────── */
.ov-idea-scene {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  flex: 1;
}
.ov-idea-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--green) 8%, transparent);
  animation: ov-ring-pulse 4s ease-in-out infinite;
}
.ov-ir-1 { width: 320px; height: 320px; }
.ov-ir-2 { width: 500px; height: 500px; animation-delay: -2s; border-color: color-mix(in srgb, var(--green) 4%, transparent); }
@keyframes ov-ring-pulse {
  0%,100%{ transform:scale(1); opacity:1; }
  50%{ transform:scale(1.04); opacity:.5; }
}
.ov-idea-card {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 40px 56px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 24px;
  backdrop-filter: blur(16px);
  text-align: center;
  opacity: 0;
  transform: translateY(24px) scale(.96);
  transition: opacity .7s ease, transform .7s ease;
}
.ov-idea-card.ov-vis { opacity: 1; transform: translateY(0) scale(1); }
.ov-idea-spark { font-size: 28px; color: var(--green); line-height: 1; }
.ov-idea-title {
  font-size: clamp(20px, 2.8vw, 36px);
  font-weight: 700;
  letter-spacing: -.03em;
  color: #fff;
  line-height: 1.2;
}
.ov-idea-sub { font-size: 13px; color: rgba(255,255,255,.4); letter-spacing: .04em; text-transform: uppercase; }
.ov-idea-caption {
  padding-bottom: 20px;
  font-size: 15px;
  color: rgba(255,255,255,.35);
  opacity: 0;
  transition: opacity .6s ease .4s;
}
.ov-idea-caption.ov-vis { opacity: 1; }

/* ── Ch 2: Strategy ────────────────────────────────────────────────── */
.ov-strat-scene {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  width: 100%;
  max-width: 820px;
}
.ov-strat-nucleus {
  padding: 14px 28px;
  background: color-mix(in srgb, var(--green) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius: 40px;
  font-size: 14px;
  font-weight: 600;
  color: var(--green);
  opacity: 0;
  transform: scale(.9);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-strat-nucleus.ov-vis { opacity: 1; transform: scale(1); }
.ov-strat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  width: 100%;
  max-width: 660px;
}
.ov-sc {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 16px;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px;
  text-align: center;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .4s ease, transform .4s ease;
}
.ov-sc.ov-vis { opacity: 1; transform: translateY(0); }
.ov-sc-icon { font-size: 20px; color: color-mix(in srgb, var(--green) 60%, transparent); line-height: 1; }
.ov-sc span { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.65); letter-spacing: .02em; }

/* ── Ch 3: Blueprint ────────────────────────────────────────────────── */
.ov-bp-scene {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  max-width: 360px;
}
.ov-bp-step {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  opacity: 0;
  transform: translateX(-16px);
  transition: opacity .4s ease, transform .4s ease;
}
.ov-bp-step.ov-vis { opacity: 1; transform: translateX(0); }
.ov-bp-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,.2);
  border: 2px solid rgba(255,255,255,.12);
  flex-shrink: 0;
  margin-left: 3px;
}
.ov-bp-dot-live { background: var(--green); border-color: var(--green); box-shadow: 0 0 12px color-mix(in srgb, var(--green) 50%, transparent); }
.ov-bp-txt { font-size: 16px; font-weight: 600; color: rgba(255,255,255,.55); padding: 12px 0; }
.ov-bp-step.ov-vis .ov-bp-txt { color: rgba(255,255,255,.88); }
.ov-bp-line {
  width: 1px;
  height: 0;
  background: linear-gradient(to bottom, rgba(255,255,255,.12), color-mix(in srgb, var(--green) 20%, transparent));
  margin-left: 8px;
  transition: height .3s ease;
}
.ov-bp-line.ov-vis { height: 24px; }

/* ── Ch 4: Ads ──────────────────────────────────────────────────────── */
.ov-ads-scene {
  display: grid;
  grid-template-columns: 1fr 1fr 130px 130px;
  gap: 12px;
  width: 100%;
  max-width: 800px;
  align-items: start;
}
.ov-ad {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 14px;
  overflow: hidden;
  opacity: 0;
  transform: translateY(20px);
  transition: opacity .4s ease, transform .4s ease;
}
.ov-ad.ov-vis { opacity: 1; transform: translateY(0); }
.ov-ad-platform {
  padding: 8px 12px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.35);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.ov-ad-visual {
  height: 160px;
  display: flex;
  align-items: flex-end;
  padding: 12px;
  position: relative;
  overflow: hidden;
}
.ov-av-ig { background: linear-gradient(145deg,#2D1B4E,#1A0E2E); }
.ov-av-ig::after,.ov-av-fb::after { content:''; position:absolute; inset:0; background:linear-gradient(to top,rgba(0,0,0,.5),transparent 60%); }
.ov-av-fb { background: linear-gradient(145deg,#0D2137,#091825); }
.ov-av-disp { background: linear-gradient(145deg,#0A1A0A,#051005); height:100px; }
.ov-av-vid { background: #0A0A0D; height:100px; flex-direction:column; justify-content:center; align-items:center; gap:8px; padding:0; }
.ov-av-caption { position:relative; z-index:1; font-size:15px; font-weight:800; color:#fff; line-height:1.2; letter-spacing:-.02em; }
.ov-av-disp .ov-av-caption { position:static; font-size:12px; padding:10px; }
.ov-ad-footer { display:flex; align-items:center; justify-content:space-between; padding:10px 12px; }
.ov-ad-brand { font-size:11px; font-weight:700; color:rgba(255,255,255,.5); }
.ov-ad-cta-pill { font-size:9px; font-weight:700; padding:4px 10px; background:var(--green); color:#0a0a0a; border-radius:20px; }
.ov-vid-play { font-size:20px; color:rgba(255,255,255,.6); }
.ov-vid-bar { width:80%; height:2px; background:rgba(255,255,255,.1); border-radius:1px; }
.ov-vid-fill { width:35%; height:100%; background:var(--green); border-radius:1px; }

/* ── Ch 5: Landing Page Preview ─────────────────────────────────────── */
.ov-lp-scene { width:100%; max-width:600px; }
.ov-lp-browser {
  background: #111114;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 12px;
  overflow: hidden;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-lp-browser.ov-vis { opacity:1; transform:translateY(0); }
.ov-lp-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  background: #0D0D10;
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.ov-lp-dots { display:flex; gap:5px; }
.ov-lp-dots i { width:8px; height:8px; border-radius:50%; background:rgba(255,255,255,.15); font-style:normal; }
.ov-lp-url { font-size:11px; color:rgba(255,255,255,.3); flex:1; text-align:center; padding:3px 12px; background:rgba(255,255,255,.04); border-radius:6px; }
.ov-lp-sec { padding:24px; border-bottom:1px solid rgba(255,255,255,.06); opacity:0; transition:opacity .4s ease; }
.ov-lp-sec.ov-vis { opacity:1; }
.ov-lps-hero { background:linear-gradient(135deg,#0D1A2E,#070710); }
.ov-lps-h1 { font-size:20px; font-weight:800; color:#fff; letter-spacing:-.03em; margin-bottom:6px; }
.ov-lps-sub { font-size:12px; color:rgba(255,255,255,.45); margin-bottom:14px; }
.ov-lps-btn { display:inline-block; padding:8px 18px; background:var(--green); color:#0a0a0a; font-size:11px; font-weight:700; border-radius:20px; }
.ov-lps-benefits { display:flex; gap:12px; flex-wrap:wrap; }
.ov-lps-bitem { font-size:11px; color:rgba(255,255,255,.55); }
.ov-lps-social { text-align:center; }
.ov-lps-stars { color:var(--green); font-size:14px; letter-spacing:2px; margin-bottom:4px; }
.ov-lps-rev { font-size:11px; color:rgba(255,255,255,.4); }

/* ── Ch 6: Content System ───────────────────────────────────────────── */
.ov-content-scene {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 10px;
  width: 100%;
  max-width: 780px;
}
.ov-ct {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 12px;
  padding: 16px;
  opacity: 0;
  transform: translateY(12px);
  transition: opacity .35s ease, transform .35s ease;
  min-height: 100px;
}
.ov-ct.ov-vis { opacity:1; transform:translateY(0); }
.ov-ct-tag { display:inline-block; font-size:9px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:var(--green); background:color-mix(in srgb, var(--green) 10%, transparent); border-radius:4px; padding:2px 7px; margin-bottom:8px; }
.ov-ct-title { font-size:12px; font-weight:600; color:rgba(255,255,255,.7); line-height:1.4; margin-bottom:10px; }
.ov-ct-lines span { display:block; height:2px; background:rgba(255,255,255,.08); border-radius:1px; margin-bottom:5px; }
.ov-ct-lines span:nth-child(1){ width:90%; }
.ov-ct-lines span:nth-child(2){ width:75%; }
.ov-ct-lines span:nth-child(3){ width:55%; }
.ov-ct-img { height:54px; background:linear-gradient(135deg,#1A0E2E,#0D1A2E); border-radius:8px; margin-bottom:8px; }
.ov-ct-caption,.ov-ct-dur { font-size:11px; color:rgba(255,255,255,.4); margin-top:4px; }
.ov-ct-tweet { font-size:11px; color:rgba(255,255,255,.55); line-height:1.5; font-style:italic; margin-top:6px; }

/* ── Ch 7: Brand System ─────────────────────────────────────────────── */
.ov-brand-scene {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 32px;
  width: 100%;
  max-width: 600px;
}
.ov-bs-top {
  display: flex;
  gap: 40px;
  align-items: center;
  justify-content: center;
  width: 100%;
  flex-wrap: wrap;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-bs-top.ov-vis { opacity:1; transform:translateY(0); }
.ov-bs-palette { display:flex; gap:8px; }
.ov-bs-swatch { width:40px; height:40px; border-radius:10px; }
.ov-bsv-label { font-size:10px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:rgba(255,255,255,.3); margin-bottom:8px; }
.ov-bsv-tags { display:flex; gap:6px; flex-wrap:wrap; }
.ov-bsv-tags span { padding:4px 10px; background:rgba(255,255,255,.06); border:1px solid rgba(255,255,255,.1); border-radius:20px; font-size:11px; color:rgba(255,255,255,.6); }
.ov-bs-assets {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
  opacity: 0;
  transform: translateY(12px);
  transition: opacity .5s ease .15s, transform .5s ease .15s;
}
.ov-bs-assets.ov-vis { opacity:1; transform:translateY(0); }
.ov-bsa {
  padding: 10px 20px;
  background: rgba(255,255,255,.04);
  border: 1px solid color-mix(in srgb, var(--green) 15%, transparent);
  border-radius: 10px;
  font-size: 12px;
  font-weight: 600;
  color: rgba(255,255,255,.6);
  position: relative;
}
.ov-bsa::before { content:''; position:absolute; top:0; left:0; right:0; height:1px; background:linear-gradient(90deg,transparent,color-mix(in srgb, var(--green) 30%, transparent),transparent); }
.ov-bs-caption { font-size:14px; color:rgba(255,255,255,.35); text-align:center; opacity:0; transition:opacity .5s ease .3s; }
.ov-bs-caption.ov-vis { opacity:1; }

/* ── Ch 8: Launch ───────────────────────────────────────────────────── */
.ov-launch-scene {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 400px;
  height: 400px;
}
.ov-lr {
  position: absolute;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--green) 12%, transparent);
  opacity: 0;
  transform: scale(.6);
  transition: opacity .6s ease, transform .8s ease;
}
.ov-lr-1 { width:160px; height:160px; }
.ov-lr-2 { width:280px; height:280px; transition-delay:.1s; }
.ov-lr-3 { width:400px; height:400px; transition-delay:.2s; }
.ov-lr.ov-vis { opacity:1; transform:scale(1); }
.ov-launch-core {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  opacity: 0;
  transform: scale(.8);
  transition: opacity .5s ease .3s, transform .5s ease .3s;
}
.ov-launch-core.ov-vis { opacity:1; transform:scale(1); }
.ov-lc-arrow { font-size:32px; color:var(--green); line-height:1; animation:ov-lc-float 2.5s ease-in-out infinite; }
@keyframes ov-lc-float { 0%,100%{ transform:translateY(0); } 50%{ transform:translateY(-8px); } }
.ov-lc-txt { font-size:13px; font-weight:700; color:rgba(255,255,255,.6); letter-spacing:.08em; text-transform:uppercase; }

/* ── Ch 9: Results ──────────────────────────────────────────────────── */
.ov-results-scene {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 40px;
  width: 100%;
  max-width: 800px;
  text-align: center;
}
.ov-result { opacity:0; transform:translateY(20px); transition:opacity .5s ease, transform .5s ease; }
.ov-result.ov-vis { opacity:1; transform:translateY(0); }
.ov-res-num { font-size:clamp(48px,6vw,80px); font-weight:800; color:var(--green); letter-spacing:-.04em; line-height:1; margin-bottom:12px; font-variant-numeric:tabular-nums; }
.ov-res-label { font-size:13px; color:rgba(255,255,255,.4); letter-spacing:.02em; line-height:1.4; }

/* ── Ch 10: Testimonials ────────────────────────────────────────────── */
.ov-reviews-scene {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 16px;
  width: 100%;
  max-width: 900px;
}
.ov-rev {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px;
  padding: 28px 24px;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .4s ease, transform .4s ease;
}
.ov-rev.ov-vis { opacity:1; transform:translateY(0); }
.ov-rev-stars { color:var(--green); letter-spacing:2px; font-size:12px; margin-bottom:16px; }
.ov-rev-q { margin:0 0 20px; font-size:14px; line-height:1.65; color:rgba(255,255,255,.7); font-style:normal; letter-spacing:-.01em; }
.ov-rev-author { font-size:11px; color:rgba(255,255,255,.3); font-weight:600; letter-spacing:.04em; }

/* ── Ch 11: Pricing ─────────────────────────────────────────────────── */
.ov-pricing-scene {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 16px;
  width: 100%;
  max-width: 860px;
  align-items: start;
}
.ov-pc {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 20px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  text-align: left;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .4s ease, transform .4s ease, border-color .2s, box-shadow .2s;
}
.ov-pc.ov-vis { opacity:1; transform:translateY(0); }
.ov-pc.ov-vis:hover { border-color: rgba(255,255,255,.18); box-shadow: 0 8px 40px rgba(0,0,0,.3); }
.ov-pc-pro { background:color-mix(in srgb, var(--green) 4%, transparent); border-color:color-mix(in srgb, var(--green) 20%, transparent); }
.ov-pc-pro.ov-vis:hover { border-color: color-mix(in srgb, var(--green) 38%, transparent); box-shadow: 0 0 60px color-mix(in srgb, var(--green) 7%, transparent), 0 8px 40px rgba(0,0,0,.3); }
/* Fixed-height header: badge (optional) + tier name — keeps price at same Y */
.ov-pc-head { height: 60px; display: flex; flex-direction: column; justify-content: flex-end; margin-bottom: 16px; }
.ov-pc-badge { display: inline-block; font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; padding: 3px 10px; background: color-mix(in srgb, var(--green) 15%, transparent); color: var(--green); border-radius: 20px; margin-bottom: 8px; width: fit-content; }
.ov-pc-tier { font-size: 13px; font-weight: 700; color: rgba(255,255,255,.5); letter-spacing: .06em; text-transform: uppercase; }
.ov-pc-pro .ov-pc-tier { color: color-mix(in srgb, var(--green) 70%, transparent); }
/* Fixed-height price block: price + credits line — keeps desc + list + btn at same Y */
.ov-pc-price-block { height: 80px; display: flex; flex-direction: column; justify-content: flex-start; margin-bottom: 14px; padding-bottom: 14px; border-bottom: 1px solid rgba(255,255,255,.07); }
.ov-pc-price { font-size: 40px; font-weight: 800; color: #fff; letter-spacing: -.04em; line-height: 1; }
.ov-pc-price span { font-size: 14px; font-weight: 500; color: rgba(255,255,255,.35); margin-left: 2px; }
/* Count-up wrapper around the number itself — restore the big-number look
   the plain ".ov-pc-price span" rule above would otherwise shrink it to. */
.ov-pc-price .ov-pc-price-num { font-size: inherit; font-weight: inherit; color: inherit; letter-spacing: inherit; }
.ov-pc-price-cs { font-size: 26px; letter-spacing: -.02em; line-height: 1.2; }
.ov-pc-credits { font-size: 11px; color: rgba(255,255,255,.28); margin-top: 6px; }
.ov-pc-desc { font-size: 12px; color: rgba(255,255,255,.4); line-height: 1.6; margin-bottom: 18px; }
.ov-pc-list { list-style: none; padding: 0; margin: 0 0 24px; flex: 1; }
.ov-pc-list li { font-size: 12px; color: rgba(255,255,255,.55); padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.04); display: flex; align-items: center; gap: 8px; }
.ov-pc-list li::before { content: '✓'; color: var(--green); font-weight: 700; font-size: 11px; flex-shrink: 0; }
.ov-pc-btn { display: block; width: 100%; padding: 12px; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.12); border-radius: 10px; font-size: 13px; font-weight: 600; color: rgba(255,255,255,.7); text-align: center; text-decoration: none; cursor: pointer; transition: background .15s; box-sizing: border-box; }
.ov-pc-btn:hover { background: rgba(255,255,255,.12); }
.ov-pc-btn-pro { background: var(--green); border-color: var(--green); color: #0a0a0a; }
.ov-pc-btn-pro:hover { background: var(--gm); }
.ov-pc-btn-agency { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.15); }
.ov-pc-btn-agency:hover { background: rgba(255,255,255,.1); }

/* ── Ch 12: FAQ ─────────────────────────────────────────────────────── */
.ov-faq-scene { width:100%; max-width:640px; display:flex; flex-direction:column; }
.ov-faq { border-bottom:1px solid rgba(255,255,255,.07); opacity:0; transition:opacity .35s ease; }
.ov-faq.ov-vis { opacity:1; }
.ov-faq-q {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 18px 0;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  gap: 16px;
  color: rgba(255,255,255,.75);
  font-size: 14px;
  font-weight: 500;
