}
.ov-faq-q:hover { color:#fff; }
.ov-faq-ic { font-size:20px; font-weight:300; color:rgba(255,255,255,.3); flex-shrink:0; transition:transform .25s ease, color .15s; line-height:1; }
.ov-faq.ov-faq-open .ov-faq-ic { transform:rotate(45deg); color:var(--green); }
.ov-faq-a { font-size:13px; color:rgba(255,255,255,.45); line-height:1.7; max-height:0; overflow:hidden; transition:max-height .35s ease, padding .35s ease; }
