.ov-final-h2 { font-size:clamp(32px,5vw,68px); font-weight:800; letter-spacing:-.04em; color:#fff; line-height:1.05; margin:0 0 16px; }
.ov-final-sub { font-size:15px; color:rgba(255,255,255,.38); margin:0 0 40px; }
.ov-final-btns { display:flex; gap:12px; justify-content:center; flex-wrap:wrap; margin-bottom:32px; }
