/* ── Section 03 Campaign Showcase ────────────────────────────────────── */
#ov-showcase {
  background: #07070A;
  padding: 100px 48px 120px;
}
.ov-showcase-inner {
  max-width: 1100px;
  margin: 0 auto;
  text-align: center;
}
.ov-showcase-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  width: 100%;
  max-width: 1060px;
  margin: 0 auto;
  height: auto;
}
.ov-so {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 18px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow: hidden;
  min-height: 280px;
