.ov-showcase-grid .ov-so:nth-child(4) { transform: translate(22px, -22px); }
.ov-showcase-grid.ov-vis .ov-so { opacity: 1; transform: none; }
.ov-showcase-grid.ov-vis .ov-so:hover { border-color: color-mix(in srgb, var(--green) 15%, transparent); box-shadow: 0 0 40px color-mix(in srgb, var(--green) 4%, transparent), 0 12px 32px rgba(0,0,0,.22); }
.ov-showcase-grid.ov-vis .ov-so:nth-child(1) { transition-delay: 0s; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(2) { transition-delay: .1s; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(3) { transition-delay: .2s; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(4) { transition-delay: .3s; }
.ov-so-tag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
