}
.ov-so-ad-sub { font-size: 10px; color: rgba(255,255,255,.4); }
.ov-so-footer { display:flex; align-items:center; justify-content:space-between; flex-shrink:0; }
.ov-so-cta-pill { font-size: 11px; font-weight: 700; color: var(--green); }
