/* ── Section 01 Brand Identity ─────────────────────────────────────── */
#ov-brand-identity {
  background: #07070A;
  padding: 100px 48px;
  min-height: 80vh;
  display: flex;
  align-items: center;
}
.ov-bi-inner {
  width: 100%;
  max-width: 1040px;
  margin: 0 auto;
  text-align: center;
}
.ov-bi-card { text-align: left; }
.ov-bi-heading, .ov-cs-heading {
  font-size: clamp(26px, 3.5vw, 46px);
  font-weight: 800;
  color: #fff;
  letter-spacing: -.04em;
  line-height: 1.06;
  margin: 0 0 32px;
}
.ov-bi-card {
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 18px;
  overflow: hidden;
  background: rgba(255,255,255,.02);
  max-width: 700px;
  margin: 0 auto;
  width: 100%;
}
.ov-bi-card .ov-bi-row {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity .45s ease, transform .45s ease;
}
/* Staggered reveal when card gets ov-vis */
.ov-bi-card.ov-vis .ov-bi-row { opacity: 1; transform: translateY(0); }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(1) { transition-delay: 0s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(2) { transition-delay: .07s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(3) { transition-delay: .14s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(4) { transition-delay: .21s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(5) { transition-delay: .28s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(6) { transition-delay: .35s; }
.ov-bi-row {
  display: flex;
  align-items: center;
  padding: 16px 24px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.ov-bi-row:last-child { border-bottom: none; }
.ov-bi-key {
  font-size: 11px;
  font-weight: 600;
  color: rgba(255,255,255,.28);
  letter-spacing: .06em;
  text-transform: uppercase;
  width: 150px;
  flex-shrink: 0;
}
.ov-bi-val {
  font-size: 15px;
  font-weight: 500;
  color: rgba(255,255,255,.8);
  letter-spacing: -.01em;
}
.ov-bi-colors { display: flex; gap: 8px; align-items: center; }
.ov-bi-swatch {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.15);
}

/* ── Section 02 Campaign Setup ─────────────────────────────────────── */
/* ── Section 02 Campaign Setup ─────────────────────────────────────── */
#ov-campaign-setup {
  background: #07070A;
  padding: 100px 48px;
  min-height: 75vh;
  display: flex;
  align-items: center;
}
.ov-cs-inner {
  width: 100%;
  max-width: 1040px;
  margin: 0 auto;
  text-align: center;
}
.ov-cs-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}
.ov-cs-type {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 12px 20px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 10px;
  background: rgba(255,255,255,.02);
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,.5);
  letter-spacing: -.01em;
  opacity: 0;
  transition: opacity .38s ease, transform .38s ease;
}
/* Directional — chips enter from alternating sides */
.ov-cs-grid .ov-cs-type:nth-child(odd)  { transform: translateX(-28px); }
.ov-cs-grid .ov-cs-type:nth-child(even) { transform: translateX(28px); }
.ov-cs-grid .ov-cs-type:last-child      { transform: translateY(16px); }
.ov-cs-grid.ov-vis .ov-cs-type { opacity: 1; transform: none; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(1) { transition-delay: 0s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(2) { transition-delay: .06s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(3) { transition-delay: .12s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(4) { transition-delay: .18s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(5) { transition-delay: .24s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(6) { transition-delay: .30s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(7) { transition-delay: .36s; }
.ov-cs-active {
  background: color-mix(in srgb, var(--green) 6%, transparent);
  border-color: color-mix(in srgb, var(--green) 28%, transparent);
  color: #fff;
}
.ov-cs-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255,255,255,.2);
  flex-shrink: 0;
}
.ov-cs-active .ov-cs-dot { background: var(--green); }

/* ── Section 04 Results ────────────────────────────────────────────── */
#ov-results .ov-section-label { margin-bottom: 10px; }
#ov-results .ov-section-h { margin-bottom: 60px; text-align: center; }

/* ── Section 05 Reviews — 3-card paginated ─────────────────────── */
.ov-reviews-section {
  background: #07070A;
  padding: 100px 48px 80px;
}
.ov-reviews-inner {
  max-width: 1400px; /* Redesign: was 1200px */
  margin: 0 auto;
  text-align: center;
}
/* Stage: clips animation overflow */
.ov-rev-stage {
  overflow: hidden;
  margin-bottom: 36px;
}
/* Row: 3-column grid, transitions for page animation */
.ov-rev-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  transition: transform .38s cubic-bezier(.4,0,.2,1), opacity .32s ease;
}
.ov-rev-row.ov-row-exit-left  { transform: translateX(-32px); opacity: 0; }
.ov-rev-row.ov-row-exit-right { transform: translateX(32px);  opacity: 0; }
.ov-rev-row.ov-row-enter-right { transform: translateX(32px);  opacity: 0; transition: none; }
.ov-rev-row.ov-row-enter-left  { transform: translateX(-32px); opacity: 0; transition: none; }
/* Cards: always visible, equal height via flex */
.ov-rev-card {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 20px;
  padding: 32px 28px 28px;
  display: flex;
  flex-direction: column;
  text-align: left;
  transition: border-color .2s, box-shadow .2s;
}
.ov-rev-card:hover { border-color: rgba(255,255,255,.16); box-shadow: 0 4px 28px rgba(0,0,0,.3); }
.ov-rev-stars { color: var(--green); letter-spacing: 2px; font-size: 13px; margin-bottom: 18px; flex-shrink: 0; }
.ov-rev-q { font-size: 14px; color: rgba(255,255,255,.62); line-height: 1.7; font-style: italic; margin: 0; flex: 1; letter-spacing: -.01em; padding-bottom: 20px; }
.ov-rev-author { font-size: 11px; color: rgba(255,255,255,.28); font-weight: 600; letter-spacing: .05em; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.06); flex-shrink: 0; }
/* Navigation */
.ov-rev-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
}
.ov-rev-nav-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  color: rgba(255,255,255,.55);
  font-size: 18px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .15s, border-color .15s, color .15s;
  line-height: 1;
}
.ov-rev-nav-btn:hover:not(:disabled) {
  background: rgba(255,255,255,.12);
  border-color: rgba(255,255,255,.22);
  color: #fff;
}
.ov-rev-nav-btn:disabled { opacity: .25; cursor: default; }
/* Dot indicators */
.ov-rev-nav-dots {
  display: flex;
  align-items: center;
  gap: 7px;
}
.ov-rev-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(255,255,255,.18);
  transition: background .2s, transform .2s;
  display: inline-block;
}
.ov-rev-dot.ov-dot-active {
  background: var(--green);
  transform: scale(1.4);
}

/* ── Section 06 Pricing (4 plans) ─────────────────────────────────── */
.ov-pricing-grid-4 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  align-items: stretch;
  margin-bottom: 24px;
}

/* ── Final CTA updates ─────────────────────────────────────────────── */
#ov-final .ov-section-label { margin-bottom: 14px; }

/* ── Section 01 extended stagger (8 rows) ──────────────────────────── */
.ov-bi-card.ov-vis .ov-bi-row:nth-child(7) { transition-delay: .42s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(8) { transition-delay: .49s; }

/* ── Section 02 extended stagger (10 chips) ────────────────────────── */
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(8)  { transition-delay: .42s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(9)  { transition-delay: .48s; }
.ov-cs-grid.ov-vis .ov-cs-type:nth-child(10) { transition-delay: .54s; }

/* ── Section 03 Showcase — 8-card animation (alternating left/right) ─ */
.ov-showcase-grid .ov-so:nth-child(odd)  { transform: translateX(-22px); }
.ov-showcase-grid .ov-so:nth-child(even) { transform: translateX(22px); }
/* Override the corner-converge rules set earlier */
.ov-showcase-grid .ov-so:nth-child(1) { transform: translateX(-22px); }
.ov-showcase-grid .ov-so:nth-child(2) { transform: translateX(22px); }
.ov-showcase-grid .ov-so:nth-child(3) { transform: translateX(-22px); }
.ov-showcase-grid .ov-so:nth-child(4) { transform: translateX(22px); }
.ov-showcase-grid.ov-vis .ov-so:nth-child(5) { transition-delay: .28s; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(6) { transition-delay: .35s; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(7) { transition-delay: .42s; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(8) { transition-delay: .49s; }

/* ── Facebook Ad card ───────────────────────────────────────────────── */
.ov-so-fb { flex: 1; display: flex; flex-direction: column; gap: 8px; min-height: 0; }
.ov-so-fb-badge { font-size: 8px; letter-spacing: .06em; color: rgba(255,255,255,.25); margin-bottom: 2px; }
.ov-so-fb-img {
  flex: 1;
  min-height: 80px;
  background: linear-gradient(135deg, #0d1a2e 0%, #1a2e1a 50%, #0d0d0d 100%);
  border-radius: 10px;
}
.ov-so-fb-body { padding: 4px 0 0; }
.ov-so-fb-h { font-size: clamp(13px, 1.3vw, 17px); font-weight: 800; color: #fff; letter-spacing: -.02em; line-height: 1.2; margin-bottom: 3px; }
.ov-so-fb-url { font-size: 9px; color: rgba(255,255,255,.22); }

/* ── Landing page trust line ────────────────────────────────────────── */
.ov-so-lp-trust { font-size: 9px; color: color-mix(in srgb, var(--green) 40%, transparent); margin-top: 4px; }

/* ── Email from line ────────────────────────────────────────────────── */
.ov-so-em-from { font-size: 9px; color: rgba(255,255,255,.2); margin-bottom: 6px; }

/* ── Video Concept card ─────────────────────────────────────────────── */
.ov-so-video { flex: 1; display: flex; flex-direction: column; justify-content: space-between; min-height: 0; }
.ov-so-scene { padding: 8px 0; }
.ov-so-scene-n {
  font-size: 8px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 50%, transparent); margin-bottom: 4px;
}
.ov-so-scene-d { font-size: 11px; color: rgba(255,255,255,.35); margin-bottom: 3px; }
.ov-so-scene-l { font-size: 12px; font-style: italic; color: rgba(255,255,255,.65); font-weight: 500; }
.ov-so-scene-div { height: 1px; background: rgba(255,255,255,.06); }

/* ── Creative Brief card ────────────────────────────────────────────── */
.ov-so-brief { flex: 1; display: flex; flex-direction: column; }
.ov-so-brief-row {
  display: flex; flex-direction: column; gap: 3px;
  padding: 9px 0; border-bottom: 1px solid rgba(255,255,255,.05);
}
.ov-so-brief-row:last-child { border-bottom: none; }
.ov-so-brief-k { font-size: 8px; text-transform: uppercase; letter-spacing: .1em; color: rgba(255,255,255,.22); }
.ov-so-brief-v { font-size: 12px; color: rgba(255,255,255,.7); font-weight: 500; letter-spacing: -.01em; }

/* ── Marketing Strategy card ────────────────────────────────────────── */
.ov-so-strategy { flex: 1; display: flex; flex-direction: column; gap: 12px; }
.ov-so-strat-phase { }
.ov-so-strat-n {
  font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 55%, transparent); margin-bottom: 6px;
}
.ov-so-strat-item { font-size: 11px; color: rgba(255,255,255,.45); padding: 2px 0; }

/* ── Audience Analysis card ─────────────────────────────────────────── */
.ov-so-audience { flex: 1; display: flex; flex-direction: column; gap: 10px; justify-content: space-between; }
.ov-so-seg { }
.ov-so-seg-label { font-size: 8px; text-transform: uppercase; letter-spacing: .12em; color: rgba(255,255,255,.2); margin-bottom: 4px; }
.ov-so-seg-name { font-size: 13px; font-weight: 700; color: #fff; letter-spacing: -.02em; margin-bottom: 6px; }
.ov-so-seg-data { font-size: 10px; color: rgba(255,255,255,.38); padding: 1px 0; }
.ov-so-seg-div { height: 1px; background: rgba(255,255,255,.06); }

/* ── Reviews Carousel ───────────────────────────────────────────────── */
.ov-car-wrap { position: relative; }
.ov-carousel {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  cursor: grab;
  user-select: none;
  padding: 4px 2px 8px;
  scroll-behavior: smooth;
}
.ov-carousel::-webkit-scrollbar { display: none; }
.ov-carousel.is-dragging { cursor: grabbing; scroll-behavior: auto; }

/* Carousel cards: always visible (not IO'd individually) */
.ov-carousel .ov-rev-card {
  flex: 0 0 320px;
  opacity: 1;
  transform: none;
  cursor: default;
}
.ov-carousel .ov-rev-card:hover { border-color: rgba(255,255,255,.16); box-shadow: 0 4px 24px rgba(0,0,0,.25); }
/* Carousel fade-in via parent data-observe */
.ov-car-wrap { opacity: 0; transform: translateY(16px); transition: opacity .5s ease, transform .5s ease; }
.ov-car-wrap.ov-vis { opacity: 1; transform: none; }

.ov-car-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 20px;
}
.ov-car-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  color: rgba(255,255,255,.55);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background .15s, color .15s, border-color .15s;
}
.ov-car-btn:hover {
  background: rgba(255,255,255,.12);
  color: #fff;
  border-color: rgba(255,255,255,.2);
}

/* ── Responsive ─────────────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .ov-pricing-grid-4 { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 900px) {
  .ov-stats-row { flex-direction: column; gap: 40px; }
  .ov-stat-div { width: 80px; height: 1px; }
  .ov-stat { padding: 0 20px; }
  .ov-reviews-grid { grid-template-columns: 1fr 1fr; }
