  .ov-pricing-section, .ov-faq-section { padding: 70px 20px; }
  .ov-reviews-section { padding: 60px 20px 50px; }
  .ov-rev-row { grid-template-columns: 1fr; }
  #ov-results { padding: 70px 20px; min-height: 0; }
  .ov-pricing-grid-4 { grid-template-columns: 1fr; }
  .ov-reviews-grid { grid-template-columns: 1fr; }
  .ov-bi-key { width: 110px; font-size: 10px; }
}

/* ===== AI MODELS MARQUEE STRIP ===== */
.ov-ai-strip {
  background: #07070A;
  border-bottom: 1px solid rgba(255,255,255,.06);
  height: 46px;
  display: flex;
  align-items: center;
  overflow: hidden;
  position: relative;
  flex-shrink: 0;
}
.ov-ai-strip::before,
.ov-ai-strip::after {
  content: '';
  position: absolute;
  top: 0;
  width: 100px;
  height: 100%;
  z-index: 2;
  pointer-events: none;
}
.ov-ai-strip::before { left: 0; background: linear-gradient(to right, #07070A 60%, transparent); }
.ov-ai-strip::after  { right: 0; background: linear-gradient(to left,  #07070A 60%, transparent); }
.ov-ai-overflow {
  flex: 1;
  overflow: hidden;
  mask-image: linear-gradient(to right, transparent 0%, #000 8%, #000 92%, transparent 100%);
  -webkit-mask-image: linear-gradient(to right, transparent 0%, #000 8%, #000 92%, transparent 100%);
}
.ov-ai-track {
  display: flex;
  align-items: center;
  animation: ovAiScroll 38s linear infinite;
  will-change: transform;
  width: max-content;
}
.ov-ai-track:hover { animation-play-state: paused; }
.ov-ai-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 26px;
  font-size: 10px;
  font-weight: 700;
  color: rgba(255,255,255,.2);
  letter-spacing: .09em;
  text-transform: uppercase;
  white-space: nowrap;
  transition: color .2s;
}
.ov-ai-item:hover { color: rgba(255,255,255,.5); }
.ov-ai-pip {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--green) 30%, transparent);
  flex-shrink: 0;
}
.ov-ai-sep {
  color: rgba(255,255,255,.07);
  font-size: 18px;
  line-height: 1;
  flex-shrink: 0;
}
@keyframes ovAiScroll {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
/* ===== INSTAGRAM AD ENHANCEMENTS ===== */
.ov-so-ig-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
.ov-so-ig-pic {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--green) 0%, #00d4aa 100%);
  flex-shrink: 0;
  border: 1.5px solid rgba(255,255,255,.15);
}
.ov-so-ig-meta { display: flex; flex-direction: column; }
.ov-so-ig-name { font-size: 11px; font-weight: 700; color: rgba(255,255,255,.75); line-height: 1.2; }
.ov-so-ig-sp   { font-size: 9px; color: rgba(255,255,255,.28); }
/* ===== LANDING PAGE CARD ENHANCEMENTS ===== */
.ov-so-lp { flex: 1; display: flex; flex-direction: column; gap: 0; min-height: 0; }
.ov-so-lp-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,.06);
  margin-bottom: 8px;
}
.ov-so-lp-logo { font-size: 9px; font-weight: 800; letter-spacing: .1em; color: rgba(255,255,255,.75); }
.ov-so-lp-nav-links { display: flex; gap: 10px; }
.ov-so-lp-nav-links span { font-size: 7px; color: rgba(255,255,255,.22); letter-spacing: .04em; }
.ov-so-lp-hero {
  flex: 1;
  background: linear-gradient(155deg, #1a0a2e 0%, #0d1a1a 55%, #050a0a 100%);
  border-radius: 10px;
  padding: 14px 14px 12px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 5px;
  min-height: 90px;
  margin-bottom: 8px;
}
/* ===== EMAIL CARD ENHANCEMENTS ===== */
.ov-so-em-hero {
  height: 44px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--green) 7%, transparent) 0%, rgba(0,200,180,.05) 100%);
  border-radius: 6px;
  margin-bottom: 8px;
  border: 1px solid color-mix(in srgb, var(--green) 7%, transparent);
}

/* ===== SECTION SUBHEADING ===== */
.ov-section-sub {
  font-size: clamp(13px, 1.3vw, 16px);
  color: rgba(255,255,255,.35);
  line-height: 1.6;
  margin: -16px 0 40px;
  max-width: 520px;
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

/* ===== SHOWCASE CARD MICRO-ANIMATIONS ===== */

/* Email card: lines draw from left on reveal */
.ov-so-em-line {
  transform-origin: left center;
  transform: scaleX(0);
}
.ov-showcase-grid.ov-vis .ov-so-em-line {
  transform: scaleX(1);
  transition: transform .55s cubic-bezier(.4,0,.2,1);
}
/* nth-child relative to .ov-so-email container */
.ov-showcase-grid.ov-vis .ov-so-em-line:nth-child(4) { transition-delay: .75s; }
.ov-showcase-grid.ov-vis .ov-so-em-line:nth-child(5) { transition-delay: .90s; }
.ov-showcase-grid.ov-vis .ov-so-em-line:nth-child(6) { transition-delay: 1.05s; }
.ov-showcase-grid.ov-vis .ov-so-em-line:nth-child(7) { transition-delay: 1.20s; }

/* Instagram Ad card: profile pic + name build in after card appears */
.ov-so-ig-pic { opacity: 0; transform: scale(0.5); }
.ov-so-ig-name { opacity: 0; }
.ov-so-ig-sp { opacity: 0; }
.ov-so-ad-h { opacity: 0; transform: translateY(6px); }
.ov-showcase-grid.ov-vis .ov-so:nth-child(1) .ov-so-ig-pic {
  animation: ovPicIn .35s cubic-bezier(.34,1.56,.64,1) .54s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(1) .ov-so-ig-name {
  animation: ovFadeInQ .3s ease .68s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(1) .ov-so-ig-sp {
  animation: ovFadeInQ .3s ease .74s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(1) .ov-so-ad-h {
  animation: ovSlideUpIn .4s ease .78s both;
}

/* Landing Page card: nav → headline → sub → btn sequential reveal */
.ov-so-lp-logo { opacity: 0; }
.ov-so-lp-nav-links { opacity: 0; }
.ov-so-lp-h { opacity: 0; transform: translateY(8px); }
.ov-so-lp-sub { opacity: 0; }
.ov-so-lp-btn { opacity: 0; }
.ov-so-lp-trust { opacity: 0; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(3) .ov-so-lp-logo {
  animation: ovFadeInQ .3s ease .72s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(3) .ov-so-lp-nav-links {
  animation: ovFadeInQ .3s ease .80s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(3) .ov-so-lp-h {
  animation: ovSlideUpIn .4s ease .90s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(3) .ov-so-lp-sub {
  animation: ovFadeInQ .35s ease 1.06s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(3) .ov-so-lp-btn {
  animation: ovFadeInQ .35s ease 1.20s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(3) .ov-so-lp-trust {
  animation: ovFadeInQ .3s ease 1.34s both;
}

/* Email card header fades in before lines draw */
.ov-so-em-from { opacity: 0; }
.ov-so-em-subject { opacity: 0; }
.ov-so-em-hero { opacity: 0; transform: scaleY(0); transform-origin: top; }
.ov-so-em-btn { opacity: 0; }
.ov-showcase-grid.ov-vis .ov-so:nth-child(4) .ov-so-em-from {
  animation: ovFadeInQ .3s ease .62s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(4) .ov-so-em-subject {
  animation: ovFadeInQ .3s ease .72s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(4) .ov-so-em-hero {
  animation: ovGrowDown .45s cubic-bezier(.4,0,.2,1) .80s both;
}
.ov-showcase-grid.ov-vis .ov-so:nth-child(4) .ov-so-em-btn {
  animation: ovFadeInQ .3s ease 1.35s both;
}

/* Shared keyframes */
@keyframes ovPicIn {
  from { opacity: 0; transform: scale(0.5); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes ovFadeInQ {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes ovSlideUpIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes ovGrowDown {
  from { opacity: 0; transform: scaleY(0); }
  to   { opacity: 1; transform: scaleY(1); }
}

/* ===== PRICING — remove old duplicate desc border rule ===== */
/* Price block now owns the divider, not ov-pc-desc */

/* ===== REVIEWS SCROLL HINT ===== */
.ov-rev-scroll-hint {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: rgba(255,255,255,.18);
  margin-bottom: 20px;
  display: block;
}

/* ===== SECTION 01 — BRAND BLUEPRINT HEADER ===== */
.ov-bi-doc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px 14px;
  border-bottom: 1px solid rgba(255,255,255,.07);
  background: color-mix(in srgb, var(--green) 3%, transparent);
}
.ov-bi-doc-title {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ov-bi-doc-spark {
  color: var(--green);
  font-size: 14px;
  opacity: .7;
}
.ov-bi-doc-name {
  font-size: 15px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -.02em;
}
.ov-bi-doc-sub {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255,255,255,.28);
  letter-spacing: .06em;
  text-transform: uppercase;
  padding-left: 8px;
  border-left: 1px solid rgba(255,255,255,.1);
}
.ov-bi-doc-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 600;
  color: color-mix(in srgb, var(--green) 60%, transparent);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.ov-bi-doc-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
  display: inline-block;
  animation: ovDocPulse 2s ease-in-out infinite;
}
@keyframes ovDocPulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: .3; }
}

/* ===== SECTION 02 — CHIP VISUAL PREVIEWS ===== */
.ov-cs-type {
  flex-direction: column;
  gap: 0;
  padding: 0;
  overflow: hidden;
  min-width: 148px;
}
.ov-cs-vis {
  width: 100%;
  height: 48px;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}
.ov-cs-vis::before,
.ov-cs-vis::after {
  content: '';
  position: absolute;
  border-radius: 2px;
}
.ov-cs-label {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 12px 9px;
  font-size: 12px;
}
/* Meta Ads */
.ov-cs-meta .ov-cs-vis { background: linear-gradient(145deg, #1565c0 0%, #090924 100%); }
.ov-cs-meta .ov-cs-vis::before { top: 10px; left: 10px; right: 10px; height: 5px; background: rgba(255,255,255,.3); }
.ov-cs-meta .ov-cs-vis::after  { top: 22px; left: 10px; width: 45%; height: 3px; background: rgba(255,255,255,.15); }
/* Google Ads */
.ov-cs-google .ov-cs-vis { background: linear-gradient(145deg, #1a3a1a 0%, #060e06 100%); }
.ov-cs-google .ov-cs-vis::before { top: 9px; left: 10px; right: 10px; height: 18px; background: rgba(255,255,255,.06); border-radius: 3px; border: 1px solid rgba(255,255,255,.1); }
.ov-cs-google .ov-cs-vis::after  { top: 14px; left: 16px; width: 28px; height: 3px; background: color-mix(in srgb, var(--green) 55%, transparent); border-radius: 1px; }
/* Landing Pages */
.ov-cs-lp .ov-cs-vis { background: linear-gradient(145deg, #0d1a2e 0%, #060a10 100%); }
.ov-cs-lp .ov-cs-vis::before { top: 8px; left: 10px; right: 10px; height: 6px; background: rgba(255,255,255,.15); border-radius: 2px; }
.ov-cs-lp .ov-cs-vis::after  { top: 20px; left: 10px; right: 10px; height: 16px; background: rgba(255,255,255,.05); border-radius: 2px; border: 1px solid rgba(255,255,255,.06); }
/* Email Campaigns */
.ov-cs-email .ov-cs-vis { background: linear-gradient(145deg, #1a1a3a 0%, #060610 100%); }
.ov-cs-email .ov-cs-vis::before { top: 9px; left: 10px; right: 10px; height: 4px; background: rgba(255,255,255,.2); }
.ov-cs-email .ov-cs-vis::after  { top: 19px; left: 10px; width: 55%; height: 3px; background: rgba(255,255,255,.09); }
/* Video Concepts */
.ov-cs-video .ov-cs-vis { background: linear-gradient(145deg, #1a0a0a 0%, #080206 100%); }
.ov-cs-video .ov-cs-vis::before { top: 50%; left: 50%; transform: translate(-50%, -50%); width: 0; height: 0; background: transparent; border-style: solid; border-width: 7px 0 7px 14px; border-color: transparent transparent transparent rgba(255,255,255,.5); border-radius: 0; }
/* Social Media Content */
.ov-cs-social .ov-cs-vis { background: linear-gradient(145deg, #2a0a3a 0%, #0a0410 100%); }
.ov-cs-social .ov-cs-vis::before { top: 8px; left: 10px; width: 14px; height: 14px; background: rgba(255,255,255,.25); border-radius: 3px; }
.ov-cs-social .ov-cs-vis::after  { top: 8px; left: 30px; width: 14px; height: 14px; background: color-mix(in srgb, var(--green) 20%, transparent); border-radius: 3px; }
/* Creative Assets */
.ov-cs-creative .ov-cs-vis { background: linear-gradient(145deg, #1a1a0a 0%, #080608 100%); }
.ov-cs-creative .ov-cs-vis::before { top: 12px; left: 10px; width: 10px; height: 10px; border-radius: 50%; background: color-mix(in srgb, var(--green) 50%, transparent); }
.ov-cs-creative .ov-cs-vis::after  { top: 12px; left: 26px; width: 10px; height: 10px; border-radius: 50%; background: rgba(255,100,100,.35); }
/* Marketing Strategy */
.ov-cs-strategy .ov-cs-vis { background: linear-gradient(145deg, #0a1a2a 0%, #040810 100%); }
.ov-cs-strategy .ov-cs-vis::before { top: 8px; left: 10px; right: 10px; height: 4px; background: color-mix(in srgb, var(--green) 40%, transparent); }
.ov-cs-strategy .ov-cs-vis::after  { top: 18px; left: 16px; right: 16px; height: 3px; background: color-mix(in srgb, var(--green) 20%, transparent); }
/* Funnels */
.ov-cs-funnel .ov-cs-vis { background: linear-gradient(145deg, #0a2a1a 0%, #040a08 100%); }
.ov-cs-funnel .ov-cs-vis::before { top: 8px; left: 10px; right: 10px; height: 3px; background: color-mix(in srgb, var(--green) 45%, transparent); }
.ov-cs-funnel .ov-cs-vis::after  { top: 16px; left: 18px; right: 18px; height: 3px; background: color-mix(in srgb, var(--green) 20%, transparent); }
/* Retargeting */
.ov-cs-retarget .ov-cs-vis { background: linear-gradient(145deg, #2a1a0a 0%, #0a0806 100%); }
.ov-cs-retarget .ov-cs-vis::before { top: 9px; left: 10px; right: 10px; height: 18px; border: 2px solid rgba(255,255,255,.2); border-radius: 50%; }
.ov-cs-retarget .ov-cs-vis::after  { top: 9px; right: 10px; width: 6px; height: 6px; background: rgba(255,255,255,.5); border-radius: 50%; }

/* ===== SECTION 03 — CAMPAIGN INPUT BAR ===== */
.ov-sc-input-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: color-mix(in srgb, var(--green) 4%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 12%, transparent);
  border-radius: 14px;
  padding: 16px 22px;
  margin: 0 auto 28px;
  max-width: 1060px;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity .4s ease, transform .4s ease;
}
.ov-sc-input-bar.ov-vis { opacity: 1; transform: translateY(0); }
.ov-sc-ib-left {
  display: flex;
  align-items: center;
  gap: 12px;
}
.ov-sc-ib-spark {
  color: var(--green);
  font-size: 16px;
  opacity: .7;
  flex-shrink: 0;
}
.ov-sc-ib-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: rgba(255,255,255,.28);
  margin-bottom: 3px;
}
.ov-sc-ib-val {
  font-size: 14px;
  font-weight: 700;
  color: rgba(255,255,255,.85);
  letter-spacing: -.01em;
}
.ov-sc-ib-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}
.ov-sc-ib-count {
  font-size: 12px;
  font-weight: 700;
  color: rgba(255,255,255,.5);
}
.ov-sc-ib-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 65%, transparent);
}
.ov-sc-ib-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
  display: inline-block;
  animation: ovDocPulse 2s ease-in-out infinite;
}

/* ===== SECTION 04 — CASE STUDY CARD ===== */
.ov-case-card {
  background: rgba(255,255,255,.02);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 18px;
  padding: 24px 32px;
  max-width: 860px;
  margin: 0 auto 56px;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .45s ease, transform .45s ease;
}
.ov-case-card.ov-vis { opacity: 1; transform: translateY(0); }
.ov-case-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}
.ov-case-tag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--green);
  background: color-mix(in srgb, var(--green) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius: 20px;
  padding: 3px 10px;
}
.ov-case-brand {
  font-size: 12px;
  color: rgba(255,255,255,.38);
  font-weight: 500;
}
.ov-case-metrics {
  display: flex;
  align-items: center;
}
.ov-case-m {
  flex: 1;
  text-align: center;
  padding: 0 16px;
}
.ov-case-m-div {
  width: 1px;
  height: 36px;
  background: rgba(255,255,255,.07);
  flex-shrink: 0;
}
.ov-case-m-name {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: rgba(255,255,255,.28);
  margin-bottom: 8px;
}
.ov-case-m-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.ov-case-m-before {
  font-size: 17px;
  font-weight: 700;
  color: rgba(255,255,255,.3);
  letter-spacing: -.02em;
}
.ov-case-m-arr {
  font-size: 13px;
  color: rgba(255,255,255,.18);
}
.ov-case-m-after {
  font-size: 20px;
  font-weight: 800;
  color: var(--green);
  letter-spacing: -.03em;
}

/* Mobile tweaks for new elements */
@media (max-width: 700px) {
  .ov-sc-input-bar { flex-direction: column; align-items: flex-start; gap: 12px; }
  .ov-sc-ib-right { align-items: flex-start; }
  .ov-case-card { padding: 20px 18px; }
  .ov-case-metrics { flex-direction: column; gap: 16px; }
  .ov-case-m-div { display: none; }
  .ov-case-m { padding: 0; }
  .ov-cs-type { min-width: 130px; }
}

/* Fix nth-child stagger after .ov-bi-doc-header was added as first child */
.ov-bi-card.ov-vis .ov-bi-row:nth-child(2)  { transition-delay: 0s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(3)  { transition-delay: .07s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(4)  { transition-delay: .14s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(5)  { transition-delay: .21s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(6)  { transition-delay: .28s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(7)  { transition-delay: .35s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(8)  { transition-delay: .42s; }
.ov-bi-card.ov-vis .ov-bi-row:nth-child(9)  { transition-delay: .49s; }

/* ===== FINAL POLISH PASS CSS ===== */

/* --- Section 02: chip hover states --- */
.ov-cs-type { cursor: pointer; }
.ov-cs-type:hover {
  transform: scale(1.04) translateY(-2px);
  border-color: color-mix(in srgb, var(--green) 30%, transparent);
  background: color-mix(in srgb, var(--green) 6%, transparent);
  box-shadow: 0 8px 32px rgba(0,0,0,.45), 0 0 0 1px color-mix(in srgb, var(--green) 15%, transparent);
  color: #fff;
}
.ov-cs-type:hover .ov-cs-dot { background: var(--green); }
.ov-cs-type { transition: opacity .38s ease, transform .38s cubic-bezier(.34,1.56,.64,1), border-color .2s ease, background .2s ease, box-shadow .2s ease, color .2s ease; }

/* --- Section 04: stats context label --- */
.ov-stats-context {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.22);
  text-align: center;
  margin-bottom: 28px;
  padding-top: 4px;
  position: relative;
}
.ov-stats-context::before {
  content: '';
  display: block;
  width: 32px;
  height: 1px;
  background: rgba(255,255,255,.1);
  margin: 0 auto 14px;
}

/* --- FAQ: center heading --- */
.ov-faq-inner { text-align: center; }
.ov-faq-list { text-align: left; }

/* --- Final CTA: depth rings --- */
.ov-final-rings {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.ov-fr {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--green) 6%, transparent);
  animation: ovRingPulse 6s ease-in-out infinite;
}
.ov-fr-1 { width: 400px; height: 400px; animation-delay: 0s; }
.ov-fr-2 { width: 700px; height: 700px; animation-delay: 1.5s; border-color: color-mix(in srgb, var(--green) 4%, transparent); }
.ov-fr-3 { width: 1000px; height: 1000px; animation-delay: 3s; border-color: color-mix(in srgb, var(--green) 2.5%, transparent); }
@keyframes ovRingPulse {
  0%, 100% { opacity: .6; transform: translate(-50%, -50%) scale(1); }
  50%        { opacity: 1;  transform: translate(-50%, -50%) scale(1.03); }
}
#ov-final::before {
