.bcp-empty {
  text-align: center !important; padding: 80px 24px !important;
}
.bcp-empty-title { font-size: 22px !important; font-weight: 700 !important; color: var(--ap-text) !important; letter-spacing: -.02em !important; }
.bcp-empty-sub { color: var(--ap-muted) !important; font-size: 14px !important; margin: 8px 0 24px !important; }

/* ── SETTINGS ───────────────────────────────────────────────── */
