.se-card { background: var(--ap-bg3) !important; border: 1px solid var(--ap-border) !important; border-radius: var(--ap-radius) !important; padding: 20px 22px !important; margin-bottom: 10px !important; }

/* ── INTEL / MONITOR ─────────────────────────────────────────── */
