/* ── ASSETS PAGE ────────────────────────────────────────────── */
.asl-outer { max-width: var(--orv-content-maxw); margin: 0 auto; padding: var(--orv-content-pad-top) var(--orv-content-pad-x) var(--orv-content-pad-bottom); }
.asl-hdr { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: var(--orv-title-gap); }
.asl-title { font-size: 22px; font-weight: 800; letter-spacing: -.03em; line-height: 1.2; color: var(--ap-text); margin: 0 0 5px; }
.asl-sub { font-size: 13px; color: var(--ap-muted); margin: 0; line-height: 1.5; }
.asl-create-btn {
  background: var(--ap-green); color: #000; border: none;
  border-radius: 10px; padding: 10px 18px;
  font-size: 13px; font-weight: 700; cursor: pointer;
  display: inline-flex; align-items: center; gap: 6px;
  flex-shrink: 0; transition: opacity .15s;
}
.asl-create-btn:hover { opacity: .88; }
.asl-filters { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 22px; }
.asl-filter {
  background: var(--ap-bg3); border: 1px solid var(--ap-border);
