.asl-grid { display: grid; grid-template-columns: repeat(auto-fill,minmax(230px,1fr)); gap: 12px; }
.asl-card {
  background: var(--ap-bg3); border: 1px solid var(--ap-border);
  border-radius: var(--ap-radius); padding: 20px; cursor: pointer;
  transition: border-color .18s, transform .18s;
  display: flex; flex-direction: column; gap: 8px; min-height: 96px;
}
.asl-card:hover { border-color: rgba(255,255,255,.16); transform: translateY(-1px); }
.asl-card-type {
  font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--ap-green); background: var(--ap-green-d);
