}
.asl-card-camp { font-size: 14px; font-weight: 600; color: var(--ap-text); letter-spacing: -.01em; }
.asl-card-date { font-size: 11px; color: var(--ap-muted); margin-top: auto; }
.asl-empty { padding: 60px 24px; text-align: center; }
