  background: none; border: 1px solid var(--ap-border);
  border-radius: 10px; padding: 10px 20px;
  font-size: 13px; font-weight: 500; color: var(--ap-text);
  cursor: pointer; font-family: inherit; transition: border-color .15s;
}
.asl-empty-btn:hover { border-color: rgba(255,255,255,.2); }

/* ── TOAST ──────────────────────────────────────────────────── */
.toast {
  position: fixed !important; bottom: 24px !important;
  left: 50% !important; transform: translateX(-50%) translateY(80px) !important;
  background: var(--ap-bg3) !important; border: 1px solid var(--ap-border) !important;
  border-radius: 10px !important; padding: 10px 18px !important;
  font-size: 13px !important; color: var(--ap-text) !important;
  z-index: 9000 !important; transition: transform .25s, opacity .25s !important;
  max-width: calc(100vw - 32px) !important; white-space: normal !important; text-align: center !important;
}
/* app.js toast() only ever applies class "show" (never "toast-show") — this
   selector previously never matched, so the toast's resting transform
   (translateY(80px)) was never overridden back to visible position. */
.toast.show { transform: translateX(-50%) translateY(0) !important; }

/* ── MODALS on dark theme ────────────────────────────────────── */
.bcw-panel, .pw-modal { background: var(--ap-bg2) !important; border: 1px solid var(--ap-border) !important; }

