    color: #000 !important;
  }
  .mbn-create-btn svg { stroke: #000 !important; opacity: 1 !important; }
  .mc { padding-bottom: 58px !important; }
  .ap-home-outer { padding: 22px 16px 20px !important; }
  .asl-outer { padding: 22px 16px 20px !important; }
  .camp-hub { padding: 22px 16px 20px !important; }
  .bcp-scroll { padding: 22px 16px 20px !important; }
  .intel-outer, .bsp-outer { padding: 22px 16px 20px !important; }
  .se-outer { padding: 22px 16px 20px !important; }
  .bb-top-row { grid-template-columns: 1fr !important; }
  .bb-metrics { grid-template-columns: repeat(2,1fr) !important; }
