  white-space: pre-wrap;
}
.cws-tiktok-caption-text {
  font-size: 14px;
  color: var(--t1, #fff);
  line-height: 1.6;
}
.cws-tiktok-meta { display: flex; flex-direction: column; gap: 12px; }
.cws-tiktok-cta-row { display: flex; }
.cws-tiktok-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }

/* ── Campaign Results (no sidebar) ─────────────────────────────── */
.cwr {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
}
.cwr-topbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 28px;
  border-bottom: 1px solid rgba(255,255,255,.06);
  flex-shrink: 0;
}
.cwr-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--t3, #888);
  background: none;
  border: none;
  cursor: pointer;
  padding: 5px 10px;
  border-radius: 6px;
  transition: background .15s, color .15s;
}
.cwr-back:hover { background: rgba(255,255,255,.06); color: var(--t1, #fff); }
.cwr-back svg { width: 10px; height: 10px; }
.cwr-meta { display: flex; align-items: center; gap: 8px; }
.cwr-name { font-size: 14px; font-weight: 600; color: var(--t1, #fff); }
.cwr-type-badge {
  font-size: 11px; font-weight: 600; letter-spacing: .06em;
  text-transform: uppercase; color: var(--t3, #888);
  background: rgba(255,255,255,.07); border-radius: 10px;
  padding: 2px 8px;
}
.cwr-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 36px 28px 60px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.cwr-asset-wrap { width: 100%; max-width: 800px; }
.cwr-asset-inner { display: flex; flex-direction: column; gap: 0; }

/* Asset action bar */
.cwr-action-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  padding: 28px 0 8px;
  border-top: 1px solid rgba(255,255,255,.06);
  margin-top: 24px;
}
.cwr-ab-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background .15s, opacity .15s;
  text-decoration: none;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.05);
  color: var(--t1, #fff);
}
.cwr-ab-btn:hover { background: rgba(255,255,255,.1); }
.cwr-ab-primary {
  background: var(--green) !important;
  color: #000 !important;
  border-color: transparent !important;
  font-weight: 700;
}
.cwr-ab-primary:hover { background: var(--gm) !important; }
.cwr-ab-danger {
  border-color: rgba(255,80,80,.3) !important;
  color: #ff6060 !important;
}
.cwr-ab-danger:hover { background: rgba(255,80,80,.12) !important; }

/* Video player */
.cws-vid-wrap {
  width: 100%;
  border-radius: 12px;
  overflow: hidden;
  background: #000;
  margin-bottom: 24px;
}
.cws-vid-player {
  width: 100%;
  display: block;
  max-height: 480px;
  object-fit: contain;
}

/* Video generating state */
.cws-vid-generating {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 48px 24px;
  background: color-mix(in srgb, var(--green) 4%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 12%, transparent);
  border-radius: 12px;
  margin-bottom: 24px;
  text-align: center;
}
.cws-vid-gen-spin {
  width: 32px; height: 32px;
  border: 3px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-top-color: var(--green);
  border-radius: 50%;
  animation: spin .8s linear infinite;
}
.cws-vid-gen-lbl { font-size: 14px; color: var(--t2, #ccc); line-height: 1.5; }
.cws-vid-failed {
  padding: 20px;
  background: rgba(255,80,80,.06);
  border: 1px solid rgba(255,80,80,.2);
  border-radius: 10px;
  color: #ff8080;
  font-size: 13px;
  text-align: center;
  margin-bottom: 20px;
}

/* Image upload in campaign creation */
.ncc-upload-label {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border: 1.5px dashed rgba(255,255,255,.18);
  border-radius: 10px;
  cursor: pointer;
  font-size: 13px;
  color: var(--t3, #888);
  transition: border-color .15s, background .15s;
  background: rgba(255,255,255,.02);
}
.ncc-upload-label:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); background: color-mix(in srgb, var(--green) 4%, transparent); color: var(--t2,#ccc); }
.ncc-img-previews { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.ncc-img-thumb {
  position: relative;
  width: 64px; height: 64px;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.1);
}
.ncc-img-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ncc-img-remove {
  position: absolute; top: 2px; right: 2px;
  width: 18px; height: 18px;
  border-radius: 50%;
  background: rgba(0,0,0,.7);
  border: none; cursor: pointer;
  color: #fff; font-size: 11px; line-height: 18px; text-align: center;
}

/* Desktop/Mobile/Tablet preview toggle */
.cwr-preview-toggle {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 10px 14px;
  background: rgba(255,255,255,.03);
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.cwr-ptog {
  padding: 5px 14px; font-size: 12px; font-weight: 500;
  border-radius: 6px; border: none; cursor: pointer;
  background: none; color: var(--t3, #888); transition: all .15s;
}
.cwr-ptog-on { background: rgba(255,255,255,.1); color: var(--t1, #fff); }
.cwr-ptog-fullscreen {
  margin-left: auto;
  display: inline-flex; align-items: center; gap: 5px;
  padding: 5px 12px; font-size: 12px; font-weight: 500;
  border-radius: 6px; border: 1px solid rgba(255,255,255,.1); cursor: pointer;
  background: none; color: var(--t3, #888); transition: all .15s;
}
.cwr-ptog-fullscreen:hover { background: rgba(255,255,255,.07); color: var(--t1, #fff); }

/* Fullscreen LP overlay */
.cws-lp-fullscreen {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: #fff;
  display: flex;
  flex-direction: column;
}
.cws-lp-fullscreen-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
  background: #111;
  border-bottom: 1px solid rgba(255,255,255,.1);
  flex-shrink: 0;
}
.cws-lp-fullscreen-title { font-size: 13px; color: rgba(255,255,255,.6); font-weight: 500; }
.cws-lp-fullscreen-close {
  background: none; border: none; cursor: pointer;
  color: rgba(255,255,255,.7); font-size: 13px; font-weight: 500;
  padding: 6px 14px; border-radius: 6px;
  border: 1px solid rgba(255,255,255,.15);
  transition: all .15s;
}
.cws-lp-fullscreen-close:hover { background: rgba(255,255,255,.1); color: #fff; }
.cws-lp-fullscreen-frame {
  flex: 1;
  width: 100%;
  border: none;
  display: block;
}

/* Assets library page */
#page-assets.active { display: flex; flex-direction: column; padding: 0; height: 100%; }
.ast-wrap { flex: 1; overflow-y: auto; padding: 36px 40px 60px; }
.ast-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 32px; }
.ast-title { font-size: 22px; font-weight: 700; color: var(--t1, #fff); }
.ast-subtitle { font-size: 13px; color: var(--t3, #888); margin-top: 4px; }
.ast-tabs { display: flex; gap: 4px; margin-bottom: 28px; }
.ast-tab {
  padding: 7px 16px; border-radius: 8px; font-size: 13px; font-weight: 500;
  cursor: pointer; border: none; background: none; color: var(--t3, #888);
  transition: all .15s;
}
.ast-tab.on { background: rgba(255,255,255,.08); color: var(--t1, #fff); }
.ast-empty {
  text-align: center; padding: 80px 20px;
  color: var(--t3, #888); font-size: 14px;
}
.ast-empty svg { opacity: .3; margin-bottom: 16px; }
.ast-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}
.ast-card {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 12px;
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: border-color .15s;
}
.ast-card:hover { border-color: rgba(255,255,255,.16); }
.ast-card-thumb {
  width: 100%; aspect-ratio: 16/9; background: rgba(255,255,255,.04);
  display: flex; align-items: center; justify-content: center;
  overflow: hidden; position: relative;
}
.ast-card-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ast-card-thumb-placeholder {
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  color: rgba(255,255,255,.2);
}
.ast-card-body { padding: 14px 16px; flex: 1; display: flex; flex-direction: column; gap: 4px; }
.ast-card-type {
  font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--t3, #888);
}
.ast-card-name { font-size: 14px; font-weight: 600; color: var(--t1, #fff); line-height: 1.3; }
.ast-card-date { font-size: 12px; color: var(--t3, #888); margin-top: 2px; }
.ast-card-actions {
  display: flex; gap: 6px; padding: 10px 16px 14px;
  border-top: 1px solid rgba(255,255,255,.05);
}
.ast-card-btn {
  flex: 1; padding: 7px 10px; border-radius: 7px; font-size: 12px; font-weight: 500;
  cursor: pointer; border: 1px solid rgba(255,255,255,.1);
  background: none; color: var(--t2, #ccc); transition: all .15s; text-align: center;
  text-decoration: none; display: inline-flex; align-items: center; justify-content: center;
}
.ast-card-btn:hover { background: rgba(255,255,255,.07); color: var(--t1, #fff); }
.ast-card-btn-danger { border-color: rgba(255,80,80,.2) !important; color: #ff6060 !important; }
.ast-card-btn-danger:hover { background: rgba(255,80,80,.08) !important; }

/* ════════════════════════════════════════════════════════════════
   BRAND ONBOARDING OVERLAY
   ════════════════════════════════════════════════════════════════ */
.obd-overlay {
  position: fixed; inset: 0; z-index: 10000;
  background: rgba(0,0,0,.92);
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
}
.obd-card {
  background: #111; border: 1px solid rgba(255,255,255,.1);
  border-radius: 20px; padding: 48px 48px 40px;
  width: 100%; max-width: 540px;
  display: flex; flex-direction: column; gap: 0;
}
.obd-logo {
  font-size: 13px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  color: var(--green); margin-bottom: 36px;
}
.obd-progress {
  display: flex; gap: 6px; margin-bottom: 32px;
}
.obd-dot {
  height: 3px; flex: 1; border-radius: 2px;
  background: rgba(255,255,255,.12); transition: background .2s;
}
.obd-dot-done   { background: color-mix(in srgb, var(--green) 50%, transparent); }
.obd-dot-active { background: var(--green); }
.obd-counter {
  font-size: 11px; color: rgba(255,255,255,.4); font-weight: 600;
  letter-spacing: .06em; text-transform: uppercase; margin-bottom: 12px;
}
.obd-question {
  font-size: 22px; font-weight: 700; color: #fff; line-height: 1.3;
  margin-bottom: 28px;
}
.obd-input {
  width: 100%;
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.12);
  border-radius: 10px; padding: 14px 16px;
  font-size: 15px; color: #fff; outline: none; transition: border-color .15s;
}
.obd-input::placeholder { color: rgba(255,255,255,.3); }
.obd-input:focus { border-color: color-mix(in srgb, var(--green) 50%, transparent); }
.obd-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.obd-chip {
  padding: 9px 16px; border-radius: 100px;
  border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.04);
  font-size: 13px; font-weight: 500; color: rgba(255,255,255,.7);
  cursor: pointer; transition: all .15s;
}
.obd-chip:hover { background: rgba(255,255,255,.08); color: #fff; border-color: rgba(255,255,255,.2); }
.obd-chip-sel { background: color-mix(in srgb, var(--green) 12%, transparent) !important; border-color: var(--green) !important; color: var(--green) !important; }
.obd-nav {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: 36px;
}
.obd-skip {
  background: none; border: none; cursor: pointer;
  font-size: 12px; color: rgba(255,255,255,.3); font-weight: 500;
  transition: color .15s; padding: 0;
}
.obd-skip:hover { color: rgba(255,255,255,.6); }
.obd-btns { display: flex; gap: 10px; }
.obd-back {
  padding: 11px 22px; border-radius: 10px; font-size: 14px; font-weight: 600;
  border: 1px solid rgba(255,255,255,.12); background: none; color: rgba(255,255,255,.6);
  cursor: pointer; transition: all .15s;
}
.obd-back:hover { background: rgba(255,255,255,.06); color: #fff; }
.obd-next {
  padding: 11px 26px; border-radius: 10px; font-size: 14px; font-weight: 700;
  border: none; background: var(--green); color: #000;
  cursor: pointer; transition: all .15s;
}
.obd-next:hover { background: var(--gm); }

/* ── Product tour overlay ────────────────────────────────────── */
#obTourOverlay { display: none; }

/* ── Reward screen ───────────────────────────────────────────── */
.obd-reward-overlay {
  position: fixed; inset: 0; z-index: 10000;
  background: rgba(0,0,0,.94);
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
}
.obd-reward-card {
  background: #111; border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius: 24px; padding: 52px 48px 44px;
  width: 100%; max-width: 480px;
  display: flex; flex-direction: column; align-items: center;
  text-align: center; gap: 0;
}
.obd-reward-icon {
  width: 68px; height: 68px; border-radius: 18px;
  background: color-mix(in srgb, var(--green) 10%, transparent); border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  display: flex; align-items: center; justify-content: center;
  font-size: 32px; margin-bottom: 28px;
}
.obd-reward-title {
  font-size: 26px; font-weight: 800; color: #fff; line-height: 1.2; margin-bottom: 10px;
}
.obd-reward-sub {
  font-size: 14px; color: rgba(255,255,255,.5); line-height: 1.6; margin-bottom: 32px;
  max-width: 340px;
}
.obd-reward-credit {
  background: color-mix(in srgb, var(--green) 8%, transparent); border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius: 14px; padding: 20px 28px; width: 100%; margin-bottom: 32px;
}
.obd-reward-credit-label {
  font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 70%, transparent); margin-bottom: 8px;
}
.obd-reward-credit-value {
  font-size: 22px; font-weight: 800; color: var(--green); margin-bottom: 4px;
}
.obd-reward-credit-hint {
  font-size: 12px; color: rgba(255,255,255,.35);
}
.obd-reward-cta {
  width: 100%; padding: 15px 28px; border-radius: 12px;
  background: var(--green); color: #000; font-size: 15px; font-weight: 800;
  border: none; cursor: pointer; transition: background .15s;
}
.obd-reward-cta:hover { background: var(--gm); }
.obd-reward-fine {
  font-size: 11px; color: rgba(255,255,255,.25); margin-top: 14px;
}

/* ── Edit drawer ────────────────────────────────────────────────── */
.cwr-edit-drawer {
  position: fixed;
  right: 0; top: 0; bottom: 0;
  width: 420px;
  background: var(--bg2, #111);
  border-left: 1px solid rgba(255,255,255,.08);
  display: flex;
  flex-direction: column;
  z-index: 900;
  box-shadow: -8px 0 40px rgba(0,0,0,.5);
}
.cwr-edit-hdr {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 20px; border-bottom: 1px solid rgba(255,255,255,.08);
  flex-shrink: 0;
}
.cwr-edit-title { font-size: 15px; font-weight: 600; color: var(--t1, #fff); }
.cwr-edit-close { background: none; border: none; cursor: pointer; color: var(--t3, #888); padding: 4px; border-radius: 4px; }
.cwr-edit-close:hover { color: var(--t1, #fff); }
.cwr-edit-body { flex: 1; overflow-y: auto; padding: 16px 20px; display: flex; flex-direction: column; gap: 20px; }
.cwr-edit-foot { padding: 16px 20px; border-top: 1px solid rgba(255,255,255,.08); flex-shrink: 0; }
.cwr-edit-apply {
  width: 100%; padding: 12px; border-radius: 8px;
  background: var(--green); color: #000; border: none;
  font-size: 14px; font-weight: 700; cursor: pointer;
}
.cwr-edit-apply:hover { background: var(--gm); }
.cwr-edit-section { display: flex; flex-direction: column; gap: 8px; }
.cwr-edit-lbl { font-size: 11px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--t3, #888); }
.cwr-edit-textarea {
  width: 100%; height: 260px; padding: 12px; border-radius: 8px;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1);
  color: var(--t1, #fff); font-size: 12px; font-family: monospace;
  resize: vertical; box-sizing: border-box;
}
.cwr-edit-link-row { display: flex; flex-direction: column; gap: 4px; margin-bottom: 8px; }
.cwr-edit-link-text { font-size: 11px; color: var(--t3, #888); }
.cwr-edit-link-inp {
  padding: 8px 10px; border-radius: 6px;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1);
  color: var(--t1, #fff); font-size: 12px; width: 100%; box-sizing: border-box;
}

/* ── Modal header fix (step dots + close, no overlap) ───────────── */
.ncc-modal-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 20px 0;
  flex-shrink: 0;
}
.ncc-modal-head .ncc-stepbar { flex: 1; margin: 0; padding: 0; }
.ncc-modal-head .ncc-close {
  position: static !important;
  flex-shrink: 0;
  margin-left: 8px;
}

/* ════════════════════════════════════════════════════════════════
   LANDING PAGE REDESIGN — Marketing Intelligence Platform
   ════════════════════════════════════════════════════════════════ */

/* ── Hero: accent headline + integration pills ─────────────────── */
.ov-h1-accent { color: var(--green); }

.ov-hero-integrations {
  display: flex; align-items: center; gap: 14px;
  margin-top: 28px; flex-wrap: wrap;
}
.ov-hero-int-label {
  font-size: 12px; color: rgba(255,255,255,.38); font-weight: 500;
  letter-spacing: .02em; white-space: nowrap;
}
.ov-hero-int-logos { display: flex; gap: 8px; flex-wrap: wrap; }
.ov-hero-int-pill {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 6px 13px; border-radius: 100px;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1);
  font-size: 12px; font-weight: 500; color: rgba(255,255,255,.65);
  letter-spacing: .01em;
  /* Redesign: now a <button>, visually selectable (ovHeroPlatformPick) —
     purely cosmetic, no functional targeting. */
  cursor: pointer;
  font-family: inherit;
  transition: opacity .2s ease, border-color .2s ease;
}
.ov-hero-int-pill:not(.ov-hero-int-pill-active) { opacity: .4; }
.ov-hero-int-pill:hover { opacity: .85; }
.ov-hero-int-pill-active:hover { opacity: 1; }
.ov-hero-int-pill:focus-visible { outline: 2px solid var(--green, #B7FF2A); outline-offset: 2px; }
.ov-int-dot {
  width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0;
}
.ov-int-dot-google { background: #4285F4; }
.ov-int-dot-tiktok { background: #EE1D52; }
.ov-int-dot-meta   { background: #0866FF; }

/* ── Utility ───────────────────────────────────────────────────── */
.ov-green { color: var(--green) !important; }

/* ── Platform Unification (Section 01) ────────────────────────── */
#ov-platform {
  padding: 120px 24px;
  background: rgba(255,255,255,.01);
}
.ov-plat-inner { max-width: 1080px; margin: 0 auto; }

.ov-plat-diagram {
  display: flex; align-items: stretch;
  margin-top: 56px; border-radius: 20px;
  border: 1px solid rgba(255,255,255,.08);
  background: rgba(255,255,255,.02); overflow: hidden;
  opacity: 0; transform: translateY(24px);
  transition: opacity .65s ease, transform .65s ease;
}
.ov-plat-diagram.ov-vis { opacity: 1; transform: translateY(0); }

.ov-plat-sources {
  flex: 1; display: flex; flex-direction: column;
  border-right: 1px solid rgba(255,255,255,.08);
}
.ov-plat-source {
  flex: 1; display: flex; overflow: hidden;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.ov-plat-source:last-child { border-bottom: none; }

.ov-ps-bar { width: 3px; flex-shrink: 0; }
.ov-ps-bar-google { background: #4285F4; }
.ov-ps-bar-tiktok { background: #EE1D52; }
.ov-ps-bar-meta   { background: #0866FF; }

.ov-ps-body { padding: 22px 24px; flex: 1; }
