.ov-ps-dot-google { background: #4285F4; }
.ov-ps-dot-tiktok { background: #EE1D52; }
.ov-ps-dot-meta   { background: #0866FF; }

.ov-ps-metrics { display: flex; flex-direction: column; gap: 6px; }
.ov-ps-m {
