}
.ov-pb-logo-text {
  font-size: 12px; font-weight: 800; letter-spacing: .12em;
  color: var(--green);
}
.ov-pb-badge {
  font-size: 10px; font-weight: 600; letter-spacing: .06em;
  text-transform: uppercase; color: color-mix(in srgb, var(--green) 70%, transparent);
