/* ── Comparison Section (Section 02) ──────────────────────────── */
#ov-compare {
  padding: 120px 24px;
  background: rgba(0,0,0,.2);
}
.ov-compare-inner { max-width: 920px; margin: 0 auto; }

.ov-compare-grid {
  display: grid; grid-template-columns: 1fr auto 1fr;
  margin-top: 52px; gap: 0;
  opacity: 0; transform: translateY(20px);
  transition: opacity .6s ease, transform .6s ease;
}
.ov-compare-grid.ov-vis { opacity: 1; transform: translateY(0); }

.ov-cmp-col {
  padding: 34px; border: 1px solid rgba(255,255,255,.08); border-radius: 16px;
}
.ov-cmp-before { background: rgba(255,255,255,.02); }
.ov-cmp-after {
  background: color-mix(in srgb, var(--green) 2.5%, transparent);
  border-color: color-mix(in srgb, var(--green) 14%, transparent);
}
.ov-cmp-head {
  font-size: 13px; font-weight: 700; letter-spacing: .04em;
  text-transform: uppercase; margin-bottom: 24px;
}
.ov-cmp-before .ov-cmp-head { color: rgba(255,255,255,.38); }
.ov-cmp-after  .ov-cmp-head { color: var(--green); }

.ov-cmp-list {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-direction: column; gap: 15px;
}
.ov-cmp-list li {
  display: flex; align-items: flex-start; gap: 10px;
  font-size: 14px; line-height: 1.5; color: rgba(255,255,255,.58);
}
