/* ── Globe visual ─────────────────────────────────────────────── */
.ov-global-visual {
  margin: 52px auto 56px;
  max-width: 600px;
  display: flex; justify-content: center; align-items: center;
  opacity: 0; transform: translateY(24px);
  transition: opacity .8s ease, transform .8s ease;
}
.ov-global-visual.ov-vis { opacity: 1; transform: translateY(0); }

.ov-globe-container {
  position: relative;
  display: flex; flex-direction: column; align-items: center; gap: 28px;
}

.ov-globe-svg {
  width: 280px; height: 280px;
  filter: drop-shadow(0 0 40px color-mix(in srgb, var(--green) 7%, transparent));
}

/* Pulsing glow on dots */
.ov-gdot {
  opacity: .85;
  animation: ov-gdot-pulse 2.8s ease-in-out infinite;
}
.ov-gdot-1 { animation-delay: 0s; }
.ov-gdot-2 { animation-delay: .4s; }
.ov-gdot-3 { animation-delay: .8s; }
.ov-gdot-4 { animation-delay: 1.2s; }
.ov-gdot-5 { animation-delay: .6s; }
.ov-gdot-6 { animation-delay: 1.6s; }
.ov-gdot-7 { animation-delay: .2s; }

.ov-gdot-halo {
  animation: ov-gdot-halo-pulse 2.8s ease-in-out infinite;
}

@keyframes ov-gdot-pulse {
  0%, 100% { opacity: .85; r: 4; }
  50%       { opacity: 1;   }
}
@keyframes ov-gdot-halo-pulse {
  0%, 100% { opacity: .07; }
  50%       { opacity: .18; }
}

/* Country pills below globe */
.ov-globe-countries {
  display: flex; flex-wrap: wrap; gap: 8px; justify-content: center;
