/* ════════════════════════════════════════════════════════════════
   LANDING REFINEMENTS — Fragment Concept + Polish
   ════════════════════════════════════════════════════════════════ */

/* ── Google Ads: gold everywhere ──────────────────────────────── */
.ov-ps-bar-google  { background: #FBBC05; }
.ov-ps-dot-google  { background: #FBBC05; }
.ov-int-dot-google { background: #FBBC05; }

/* ── Section 03: centered heading ─────────────────────────────── */
#ov-brand-identity .ov-section-h,
#ov-brand-identity .ov-section-sub { text-align: center; }

/* ── Section 04: centered heading ─────────────────────────────── */
#ov-brief-preview .ov-section-h,
#ov-brief-preview .ov-section-sub  { text-align: center; }

/* ── Fragment visual layer ─────────────────────────────────────── */
.ov-frag-layer {
  position: absolute; inset: 0;
  pointer-events: none; overflow: hidden; z-index: 0;
}
.ov-frag {
  position: absolute;
  width: 36px; height: 5px;
  background: color-mix(in srgb, var(--green) 5.5%, transparent);
  border-radius: 1px;
  animation: ov-frag-drift var(--dur,8s) ease-in-out var(--del,0s) infinite;
  transform: rotate(var(--rot,0deg));
}
.ov-frag-sm { width: 22px; height: 4px; background: color-mix(in srgb, var(--green) 4%, transparent); }
.ov-frag-lg { width: 54px; height: 5px; background: color-mix(in srgb, var(--green) 4%, transparent); }
.ov-frag-v  { width: 4px;  height: 26px; }

@keyframes ov-frag-drift {
  0%   { transform: rotate(var(--rot,0deg)) translate(0,0);            opacity: .4;  }
  25%  { transform: rotate(calc(var(--rot,0deg) + 14deg)) translate(8px,-16px);  opacity: .8;  }
  55%  { transform: rotate(calc(var(--rot,0deg) +  7deg)) translate(4px,-10px);  opacity: .5;  }
  80%  { transform: rotate(calc(var(--rot,0deg) -  9deg)) translate(-7px,-19px); opacity: .7;  }
  100% { transform: rotate(var(--rot,0deg)) translate(0,0);            opacity: .4;  }
}

/* Micro fragment accents at section tops */
#ov-platform,
#ov-compare,
#ov-brand-identity { position: relative; }

#ov-platform::before,
#ov-compare::before,
#ov-brand-identity::before {
  content: '';
  display: block;
  position: absolute;
  top: 0; left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 24px; height: 4px;
  background: color-mix(in srgb, var(--green) 7%, transparent);
  border-radius: 1px;
  pointer-events: none;
}

/* ── Interactive 3D globe canvas ───────────────────────────────── */
.ov-globe-wrap {
  position: relative;
  display: flex; justify-content: center;
}
#ov-globe-canvas {
  display: block;
  max-width: 100%;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

/* ── Language cards: staggered entrance via parent ov-vis ─────── */
.ov-lang-grid {
  opacity:    1 !important;
  transform:  none !important;
  transition: none !important;
}
.ov-lang-card {
  opacity:   0;
  transform: translateY(18px);
  transition: opacity .5s cubic-bezier(.22,1,.36,1),
              transform .5s cubic-bezier(.22,1,.36,1),
              border-color .2s, background .2s;
}
.ov-lang-grid.ov-vis .ov-lang-card              { opacity: 1; transform: none; }
.ov-lang-grid.ov-vis .ov-lang-card:nth-child(1) { transition-delay: .04s; }
.ov-lang-grid.ov-vis .ov-lang-card:nth-child(2) { transition-delay: .10s; }
.ov-lang-grid.ov-vis .ov-lang-card:nth-child(3) { transition-delay: .16s; }
.ov-lang-grid.ov-vis .ov-lang-card:nth-child(4) { transition-delay: .22s; }
.ov-lang-grid.ov-vis .ov-lang-card:nth-child(5) { transition-delay: .28s; }
.ov-lang-grid.ov-vis .ov-lang-card:nth-child(6) { transition-delay: .34s; }
.ov-lang-grid.ov-vis .ov-lang-card:nth-child(7) { transition-delay: .40s; }

/* ── Feature cards: spring curve + hover lift ─────────────────── */
.ov-feat-card {
  transition: opacity .55s cubic-bezier(.22,1,.36,1),
              transform .55s cubic-bezier(.22,1,.36,1),
              border-color .2s, box-shadow .2s;
}
.ov-feat-card.ov-vis:hover {
  border-color: color-mix(in srgb, var(--green) 18%, transparent);
  box-shadow:   0 0 0 1px color-mix(in srgb, var(--green) 6%, transparent), 0 12px 32px rgba(0,0,0,.24);
  transform:    translateY(-3px);
}

/* ── Brief card hover ──────────────────────────────────────────── */
.ov-brief-card {
  transition: opacity .7s ease, transform .7s ease, box-shadow .25s ease;
}
.ov-brief-card.ov-vis:hover {
  box-shadow: 0 24px 64px rgba(0,0,0,.3), 0 0 0 1px color-mix(in srgb, var(--green) 12%, transparent);
}

/* ── Platform arrow: animated pulse ───────────────────────────── */
.ov-plat-arrow-head {
  display: inline-block;
  animation: ov-arrow-nudge 2.4s ease-in-out infinite;
}
@keyframes ov-arrow-nudge {
  0%,100% { opacity: .45; transform: translateX(0);   }
  50%     { opacity: .9;  transform: translateX(5px);  }
}

/* ── Comparison grid: entrance animation improvement ──────────── */
.ov-compare-grid {
  transition: opacity .7s cubic-bezier(.22,1,.36,1),
              transform .7s cubic-bezier(.22,1,.36,1);
}

/* ── Globe countries margin ────────────────────────────────────── */
.ov-globe-countries { margin-top: 20px; }

/* ── Section label: consistent accent ─────────────────────────── */
.ov-section-label {
  letter-spacing: .12em;
  color: color-mix(in srgb, var(--green) 45%, transparent);
}

/* ════════════════════════════════════════════════════════════════
   SUB-PAGE SYSTEM — Product / Solutions / About / Blog
   ════════════════════════════════════════════════════════════════ */

/* Sub-page wrapper */
.ov-sub-page {
  min-height: 100vh;
  background: #07070A;
  color: #fff;
  font-family: 'Geist', sans-serif;
  overflow-y: auto;
}

/* ── Sub-page nav ─────────────────────────────────────────────── */
.ov-sub-nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(7,7,10,.88);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.ov-sub-nav-inner {
  max-width: 1100px; margin: 0 auto;
  padding: 0 24px; height: 64px;
  display: flex; align-items: center; position: relative;
}
.ov-sub-nav .lp-logo { flex-shrink: 0; }
.ov-sub-nav-links {
  position: absolute; left: 50%; transform: translateX(-50%);
  display: flex; gap: 4px;
}
.ov-sub-nav-link {
  padding: 6px 14px; border-radius: 8px;
  font-size: 14px; font-weight: 500;
  color: rgba(255,255,255,.52); text-decoration: none;
  transition: color .18s, background .18s;
}
.ov-sub-nav-link:hover { color: rgba(255,255,255,.88); background: rgba(255,255,255,.06); }
.ov-sub-nav-active { color: rgba(255,255,255,.9) !important; background: rgba(255,255,255,.07) !important; }
.ov-sub-nav-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }

/* ── Hero ─────────────────────────────────────────────────────── */
.ov-sp-hero {
  position: relative;
  padding: 120px 24px 96px;
  text-align: center;
  border-bottom: 1px solid rgba(255,255,255,.06);
  overflow: hidden;
}
.ov-sp-hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 0%, color-mix(in srgb, var(--green) 5%, transparent) 0%, transparent 70%);
  pointer-events: none;
}
.ov-sp-hero-inner { position: relative; z-index: 1; max-width: 720px; margin: 0 auto; }
.ov-sp-h1 {
  font-size: clamp(36px, 5.5vw, 68px);
  font-weight: 700; line-height: 1.08;
  letter-spacing: -.03em; color: rgba(255,255,255,.95);
  margin: 16px 0 22px;
}
.ov-sp-hero-sub {
  font-size: 17px; line-height: 1.72;
  color: rgba(255,255,255,.48);
  max-width: 560px; margin: 0 auto 40px;
}

/* ── Sections ─────────────────────────────────────────────────── */
.ov-sp-section { padding: 96px 24px; }
.ov-sp-alt {
  background: rgba(255,255,255,.012);
  border-top: 1px solid rgba(255,255,255,.05);
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.ov-sp-section-inner { max-width: 900px; margin: 0 auto; }

.ov-sp-tag {
  display: inline-block;
  font-size: 10px; font-weight: 800; letter-spacing: .14em;
  text-transform: uppercase; color: color-mix(in srgb, var(--green) 65%, transparent);
  background: color-mix(in srgb, var(--green) 7%, transparent); border: 1px solid color-mix(in srgb, var(--green) 15%, transparent);
  padding: 4px 10px; border-radius: 100px; margin-bottom: 18px;
}
.ov-sp-h2 {
  font-size: clamp(26px, 3.8vw, 46px);
  font-weight: 700; letter-spacing: -.025em; line-height: 1.12;
  color: rgba(255,255,255,.92); margin-bottom: 18px;
}
.ov-sp-sub {
  font-size: 16px; line-height: 1.75;
  color: rgba(255,255,255,.46);
  max-width: 640px; margin-bottom: 52px;
}

/* ── Feature list ─────────────────────────────────────────────── */
.ov-sp-feat-list { display: flex; flex-direction: column; gap: 14px; }
.ov-sp-feat {
  display: flex; gap: 18px; align-items: flex-start;
  padding: 22px 26px;
  border: 1px solid rgba(255,255,255,.07); border-radius: 14px;
  background: rgba(255,255,255,.025);
  transition: border-color .2s, transform .25s cubic-bezier(.22,1,.36,1);
}
.ov-sp-feat:hover { border-color: color-mix(in srgb, var(--green) 16%, transparent); transform: translateX(4px); }
.ov-sp-feat-icon { font-size: 22px; flex-shrink: 0; margin-top: 2px; }
.ov-sp-feat-name { font-size: 15px; font-weight: 600; color: rgba(255,255,255,.88); margin-bottom: 6px; }
.ov-sp-feat-desc { font-size: 13.5px; line-height: 1.65; color: rgba(255,255,255,.44); }

/* ── Audience cards (Solutions) ───────────────────────────────── */
.ov-sp-audience-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px;
}
.ov-sp-audience-card {
  padding: 32px; border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--green) 12%, transparent);
  background: color-mix(in srgb, var(--green) 3%, transparent);
  transition: border-color .2s, background .2s, transform .25s cubic-bezier(.22,1,.36,1), box-shadow .2s;
}
.ov-sp-audience-card:hover {
  border-color: color-mix(in srgb, var(--green) 28%, transparent);
  background: color-mix(in srgb, var(--green) 5.5%, transparent);
  transform: translateY(-3px);
  box-shadow: 0 20px 52px rgba(0,0,0,.28), 0 0 0 0 color-mix(in srgb, var(--green) 4%, transparent);
}
.ov-sp-audience-icon { font-size: 30px; margin-bottom: 16px; }
.ov-sp-audience-title { font-size: 19px; font-weight: 700; color: rgba(255,255,255,.92); margin-bottom: 10px; }
.ov-sp-audience-desc { font-size: 14px; line-height: 1.7; color: rgba(255,255,255,.44); margin-bottom: 18px; }
.ov-sp-audience-list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 9px; }
.ov-sp-audience-list li {
  font-size: 13.5px; color: rgba(255,255,255,.54);
  display: flex; gap: 9px; align-items: flex-start;
}
.ov-sp-audience-list li::before {
  content: '✓'; color: var(--green); flex-shrink: 0; font-weight: 700;
  font-size: 11px; margin-top: 2px;
}

/* ── Brief demo (Product page) ────────────────────────────────── */
.ov-sp-brief-demo {
  border: 1px solid color-mix(in srgb, var(--green) 16%, transparent); border-radius: 16px;
  background: rgba(255,255,255,.025); overflow: hidden;
}
.ov-sp-brief-hdr {
  display: flex; align-items: center; gap: 14px; padding: 18px 26px;
  border-bottom: 1px solid rgba(255,255,255,.07);
  background: color-mix(in srgb, var(--green) 2.5%, transparent);
}
.ov-sp-brief-badge {
  font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase;
  color: var(--green); background: color-mix(in srgb, var(--green) 10%, transparent); border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  padding: 3px 10px; border-radius: 100px;
}
.ov-sp-brief-date { font-size: 12px; color: rgba(255,255,255,.35); }
.ov-sp-brief-body { padding: 22px 26px; font-size: 14px; line-height: 1.75; color: rgba(255,255,255,.52); }
.ov-sp-brief-body strong { color: rgba(255,255,255,.88); font-weight: 600; }
.ov-sp-brief-actions { padding: 0 26px 20px; display: flex; flex-direction: column; gap: 8px; }
.ov-sp-brief-action {
  display: flex; align-items: center; gap: 12px;
  font-size: 13px; color: rgba(255,255,255,.5);
  padding: 10px 14px; border-radius: 9px;
  background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.07);
}

/* ── Dashboard pills ──────────────────────────────────────────── */
.ov-sp-dp-row { display: flex; flex-wrap: wrap; gap: 10px; }
.ov-sp-dp {
  display: flex; align-items: center; gap: 8px; padding: 10px 18px;
  border-radius: 100px; background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.1);
  font-size: 14px; font-weight: 500; color: rgba(255,255,255,.65);
}
.ov-sp-dp-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.ov-sp-dp-g { background: #FBBC05; }
.ov-sp-dp-t { background: #EE1D52; }
.ov-sp-dp-m { background: #0866FF; }
.ov-sp-dp-ai {
  background: color-mix(in srgb, var(--green) 6%, transparent); border-color: color-mix(in srgb, var(--green) 20%, transparent); color: color-mix(in srgb, var(--green) 80%, transparent);
}

/* ── CTA section ──────────────────────────────────────────────── */
.ov-sp-cta {
  position: relative; padding: 100px 24px; text-align: center;
  overflow: hidden; border-top: 1px solid rgba(255,255,255,.06);
}
.ov-sp-cta::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 70% 50% at 50% 100%, color-mix(in srgb, var(--green) 4%, transparent) 0%, transparent 70%);
  pointer-events: none;
}
.ov-sp-cta-inner { position: relative; z-index: 1; max-width: 580px; margin: 0 auto; }
.ov-sp-cta-h {
  font-size: clamp(28px, 4.5vw, 52px); font-weight: 700; letter-spacing: -.025em;
  color: rgba(255,255,255,.93); margin-bottom: 18px; line-height: 1.12;
}
.ov-sp-cta-sub { font-size: 16px; color: rgba(255,255,255,.44); margin-bottom: 36px; line-height: 1.7; }

/* ── Sub-page footer ──────────────────────────────────────────── */
.ov-sub-footer { padding: 28px 24px; border-top: 1px solid rgba(255,255,255,.06); }
.ov-sub-footer-inner {
  max-width: 1100px; margin: 0 auto;
  font-size: 12px; color: rgba(255,255,255,.28); text-align: center;
}

/* ── About page ───────────────────────────────────────────────── */
.ov-about-problem-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 48px;
}
.ov-about-prob-card {
  padding: 28px; border-radius: 14px;
  border: 1px solid rgba(255,80,80,.1); background: rgba(255,50,50,.018);
  transition: border-color .2s;
}
.ov-about-prob-card:hover { border-color: rgba(255,80,80,.2); }
.ov-about-prob-icon { font-size: 26px; margin-bottom: 14px; }
.ov-about-prob-title { font-size: 15px; font-weight: 600; color: rgba(255,255,255,.8); margin-bottom: 8px; }
.ov-about-prob-desc { font-size: 13px; line-height: 1.65; color: rgba(255,255,255,.42); }

.ov-about-values-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; margin-top: 0; }
.ov-about-value-card {
  padding: 28px; border-radius: 14px;
  border: 1px solid rgba(255,255,255,.07); background: rgba(255,255,255,.025);
}
.ov-about-value-num {
  font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 50%, transparent); margin-bottom: 12px;
}
.ov-about-value-title { font-size: 17px; font-weight: 700; color: rgba(255,255,255,.88); margin-bottom: 10px; }
.ov-about-value-desc { font-size: 14px; line-height: 1.7; color: rgba(255,255,255,.44); }

/* ── Our Story two-column layout ───────────────────────────── */
.ov-about-story-grid {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 80px;
  align-items: center;
  margin-top: 16px;
}
.ov-about-story-img-wrap { position: relative; }
.ov-about-story-logo-display {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 72px 48px;
}
.ov-about-story-logo {
  width: 100%;
  max-width: 240px;
  height: auto;
  display: block;
  opacity: .92;
  filter: brightness(1.05);
}
.ov-about-story-text { padding-top: 8px; }
.ov-about-story-body p {
  font-size: 15px;
  line-height: 1.8;
  color: rgba(255,255,255,.52);
  margin: 0 0 18px;
}
.ov-about-story-body p:last-child { margin-bottom: 0; }

/* ── Centered about sections (Mission, Vision, Team) ────────── */
.ov-about-centered { text-align: center; }
.ov-about-centered .ov-sp-sub {
  margin-left: auto;
  margin-right: auto;
}
.ov-about-centered .ov-about-values-grid { text-align: left; }
.ov-about-centered .ov-sp-feat-list { text-align: left; }

/* ── Team section ───────────────────────────────────────────── */
.ov-about-team { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 0; }
.ov-about-team-card {
  text-align: center; padding: 36px 28px; border-radius: 16px;
  border: 1px solid rgba(255,255,255,.07); background: rgba(255,255,255,.02);
  transition: border-color .2s, transform .25s;
}
.ov-about-team-card:hover { border-color: color-mix(in srgb, var(--green) 14%, transparent); transform: translateY(-3px); }
.ov-about-founder-photo-wrap {
  width: 120px; height: 120px; border-radius: 50%;
  overflow: hidden;
  margin: 0 auto 22px;
  border: 1px solid rgba(255,255,255,.14);
}
.ov-about-founder-photo {
  width: 100%; height: 100%;
  object-fit: cover;
  object-position: center top;
  display: block;
}
.ov-about-team-name { font-size: 17px; font-weight: 600; color: rgba(255,255,255,.88); margin-bottom: 5px; }
.ov-about-team-role { font-size: 13px; color: color-mix(in srgb, var(--green) 60%, transparent); margin-bottom: 14px; font-weight: 500; }
.ov-about-team-bio { font-size: 13px; line-height: 1.65; color: rgba(255,255,255,.38); }

@media (max-width: 768px) {
  .ov-about-story-grid { grid-template-columns: 1fr; gap: 40px; }
  .ov-about-story-logo-display { padding: 40px 32px; }
}

/* ── Blog page ────────────────────────────────────────────────── */
.ov-blog-hero { padding: 96px 24px 72px; text-align: center; border-bottom: 1px solid rgba(255,255,255,.06); }
.ov-blog-search-wrap { margin: 32px auto 0; max-width: 440px; position: relative; }
.ov-blog-search-input {
  width: 100%; padding: 13px 20px 13px 44px; border-radius: 100px;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1);
  color: rgba(255,255,255,.8); font-size: 14px; font-family: 'Geist',sans-serif;
  box-sizing: border-box; outline: none; transition: border-color .2s;
}
.ov-blog-search-input:focus { border-color: color-mix(in srgb, var(--green) 30%, transparent); }
.ov-blog-search-input::placeholder { color: rgba(255,255,255,.3); }
.ov-blog-search-icon {
  position: absolute; left: 16px; top: 50%; transform: translateY(-50%);
  color: rgba(255,255,255,.3); font-size: 16px; pointer-events: none;
}

.ov-blog-cats {
  display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; margin: 0 auto 0;
  max-width: 880px; padding: 28px 24px 0;
}
.ov-blog-cat-btn {
  padding: 7px 16px; border-radius: 100px;
  font-size: 13px; font-weight: 500;
  border: 1px solid rgba(255,255,255,.1);
  background: transparent; color: rgba(255,255,255,.5);
  cursor: pointer; transition: all .2s; font-family: 'Geist',sans-serif;
}
.ov-blog-cat-btn:hover,
.ov-blog-cat-btn.ov-cat-active {
  background: color-mix(in srgb, var(--green) 8%, transparent);
  border-color: color-mix(in srgb, var(--green) 25%, transparent);
  color: color-mix(in srgb, var(--green) 85%, transparent);
}

.ov-blog-featured { max-width: 1080px; margin: 0 auto; padding: 40px 24px 0; }
.ov-blog-featured-inner {
  border: 1px solid color-mix(in srgb, var(--green) 12%, transparent); border-radius: 20px;
  overflow: hidden; background: color-mix(in srgb, var(--green) 1.8%, transparent);
  display: grid; grid-template-columns: 1fr 1.2fr;
  transition: border-color .2s, box-shadow .2s; cursor: pointer;
}
.ov-blog-featured-inner:hover {
  border-color: color-mix(in srgb, var(--green) 25%, transparent);
  box-shadow: 0 24px 64px rgba(0,0,0,.3);
}
.ov-blog-feat-thumb {
  background: linear-gradient(135deg, color-mix(in srgb, var(--green) 6%, transparent) 0%, rgba(7,7,10,0) 100%);
  border-right: 1px solid rgba(255,255,255,.06);
  display: flex; align-items: center; justify-content: center;
  font-size: 72px; min-height: 260px;
}
.ov-blog-feat-body { padding: 40px; }
.ov-blog-feat-label {
  font-size: 10px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase;
  color: var(--green); margin-bottom: 14px;
}
.ov-blog-feat-title {
  font-size: clamp(20px, 2.8vw, 30px); font-weight: 700;
  color: rgba(255,255,255,.92); line-height: 1.25; margin-bottom: 14px;
}
.ov-blog-feat-excerpt { font-size: 15px; line-height: 1.72; color: rgba(255,255,255,.44); margin-bottom: 26px; }
.ov-blog-read-more {
  font-size: 13px; font-weight: 600; color: var(--green); text-decoration: none;
  display: inline-flex; align-items: center; gap: 6px;
  transition: gap .18s ease;
}
.ov-blog-read-more:hover { gap: 10px; }
.ov-blog-feat-meta { font-size: 12px; color: rgba(255,255,255,.28); margin-top: 16px; }

.ov-blog-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px;
  max-width: 1080px; margin: 40px auto 0; padding: 0 24px 80px;
}
.ov-blog-card {
  border: 1px solid rgba(255,255,255,.07); border-radius: 16px;
  background: rgba(255,255,255,.025); overflow: hidden;
  transition: border-color .2s, transform .25s cubic-bezier(.22,1,.36,1), box-shadow .2s;
  cursor: pointer; display: flex; flex-direction: column;
}
.ov-blog-card:hover {
  border-color: color-mix(in srgb, var(--green) 15%, transparent);
  transform: translateY(-4px);
  box-shadow: 0 20px 52px rgba(0,0,0,.28);
}
.ov-blog-card-thumb {
  height: 148px;
  background: linear-gradient(135deg, rgba(255,255,255,.03) 0%, color-mix(in srgb, var(--green) 3%, transparent) 100%);
  border-bottom: 1px solid rgba(255,255,255,.06);
  display: flex; align-items: center; justify-content: center; font-size: 36px;
}
.ov-blog-card-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.ov-blog-card-cat {
  font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: color-mix(in srgb, var(--green) 60%, transparent); margin-bottom: 10px;
}
.ov-blog-card-title { font-size: 16px; font-weight: 600; color: rgba(255,255,255,.88); line-height: 1.4; margin-bottom: 10px; flex: 1; }
.ov-blog-card-excerpt { font-size: 13px; line-height: 1.6; color: rgba(255,255,255,.4); margin-bottom: 16px; }
.ov-blog-card-meta { font-size: 11px; color: rgba(255,255,255,.28); display: flex; gap: 10px; }

/* ── Section alignment: 01 heading ───────────────────────────── */
#ov-platform .ov-section-h,
#ov-platform .ov-section-sub { text-align: center; }

/* Section 02 comparison heading center (reinforced) */
#ov-compare .ov-section-h { text-align: center; }

/* ── Responsive ───────────────────────────────────────────────── */
@media (max-width: 900px) {
  .ov-sp-audience-grid { grid-template-columns: 1fr; }
  .ov-about-problem-grid { grid-template-columns: 1fr; }
  .ov-about-team { grid-template-columns: repeat(2, 1fr); }
  .ov-about-values-grid { grid-template-columns: 1fr; }
  .ov-blog-grid { grid-template-columns: repeat(2, 1fr); }
  .ov-blog-featured-inner { grid-template-columns: 1fr; }
  .ov-blog-feat-thumb { min-height: 160px; }
}
@media (max-width: 600px) {
  .ov-sub-nav-links { display: none; }
  .ov-sp-hero { padding: 80px 20px 60px; }
  .ov-sp-section { padding: 60px 20px; }
  .ov-blog-grid { grid-template-columns: 1fr; }
  .ov-about-team { grid-template-columns: 1fr; }
}

/* ═══════════════════════════════════════════════════════
   HOMEPAGE REDESIGN — new section styles
   ═══════════════════════════════════════════════════════ */

/* ── Colored fragment variants ── */
.ov-frag-google { background: rgba(251,188,5,.16) !important; border-color: rgba(251,188,5,.22) !important; }
.ov-frag-meta   { background: rgba(8,102,255,.16) !important; border-color: rgba(8,102,255,.22) !important; }
.ov-frag-tiktok { background: rgba(238,29,82,.16) !important; border-color: rgba(238,29,82,.22) !important; }

/* ── 02 THE PROBLEM ── */
#ov-problem { padding: 100px 24px; }
.ov-problem-inner { max-width: 1100px; margin: 0 auto; }
.ov-prob-diagram {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 32px;
  align-items: center;
  margin-top: 60px;
}
.ov-prob-sources { display: flex; flex-direction: column; gap: 14px; }
.ov-prob-source {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 12px;
  overflow: hidden;
  transition: border-color .3s;
}
.ov-prob-source:hover { border-color: rgba(255,255,255,.13); }
.ov-prob-src-bar { height: 3px; }
.ov-prob-src-bar.ov-prob-src-google { background: #FBBC05; }
.ov-prob-src-bar.ov-prob-src-meta   { background: #0866FF; }
.ov-prob-src-bar.ov-prob-src-tiktok { background: #EE1D52; }
.ov-prob-src-body { padding: 14px 18px; }
.ov-prob-src-name {
  display: flex; align-items: center; gap: 8px;
  font-size: 13px; font-weight: 600; color: rgba(255,255,255,.7);
  margin-bottom: 10px;
}
.ov-prob-src-row {
  display: flex; justify-content: space-between;
  font-size: 12px; color: rgba(255,255,255,.35); padding: 2px 0;
}
.ov-prob-src-row span:last-child { color: rgba(255,255,255,.6); font-weight: 500; }
.ov-prob-arrow {
  display: flex; flex-direction: column; align-items: center; gap: 10px;
}
.ov-prob-arrow-line {
  width: 1px; height: 36px;
  background: linear-gradient(to bottom, transparent, color-mix(in srgb, var(--green) 30%, transparent), transparent);
}
.ov-prob-arrow-label {
  font-size: 11px; font-weight: 700; color: color-mix(in srgb, var(--green) 60%, transparent);
  text-transform: uppercase; letter-spacing: .1em; white-space: nowrap;
  writing-mode: vertical-rl; text-orientation: mixed;
}
.ov-prob-unified {
  background: rgba(255,255,255,.03);
  border: 1px solid color-mix(in srgb, var(--green) 15%, transparent);
  border-radius: 16px; overflow: hidden;
}

/* ── 03 DASHBOARD MOCKUP ── */
#ov-dashboard { padding: 100px 24px; background: rgba(255,255,255,.012); }
.ov-dash-inner { max-width: 1100px; margin: 0 auto; }
.ov-dash-mockup {
  margin-top: 52px;
  background: #0a0a0e;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 16px; overflow: hidden;
  box-shadow: 0 40px 100px rgba(0,0,0,.7), 0 0 0 1px rgba(255,255,255,.04) inset;
}
.ov-dash-topbar {
  display: flex; justify-content: space-between; align-items: center;
  padding: 11px 20px;
  background: rgba(255,255,255,.04);
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.ov-dash-topbar-left { display: flex; align-items: center; gap: 14px; }
.ov-dash-win-dots { display: flex; gap: 6px; }
.ov-dash-win-dots span { width: 10px; height: 10px; border-radius: 50%; background: rgba(255,255,255,.1); }
.ov-dash-title-bar { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.45); letter-spacing: .04em; }
.ov-dash-topbar-right { display: flex; align-items: center; gap: 16px; }
.ov-dash-range { font-size: 12px; color: rgba(255,255,255,.3); }
.ov-dash-live { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--green) 75%, transparent); }
.ov-dash-live-dot {
  width: 7px; height: 7px; border-radius: 50%; background: var(--green);
  animation: ov-live-pulse 2s ease-in-out infinite;
}
@keyframes ov-live-pulse {
  0%,100% { opacity: 1; box-shadow: 0 0 0 0 color-mix(in srgb, var(--green) 40%, transparent); }
  50% { opacity: .7; box-shadow: 0 0 0 4px color-mix(in srgb, var(--green) 0%, transparent); }
}
.ov-dash-kpi-row {
  display: grid; grid-template-columns: repeat(5,1fr);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.ov-dash-kpi {
  padding: 18px 20px;
  border-right: 1px solid rgba(255,255,255,.05);
}
.ov-dash-kpi:last-child { border-right: none; }
.ov-dash-kpi-lbl { font-size: 11px; color: rgba(255,255,255,.28); font-weight: 600; letter-spacing: .07em; text-transform: uppercase; margin-bottom: 6px; }
.ov-dash-kpi-val { font-size: 22px; font-weight: 700; color: rgba(255,255,255,.92); margin-bottom: 4px; letter-spacing: -.5px; }
.ov-dash-kpi-delta { font-size: 11px; font-weight: 500; }
.ov-delta-up   { color: color-mix(in srgb, var(--green) 80%, transparent); }
.ov-delta-down { color: rgba(255,90,90,.8); }
.ov-delta-neutral { color: rgba(255,255,255,.28); }
.ov-dash-body { display: grid; grid-template-columns: 1fr 260px; border-bottom: 1px solid rgba(255,255,255,.06); }
.ov-dash-chart-area { padding: 20px; border-right: 1px solid rgba(255,255,255,.06); }
.ov-dash-chart-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
.ov-dash-chart-title { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.5); }
.ov-dash-chart-legend { display: flex; gap: 16px; font-size: 11px; color: rgba(255,255,255,.38); }
.ov-dash-chart-legend span { display: flex; align-items: center; gap: 5px; }
.ov-dash-leg-dot { width: 8px; height: 8px; border-radius: 2px; display: inline-block; }
.ov-dash-chart { display: flex; align-items: flex-end; gap: 10px; height: 120px; }
.ov-dash-bar-grp { display: flex; flex-direction: column; align-items: center; gap: 5px; flex: 1; }
.ov-dash-bar-stack {
  display: flex; flex-direction: column-reverse; justify-content: flex-start;
  width: 100%; height: 100px; border-radius: 4px 4px 0 0; overflow: hidden;
  gap: 1px;
}
.ov-dash-bar-seg { width: 100%; transition: filter .2s; }
.ov-seg-google { background: rgba(251,188,5,.65); }
.ov-seg-meta   { background: rgba(8,102,255,.6); }
.ov-seg-tiktok { background: rgba(238,29,82,.55); }
.ov-dash-bar-lbl { font-size: 10px; color: rgba(255,255,255,.2); }
.ov-dash-plat-breakdown { padding: 20px; }
.ov-dash-pb-head { font-size: 11px; font-weight: 700; color: rgba(255,255,255,.3); text-transform: uppercase; letter-spacing: .07em; margin-bottom: 18px; }
.ov-dash-pb-row { margin-bottom: 16px; }
.ov-dash-pb-name { display: flex; align-items: center; gap: 7px; font-size: 12px; color: rgba(255,255,255,.6); margin-bottom: 6px; }
.ov-dash-pb-dot { width: 8px; height: 8px; border-radius: 2px; display: inline-block; flex-shrink: 0; }
.ov-dash-pb-bar-wrap { height: 4px; background: rgba(255,255,255,.07); border-radius: 2px; margin-bottom: 5px; }
.ov-dash-pb-bar { height: 100%; border-radius: 2px; }
.ov-dash-pb-vals { display: flex; justify-content: space-between; font-size: 11px; color: rgba(255,255,255,.32); }
.ov-dash-table { }
.ov-dash-table-hdr {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr 1fr;
  padding: 10px 20px;
  background: rgba(255,255,255,.025);
  font-size: 11px; font-weight: 700; color: rgba(255,255,255,.28);
  text-transform: uppercase; letter-spacing: .06em;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.ov-dash-table-row {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr 1fr;
  padding: 12px 20px;
  font-size: 13px; color: rgba(255,255,255,.6);
  border-bottom: 1px solid rgba(255,255,255,.04);
  align-items: center; transition: background .15s;
}
.ov-dash-table-row:last-child { border-bottom: none; }
.ov-dash-table-row:hover { background: rgba(255,255,255,.02); }
.ov-dash-camp-name { font-weight: 500; color: rgba(255,255,255,.82); }
.ov-dash-tag {
  display: inline-block; font-size: 10px; font-weight: 700;
  padding: 2px 7px; border-radius: 4px; letter-spacing: .04em;
}
.ov-tag-google { background: rgba(251,188,5,.15); color: #fbbc05; }
.ov-tag-meta   { background: rgba(8,102,255,.15); color: #6aa3ff; }
.ov-tag-tiktok { background: rgba(238,29,82,.15); color: #f0617b; }
.ov-dash-status { display: inline-block; font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 4px; }
.ov-status-on   { background: color-mix(in srgb, var(--green) 10%, transparent); color: color-mix(in srgb, var(--green) 85%, transparent); }
.ov-status-warn { background: rgba(255,180,0,.1); color: rgba(255,180,0,.85); }
.ov-red { color: rgba(255,100,100,.9) !important; }

/* ── 04 AI RECOMMENDATIONS ── */
#ov-ai-recs { padding: 100px 24px; }
.ov-ai-inner { max-width: 1100px; margin: 0 auto; }
.ov-ai-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; margin-top: 52px; }
.ov-ai-card {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 16px; padding: 24px;
  transition: border-color .3s, transform .3s cubic-bezier(.22,1,.36,1), box-shadow .3s;
}
.ov-ai-card:hover { border-color: color-mix(in srgb, var(--green) 15%, transparent); transform: translateY(-4px); box-shadow: 0 20px 50px rgba(0,0,0,.35); }
.ov-ai-card-highlight {
  border-color: color-mix(in srgb, var(--green) 22%, transparent);
  background: linear-gradient(145deg, color-mix(in srgb, var(--green) 5%, transparent) 0%, transparent 55%);
}
.ov-ai-card-highlight:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.ov-ai-card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; margin-bottom: 16px; }
.ov-ai-alert { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; padding: 5px 10px; border-radius: 6px; }
.ov-ai-alert-warn { background: rgba(255,80,80,.1); color: rgba(255,110,110,.95); }
.ov-ai-alert-up   { background: color-mix(in srgb, var(--green) 10%, transparent); color: color-mix(in srgb, var(--green) 95%, transparent); }
.ov-ai-alert-info { background: rgba(100,160,255,.1); color: rgba(130,185,255,.95); }
.ov-ai-alert-icon { font-size: 9px; }
.ov-ai-platform-tag { font-size: 10px; font-weight: 700; padding: 3px 8px; border-radius: 4px; white-space: nowrap; letter-spacing: .04em; flex-shrink: 0; }
.ov-ai-metrics { margin-bottom: 18px; }
.ov-ai-metric { display: flex; justify-content: space-between; padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,.05); font-size: 12px; }
.ov-ai-metric:last-child { border-bottom: none; }
.ov-ai-metric span:first-child { color: rgba(255,255,255,.35); }
.ov-ai-metric span:last-child { color: rgba(255,255,255,.75); font-weight: 500; }
.ov-ai-rec { background: rgba(255,255,255,.04); border-radius: 10px; padding: 16px; }
.ov-ai-rec-label { display: flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 700; color: color-mix(in srgb, var(--green) 75%, transparent); text-transform: uppercase; letter-spacing: .09em; margin-bottom: 9px; }
.ov-ai-rec-pip { width: 6px; height: 6px; border-radius: 50%; background: var(--green); display: inline-block; flex-shrink: 0; }
.ov-ai-rec-text { font-size: 13px; line-height: 1.62; color: rgba(255,255,255,.58); margin-bottom: 14px; }
.ov-ai-rec-action {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--green) 90%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 22%, transparent); border-radius: 6px;
  padding: 5px 12px; cursor: default;
  transition: background .2s, border-color .2s;
}
.ov-ai-rec-action::after { content: "→"; font-size: 13px; }
.ov-ai-card:hover .ov-ai-rec-action { background: color-mix(in srgb, var(--green) 6%, transparent); border-color: color-mix(in srgb, var(--green) 35%, transparent); }

/* ── 05 INTEGRATIONS ── */
#ov-integrations { padding: 100px 24px; background: rgba(255,255,255,.012); }
.ov-int-inner { max-width: 1100px; margin: 0 auto; }
.ov-int-cards-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; margin-top: 52px; }
.ov-int-card-new {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 14px; padding: 24px;
  transition: border-color .3s, transform .3s cubic-bezier(.22,1,.36,1);
}
.ov-int-live:hover { border-color: color-mix(in srgb, var(--green) 20%, transparent); transform: translateY(-3px); }
.ov-int-soon { opacity: .5; pointer-events: none; }
.ov-int-card-dot { width: 36px; height: 36px; border-radius: 10px; margin-bottom: 16px; }
.ov-int-card-logo { width: 44px; height: 36px; margin-bottom: 16px; display: flex; align-items: center; }
.ov-int-card-new-name { font-size: 16px; font-weight: 700; color: rgba(255,255,255,.88); margin-bottom: 5px; }
.ov-int-card-new-status { font-size: 12px; font-weight: 600; margin-bottom: 10px; }
.ov-int-status-live { color: color-mix(in srgb, var(--green) 80%, transparent); }
.ov-int-status-soon { color: rgba(255,255,255,.28); }
.ov-int-card-new-desc { font-size: 13px; line-height: 1.55; color: rgba(255,255,255,.36); }
.ov-int-note { margin-top: 28px; font-size: 13px; color: rgba(255,255,255,.25); text-align: center; }

/* ── 06 CAMPAIGN EXAMPLES ── */
#ov-campaigns { padding: 100px 24px; }
.ov-camp-inner { max-width: 1100px; margin: 0 auto; }
.ov-camp-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; margin-top: 52px; }
.ov-camp-card {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 16px; overflow: hidden;
  transition: border-color .3s, transform .3s cubic-bezier(.22,1,.36,1), box-shadow .3s;
}
.ov-camp-card:hover { border-color: rgba(255,255,255,.13); transform: translateY(-4px); box-shadow: 0 20px 50px rgba(0,0,0,.35); }
.ov-camp-card-head { padding: 20px 20px 14px; }
.ov-camp-plat-tag {
  display: inline-block; font-size: 10px; font-weight: 700;
  padding: 2px 8px; border-radius: 4px; letter-spacing: .04em; margin-bottom: 8px;
}
.ov-camp-name { font-size: 15px; font-weight: 700; color: rgba(255,255,255,.85); }
.ov-camp-metrics { display: grid; grid-template-columns: repeat(3,1fr); border-top: 1px solid rgba(255,255,255,.06); border-bottom: 1px solid rgba(255,255,255,.06); }
.ov-camp-metric { padding: 14px 14px; text-align: center; }
.ov-camp-metric:not(:last-child) { border-right: 1px solid rgba(255,255,255,.06); }
.ov-camp-metric-val { font-size: 18px; font-weight: 700; color: rgba(255,255,255,.88); margin-bottom: 3px; }
.ov-camp-metric-lbl { font-size: 10px; color: rgba(255,255,255,.28); font-weight: 600; text-transform: uppercase; letter-spacing: .07em; }
.ov-camp-trend { padding: 14px 20px 8px; }
.ov-camp-trend-bars { display: flex; align-items: flex-end; gap: 3px; height: 36px; }
.ov-camp-trend-bars > div { flex: 1; background: color-mix(in srgb, var(--green) 16%, transparent); border-radius: 2px 2px 0 0; transition: background .2s; }
.ov-camp-card:hover .ov-camp-trend-bars > div { background: color-mix(in srgb, var(--green) 28%, transparent); }
.ov-camp-insight { padding: 10px 20px 20px; }
.ov-camp-insight-label { display: flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 700; color: color-mix(in srgb, var(--green) 65%, transparent); text-transform: uppercase; letter-spacing: .09em; margin-bottom: 7px; }
.ov-camp-insight-text { font-size: 13px; line-height: 1.62; color: rgba(255,255,255,.5); }

/* ── 07 COMPARISON TABLE ── */
#ov-compare { padding: 100px 24px; background: rgba(255,255,255,.012); }
.ov-compare-inner { max-width: 1100px; margin: 0 auto; }
.ov-feat-table {
  max-width: 700px; margin: 52px auto 0;
  border: 1px solid rgba(255,255,255,.09); border-radius: 16px; overflow: hidden;
}
.ov-feat-table-head {
  display: grid; grid-template-columns: 1fr 150px 150px;
  padding: 14px 24px;
  background: rgba(255,255,255,.05);
  font-size: 11px; font-weight: 700; color: rgba(255,255,255,.32);
  text-transform: uppercase; letter-spacing: .09em;
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.ov-feat-oriven-badge { font-size: 11px; font-weight: 800; color: color-mix(in srgb, var(--green) 95%, transparent); letter-spacing: .1em; }
.ov-feat-table-row {
  display: grid; grid-template-columns: 1fr 150px 150px;
  padding: 13px 24px;
  font-size: 14px; color: rgba(255,255,255,.55);
  border-bottom: 1px solid rgba(255,255,255,.05);
  align-items: center;
}
.ov-feat-table-row:last-child { border-bottom: none; }
.ov-feat-row-hi { background: color-mix(in srgb, var(--green) 2.5%, transparent); }
.ov-feat-table-row > div:first-child { font-weight: 500; color: rgba(255,255,255,.7); }
.ov-ft-cell { text-align: center; }
.ov-ft-chk { color: color-mix(in srgb, var(--green) 95%, transparent); font-size: 16px; font-weight: 700; }
.ov-ft-chk-gray { color: rgba(255,255,255,.3) !important; }
.ov-ft-x { color: rgba(255,80,80,.55); font-size: 16px; }

/* ── RESPONSIVE ── */
@media (max-width: 960px) {
  .ov-prob-diagram { grid-template-columns: 1fr; gap: 20px; }
  .ov-prob-arrow { flex-direction: row; }
  .ov-prob-arrow-line { width: 40px; height: 1px; background: linear-gradient(to right, transparent, color-mix(in srgb, var(--green) 30%, transparent), transparent); }
  .ov-prob-arrow-label { writing-mode: horizontal-tb; }
  .ov-dash-kpi-row { grid-template-columns: repeat(3,1fr); }
  .ov-dash-kpi:nth-child(4), .ov-dash-kpi:nth-child(5) { border-top: 1px solid rgba(255,255,255,.05); }
  .ov-dash-body { grid-template-columns: 1fr; }
  .ov-dash-plat-breakdown { border-top: 1px solid rgba(255,255,255,.06); }
  .ov-dash-table-hdr,
  .ov-dash-table-row { grid-template-columns: 2fr 1fr 1fr 1fr; }
  .ov-dash-table-hdr span:nth-child(5),
  .ov-dash-table-hdr span:nth-child(6),
  .ov-dash-table-row span:nth-child(5),
  .ov-dash-table-row span:nth-child(6) { display: none; }
  .ov-ai-grid { grid-template-columns: 1fr; }
  .ov-int-cards-grid { grid-template-columns: repeat(2,1fr); }
  .ov-camp-grid { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .ov-dash-kpi-row { grid-template-columns: repeat(2,1fr); }
  .ov-dash-kpi:nth-child(5) { display: none; }
  .ov-int-cards-grid { grid-template-columns: 1fr; }
  .ov-feat-table-head,
  .ov-feat-table-row { grid-template-columns: 1fr 90px 90px; padding: 12px 16px; font-size: 13px; }
}


/* ═══════════════════════════════════════════════════════
   HOMEPAGE REFINEMENTS
   ═══════════════════════════════════════════════════════ */

/* ── GLOBAL: Center all section labels, titles, subtitles ── */
.ov-section-label,
.ov-section-h,
.ov-section-sub {
  text-align: center !important;
}

