#ov-creative, #ov-compare, #ov-reviews, #pricing, #faq, #ov-final {
  background: transparent !important;
  border-top: none !important;
}

/* Remove ALL pseudo-element gradient overlays on all sections */
#ov-hero::before, #ov-hero::after,
#ov-problem::before, #ov-problem::after,
#ov-dashboard::before, #ov-dashboard::after,
#ov-ai-recs::before, #ov-ai-recs::after,
#ov-integrations::before, #ov-integrations::after,
#ov-creative::before, #ov-creative::after,
#ov-compare::before, #ov-compare::after,
#ov-reviews::before, #ov-reviews::after,
#pricing::before, #pricing::after,
#faq::before, #faq::after,
#ov-final::before, #ov-final::after {
  display: none !important;
}

/* Hide canvas particle system */
#ov-canvas { display: none !important; }

/* Hide scroll cue animated line */
.ov-scroll-cue { display: none !important; }

/* Hide fragment layers outside hero */
#ov-final .ov-frag-layer { display: none !important; }

/* Hide Section 11 decorative network */
.ov-final-network { display: none !important; }

/* Neutralise any green-tinted inner wrappers on homepage sections */
#ov-ai-recs .ov-section-label { color: color-mix(in srgb, var(--green) 35%, transparent) !important; }
#ov-ai-recs > * { background: transparent !important; }
#ov-creative > * { background: transparent !important; }

/* ═══════════════════════════════════════════════════════
   NAVIGATION DROPDOWNS
   ═══════════════════════════════════════════════════════ */

/* -- Dropdown container items -- */
.lp-nav-item { position: relative; display: flex; align-items: center; }

.lp-dd-trig {
  all: unset;
  display: flex; align-items: center; gap: 5px;
  font-size: 14px; font-weight: 500; color: rgba(255,255,255,.65);
  cursor: pointer; padding: 6px 2px;
  transition: color .15s;
  white-space: nowrap;
}
.lp-dd-trig:hover { color: rgba(255,255,255,.92); }
.lp-dd-chev {
  width: 10px; height: 6px; flex-shrink: 0;
  transition: transform .2s ease;
  color: rgba(255,255,255,.4);
}
.lp-dd-open .lp-dd-chev { transform: rotate(180deg); color: rgba(255,255,255,.7); }

/* -- Dropdown panel -- */
.lp-dropdown {
  position: absolute;
  top: calc(100% + 12px);
  left: 50%;
  transform: translateX(-50%) translateY(-6px);
  background: rgba(9, 9, 15, 0.98);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 16px;
  box-shadow: 0 24px 60px rgba(0,0,0,.6), 0 0 0 1px rgba(255,255,255,.05);
  backdrop-filter: blur(24px);
  z-index: 1200;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .18s ease, transform .18s ease, visibility .18s ease;
  white-space: nowrap;
}
.lp-dd-open > .lp-dropdown {
  opacity: 1;
  visibility: visible;
  pointer-events: all;
  transform: translateX(-50%) translateY(0);
}

/* -- Mega menu (Product) -- */
.lp-dd-mega {
  display: flex; flex-direction: row;
  min-width: 680px;
  padding: 32px 8px 28px;
  gap: 0;
  left: auto; right: auto;
  transform: translateX(-40%) translateY(-6px);
}
.lp-dd-open > .lp-dd-mega { transform: translateX(-40%) translateY(0); }

.lp-dd-col { flex: 1; padding: 18px 36px 0; }
.lp-dd-col + .lp-dd-col { border-left: 1px solid rgba(255,255,255,.07); }
.lp-dd-colhead {
  font-size: 10px; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: rgba(255,255,255,.3);
  margin-bottom: 24px; padding-bottom: 12px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}

/* -- Dropdown items -- */
.lp-dd-item {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 10px;
  text-decoration: none; color: rgba(255,255,255,.72);
  font-size: 13.5px; font-weight: 500;
  transition: background .14s, color .14s;
  cursor: pointer; margin-bottom: 2px;
}
.lp-dd-item:hover { background: rgba(255,255,255,.07); color: rgba(255,255,255,.95); }
.lp-dd-item-inner { display: flex; align-items: center; gap: 8px; }
.lp-dd-item-name { line-height: 1; }
.lp-dd-item-desc {
  display: block; font-size: 11px; color: rgba(255,255,255,.3);
  font-weight: 400; margin-top: 2px; line-height: 1.3;
}

.lp-dd-icon {
  width: 28px; height: 28px; border-radius: 7px;
  background: rgba(255,255,255,.06);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  border: 1px solid rgba(255,255,255,.08);
}
.lp-dd-icon svg { width: 15px; height: 15px; }

/* Live badge */
.lp-dd-badge {
  font-size: 9px; font-weight: 700; letter-spacing: .07em;
  padding: 2px 6px; border-radius: 4px;
  background: color-mix(in srgb, var(--green) 12%, transparent); color: color-mix(in srgb, var(--green) 80%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent); text-transform: uppercase;
  flex-shrink: 0;
}
.lp-dd-badge-soon {
  background: rgba(255,255,255,.05); color: rgba(255,255,255,.3);
  border-color: rgba(255,255,255,.08);
}

/* Soon column items */
.lp-dd-item-soon { color: rgba(255,255,255,.35); cursor: default; }
.lp-dd-item-soon:hover { background: transparent; color: rgba(255,255,255,.35); }
.lp-dd-icon-soon { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.05); }

/* -- Small dropdown (Solutions) -- */
.lp-dd-sm {
  min-width: 220px;
  padding: 10px 8px;
  left: 50%;
  transform: translateX(-50%) translateY(-6px);
}
.lp-dd-open > .lp-dd-sm { transform: translateX(-50%) translateY(0); }
.lp-dd-sm .lp-dd-item { font-size: 13px; padding: 8px 10px; }

/* -- Mobile menu dropdown items -- */
.lp-mm-item { }
.lp-mm-dd-trig {
  all: unset;
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; box-sizing: border-box;
  padding: 14px 0;
  font-size: 18px; font-weight: 600; color: rgba(255,255,255,.82);
  cursor: pointer; border-bottom: 1px solid rgba(255,255,255,.06);
}
.lp-mm-chev {
  font-size: 16px; color: rgba(255,255,255,.35);
  transition: transform .2s ease;
}
.lp-mm-item.lp-mm-open .lp-mm-chev { transform: rotate(90deg); }
.lp-mm-dd-items {
  display: none;
  padding: 8px 0 4px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.lp-mm-item.lp-mm-open .lp-mm-dd-items { display: block; }
.lp-mm-cat {
  font-size: 10px; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: rgba(255,255,255,.25);
  padding: 10px 0 6px;
}
.lp-mm-dd-link {
  display: block; padding: 9px 0;
  font-size: 15px; font-weight: 500; color: rgba(255,255,255,.6);
  text-decoration: none; transition: color .12s;
}
.lp-mm-dd-link:hover { color: rgba(255,255,255,.9); }

@media (max-width: 768px) {
  .lp-nav-item, .lp-dd-trig { display: none; }
}


/* nav dropdown trigger — match regular nav-link sizing */
.lp-nav-links .lp-dd-trig { padding: 7px 13px; border-radius: 8px; font-size: 13px; }
.lp-nav-links .lp-nav-item { gap: 0; }
@media (min-width: 769px) {
  .lp-nav-links .lp-nav-item,
  .lp-nav-links .lp-dd-trig { display: flex; }
}

/* ═══════════════════════════════════════════════════════
   NAV DROPDOWN v2 — hover fix + visual polish
   ═══════════════════════════════════════════════════════ */

/* ── Gap bridge: dropdown starts at top:100% so cursor never
   leaves .lp-has-dd bounds when moving from trigger to panel.
   Transparent padding-top creates the visual gap without a dead zone. ── */
.lp-dropdown {
  top: 100% !important;
  padding-top: 10px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* Visual card rendered via ::before so it sits below the transparent padding.
   Color matches the real Oriven app sidebar exactly (body.dark-mode .orv-sb,
   computed live as rgb(11,11,12) / #0B0B0C, border rgba(255,255,255,.06)) —
   opaque, no blue undertone, instead of the previous rgba(10,10,18,.97). */
.lp-dropdown::before {
  content: '';
  position: absolute;
  inset: 10px 0 0 0;   /* top matches padding-top */
  background: #0B0B0C;
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 16px;
  box-shadow:
    0 4px 16px rgba(0,0,0,.35),
    0 20px 56px rgba(0,0,0,.65),
    0 0 0 1px rgba(255,255,255,.04);
  pointer-events: none;
  z-index: -1;
}

/* Ensure dropdown content renders above ::before */
.lp-dropdown > * { position: relative; z-index: 1; }

/* ── 2-column mega ── */
.lp-dd-mega {
  min-width: 580px !important;
  padding-top: 10px !important;   /* matches lp-dropdown padding-top, visual gap */
  padding-bottom: 40px !important;
}

/* Tighten translate animation — shorter since gap is bridged */
.lp-dropdown      { transform: translateX(-50%) translateY(-5px) !important; }
.lp-dd-mega       { transform: translateX(-40%) translateY(-5px) !important; }
.lp-dd-sm         { transform: translateX(-50%) translateY(-5px) !important; }
.lp-dd-open > .lp-dropdown { transform: translateX(-50%) translateY(0) !important; }
.lp-dd-open > .lp-dd-mega  { transform: translateX(-40%) translateY(0) !important; }
.lp-dd-open > .lp-dd-sm    { transform: translateX(-50%) translateY(0) !important; }

/* Crisper transition */
.lp-dropdown {
  transition: opacity .16s cubic-bezier(.16,1,.3,1),
              transform .16s cubic-bezier(.16,1,.3,1),
              visibility .16s !important;
}

/* ── Item hover polish ── */
.lp-dd-item {
  cursor: pointer !important;
  transition: background .1s ease, color .1s ease !important;
  border-radius: 10px !important;
}
.lp-dd-item:hover {
  background: rgba(255,255,255,.07) !important;
  color: rgba(255,255,255,.96) !important;
}
.lp-dd-item:active { background: rgba(255,255,255,.1) !important; }

/* Icon scales slightly on hover */
.lp-dd-item:hover .lp-dd-icon {
  background: rgba(255,255,255,.09) !important;
  border-color: rgba(255,255,255,.14) !important;
}

/* ── Trigger hover polish ── */
.lp-dd-trig:hover .lp-dd-chev { color: rgba(255,255,255,.75) !important; }
.lp-dd-open .lp-dd-trig { color: rgba(255,255,255,.92) !important; }

/* ── Column separator spacing ── */
.lp-dd-col:first-child { border-left: none !important; }


/* ═══════════════════════════════════════════════════════
   REDUCED MOTION — one shared override for every [data-observe]
   scroll-reveal element (the whole landing page reuses this single
   IntersectionObserver-driven mechanism instead of per-section ones)
   ═══════════════════════════════════════════════════════ */
@media (prefers-reduced-motion: reduce) {
  [data-observe] {
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

