/* ═══════════════════════════════════════════════════════
   BLOG — SPACING & MODAL
   ═══════════════════════════════════════════════════════ */

/* Reduce gap between hero and article grid on the blog page only */
#view-blog .ov-sp-hero {
  padding-bottom: 0 !important;
  border-bottom: none !important;
}
#view-blog .ov-sp-section {
  padding-top: 48px !important;
}

/* ── Article modal ─────────────────────────────────────── */
.ov-blog-modal {
  position: fixed;
  inset: 0;
  z-index: 19999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  transition: opacity .22s ease, visibility .22s;
}
.ov-blog-modal.is-open {
  opacity: 1;
  pointer-events: all;
  visibility: visible;
}
.ov-blog-modal-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.72);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  cursor: pointer;
}
.ov-blog-modal-card {
  position: relative;
  z-index: 1;
  background: rgba(10,10,16,.98);
  border: 1px solid color-mix(in srgb, var(--green) 18%, transparent);
  border-radius: 20px;
  padding: 52px 52px 48px;
  max-width: 620px;
  width: 100%;
  max-height: 80vh;
  overflow-y: auto;
  transform: translateY(14px) scale(.98);
  transition: transform .24s cubic-bezier(.22,1,.36,1);
}
.ov-blog-modal.is-open .ov-blog-modal-card {
  transform: translateY(0) scale(1);
}
.ov-blog-modal-close {
  position: absolute;
  top: 18px;
  right: 18px;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: rgba(255,255,255,.55);
  transition: background .15s, color .15s, border-color .15s;
  padding: 0;
}
.ov-blog-modal-close:hover {
  background: rgba(255,255,255,.1);
  color: rgba(255,255,255,.9);
  border-color: rgba(255,255,255,.18);
}
.ov-blog-modal-title {
  font-size: 22px;
  font-weight: 700;
  color: rgba(255,255,255,.92);
  letter-spacing: -.02em;
  line-height: 1.25;
  margin-bottom: 28px;
  padding-right: 32px;
}
.ov-blog-modal-body p {
  font-size: 15px;
  line-height: 1.82;
  color: rgba(255,255,255,.52);
  margin: 0 0 18px;
}
.ov-blog-modal-body p:last-child { margin-bottom: 0; }
@media (max-width: 600px) {
  .ov-blog-modal-card { padding: 40px 28px 36px; border-radius: 16px; }
}

/* ═══════════════════════════════════════════════════════
   BLOG — ARTICLE CARDS
   ═══════════════════════════════════════════════════════ */

.ov-blog-art-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 48px;
  text-align: left;
}

.ov-blog-art-card {
  display: flex;
  flex-direction: column;
  background: color-mix(in srgb, var(--green) 3%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 13%, transparent);
  border-radius: 14px;
  padding: 28px 24px;
  transition: border-color .2s, background .2s, box-shadow .2s;
}
.ov-blog-art-card:hover {
  border-color: color-mix(in srgb, var(--green) 28%, transparent);
  background: color-mix(in srgb, var(--green) 5.5%, transparent);
  box-shadow: 0 8px 32px color-mix(in srgb, var(--green) 6%, transparent);
}

.ov-blog-art-body {
  flex: 1;
  margin-bottom: 24px;
}

.ov-blog-art-title {
  font-size: 16px;
  font-weight: 650;
  color: rgba(255,255,255,.88);
  line-height: 1.45;
  letter-spacing: -.015em;
