  font-weight: 700;
  padding: 2px 7px;
  border-radius: 20px;
  background: color-mix(in srgb, var(--green) 15%, transparent);
  color: var(--green);
}
/* Product Simplification Sprint — Intelligence's sidebar notification dot:
   a plain small dot ("something meaningful happened"), not a count pill,
   matching modern productivity-software unread indicators. */
#orvIntelBadge {
  width: 7px;
  height: 7px;
  padding: 0;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--green) 25%, transparent);
}
.orv-sb-bottom {
  flex-shrink: 0;
  border-top: 1px solid var(--border, rgba(255,255,255,.07));
  padding: 10px;
}
.orv-sb-user {
  display: flex;
  align-items: center;
  gap: 10px;
