}
.orv-sb-user:hover { background: color-mix(in srgb, var(--green) 8%, transparent); }
body.dark-mode .orv-sb-user:hover { background: color-mix(in srgb, var(--green) 10%, transparent); }
.orv-sb-avatar {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--green) 15%, transparent);
  color: var(--green-text);
