  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
body.dark-mode .orv-sb-avatar { color: var(--green); }
.orv-sb-user-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--charcoal, #18181A);
  white-space: nowrap;
