}
body.dark-mode .orv-sb-user-name { color: rgba(255,255,255,.85); }
.orv-sb-user-plan { font-size: 10px; color: var(--muted); }

/* Main content adjusts for sidebar */
.mc { flex: 1 !important; min-width: 0 !important; height: 100vh !important; overflow-y: auto !important; overflow-x: hidden !important; }

