.orv-rec-title { font-size: 14px; font-weight: 700; color: var(--charcoal); margin-bottom: 2px; }
body.dark-mode .orv-rec-title { color: rgba(255,255,255,.9); }
.orv-rec-camp { font-size: 11px; color: var(--muted); }
.orv-rec-body { font-size: 13px; color: var(--muted); line-height: 1.55; margin-bottom: 16px; }
.orv-rec-footer { display: flex; align-items: center; justify-content: space-between; }
.orv-rec-impact { display: flex; align-items: center; gap: 20px; }
.orv-rec-stat-val { font-size: 18px; font-weight: 800; color: var(--green); letter-spacing: -.02em; }
.orv-rec-stat-lbl { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.orv-conf-wrap { display: flex; align-items: center; gap: 6px; }
.orv-conf-label { font-size: 11px; font-weight: 600; color: var(--muted); }
.orv-conf-bar { width: 52px; height: 4px; background: var(--border); border-radius: 4px; overflow: hidden; }
.orv-conf-fill { height: 100%; background: linear-gradient(90deg, var(--green), #6ee7b7); border-radius: 4px; }

/* ── Generic empty state ──────────────────────────────────────── */
.orv-empty { text-align: center; padding: 80px 32px; }
.orv-empty-ico { width: 52px; height: 52px; border-radius: 14px; background: color-mix(in srgb, var(--green) 8%, transparent); display: flex; align-items: center; justify-content: center; margin: 0 auto 18px; color: var(--green); }
.orv-empty-title { font-size: 18px; font-weight: 700; color: var(--charcoal); letter-spacing: -.02em; margin-bottom: 8px; }
body.dark-mode .orv-empty-title { color: rgba(255,255,255,.9); }
.orv-empty-sub { font-size: 14px; color: var(--muted); max-width: 380px; margin: 0 auto 24px; line-height: 1.6; }


/* ══════════════════════════════════════════════════════════════
   HOMEPAGE — NEW WORKFLOW SECTIONS
   ══════════════════════════════════════════════════════════════ */

/* ── Workflow section base ───────────────────────────────────── */
.ov-wf-section {
  padding: 100px 0;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.ov-wf-section.ov-wf-alt { background: rgba(255,255,255,.02); }

/* Redesign v2 — text-column entrance (Intelligence/Autopilot/Business):
   previously only the visual mockup side animated in via data-observe;
   the copy/bullets side just appeared instantly. */
.ov-wf-text {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .55s cubic-bezier(.16,1,.3,1), transform .55s cubic-bezier(.16,1,.3,1);
}
.ov-wf-text.ov-vis { opacity: 1; transform: translateY(0); }

/* ══════════════════════════════════════════════════════════════════
   REDESIGN — Ad Examples Showcase (platform-switching interactive proof)
   ══════════════════════════════════════════════════════════════════ */
.ov-showcase-section { padding: 100px 48px; background: #07070A; border-bottom: 1px solid rgba(255,255,255,.05); }
.ov-showcase-inner { max-width: 1400px; margin: 0 auto; }
.ov-showcase-head { text-align: center; margin-bottom: 40px; }
.ov-showcase-tabs { display: flex; justify-content: center; gap: 10px; margin-bottom: 48px; flex-wrap: wrap; }
.ov-showcase-tab {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 11px 22px; border-radius: 100px;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1);
  color: rgba(255,255,255,.6); font-size: 13px; font-weight: 600;
  cursor: pointer; font-family: inherit;
  transition: background .25s ease, border-color .25s ease, color .25s ease;
}
.ov-showcase-tab:hover { color: #fff; border-color: rgba(255,255,255,.2); }
.ov-showcase-tab-active { background: rgba(183,255,42,.08); border-color: rgba(183,255,42,.4); color: #fff; }
.ov-showcase-tab:focus-visible { outline: 2px solid var(--green, #B7FF2A); outline-offset: 2px; }
@media (max-width: 640px) {
  .ov-showcase-section { padding: 64px 20px; }
}

/* ══════════════════════════════════════════════════════════════════
   REDESIGN — "Every Brand Needs It"
   ══════════════════════════════════════════════════════════════════ */
.ov-brands-section { padding: 64px 48px; background: rgba(255,255,255,.02); border-bottom: 1px solid rgba(255,255,255,.05); }
.ov-brands-inner { max-width: 1400px; margin: 0 auto; }
.ov-brands-head { text-align: center; margin-bottom: 40px; }
.ov-brands-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.ov-brand-card {
  background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px; padding: 28px 24px;
  opacity: 0; transition: opacity .35s ease, border-color .3s ease, background .3s ease, transform .3s ease;
}
.ov-brand-card.ov-vis { opacity: 1; }
.ov-brand-card:hover { border-color: rgba(183,255,42,.3); background: rgba(255,255,255,.045); transform: translateY(-3px); }
.ov-brand-ico { width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; background: rgba(183,255,42,.08); border-radius: 10px; margin-bottom: 18px; }
.ov-brand-ico svg { width: 20px; height: 20px; }
.ov-brand-name { font-size: 16px; font-weight: 700; color: #fff; margin-bottom: 8px; }
.ov-brand-desc { font-size: 13.5px; line-height: 1.55; color: rgba(255,255,255,.55); }

@media (max-width: 900px) {
  .ov-brands-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .ov-brands-grid { grid-template-columns: 1fr; }
  .ov-brands-section, .ov-showcase-section { padding: 64px 20px; }
}
.ov-wf-inner {
  max-width: 1400px; /* Redesign: was 1100px */
  margin: 0 auto;
  padding: 0 48px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.ov-wf-inner-rev { direction: rtl; }
.ov-wf-inner-rev > * { direction: ltr; }

/* Business/Teams — the one section deliberately mirrored end-to-end
   (visual left, text right, text itself right-aligned) to close out the
   Build -> Publish -> Scale alternating rhythm with a clean bookend. */
.ov-wf-text-r { text-align: right; }
.ov-wf-text-r .ov-wf-bullets { align-items: flex-end; }
.ov-wf-text-r .ov-wf-bullets li { padding-left: 0; padding-right: 20px; }
.ov-wf-text-r .ov-wf-bullets li::before { left: auto; right: 0; }
.ov-wf-step-num {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 14px;
}
.ov-wf-h2 {
  font-size: 36px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -.03em;
  line-height: 1.18;
  margin: 0 0 16px;
}
.ov-wf-desc {
  font-size: 15px;
  color: rgba(255,255,255,.55);
  line-height: 1.7;
  margin: 0 0 22px;
}
.ov-wf-bullets {
  list-style: none;
  padding: 0;
  margin: 0 0 28px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.ov-wf-bullets li {
  font-size: 13px;
  color: rgba(255,255,255,.6);
  padding-left: 20px;
  position: relative;
  line-height: 1.5;
}
.ov-wf-bullets li::before {
  content: '↗';
  position: absolute;
  left: 0;
  color: var(--green);
  font-size: 11px;
  top: 1px;
}
.ov-btn-sm {
  font-size: 13px;
  padding: 9px 18px;
  border-radius: 9px;
}

/* ── Connect visual ──────────────────────────────────────────── */
.ov-conn-cards {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.ov-conn-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 14px;
  padding: 14px 16px;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-conn-card.ov-vis {
  opacity: 1;
  transform: translateY(0);
}
.ov-conn-card-left { display: flex; align-items: center; gap: 12px; }
.ov-conn-logo {
  width: 38px; height: 38px; border-radius: 10px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.08);
  display: flex; align-items: center; justify-content: center;
}
.ov-conn-name { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.9); margin-bottom: 2px; }
.ov-conn-sub { font-size: 11px; color: rgba(255,255,255,.4); }
.ov-conn-badge { font-size: 11px; font-weight: 700; color: var(--green); letter-spacing: .03em; }
.ov-conn-badge-grey { font-size: 11px; font-weight: 700; color: rgba(255,255,255,.3); letter-spacing: .03em; }
.ov-conn-stat-row {
  display: grid; grid-template-columns: repeat(3,1fr); gap: 10px;
  background: color-mix(in srgb, var(--green) 5%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 15%, transparent);
  border-radius: 14px;
  padding: 16px;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-conn-stat-row.ov-vis { opacity: 1; transform: translateY(0); }
.ov-conn-stat-val { font-size: 20px; font-weight: 800; color: #fff; letter-spacing: -.03em; }
.ov-conn-stat-lbl { font-size: 10px; color: rgba(255,255,255,.4); text-transform: uppercase; letter-spacing: .07em; margin-top: 3px; font-weight: 600; }

/* ── Workspace framing + connection visual (Section 01) ──────── */
.ov-conn-workspace { display: flex; flex-direction: column; gap: 14px; }
.ov-conn-ws-head {
  display: flex; align-items: center; gap: 9px;
  padding: 10px 14px;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 11px;
  opacity: 0; transform: translateY(12px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-conn-ws-head.ov-vis { opacity: 1; transform: translateY(0); }
.ov-conn-ws-mark {
  width: 20px; height: 20px; border-radius: 6px;
  background: color-mix(in srgb, var(--green) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 30%, transparent);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.ov-conn-ws-mark svg { width: 11px; height: 11px; }
.ov-conn-ws-title {
  font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: rgba(255,255,255,.55); flex: 1;
}
.ov-conn-ws-sync {
  display: flex; align-items: center; gap: 6px;
  font-size: 10.5px; font-weight: 600; color: color-mix(in srgb, var(--green) 75%, transparent);
}
.ov-conn-ws-dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--green);
  animation: ovWsPulse 2.2s ease-out infinite;
}
@keyframes ovWsPulse {
  0%   { box-shadow: 0 0 0 0 color-mix(in srgb, var(--green) 45%, transparent); }
  70%  { box-shadow: 0 0 0 7px color-mix(in srgb, var(--green) 0%, transparent); }
  100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--green) 0%, transparent); }
}

.ov-conn-cards { position: relative; padding-left: 14px; }
.ov-conn-rail {
  position: absolute; top: 6px; bottom: 6px; left: 0;
  width: 2px;
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--green) 45%, transparent) 0%,
    color-mix(in srgb, var(--green) 12%, transparent) 100%);
  border-radius: 2px;
  overflow: hidden;
  pointer-events: none;
}
.ov-conn-rail-dot {
  position: absolute; left: 50%; top: 0;
  width: 6px; height: 6px; margin-left: -3px;
  border-radius: 50%; background: var(--green);
  box-shadow: 0 0 8px color-mix(in srgb, var(--green) 70%, transparent);
  animation: ovRailFlow 3.2s ease-in-out infinite;
}
@keyframes ovRailFlow {
  0%   { top: 0%; opacity: 0; }
  10%  { opacity: 1; }
  90%  { opacity: 1; }
  100% { top: 100%; opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .ov-conn-ws-dot { animation: none; }
  .ov-conn-rail-dot { animation: none; top: 50%; opacity: .8; }
}

/* ── Discover visual ─────────────────────────────────────────── */
.ov-disc-mock {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px;
  overflow: hidden;
}
.ov-disc-prompt {
  padding: 18px 20px 16px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.ov-disc-prompt-lbl { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .09em; color: rgba(255,255,255,.35); margin-bottom: 8px; }
.ov-disc-prompt-text { font-size: 13px; color: rgba(255,255,255,.7); line-height: 1.5; }
.ov-disc-results { padding: 16px 20px 18px; display: flex; flex-direction: column; gap: 10px; }
.ov-disc-card {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 12px;
  padding: 12px 14px;
  opacity: 0;
  transform: translateY(12px);
  transition: opacity .45s ease, transform .45s ease;
}
.ov-disc-card.ov-vis { opacity: 1; transform: translateY(0); }
.ov-disc-tag {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 5px;
  margin-bottom: 7px;
}
.ov-disc-tag-aud { background: rgba(96,165,250,.12); color: #60a5fa; }
.ov-disc-tag-hook { background: color-mix(in srgb, var(--green) 10%, transparent); color: var(--green); }
.ov-disc-tag-ins { background: rgba(251,191,36,.1); color: #fbbf24; }
.ov-disc-title { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.85); margin-bottom: 4px; line-height: 1.4; }
.ov-disc-body { font-size: 11px; color: rgba(255,255,255,.4); line-height: 1.5; }

/* ── Create visual ───────────────────────────────────────────── */
.ov-create-mock {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px;
  overflow: hidden;
}
.ov-cr-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.ov-cr-title { font-size: 12px; font-weight: 700; color: rgba(255,255,255,.8); }
.ov-cr-badge {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .04em;
  color: rgba(255,255,255,.4);
  background: rgba(255,255,255,.06);
  padding: 3px 8px;
  border-radius: 5px;
}
.ov-cr-asset {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(255,255,255,.05);
  opacity: 0;
  transform: translateY(10px);
  transition: opacity .4s ease, transform .4s ease;
}
.ov-cr-asset.ov-vis { opacity: 1; transform: translateY(0); }
.ov-cr-asset:last-child { border-bottom: none; }
.ov-cr-asset-lbl { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.3); min-width: 80px; padding-top: 2px; flex-shrink: 0; }
.ov-cr-asset-val { font-size: 12px; color: rgba(255,255,255,.75); line-height: 1.5; flex: 1; }
.ov-cr-score { display: flex; align-items: center; gap: 5px; font-size: 10px; color: rgba(255,255,255,.4); flex-shrink: 0; white-space: nowrap; }
.ov-score-dot { width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0; }
.ov-score-dot.ov-score-great { background: var(--green); }
.ov-score-dot.ov-score-ok { background: #fbbf24; }

/* ── Launch visual ───────────────────────────────────────────── */
.ov-launch-mock {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px;
  padding: 22px 24px;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.ov-lm-step {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 10px 0;
  opacity: 0;
  transform: translateX(-10px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-lm-step.ov-vis { opacity: 1; transform: translateX(0); }
.ov-lm-num {
  width: 28px; height: 28px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 700; flex-shrink: 0;
}
.ov-lm-num-done { background: color-mix(in srgb, var(--green) 12%, transparent); color: var(--green); }
.ov-lm-num-active {
  background: var(--green); color: #000;
  transform-origin: center center;
  animation: ovLmPulse 2.2s cubic-bezier(.45,0,.55,1) infinite;
}
.ov-lm-num-inactive { background: rgba(255,255,255,.05); color: rgba(255,255,255,.25); }

/* Active step indicator — subtle continuous "in progress" pulse. Scale-only,
   fixed box size, so it never shifts the surrounding step layout. */
@keyframes ovLmPulse {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.10); }
}
@media (prefers-reduced-motion: reduce) {
  .ov-lm-num-active { animation: none; }
}
.ov-lm-step-t { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.85); margin-bottom: 2px; }
.ov-lm-step.ov-lm-inactive .ov-lm-step-t { color: rgba(255,255,255,.3); }
.ov-lm-step-s { font-size: 11px; color: rgba(255,255,255,.35); }
.ov-lm-connector {
  width: 1px;
  height: 18px;
  background: rgba(255,255,255,.08);
  margin: 0 0 0 14px;
}
.ov-lm-done-line { background: color-mix(in srgb, var(--green) 25%, transparent); }

/* ── Analyze visual ──────────────────────────────────────────── */
.ov-an-mock {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px;
  overflow: hidden;
}
.ov-an-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.ov-an-tabs { display: flex; gap: 0; }
.ov-an-tab {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 12px;
  font-size: 11px; font-weight: 600; color: rgba(255,255,255,.4);
  border-radius: 7px; cursor: default;
}
.ov-an-tab-active { background: rgba(255,255,255,.07); color: rgba(255,255,255,.85); }
.ov-an-dot { width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0; }
.ov-an-range { font-size: 11px; color: rgba(255,255,255,.3); font-weight: 500; }
.ov-an-kpis {
  display: grid; grid-template-columns: repeat(4,1fr);
  padding: 14px 16px;
  gap: 0;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.ov-an-kpi { padding: 6px 0; }
.ov-an-kv { font-size: 18px; font-weight: 800; color: rgba(255,255,255,.9); letter-spacing: -.03em; }
.ov-an-kl { font-size: 10px; color: rgba(255,255,255,.35); text-transform: uppercase; letter-spacing: .07em; font-weight: 600; margin-top: 2px; }
.ov-an-table { padding: 0 0 8px; }
.ov-an-table-hdr {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr;
  padding: 8px 16px;
  font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em;
  color: rgba(255,255,255,.25);
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.ov-an-row {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr;
  padding: 10px 16px;
  font-size: 12px; color: rgba(255,255,255,.7);
  border-bottom: 1px solid rgba(255,255,255,.04);
}
.ov-an-row:last-child { border-bottom: none; }

/* ── Scale visual ────────────────────────────────────────────── */
.ov-scale-mock { display: flex; flex-direction: column; gap: 12px; }
.ov-sm-topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 2px 2px;
  opacity: 0; transform: translateY(10px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-scale-mock.ov-vis .ov-sm-topbar { opacity: 1; transform: translateY(0); }
.ov-sm-topbar-title { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; color: rgba(255,255,255,.7); }
.ov-sm-topbar-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); flex-shrink: 0; animation: ovSmPulseDot 1.6s ease-in-out infinite; }
.ov-sm-topbar-status { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.35); }
@keyframes ovSmPulseDot { 0%, 100% { opacity: .4; transform: scale(1); } 50% { opacity: 1; transform: scale(1.3); } }
@media (prefers-reduced-motion: reduce) { .ov-sm-topbar-dot { animation: none; } }

/* All three platforms shown as continuously, independently monitored —
   replaces the old single "hero variant" card treatment, which made two
   of the three platforms read as inert. */
.ov-sm-platforms {
  display: flex; flex-direction: column; gap: 8px;
  opacity: 0; transform: translateY(14px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-sm-platforms.ov-vis { opacity: 1; transform: translateY(0); }
.ov-sm-plat {
  display: flex; align-items: center; gap: 10px;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 10px;
  padding: 11px 14px;
}
.ov-sm-plat-logo { display: flex; align-items: center; justify-content: center; width: 18px; flex-shrink: 0; }
.ov-sm-plat-name { font-size: 12.5px; font-weight: 600; color: rgba(255,255,255,.75); flex: 1; }
.ov-sm-plat-live { display: flex; align-items: center; gap: 5px; font-size: 10.5px; font-weight: 700; color: var(--green); letter-spacing: .02em; }
.ov-sm-plat-live-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--green); animation: ovSmPulseDot 1.8s ease-in-out infinite; }
.ov-sm-plat:nth-child(2) .ov-sm-plat-live-dot { animation-delay: .3s; }
.ov-sm-plat:nth-child(3) .ov-sm-plat-live-dot { animation-delay: .6s; }
@media (prefers-reduced-motion: reduce) { .ov-sm-plat-live-dot { animation: none; opacity: .85; } }

/* Live activity feed — a genuine "system log" of optimization events,
   one row entering at a time (see the JS tick() in index.html), the
   older two rows dimming in place like a real notification feed rather
   than everything appearing at once. */
.ov-sm-feed {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 14px;
  padding: 16px 18px;
  opacity: 0; transform: translateY(14px);
  transition: opacity .5s ease .08s, transform .5s ease .08s;
}
.ov-sm-feed.ov-vis { opacity: 1; transform: translateY(0); }
.ov-sm-feed-head { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.3); margin-bottom: 12px; }
.ov-sm-feed-rows { display: flex; flex-direction: column; gap: 11px; }
.ov-sm-feed-row { display: flex; align-items: center; gap: 8px; font-size: 12.5px; transition: opacity .3s ease; }
.ov-sm-feed-row:nth-child(1) { opacity: .95; }
.ov-sm-feed-row:nth-child(2) { opacity: .5; }
.ov-sm-feed-row:nth-child(3) { opacity: .26; }
.ov-sm-feed-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--green); flex-shrink: 0; }
.ov-sm-feed-plat { color: rgba(255,255,255,.55); font-weight: 600; flex-shrink: 0; }
.ov-sm-feed-sep { color: rgba(255,255,255,.25); }
.ov-sm-feed-txt { color: rgba(255,255,255,.9); font-weight: 600; }
.ov-sm-feed-row-flash { animation: ovSmFeedFlash .5s ease; }
@keyframes ovSmFeedFlash { 0% { opacity: 0; transform: translateX(-6px); } 100% { opacity: .95; transform: translateX(0); } }
@media (prefers-reduced-motion: reduce) { .ov-sm-feed-row-flash { animation: none; } }

/* ══════════════════════════════════════════════════════════════════
   REDESIGN — Build → Publish → Scale workflow. Replaces the old
   Intelligence/Autopilot sections with three connected steps. Reuses
   .ov-wf-section/.ov-wf-inner/.ov-wf-text and (for Scale) the
   .ov-scale-mock/.ov-sm-platforms/.ov-sm-feed above as-is — the only
   new component CSS is below: .ov-build-mock/.ov-bm-*,
   .ov-pub-mock/.ov-pub-*, and .ov-workflow-connector/.ov-wfc-*.
   ══════════════════════════════════════════════════════════════════ */

/* ── Build visual — prompt → generating → finished ad, auto-cycling
   through three stacked panels. A miniature version of the real Oriven
   generation UI's own language (structured field: "value" lines, a
   green active-glow on the field still resolving) rather than a
   generic illustration — see app.html's campaign blueprint, which uses
   the same visual vocabulary at full scale. ── */
.ov-build-mock { display: flex; flex-direction: column; align-items: center; gap: 22px; width: 100%; }
.ov-bm-card {
  position: relative;
  width: 100%;
  max-width: 420px;
  min-height: 280px;
  background: #08080a;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 30px 70px -30px rgba(0,0,0,.6);
}
.ov-bm-panel {
  position: absolute;
  inset: 0;
  padding: 30px 28px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity .45s ease;
}
.ov-bm-panel.ov-bm-panel-active { opacity: 1; visibility: visible; }

.ov-bm-eyebrow { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.35); margin-bottom: 14px; display: flex; align-items: center; gap: 8px; }
.ov-bm-eyebrow-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); flex-shrink: 0; animation: ovBmPulseDot 1.4s ease-in-out infinite; }

/* Stage 1 — prompt, typed in via a pure-CSS steps() typewriter that
   restarts each time this panel becomes active (see the JS toggle). */
.ov-bm-prompt-box { background: rgba(255,255,255,.044); border: 1.5px solid rgba(255,255,255,.1); border-radius: 14px; padding: 18px 20px; min-height: 52px; display: flex; align-items: center; }
.ov-bm-prompt-text {
  display: inline-block;
  overflow: hidden;
  white-space: nowrap;
  font-size: 14.5px;
  color: rgba(255,255,255,.88);
  width: 0;
}
.ov-bm-panel-active .ov-bm-prompt-text { animation: ovBmType 2.2s steps(32, end) forwards; }
.ov-bm-cursor { display: inline-block; width: 2px; height: 16px; background: var(--green); margin-left: 2px; vertical-align: -3px; animation: ovBmBlink .9s steps(1) infinite; }

/* Stage 2 — generating (miniature campaign-blueprint style) */
.ov-bm-gen-lines { font-family: "SF Mono","Cascadia Code","Consolas",monospace; font-size: 12.5px; line-height: 2.1; }
.ov-bm-gen-line { color: rgba(255,255,255,.42); }
.ov-bm-gen-key { color: rgba(255,255,255,.4); }
.ov-bm-gen-colon { color: rgba(255,255,255,.22); }
.ov-bm-gen-val { color: var(--green); font-weight: 600; }
.ov-bm-gen-line-active .ov-bm-gen-val { animation: ovBmActivePulse 1.3s ease-in-out infinite; }

/* Stage 3 — the finished ad (reuses .adv-card/.adv-g-* from the ad
   showcase wall — the same real card style, not a new one). */
.ov-bm-result { display: flex; flex-direction: column; align-items: center; gap: 14px; }
.ov-bm-result-card {
  width: 100%;
  max-width: 320px;
  height: 168px;
  border-radius: 14px;
  background: #0c0c10;
  border: 1px solid rgba(251,188,5,.2);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ov-bm-dots { display: flex; gap: 8px; }
.ov-bm-dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,.15); transition: background .3s ease, transform .3s ease; }
.ov-bm-dot.ov-bm-dot-active { background: var(--green); transform: scale(1.35); }

@keyframes ovBmType { to { width: 27ch; } }
@keyframes ovBmBlink { 50% { opacity: 0; } }
@keyframes ovBmPulseDot { 0%, 100% { opacity: .4; transform: scale(1); } 50% { opacity: 1; transform: scale(1.3); } }
@keyframes ovBmActivePulse { 0%, 100% { opacity: .6; } 50% { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .ov-bm-prompt-text { animation: none !important; width: 27ch !important; }
  .ov-bm-cursor, .ov-bm-eyebrow-dot, .ov-bm-gen-line-active .ov-bm-gen-val { animation: none !important; }
}

/* ── Publish visual — one ad, branching to three platforms. Deliberately
   simple: a source card, a stem, a branch line, three targets — not a
   dashboard. ── */
.ov-pub-mock { position: relative; display: flex; flex-direction: column; align-items: center; width: 100%; max-width: 620px; }

/* Entrance sequence, all keyed off .ov-pub-mock.ov-vis (the mock's own
   data-observe): the source card appears, then each platform's own
   connector draws in, sends a traveling pulse, and activates its node —
   one platform fully at a time, not a shared branch that reveals all
   three together. Deliberately slower than a typical UI transition so
   the sequence itself reads as "Oriven distributing this ad", not just
   decoration. No background glow — removed per design direction. */
.ov-pub-source {
  position: relative;
  z-index: 1;
  display: flex; align-items: center; gap: 12px;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1);
  border-radius: 14px; padding: 16px 24px;
  font-size: 16px; font-weight: 600; color: #fff;
  opacity: 0; transform: translateY(8px);
  transition: opacity .6s ease .1s, transform .6s cubic-bezier(.16,1,.3,1) .1s;
}
.ov-pub-mock.ov-vis .ov-pub-source { opacity: 1; transform: translateY(0); }
.ov-pub-source-ico { width: 28px; height: 28px; border-radius: 8px; background: color-mix(in srgb, var(--green) 14%, transparent); display: flex; align-items: center; justify-content: center; flex-shrink: 0; }

.ov-pub-flow { position: relative; z-index: 1; display: flex; justify-content: space-between; width: 100%; padding-top: 12px; gap: 20px; }
.ov-pub-conn { display: flex; flex-direction: column; align-items: center; flex: 1; }

.ov-pub-conn-line {
  position: relative;
  width: 1.5px; height: 42px; background: rgba(255,255,255,.15);
  transform-origin: top; transform: scaleY(0);
  opacity: 0;
  transition: transform .5s cubic-bezier(.16,1,.3,1) var(--d), opacity .25s ease var(--d);
}
.ov-pub-mock.ov-vis .ov-pub-conn-line { transform: scaleY(1); opacity: 1; }
.ov-pub-conn-pulse {
  position: absolute; left: 50%; top: 0;
  width: 6px; height: 6px; margin-left: -3px;
  border-radius: 50%; background: var(--green);
  opacity: 0;
  box-shadow: 0 0 10px 1px color-mix(in srgb, var(--green) 65%, transparent);
}
.ov-pub-mock.ov-vis .ov-pub-conn-pulse { animation: ovPubPulseTravel .55s ease-out calc(var(--d) + .15s) 1; }
@keyframes ovPubPulseTravel { 0% { opacity: 1; top: 0; } 85% { opacity: 1; } 100% { opacity: 0; top: 100%; } }

.ov-pub-node {
  display: flex; flex-direction: column; align-items: center; gap: 11px;
  margin-top: 14px;
  opacity: 0; transform: translateY(10px);
  transition: opacity .55s cubic-bezier(.16,1,.3,1) calc(var(--d) + .45s), transform .55s cubic-bezier(.16,1,.3,1) calc(var(--d) + .45s);
}
.ov-pub-mock.ov-vis .ov-pub-node { opacity: 1; transform: translateY(0); }
.ov-pub-target-logo { width: 68px; height: 68px; border-radius: 17px; background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.1); display: flex; align-items: center; justify-content: center; }
.ov-pub-target-name { font-size: 13.5px; font-weight: 600; color: rgba(255,255,255,.65); }
.ov-pub-target-status { display: flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 700; letter-spacing: .02em; color: var(--green); }

@media (prefers-reduced-motion: reduce) {
  .ov-pub-source, .ov-pub-conn-line, .ov-pub-node {
    transition: opacity .3s ease !important;
    transform: none !important;
  }
  .ov-pub-conn-pulse { animation: none !important; opacity: 0 !important; }
}

/* ── Workflow connector — the ↓ thread between Build/Publish/Scale ── */
.ov-workflow-connector {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 12px 0;
  background: #07070A;
}
.ov-wfc-line { width: 1.5px; height: 22px; background: linear-gradient(to bottom, rgba(255,255,255,.03), rgba(255,255,255,.18)); }
.ov-wfc-arrow { color: var(--green); display: flex; opacity: .85; }
.ov-wfc-label { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: rgba(255,255,255,.3); }

/* ── Social proof strip ──────────────────────────────────────── */
.ov-social-proof { padding: 72px 0; border-bottom: 1px solid rgba(255,255,255,.05); }
.ov-sp-wrap { max-width: 1300px; margin: 0 auto; padding: 0 48px; text-align: center; } /* Redesign: was 900px */
.ov-sp-label { font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: rgba(255,255,255,.3); margin-bottom: 36px; }
.ov-sp-stats { display: grid; grid-template-columns: repeat(4,1fr); gap: 0; }
.ov-sp-stat {
  padding: 8px 16px;
  border-right: 1px solid rgba(255,255,255,.06);
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .5s ease, transform .5s ease;
}
.ov-sp-stat.ov-vis { opacity: 1; transform: translateY(0); }
.ov-sp-stat:last-child { border-right: none; }
.ov-sp-stat-val { font-size: 32px; font-weight: 800; color: #fff; letter-spacing: -.04em; margin-bottom: 6px; }
.ov-sp-stat-lbl { font-size: 12px; color: rgba(255,255,255,.4); font-weight: 500; }

/* ── Staggered recurring glow (Section 04 stats) ─────────────── */
.ov-sp-glow { position: relative; }
.ov-sp-glow::before {
  content: '';
  position: absolute;
  inset: -8px -6px;
  border-radius: 14px;
  background: radial-gradient(ellipse at 50% 38%, color-mix(in srgb, var(--green) 18%, transparent) 0%, transparent 72%);
  opacity: 0;
  pointer-events: none;
  z-index: -1;
  animation: ovSpGlow 4.5s ease-in-out infinite;
  animation-delay: var(--glow-delay, 0s);
}
@keyframes ovSpGlow {
  0%, 100% { opacity: 0; }
  50% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .ov-sp-glow::before { animation: none !important; opacity: 0 !important; }
}

/* ── Responsive ──────────────────────────────────────────────── */
@media (max-width: 860px) {
  .ov-wf-inner { grid-template-columns: 1fr; gap: 40px; }
  .ov-wf-inner-rev { direction: ltr; }
  .ov-wf-text-r { text-align: left; }
  .ov-wf-text-r .ov-wf-bullets { align-items: flex-start; }
  .ov-wf-text-r .ov-wf-bullets li { padding-left: 20px; padding-right: 0; }
  .ov-wf-text-r .ov-wf-bullets li::before { left: 0; right: auto; }
  .ov-wf-h2 { font-size: 26px; }
  .ov-wf-section { padding: 64px 0; }
  .ov-sp-stats { grid-template-columns: repeat(2,1fr); }
  .ov-sp-stat:nth-child(2) { border-right: none; }
  .ov-sp-stat:nth-child(3) { border-top: 1px solid rgba(255,255,255,.06); }
  .ov-sp-stat:nth-child(4) { border-top: 1px solid rgba(255,255,255,.06); border-right: none; }
  .ov-an-kpis { grid-template-columns: repeat(2,1fr); }
  .ov-an-table-hdr, .ov-an-row { grid-template-columns: 2fr 1fr 1fr; }
  .ov-an-table-hdr span:last-child, .ov-an-row span:last-child { display: none; }
}
@media (max-width: 540px) {
  .ov-wf-inner { padding: 0 20px; }
  .ov-sp-wrap { padding: 0 20px; }
  .ov-sp-stats { grid-template-columns: 1fr 1fr; }
}


/* ══════════════════════════════════════════════════════════════
   ORIVEN v2 — PRODUCT REDESIGN CSS
   ══════════════════════════════════════════════════════════════ */

/* ── Hide legacy top nav + old sidebar ──────────────────────── */
.ap-nav { display: none !important; }
.ap-mob-nav { display: none !important; }
body > .ap-nav { display: none !important; }
#apMobNav { display: none !important; }

/* ── App shell: sidebar + workspace + AI panel ──────────────── */
.app {
  display: flex !important;
  flex-direction: row !important;
  height: 100vh !important;
  width: 100% !important;
  overflow: hidden !important;
}

/* ── Sidebar ─────────────────────────────────────────────────── */
.orv-sb {
  width: 280px;
  min-width: 280px;
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: var(--surface, #fff);
  border-right: 1px solid var(--border, rgba(0,0,0,.07));
  flex-shrink: 0;
  z-index: 10;
  overflow: hidden;
}
body.dark-mode .orv-sb {
  background: #111113;
  border-right-color: rgba(255,255,255,.07);
}

.orv-sb-logo {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 18px 16px 14px;
  cursor: default;
  flex-shrink: 0;
  border-bottom: 1px solid var(--border, rgba(0,0,0,.06));
  margin-bottom: 10px;
}
.orv-sb-logo-img { width: 40px; height: 40px; object-fit: contain; flex-shrink: 0; }
.orv-sb-logo-name { font-size: 13px; font-weight: 800; letter-spacing: .08em; color: var(--charcoal, #18181A); }
body.dark-mode .orv-sb-logo-name { color: #fff; }

.orv-sb-nav {
  flex: 1;
  overflow-y: auto;
  padding: 6px 12px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.orv-ni {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 9px;
  font-size: 13.5px;
  font-weight: 500;
  color: rgba(0,0,0,.5);
  cursor: pointer;
  border: none;
  background: none;
  width: 100%;
  text-align: left;
  position: relative;
  user-select: none;
  transition: color var(--orv-t, .16s), background var(--orv-t, .16s), box-shadow var(--orv-t, .16s);
  letter-spacing: -.01em;
}
/* Premium Motion System — hover/active/glow all read var(--green), the
   same variable Settings' Accent Color picker overrides on <body>
   (settings.js:_applyAccent), so the sidebar automatically follows
   whichever accent the user has chosen instead of a hardcoded green. */
.orv-ni:hover { background: color-mix(in srgb, var(--green) 8%, transparent); color: var(--charcoal, #18181A); }
body.dark-mode .orv-ni { color: rgba(255,255,255,.45); }
body.dark-mode .orv-ni:hover { background: color-mix(in srgb, var(--green) 10%, transparent); color: rgba(255,255,255,.9); }
/* Light mode: solid lime background + near-black text/icon (--green-deep,
   the same "black-on-green" token .sub-pcard-btn-up already uses) -- the
   previous pale 10%-tint background + var(--gm) lime TEXT read as
   green-on-green with poor contrast. Dark mode below is unchanged (a
   subtle tinted background with bright lime text already reads correctly
   against a near-black surface). */
.orv-ni.orv-active {
  background: var(--green);
  color: var(--green-deep);
  font-weight: 600;
}
body.dark-mode .orv-ni.orv-active { background: color-mix(in srgb, var(--green) 12%, transparent); color: var(--green); }
.orv-ni.orv-active::before {
  content: '';
  position: absolute;
  left: 0; top: 7px; bottom: 7px;
  width: 3px;
  border-radius: 0 2px 2px 0;
  background: var(--green);
  opacity: 0;
  transform: scaleY(.4);
  transition: opacity var(--orv-t, .16s), transform var(--orv-t, .16s);
}
.orv-ni.orv-active::before { opacity: 1; transform: scaleY(1); }

/* Fixed-size icon "slot" -- width/height never change, so every hover
   micro-interaction below (per icon, see the Icon Motion System further
   down) animates purely via transform/opacity/filter inside this box and
   can never shift the label or any other row. */
.orv-ni svg {
  width: 17px; height: 17px; flex-shrink: 0; opacity: .55;
  transition: opacity var(--orv-t, .16s), transform var(--orv-nit, .18s) cubic-bezier(.22,.61,.36,1), filter var(--orv-nit, .18s) ease;
}
.orv-ni:hover svg, .orv-ni.orv-active svg { opacity: 1; }
.orv-ni-label { display: inline-block; }

.orv-sb-bottom {
  flex-shrink: 0;
  border-top: 1px solid var(--border, rgba(0,0,0,.07));
  padding: 10px 12px;
}
body.dark-mode .orv-sb-bottom { border-top-color: rgba(255,255,255,.07); }

.orv-sb-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: 9px;
  cursor: default;
  transition: background .12s;
  margin-top: 4px;
}
.orv-sb-user:hover { background: color-mix(in srgb, var(--green) 8%, transparent); }
body.dark-mode .orv-sb-user:hover { background: color-mix(in srgb, var(--green) 10%, transparent); }
.orv-sb-avatar {
  width: 30px; height: 30px; border-radius: 9px;
  background: color-mix(in srgb, var(--green) 18%, transparent); color: var(--green-text);
  font-size: 12.5px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
body.dark-mode .orv-sb-avatar { color: var(--green); background: color-mix(in srgb, var(--green) 12%, transparent); }
.orv-sb-user-info { min-width: 0; }
.orv-sb-user-name { font-size: 12.5px; font-weight: 600; color: var(--charcoal, #18181A); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
body.dark-mode .orv-sb-user-name { color: rgba(255,255,255,.9); }
.orv-sb-user-plan { font-size: 11px; color: var(--muted, rgba(0,0,0,.45)); margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ── Icon Motion System — one distinct micro-interaction per nav item ──
   Each targets only the icon's own transform/filter, never layout
   properties, so the fixed 17x17 slot above never resizes and the label
   never moves. var(--orv-nit) = 180ms, inside the spec's 150-220ms range.
   A few items below need a one-shot sequence (rotate a full 360°, pulse
   up then settle, dim then relight) rather than a simple two-state hover
   hold -- those use a keyframe `animation` (plays once per hover-in) instead
   of a `transition`; the base `.orv-ni svg` transition already declared
   above still handles the smooth return to rest on hover-out. */
:root { --orv-nit: 180ms; }

/* Launch — arrow nudges right (the icon already IS an arrow). Unchanged. */
.orv-ni[data-orv-page="create"]:hover svg { transform: translateX(4px); }

/* Campaigns — the clipboard's clip presses down and closes over the body;
   the body/list-lines stay put so only the clip itself reads as moving. */
.orv-ni svg .orv-ni-clip {
  transform-box: fill-box; transform-origin: center;
  transition: transform var(--orv-nit, .18s) cubic-bezier(.22,.61,.36,1);
}
.orv-ni[data-orv-page="performance"]:hover svg .orv-ni-clip { transform: translateY(2.4px) scaleY(.72); }

/* Intelligence — the clock hand sweeps one complete revolution; the dial
   (the circle) stays completely stationary the whole time. */
@keyframes orv-ni-clock-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
.orv-ni[data-orv-page="intelligence"] svg .orv-ni-clockhand {
  transform-box: fill-box; transform-origin: center;
}
.orv-ni[data-orv-page="intelligence"]:hover svg .orv-ni-clockhand {
  animation: orv-ni-clock-spin 620ms cubic-bezier(.55,.06,.45,.94) 1;
}

/* Autopilot — the bolt energizes: a quick scale pulse with a brief glow,
   settling back to rest -- one controlled "charge", not a spin. */
@keyframes orv-ni-bolt-pulse {
  0%   { transform: scale(1) translateY(0); filter: none; }
  45%  { transform: scale(1.18) translateY(-1px); filter: drop-shadow(0 0 3px color-mix(in srgb, var(--green) 75%, transparent)); }
  100% { transform: scale(1) translateY(0); filter: none; }
}
.orv-ni[data-orv-page="autopilot"]:hover svg {
  animation: orv-ni-bolt-pulse 300ms cubic-bezier(.22,.61,.36,1) 1;
}

/* Business / Brand Brain — the bulb switches OFF briefly, then back ON,
   ending slightly brighter than its resting state (restrained glow). BUG
   FIX: the previous version also scaled the whole <svg> up to 1.08x at
   its peak, which visibly moved/resized the bulb geometry itself -- exactly
   what the icon must never do. Rebuilt with zero transform anywhere: the
   bulb outline is its own <g class="orv-ni-bulb-body"> that only ever
   changes opacity (dims, then restores -- never moves or resizes), and a
   separate, blurred <circle class="orv-ni-bulb-glow"> painted behind it
   (present in the SVG at opacity:0 normally) is the actual "light" that
   switches off then on with a strong glow -- it can extend past the
   bulb's own bounds without affecting the bulb's own geometry, since it's
   a different element entirely. */
.orv-ni[data-orv-page="businessbrain"] svg .orv-ni-bulb-glow { filter: blur(2.4px); }
@keyframes orv-ni-bulb-body-flicker {
  0%   { opacity: 1; }
  22%  { opacity: .3; }
  45%  { opacity: 1; }
  100% { opacity: 1; }
}
@keyframes orv-ni-bulb-glow-pulse {
  0%   { opacity: 0; }
  22%  { opacity: 0; }
  45%  { opacity: .25; }
  65%  { opacity: .95; }
  82%  { opacity: .95; }
  100% { opacity: .4; }
}
.orv-ni[data-orv-page="businessbrain"]:hover svg .orv-ni-bulb-body {
  animation: orv-ni-bulb-body-flicker 820ms ease 1;
}
.orv-ni[data-orv-page="businessbrain"]:hover svg .orv-ni-bulb-glow {
  animation: orv-ni-bulb-glow-pulse 820ms ease 1;
  animation-fill-mode: forwards;
}

/* Settings — a small, deliberate turn, not a continuous spin. Unchanged. */
#orvNavSettingsBtn:hover svg { transform: rotate(18deg); }

@media (prefers-reduced-motion: reduce) {
  .orv-ni svg, .orv-ni svg .orv-ni-clockhand, .orv-ni svg .orv-ni-clip,
  .orv-ni svg .orv-ni-bulb-body, .orv-ni svg .orv-ni-bulb-glow { transition: none !important; animation: none !important; }
  .orv-ni[data-orv-page="create"]:hover svg,
  .orv-ni[data-orv-page="performance"]:hover svg .orv-ni-clip,
  .orv-ni[data-orv-page="intelligence"]:hover svg .orv-ni-clockhand,
  .orv-ni[data-orv-page="autopilot"]:hover svg,
  .orv-ni[data-orv-page="businessbrain"]:hover svg .orv-ni-bulb-body,
  #orvNavSettingsBtn:hover svg { transform: none !important; filter: none !important; animation: none !important; }
  .orv-ni[data-orv-page="businessbrain"]:hover svg .orv-ni-bulb-glow { opacity: 0 !important; animation: none !important; }
}

/* ── Main content ────────────────────────────────────────────── */
.mc {
  flex: 1 !important;
  min-width: 0 !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  height: 100vh !important;
  transition: none !important;
  background: var(--bg, #F8F8F6);
}
body.dark-mode .mc { background: #0e0e10; }

/* Oriven 1.0 (V11) — permanent sidebar is back (the fixed header from
   V5/V8 that needed .mc's padding-top:56px to clear it is gone), so
   .orv-sb's display:none retirement rule and that padding are both
   removed here. Sidebar's own display:flex (below) is unopposed again. */

/* ── Workspace header — replaces the sidebar's logo/settings/avatar ── */
.orv-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  height: 56px;
  z-index: 250;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  background: var(--surface, #fff);
  border-bottom: 1px solid var(--border, rgba(0,0,0,.07));
}
body.dark-mode .orv-header { background: #111113; border-bottom-color: rgba(255,255,255,.07); }

.orv-header-logo { display: flex; align-items: center; cursor: pointer; }
.orv-header-logo-img { width: 32px; height: 32px; object-fit: contain; }


.orv-header-right { display: flex; align-items: center; gap: 8px; }

.orv-header-ic {
  display: flex; align-items: center; justify-content: center;
  width: 34px; height: 34px; border-radius: 9px;
  border: none; background: none; cursor: pointer;
  color: rgba(0,0,0,.5); transition: background .12s, color .12s;
}
.orv-header-ic:hover { background: rgba(0,0,0,.05); color: var(--charcoal, #18181A); }
body.dark-mode .orv-header-ic { color: rgba(255,255,255,.5); }
body.dark-mode .orv-header-ic:hover { background: rgba(255,255,255,.07); color: #fff; }

/* ── Workspace Switcher panel (Oriven 1.0 V8) — floating, not a sidebar/
   dropdown/modal. Fixed under the header's right side, fade+scale in. ── */
.orv-ws-panel {
  position: fixed;
  top: 64px;
  right: 20px;
  width: 340px;
  z-index: 260;
  background: var(--surface, #fff);
  border: 1px solid var(--border, rgba(0,0,0,.08));
  border-radius: 18px;
  box-shadow: 0 16px 48px rgba(0,0,0,.14);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  padding: 8px;
  opacity: 0;
  transform: translateY(-6px) scale(.98);
  transition: opacity .16s cubic-bezier(.22,.61,.36,1), transform .16s cubic-bezier(.22,.61,.36,1);
}
.orv-ws-panel.orv-ws-open { opacity: 1; transform: translateY(0) scale(1); }
body.dark-mode .orv-ws-panel { background: rgba(17,17,19,.92); border-color: rgba(255,255,255,.08); box-shadow: 0 16px 48px rgba(0,0,0,.45); }

.orv-ws-item {
  display: flex; align-items: flex-start; gap: 12px;
  width: 100%; text-align: left;
  padding: 10px; border-radius: 12px;
  border: none; background: none; cursor: pointer;
  transition: background .15s, transform .15s;
}
.orv-ws-item:hover, .orv-ws-item:focus-visible { background: rgba(0,0,0,.045); outline: none; transform: translateX(2px); }
body.dark-mode .orv-ws-item:hover, body.dark-mode .orv-ws-item:focus-visible { background: rgba(255,255,255,.06); }
.orv-ws-item-ico {
  flex-shrink: 0; width: 34px; height: 34px; border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  color: var(--green-text); background: color-mix(in srgb, var(--green) 10%, transparent);
  transition: background .15s, transform .15s;
}
.orv-ws-item:hover .orv-ws-item-ico { background: color-mix(in srgb, var(--green) 18%, transparent); transform: scale(1.06); }
body.dark-mode .orv-ws-item-ico { color: var(--green); }
.orv-ws-item-title { font-size: 13.5px; font-weight: 700; color: var(--charcoal, #18181A); margin-bottom: 2px; }
body.dark-mode .orv-ws-item-title { color: #fff; }
.orv-ws-item-desc { font-size: 12px; color: var(--muted, rgba(0,0,0,.5)); line-height: 1.4; }

/* Notif bell now flows inside the header instead of floating fixed */
.orv-header .orv-notif-bell { position: static; top: auto; right: auto; }

.orv-header-user {
  display: flex; align-items: center; gap: 8px;
  cursor: pointer; padding: 4px 8px 4px 4px; border-radius: 10px;
  transition: background .12s;
}
.orv-header-user:hover { background: rgba(0,0,0,.04); }
body.dark-mode .orv-header-user:hover { background: rgba(255,255,255,.06); }
.orv-header-user-info { display: flex; flex-direction: column; line-height: 1.2; }
.orv-header-user-info .orv-sb-user-name { font-size: 12px; font-weight: 700; }
.orv-header-user-info .orv-sb-user-plan { font-size: 11px; color: var(--muted); }

@media (max-width: 640px) {
  .orv-header-user-info { display: none; }
}

/* ── AI panel ────────────────────────────────────────────────── */
/* ── Oriven AI — panel, feed, action cards ────────────────────── */

/* Panel shell */
.orv-ai-panel {
  width: 0;
  min-width: 0;
  height: 100vh;
  background: var(--surface, #fff);
  border-left: 1px solid var(--border, rgba(0,0,0,.05));
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  overflow: hidden;
  box-sizing: border-box;
  transition: width .24s cubic-bezier(.22,.61,.36,1), min-width .24s cubic-bezier(.22,.61,.36,1);
  z-index: 20;
}
/* Oriven 1.0 (V11) — the V9 padding-top:56px fix (dodging the fixed
   header's z-index) is no longer needed now that the header is retired
   in favour of the permanent sidebar; the panel's close button has no
   more overlapping ancestor to hide under. */
body.dark-mode .orv-ai-panel { background: #111113; border-left-color: rgba(255,255,255,.06); }
.orv-ai-panel.orv-ai-open { width: 320px; min-width: 320px; }

/* Panel header */
.orv-ai-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--border, rgba(0,0,0,.06));
  flex-shrink: 0;
}
body.dark-mode .orv-ai-panel-head { border-bottom-color: rgba(255,255,255,.07); }
.orv-ai-panel-head-left { display: flex; flex-direction: column; gap: 2px; }
.orv-ai-panel-name {
  font-size: 15px; font-weight: 800; letter-spacing: -.03em;
  color: var(--charcoal, #18181A); line-height: 1;
}
body.dark-mode .orv-ai-panel-name { color: rgba(255,255,255,.95); }
.orv-ai-panel-role { font-size: 11px; color: var(--muted); font-weight: 500; }
.orv-ai-panel-head-right { display: flex; align-items: center; gap: 10px; }
.orv-ai-panel-status {
  display: flex; align-items: center; gap: 5px;
  font-size: 11px; font-weight: 600; color: var(--green-text); white-space: nowrap;
}
body.dark-mode .orv-ai-panel-status { color: var(--green); }
.orv-ai-online-dot {
  width: 7px; height: 7px; border-radius: 50%; background: var(--green); flex-shrink: 0;
  animation: oliviaOnlinePulse 2.8s ease-in-out infinite;
}
@keyframes oliviaOnlinePulse {
  0%,100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--green) 50%, transparent); opacity: 1; }
  50%      { box-shadow: 0 0 0 4px color-mix(in srgb, var(--green) 0%, transparent); opacity: .85; }
}
.orv-ai-panel-close {
  width: 26px; height: 26px; border-radius: 7px;
  display: flex; align-items: center; justify-content: center;
  background: none; border: none; cursor: pointer;
  color: var(--muted, rgba(0,0,0,.4)); transition: background .12s, color .12s;
}
.orv-ai-panel-close:hover { background: rgba(0,0,0,.05); color: var(--charcoal); }
body.dark-mode .orv-ai-panel-close:hover { background: rgba(255,255,255,.07); color: #fff; }

/* Context bar */
.orv-ai-context-bar {
  display: flex; align-items: center; gap: 6px;
  padding: 5px 16px;
  background: color-mix(in srgb, var(--green) 6%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--green) 10%, transparent);
  font-size: 11px; font-weight: 600; color: var(--green-text); flex-shrink: 0;
}
body.dark-mode .orv-ai-context-bar { color: var(--green); background: color-mix(in srgb, var(--green) 5%, transparent); border-bottom-color: color-mix(in srgb, var(--green) 8%, transparent); }
.orv-ai-ctx-dot { width: 5px; height: 5px; border-radius: 50%; background: #4ade80; flex-shrink: 0; }

/* Feed */
.orv-ai-feed {
  flex: 1; overflow-y: auto; padding: 16px;
  display: flex; flex-direction: column; gap: 10px;
}

/* Greeting */
.orv-ai-greeting { display: flex; flex-direction: column; gap: 14px; }
.orv-ai-greeting-text {
  font-size: 17px; font-weight: 800; letter-spacing: -.03em;
  color: var(--charcoal); line-height: 1.2; margin-top: 4px;
}
body.dark-mode .orv-ai-greeting-text { color: rgba(255,255,255,.95); }
.orv-ai-greeting-sub { font-size: 12px; color: var(--muted); margin-top: -8px; font-weight: 500; }

/* Recommendation cards */
.orv-ai-rec-list { display: flex; flex-direction: column; gap: 8px; }

@keyframes oliviaRecIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
.orv-ai-rec-stagger {
  animation: oliviaRecIn .35s cubic-bezier(.22,.61,.36,1) both;
  animation-delay: calc(var(--i, 0) * 80ms + 60ms);
}

.orv-ai-rec-card {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  transition: border-color .14s, box-shadow .14s;
}
.orv-ai-rec-card:hover { border-color: color-mix(in srgb, var(--green) 35%, transparent); box-shadow: 0 2px 12px color-mix(in srgb, var(--green) 6%, transparent); }
body.dark-mode .orv-ai-rec-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
body.dark-mode .orv-ai-rec-card:hover { border-color: color-mix(in srgb, var(--green) 25%, transparent); }

.orv-ai-rec-icon {
  width: 30px; height: 30px; border-radius: 8px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
}
.orv-ai-rec-icon-warn  { background: rgba(251,191,36,.12); color: #92610a; }
.orv-ai-rec-icon-green { background: color-mix(in srgb, var(--green) 12%, transparent); color: var(--green-text); }
.orv-ai-rec-icon-blue  { background: rgba(99,179,237,.12); color: #2563eb; }
.orv-ai-rec-icon-gold  { background: rgba(253,224,71,.12); color: #854d0e; }
body.dark-mode .orv-ai-rec-icon-warn  { color: #fbbf24; }
body.dark-mode .orv-ai-rec-icon-green { color: var(--green); }
body.dark-mode .orv-ai-rec-icon-blue  { color: #60a5fa; }
body.dark-mode .orv-ai-rec-icon-gold  { color: #fcd34d; }

.orv-ai-rec-body { flex: 1; min-width: 0; }
.orv-ai-rec-label { font-size: 12px; font-weight: 700; color: var(--charcoal); letter-spacing: -.01em; margin-bottom: 2px; }
body.dark-mode .orv-ai-rec-label { color: rgba(255,255,255,.9); }
.orv-ai-rec-desc { font-size: 11px; color: var(--muted); line-height: 1.45; }

.orv-ai-rec-action {
  font-size: 11px; font-weight: 700; color: var(--green-text);
  background: color-mix(in srgb, var(--green) 10%, transparent); border: 1px solid color-mix(in srgb, var(--green) 25%, transparent);
  border-radius: 7px; padding: 4px 9px; cursor: pointer; white-space: nowrap;
  transition: background .12s, border-color .12s;
}
.orv-ai-rec-action:hover { background: color-mix(in srgb, var(--green) 20%, transparent); border-color: color-mix(in srgb, var(--green) 45%, transparent); }
body.dark-mode .orv-ai-rec-action { color: var(--green); background: color-mix(in srgb, var(--green) 8%, transparent); border-color: color-mix(in srgb, var(--green) 20%, transparent); }

/* Section divider */
.orv-ai-section-divider {
  display: flex; align-items: center; gap: 10px;
  font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em;
  color: var(--muted); margin-top: 4px;
}
.orv-ai-section-divider::before,.orv-ai-section-divider::after {
  content: ''; flex: 1; height: 1px; background: var(--border, rgba(0,0,0,.07));
}
body.dark-mode .orv-ai-section-divider::before, body.dark-mode .orv-ai-section-divider::after { background: rgba(255,255,255,.07); }

/* Chat messages */
.orv-ai-msg { display: flex; flex-direction: column; gap: 4px; }
.orv-ai-msg-user .orv-ai-msg-bubble {
  align-self: flex-end;
  background: color-mix(in srgb, var(--green) 12%, transparent); color: var(--charcoal);
  border-radius: 12px 12px 3px 12px;
}
body.dark-mode .orv-ai-msg-user .orv-ai-msg-bubble { background: color-mix(in srgb, var(--green) 12%, transparent); color: rgba(255,255,255,.9); }
.orv-ai-msg-ai .orv-ai-msg-bubble {
  align-self: flex-start;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 3px 12px 12px 12px; color: var(--charcoal);
}
body.dark-mode .orv-ai-msg-ai .orv-ai-msg-bubble { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.85); }
.orv-ai-msg-bubble { padding: 9px 13px; font-size: 13px; line-height: 1.55; max-width: 100%; white-space: pre-wrap; }
.orv-ai-used-context {
  align-self: flex-start; font-size: 10.5px; color: var(--muted);
  padding: 0 4px; max-width: 100%; overflow-wrap: break-word;
}
body.dark-mode .orv-ai-used-context { color: rgba(255,255,255,.4); }

/* Action cards — Tool Router confirmation flow */
.orv-ai-action-card { padding: 12px 13px 11px; }
.orv-ai-action-card-summary { font-size: 13px; line-height: 1.5; color: var(--charcoal); }
body.dark-mode .orv-ai-action-card-summary { color: rgba(255,255,255,.9); }
.orv-ai-action-card-actions { display: flex; gap: 8px; margin-top: 10px; }
.orv-ai-action-btn {
  flex: 1; padding: 7px 10px; font-size: 12.5px; font-weight: 600;
  border-radius: 8px; cursor: pointer; transition: opacity .12s, transform .12s;
  border: 1px solid var(--border); background: transparent; color: var(--charcoal);
}
body.dark-mode .orv-ai-action-btn { border-color: rgba(255,255,255,.12); color: rgba(255,255,255,.85); }
.orv-ai-action-btn:hover { opacity: .82; transform: scale(1.02); }
.orv-ai-action-apply { background: var(--green); border-color: var(--green); color: #000; }
.orv-ai-action-success { color: #4a9d5f; border-color: rgba(74,157,95,.3) !important; background: rgba(74,157,95,.08) !important; }
body.dark-mode .orv-ai-action-success { color: #7fe89a; }
.orv-ai-action-error { color: #d9534f; border-color: rgba(217,83,79,.3) !important; background: rgba(217,83,79,.08) !important; }
body.dark-mode .orv-ai-action-error { color: #ff8b87; }

/* Thinking indicator */
.orv-ai-thinking-dots { display: inline-flex; gap: 4px; align-items: center; padding: 2px 0; }
.orv-ai-thinking-dots span {
  width: 5px; height: 5px; border-radius: 50%; background: var(--muted);
  animation: oliviaThinkDot 1.2s ease-in-out infinite;
}
.orv-ai-thinking-dots span:nth-child(2) { animation-delay: .15s; }
.orv-ai-thinking-dots span:nth-child(3) { animation-delay: .3s; }
@keyframes oliviaThinkDot {
  0%,60%,100% { transform: translateY(0); opacity: .3; }
  30%          { transform: translateY(-4px); opacity: 1; }
}

/* Input area */
.orv-ai-input-wrap {
  display: flex; gap: 8px; align-items: flex-end;
  padding: 12px 14px;
  border-top: 1px solid var(--border, rgba(0,0,0,.07)); flex-shrink: 0;
}
body.dark-mode .orv-ai-input-wrap { border-top-color: rgba(255,255,255,.07); }
.orv-ai-input {
  flex: 1; background: rgba(0,0,0,.03); border: 1px solid var(--border);
  border-radius: 10px; padding: 8px 11px; font-size: 13px; color: var(--charcoal);
  resize: none; font-family: inherit; line-height: 1.4; max-height: 100px; overflow-y: auto;
}
body.dark-mode .orv-ai-input { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.9); }
.orv-ai-input:focus { outline: none; border-color: color-mix(in srgb, var(--green) 50%, transparent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 6%, transparent); }
.orv-ai-input::placeholder { color: var(--muted); }
.orv-ai-send {
  width: 34px; height: 34px; border-radius: 9px; background: var(--green); color: #000;
  border: none; cursor: pointer; display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; transition: opacity .12s, transform .12s;
}
.orv-ai-send:hover { opacity: .88; transform: scale(1.04); }
.orv-ai-send:disabled { opacity: .35; cursor: default; transform: none; }

/* Floating button */
/* ── Smart Notifications (V6 Final Phase) ────────────────────────── */
.orv-notif-bell {
  position: fixed; top: 20px; right: 24px; z-index: 210;
  width: 36px; height: 36px; border-radius: 10px;
  background: var(--surface); border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center; cursor: pointer;
  color: var(--charcoal); transition: border-color .15s;
}
body.dark-mode .orv-notif-bell { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.85); }
.orv-notif-bell:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.orv-notif-count {
  position: absolute; top: -5px; right: -5px;
  min-width: 16px; height: 16px; padding: 0 3px; border-radius: 8px;
  background: #ef4444; color: #fff; font-size: 10px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}
.orv-notif-panel {
  position: fixed; top: 62px; right: 24px; z-index: 210;
  width: 320px; max-height: 420px; overflow-y: auto;
  background: var(--surface); border: 1px solid var(--border); border-radius: 14px;
  box-shadow: 0 12px 40px rgba(0,0,0,.14);
}
body.dark-mode .orv-notif-panel { background: #111113; border-color: rgba(255,255,255,.08); }
.orv-notif-hd {
  position: sticky; top: 0; z-index: 1;
  display: flex; align-items: center; justify-content: space-between;
  font-size: 13px; font-weight: 700; padding: 12px 14px; color: var(--charcoal);
  background: var(--surface); border-bottom: 1px solid var(--border);
}
body.dark-mode .orv-notif-hd { color: rgba(255,255,255,.92); background: #111113; border-color: rgba(255,255,255,.08); }
.orv-notif-hd-actions { display: flex; align-items: center; gap: 10px; }
.orv-notif-markall { font-size: 11px; font-weight: 600; color: var(--muted, #888); background: none; border: none; cursor: pointer; padding: 2px 4px; }
.orv-notif-markall:hover { color: var(--charcoal); }
body.dark-mode .orv-notif-markall:hover { color: rgba(255,255,255,.9); }
/* "Clear inbox" — deliberately separate from "Mark all read" both in
   wording and hover color (destructive red vs. neutral) so the two
   actions can't be confused: one changes read state, the other removes
   notifications permanently. */
.orv-notif-clearall { font-size: 11px; font-weight: 600; color: var(--muted, #888); background: none; border: none; cursor: pointer; padding: 2px 4px; }
.orv-notif-clearall:hover { color: #ef4444; }
body.dark-mode .orv-notif-clearall:hover { color: #f87171; }

/* Per-notification delete — small, subtle, icon-only so it never competes
   visually with the notification content itself; only firms up into an
   obvious "destructive" affordance (red tint) on hover, not at rest. */
.orv-notif-del {
  align-self: flex-start; display: flex; align-items: center; justify-content: center;
  background: none; border: none; cursor: pointer; padding: 4px; border-radius: 5px;
  color: var(--muted); opacity: .5; flex-shrink: 0;
  transition: opacity .15s, background .15s, color .15s;
}
.orv-notif-del:hover { opacity: 1; background: rgba(239,68,68,.1); color: #ef4444; }
body.dark-mode .orv-notif-del:hover { background: rgba(239,68,68,.16); color: #f87171; }

/* Notification items -- unread emphasis + severity dot (info/success/
   warning/critical), Final Polish notification rewrite. */
.orv-notif-item { cursor: pointer; position: relative; }
.orv-notif-item.orv-notif-unread { background: color-mix(in srgb, var(--green) 6%, transparent); }
.orv-notif-sev-dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; margin-right: 2px; background: rgba(120,120,120,.5); }
.orv-notif-sev-info .orv-notif-sev-dot { background: #60a5fa; }
.orv-notif-sev-success .orv-notif-sev-dot { background: #34d399; }
.orv-notif-sev-warning .orv-notif-sev-dot { background: #fbbf24; }
.orv-notif-sev-critical .orv-notif-sev-dot { background: #ef4444; }

.orv-ai-fab {
  position: fixed; bottom: 24px; right: 24px; z-index: 200;
  display: flex; align-items: center; gap: 7px;
  padding: 10px 18px 10px 14px;
  background: var(--green); color: #000;
  border: none; border-radius: 50px; cursor: pointer;
  font-size: 13px; font-weight: 800; letter-spacing: -.02em;
  box-shadow: 0 4px 20px color-mix(in srgb, var(--green) 35%, transparent), 0 2px 8px rgba(0,0,0,.12);
  transition: transform .18s cubic-bezier(.22,.61,.36,1), box-shadow .18s;
}
.orv-ai-fab:hover { transform: translateY(-2px); box-shadow: 0 8px 28px color-mix(in srgb, var(--green) 45%, transparent), 0 4px 12px rgba(0,0,0,.1); }
body.dark-mode .orv-ai-fab { background: var(--green); color: #000; }
.orv-ai-fab.orv-ai-fab-hidden { display: none; }
.orv-ai-fab-dot {
  width: 7px; height: 7px; border-radius: 50%; background: rgba(0,0,0,.35); flex-shrink: 0;
  animation: oliviaFabDot 2.4s ease-in-out infinite;
}
@keyframes oliviaFabDot {
  0%,100% { opacity: 1; transform: scale(1); }
  50%      { opacity: .5; transform: scale(0.7); }
}
.orv-ai-fab-label { letter-spacing: -.02em; }

/* ── Page wrapper ────────────────────────────────────────────── */
.orv-page-wrap {
  max-width: var(--orv-content-maxw);
  margin: 0 auto;
  padding: var(--orv-content-pad-top) var(--orv-content-pad-x) var(--orv-content-pad-bottom);
}

.orv-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: var(--orv-title-gap);
  gap: 20px;
}
.orv-ph-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--charcoal, #18181A);
  letter-spacing: -.03em;
  line-height: 1.2;
  margin: 0 0 5px;
}
body.dark-mode .orv-ph-title { color: rgba(255,255,255,.95); }
.orv-ph-sub { font-size: 13px; color: var(--muted); margin: 0; line-height: 1.5; }

.orv-section-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 12px;
}

/* ── Overview layout ─────────────────────────────────────────── */
.orv-platform-strip { display: flex; gap: 6px; flex-wrap: wrap; }
.orv-platform-pill {
  display: flex; align-items: center; gap: 5px;
  padding: 5px 10px;
  border: 1px solid var(--border);
  border-radius: 20px;
  font-size: 11px; font-weight: 600;
  color: var(--muted);
  cursor: pointer; transition: border-color .12s;
  white-space: nowrap;
}
.orv-platform-pill:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
body.dark-mode .orv-platform-pill { border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.5); }
.orv-platform-dot { width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0; }
.orv-platform-dot.connected { background: var(--green); }
.orv-platform-dot.disconnected { background: rgba(128,128,128,.4); }

.orv-kpi-strip {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px,1fr));
  gap: 10px;
  margin-bottom: 32px;
}
.orv-kpi-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
}
body.dark-mode .orv-kpi-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
.orv-kpi-val { font-size: 24px; font-weight: 800; color: var(--charcoal); letter-spacing: -.04em; margin-bottom: 4px; }
body.dark-mode .orv-kpi-val { color: rgba(255,255,255,.95); }
.orv-kpi-val.orv-accent { color: var(--green); }
.orv-kpi-lbl { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .07em; color: var(--muted); }

.orv-two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; }

.orv-insights-list { display: flex; flex-direction: column; gap: 8px; }
.orv-insight-card {
  background: var(--surface); border: 1px solid var(--border); border-radius: 12px;
  padding: 14px 16px; cursor: pointer; transition: border-color .12s;
}
.orv-insight-card:hover { border-color: color-mix(in srgb, var(--green) 30%, transparent); }
body.dark-mode .orv-insight-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
.orv-insight-empty {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 16px; border: 1.5px dashed var(--border); border-radius: 12px;
