}
.orv-insight-empty:hover { border-color: color-mix(in srgb, var(--green) 35%, transparent); }
.orv-insight-empty svg { flex-shrink: 0; opacity: .6; margin-top: 2px; }
.orv-insight-empty-title { font-size: 13px; font-weight: 600; color: var(--charcoal); margin-bottom: 4px; }
body.dark-mode .orv-insight-empty-title { color: rgba(255,255,255,.8); }
.orv-insight-empty-sub { font-size: 12px; color: var(--muted); line-height: 1.5; }

.orv-quick-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.orv-qa-btn {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 14px;
  background: var(--surface); border: 1px solid var(--border); border-radius: 12px;
  font-size: 12px; font-weight: 600; color: var(--charcoal); text-align: left;
  cursor: pointer; transition: border-color .12s;
}
.orv-qa-btn:hover { border-color: color-mix(in srgb, var(--green) 35%, transparent); }
body.dark-mode .orv-qa-btn { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); color: rgba(255,255,255,.8); }
.orv-qa-btn svg { flex-shrink: 0; opacity: .6; }

/* ── Create workflow ─────────────────────────────────────────── */
.orv-create-shell { max-width: 680px; }

.orv-steps {
  display: flex;
  align-items: center;
  gap: 0;
  margin-bottom: 40px;
  overflow-x: auto;
  padding-bottom: 2px;
}
.orv-step {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}
.orv-step-num {
  width: 26px; height: 26px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 800;
  background: rgba(0,0,0,.06);
  color: var(--muted);
  flex-shrink: 0;
}
body.dark-mode .orv-step-num { background: rgba(255,255,255,.08); color: rgba(255,255,255,.4); }
.orv-step-lbl { font-size: 12px; font-weight: 500; color: var(--muted); }
.orv-step.orv-step-active .orv-step-num { background: var(--green); color: #000; }
.orv-step.orv-step-active .orv-step-lbl { color: var(--charcoal); font-weight: 600; }
body.dark-mode .orv-step.orv-step-active .orv-step-lbl { color: rgba(255,255,255,.9); }
.orv-step.orv-step-done .orv-step-num { background: color-mix(in srgb, var(--green) 15%, transparent); color: var(--green-text); }
body.dark-mode .orv-step.orv-step-done .orv-step-num { color: var(--green); background: color-mix(in srgb, var(--green) 10%, transparent); }
.orv-step-line { flex: 1; height: 1px; background: var(--border); margin: 0 10px; min-width: 20px; }

.orv-create-step-title { font-size: 18px; font-weight: 700; color: var(--charcoal); letter-spacing: -.02em; margin-bottom: 8px; }
body.dark-mode .orv-create-step-title { color: rgba(255,255,255,.95); }
.orv-create-step-sub { font-size: 13px; color: var(--muted); margin-bottom: 22px; line-height: 1.5; }
.orv-create-textarea {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px 16px;
  font-size: 14px;
  color: var(--charcoal);
  font-family: inherit;
  resize: vertical;
  line-height: 1.6;
  transition: border-color .15s;
  box-sizing: border-box;
}
body.dark-mode .orv-create-textarea { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.9); }
.orv-create-textarea:focus { outline: none; border-color: color-mix(in srgb, var(--green) 50%, transparent); }
.orv-create-textarea::placeholder { color: var(--muted); }
.orv-create-actions { display: flex; gap: 10px; margin-top: 24px; }

.orv-goal-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px,1fr)); gap: 10px; }
.orv-goal-card {
  background: var(--surface);
  border: 1.5px solid var(--border);
  border-radius: 14px;
  padding: 18px 16px;
  text-align: left;
  cursor: pointer;
  transition: border-color .15s, background .12s;
}
.orv-goal-card:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.orv-goal-card.selected { border-color: var(--green); background: color-mix(in srgb, var(--green) 6%, transparent); }
body.dark-mode .orv-goal-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.09); }
body.dark-mode .orv-goal-card.selected { border-color: var(--green); background: color-mix(in srgb, var(--green) 7%, transparent); }
.orv-goal-icon { margin-bottom: 12px; color: var(--muted); }
.orv-goal-card.selected .orv-goal-icon { color: var(--green-text); }
body.dark-mode .orv-goal-card.selected .orv-goal-icon { color: var(--green); }
.orv-goal-name { font-size: 13px; font-weight: 700; color: var(--charcoal); margin-bottom: 4px; }
body.dark-mode .orv-goal-name { color: rgba(255,255,255,.9); }
.orv-goal-desc { font-size: 11px; color: var(--muted); line-height: 1.4; }

.orv-platform-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; }
.orv-platform-card {
  background: var(--surface);
  border: 1.5px solid var(--border);
  border-radius: 14px;
  padding: 18px 16px;
  text-align: left;
  cursor: pointer;
  transition: border-color .15s;
  position: relative;
}
.orv-platform-card:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.orv-platform-card.selected { border-color: var(--green); }
body.dark-mode .orv-platform-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.09); }
.orv-platform-card-name { font-size: 13px; font-weight: 700; color: var(--charcoal); margin-top: 10px; margin-bottom: 3px; }
body.dark-mode .orv-platform-card-name { color: rgba(255,255,255,.9); }
.orv-platform-card-sub { font-size: 11px; color: var(--muted); }
.orv-platform-check {
  position: absolute; top: 10px; right: 10px;
  width: 18px; height: 18px; border-radius: 50%;
  background: color-mix(in srgb, var(--green) 12%, transparent);
  display: flex; align-items: center; justify-content: center;
  opacity: 0; transition: opacity .12s;
}
.orv-platform-card.selected .orv-platform-check { opacity: 1; color: var(--green-text); }
body.dark-mode .orv-platform-card.selected .orv-platform-check { color: var(--green); background: color-mix(in srgb, var(--green) 12%, transparent); }

/* Generated ad output */
.orv-gen-header {
  display: flex; align-items: flex-start; justify-content: space-between;
  margin-bottom: 28px; gap: 16px;
}
.orv-gen-title { font-size: 18px; font-weight: 700; color: var(--charcoal); letter-spacing: -.02em; }
body.dark-mode .orv-gen-title { color: rgba(255,255,255,.95); }
.orv-gen-meta { font-size: 12px; color: var(--muted); margin-top: 4px; }
.orv-gen-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 28px; }
.orv-gen-section-label {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em;
  color: var(--muted); margin-bottom: 14px;
}
.orv-gen-asset-group { margin-bottom: 18px; }
.orv-gen-asset-label {
  font-size: 11px; font-weight: 600; color: var(--muted); margin-bottom: 7px;
}
.orv-gen-asset-item {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 13px;
  color: var(--charcoal);
  line-height: 1.5;
  margin-bottom: 6px;
  cursor: text;
  outline: none;
  transition: border-color .12s;
}
body.dark-mode .orv-gen-asset-item { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.85); }
.orv-gen-asset-item:focus { border-color: color-mix(in srgb, var(--green) 45%, transparent); }

.orv-publish-bar {
  background: color-mix(in srgb, var(--green) 7%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius: 14px;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
body.dark-mode .orv-publish-bar { background: color-mix(in srgb, var(--green) 5%, transparent); border-color: color-mix(in srgb, var(--green) 15%, transparent); }
.orv-publish-label { font-size: 13px; font-weight: 600; color: var(--charcoal); }
body.dark-mode .orv-publish-label { color: rgba(255,255,255,.9); }
.orv-publish-btns { display: flex; gap: 8px; flex-wrap: wrap; }

/* ── Reports page ────────────────────────────────────────────── */
.orv-reports-grid { display: grid; grid-template-columns: repeat(auto-fill,minmax(250px,1fr)); gap: 14px; }
.orv-report-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px 20px 16px;
  cursor: pointer;
  transition: border-color .15s;
}
.orv-report-card:hover { border-color: color-mix(in srgb, var(--green) 35%, transparent); }
body.dark-mode .orv-report-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
.orv-report-ico {
  width: 40px; height: 40px; border-radius: 11px;
  background: color-mix(in srgb, var(--green) 8%, transparent);
  color: var(--green-text);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 14px;
}
body.dark-mode .orv-report-ico { color: var(--green); background: color-mix(in srgb, var(--green) 8%, transparent); }
.orv-report-name { font-size: 14px; font-weight: 700; color: var(--charcoal); margin-bottom: 6px; letter-spacing: -.01em; }
body.dark-mode .orv-report-name { color: rgba(255,255,255,.9); }
.orv-report-desc { font-size: 12px; color: var(--muted); line-height: 1.55; margin-bottom: 14px; }
.orv-report-tag {
  display: inline-block;
  font-size: 10px; font-weight: 700; letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 8px; border-radius: 5px;
  background: rgba(0,0,0,.05); color: var(--muted);
}
body.dark-mode .orv-report-tag { background: rgba(255,255,255,.06); }

/* ── Performance page wrapper ────────────────────────────────── */
#page-performance .orv-page-wrap { padding-bottom: 0; }
#page-performance .ads-page { padding-top: 0; }

/* ── Responsive ──────────────────────────────────────────────── */
/* The icon-only collapsed sidebar (64px rail, labels hidden) that used to
   live here at <=900px has been removed entirely per the "Responsive
   Navigation" sprint — there are now exactly two nav modes: full sidebar
   above the drawer breakpoint (see .orv-sb display:none below), hamburger
   + drawer at or below it. No intermediate icon-only state. */
@media (max-width: 900px) {
  .orv-ai-panel.orv-ai-open { width: 300px; min-width: 300px; }
  .orv-two-col { grid-template-columns: 1fr; }
  .orv-platform-grid { grid-template-columns: 1fr; }
  .orv-gen-grid { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .orv-page-wrap { padding: 24px 18px 60px; }
  .orv-goal-grid { grid-template-columns: 1fr 1fr; }
}
/* AI panel full-screen slide-over — moved to the canonical 768px mobile
   cutover (was bundled into the 600px block above with unrelated Launch
   rules) and z-index raised from 300 to 9250: the sidebar rail is
   z-index:9200 !important and is never removed below 900px on its own, so
   at 300 the "full-screen" panel was rendering underneath it. 9250 clears
   the sidebar while staying below the onboarding tour's 9300/9301. */
@media (max-width: 768px) {
  .orv-ai-panel.orv-ai-open { width: 100vw; min-width: 100vw; position: fixed; right: 0; top: 0; z-index: 9250; }
  .orv-ai-fab { bottom: 16px; right: 16px; padding: 10px; border-radius: 50%; }
  .orv-ai-fab-label { display: none; }
}

/* ── Mobile/tablet nav: hamburger + slide-out drawer, replacing .orv-sb
   below the unified drawer breakpoint (1024px — see the @media rule at the
   bottom of this section) ────────────────────────────────────────────────
   Exactly two nav modes app-wide: full sidebar above 1024px, hamburger+
   drawer at or below it. No intermediate icon-only rail (removed above).
   1024px chosen as "where the interface genuinely stops behaving like a
   desktop": it's iPad Pro 12.9" portrait width, the standard tablet/laptop
   boundary, and already used elsewhere in this file as the "tablet-lg"
   tier. Landscape tablets wider than that (iPad Air/Pro landscape, Surface
   landscape) get the real sidebar, matching "Desktop/Laptop: exactly like
   today" — only portrait/narrow tablet and phone widths get the drawer.
   New class names only, does not touch either existing .orv-sb block
   (24059/24713 range — that duplication is pre-existing and out of scope
   here). Off-canvas slide-in adapted from the same approach the retired
   .sb drawer already used (left:-Npx -> left:0, .25s ease, dark overlay). */
.orv-mob-toggle {
  display: none;
  position: fixed; top: 12px; left: 12px; z-index: 9215;
  width: 44px; height: 44px;
  align-items: center; justify-content: center;
  background: var(--surface); border: 1px solid var(--border); border-radius: 10px;
  color: var(--charcoal); cursor: pointer; box-shadow: var(--shm);
}
body.dark-mode .orv-mob-toggle { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.09); color: rgba(255,255,255,.85); }
/* Applied by _orvDrawerOpen/_orvDrawerClose (app.html) — the hamburger and
   the drawer's own close (X) button must never both be visible at once.
   Two classes on the same element beats the single-class @media rule
   below by specificity alone, no !important needed. */
.orv-mob-toggle.orv-mob-toggle-hidden { display: none; }

.orv-mob-drawer-overlay {
  display: none; position: fixed; inset: 0;
  background: rgba(0,0,0,.45); z-index: 9205;
  opacity: 0; transition: opacity .25s ease;
}
.orv-mob-drawer-overlay.open { display: block; }
.orv-mob-drawer-overlay.open.active { opacity: 1; }

.orv-mob-drawer {
  display: none;
  position: fixed; left: -260px; top: 0; height: 100vh; width: 240px;
  z-index: 9210; background: var(--bg, #F6F3EE);
  border-right: 1px solid var(--border); box-shadow: var(--shl);
  transition: left .25s ease;
  flex-direction: column;
}
body.dark-mode .orv-mob-drawer { background: #0E0E0F; border-color: rgba(255,255,255,.07); }
.orv-mob-drawer.open { display: flex; }
.orv-mob-drawer.open.active { left: 0; }

.orv-mob-drawer-hd {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 14px 12px;
}
.orv-mob-drawer-logo { width: 32px; height: 32px; border-radius: 7px; }
.orv-mob-drawer-close {
  width: 32px; height: 32px; display: flex; align-items: center; justify-content: center;
  background: none; border: none; color: var(--muted); cursor: pointer; border-radius: 8px;
}
.orv-mob-drawer-close:hover { background: rgba(0,0,0,.05); }
body.dark-mode .orv-mob-drawer-close:hover { background: rgba(255,255,255,.06); }

.orv-mob-drawer-nav { display: flex; flex-direction: column; gap: 2px; padding: 4px 8px; flex: 1; overflow-y: auto; }
.orv-mob-drawer-bottom { padding: 8px; border-top: 1px solid var(--border); }
body.dark-mode .orv-mob-drawer-bottom { border-color: rgba(255,255,255,.07); }
/* .orv-mob-drawer-nav/.orv-mob-drawer-bottom buttons reuse .orv-ni's own
   visual styling (already defined in the .orv-sb blocks) — only the
   drawer's own chrome and layout are new. */
.orv-mob-drawer .orv-ni { width: 100%; justify-content: flex-start; padding: 10px 12px; min-height: 44px; }
.orv-mob-drawer .orv-ni .orv-ni-label { display: inline !important; }

@media (max-width: 1024px) {
  .orv-sb { display: none !important; } /* base .orv-sb is display:flex !important — must match to win */
  .orv-mob-toggle { display: flex; }
}


/* ══════════════════════════════════════════════════════════════
   OVERVIEW v2 — Command Center redesign
   ══════════════════════════════════════════════════════════════ */

/* ── Sidebar logo: left-aligned, larger ────────────────────── */
.orv-sb-logo-name { display: none !important; }
.orv-sb-logo-img  { width: 40px !important; height: 40px !important; border-radius: 8px !important; }
.orv-sb-logo      { justify-content: flex-start !important; padding: 14px 12px 12px !important; }

/* ── Page wrapper ───────────────────────────────────────────── */
.orv-ov-wrap {
  max-width: 1160px;
  margin: 0 auto;
  padding: 24px 32px 56px;
}

/* ── Header ─────────────────────────────────────────────────── */
.orv-ov-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
}

/* ── Quick actions strip ────────────────────────────────────── */
.orv-ov-actions { display: flex; gap: 6px; flex-shrink: 0; }
.orv-ov-action {
  display: flex; align-items: center; gap: 6px;
  padding: 7px 13px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 12px; font-weight: 600;
  color: var(--muted);
  cursor: pointer;
  transition: border-color .12s, color .12s;
  white-space: nowrap;
  font-family: inherit;
}
.orv-ov-action:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); color: var(--charcoal); }
.orv-ov-action svg { opacity: .7; flex-shrink: 0; }
body.dark-mode .orv-ov-action {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.08);
  color: rgba(255,255,255,.45);
}
body.dark-mode .orv-ov-action:hover { color: rgba(255,255,255,.9); border-color: color-mix(in srgb, var(--green) 40%, transparent); }

/* ── KPI strip ──────────────────────────────────────────────── */
.orv-ov-kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 12px;
}
.orv-ov-kpi {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px 16px;
}
body.dark-mode .orv-ov-kpi {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.07);
}
.orv-ov-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 7px;
}
.orv-ov-kpi-lbl {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.orv-ov-kpi-trend { font-size: 11px; font-weight: 600; }
.orv-trend-up   { color: #3ecf8e; }
.orv-trend-down { color: #f66; }
.orv-trend-flat { color: var(--muted); }
.orv-ov-kpi-val {
  font-size: 26px;
  font-weight: 800;
  color: var(--charcoal);
  letter-spacing: -.04em;
  line-height: 1;
}
body.dark-mode .orv-ov-kpi-val { color: rgba(255,255,255,.95); }
.orv-kpi-accent { color: var(--green-text) !important; }
body.dark-mode .orv-kpi-accent { color: var(--green) !important; }

/* ── Main grid ──────────────────────────────────────────────── */
.orv-ov-main {
  display: grid;
  grid-template-columns: 1fr 292px;
  gap: 12px;
  margin-bottom: 12px;
}

/* ── Campaigns card ─────────────────────────────────────────── */
.orv-ov-campaigns {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
}
body.dark-mode .orv-ov-campaigns {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.07);
}
.orv-ov-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 11px;
  border-bottom: 1px solid var(--border);
}
body.dark-mode .orv-ov-card-head { border-bottom-color: rgba(255,255,255,.06); }
.orv-ov-card-title {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .09em;
  color: var(--muted);
}
.orv-ov-see-all {
  font-size: 11px; font-weight: 500;
  color: var(--muted); background: none; border: none;
  cursor: pointer; padding: 0; font-family: inherit;
  transition: color .12s;
}
.orv-ov-see-all:hover { color: var(--charcoal); }
body.dark-mode .orv-ov-see-all:hover { color: rgba(255,255,255,.85); }

/* Campaign table header */
.orv-ov-camp-thead {
  display: grid;
  grid-template-columns: 1fr 80px 56px 56px;
  gap: 8px;
  padding: 7px 16px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--muted);
  border-bottom: 1px solid var(--border);
  opacity: .6;
}
body.dark-mode .orv-ov-camp-thead { border-bottom-color: rgba(255,255,255,.05); }
.orv-camp-th-r { text-align: right; }

/* Campaign rows */
.orv-ov-camp-row {
  display: grid;
  grid-template-columns: 1fr 80px 56px 56px;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background .1s;
}
.orv-ov-camp-row:last-child { border-bottom: none; }
.orv-ov-camp-row:hover { background: color-mix(in srgb, var(--green) 4%, transparent); }
body.dark-mode .orv-ov-camp-row { border-bottom-color: rgba(255,255,255,.05); }
body.dark-mode .orv-ov-camp-row:hover { background: rgba(255,255,255,.03); }
.orv-ov-camp-name {
  font-size: 12px; font-weight: 600;
  color: var(--charcoal);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
body.dark-mode .orv-ov-camp-name { color: rgba(255,255,255,.88); }
.orv-ov-camp-plat {
  font-size: 11px; color: var(--muted); font-weight: 500;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.orv-ov-camp-stat {
  text-align: right;
  font-size: 12px; font-weight: 700;
  color: var(--charcoal);
}
body.dark-mode .orv-ov-camp-stat { color: rgba(255,255,255,.88); }
.orv-camp-stat-good { color: #3ecf8e !important; }
.orv-camp-stat-warn { color: #ffb43c !important; }

/* ── AI Recommendations card ────────────────────────────────── */
.orv-ov-ai-recs {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  position: relative;
}
body.dark-mode .orv-ov-ai-recs {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.07);
}
/* Top accent line — marks this as the most important card */
.orv-ov-ai-recs::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0; height: 2px;
  background: linear-gradient(90deg, var(--green) 0%, color-mix(in srgb, var(--green) 0%, transparent) 100%);
  border-radius: 14px 14px 0 0;
}

.orv-ov-ai-badge {
  font-size: 9px; font-weight: 800; letter-spacing: .1em;
  background: color-mix(in srgb, var(--green) 13%, transparent);
  color: var(--green-text);
  padding: 2px 7px; border-radius: 20px;
}
body.dark-mode .orv-ov-ai-badge { color: var(--green); background: color-mix(in srgb, var(--green) 14%, transparent); }

/* Rec rows */
.orv-ov-rec-list { display: flex; flex-direction: column; }
.orv-ov-rec {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 11px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background .1s;
}
.orv-ov-rec:last-of-type { border-bottom: none; }
.orv-ov-rec:hover { background: color-mix(in srgb, var(--green) 4%, transparent); }
body.dark-mode .orv-ov-rec { border-bottom-color: rgba(255,255,255,.06); }

/* Ghost state: shown when no account connected */
.orv-ov-rec.orv-rec-ghost { opacity: .3; pointer-events: none; }

.orv-ov-rec-icon {
  width: 26px; height: 26px;
  border-radius: 7px;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800;
  flex-shrink: 0; margin-top: 1px;
}
.orv-rec-green { background: rgba(62,207,142,.12); color: #3ecf8e; }
.orv-rec-red   { background: rgba(246,102,102,.12); color: #f55; }
.orv-rec-blue  { background: rgba(99,179,255,.12);  color: #63b3ff; }
.orv-rec-warn  { background: rgba(255,180,60,.12);  color: #ffb43c; }

.orv-ov-rec-body { flex: 1; min-width: 0; }
.orv-ov-rec-title {
  font-size: 12px; font-weight: 600;
  color: var(--charcoal); line-height: 1.35; margin-bottom: 2px;
}
body.dark-mode .orv-ov-rec-title { color: rgba(255,255,255,.88); }
.orv-ov-rec-sub { font-size: 11px; color: var(--muted); line-height: 1.4; }
.orv-ov-rec-arrow { font-size: 11px; color: var(--muted); flex-shrink: 0; margin-top: 3px; }

/* Connect banner inside rec list */
.orv-ov-rec-connect {
  display: flex; align-items: center; gap: 7px;
  padding: 10px 16px 13px;
  font-size: 11px; font-weight: 600;
  color: var(--muted); cursor: pointer;
  transition: color .12s;
  border-top: 1px dashed var(--border);
  font-family: inherit; background: none;
}
.orv-ov-rec-connect:hover { color: var(--charcoal); }
body.dark-mode .orv-ov-rec-connect:hover { color: rgba(255,255,255,.8); }

/* ── Empty state ────────────────────────────────────────────── */
.orv-ov-empty {
  padding: 28px 20px;
  text-align: center;
  cursor: pointer;
}
.orv-ov-empty-icon { margin-bottom: 8px; }
.orv-ov-empty-title {
  font-size: 12px; font-weight: 600;
  color: var(--charcoal); margin-bottom: 4px;
}
body.dark-mode .orv-ov-empty-title { color: rgba(255,255,255,.55); }
.orv-ov-empty-sub { font-size: 11px; color: var(--muted); line-height: 1.5; }

/* ── Platform status row ────────────────────────────────────── */
.orv-ov-platforms {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.orv-ov-plat {
  display: flex; align-items: center; justify-content: space-between;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 11px 16px;
  cursor: pointer;
  transition: border-color .12s;
}
.orv-ov-plat:hover { border-color: color-mix(in srgb, var(--green) 30%, transparent); }
body.dark-mode .orv-ov-plat {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.07);
}
.orv-ov-plat-left { display: flex; align-items: center; gap: 10px; }
.orv-ov-plat-name { font-size: 12px; font-weight: 600; color: var(--charcoal); line-height: 1.3; }
body.dark-mode .orv-ov-plat-name { color: rgba(255,255,255,.85); }
.orv-ov-plat-meta { font-size: 11px; color: var(--muted); margin-top: 1px; }
.orv-ov-plat-status { font-size: 11px; color: var(--muted); font-weight: 500; white-space: nowrap; }
.orv-ov-plat-status.connected { color: #3ecf8e; }

/* ── Responsive ─────────────────────────────────────────────── */
@media (max-width: 1024px) {
  .orv-ov-main { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  .orv-ov-wrap { padding: 16px 16px 40px; }
  .orv-ov-kpis { grid-template-columns: repeat(2, 1fr); }
  .orv-ov-platforms { grid-template-columns: 1fr; }
  .orv-ov-actions { display: none; }
  .orv-ov-header { margin-bottom: 14px; }
}


/* ══════════════════════════════════════════════════════════════
   OVERVIEW v3 — Expanded viewport, platform filters
   ══════════════════════════════════════════════════════════════ */

/* ── Remove centering constraint, fill the viewport ────────── */
.orv-ov-wrap {
  max-width: none !important;
  padding: 22px 28px 44px !important;
}

/* ── KPI source label row ───────────────────────────────────── */
.orv-ov-kpi-source-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}
.orv-ov-kpi-source {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .09em;
  color: var(--muted);
}
.orv-ov-kpi-clear {
  font-size: 11px;
  font-weight: 600;
  color: var(--muted);
  background: none;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 2px 8px;
  cursor: pointer;
  font-family: inherit;
  transition: color .12s, border-color .12s;
}
.orv-ov-kpi-clear:hover { color: var(--charcoal); border-color: color-mix(in srgb, var(--green) 40%, transparent); }
body.dark-mode .orv-ov-kpi-clear { border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.4); }
body.dark-mode .orv-ov-kpi-clear:hover { color: rgba(255,255,255,.85); border-color: color-mix(in srgb, var(--green) 40%, transparent); }

/* ── KPI cards — slightly taller, larger values ─────────────── */
.orv-ov-kpis { gap: 10px; margin-bottom: 12px; }
.orv-ov-kpi  { padding: 16px 18px 14px !important; }
.orv-ov-kpi-val { font-size: 30px !important; }

/* ── Main grid — campaigns fill available width ─────────────── */
.orv-ov-main { grid-template-columns: 1fr 308px !important; gap: 10px !important; margin-bottom: 10px !important; }

/* ── Campaign list — taller, scrollable ─────────────────────── */
.orv-ov-camp-list {
  min-height: 300px;
  max-height: 460px;
  overflow-y: auto;
}
.orv-ov-camp-list::-webkit-scrollbar { width: 4px; }
.orv-ov-camp-list::-webkit-scrollbar-track { background: transparent; }
.orv-ov-camp-list::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }

/* ── AI rec list — taller to match campaigns ─────────────────── */
.orv-ov-ai-recs .orv-ov-rec-list {
  min-height: 300px;
}

/* ══════════════════════════════════════════════════════════════
   PLATFORM FILTER CARDS — full redesign
   ══════════════════════════════════════════════════════════════ */

/* Override old flat layout with vertical card layout */
.orv-ov-platforms { gap: 10px; }

.orv-ov-plat {
  flex-direction: column !important;
  align-items: stretch !important;
  justify-content: flex-start !important;
  gap: 12px !important;
  padding: 14px 16px !important;
  border-radius: 13px !important;
  cursor: pointer;
  transition: border-color .15s, opacity .15s, background .15s !important;
  user-select: none;
}

/* Platform card head row */
.orv-ov-plat-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.orv-ov-plat-name {
  font-size: 13px !important;
  font-weight: 700 !important;
  flex: 1;
}
.orv-ov-plat-filter-hint {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--muted);
  opacity: 0;
  transition: opacity .15s;
}
.orv-ov-plat:hover .orv-ov-plat-filter-hint { opacity: 1; }

/* Stats block inside card */
.orv-ov-plat-stats {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.orv-ov-plat-stat {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}
.orv-ov-plat-stat-lbl {
  font-size: 11px;
  color: var(--muted);
  font-weight: 500;
}
.orv-ov-plat-stat-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--charcoal);
}
body.dark-mode .orv-ov-plat-stat-val { color: rgba(255,255,255,.88); }

/* Status value colour */
.orv-ov-plat-status.connected { color: #3ecf8e !important; }
body.dark-mode .orv-ov-plat-status:not(.connected) { color: rgba(255,255,255,.35) !important; }

/* ── Filter states ───────────────────────────────────────────── */

/* Default: all active */
.orv-ov-plat.orv-plat-active {
  border-color: var(--border);
  opacity: 1;
}
/* Active filter — selected card gets accent border + faint bg */
.orv-ov-plat.orv-plat-active.orv-plat-selected {
  border-color: color-mix(in srgb, var(--green) 55%, transparent) !important;
  background: color-mix(in srgb, var(--green) 4%, transparent) !important;
}
body.dark-mode .orv-ov-plat.orv-plat-active.orv-plat-selected {
  background: color-mix(in srgb, var(--green) 6%, transparent) !important;
}
/* Dimmed: non-selected platforms when a filter is active */
.orv-ov-plat.orv-plat-dim {
  opacity: .38 !important;
  border-color: var(--border) !important;
  background: var(--surface) !important;
}

/* ── Responsive ─────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .orv-ov-main { grid-template-columns: 1fr 280px !important; }
}
@media (max-width: 900px) {
  .orv-ov-main { grid-template-columns: 1fr !important; }
  .orv-ov-camp-list { max-height: 300px; }
}
@media (max-width: 700px) {
  .orv-ov-wrap { padding: 14px 14px 36px !important; }
  .orv-ov-kpis { grid-template-columns: repeat(2,1fr) !important; }
  .orv-ov-platforms { grid-template-columns: 1fr !important; }
  .orv-ov-actions { display: none; }
}


/* ══════════════════════════════════════════════════════════════
   OVERVIEW v4 — Visual energy: strategic color + hierarchy
   ══════════════════════════════════════════════════════════════ */

/* ── Platform icon badges ───────────────────────────────────── */
.orv-plat-icon {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 900;
  flex-shrink: 0;
  letter-spacing: -.01em;
  font-style: normal;
  line-height: 1;
}

/* Light mode */
.orv-plat-icon-google {
  background: rgba(251,188,4,.12);
  color: #b8860b;
  border: 1px solid rgba(251,188,4,.25);
}
.orv-plat-icon-meta {
  background: rgba(24,119,242,.1);
  color: #1a6ed8;
  border: 1px solid rgba(24,119,242,.2);
}
.orv-plat-icon-tiktok {
  background: rgba(254,44,85,.09);
  color: #c81e3d;
  border: 1px solid rgba(254,44,85,.18);
}

/* Dark mode */
body.dark-mode .orv-plat-icon-google {
  background: rgba(251,188,4,.1);
  color: #FBBC04;
  border-color: rgba(251,188,4,.2);
}
body.dark-mode .orv-plat-icon-meta {
  background: rgba(24,119,242,.1);
  color: #5da8ff;
  border-color: rgba(24,119,242,.2);
}
body.dark-mode .orv-plat-icon-tiktok {
  background: rgba(254,44,85,.1);
  color: #ff6b7a;
  border-color: rgba(254,44,85,.16);
}

/* ── Platform cards: CSS custom property per platform ────────── */
.orv-ov-plat[data-platform="google"] { --pc: 251,188,4; }
.orv-ov-plat[data-platform="meta"]   { --pc: 24,119,242; }
.orv-ov-plat[data-platform="tiktok"] { --pc: 254,44,85; }

/* Position context for ::before accent line */
.orv-ov-plat[data-platform] {
  position: relative;
  overflow: hidden;
}

/* Colored top accent line — always visible */
.orv-ov-plat[data-platform]::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: rgba(var(--pc), 1);
  opacity: .45;
  border-radius: 13px 13px 0 0;
  transition: opacity .15s;
}

/* Hover: colored border + platform-tinted background */
.orv-ov-plat[data-platform]:hover {
  border-color: rgba(var(--pc), .3) !important;
  background: rgba(var(--pc), .03) !important;
}
.orv-ov-plat[data-platform]:hover::before { opacity: .7; }
body.dark-mode .orv-ov-plat[data-platform]:hover {
  background: rgba(var(--pc), .06) !important;
}

/* Selected state: platform color takes over */
.orv-ov-plat[data-platform].orv-plat-selected {
  border-color: rgba(var(--pc), .45) !important;
  background: rgba(var(--pc), .05) !important;
}
.orv-ov-plat[data-platform].orv-plat-selected::before { opacity: .9; }
body.dark-mode .orv-ov-plat[data-platform].orv-plat-selected {
  border-color: rgba(var(--pc), .4) !important;
  background: rgba(var(--pc), .08) !important;
}

/* Filter hint shows in platform color when selected */
.orv-ov-plat[data-platform].orv-plat-selected .orv-ov-plat-filter-hint {
  color: rgba(var(--pc), 1);
  opacity: 1;
}

/* Status "Active" text gets platform color tint */
.orv-ov-plat[data-platform].orv-plat-selected .orv-ov-plat-status.connected {
  color: rgba(var(--pc), .9) !important;
}

/* ── KPI cards: colored top accent by position ───────────────── */
.orv-ov-kpi {
  position: relative;
  overflow: hidden;
}
.orv-ov-kpi::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  border-radius: 12px 12px 0 0;
}

/* Spend — warm yellow */
.orv-ov-kpis .orv-ov-kpi:nth-child(1)::before { background: rgba(251,188,4,.75); }
/* Clicks — cool blue */
.orv-ov-kpis .orv-ov-kpi:nth-child(2)::before { background: rgba(99,179,255,.75); }
/* Conversions — green */
.orv-ov-kpis .orv-ov-kpi:nth-child(3)::before { background: rgba(62,207,142,.75); }
/* ROAS — brand accent */
.orv-ov-kpis .orv-ov-kpi:nth-child(4)::before { background: color-mix(in srgb, var(--green) 80%, transparent); }

/* KPI label: tinted to echo card accent (dark mode only — legible on dark bg) */
body.dark-mode .orv-ov-kpis .orv-ov-kpi:nth-child(1) .orv-ov-kpi-lbl { color: rgba(251,188,4,.55); }
body.dark-mode .orv-ov-kpis .orv-ov-kpi:nth-child(2) .orv-ov-kpi-lbl { color: rgba(99,179,255,.55); }
body.dark-mode .orv-ov-kpis .orv-ov-kpi:nth-child(3) .orv-ov-kpi-lbl { color: rgba(62,207,142,.55); }
body.dark-mode .orv-ov-kpis .orv-ov-kpi:nth-child(4) .orv-ov-kpi-lbl { color: color-mix(in srgb, var(--green) 55%, transparent); }

/* ── Quick action buttons: color-coded ───────────────────────── */
.orv-ov-actions .orv-ov-action {
  position: relative;
  overflow: hidden;
}
/* Colored top line per button */
.orv-ov-actions .orv-ov-action::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1.5px;
}
.orv-ov-actions .orv-ov-action:nth-child(1)::before { background: color-mix(in srgb, var(--green) 65%, transparent); }  /* Create: green */
.orv-ov-actions .orv-ov-action:nth-child(2)::before { background: rgba(99,179,255,.65); }  /* Connect: blue */
.orv-ov-actions .orv-ov-action:nth-child(3)::before { background: rgba(251,188,4,.65); }   /* Performance: yellow */
.orv-ov-actions .orv-ov-action:nth-child(4)::before { background: rgba(168,85,247,.65); }  /* Reports: purple */

/* Colored SVG icons */
.orv-ov-actions .orv-ov-action:nth-child(1) svg { color: var(--green); opacity: .9; }
.orv-ov-actions .orv-ov-action:nth-child(2) svg { color: #63b3ff; opacity: .9; }
.orv-ov-actions .orv-ov-action:nth-child(3) svg { color: #FBBC04; opacity: .9; }
.orv-ov-actions .orv-ov-action:nth-child(4) svg { color: #a855f7; opacity: .9; }

/* Hover: match accent color */
.orv-ov-actions .orv-ov-action:nth-child(1):hover {
  border-color: color-mix(in srgb, var(--green) 35%, transparent) !important;
  background: color-mix(in srgb, var(--green) 4%, transparent) !important;
}
.orv-ov-actions .orv-ov-action:nth-child(2):hover {
  border-color: rgba(99,179,255,.35) !important;
  background: rgba(99,179,255,.04) !important;
}
.orv-ov-actions .orv-ov-action:nth-child(3):hover {
  border-color: rgba(251,188,4,.35) !important;
  background: rgba(251,188,4,.04) !important;
}
.orv-ov-actions .orv-ov-action:nth-child(4):hover {
  border-color: rgba(168,85,247,.35) !important;
  background: rgba(168,85,247,.04) !important;
}

/* ── AI Recommendations: fill full height of main grid ───────── */
.orv-ov-main { align-items: stretch !important; }
.orv-ov-ai-recs {
  display: flex !important;
  flex-direction: column !important;
}
.orv-ov-ai-recs .orv-ov-card-head { flex-shrink: 0; }
.orv-ov-ai-recs .orv-ov-rec-list  { flex: 1; min-height: 0; }

/* ── Campaign card: centerpiece emphasis ─────────────────────── */
.orv-ov-campaigns {
  position: relative;
  overflow: hidden;
}
/* Subtle white top-line — differentiates from AI card's green */
.orv-ov-campaigns::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg,
    rgba(255,255,255,.18) 0%,
    rgba(255,255,255,.06) 50%,
    rgba(255,255,255,0)   100%
  );
  border-radius: 14px 14px 0 0;
}
/* Slightly elevated header */
.orv-ov-campaigns .orv-ov-card-head {
  background: rgba(255,255,255,.015);
}
/* Stronger section label */
.orv-ov-campaigns .orv-ov-card-title {
  letter-spacing: .11em !important;
}

/* Campaign table header: subtle tinted row */
.orv-ov-camp-thead {
  background: rgba(255,255,255,.018);
}
body.dark-mode .orv-ov-camp-thead {
  background: rgba(255,255,255,.022);
}


/* ══════════════════════════════════════════════════════════════
   OVERVIEW v5 — Height expansion, whitespace reduction
   ══════════════════════════════════════════════════════════════ */

/* ── Reduce bottom padding — content fills screen ───────────── */
.orv-ov-wrap { padding-bottom: 20px !important; }

/* ── Active Campaigns: taller list ──────────────────────────── */
.orv-ov-camp-list {
  min-height: 400px !important;
  max-height: 600px !important;
}

/* ── AI panel: taller rec list to match campaigns ────────────── */
.orv-ov-ai-recs .orv-ov-rec-list {
  min-height: 400px !important;
}

/* Empty state: vertically centered in the taller space */
.orv-ov-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 280px;
  padding: 20px !important;
  cursor: default !important;
}

/* Campaign empty state: no pointer cursor since it's not clickable */
#orvCampEmpty { cursor: default !important; }


/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   CONNECT PAGE v1 â€” 3-column integrations grid
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

/* â”€â”€ Page wrapper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-page {
  padding: 28px 32px 48px;
}

/* â”€â”€ Page header â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-hdr { margin-bottom: 28px; }
.conn-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--charcoal);
  margin: 0 0 6px;
  letter-spacing: -.02em;
}
body.dark-mode .conn-title { color: rgba(255,255,255,.92); }
.conn-sub {
  font-size: 13px;
  color: var(--muted);
  margin: 0;
  line-height: 1.55;
  max-width: 540px;
}

/* â”€â”€ 3-column grid â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  align-items: start;
}

/* â”€â”€ Individual card â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
  overflow: hidden;
  transition: border-color .15s;
}
body.dark-mode .conn-card {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.07);
}

/* Platform-color top accent line */
.conn-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: rgba(var(--conn-pc), 1);
  opacity: .45;
  border-radius: 14px 14px 0 0;
}
.conn-card:hover::before { opacity: .75; }

.conn-card-google { --conn-pc: 251,188,4; }
.conn-card-meta   { --conn-pc: 24,119,242; }
.conn-card-tiktok { --conn-pc: 254,44,85; }

/* Subtle hover */
.conn-card:hover {
  border-color: rgba(var(--conn-pc), .3);
}
body.dark-mode .conn-card:hover {
  border-color: rgba(var(--conn-pc), .25);
}

/* â”€â”€ Card head: logo + name + status badge â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-card-head {
  display: flex;
  align-items: center;
  gap: 12px;
}
.conn-logo-wrap {
  flex-shrink: 0;
  border-radius: 10px;
  overflow: hidden;
  line-height: 0;
}
.conn-name-group { flex: 1; min-width: 0; }
.conn-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  letter-spacing: -.015em;
  margin-bottom: 4px;
}
body.dark-mode .conn-name { color: rgba(255,255,255,.92); }

/* â”€â”€ Connected badge â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-badge-on {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .02em;
  color: #3ecf8e;
  background: rgba(62,207,142,.1);
  border: 1px solid rgba(62,207,142,.22);
  padding: 2px 8px 2px 6px;
  border-radius: 20px;
}
.conn-badge-on::before {
  content: '';
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #3ecf8e;
  flex-shrink: 0;
}

/* â”€â”€ Description â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-desc {
  font-size: 12px;
  color: var(--muted);
  line-height: 1.55;
  margin: 0;
}

/* â”€â”€ Connected details block â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-details {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.conn-loading {
  font-size: 12px;
  color: var(--muted);
  padding: 4px 0;
}
.conn-error {
  font-size: 12px;
  color: #ef4444;
  line-height: 1.45;
}

/* Accounts section label */
.conn-accounts-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 8px;
}

/* Compact account list: tighten the existing int-account-row styles */
.conn-accounts-list .int-account-row {
  padding: 8px 10px !important;
  border-radius: 8px !important;
  margin-bottom: 4px;
}
.conn-accounts-list .int-account-row:last-child { margin-bottom: 0; }
.conn-accounts-list .int-account-name { font-size: 12px !important; }
.conn-accounts-list .int-account-id   { font-size: 10px !important; }
.conn-accounts-list .int-account-meta { font-size: 10px !important; }
.conn-accounts-list .int-account-mcc-warn { font-size: 10px !important; }

/* â”€â”€ Details actions: Refresh + Disconnect â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-details-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  padding-top: 2px;
}
.conn-btn-danger {
  color: rgba(239,68,68,.75) !important;
  border-color: rgba(239,68,68,.18) !important;
}
.conn-btn-danger:hover {
  color: #ef4444 !important;
  border-color: rgba(239,68,68,.4) !important;
  background: rgba(239,68,68,.04) !important;
}

/* â”€â”€ Connect button (full-width, disconnected state) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-btn-full {
  width: 100%;
  justify-content: center !important;
  padding: 9px 16px !important;
  font-size: 13px !important;
}

/* â”€â”€ Responsive â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
@media (max-width: 1100px) {
  .conn-grid { grid-template-columns: repeat(2, 1fr); }
  .conn-card-tiktok { grid-column: span 2; max-width: 50%; }
}
@media (max-width: 740px) {
  .conn-page { padding: 16px 16px 40px; }
  .conn-grid { grid-template-columns: 1fr; }
  .conn-card-tiktok { grid-column: span 1; max-width: none; }
}



/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   CONNECT PAGE v2 â€” Equal card heights
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

/* Grid rows stretch all cards to the same height */
.conn-grid { align-items: stretch !important; }

/* â”€â”€ Disconnected state: Connect button pins to bottom â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.conn-btn-full { margin-top: auto !important; }

/* â”€â”€ Connected state: details block fills remaining height â”€â”€â”€â”€â”€ */
.conn-details {
  flex: 1 !important;
}

/* Actions pin to bottom of the details block regardless of account count */
.conn-details-actions { margin-top: auto !important; }



/* ══════════════════════════════════════════════════════════════
   CAMPAIGN CREATION v2 — 5-screen guided experience
   ══════════════════════════════════════════════════════════════ */

/* ── Page & screen container ─────────────────────────────────── */
#page-create {
  height: 100%;
  flex-direction: column;
}
.crv-page {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.crv-screen {
  flex: 1;
  overflow-y: auto;
}
.crv-screen::-webkit-scrollbar { width: 4px; }
.crv-screen::-webkit-scrollbar-track { background: transparent; }
.crv-screen::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }

/* ── Stage (centered content wrapper) ───────────────────────── */
.crv-stage {
  padding: 56px 32px 64px;
  margin: 0 auto;
  width: 100%;
}
.crv-stage-center { max-width: 980px; }
.crv-stage-narrow { max-width: 520px; }
.crv-stage-wide   { max-width: 1100px; }

/* ── Typography ──────────────────────────────────────────────── */
.crv-eyebrow {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--muted);
  margin-bottom: 16px;
}
.crv-h1 {
  font-size: 32px;
  font-weight: 800;
  color: var(--charcoal);
  letter-spacing: -.03em;
  line-height: 1.15;
  margin: 0 0 10px;
}
body.dark-mode .crv-h1 { color: rgba(255,255,255,.95); }
.crv-lead {
  font-size: 14px;
  color: var(--muted);
  margin: 0 0 40px;
  line-height: 1.5;
}

/* ── Navigation row (back + breadcrumb) ──────────────────────── */
.crv-nav-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 32px;
}
.crv-back {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  font-family: inherit;
  transition: color .12s;
  flex-shrink: 0;
}
.crv-back:hover { color: var(--charcoal); }
body.dark-mode .crv-back:hover { color: rgba(255,255,255,.85); }
.crv-breadcrumb {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 3px 10px;
}
body.dark-mode .crv-breadcrumb {
  background: rgba(255,255,255,.05);
  border-color: rgba(255,255,255,.09);
}

/* ══════════════════════════════════════════════════════════════
   SCREEN 1 — Platform Selection
   ══════════════════════════════════════════════════════════════ */

.crv-plat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  max-width: 860px;
}

.crv-plat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 28px 26px 26px;
  cursor: pointer;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
  overflow: hidden;
  transition: transform .18s, border-color .18s, box-shadow .18s;
  font-family: inherit;
}
body.dark-mode .crv-plat-card {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.08);
}

/* Platform color accent line */
.crv-plat-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: rgba(var(--crv-pc), 1);
  opacity: .5;
  border-radius: 18px 18px 0 0;
  transition: opacity .18s, height .18s;
}
.crv-plat-card:hover::before  { opacity: .9; height: 4px; }
.crv-plat-card:hover {
  transform: translateY(-3px);
  border-color: rgba(var(--crv-pc), .35);
  box-shadow: 0 10px 32px rgba(var(--crv-pc), .12);
}
.crv-plat-card.crv-plat-selected {
  border-color: rgba(var(--crv-pc), .5) !important;
  background: rgba(var(--crv-pc), .04) !important;
}
body.dark-mode .crv-plat-card.crv-plat-selected {
  background: rgba(var(--crv-pc), .07) !important;
}

.crv-plat-google { --crv-pc: 251,188,4; }
.crv-plat-meta   { --crv-pc: 24,119,242; }
.crv-plat-tiktok { --crv-pc: 254,44,85; }

.crv-plat-logo {
  line-height: 0;
  border-radius: 10px;
  overflow: hidden;
  width: 48px;
  height: 48px;
  flex-shrink: 0;
}

.crv-plat-name {
  font-size: 18px;
  font-weight: 800;
  color: var(--charcoal);
  letter-spacing: -.02em;
}
body.dark-mode .crv-plat-name { color: rgba(255,255,255,.92); }

.crv-plat-types {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.crv-plat-types li {
  font-size: 12px;
  color: var(--muted);
  font-weight: 500;
  padding-left: 14px;
  position: relative;
}
.crv-plat-types li::before {
  content: '·';
  position: absolute;
  left: 4px;
  color: rgba(var(--crv-pc), 1);
  font-weight: 900;
}

/* ══════════════════════════════════════════════════════════════
   SCREEN 2 — Goal Selection
   ══════════════════════════════════════════════════════════════ */

.crv-goal-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  max-width: 760px;
}

.crv-goal-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px 18px;
  cursor: pointer;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: inherit;
  transition: border-color .14s, background .14s, transform .14s;
  position: relative;
  overflow: hidden;
}
body.dark-mode .crv-goal-card {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.08);
}
.crv-goal-card:hover {
  border-color: color-mix(in srgb, var(--green) 40%, transparent);
  background: color-mix(in srgb, var(--green) 3%, transparent);
  transform: translateY(-1px);
}
.crv-goal-card.crv-selected {
  border-color: color-mix(in srgb, var(--green) 55%, transparent) !important;
  background: color-mix(in srgb, var(--green) 5%, transparent) !important;
}
body.dark-mode .crv-goal-card.crv-selected {
  background: color-mix(in srgb, var(--green) 7%, transparent) !important;
}

.crv-goal-ico {
  color: var(--muted);
  transition: color .14s;
  width: 22px;
  height: 22px;
}
.crv-goal-card:hover .crv-goal-ico,
.crv-goal-card.crv-selected .crv-goal-ico { color: var(--green); }
body.dark-mode .crv-goal-card.crv-selected .crv-goal-ico { color: var(--green); }

.crv-goal-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--charcoal);
  letter-spacing: -.01em;
}
body.dark-mode .crv-goal-name { color: rgba(255,255,255,.9); }
.crv-goal-desc {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.45;
}

/* ══════════════════════════════════════════════════════════════
   SCREEN 3 — Product Details
   ══════════════════════════════════════════════════════════════ */

.crv-fields { display: flex; flex-direction: column; gap: 18px; margin-bottom: 28px; }

.crv-field { display: flex; flex-direction: column; gap: 7px; }
.crv-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--charcoal);
  display: flex;
  align-items: center;
  gap: 8px;
}
body.dark-mode .crv-label { color: rgba(255,255,255,.75); }
.crv-opt {
  font-size: 10px;
  font-weight: 500;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .05em;
}

.crv-input, .crv-textarea {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 11px 14px;
  font-size: 13px;
  color: var(--charcoal);
  font-family: inherit;
  transition: border-color .12s;
  box-sizing: border-box;
  resize: none;
  outline: none;
}
body.dark-mode .crv-input, body.dark-mode .crv-textarea {
  background: rgba(255,255,255,.04);
  border-color: rgba(255,255,255,.1);
  color: rgba(255,255,255,.9);
}
.crv-input:focus, .crv-textarea:focus {
  border-color: color-mix(in srgb, var(--green) 50%, transparent);
}
.crv-input::placeholder, .crv-textarea::placeholder { color: var(--muted); opacity: .7; }

.crv-continue {
  width: 100%;
  justify-content: center !important;
  padding: 12px 24px !important;
  font-size: 14px !important;
}

/* ══════════════════════════════════════════════════════════════
   SHARED — Loading state
   ══════════════════════════════════════════════════════════════ */

.crv-loading-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
  min-height: 300px;
  padding: 60px 20px;
  gap: 16px;
}
.crv-spinner-ring {
  width: 36px;
  height: 36px;
  border: 2.5px solid var(--border);
  border-top-color: var(--green);
  border-radius: 50%;
  animation: crvSpin .75s linear infinite;
}
body.dark-mode .crv-spinner-ring { border-color: rgba(255,255,255,.1); border-top-color: var(--green); }
@keyframes crvSpin { to { transform: rotate(360deg); } }

.crv-loading-h {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  letter-spacing: -.01em;
}
body.dark-mode .crv-loading-h { color: rgba(255,255,255,.85); }
.crv-loading-p { font-size: 12px; color: var(--muted); }

/* ══════════════════════════════════════════════════════════════
   SCREEN 4 — Concept Cards
   ══════════════════════════════════════════════════════════════ */

.crv-concepts-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-top: 8px;
}

.crv-concept-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px 18px;
  cursor: pointer;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-family: inherit;
  transition: transform .15s, border-color .15s, box-shadow .15s;
  position: relative;
}
body.dark-mode .crv-concept-card {
  background: rgba(255,255,255,.03);
  border-color: rgba(255,255,255,.08);
}
.crv-concept-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,.08);
  border-color: color-mix(in srgb, var(--green) 30%, transparent);
}
body.dark-mode .crv-concept-card:hover { box-shadow: 0 8px 24px rgba(0,0,0,.3); }
.crv-concept-card.crv-selected {
  border-color: color-mix(in srgb, var(--green) 55%, transparent) !important;
  background: color-mix(in srgb, var(--green) 4%, transparent) !important;
}

.crv-concept-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 20px;
  align-self: flex-start;
}
.crv-concept-angle {
  font-size: 13px;
  font-weight: 700;
  color: var(--charcoal);
  letter-spacing: -.01em;
  line-height: 1.3;
}
body.dark-mode .crv-concept-angle { color: rgba(255,255,255,.9); }
.crv-concept-hook {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.5;
  flex: 1;
}
.crv-concept-line {
  font-size: 12px;
  font-weight: 600;
  color: var(--charcoal);
  font-style: italic;
  line-height: 1.4;
  border-left: 2px solid var(--border);
  padding-left: 10px;
}
body.dark-mode .crv-concept-line { color: rgba(255,255,255,.7); }
.crv-concept-cta {
  font-size: 11px;
  font-weight: 600;
  color: var(--muted);
  margin-top: auto;
  transition: color .12s;
}
.crv-concept-card:hover .crv-concept-cta { color: var(--green); }

