.adm-view-btn { font-size: 11px; font-weight: 600; color: rgba(0,0,0,.5); text-decoration: none; padding: 4px 9px; border-radius: 6px; border: 1px solid rgba(0,0,0,.12); transition: color .12s, background .12s; white-space: nowrap; display: inline-block; }
