}
.adm-conn-loading { color: rgba(255,255,255,.35); }
.adm-conn-no { color: rgba(255,255,255,.35); }
.adm-conn-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
.adm-conn-ok-dot { background: #4ade80; box-shadow: 0 0 5px rgba(74,222,128,.5); }
.adm-conn-no-dot { background: rgba(255,255,255,.2); }
.adm-conn-change, .adm-conn-connect { font-size: 11px; font-weight: 600; padding: 3px 9px; border-radius: 6px; border: 1px solid rgba(255,255,255,.15); background: rgba(255,255,255,.07); color: rgba(255,255,255,.5); cursor: pointer; transition: background .15s, color .15s; }
.adm-conn-change:hover, .adm-conn-connect:hover { background: rgba(255,255,255,.12); color: rgba(255,255,255,.85); }
.adm-conn-connect { border-color: rgba(99,179,237,.3); background: rgba(99,179,237,.1); color: #63B3ED; }
.adm-conn-connect:hover { background: rgba(99,179,237,.18); color: #90cdf4; }

/* Light-mode adjustments */
body:not(.dark-mode) .adm-conn-loading { color: rgba(0,0,0,.35); }
body:not(.dark-mode) .adm-conn-no { color: rgba(0,0,0,.35); }
body:not(.dark-mode) .adm-conn-change, body:not(.dark-mode) .adm-conn-connect { color: rgba(0,0,0,.45); border-color: rgba(0,0,0,.12); background: rgba(0,0,0,.05); }
body:not(.dark-mode) .adm-conn-ok-dot { background: #16a34a; box-shadow: 0 0 5px rgba(22,163,74,.4); }
body:not(.dark-mode) .adm-conn-no-dot { background: rgba(0,0,0,.15); }

/* Ads Manager — Oriven status pills */
.adm-status-ready      { background: rgba(99,179,237,.15);  color: #63B3ED; }
.adm-status-arch       { background: rgba(107,107,107,.12); color: rgba(255,255,255,.35); }
.adm-status-publishing { background: rgba(251,191,36,.12);  color: #fbbf24; }
