/* Ads Manager — action buttons */
.adm-act-group { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.adm-act-btn { font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 6px; border: 1px solid transparent; cursor: pointer; transition: background .12s, color .12s, border-color .12s; white-space: nowrap; background: none; }
.adm-act-publish { background: rgba(74,222,128,.15); color: #4ade80; border-color: rgba(74,222,128,.25); }
