.adm-act-arch    { color: var(--muted, rgba(0,0,0,.4)); border-color: var(--border, rgba(0,0,0,.12)); }
.adm-act-arch:hover    { background: rgba(0,0,0,.06); color: var(--charcoal, #18181A); }
body.dark-mode .adm-act-arch    { color: rgba(255,255,255,.35); border-color: rgba(255,255,255,.1); }
body.dark-mode .adm-act-arch:hover    { background: rgba(255,255,255,.06); color: rgba(255,255,255,.6); }
.adm-act-connect { background: rgba(66,133,244,.15); color: #4285F4; border-color: rgba(66,133,244,.25); }
