.adm-act-retry { background: rgba(248,113,113,.12); color: #f87171; border-color: rgba(248,113,113,.2); }
.adm-act-retry:hover { background: rgba(248,113,113,.22); }

/* Ads Manager — account selector + publishing states */
.adm-acct-sel { font-size: 11px; font-weight: 500; padding: 4px 8px; border-radius: 6px; border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.06); color: rgba(255,255,255,.7); cursor: pointer; max-width: 150px; }
