.camp-card-act-adm { font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 6px; border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.06); color: rgba(255,255,255,.5); cursor: pointer; transition: background .12s, color .12s; white-space: nowrap; flex: 1; text-align: left; }
