.camp-card-act-del { padding: 4px 7px; border-radius: 6px; border: 1px solid rgba(255,255,255,.08); background: none; color: rgba(255,255,255,.25); cursor: pointer; transition: color .12s, background .12s, border-color .12s; display: inline-flex; align-items: center; justify-content: center; }
.camp-card-act-del:hover { color: #f87171; border-color: rgba(248,113,113,.25); background: rgba(248,113,113,.08); }

/* Campaign workspace — topbar right actions */
