.cwr-adm-btn { font-size: 12px; font-weight: 600; padding: 6px 14px; border-radius: 8px; border: 1px solid rgba(74,222,128,.3); background: rgba(74,222,128,.1); color: #4ade80; cursor: pointer; transition: background .12s, color .12s; white-space: nowrap; }
