.cwr-del-btn { font-size: 12px; font-weight: 600; padding: 6px 12px; border-radius: 8px; border: 1px solid rgba(255,255,255,.1); background: none; color: rgba(255,255,255,.3); cursor: pointer; transition: color .12s, background .12s, border-color .12s; }
.cwr-del-btn:hover { color: #f87171; border-color: rgba(248,113,113,.25); background: rgba(248,113,113,.08); }

/* clib-status pills — light-mode variants */
