/* ── Ads Manager V3 — Premium Section Layout ─────────────────────── */
.adm-v3-section { margin-top: 20px; background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.07); border-radius: 14px; overflow: hidden; transition: border-color .2s; }
.adm-v3-section:hover { border-color: rgba(255,255,255,.11); }
.adm-v3-drafts { background: rgba(255,255,255,.015); border-color: rgba(255,255,255,.06); }

.adm-v3-sh { display: flex; align-items: center; justify-content: space-between; padding: 13px 18px; border-bottom: 1px solid rgba(255,255,255,.06); }
.adm-v3-sh-left { display: flex; align-items: center; gap: 9px; font-size: 11px; font-weight: 700; color: rgba(255,255,255,.45); text-transform: uppercase; letter-spacing: .7px; }

.adm-v3-live-dot { width: 7px; height: 7px; border-radius: 50%; background: #4ade80; box-shadow: 0 0 6px rgba(74,222,128,.6); flex-shrink: 0; animation: admLivePulse 2.4s ease-in-out infinite; }
@keyframes admLivePulse { 0%,100% { box-shadow: 0 0 4px rgba(74,222,128,.4); } 50% { box-shadow: 0 0 10px rgba(74,222,128,.75), 0 0 20px rgba(74,222,128,.25); } }

.adm-v3-draft-dot { width: 7px; height: 7px; border-radius: 50%; background: #fbbf24; box-shadow: 0 0 5px rgba(251,191,36,.35); flex-shrink: 0; }

.adm-v3-count { font-size: 11px; font-weight: 600; padding: 2px 9px; border-radius: 20px; background: rgba(255,255,255,.08); color: rgba(255,255,255,.4); font-variant-numeric: tabular-nums; min-width: 24px; text-align: center; }

.adm-v3-table-wrap { overflow-x: auto; }

/* Premium V3 table */
.adm-v3-table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 13px; }
.adm-v3-table thead th { padding: 9px 16px; font-size: 11px; font-weight: 600; color: rgba(255,255,255,.28); text-transform: uppercase; letter-spacing: .5px; text-align: left; background: rgba(255,255,255,.018); border-bottom: 1px solid rgba(255,255,255,.05); white-space: nowrap; }
.adm-v3-table thead th:first-child { padding-left: 20px; }
.adm-v3-table thead th:last-child { padding-right: 20px; }
.adm-v3-table tbody tr { transition: background .14s ease; }
.adm-v3-table tbody tr:hover td { background: color-mix(in srgb, var(--green) 6%, transparent); }
.adm-v3-table tbody tr:not(:last-child) td { border-bottom: 1px solid rgba(255,255,255,.038); }
.adm-v3-table tbody td { padding: 12px 16px; color: rgba(255,255,255,.75); vertical-align: middle; }
.adm-v3-table tbody td:first-child { padding-left: 20px; }
.adm-v3-table tbody td:last-child { padding-right: 20px; }

.adm-th-check,.adm-td-check { width: 38px; padding-left: 18px !important; padding-right: 4px !important; }
.adm-v3-cb { width: 14px; height: 14px; accent-color: var(--green); cursor: pointer; }

/* Card-stack on mobile — .adm-v3-table-wrap's overflow-x:auto was the only
   responsive treatment before this; that still lets narrow tables scroll
   horizontally, which the spec rules out. Each <td> becomes a labeled row
   instead, using data-label attributes added at render time (app.html,
   _admRenderGoogleLive/_admRenderMetaLive row templates). */
@media (max-width: 640px) {
  .adm-v3-table-wrap { overflow-x: visible; }
  .adm-v3-table thead { display: none; }
  .adm-v3-table, .adm-v3-table tbody, .adm-v3-table tr { display: block; width: 100%; }
  .adm-v3-table tbody tr {
    border: 1px solid rgba(255,255,255,.07); border-radius: 10px;
    margin-bottom: 10px; padding: 4px 12px; background: rgba(255,255,255,.015);
  }
  .adm-v3-table tbody tr:not(:last-child) td { border-bottom: 1px solid rgba(255,255,255,.038); }
  .adm-v3-table tbody td {
    display: flex; align-items: center; justify-content: space-between; gap: 12px;
    padding: 8px 4px !important; text-align: right;
  }
  .adm-v3-table tbody td::before {
    content: attr(data-label); font-size: 11px; font-weight: 600; text-transform: uppercase;
    letter-spacing: .04em; color: rgba(255,255,255,.35); text-align: left; flex-shrink: 0;
  }
  .adm-v3-table tbody td:empty::before { content: none; }
  .adm-v3-table .adm-th-check { padding-left: 4px !important; }
  .adm-v3-table .adm-camp-name, .adm-v3-table .adm-camp-id { text-align: right; }
}
body:not(.dark-mode) .adm-v3-table tbody td::before { color: rgba(0,0,0,.4); }
@media (max-width: 640px) {
  body:not(.dark-mode) .adm-v3-table tbody tr { border-color: rgba(0,0,0,.08); background: rgba(0,0,0,.012); }
  body:not(.dark-mode) .adm-v3-table tbody tr:not(:last-child) td { border-bottom-color: rgba(0,0,0,.06); }
}

.adm-v3-camp-name { font-weight: 500; color: rgba(255,255,255,.88); }
.adm-v3-camp-id { font-size: 11px; color: rgba(255,255,255,.22); margin-top: 2px; font-variant-numeric: tabular-nums; }
