.adm-v3-type { display: inline-block; font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: 5px; background: rgba(255,255,255,.07); color: rgba(255,255,255,.4); letter-spacing: .3px; white-space: nowrap; }
.adm-v3-acts { display: flex; align-items: center; gap: 5px; }

