/* ════════════════════════════════════════════════════════════
   REPORTS PAGE — scoped under #page-reports to override legacy rpt-* styles
   ════════════════════════════════════════════════════════════ */

.rpt-wrap {
  max-width: 960px;
  margin: 0 auto;
  padding: 40px 40px 80px;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  box-sizing: border-box;
}
#page-reports .rpt-hdr {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 24px;
  gap: 16px;
}
#page-reports .rpt-title {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -.5px;
  color: #fff;
  margin: 0 0 4px;
}
#page-reports .rpt-sub {
  font-size: 13px;
  color: rgba(255,255,255,.4);
  margin: 0;
}
.rpt-hdr-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-shrink: 0;
  flex-wrap: wrap;
}
.rpt-btn-secondary {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 500;
  color: rgba(255,255,255,.65);
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 10px;
  cursor: pointer;
  transition: all .15s;
}
.rpt-btn-secondary:hover { background: rgba(255,255,255,.09); color: #fff; }
.rpt-btn-primary {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 700;
  color: #000;
  background: var(--green);
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: opacity .15s;
}
.rpt-btn-primary:hover { opacity: .86; }

/* Tabs */
.rpt-tabs {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid rgba(255,255,255,.07);
  margin-bottom: 28px;
  overflow-x: auto;
}
.rpt-tab {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 9px 14px;
  font-size: 13px;
  font-weight: 500;
  color: rgba(0,0,0,.45);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  margin-bottom: -1px;
  white-space: nowrap;
  transition: all .15s;
}
.rpt-tab:hover { color: var(--charcoal, #18181A); }
.rpt-tab.active { color: var(--charcoal, #18181A); border-bottom-color: var(--green); }
/* Oriven 1.0 (V6 light-mode fix) — was dark-only, invisible in light mode. */
body.dark-mode .rpt-tab { color: rgba(255,255,255,.4); }
body.dark-mode .rpt-tab:hover { color: rgba(255,255,255,.75); }
body.dark-mode .rpt-tab.active { color: #fff; }

/* Empty state */
.rpt-empty {
  text-align: center;
  padding: 72px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.rpt-empty-ico {
  width: 56px;
  height: 56px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  color: rgba(255,255,255,.28);
}
.rpt-empty-title {
  font-size: 18px;
  font-weight: 700;
  color: rgba(255,255,255,.65);
  margin-bottom: 10px;
  letter-spacing: -.2px;
}
.rpt-empty-sub {
  font-size: 14px;
  color: rgba(255,255,255,.35);
  max-width: 400px;
  line-height: 1.65;
  margin-bottom: 28px;
}

/* ════════════════════════════════════════════════════════════
   CONNECT PAGE — con-*
   ════════════════════════════════════════════════════════════ */

.con-wrap {
  max-width: 1060px;
  margin: 0 auto;
  padding: 40px 40px 80px;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  box-sizing: border-box;
}
/* Oriven 1.0 Business redesign — .page's min-height:100% forces every hub
   sub-page to fill a full viewport even when a hub-tabs strip sits above it
   eating into that same viewport, so short pages (Connect's 3 cards) always
   overflowed by exactly the hub-tabs bar's height. Content-driven height
   removes the forced empty space; overflow-y:auto still scrolls once real
   content (many connected accounts) genuinely exceeds the viewport. */
#page-integrations.page { min-height: 0; }
.con-hdr { margin-bottom: 32px; }
.con-title {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.2;
  color: var(--charcoal);
  margin: 0 0 5px;
}
body.dark-mode .con-title { color: #fff; }
.con-sub {
  font-size: 13px;
  color: var(--muted);
  margin: 0;
  max-width: 540px;
  line-height: 1.5;
}
body.dark-mode .con-sub { color: rgba(255,255,255,.4); }

/* 3-card grid */
.con-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}
.con-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 26px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  transition: border-color var(--orv-t, .16s), transform var(--orv-t, .16s), box-shadow var(--orv-t, .16s);
}
.con-card:hover { border-color: color-mix(in srgb, var(--green) 30%, var(--b2)); transform: translateY(var(--orv-lift)) scale(var(--orv-scale)); box-shadow: 0 8px 20px rgba(0,0,0,.05), 0 0 0 1px color-mix(in srgb, var(--green) 10%, transparent); }
body.dark-mode .con-card { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); }
body.dark-mode .con-card:hover { border-color: color-mix(in srgb, var(--green) 35%, rgba(255,255,255,.14)); box-shadow: 0 8px 20px rgba(0,0,0,.3), 0 0 0 1px color-mix(in srgb, var(--green) 14%, transparent); }
.con-card-connected {
  border-color: rgba(22,163,74,.28);
  background: rgba(22,163,74,.04);
}
body.dark-mode .con-card-connected { border-color: rgba(74,222,128,.22); background: rgba(74,222,128,.025); }

.con-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.con-card-logo {
  width: 46px;
  height: 46px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.con-logo-google { background: rgba(0,0,0,.04); border: 1px solid var(--border); }
body.dark-mode .con-logo-google { background: rgba(255,255,255,.07); border-color: rgba(255,255,255,.1); }
.con-logo-meta   { background: #1877F2; }
.con-logo-tiktok { background: #000; border: 1px solid rgba(255,255,255,.12); }

.con-card-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: 20px;
  background: rgba(0,0,0,.035);
  border: 1px solid var(--border);
  color: var(--muted);
  white-space: nowrap;
}
body.dark-mode .con-card-status { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.4); }
.con-card-status.connected {
  background: rgba(22,163,74,.1);
  border-color: rgba(22,163,74,.25);
  color: #16a34a;
}
body.dark-mode .con-card-status.connected { background: rgba(74,222,128,.08); border-color: rgba(74,222,128,.2); color: #4ade80; }
.con-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}
.con-dot-on  { background: #16a34a; box-shadow: 0 0 5px rgba(22,163,74,.4); }
body.dark-mode .con-dot-on { background: #4ade80; box-shadow: 0 0 5px rgba(74,222,128,.55); }
.con-dot-off { background: var(--b2); }
body.dark-mode .con-dot-off { background: rgba(255,255,255,.18); }

.con-card-name {
  font-size: 19px;
  font-weight: 700;
  color: var(--charcoal);
  letter-spacing: -.3px;
}
body.dark-mode .con-card-name { color: #fff; }
.con-card-desc {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.6;
}
body.dark-mode .con-card-desc { color: rgba(255,255,255,.45); }
.con-card-features {
  display: flex;
  flex-direction: column;
  gap: 7px;
  flex: 1;
}
.con-feat {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--muted);
}
body.dark-mode .con-feat { color: rgba(255,255,255,.55); }
.con-feat::before {
  content: '';
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(120,175,20,.65);
  flex-shrink: 0;
}
body.dark-mode .con-feat::before { background: color-mix(in srgb, var(--green) 55%, transparent); }
.con-card-foot { margin-top: auto; }
/* Root cause of Google Ads' account list sitting lower than Meta's: two
   compounding issues. (1) .con-cards is a grid with align-items:stretch,
   so every card is forced to the height of the tallest sibling (Meta, 3
   detail rows). With flex:1 here, THIS block was the one absorbing that
   leftover height, pushing the account list further down still. Removing
   flex:1 fixed that part. (2) Even without flex:1, .con-card-details still
   only grows to its OWN content's height -- Google's 2 rows vs Meta's 3
   means Google's block is naturally shorter (measured: 86px vs 133px,
   exactly one row + gap = 39px + 8px = 47px, matching the reported gap),
   so its next sibling (the account list) still started ~47px higher than
   Meta's regardless of flex:1. min-height below pins every card's details
   block to Meta's real height (3 rows x 39px + 2 gaps x 8px = 133px) --
   Meta (already 133px) is unaffected; Google/TikTok's shorter blocks (2
   and 1 real rows respectively) now match it exactly, so the account list
   starts at the identical Y position in every card regardless of how many
   real detail rows each platform actually has. */
.con-card-details {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 133px;
}
.con-detail-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  background: rgba(0,0,0,.025);
  border: 1px solid var(--border);
  border-radius: 10px;
}
body.dark-mode .con-detail-row { background: rgba(255,255,255,.035); border-color: rgba(255,255,255,.06); }
.con-detail-lbl {
  font-size: 12px;
  color: var(--muted);
  letter-spacing: .01em;
}
body.dark-mode .con-detail-lbl { color: rgba(255,255,255,.4); }
.con-detail-val {
  font-size: 13px;
  font-weight: 600;
  color: var(--c2);
  font-variant-numeric: tabular-nums;
}
body.dark-mode .con-detail-val { color: rgba(255,255,255,.55); }
.con-btn-connect {
  width: 100%;
  padding: 12px;
  font-size: 14px;
  font-weight: 700;
  color: #000;
  background: var(--green);
  border: none;
  border-radius: 11px;
  cursor: pointer;
  transition: opacity .15s;
}
.con-btn-connect:hover { opacity: .86; }
.con-btn-connect:disabled { opacity: .5; cursor: default; }
.con-btn-disconnect {
  width: 100%;
  padding: 12px;
  font-size: 13px;
  font-weight: 500;
  color: var(--muted);
  background: rgba(0,0,0,.03);
  border: 1px solid var(--border);
  border-radius: 11px;
  cursor: pointer;
  transition: all .15s;
}
body.dark-mode .con-btn-disconnect { color: rgba(255,255,255,.45); background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.1); }
.con-btn-disconnect:hover { color: #dc2626; border-color: rgba(220,38,38,.3); background: rgba(220,38,38,.05); }
body.dark-mode .con-btn-disconnect:hover { color: #f87171; border-color: rgba(248,113,113,.28); background: rgba(248,113,113,.04); }

/* Integration card — account list */
.con-acct-list { margin: 10px 0 4px; border: 1px solid rgba(255,255,255,.08); border-radius: 8px; overflow: hidden; }
.con-acct-list-hdr { padding: 7px 12px 5px; font-size: 10px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: rgba(255,255,255,.3); border-bottom: 1px solid rgba(255,255,255,.07); }
.con-acct-row { display: flex; align-items: center; gap: 8px; padding: 9px 12px; transition: background .12s; }
.con-acct-row + .con-acct-row { border-top: 1px solid rgba(255,255,255,.06); }
.con-acct-row.con-acct-active { background: rgba(74,222,128,.06); }
.con-acct-info { flex: 1; min-width: 0; }
.con-acct-name { font-size: 13px; font-weight: 500; color: rgba(255,255,255,.8); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.con-acct-id { font-size: 11px; color: rgba(255,255,255,.3); margin-top: 1px; }
.con-acct-badge { font-size: 10px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: #4ade80; background: rgba(74,222,128,.12); border: 1px solid rgba(74,222,128,.2); border-radius: 5px; padding: 2px 7px; white-space: nowrap; flex-shrink: 0; }
.con-acct-set { font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 6px; border: 1px solid rgba(255,255,255,.14); background: rgba(255,255,255,.07); color: rgba(255,255,255,.55); cursor: pointer; white-space: nowrap; flex-shrink: 0; transition: background .12s, color .12s; }
.con-acct-set:hover { background: rgba(255,255,255,.13); color: rgba(255,255,255,.9); }

/* Honest error state (e.g. Google Ads discovery genuinely failed -- bad
   dev token, expired credentials, API error) -- never just a bare, visually
   identical "0 accounts" empty state. */
.con-acct-err { margin: 8px 0 4px; padding: 9px 12px; font-size: 12px; line-height: 1.5; color: #f87171; background: rgba(248,113,113,.08); border: 1px solid rgba(248,113,113,.2); border-radius: 8px; }

/* Light mode */
body:not(.dark-mode) .con-acct-list { border-color: rgba(0,0,0,.1); }
body:not(.dark-mode) .con-acct-list-hdr { color: rgba(0,0,0,.3); border-bottom-color: rgba(0,0,0,.07); }
body:not(.dark-mode) .con-acct-row + .con-acct-row { border-top-color: rgba(0,0,0,.06); }
body:not(.dark-mode) .con-acct-row.con-acct-active { background: rgba(22,163,74,.06); }
body:not(.dark-mode) .con-acct-name { color: rgba(0,0,0,.8); }
body:not(.dark-mode) .con-acct-id { color: rgba(0,0,0,.35); }
body:not(.dark-mode) .con-acct-badge { color: #16a34a; background: rgba(22,163,74,.1); border-color: rgba(22,163,74,.2); }
body:not(.dark-mode) .con-acct-set { border-color: rgba(0,0,0,.12); background: rgba(0,0,0,.05); color: rgba(0,0,0,.5); }
body:not(.dark-mode) .con-acct-set:hover { background: rgba(0,0,0,.1); color: rgba(0,0,0,.85); }
body:not(.dark-mode) .con-acct-err { color: #dc2626; background: rgba(220,38,38,.06); border-color: rgba(220,38,38,.18); }

/* Why connect section */
.con-why { border-top: 1px solid rgba(255,255,255,.07); padding-top: 40px; }
.con-why-title {
  font-size: 14px;
  font-weight: 600;
  color: rgba(255,255,255,.38);
  text-transform: uppercase;
  letter-spacing: .5px;
  margin-bottom: 20px;
}
.con-why-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.con-why-item {
  padding: 20px;
  background: rgba(255,255,255,.025);
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 14px;
}
.con-why-ico {
  width: 34px;
  height: 34px;
  background: color-mix(in srgb, var(--green) 7%, transparent);
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  margin-bottom: 12px;
}
.con-why-lbl { font-size: 14px; font-weight: 600; color: rgba(255,255,255,.65); margin-bottom: 6px; }
.con-why-desc { font-size: 13px; color: rgba(255,255,255,.35); line-height: 1.6; }

/* Responsive */
@media (max-width: 960px) {
  .prf-kpis  { grid-template-columns: repeat(3, 1fr); }
  .prf-charts-grid { grid-template-columns: 1fr; }
  .prf-chart-wide  { grid-column: span 1; }
  .con-cards { grid-template-columns: 1fr; }
  .con-why-grid { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  .prf-wrap, .rpt-wrap, .con-wrap { padding: 24px 20px 60px; }
  .prf-kpis  { grid-template-columns: repeat(2, 1fr); }
  .prf-hdr   { flex-direction: column; }
  .rpt-hdr   { flex-direction: column; }
  .rpt-hdr-actions { flex-wrap: wrap; }
}
/* .prf-kpis only, on the canonical tablet/mobile tiers -- spec wants
   2/row on tablet, 1/row on mobile. The 960/720 rules above also control
   unrelated rpt- and con- prefixed selectors sharing those blocks, so
   rather than repurposing their breakpoints (which would shift Reports/
   Connections behavior too, outside this page's scope), this coexists
   with them: placed after, so it wins by source order at the same
   specificity. */
@media (max-width: 900px) {
  .prf-kpis { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .prf-kpis { grid-template-columns: 1fr; }
}
/* .prf-charts-grid is 2-col by default (desktop) — the 960px rule above
   collapses it to 1-col starting at the tablet band, which undercuts spec's
   "tablet: charts become 2 columns" (already true on desktop; tablet should
   stay that way, only mobile should stack to 1). Restore 2-col through the
   whole tablet range (up to and including the 912px test width), then
   actually collapse to 1 only at the mobile tier. */
@media (max-width: 1024px) {
  .prf-charts-grid { grid-template-columns: repeat(2, 1fr); }
  .prf-chart-wide { grid-column: span 2; }
}
@media (max-width: 640px) {
  .prf-charts-grid { grid-template-columns: 1fr; }
  .prf-chart-wide { grid-column: span 1; }
}



/* ════════════════════════════════════════════════════════════════
   CAMPAIGN RESULTS PAGE — #page-campaign-results
   ════════════════════════════════════════════════════════════════ */
/* Flex-sizing fix generalized to `.app > .page.active` in the app-shell
   section (styles.css ~24114) -- covers this page and every other route
   using the same direct-.app-child pattern, not just this one. */
#page-campaign-results { overflow-y: auto; }

.cgr-wrap {
  max-width: 1100px;
  margin: 0 auto;
  padding: 32px 40px 80px;
}

/* Back bar */
.cgr-back {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
}
/* Wins over body.dark-mode .cgr-back's own !important display rule
   (needed for its sticky/blur chrome) -- see _showResultsPage/_cgrShowChrome.
   Needs the ID, not just a second class: body.dark-mode .cgr-back is
   (0,2,1) specificity (element+2 classes) which beats a same-!important
   (0,2,0) two-class rule regardless of source order; #cgrBackBar makes
   this unambiguously win. */
#cgrBackBar.cgr-back-hidden { display: none !important; }
.cgr-back-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: none;
  border: none;
  color: rgba(255,255,255,.4);
  font-size: 13px;
  cursor: pointer;
  padding: 0;
  transition: color .15s;
}
.cgr-back-btn:hover { color: rgba(255,255,255,.7); }
.cgr-back-actions { display: flex; gap: 10px; }
.cgr-action-btn {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 8px;
  color: rgba(255,255,255,.6);
  font-size: 12px;
  padding: 7px 14px;
  cursor: pointer;
  transition: all .15s;
  display: flex;
  align-items: center;
  gap: 6px;
}
.cgr-action-btn:hover { background: rgba(255,255,255,.1); color: #fff; }
.cgr-action-btn-primary {
  background: var(--green);
  border-color: var(--green);
  color: #0a0a0a;
  font-weight: 600;
}
.cgr-action-btn-primary:hover { background: var(--gm); color: #0a0a0a; }

/* ══════════════════════════════════════════════════════════════════
   Campaign blueprint — the "building" view shown while a campaign
   generates. Deliberately committed to one dark aesthetic regardless of
   theme (same precedent as the ad-workspace's own dark commitment) — a
   premium AI dev-tool surface, not a spinner-and-checklist loading
   screen. Driven by _cgrBuildStart in app.html.
   ══════════════════════════════════════════════════════════════════ */
.cgr-build {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 28px;
  min-height: 68vh;
  padding: 60px 40px;
}
.cgr-build-status {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: rgba(255,255,255,.35);
}
.cgr-build-status::before {
  content: '';
  display: inline-block;
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--green);
  margin-right: 9px;
  vertical-align: middle;
  animation: cgrBuildPulseDot 1.6s ease-in-out infinite;
}
@keyframes cgrBuildPulseDot { 0%, 100% { opacity: .4; transform: scale(1); } 50% { opacity: 1; transform: scale(1.3); } }

.cgr-build-card {
  position: relative;
  width: 100%;
  max-width: 780px;
  min-height: 500px;
  background: #08080a;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 18px;
  padding: 40px 48px;
  overflow: hidden;
  box-shadow: 0 40px 90px -30px rgba(0,0,0,.6);
}
.cgr-build-glow {
  position: absolute;
  inset: -20%;
  background: radial-gradient(ellipse 55% 40% at 50% 0%, color-mix(in srgb, var(--green) 7%, transparent), transparent 70%);
  pointer-events: none;
  opacity: .6;
  transition: opacity .6s ease;
}
.cgr-build-glow-flash { animation: cgrBuildFlash 1.1s ease; }
@keyframes cgrBuildFlash {
  0%   { opacity: .6; }
  30%  { opacity: 1; background: radial-gradient(ellipse 60% 45% at 50% 0%, color-mix(in srgb, var(--green) 16%, transparent), transparent 72%); }
  100% { opacity: .6; }
}

.cgr-build-lines {
  position: relative;
  z-index: 1;
  font-family: "SF Mono", "Cascadia Code", "Consolas", monospace;
  font-size: 13px;
  line-height: 1.75;
  max-width: 620px;
  margin: 0 auto;
  text-align: left;
}

/* One line of the nested campaign{} object -- see _cgrBlLine in app.html.
   The border-left/margin pair (rather than an absolutely-positioned bar)
   is what lets .cgr-bl-line-active show a left accent without disturbing
   the per-depth padding-left indentation below. */
.cgr-bl-line {
  position: relative;
  min-height: 1.75em;
  margin-left: -12px;
  padding-left: 12px;
  border-left: 2px solid transparent;
  border-radius: 3px;
  transition: border-color .3s ease, background .3s ease;
  white-space: nowrap;
}
.cgr-bl-blank { min-height: 1.75em; }
.cgr-bl-d1 { padding-left: calc(12px + 1.6em); }
.cgr-bl-d2 { padding-left: calc(12px + 3.2em); }

/* Active/unresolved line -- a faint green wash + left accent, the "AI is
   still working on this one" signal. Removed the instant a field resolves
   (see _cgrBlFieldDone). */
.cgr-bl-line-active {
  border-left-color: color-mix(in srgb, var(--green) 55%, transparent);
  background: linear-gradient(90deg, color-mix(in srgb, var(--green) 6%, transparent), transparent 65%);
}

.cgr-bl-brace { color: rgba(255,255,255,.5); }
.cgr-bl-key   { color: rgba(255,255,255,.42); }
.cgr-bl-punct { color: rgba(255,255,255,.22); }
.cgr-bl-str   { color: rgba(255,255,255,.22); }
.cgr-bl-value { font-weight: 600; transition: color .3s ease; }
.cgr-bl-value-active {
  color: color-mix(in srgb, var(--green) 78%, white 8%);
  animation: cgrBlActivePulse 1.4s ease-in-out infinite;
}
@keyframes cgrBlActivePulse { 0%, 100% { opacity: .65; } 50% { opacity: 1; } }
.cgr-bl-value-done  { color: var(--green); opacity: 1; animation: none; }
.cgr-bl-value-error { color: rgba(248,113,113,.85); opacity: 1; animation: none; }

.cgr-bl-cursor {
  display: inline-block;
  width: 7px; height: 14px;
  margin-left: 1px;
  background: color-mix(in srgb, var(--green) 55%, transparent);
  vertical-align: text-bottom;
  animation: cgrBlCursorBlink .9s steps(1) infinite;
}
@keyframes cgrBlCursorBlink { 50% { opacity: 0; } }

@media (max-width: 900px) {
  .cgr-build { padding: 40px 20px; min-height: auto; }
  .cgr-build-card { padding: 30px 24px; min-height: 380px; }
  .cgr-build-lines { max-width: 100%; white-space: normal; }
  .cgr-bl-line { white-space: normal; }
}
@media (prefers-reduced-motion: reduce) {
  .cgr-build-status::before, .cgr-build-glow-flash, .cgr-bl-value-active, .cgr-bl-cursor {
    animation: none !important;
  }
  .cgr-bl-value-active { opacity: 1; }
}

/* Header */
.cgr-hdr {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 40px;
  padding-bottom: 32px;
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.cgr-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--green);
  background: color-mix(in srgb, var(--green) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 20%, transparent);
  border-radius: 6px;
  padding: 4px 8px;
  margin-bottom: 10px;
}
.cgr-title {
  font-size: 32px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -.7px;
  line-height: 1.1;
  margin-bottom: 6px;
}
.cgr-prompt-echo {
  font-size: 13px;
  color: rgba(255,255,255,.35);
  font-style: italic;
}
.cgr-hdr-meta {
  display: flex;
  gap: 20px;
  flex-shrink: 0;
}
.cgr-meta-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
  text-align: right;
}
.cgr-meta-lbl { font-size: 10px; color: rgba(255,255,255,.3); text-transform: uppercase; letter-spacing: .06em; }
.cgr-meta-val { font-size: 14px; font-weight: 600; color: rgba(255,255,255,.7); }

/* Section layout */
.cgr-section {
  margin-bottom: 56px;
}
.cgr-section-hd {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  margin-bottom: 24px;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.cgr-section-num {
  font-size: 11px;
  font-weight: 700;
  color: color-mix(in srgb, var(--green) 70%, transparent);
  letter-spacing: .08em;
  margin-top: 3px;
  min-width: 24px;
}
.cgr-section-title { font-size: 18px; font-weight: 700; color: #fff; letter-spacing: -.3px; }
.cgr-section-sub   { font-size: 13px; color: rgba(255,255,255,.35); margin-top: 3px; }

/* Strategy grid */
.cgr-strategy-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}
.cgr-strat-block {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 12px;
  padding: 14px 16px;
}
.cgr-strat-lbl { font-size: 10px; color: rgba(255,255,255,.3); text-transform: uppercase; letter-spacing: .07em; margin-bottom: 5px; }
.cgr-strat-val { font-size: 13px; color: rgba(255,255,255,.75); line-height: 1.5; }

/* Tag rows */
.cgr-tags-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
.cgr-tags-lbl { font-size: 11px; color: rgba(255,255,255,.3); text-transform: uppercase; letter-spacing: .07em; margin-bottom: 8px; }
.cgr-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.cgr-tag {
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 20px;
  background: rgba(255,255,255,.06);
  color: rgba(255,255,255,.6);
  border: 1px solid rgba(255,255,255,.1);
}
.cgr-tag-red   { background: rgba(248,113,113,.08); color: rgba(248,113,113,.85); border-color: rgba(248,113,113,.2); }
.cgr-tag-green { background: rgba(74,222,128,.08);  color: rgba(74,222,128,.9);   border-color: rgba(74,222,128,.2); }
.cgr-tag-blue  { background: rgba(96,165,250,.08);  color: rgba(96,165,250,.85);  border-color: rgba(96,165,250,.2); }

/* Concept tabs */
.cgr-concept-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
.cgr-ctab {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 10px;
  padding: 10px 16px;
  cursor: pointer;
  transition: all .15s;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 180px;
  text-align: left;
}
.cgr-ctab:hover { background: rgba(255,255,255,.07); }
.cgr-ctab-angle { font-size: 10px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--green); }
.cgr-ctab-name  { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.75); }

/* Concept panels */
.cgr-cpanel-hidden { display: none; }
.cgr-cpanel-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.cgr-cpanel-left, .cgr-cpanel-right {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 14px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.cgr-cpanel-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  border-radius: 6px;
  padding: 4px 9px;
  align-self: flex-start;
}
.cgr-cpanel-hook { font-size: 20px; font-weight: 800; color: #fff; letter-spacing: -.4px; line-height: 1.25; }
.cgr-cpanel-field { display: flex; flex-direction: column; gap: 4px; }
.cgr-cpanel-lbl { font-size: 10px; color: rgba(255,255,255,.3); text-transform: uppercase; letter-spacing: .07em; }
.cgr-cpanel-val { font-size: 13px; color: rgba(255,255,255,.7); line-height: 1.55; }
.cgr-cpanel-headline { font-size: 16px; font-weight: 700; color: #fff; letter-spacing: -.2px; }
.cgr-cpanel-cta {
  display: inline-block;
  align-self: flex-start;
  background: var(--green);
  color: #0a0a0a;
  font-size: 12px;
  font-weight: 700;
  padding: 8px 16px;
  border-radius: 8px;
  letter-spacing: .02em;
  margin-top: auto;
}
.cgr-cpanel-chips { display: flex; flex-direction: column; gap: 10px; margin-top: auto; }
.cgr-chip-group { display: flex; flex-wrap: wrap; gap: 5px; align-items: center; }
.cgr-chip-lbl { font-size: 10px; color: rgba(255,255,255,.3); text-transform: uppercase; letter-spacing: .07em; width: 100%; }
.cgr-chip { font-size: 11px; padding: 3px 8px; border-radius: 20px; border: 1px solid; }
.cgr-chip-g { background: rgba(74,222,128,.08); color: rgba(74,222,128,.85); border-color: rgba(74,222,128,.2); }
.cgr-chip-r { background: rgba(248,113,113,.08); color: rgba(248,113,113,.85); border-color: rgba(248,113,113,.2); }
.cgr-chip-b { background: rgba(96,165,250,.08); color: rgba(96,165,250,.85); border-color: rgba(96,165,250,.2); }
.cgr-chip-p { background: rgba(168,85,247,.08); color: rgba(168,85,247,.85); border-color: rgba(168,85,247,.2); }

/* Platform tabs */
.cgr-plat-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 20px;
}
.cgr-plat-tab {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px 16px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 9px;
  color: rgba(255,255,255,.45);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all .15s;
}
.cgr-plat-tab:hover { background: rgba(255,255,255,.08); color: rgba(255,255,255,.75); }
.cgr-plat-tab.active { background: color-mix(in srgb, var(--green) 10%, transparent); border-color: color-mix(in srgb, var(--green) 30%, transparent); color: var(--green); }

/* Asset blocks */
.cgr-plat-panel { display: flex; flex-direction: column; gap: 16px; }
.cgr-asset-block {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 12px;
  padding: 18px 20px;
}
.cgr-asset-hd {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.cgr-asset-title { font-size: 13px; font-weight: 600; color: rgba(255,255,255,.65); }
.cgr-asset-count { font-size: 11px; color: rgba(255,255,255,.25); }
.cgr-asset-badge { font-size: 10px; background: color-mix(in srgb, var(--green) 10%, transparent); color: var(--green); border: 1px solid color-mix(in srgb, var(--green) 20%, transparent); border-radius: 5px; padding: 2px 7px; font-weight: 600; letter-spacing: .05em; }
.cgr-asset-row-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }

.cgr-headlines-grid { display: flex; flex-wrap: wrap; gap: 7px; }
.cgr-hl-chip {
  font-size: 12px;
  padding: 6px 12px;
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 7px;
  color: rgba(255,255,255,.7);
  cursor: pointer;
  transition: all .15s;
}
.cgr-hl-chip:hover { background: color-mix(in srgb, var(--green) 10%, transparent); border-color: color-mix(in srgb, var(--green) 30%, transparent); color: var(--green); }

.cgr-descriptions { display: flex; flex-direction: column; gap: 8px; }
.cgr-desc-item {
  font-size: 13px;
  color: rgba(255,255,255,.65);
  padding: 10px 14px;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color .15s;
  line-height: 1.5;
}
.cgr-desc-item:hover { border-color: color-mix(in srgb, var(--green) 30%, transparent); }

.cgr-kw-grid { display: flex; flex-wrap: wrap; gap: 6px; }
.cgr-kw-chip {
  font-size: 12px;
  padding: 4px 10px;
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 20px;
  color: rgba(255,255,255,.55);
  cursor: pointer;
  transition: all .15s;
}
.cgr-kw-chip:hover { background: color-mix(in srgb, var(--green) 8%, transparent); border-color: color-mix(in srgb, var(--green) 25%, transparent); color: color-mix(in srgb, var(--green) 85%, transparent); }

.cgr-prose { font-size: 13px; color: rgba(255,255,255,.65); line-height: 1.65; }
.cgr-prose-lg { font-size: 14px; }
.cgr-prose-bold { font-size: 16px; font-weight: 700; color: #fff; }
.cgr-list-items { display: flex; flex-direction: column; gap: 7px; }
.cgr-list-item {
  font-size: 13px;
  color: rgba(255,255,255,.6);
  padding: 8px 12px;
  background: rgba(255,255,255,.025);
  border-left: 2px solid color-mix(in srgb, var(--green) 30%, transparent);
  border-radius: 0 6px 6px 0;
  line-height: 1.5;
}
.cgr-script {
  font-size: 13px;
  color: rgba(255,255,255,.65);
  line-height: 1.8;
  white-space: pre-wrap;
  background: rgba(0,0,0,.2);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 8px;
  padding: 14px 16px;
  font-family: "SF Mono", "Cascadia Code", "Consolas", monospace;
}

/* Visual concepts */
.cgr-visual-grid { display: flex; flex-direction: column; gap: 16px; }
.cgr-vis-card {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 14px;
  overflow: hidden;
}
.cgr-vis-hd {
  padding: 20px 22px 16px;
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.cgr-vis-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  border-radius: 6px;
  padding: 4px 9px;
  margin-bottom: 10px;
}
.cgr-vis-concept { font-size: 14px; font-weight: 600; color: rgba(255,255,255,.75); line-height: 1.5; }
.cgr-vis-dir { display: flex; flex-wrap: wrap; gap: 0; padding: 14px 22px; border-bottom: 1px solid rgba(255,255,255,.05); }
.cgr-vis-dir-row { width: 33.333%; padding: 7px 0; display: flex; flex-direction: column; gap: 3px; }
.cgr-vis-dir-lbl { font-size: 10px; color: rgba(255,255,255,.28); text-transform: uppercase; letter-spacing: .06em; }
.cgr-vis-dir-val { font-size: 12px; color: rgba(255,255,255,.6); }
.cgr-vis-prompts { padding: 18px 22px; }
.cgr-vis-prompts-hd { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.3); text-transform: uppercase; letter-spacing: .07em; margin-bottom: 12px; }
.cgr-vis-prompt {
  display: flex;
  gap: 12px;
  padding: 12px 14px;
  background: rgba(0,0,0,.2);
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 8px;
  margin-bottom: 8px;
  cursor: pointer;
  transition: border-color .15s;
}
.cgr-vis-prompt:last-child { margin-bottom: 0; }
.cgr-vis-prompt:hover { border-color: color-mix(in srgb, var(--green) 30%, transparent); }
.cgr-vis-prompt-n { font-size: 11px; font-weight: 700; color: color-mix(in srgb, var(--green) 60%, transparent); min-width: 14px; margin-top: 2px; }
.cgr-vis-prompt-txt { font-size: 12px; color: rgba(255,255,255,.5); line-height: 1.6; }

/* Performance prediction */
.cgr-perf-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.cgr-perf-scores {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 14px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.cgr-score-row { display: flex; align-items: center; justify-content: space-between; }
.cgr-score-lbl { font-size: 12px; color: rgba(255,255,255,.4); min-width: 130px; }
.cgr-score-ctr { font-size: 28px; font-weight: 800; color: var(--green); letter-spacing: -.5px; }
.cgr-score-bar-row { display: flex; align-items: center; gap: 12px; }
.cgr-score-track { flex: 1; height: 5px; background: rgba(255,255,255,.07); border-radius: 3px; overflow: hidden; }
.cgr-score-fill { height: 100%; border-radius: 3px; transition: width .8s cubic-bezier(.25,.46,.45,.94); }
.cgr-fill-green  { background: #4ade80; }
.cgr-fill-blue   { background: #60a5fa; }
.cgr-fill-lime   { background: var(--green); }
.cgr-score-num { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.45); min-width: 48px; text-align: right; font-variant-numeric: tabular-nums; }
.cgr-perf-explain {
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 14px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.cgr-perf-potential { display: flex; align-items: center; justify-content: space-between; }
.cgr-perf-lbl { font-size: 12px; color: rgba(255,255,255,.35); }
.cgr-perf-potential-val {
  font-size: 14px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 20px;
}
.cgr-pot-high { background: rgba(74,222,128,.12); color: #4ade80; }
.cgr-pot-med  { background: rgba(251,191,36,.12);  color: #fbbf24; }
.cgr-pot-low  { background: rgba(248,113,113,.12); color: #f87171; }
.cgr-perf-text { font-size: 13px; color: rgba(255,255,255,.5); line-height: 1.65; }

/* Error state */
.cgr-error {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 80px 0;
  gap: 16px;
  text-align: center;
}
.cgr-error-ico { font-size: 32px; }
.cgr-error-title { font-size: 18px; font-weight: 700; color: #fff; }
.cgr-error-sub { font-size: 13px; color: rgba(255,255,255,.4); max-width: 360px; }
.cgr-debug-msg {
  background: rgba(255,60,60,.08);
  border: 1px solid rgba(255,60,60,.22);
  border-radius: 8px;
  color: #ff7a7a;
  font-family: 'Geist Mono', 'SF Mono', monospace;
  font-size: 12px;
  line-height: 1.6;
  padding: 12px 16px;
  text-align: left;
  max-width: 520px;
  white-space: pre-wrap;
  word-break: break-all;
  margin: 0;
}

/* Responsive */
@media (max-width: 900px) {
  .cgr-wrap { padding: 24px 20px 60px; }
  .cgr-strategy-grid { grid-template-columns: 1fr 1fr; }
  .cgr-tags-row { grid-template-columns: 1fr; }
  .cgr-cpanel-inner { grid-template-columns: 1fr; }
  .cgr-perf-grid { grid-template-columns: 1fr; }
  .cgr-concept-tabs { flex-wrap: wrap; }
  .cgr-asset-row-2 { grid-template-columns: 1fr; }
}


