.ov4 {
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

/* â”€â”€ HERO â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.ov4-hero {
  min-height: calc(100vh - 52px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 72px 40px 56px;
}

.ov4-hero-inner {
  width: 100%;
  max-width: 700px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.ov4-eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: rgba(255,255,255,.38);
  margin-bottom: 26px;
}

.ov4-eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px color-mix(in srgb, var(--green) 55%, transparent);
  flex-shrink: 0;
}

.ov4-headline {
  font-size: clamp(42px, 5.5vw, 64px);
  font-weight: 700;
  line-height: 1.06;
  letter-spacing: -.03em;
  color: #fff;
  margin: 0 0 18px;
  text-wrap: balance;
}

.ov4-sub {
  font-size: 16px;
  line-height: 1.65;
  color: rgba(255,255,255,.45);
  margin: 0 0 22px;
  max-width: 480px;
}

.ov4-delivers {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 5px 3px;
  margin-bottom: 38px;
}

.ov4-deliver {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: .03em;
  color: rgba(255,255,255,.3);
}

.ov4-deliver-sep {
  font-size: 11px;
  color: rgba(255,255,255,.15);
}

/* â”€â”€ INPUT BOX â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.ov4-input-wrap {
  width: 100%;
  background: rgba(255,255,255,.042);
  border: 1.5px solid rgba(255,255,255,.09);
  border-radius: 16px;
  padding: 18px 18px 13px;
  transition: border-color .2s, background .2s;
  box-sizing: border-box;
}

.ov4-input-wrap:focus-within {
  border-color: color-mix(in srgb, var(--green) 30%, transparent);
  background: rgba(255,255,255,.055);
}

.ov4-input {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  resize: none;
  font-size: 15px;
  line-height: 1.62;
  color: rgba(255,255,255,.88);
  font-family: inherit;
  min-height: 64px;
  display: block;
  box-sizing: border-box;
