@keyframes v2-fade-in  { from { opacity: 0; } to { opacity: 1; } }
@keyframes v2-fade-up  { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

/* Premium Motion System — page switches fade+settle instead of an instant
   cut, so moving between workspaces reads as one application, not
   separate pages loading. Kept intentionally light (opacity + 4px) so it
   never feels like "loading". */
.page.active { animation: orvPageIn var(--orv-t-slow, 220ms cubic-bezier(.22,.61,.36,1)) both; }
@keyframes orvPageIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
