.bi-toggle-lbl:focus-visible {
  outline: 2px solid var(--green, #B7FF2A);
  outline-offset: 2px;
}

body.dark-mode .bi-toggle {
  background: rgba(255,255,255,.06) !important;
  border: 1px solid rgba(255,255,255,.1) !important;
}
body.dark-mode .bi-toggle[data-state="off"] .bi-toggle-thumb {
  background: rgba(255,255,255,.18) !important;
}
body.dark-mode .bi-toggle-lbl { color: rgba(255,255,255,.45) !important; }
body.dark-mode .bi-toggle-lbl:hover { color: rgba(255,255,255,.75) !important; }
