/* Section header row with title + edit/regen actions */
.bb-section-hd-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.bb-card-eyebrow-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 0;
}
.bb-sec-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.bb-sec-edit-btn,
.bb-sec-regen-btn {
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 500;
  border-radius: 5px;
  cursor: pointer;
  border: 1px solid;
  transition: all .12s;
  white-space: nowrap;
}
.bb-sec-edit-btn {
  background: transparent;
  border-color: var(--border, rgba(0,0,0,.12));
  color: var(--muted, rgba(0,0,0,.4));
}
.bb-sec-edit-btn:hover { background: var(--bg2); color: var(--charcoal); }
.bb-sec-regen-btn {
  background: transparent;
  border-color: transparent;
  color: var(--muted, rgba(0,0,0,.3));
}
.bb-sec-regen-btn:hover { color: var(--green); border-color: color-mix(in srgb, var(--green) 30%, transparent); background: color-mix(in srgb, var(--green) 6%, transparent); }

/* Inline edit textarea */
.bb-edit-area {
  width: 100%;
  min-height: 90px;
  padding: 10px 12px;
  font-family: 'Geist', system-ui, -apple-system, sans-serif;
  font-size: 13.5px;
  line-height: 1.6;
  background: transparent;
  border: 1px solid rgba(0,0,0,.18);
  border-radius: 8px;
  color: inherit;
  resize: vertical;
  outline: none;
  box-sizing: border-box;
}
.bb-edit-area:focus { border-color: var(--green); box-shadow: 0 0 0 2px color-mix(in srgb, var(--green) 12%, transparent); }

/* Save / Cancel row */
.bb-edit-actions {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}
.bb-edit-save,
.bb-edit-cancel {
  padding: 5px 14px;
  font-size: 12px;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  border: 1px solid;
  transition: all .12s;
}
.bb-edit-save {
  background: var(--green);
  border-color: var(--green);
  color: #0A0A0A;
}
.bb-edit-save:hover { background: var(--gm); }
.bb-edit-cancel {
  background: transparent;
  border-color: rgba(0,0,0,.15);
  color: rgba(0,0,0,.45);
}
.bb-edit-cancel:hover { background: rgba(0,0,0,.04); color: rgba(0,0,0,.7); }

