/* ══════════════════════════════════════════════════════════
   SETTINGS — SUBSCRIPTION TWO-CARD LAYOUT
   ══════════════════════════════════════════════════════════ */

.sub-two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  align-items: start;
}

/* Shared card shell */
.sub-plan-card,
.sub-usage-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
}

.sub-card-eyebrow {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: .55;
  margin-bottom: 8px;
}

/* Plan name + price */
.sub-plan-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--charcoal);
  letter-spacing: -.04em;
  margin-bottom: 4px;
}
.sub-plan-price { margin-bottom: 8px; }
.sub-price-num { font-size: 28px; font-weight: 800; color: var(--charcoal); letter-spacing: -.04em; }
.sub-price-per { font-size: 13px; color: var(--muted); margin-left: 3px; }
.sub-price-cs  { font-size: 16px; font-weight: 600; color: var(--charcoal); }
.sub-renewal   { font-size: 12px; color: var(--muted); margin-bottom: 10px; }

/* Features list */
.sub-features {
  list-style: none;
  padding: 0;
  margin: 0 0 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.sub-features li {
  font-size: 12.5px;
  color: var(--muted);
  display: flex;
  align-items: flex-start;
  gap: 7px;
  line-height: 1.5;
}
.sub-features li::before {
  content: '';
  display: block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--green);
  flex-shrink: 0;
  margin-top: 6px;
}

/* Plan action buttons */
.sub-plan-actions { display: flex; flex-direction: column; gap: 8px; }
.sub-cancel-link {
  background: none;
  border: none;
  padding: 0;
  font-size: 12px;
  color: var(--muted);
  cursor: pointer;
  text-align: left;
  opacity: .6;
  text-decoration: underline;
  transition: opacity .15s;
}
.sub-cancel-link:hover { opacity: 1; }

/* Pending notice */
.sub-pending-notice {
  font-size: 12px;
  color: var(--muted);
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 12px;
  margin-bottom: 14px;
  line-height: 1.5;
}
.sub-undo-btn {
  background: none;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 7px;
  font-size: 11px;
  cursor: pointer;
  color: var(--muted);
  margin-left: 4px;
  transition: all .12s;
}
.sub-undo-btn:hover { background: var(--bg2); color: var(--charcoal); }

/* Usage rows */
.sub-usage-list { display: flex; flex-direction: column; gap: 0; }
.sub-usage-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
}
.sub-usage-row:last-child { border-bottom: none; }
.sub-usage-lbl { font-size: 13px; color: var(--charcoal); }
.sub-usage-right { text-align: right; }
.sub-usage-val { font-size: 13px; font-weight: 600; color: var(--charcoal); }
.sub-usage-sub { font-size: 11px; color: var(--muted); margin-top: 1px; }

/* ── Credit usage bar ─────────────────────────────────────────── */
.sub-credit-hd-row { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.sub-credit-hd-lbl { font-size: 13px; font-weight: 600; color: var(--charcoal); }
.sub-credit-hd-val { font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.sub-credit-bar-track { height: 8px; border-radius: 5px; background: var(--bg2, rgba(0,0,0,.06)); overflow: hidden; margin: 8px 0 6px; }
.sub-credit-bar-fill { height: 100%; border-radius: 5px; background: var(--green); transition: width .3s ease; }
.sub-credit-hd-sub { font-size: 12px; color: var(--muted); }
.sub-usage-unavailable { font-size: 13px; color: var(--muted); padding: 6px 0; }
body.dark-mode .sub-credit-bar-track { background: rgba(255,255,255,.07); }

/* ── Dark mode overrides ── */
body.dark-mode .sub-plan-card,
body.dark-mode .sub-usage-card {
  background: rgba(255,255,255,.04) !important;
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 14px !important;
  padding: 16px !important;
}
body.dark-mode .sub-card-eyebrow { color: rgba(255,255,255,.28) !important; opacity: 1 !important; }
body.dark-mode .sub-plan-name { color: #fff !important; }
body.dark-mode .sub-price-num { color: #fff !important; }
body.dark-mode .sub-price-per { color: rgba(255,255,255,.35) !important; }
body.dark-mode .sub-price-cs  { color: rgba(255,255,255,.8) !important; }
body.dark-mode .sub-renewal   { color: rgba(255,255,255,.3) !important; }
body.dark-mode .sub-features li { color: rgba(255,255,255,.5) !important; }
body.dark-mode .sub-features li::before { background: var(--green) !important; }
body.dark-mode .sub-cancel-link { color: rgba(255,255,255,.3) !important; }
body.dark-mode .sub-cancel-link:hover { opacity: 1 !important; color: rgba(255,255,255,.6) !important; }
body.dark-mode .sub-pending-notice { background: rgba(255,255,255,.03) !important; border-color: rgba(255,255,255,.08) !important; color: rgba(255,255,255,.5) !important; }
body.dark-mode .sub-undo-btn { border-color: rgba(255,255,255,.12) !important; color: rgba(255,255,255,.4) !important; }
body.dark-mode .sub-undo-btn:hover { background: rgba(255,255,255,.06) !important; color: rgba(255,255,255,.75) !important; }
body.dark-mode .sub-usage-row { border-bottom-color: rgba(255,255,255,.06) !important; }
body.dark-mode .sub-usage-lbl { color: rgba(255,255,255,.6) !important; }
body.dark-mode .sub-usage-val { color: rgba(255,255,255,.85) !important; }
body.dark-mode .sub-usage-sub { color: rgba(255,255,255,.28) !important; }
body.dark-mode .sub-two-col { display: grid !important; grid-template-columns: 1fr 1fr !important; gap: 16px !important; align-items: start !important; }

/* Settings nav — dark overrides for cleaner look */
body.dark-mode .se-nav {
  background: rgba(255,255,255,.03) !important;
  border: 1px solid rgba(255,255,255,.06) !important;
  border-radius: 12px !important;
  padding: 10px !important;
}
body.dark-mode .se-nav-label {
  font-size: 9px !important; font-weight: 700 !important; letter-spacing: .1em !important;
  text-transform: uppercase !important; color: rgba(255,255,255,.22) !important;
  padding: 4px 8px 5px !important; cursor: default !important;
}
body.dark-mode .snav-item {
  padding: 7px 10px !important; border-radius: 7px !important; font-size: 12.5px !important;
  color: rgba(255,255,255,.45) !important; cursor: pointer !important; margin-bottom: 1px !important;
}
body.dark-mode .snav-item:hover { background: rgba(255,255,255,.06) !important; color: rgba(255,255,255,.8) !important; }
body.dark-mode .snav-item.active { background: color-mix(in srgb, var(--green) 10%, transparent) !important; color: var(--green) !important; font-weight: 600 !important; }
body.dark-mode .se-nav-group+.se-nav-group { border-top-color: rgba(255,255,255,.05) !important; }

/* Settings panel header */
body.dark-mode .se-panel-hd { border-bottom-color: rgba(255,255,255,.06) !important; }
body.dark-mode .se-panel-title { color: #fff !important; }
body.dark-mode .se-panel-sub { color: rgba(255,255,255,.4) !important; }

/* Settings card title + help in dark */
body.dark-mode .se-card-title { color: rgba(255,255,255,.85) !important; }
body.dark-mode .se-card-help { color: rgba(255,255,255,.38) !important; }

/* Responsive — stack on small screens */
@media (max-width: 600px) {
  .sub-two-col { grid-template-columns: 1fr; }
}


/* ════════════════════════════════════════════════════════════════
   SETTINGS MODAL (smd-*)
   ════════════════════════════════════════════════════════════════ */
.smd-modal{width:960px;height:700px;max-width:calc(100vw - 32px);max-height:calc(100vh - 48px);padding:0;display:flex;flex-direction:column;overflow:hidden;border-radius:14px}
.smd-hd{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--border);flex-shrink:0}
.smd-hd-title{font-family:'Geist',system-ui,-apple-system,sans-serif;font-size:13px;font-weight:600;color:var(--charcoal);letter-spacing:-.01em}
.smd-close-btn{width:26px;height:26px;border-radius:6px;border:none;background:transparent;color:var(--muted);display:flex;align-items:center;justify-content:center;cursor:pointer;padding:0;transition:background .15s,color .15s}
.smd-close-btn:hover{background:rgba(0,0,0,.05);color:var(--charcoal)}
.smd-body{display:flex;flex:1;overflow:hidden;min-height:0}
.smd-nav{width:148px;flex-shrink:0;border-right:1px solid var(--border);padding:10px 8px;display:flex;flex-direction:column;gap:2px;overflow-y:auto}
.smd-ni{display:block;width:100%;text-align:left;padding:7px 10px;border-radius:7px;border:none;background:transparent;font-family:'Geist',system-ui,-apple-system,sans-serif;font-size:13px;font-weight:400;color:var(--muted);cursor:pointer;transition:background .12s,color .12s;letter-spacing:-.01em}
.smd-ni:hover{background:rgba(0,0,0,.04);color:var(--charcoal)}
.smd-ni.active{background:var(--glt);color:var(--charcoal);font-weight:500}
.smd-content{flex:1;overflow-y:auto;padding:16px 26px 20px;min-width:0}
.smd-panel{display:none}.smd-panel.active{display:block}
.smd-panel-hd{margin-bottom:18px}
.smd-panel-title{font-family:'Geist',system-ui,-apple-system,sans-serif;font-size:15px;font-weight:700;color:var(--charcoal);letter-spacing:-.03em}
.smd-section{padding-bottom:18px;margin-bottom:18px;border-bottom:1px solid var(--border)}
.smd-section:last-child{border-bottom:none;margin-bottom:0;padding-bottom:0}
.smd-field-lbl{font-size:13px;font-weight:500;color:var(--charcoal);margin-bottom:3px}
.smd-field-help{font-size:12px;color:var(--muted);line-height:1.5}
.smd-field-val{font-size:13px;color:var(--charcoal);padding:8px 11px;background:var(--sf2);border:1px solid var(--border);border-radius:7px;word-break:break-all;margin-top:8px}
.smd-input-row{display:flex;gap:8px;align-items:center;margin-top:10px}
.smd-input-row .inp{flex:1}

/* Theme picker */
.smd-theme-row{display:flex;gap:10px;margin-top:12px}
.smd-theme-opt{flex:1;cursor:pointer;border-radius:9px;border:2px solid var(--border);padding:10px 8px 8px;text-align:center;transition:border-color .15s;user-select:none}
.smd-theme-opt:hover{border-color:var(--gm)}
.smd-theme-opt.active{border-color:var(--green)}
.smd-theme-prev{height:50px;border-radius:5px;overflow:hidden;display:flex;margin-bottom:7px}
.smd-theme-lt{background:#F0EEEB}
.smd-theme-dk{background:#141414}
.smd-theme-sys{background:linear-gradient(90deg,#F0EEEB 50%,#141414 50%)}
.smd-tp-sb{width:30%;background:#D8D4CE}
.smd-tp-sb-dk{background:#252525}
.smd-tp-main{flex:1;padding:5px;display:flex;flex-direction:column;gap:3px}
.smd-tp-card{flex:1;background:#fff;border-radius:2px}
.smd-tp-card-dk{background:#2a2a2a}
.smd-theme-lbl{font-size:11px;font-weight:500;color:var(--muted);letter-spacing:.01em}
.smd-theme-opt.active .smd-theme-lbl{color:var(--charcoal)}

/* Notification rows */
.smd-tgl-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 0;border-bottom:1px solid var(--border)}
.smd-tgl-row:last-child{border-bottom:none;padding-bottom:0}
.smd-tgl-lbl{font-size:13px;font-weight:500;color:var(--charcoal);margin-bottom:2px}
.smd-tgl-sub{font-size:12px;color:var(--muted)}

/* Danger Zone */
.smd-danger-zone{margin-top:24px;border:1px solid rgba(239,68,68,.2);border-radius:10px;padding:16px 18px;background:rgba(239,68,68,.02)}
.smd-danger-title{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:#ef4444;margin-bottom:10px;opacity:.75}
.smd-danger-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid rgba(239,68,68,.1)}
.smd-danger-row-last{border-bottom:none;padding-bottom:0}
.smd-danger-btn{flex-shrink:0;padding:7px 14px;border-radius:7px;font-size:12px;font-weight:500;font-family:'Geist',system-ui,sans-serif;border:1px solid var(--border);background:transparent;color:var(--charcoal);cursor:pointer;transition:background .12s;white-space:nowrap}
.smd-danger-btn:hover{background:rgba(0,0,0,.05)}
.smd-danger-btn-del{border-color:rgba(239,68,68,.35);color:#ef4444}
.smd-danger-btn-del:hover{background:rgba(239,68,68,.07)}

/* Dark mode overrides */
body.dark-mode .smd-close-btn:hover{background:rgba(255,255,255,.07) !important}
body.dark-mode .smd-ni:hover{background:rgba(255,255,255,.06) !important}
body.dark-mode .smd-field-val{background:rgba(255,255,255,.04) !important}
body.dark-mode .smd-danger-zone{background:rgba(239,68,68,.04) !important}
body.dark-mode .smd-danger-btn:hover{background:rgba(255,255,255,.06) !important}
body.dark-mode .smd-danger-btn-del:hover{background:rgba(239,68,68,.1) !important}

/* Responsive */
@media (max-width: 900px){
  /* Tablet: adaptive width — previously jumped straight from the 960x700
     desktop size to the 600px bottom sheet with nothing in between. */
  .smd-modal{width:min(720px, calc(100vw - 48px));height:min(640px, calc(100vh - 64px))}
}
@media (max-width: 600px){
  .smd-modal{width:100%;height:88vh;max-height:88vh;border-radius:12px 12px 0 0;align-self:flex-end;margin-bottom:0}
  /* Previously .smd-nav{display:none} with no replacement — that hid the
     tab strip entirely, leaving 5 of 6 Settings panels unreachable on any
     <=600px viewport (confirmed by direct read before this fix). Convert
     to a horizontal-scroll strip instead, same pattern already proven at
     .bb-tab-bar (styles.css, Brand tab): overflow-x:auto, hidden scrollbar. */
  .smd-body{flex-direction:column}
  .smd-nav{
    width:100%; flex-direction:row; overflow-x:auto; overflow-y:hidden;
    scrollbar-width:none; border-right:none; border-bottom:1px solid var(--border);
    padding:8px 10px; gap:4px;
  }
  .smd-nav::-webkit-scrollbar{display:none}
  .smd-ni{flex-shrink:0; white-space:nowrap}
  .smd-content{padding:16px 18px 28px}
}


/* ── Subscription: Plan Comparison Grid ─────────────────────── */
.sub-plans-sep{height:1px;background:var(--border);margin:14px 0 10px}
.sub-plans-hd{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin-bottom:8px;opacity:.65}
.sub-plans-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.sub-pcard{border:1px solid var(--border);border-radius:10px;padding:14px 14px 12px;display:flex;flex-direction:column;gap:8px;background:var(--surface)}
.sub-pcard-active{border-color:var(--green);background:var(--glt)}
.sub-pcard-badge{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;height:16px;display:flex;align-items:center}
.sub-pcard-badge-cur{color:var(--green)}
.sub-pcard-badge-pop{color:var(--muted);opacity:.6}
.sub-pcard-badge-gap{height:16px}
.sub-pcard-name{font-size:14px;font-weight:700;color:var(--charcoal);letter-spacing:-.03em;line-height:1}
.sub-pcard-price{font-size:18px;font-weight:800;color:var(--charcoal);letter-spacing:-.04em;line-height:1}
.sub-pcard-price-cs{font-size:13px;font-weight:600;letter-spacing:0}
.sub-pcard-per{font-size:11px;font-weight:400;color:var(--muted);letter-spacing:0}
.sub-pcard-feats{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:4px;flex:1}
.sub-pcard-feats li{font-size:11px;color:var(--muted);padding-left:10px;position:relative;line-height:1.4}
.sub-pcard-feats li::before{content:'';position:absolute;left:0;top:5px;width:4px;height:4px;border-radius:50%;background:var(--muted);opacity:.45}
.sub-pcard-agency-desc{font-size:11px;color:var(--muted);line-height:1.5;flex:1}
.sub-pcard-btn{display:block;width:100%;padding:7px 8px;border-radius:7px;font-size:12px;font-weight:500;font-family:'Geist',system-ui,sans-serif;cursor:pointer;text-align:center;transition:opacity .12s,background .12s;border:1px solid var(--border);background:transparent;color:var(--charcoal);text-decoration:none;margin-top:auto}
.sub-pcard-btn:hover:not(:disabled){background:rgba(0,0,0,.04)}
.sub-pcard-btn-up{background:var(--green);border-color:var(--green);color:var(--green-deep)}
.sub-pcard-btn-up:hover:not(:disabled){opacity:.88}
.sub-pcard-btn-cur{color:var(--muted);cursor:default;opacity:.6}
.sub-pcard-btn-outline{color:var(--charcoal)}
