body.dark-mode .sub-pcard-btn:hover:not(:disabled){background:rgba(255,255,255,.06) !important}
body.dark-mode .sub-pcard-btn-up:hover:not(:disabled){background:var(--green) !important;opacity:.88}

@media(max-width:760px){.sub-plans-grid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.sub-plans-grid{grid-template-columns:1fr}}

/* ── Ads Manager – Live Campaigns Section ──────────────────────────── */
