.adm-th-check { width: 36px; padding-left: 10px !important; }
.adm-row-check { width: 14px; height: 14px; accent-color: var(--green); cursor: pointer; }
.adm-row-sel { background: color-mix(in srgb, var(--green) 4%, transparent) !important; }
.adm-live-table thead th:first-child { width: 36px; }

/* ── Delete Confirmation Modal ──────────────────────────────────────── */
.adm-delete-modal { max-width: 380px; }
.adm-delete-warn { display: flex; align-items: center; gap: 10px; padding: 10px 14px; background: rgba(248,113,113,.08); border: 1px solid rgba(248,113,113,.15); border-radius: 8px; font-size: 13px; color: #f87171; }
.adm-delete-detail { margin-top: 14px; }
.adm-delete-name { font-size: 14px; font-weight: 600; color: rgba(255,255,255,.9); }
.adm-delete-id { font-size: 11px; color: rgba(255,255,255,.3); font-family: monospace; margin-top: 3px; }
.adm-modal-del-confirm { font-size: 13px; font-weight: 600; padding: 7px 20px; border-radius: 8px; border: none; background: #ef4444; color: #fff; cursor: pointer; transition: background .12s; }
.adm-modal-del-confirm:hover { background: #dc2626; }
.adm-modal-del-confirm:disabled { opacity: .55; cursor: default; }

/* ── Campaign Details Panel ─────────────────────────────────────────── */
.adm-camp-panel { position: fixed; inset: 0; z-index: 900; display: flex; justify-content: flex-end; pointer-events: none; }
.adm-camp-panel-overlay { position: absolute; inset: 0; background: rgba(0,0,0,.4); pointer-events: all; }
.adm-camp-panel-inner { position: relative; width: 340px; max-width: 90vw; background: #1c1c1e; border-left: 1px solid rgba(255,255,255,.08); display: flex; flex-direction: column; pointer-events: all; overflow: hidden; }
.adm-camp-panel-hdr { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; padding: 20px 18px 14px; border-bottom: 1px solid rgba(255,255,255,.07); }
.adm-camp-panel-title { font-size: 15px; font-weight: 600; color: rgba(255,255,255,.9); line-height: 1.35; flex: 1; word-break: break-word; }
.adm-camp-panel-body { flex: 1; overflow-y: auto; padding: 4px 0; }
.adm-panel-row { display: flex; flex-direction: column; gap: 4px; padding: 13px 18px; border-bottom: 1px solid rgba(255,255,255,.04); }
.adm-panel-lbl { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.35); letter-spacing: .04em; text-transform: uppercase; }
.adm-panel-val { font-size: 13px; color: rgba(255,255,255,.8); }
.adm-panel-id { font-family: monospace; font-size: 12px; color: rgba(255,255,255,.4); }
.adm-camp-panel-foot { padding: 14px 18px; border-top: 1px solid rgba(255,255,255,.07); }
.adm-panel-actions { display: flex; flex-wrap: wrap; gap: 7px; }
.adm-panel-btn { font-size: 12px; font-weight: 600; padding: 7px 14px; border-radius: 7px; border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.05); color: rgba(255,255,255,.7); cursor: pointer; transition: background .12s, color .12s; }
.adm-panel-btn:hover { background: rgba(255,255,255,.1); color: #fff; }
.adm-panel-btn.adm-act-pause  { background: rgba(251,191,36,.1);  color: #fbbf24; border-color: rgba(251,191,36,.2); }
.adm-panel-btn.adm-act-resume { background: rgba(99,179,237,.1);  color: #63B3ED; border-color: rgba(99,179,237,.2); }
.adm-panel-btn.adm-act-edit   { background: rgba(255,255,255,.06); color: rgba(255,255,255,.6); border-color: rgba(255,255,255,.12); }
.adm-panel-btn.adm-act-del-panel { color: #f87171; border-color: rgba(248,113,113,.2); background: rgba(248,113,113,.08); }
.adm-panel-btn.adm-act-del-panel:hover { background: rgba(248,113,113,.16); }

/* ── Bulk action bar ────────────────────────────────────────────────── */
.adm-bulk-bar { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 10px; background: #1c1c1e; border: 1px solid rgba(255,255,255,.12); border-radius: 12px; padding: 10px 16px; box-shadow: 0 8px 32px rgba(0,0,0,.5); z-index: 800; white-space: nowrap; }
.adm-bulk-count { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.6); }
.adm-bulk-del { font-size: 12px; font-weight: 600; padding: 6px 14px; border-radius: 7px; border: 1px solid rgba(248,113,113,.2); background: rgba(248,113,113,.1); color: #f87171; cursor: pointer; transition: background .12s; display: flex; align-items: center; gap: 5px; }
.adm-bulk-del:hover { background: rgba(248,113,113,.2); }
.adm-bulk-del:disabled { opacity: .5; cursor: default; }
.adm-bulk-cancel { font-size: 12px; padding: 6px 12px; border-radius: 7px; border: 1px solid rgba(255,255,255,.1); background: transparent; color: rgba(255,255,255,.4); cursor: pointer; }
.adm-bulk-cancel:hover { background: rgba(255,255,255,.06); color: rgba(255,255,255,.7); }

/* ── Toast notifications ────────────────────────────────────────────── */
.adm-toast { position: fixed; bottom: 80px; left: 50%; transform: translateX(-50%) translateY(12px); padding: 10px 18px; border-radius: 8px; font-size: 13px; font-weight: 500; opacity: 0; transition: opacity .25s, transform .25s; z-index: 1100; pointer-events: none; white-space: nowrap; }
.adm-toast-show { opacity: 1; transform: translateX(-50%) translateY(0); }
.adm-toast-ok  { background: rgba(74,222,128,.12); color: #4ade80; border: 1px solid rgba(74,222,128,.2); }
.adm-toast-err { background: rgba(248,113,113,.12); color: #f87171; border: 1px solid rgba(248,113,113,.2); }

/* ======================================================================
   CREATE PAGE - AI Input
====================================================================== */
.aic-outer { display: flex; align-items: center; justify-content: center; min-height: calc(100vh - 60px); padding: 40px 20px; box-sizing: border-box; }
.aic-center { width: 100%; max-width: 600px; }
.aic-brand { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; color: rgba(255,255,255,.3); margin-bottom: 28px; }
.aic-brand svg { opacity: .5; }
.aic-h1 { font-size: 36px; font-weight: 700; color: #fff; line-height: 1.15; margin: 0 0 10px; text-wrap: balance; }
.aic-sub { font-size: 15px; color: rgba(255,255,255,.4); margin: 0 0 28px; line-height: 1.55; }
.aic-input-wrap { background: rgba(255,255,255,.04); border: 1.5px solid rgba(255,255,255,.1); border-radius: 14px; overflow: hidden; transition: border-color .15s; }
.aic-input-wrap:focus-within { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.aic-textarea { display: block; width: 100%; min-height: 100px; padding: 16px 18px 10px; font-size: 15px; font-family: Geist, system-ui, sans-serif; color: rgba(255,255,255,.9); background: transparent; border: none; outline: none; resize: none; line-height: 1.6; box-sizing: border-box; }
.aic-textarea::placeholder { color: rgba(255,255,255,.2); }
.aic-actions { display: flex; align-items: center; justify-content: space-between; padding: 10px 12px 10px 18px; border-top: 1px solid rgba(255,255,255,.06); }
.aic-hint { font-size: 11px; color: rgba(255,255,255,.18); }
.aic-gen-btn { display: inline-flex; align-items: center; gap: 6px; padding: 9px 16px; border-radius: 8px; background: var(--green); color: #0a0a0a; font-size: 13px; font-weight: 700; border: none; cursor: pointer; transition: opacity .12s, transform .1s; font-family: Geist, system-ui, sans-serif; }
.aic-gen-btn:hover { opacity: .88; transform: translateY(-1px); }
.aic-gen-btn:disabled { opacity: .4; cursor: default; transform: none; }
.aic-examples { margin-top: 22px; }
.aic-ex-lbl { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.18); margin-bottom: 10px; }
.aic-ex-pills { display: flex; flex-wrap: wrap; gap: 7px; }
.aic-ex-pill { padding: 7px 12px; border-radius: 20px; border: 1px solid rgba(255,255,255,.08); background: rgba(255,255,255,.03); color: rgba(255,255,255,.4); font-size: 12px; cursor: pointer; transition: background .12s, color .12s, border-color .12s; font-family: Geist, system-ui, sans-serif; text-align: left; }
.aic-ex-pill:hover { background: rgba(255,255,255,.07); color: rgba(255,255,255,.7); border-color: rgba(255,255,255,.14); }

/* ======================================================================
   CREATE PAGE v2  (.cr2-*)
====================================================================== */
.cr2-wrap {
  max-width: 820px;
  margin: 0 auto;
  padding: 32px 28px 60px;
  display: flex;
  flex-direction: column;
  gap: 28px;
}
/* Oriven 1.0 (V10) — Launch fits one viewport now (headline+prompt only);
   centering it vertically reads as a deliberately calm, framed
   composition instead of "content ran out, empty space below." */
/* Scoped to .active — #page-create alone would out-specificity .page{display:none}
   and stay visible even when another page is the active one. */
#page-create.active {
  min-height: calc(100vh - 56px);
  display: flex;
  align-items: center;
  justify-content: center;
}
#page-create .cr2-wrap { padding-top: 0; padding-bottom: 0; }

/* Hero */
.cr2-hero { text-align: center; padding: 8px 0 4px; }

/* Oriven 1.0 (V11) — "Current Business" widget: real, clickable context
   instead of technical "X enabled" badges. */
.cr2-biz-row { display: flex; align-items: center; justify-content: center; gap: 8px; flex-wrap: wrap; }
.orv-biz-lbl { font-size: 12.5px; color: var(--muted, rgba(0,0,0,.45)); }
.orv-biz-sep { color: var(--muted, rgba(0,0,0,.25)); font-size: 12px; }
.orv-biz-chip {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--charcoal, #18181A);
  background: none;
  border: none;
  border-bottom: 1px dashed color-mix(in srgb, var(--green) 50%, transparent);
  padding: 0 1px 1px;
  cursor: pointer;
  transition: border-color .15s, color .15s;
}
.orv-biz-chip:hover { color: var(--green-text); border-bottom-color: var(--green-text); }
body.dark-mode .orv-biz-chip { color: #fff; }
body.dark-mode .orv-biz-chip:hover { color: var(--green); border-bottom-color: var(--green); }
.orv-biz-setup {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12.5px; font-weight: 500;
  color: var(--muted, rgba(0,0,0,.5));
  background: none; border: 1px dashed var(--border, rgba(0,0,0,.15));
  border-radius: 100px; padding: 5px 12px;
  cursor: pointer; transition: border-color .15s, color .15s;
}
.orv-biz-setup:hover { color: var(--green-text); border-color: color-mix(in srgb, var(--green) 50%, transparent); }
body.dark-mode .orv-biz-setup:hover { color: var(--green); }
.cr2-brand-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--accent, #6366f1);
  background: rgba(99,102,241,.08);
  border: 1px solid rgba(99,102,241,.18);
  border-radius: 20px;
  padding: 4px 10px;
  margin-bottom: 14px;
}
.cr2-h1 {
  font-size: 28px;
  font-weight: 800;
  line-height: 1.22;
  letter-spacing: -.02em;
  color: var(--fg, #111);
  margin: 0 0 10px;
  text-wrap: balance;
}
.cr2-sub {
  font-size: 14px;
  color: var(--muted, #888);
  max-width: 560px;
  margin: 0 auto;
  line-height: 1.55;
}

/* Platform selector */
.cr2-plats {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.cr2-plats-lbl {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted, #888);
  margin-right: 4px;
}
/* Oriven 1.0 (V8) — Launch status pills */
.cr2-status-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 10px; }
.cr2-status-pill {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11.5px; font-weight: 500;
  color: var(--muted, rgba(0,0,0,.55));
  background: color-mix(in srgb, var(--green) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--green) 22%, transparent);
  border-radius: 100px;
  padding: 4px 10px 4px 8px;
  opacity: 0;
  animation: cr2StatusIn .4s cubic-bezier(.22,.61,.36,1) forwards;
}
.cr2-status-row .cr2-status-pill:nth-child(1) { animation-delay: .05s; }
.cr2-status-row .cr2-status-pill:nth-child(2) { animation-delay: .12s; }
.cr2-status-row .cr2-status-pill:nth-child(3) { animation-delay: .19s; }
@keyframes cr2StatusIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
.cr2-status-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green-text); flex-shrink: 0; }
body.dark-mode .cr2-status-dot { background: var(--green); }
@media (prefers-reduced-motion: reduce) { .cr2-status-pill { animation: none; opacity: 1; } }
.cr2-pp {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 20px;
  border: 1.5px solid var(--border, #e5e7eb);
  background: transparent;
  font-size: 13px;
  font-weight: 600;
  color: var(--muted, #888);
  cursor: pointer;
  transition: border-color .15s, color .15s, background .15s;
  font-family: inherit;
  white-space: nowrap;
}
.cr2-pp:hover { border-color: var(--green); color: var(--green); }
.cr2-pp.cr2-pp-on {
  border-color: var(--green);
  background: var(--glt);
  color: var(--green);
}
.cr2-pp.cr2-pp-coming {
  opacity: .48;
  cursor: default;
  pointer-events: none;
}
.cr2-cs-tag {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  background: var(--glt);
  color: var(--green);
  border-radius: 4px;
  padding: 1px 5px;
}

/* Prompt box */
.cr2-box {
  border: 1.5px solid var(--border, #e5e7eb);
  border-radius: 16px;
  background: var(--surface, #fff);
  transition: border-color .18s, box-shadow .18s;
  overflow: hidden;
}
.cr2-box:focus-within {
  border-color: var(--green);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 10%, transparent), 0 2px 16px color-mix(in srgb, var(--green) 6%, transparent);
}
.cr2-ta {
  width: 100%;
  box-sizing: border-box;
  padding: 18px 20px 10px;
  border: none;
  outline: none;
  resize: none;
  font-size: 15px;
  font-family: inherit;
  line-height: 1.6;
  color: var(--fg, #111);
  background: transparent;
  min-height: 90px;
}
.cr2-ta::placeholder { color: var(--muted, #aaa); }
.cr2-box-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  padding: 10px 14px 14px;
  gap: 10px;
  border-top: 1px solid var(--border, rgba(0,0,0,.06));
}
body.dark-mode .cr2-box-foot { border-top-color: rgba(255,255,255,.06); }
/* Oriven 1.0 (V10) — Generation Options live inside the prompt footer now,
   grouped left; Generate stays right, same "one intelligent workspace"
   composition modern AI products use. */
.cr2-foot-controls {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  flex: 1;
  min-width: 0;
}
.cr2-foot-group { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.cr2-foot-divider {
  width: 1px;
  height: 20px;
  background: var(--border, rgba(0,0,0,.1));
  flex-shrink: 0;
}
body.dark-mode .cr2-foot-divider { background: rgba(255,255,255,.1); }
.cr2-kbhint {
  font-size: 11px;
  color: var(--muted, #aaa);
  font-family: inherit;
}
.cr2-gen-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 10px 20px;
  border-radius: 10px;
  border: none;
  background: var(--green);
  color: #000;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  transition: opacity .15s, transform .15s, box-shadow .15s;
  box-shadow: 0 2px 12px color-mix(in srgb, var(--green) 20%, transparent);
  white-space: nowrap;
}
.cr2-gen-btn svg { transition: transform .18s; }
.cr2-gen-btn:hover { opacity: .92; transform: translateY(-1px); box-shadow: 0 4px 18px color-mix(in srgb, var(--green) 28%, transparent); }
.cr2-gen-btn:hover svg { transform: translateX(3px); }
/* Oriven 1.0 (V9) — tactile pressed state ("like pressing a physical
   button, not exaggerated"): quick scale-down + shadow collapse on click. */
.cr2-gen-btn:active { transform: translateY(0) scale(.97); box-shadow: 0 1px 6px color-mix(in srgb, var(--green) 25%, transparent); transition: transform .08s, box-shadow .08s; }
.cr2-gen-btn:disabled { opacity: .45; cursor: default; transform: none; box-shadow: none; }

/* Mobile: .cr2-box-foot's align-items:center vertically centers the Generate
   button against .cr2-foot-controls' FULL height once the platform pills
   wrap onto 2-3 lines at narrow widths — visually overlapping the button on
   top of the wrapped pills. Stack into full-width rows instead (also
   satisfies "Generate button full width" from spec). */
@media (max-width: 480px) {
  .cr2-box-foot { flex-direction: column; align-items: stretch; }
  .cr2-gen-btn { width: 100%; justify-content: center; }
}

/* Campaign Goal — required step, right after platform selection.
   flex-basis:100% inside .cr2-box-foot's flex row puts it on its own full
   line between the controls row and the Generate button, the same
   full-width-row behavior .cr2-box-foot already uses on mobile. */
.cr2-goal-section { flex-basis: 100%; width: 100%; order: 2; }
.cr2-goal-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .04em;
  color: var(--muted, #888);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.cr2-goal-required {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  background: var(--glt);
  color: var(--green);
  border-radius: 4px;
  padding: 1px 5px;
}
.cr2-goal-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}
.cr2-goal-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  padding: 12px 12px 11px;
  border-radius: 12px;
  border: 1.5px solid var(--border, #e5e7eb);
  background: var(--surface, #fff);
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  transition: border-color .18s, box-shadow .18s, background .18s, transform .12s cubic-bezier(.22,.61,.36,1);
}
.cr2-goal-card:hover {
  border-color: var(--green);
  transform: translateY(-2px);
  box-shadow: 0 4px 16px color-mix(in srgb, var(--green) 12%, transparent);
}
.cr2-goal-card:active { transform: translateY(-1px) scale(.98); }
.cr2-goal-card.cr2-goal-card-on {
  border-color: var(--green);
  background: var(--glt);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 16%, transparent), 0 4px 20px color-mix(in srgb, var(--green) 18%, transparent);
}
.cr2-goal-card.cr2-goal-card-disabled { opacity: .4; cursor: not-allowed; }
.cr2-goal-card.cr2-goal-card-disabled:hover { transform: none; }
/* Missing-selection nudge (parallels .cr2-box's own focus/error treatment) */
.cr2-goal-section.cr2-goal-missing .cr2-goal-grid { animation: cr2GoalShake .4s; }

/* Campaign Structure (Launch) — honest static note, shown for platforms/
   campaign types with no real multi-group backend support (Google Demand
   Gen / Performance Max). Meta, TikTok, and Google Search get the real
   interactive .cst2-struct-* cards below instead. */
.cr2-struct-note { font-size: 12px; line-height: 1.5; color: var(--muted, #888); margin-top: 4px; max-width: 560px; }

/* ── Campaign Structure Engine — premium expand cards ─────────────────────
   Two cards side by side (stack on mobile), each a green/black "active
   control" pill that expands into a 1-5 pip selector. Only one card open
   at a time (avoids overlap / layout collisions between the two). */
.cst2-struct-row { display: flex; gap: 12px; flex-wrap: wrap; }
.cst2-struct-card {
  flex: 1 1 220px; min-width: 200px;
  background: var(--surface, #fff); border: 1.5px solid var(--border, #e5e7eb);
  border-radius: 14px; overflow: hidden;
  box-shadow: 0 1px 2px rgba(0,0,0,.03);
  transition: border-color .2s ease, box-shadow .2s ease;
}
.cst2-struct-card.cst2-struct-open { border-color: var(--green); box-shadow: 0 4px 20px color-mix(in srgb, var(--green) 20%, transparent); }
.cst2-struct-head {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  gap: 10px; padding: 14px 16px; border: none; cursor: pointer; font-family: inherit;
  background: var(--green); color: #000;
  transition: transform .15s cubic-bezier(.22,.61,.36,1), opacity .15s ease;
}
.cst2-struct-head:hover { opacity: .92; }
.cst2-struct-head:active { transform: scale(.99); }
.cst2-struct-label { font-size: 11px; font-weight: 800; letter-spacing: .05em; }
.cst2-struct-value { font-size: 22px; font-weight: 800; font-variant-numeric: tabular-nums; }
.cst2-struct-hint { padding: 7px 16px; font-size: 11px; font-weight: 600; color: var(--muted, #888); background: var(--surface, #fff); }
.cst2-struct-open .cst2-struct-hint { display: none; }

/* Expand/collapse — height+opacity+transform, 220ms, premium easing;
   max-height is generous (not measured) since content is fixed/small. */
.cst2-struct-expand {
  max-height: 0; opacity: 0; transform: translateY(-4px) scale(.98);
  overflow: hidden; padding: 0 16px;
  transition: max-height .22s cubic-bezier(.22,.61,.36,1), opacity .18s ease, transform .22s cubic-bezier(.22,.61,.36,1), padding .22s cubic-bezier(.22,.61,.36,1);
}
.cst2-struct-open .cst2-struct-expand {
  max-height: 120px; opacity: 1; transform: translateY(0) scale(1);
  padding: 14px 16px 16px;
}
.cst2-pip-row { display: flex; gap: 6px; }
