@media (max-width: 600px) { .cst-struct-nav { padding: 0 16px 12px; } }
.cr2-goal-section.cr2-goal-missing .cr2-goal-card { border-color: rgba(248,113,113,.5); }
@keyframes cr2GoalShake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-3px); }
  75% { transform: translateX(3px); }
}
.cr2-goal-icon { font-size: 18px; line-height: 1; }
.cr2-goal-title {
