}

/* Section label */
.cr2-sect-lbl {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted, #aaa);
  margin-bottom: 12px;
}

/* Example cards */
.cr2-ex-sect {}
.cr2-ex-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.cr2-ex-card {
  border: 1.5px solid var(--border, #e5e7eb);
  border-radius: 12px;
  padding: 14px 16px;
  cursor: pointer;
  background: var(--surface, #fff);
  transition: border-color .18s, box-shadow .18s, background .18s, transform .18s cubic-bezier(.22,.61,.36,1);
  text-align: left;
}
.cr2-ex-card:hover {
  border-color: var(--green);
  box-shadow: 0 8px 22px color-mix(in srgb, var(--green) 14%, transparent);
  background: color-mix(in srgb, var(--green) 2%, transparent);
  transform: translateY(-2px);
}
.cr2-ex-card:active { transform: translateY(-1px) scale(.99); }
.cr2-ex-plat {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--muted, #999);
  margin-bottom: 6px;
}
.cr2-ex-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--fg, #111);
  margin-bottom: 4px;
  line-height: 1.3;
}
.cr2-ex-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; }
.cr2-ex-tag {
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 10px;
  background: var(--bg, #f5f5f5);
