  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.cr2-rec-info { flex: 1; min-width: 0; }
.cr2-rec-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--fg, #111);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cr2-rec-meta { font-size: 11px; color: var(--muted, #aaa); margin-top: 2px; }
.cr2-rec-open {
  font-size: 11px;
  font-weight: 700;
  color: var(--green);
  flex-shrink: 0;
  opacity: 0;
  transition: opacity .14s;
}
.cr2-rec-item:hover .cr2-rec-open { opacity: 1; }

/* AI Tip card */
.cr2-tip-card {
  border: 1.5px solid var(--border, #e5e7eb);
  border-radius: 14px;
  padding: 16px 18px;
  background: var(--surface, #fff);
}
