  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 10px;
}
.cr2-tip-ico { font-size: 16px; line-height: 1; }
.cr2-tip-lbl {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--muted, #aaa);
}
.cr2-tip-body {
  font-size: 13px;
  line-height: 1.6;
  color: var(--fg, #333);
  margin: 0;
