body.dark-mode .cr2-ex-tag { background: rgba(255,255,255,.06); color: rgba(255,255,255,.4); }
body.dark-mode .cr2-rec-item { border-color: rgba(255,255,255,.1); background: rgba(255,255,255,.02); }
body.dark-mode .cr2-rec-item:hover { border-color: var(--green); }
body.dark-mode .cr2-rec-name { color: #f0f0f0; }
body.dark-mode .cr2-rec-meta { color: rgba(255,255,255,.35); }
body.dark-mode .cr2-rec-plat { background: rgba(255,255,255,.06); }
body.dark-mode .cr2-rec-open { color: var(--green); }
body.dark-mode .cr2-tip-card { border-color: rgba(255,255,255,.1); background: rgba(255,255,255,.02); }
body.dark-mode .cr2-tip-body { color: rgba(255,255,255,.65); }
body.dark-mode .cr2-tip-lbl { color: rgba(255,255,255,.3); }
body.dark-mode .cr2-recent-empty { color: rgba(255,255,255,.3); }
body.dark-mode .cr2-sect-lbl { color: rgba(255,255,255,.25); }
body.dark-mode .cr2-plats-lbl { color: rgba(255,255,255,.3); }
body.dark-mode .cr2-goal-label { color: rgba(255,255,255,.4); }
