.cst-shop-title { font-size: 13.5px; color: #202124; line-height: 1.4; margin-bottom: 6px; }
.cst-shop-store { font-size: 11.5px; color: #70757a; }

/* Display / Demand Gen banner */
.cst-mock-display { width: 100%; max-width: 460px; margin: 0 auto; background: #fff; border-radius: 14px; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,.4); font-family: arial, sans-serif; }
.cst-disp-img { width: 100%; aspect-ratio: 1.91/1; background: #f0f0f0; display: flex; align-items: center; justify-content: center; overflow: hidden; }
