.cst-disp-body { padding: 14px 16px; }
.cst-disp-brand { font-size: 11px; font-weight: 700; color: #70757a; text-transform: uppercase; letter-spacing: .04em; margin-bottom: 4px; }
.cst-disp-hl { font-size: 16px; font-weight: 600; color: #202124; line-height: 1.3; margin-bottom: 4px; }
.cst-disp-desc { font-size: 13px; color: #4d5156; line-height: 1.5; margin-bottom: 10px; }
