.cst-disp-adtag { display: inline-block; font-size: 10px; font-weight: 700; color: #70757a; border: 1px solid #dadce0; border-radius: 3px; padding: 1px 5px; margin-bottom: 8px; }

/* Discover feed card */
.cst-mock-discover { width: 100%; max-width: 400px; margin: 0 auto; background: #fff; border-radius: 16px; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,.4); font-family: arial, sans-serif; }
.cst-disc-img { width: 100%; aspect-ratio: 16/9; background: #f0f0f0; display: flex; align-items: center; justify-content: center; overflow: hidden; }
.cst-disc-img img { width: 100%; height: 100%; object-fit: cover; }
.cst-disc-body { padding: 13px 15px 16px; }
.cst-disc-brand-row { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.cst-disc-sponsored { font-size: 11px; color: #70757a; }
.cst-disc-hl { font-size: 15.5px; font-weight: 600; color: #202124; line-height: 1.35; margin-bottom: 4px; }
.cst-disc-desc { font-size: 13px; color: #4d5156; line-height: 1.5; }

/* Maps */
.cst-mock-maps { width: 100%; max-width: 460px; margin: 0 auto; border-radius: 16px; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,.4); background: #e8eaed; }
.cst-maps-canvas { position: relative; height: 200px; background-image: radial-gradient(rgba(0,0,0,.06) 1px, transparent 1px); background-size: 18px 18px; background-color: #eef1f4; display: flex; align-items: center; justify-content: center; }
.cst-maps-pin { color: #ea4335; }
.cst-maps-body { background: #fff; padding: 16px; }

/* Gmail */
.cst-mock-gmail { width: 100%; max-width: 460px; margin: 0 auto; background: #fff; border-radius: 14px; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,.4); font-family: arial, sans-serif; }
.cst-gmail-row { display: flex; align-items: center; gap: 12px; padding: 14px 16px; cursor: pointer; }
.cst-gmail-row:hover { background: #f8f9fa; }
.cst-gmail-tag { font-size: 10.5px; font-weight: 700; color: #1a73e8; border: 1px solid #1a73e8; border-radius: 3px; padding: 1px 6px; flex-shrink: 0; }
.cst-gmail-preview { flex: 1; min-width: 0; }
.cst-gmail-subject { font-size: 13.5px; color: #202124; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cst-gmail-snippet { font-size: 12.5px; color: #70757a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cst-gmail-expanded { border-top: 1px solid #ececec; padding: 16px; display: none; }
.cst-gmail-expanded.cst-gmail-open { display: block; }
.cst-gmail-exp-img { width: 100%; aspect-ratio: 1.91/1; background: #f0f0f0; border-radius: 8px; overflow: hidden; margin-bottom: 12px; }
.cst-gmail-exp-img img { width: 100%; height: 100%; object-fit: contain; background: #fafafa; }

/* YouTube (video / image / shorts) */
.cst-mock-ytvideo { width: 100%; max-width: 560px; margin: 0 auto; background: #0f0f0f; border-radius: 14px; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,.5); }
.cst-yt-player { width: 100%; aspect-ratio: 16/9; background: #1a1a1a; display: flex; align-items: center; justify-content: center; position: relative; }
.cst-yt-body { padding: 14px 16px; }
.cst-yt-adtag { font-size: 10.5px; font-weight: 700; color: rgba(255,255,255,.5); text-transform: uppercase; letter-spacing: .04em; margin-bottom: 6px; }
.cst-yt-title { font-size: 15px; font-weight: 600; color: #fff; line-height: 1.3; margin-bottom: 8px; }
.cst-yt-cta-row { display: flex; align-items: center; justify-content: space-between; }
.cst-yt-brand { font-size: 12.5px; color: rgba(255,255,255,.5); }
.cst-yt-cta { font-size: 12px; font-weight: 700; padding: 7px 14px; border-radius: 18px; background: #fff; color: #0f0f0f; border: none; }

.cst-mock-ytimage { width: 100%; max-width: 460px; margin: 0 auto; background: #0f0f0f; border-radius: 14px; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,.5); }
.cst-yti-tag { padding: 10px 14px 0; font-size: 11px; font-weight: 700; color: rgba(255,255,255,.5); text-transform: uppercase; letter-spacing: .04em; }
.cst-yti-img { width: 100%; aspect-ratio: 1.91/1; background: #1a1a1a; overflow: hidden; margin-top: 8px; }
.cst-yti-img img { width: 100%; height: 100%; object-fit: contain; }
.cst-yti-body { padding: 12px 14px 16px; }
.cst-yti-hl { font-size: 14.5px; font-weight: 600; color: #fff; margin-bottom: 4px; }
.cst-yti-desc { font-size: 12.5px; color: rgba(255,255,255,.55); margin-bottom: 10px; }

.cst-mock-ytshorts { width: 240px; max-width: 76vw; aspect-ratio: 9/16; background: #000; border-radius: 24px; overflow: hidden; position: relative; box-shadow: 0 20px 50px rgba(0,0,0,.55); border: 7px solid #0a0a0a; margin: 0 auto; }

/* Final Polish — real generated-video preview (YouTube "Video" mode),
   same dark-card language as .cst-mock-ytimage next to it. */
.cst-mock-ytvideo { width: 100%; max-width: 460px; margin: 0 auto; background: #0f0f0f; border-radius: 14px; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,.5); padding: 10px 14px 14px; }
.cst-ytvideo-player { width: 100%; aspect-ratio: 16/9; border-radius: 8px; background: #000; display: block; }

/* Performance Max overview grid */
.cst-pmax-intro { text-align: center; max-width: 480px; margin: 0 auto 24px; font-size: 13px; color: rgba(255,255,255,.5); line-height: 1.55; }
.cst-pmax-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; max-width: 720px; margin: 0 auto; }
.cst-pmax-card { border: 1px solid rgba(255,255,255,.08); border-radius: 12px; padding: 16px 14px; background: rgba(255,255,255,.02); cursor: pointer; text-align: left; transition: background .12s, border-color .12s; }
.cst-pmax-card:hover { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.16); }
.cst-pmax-card-icon { font-size: 20px; margin-bottom: 8px; }
.cst-pmax-card-label { font-size: 12.5px; font-weight: 700; color: #fff; margin-bottom: 4px; }
.cst-pmax-card-snippet { font-size: 11.5px; color: rgba(255,255,255,.4); line-height: 1.4; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
@media (max-width: 600px) { .cst-pmax-grid { grid-template-columns: repeat(2, 1fr); } }
.cst-pmax-assetgroup { max-width: 480px; margin: 0 auto 22px; border: 1px solid rgba(255,255,255,.08); border-radius: 12px; padding: 14px 16px; background: rgba(255,255,255,.02); }
.cst-pmax-assetgroup b { display: block; font-size: 11.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: rgba(255,255,255,.45); margin-bottom: 10px; }
.cst-pmax-ag-row { display: flex; align-items: center; justify-content: space-between; font-size: 12.5px; color: rgba(255,255,255,.75); padding: 5px 0; border-top: 1px solid rgba(255,255,255,.05); }
.cst-pmax-ag-row:first-of-type { border-top: none; }

/* Editable list rows (headlines / descriptions / keywords) */
.cst-list { display: flex; flex-direction: column; gap: 7px; }
.cst-list-row { display: flex; align-items: center; gap: 8px; }
.cst-list-row .crv-inp { flex: 1; }
.cst-list-remove { width: 26px; height: 26px; flex-shrink: 0; border-radius: 6px; border: 1px solid rgba(255,255,255,.1); background: rgba(255,255,255,.04); color: rgba(255,255,255,.5); cursor: pointer; font-size: 14px; line-height: 1; }
.cst-list-remove:hover { background: rgba(248,113,113,.12); color: #f87171; border-color: rgba(248,113,113,.25); }
.cst-list-add { align-self: flex-start; font-size: 12px; font-weight: 600; padding: 7px 12px; border-radius: 7px; border: 1px dashed rgba(255,255,255,.18); background: transparent; color: rgba(255,255,255,.55); cursor: pointer; }
.cst-list-add:hover { color: #fff; border-color: rgba(255,255,255,.3); }
.cst-list-add:disabled { opacity: .35; cursor: not-allowed; }
.cst-char-count { font-size: 10.5px; color: rgba(255,255,255,.3); text-align: right; }

/* ── TikTok Ads Preview / Edit / Oriven Review ─────────────────────── */
.cst-mock-tiktok { width: 300px; max-width: 82vw; aspect-ratio: 9/16; background: #000; border-radius: 26px; overflow: hidden; position: relative; box-shadow: 0 20px 50px rgba(0,0,0,.55); border: 8px solid #0a0a0a; margin: 0 auto; }
.cst-tt-top { position: absolute; top: 20px; left: 0; right: 0; z-index: 3; display: flex; justify-content: center; gap: 18px; font-size: 13px; font-weight: 600; color: rgba(255,255,255,.5); }
.cst-tt-top-active { color: #fff; }
.cst-tt-media { position: absolute; inset: 0; background: linear-gradient(160deg, #232326, #101012); display: flex; align-items: center; justify-content: center; }
.cst-tt-media img { width: 100%; height: 100%; object-fit: cover; }
.cst-tt-fade { position: absolute; left: 0; right: 0; bottom: 0; height: 50%; background: linear-gradient(to top, rgba(0,0,0,.78), transparent); z-index: 2; }
.cst-tt-rail { position: absolute; right: 10px; bottom: 90px; z-index: 3; display: flex; flex-direction: column; align-items: center; gap: 17px; color: #fff; font-size: 18px; }
.cst-tt-rail span { font-size: 8px; font-weight: 600; margin-top: -8px; }
.cst-tt-foot { position: absolute; left: 14px; right: 62px; bottom: 20px; z-index: 3; display: flex; flex-direction: column; gap: 8px; }
.cst-tt-user { font-size: 13px; font-weight: 700; color: #fff; text-shadow: 0 1px 4px rgba(0,0,0,.5); }
.cst-tt-sponsored { font-size: 10.5px; color: rgba(255,255,255,.6); text-transform: uppercase; letter-spacing: .04em; }
.cst-tt-caption { font-size: 12.5px; color: #fff; line-height: 1.4; text-shadow: 0 1px 4px rgba(0,0,0,.5); }
.cst-tt-cta { align-self: flex-start; font-size: 12px; font-weight: 700; color: #000; background: #fff; border-radius: 6px; padding: 7px 14px; }
.cst-tt-empty { display: flex; flex-direction: column; align-items: center; gap: 8px; color: rgba(255,255,255,.35); font-size: 12px; text-align: center; padding: 0 24px; }

/* ── V4 AI REVIEW ────────────────────────────────────────────────── */
.v4r-wrap { padding: 0 0 40px; display: flex; flex-direction: column; gap: 24px; }

/* Hero score */
.v4r-hero { display: flex; align-items: center; gap: 28px; padding: 28px 28px 24px; background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.07); border-radius: 16px; }
.v4r-ring-wrap { position: relative; flex-shrink: 0; }
.v4r-ring-inner { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.v4r-score-num { font-size: 30px; font-weight: 800; color: #fff; letter-spacing: -.03em; line-height: 1; }
.v4r-score-denom { font-size: 11px; color: rgba(255,255,255,.35); margin-top: 2px; }
.v4r-hero-body { flex: 1; min-width: 0; }
.v4r-hero-kicker { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.35); margin-bottom: 6px; }
.v4r-hero-grade { font-size: 28px; font-weight: 800; letter-spacing: -.02em; margin-bottom: 4px; }
.v4r-grade-a { color: #4ade80; }
.v4r-grade-b { color: var(--green); }
.v4r-grade-c { color: #fbbf24; }
.v4r-grade-d { color: #f87171; }
.v4r-hero-verdict { font-size: 13px; color: rgba(255,255,255,.5); margin-bottom: 16px; }
.v4r-hero-btns { display: flex; gap: 8px; flex-wrap: wrap; }
.v4r-hero-btn { font-size: 12px; font-weight: 600; padding: 7px 14px; border-radius: 8px; border: 1px solid rgba(255,255,255,.14); background: rgba(255,255,255,.07); color: rgba(255,255,255,.7); cursor: pointer; transition: background .12s, color .12s; white-space: nowrap; }
.v4r-hero-btn:hover { background: rgba(255,255,255,.12); color: #fff; }
.v4r-hero-btn-primary { background: var(--green); color: #000; border-color: transparent; }
.v4r-hero-btn-primary:hover { background: var(--gm); color: #000; }

/* Score breakdown */
.v4r-breakdown { padding: 20px 24px; background: rgba(255,255,255,.02); border: 1px solid rgba(255,255,255,.06); border-radius: 14px; }
.v4r-sect-title { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.3); margin-bottom: 16px; }
.v4r-cats-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 14px 20px; }
.v4r-cat { }
.v4r-cat-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 5px; }
.v4r-cat-name { font-size: 12px; color: rgba(255,255,255,.6); }
.v4r-cat-val { font-size: 12px; font-weight: 700; font-variant-numeric: tabular-nums; }
.v4r-val-hi { color: #4ade80; }
.v4r-val-md { color: var(--green); }
.v4r-val-lo { color: #fbbf24; }
.v4r-track { height: 4px; background: rgba(255,255,255,.07); border-radius: 2px; overflow: hidden; }
.v4r-bar { height: 100%; border-radius: 2px; transition: width 1s cubic-bezier(.4,0,.2,1); }
.v4r-bar-hi { background: #4ade80; }
.v4r-bar-md { background: var(--green); }
.v4r-bar-lo { background: #fbbf24; }

/* Strengths + Weaknesses */
.v4r-sw { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.v4r-sw-card { padding: 18px 20px; background: rgba(255,255,255,.02); border: 1px solid rgba(255,255,255,.06); border-radius: 14px; }
.v4r-sw-hd { display: flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.4); margin-bottom: 12px; }
.v4r-sw-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
.v4r-dot-green { background: #4ade80; box-shadow: 0 0 6px rgba(74,222,128,.5); }
.v4r-dot-amber { background: #fbbf24; box-shadow: 0 0 6px rgba(251,191,36,.4); }
.v4r-dot-blue  { background: #63B3ED; box-shadow: 0 0 6px rgba(99,179,237,.4); }
.v4r-sw-list { margin: 0; padding: 0 0 0 16px; list-style: disc; display: flex; flex-direction: column; gap: 7px; }
.v4r-sw-list li { font-size: 13px; color: rgba(255,255,255,.65); line-height: 1.4; }

/* Suggestions */
.v4r-sugg-sect { display: flex; flex-direction: column; gap: 8px; }
.v4r-sugg-item { display: flex; align-items: center; gap: 12px; padding: 13px 16px; background: rgba(255,255,255,.02); border: 1px solid rgba(255,255,255,.06); border-radius: 10px; cursor: pointer; transition: background .12s, border-color .12s; }
.v4r-sugg-item:hover { background: color-mix(in srgb, var(--green) 4%, transparent); border-color: color-mix(in srgb, var(--green) 20%, transparent); }
.v4r-sugg-ico { font-size: 18px; flex-shrink: 0; }
.v4r-sugg-text { flex: 1; font-size: 13px; color: rgba(255,255,255,.7); }
.v4r-sugg-arr { color: rgba(255,255,255,.2); font-size: 14px; transition: color .12s, transform .12s; }
.v4r-sugg-item:hover .v4r-sugg-arr { color: var(--green); transform: translateX(3px); }

/* One-Click Actions */
.v4r-actions { }
.v4r-action-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.v4r-act-btn { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 14px 10px; background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.07); border-radius: 12px; cursor: pointer; transition: background .14s, border-color .14s, transform .12s; text-align: center; }
.v4r-act-btn:hover { background: rgba(255,255,255,.07); border-color: rgba(255,255,255,.14); transform: translateY(-1px); }
.v4r-act-ico { font-size: 20px; }
.v4r-act-lbl { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.6); letter-spacing: .1px; line-height: 1.3; }
.v4r-act-btn:hover .v4r-act-lbl { color: rgba(255,255,255,.9); }

/* Light-mode V4 review */
body:not(.dark-mode) .v4r-hero { background: rgba(0,0,0,.025); border-color: rgba(0,0,0,.07); }
body:not(.dark-mode) .v4r-score-num { color: #18181a; }
body:not(.dark-mode) .v4r-hero-btn { background: rgba(0,0,0,.06); color: rgba(0,0,0,.6); border-color: rgba(0,0,0,.1); }
body:not(.dark-mode) .v4r-hero-btn:hover { background: rgba(0,0,0,.1); color: #18181a; }
body:not(.dark-mode) .v4r-hero-kicker,.body:not(.dark-mode) .v4r-hero-verdict { color: rgba(0,0,0,.4); }
body:not(.dark-mode) .v4r-breakdown,.body:not(.dark-mode) .v4r-sw-card { background: rgba(0,0,0,.02); border-color: rgba(0,0,0,.06); }
body:not(.dark-mode) .v4r-cat-name { color: rgba(0,0,0,.55); }
body:not(.dark-mode) .v4r-track { background: rgba(0,0,0,.07); }
body:not(.dark-mode) .v4r-sw-list li { color: rgba(0,0,0,.65); }
body:not(.dark-mode) .v4r-sugg-item { background: rgba(0,0,0,.02); border-color: rgba(0,0,0,.06); }
body:not(.dark-mode) .v4r-sugg-text { color: rgba(0,0,0,.65); }
body:not(.dark-mode) .v4r-act-btn { background: rgba(0,0,0,.025); border-color: rgba(0,0,0,.07); }
body:not(.dark-mode) .v4r-act-lbl { color: rgba(0,0,0,.55); }

/* AI Review tab icon alignment */
.crv-tab svg { vertical-align: middle; }

@media (max-width: 900px) {
  .v4r-cats-grid { grid-template-columns: 1fr 1fr; }
  .v4r-action-grid { grid-template-columns: repeat(3, 1fr); }
  .v4r-sw { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .v4r-hero { flex-direction: column; align-items: flex-start; gap: 16px; }
  .v4r-cats-grid { grid-template-columns: 1fr; }
  .v4r-action-grid { grid-template-columns: repeat(2, 1fr); }
}

.crv-validation { margin: 0 32px 28px; padding: 14px 18px; background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.07); border-radius: 10px; }
.crv-val-hd { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; color: rgba(255,255,255,.28); margin-bottom: 11px; }
.crv-val-items { display: flex; flex-direction: column; gap: 7px; }
.crv-val-item { display: flex; align-items: flex-start; gap: 8px; font-size: 12px; line-height: 1.4; }
.crv-val-ico { flex-shrink: 0; font-size: 12px; }
.crv-val-pass { color: rgba(255,255,255,.45); }
.crv-val-fail { color: #f87171; }
.crv-val-warn { color: #fbbf24; }

@keyframes aicSpin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

/* AI Note — shown below field when AI budget explanation is longer than clean value */
.crv-ai-note { display: flex; align-items: flex-start; gap: 6px; margin-top: 5px; padding: 7px 10px; background: color-mix(in srgb, var(--green) 4%, transparent); border: 1px solid color-mix(in srgb, var(--green) 10%, transparent); border-radius: 6px; font-size: 11px; color: rgba(255,255,255,.38); line-height: 1.5; }

/* ══════════════════════════════════════════════════════════════
   V8 PHASE 2 — CREATIVE WORKSPACE (crws-*)
   Three-column layout: left context/history, center canvas/versions,
   right preview/score/director, bottom persistent chat dock.
   Reuses .oi-card/.ov3-*/.orv-ai-msg-*/.clib-status-* throughout —
   no duplicated component system.
   ══════════════════════════════════════════════════════════════ */
#page-creative-workspace { display: none; flex-direction: column; height: calc(100vh - 64px); }
#page-creative-workspace.active { display: flex; }

/* Compact page header — Studio previously had no title/purpose statement
   at all, unlike every other workspace; kept small since the 3-column
   layout below is the actual point of the page. */
.crws-hdr { padding: 14px 20px 0; flex-shrink: 0; }
.crws-hdr-title { font-size: 18px; font-weight: 700; letter-spacing: -.3px; color: var(--charcoal, #18181A); margin: 0 0 2px; }
.crws-hdr-sub { font-size: 12px; color: var(--muted, rgba(0,0,0,.5)); margin: 0 0 12px; }

.crws-layout {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 240px 1fr 300px;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}
.crws-col { background: var(--bg); overflow-y: auto; padding: 16px; display: flex; flex-direction: column; gap: 16px; min-width: 0; }
.crws-left { }
/* Bug fix (Intelligence + Studio Refinement sprint): #crwsBrainSummary
   ("Brand Knowledge Completeness") is the only place in the app that wraps
   .ov3-health-badge inside .ov3-insight — a shrink-to-fit, nowrap pill
   component designed for short one-line chips, never meant to contain a
   full health-score widget. In the 240px left column that fought the
   badge's own `width:100%` and pushed content past the card edge. Give it
   its own container behavior instead of the pill's. */
.crws-brain-summary.ov3-insight {
  display: block;
  width: 100%;
  white-space: normal;
  overflow: hidden;
  box-sizing: border-box;
}
.crws-center { padding: 0; display: flex; flex-direction: column; }
.crws-right { }
.crws-sect { display: flex; flex-direction: column; gap: 8px; }
.crws-sect-grow { flex: 1; min-height: 0; }
.crws-sect-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }

@media (max-width: 1100px) {
  .crws-layout { grid-template-columns: 1fr; grid-auto-rows: min-content; overflow-y: auto; }
  .crws-col { overflow-y: visible; }
}

/* Search */
.crws-search-wrap { position: relative; }
.crws-search-inp { width: 100%; font-size: 12.5px; padding: 8px 10px; border-radius: 8px; border: 1px solid var(--border); background: transparent; color: var(--charcoal); box-sizing: border-box; }
.crws-search-results { position: absolute; top: calc(100% + 4px); left: 0; right: 0; z-index: 40; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; box-shadow: 0 12px 32px rgba(0,0,0,.14); max-height: 320px; overflow-y: auto; }
.crws-search-item { padding: 8px 10px; font-size: 12.5px; cursor: pointer; display: flex; gap: 8px; align-items: center; border-bottom: 1px solid var(--border); }
.crws-search-item:last-child { border-bottom: none; }
.crws-search-item:hover { background: var(--bg2); }
.crws-search-type { font-size: 9px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); border: 1px solid var(--border); border-radius: 4px; padding: 1px 5px; flex-shrink: 0; }
.crws-search-empty { padding: 10px; font-size: 12px; color: var(--muted); }

/* Selects + pills */
/* Bug fix (Intelligence + Studio Refinement sprint) — Product selector was
   unreadable: background:transparent meant the native option-list popup
   fell back to whatever the browser/OS renders (often white), while the
   text color still followed the app's theme variable, so dark-mode's light
   text landed on that white popup. Explicit background + matching <option>
   colors fix both themes, same fix already applied to Campaigns' .prf-select. */
.crws-select { width: 100%; font-size: 12.5px; padding: 7px 9px; border-radius: 7px; border: 1px solid var(--border); background: var(--surface); color: var(--charcoal); box-sizing: border-box; }
.crws-select option { background: var(--surface); color: var(--charcoal); }
.crws-platform-pills, .crws-preview-tabs, .crws-preview-device-toggle { display: flex; gap: 6px; flex-wrap: wrap; }
.crws-pill { font-size: 11px; padding: 5px 10px; border-radius: 20px; border: 1px solid var(--border); background: transparent; color: var(--muted); cursor: pointer; transition: background .14s, color .14s; }
.crws-pill:hover { background: var(--bg2); }
.crws-pill-active { background: color-mix(in srgb, var(--green) 14%, transparent); color: var(--charcoal); border-color: color-mix(in srgb, var(--green) 30%, transparent); font-weight: 600; }

/* History list */
.crws-history-list { display: flex; flex-direction: column; gap: 6px; overflow-y: auto; }
.crws-hist-item { padding: 8px 9px; border-radius: 8px; border: 1px solid var(--border); cursor: pointer; transition: background .14s; }
.crws-hist-item:hover { background: var(--bg2); }
.crws-hist-kind { font-size: 9px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
.crws-hist-title { font-size: 12.5px; font-weight: 500; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.crws-hist-date { font-size: 10.5px; color: var(--muted); margin-top: 2px; }

/* Canvas (center) */
.crws-version-strip { display: flex; gap: 6px; padding: 10px 20px; border-bottom: 1px solid var(--border); overflow-x: auto; flex-shrink: 0; }
.crws-version-chip { font-size: 11px; padding: 5px 10px; border-radius: 20px; border: 1px solid var(--border); background: transparent; color: var(--muted); cursor: pointer; white-space: nowrap; }
.crws-version-active { background: color-mix(in srgb, var(--green) 14%, transparent); color: var(--charcoal); border-color: color-mix(in srgb, var(--green) 30%, transparent); font-weight: 600; }
.crws-canvas { flex: 1; min-height: 0; overflow-y: auto; padding: 24px; display: flex; align-items: center; justify-content: center; }
.crws-empty { text-align: center; max-width: 320px; }
.crws-canvas-text { width: 100%; min-height: 240px; resize: vertical; font-size: 13.5px; line-height: 1.6; padding: 14px; border-radius: 10px; border: 1px solid var(--border); background: transparent; color: var(--charcoal); font-family: inherit; box-sizing: border-box; }
.crws-canvas-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 12px 20px; border-top: 1px solid var(--border); flex-shrink: 0; }
.crws-status-select { width: auto; min-width: 140px; margin-left: auto; }
.crws-status-badge { text-transform: capitalize; }

/* Live Preview frames */
.crws-preview-frame { border-radius: 10px; overflow: hidden; border: 1px solid var(--border); background: var(--surface); transition: max-width .18s ease; margin: 0 auto; }
.crws-device-desktop .crws-preview-frame, .crws-preview-frame { max-width: 100%; }
.crws-device-tablet .crws-preview-frame { max-width: 420px; }
.crws-device-mobile .crws-preview-frame { max-width: 280px; }
#crwsPreviewFrame.crws-device-tablet { max-width: 420px; margin: 0 auto; }
#crwsPreviewFrame.crws-device-mobile { max-width: 280px; margin: 0 auto; }

.crws-pv-google { padding: 14px; font-family: arial, sans-serif; }
.crws-pv-g-ad { display: inline-block; font-size: 10px; font-weight: 700; color: #fff; background: #616161; border-radius: 3px; padding: 0 4px; margin-bottom: 4px; }
.crws-pv-g-headline { font-size: 16px; color: #1a0dab; margin-bottom: 2px; }
.crws-pv-g-url { font-size: 12px; color: #006621; margin-bottom: 4px; }
.crws-pv-g-desc { font-size: 12.5px; color: #545454; line-height: 1.4; }

.crws-pv-meta { display: flex; flex-direction: column; }
.crws-pv-meta img { width: 100%; display: block; max-height: 260px; object-fit: cover; }
.crws-pv-img-ph { width: 100%; height: 200px; background: var(--bg2); }
.crws-pv-meta-body { padding: 10px 12px; }
.crws-pv-meta-headline { font-size: 13.5px; font-weight: 700; }
.crws-pv-meta-text { font-size: 12px; color: var(--muted); margin-top: 3px; line-height: 1.4; }
.crws-pv-meta-cta { margin-top: 8px; font-size: 12px; font-weight: 600; padding: 6px 12px; border-radius: 6px; background: var(--bg2); border: 1px solid var(--border); color: var(--charcoal); }

.crws-pv-tiktok { position: relative; aspect-ratio: 9/16; max-height: 420px; background: #000; overflow: hidden; }
.crws-pv-tiktok img { width: 100%; height: 100%; object-fit: cover; opacity: .85; }
.crws-pv-tiktok-overlay { position: absolute; left: 0; right: 0; bottom: 0; padding: 16px; background: linear-gradient(transparent, rgba(0,0,0,.7)); color: #fff; }
.crws-pv-tiktok-hook { font-size: 13px; font-weight: 700; }
.crws-pv-tiktok-cta { margin-top: 8px; display: inline-block; font-size: 11px; font-weight: 700; padding: 6px 14px; border-radius: 20px; background: #fff; color: #000; }

.crws-pv-email-frame, .crws-pv-lp-frame { width: 100%; height: 420px; border: none; background: #fff; }

/* Compare modal */
.cmp-panel { max-width: 900px; }
.cmp-body { padding: 22px 24px 26px; overflow-y: auto; flex: 1; }

/* Chat dock (bottom) */
.crws-chat-dock { flex-shrink: 0; border-top: 1px solid var(--border); background: var(--surface); display: flex; flex-direction: column; max-height: 220px; }
.crws-chat-feed { flex: 1; overflow-y: auto; padding: 10px 20px; display: flex; flex-direction: column; gap: 8px; }
.crws-chat-input-row { display: flex; gap: 8px; padding: 10px 20px; border-top: 1px solid var(--border); }
.crws-chat-inp { flex: 1; font-size: 13px; padding: 9px 12px; border-radius: 20px; border: 1px solid var(--border); background: transparent; color: var(--charcoal); }
.crws-chat-send { font-size: 12.5px; font-weight: 600; padding: 8px 16px; border-radius: 20px; background: color-mix(in srgb, var(--green) 90%, transparent); border: none; color: #0a0a0a; cursor: pointer; }

body.dark-mode .crws-pv-google { background: #fff; } /* Google SERP stays light even in dark mode, matching reality */

/* ══════════════════════════════════════════════════════════════
   V9 — AUTOPILOT CENTER (ap-op-*)
   Reuses .asl-outer/.oi-card/.ov3-health-badge/.clib-status-*/.cf-panel
   throughout — no new visual system for this page.
   ══════════════════════════════════════════════════════════════ */
#page-autopilot { display: none; }
#page-autopilot.active { display: block; }
.ap-op-outer { max-width: var(--orv-content-maxw); margin: 0 auto; padding: var(--orv-content-pad-top) var(--orv-content-pad-x) var(--orv-content-pad-bottom); }
.ap-op-hdr { margin-bottom: var(--orv-title-gap); }
.ap-op-health-row { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 28px; }
.ap-op-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px; }
@media (max-width: 1000px) { .ap-op-grid { grid-template-columns: 1fr; } }
.ap-op-col { display: flex; flex-direction: column; min-width: 0; }
.ap-op-sect-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.ap-op-list { display: flex; flex-direction: column; gap: 8px; }

/* Autopilot Complete Redesign — Automation Builder. Deliberately plain
   form controls (dropdowns/inputs), never anything that reads as code —
   "almost like building a filter". Generous vertical rhythm per the
   "operational, not another dashboard" brief: breathing room is fine. */
.ap-builder { display: flex; flex-direction: column; gap: 16px; max-width: 720px; }
.ap-builder-row { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.ap-builder-lbl { font-size: 12.5px; font-weight: 600; color: var(--charcoal, #18181A); min-width: 130px; flex-shrink: 0; }
body.dark-mode .ap-builder-lbl { color: var(--text, #e8e8e8); }
.ap-builder-rule { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding-left: 144px; }
@media (max-width: 640px) { .ap-builder-rule { padding-left: 0; } }
.ap-builder-kw {
  font-size: 11px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase;
  color: var(--green-text); background: color-mix(in srgb, var(--green) 12%, transparent); border-radius: 6px; padding: 4px 9px; flex-shrink: 0;
}
body.dark-mode .ap-builder-kw { color: var(--green); }
.ap-builder-inp { width: auto; flex: 1 1 160px; min-width: 120px; }
.ap-builder-preview {
  background: color-mix(in srgb, var(--green) 6%, transparent); border: 1px solid color-mix(in srgb, var(--green) 22%, transparent); border-radius: 12px;
  padding: 14px 16px; font-size: 13.5px; line-height: 1.6; color: var(--charcoal, #18181A);
}
body.dark-mode .ap-builder-preview { color: var(--text, #e8e8e8); background: color-mix(in srgb, var(--green) 5%, transparent); border-color: color-mix(in srgb, var(--green) 18%, transparent); }
.ap-builder-preview strong { color: var(--green-text); }
body.dark-mode .ap-builder-preview strong { color: var(--green); }

/* Autopilot Refinement / Experience Redesign — the Automation Builder
   wizard. A guided conversation, not a form: one question at a time,
   selectable cards instead of dropdowns, a live plain-English review
   instead of a technical rule. Kept visually distinct from Campaigns
   (analytical, data-dense) — Autopilot is operational, roomier, calmer. */
.ap-wiz { max-width: 640px; }
.ap-wiz-step {
  transition: opacity .28s cubic-bezier(.16,1,.3,1), transform .28s cubic-bezier(.16,1,.3,1);
  opacity: 1; transform: translateY(0);
}
.ap-wiz-step-entering { opacity: 0; transform: translateY(16px); }
.ap-wiz-step-leaving { opacity: 0; transform: translateY(-12px); }
.ap-wiz-q {
  font-size: 17px; font-weight: 700; letter-spacing: -.01em; color: var(--charcoal, #18181A); margin-bottom: 16px;
}
body.dark-mode .ap-wiz-q { color: var(--text, #e8e8e8); }

/* Collapsed recap chip for a completed step */
.ap-wiz-recap {
  display: flex; align-items: center; gap: 10px; padding: 10px 14px; margin-bottom: 10px;
  background: var(--bg, rgba(0,0,0,.02)); border: 1px solid var(--border, rgba(0,0,0,.08)); border-radius: 10px;
  cursor: pointer; transition: opacity .3s ease, transform .3s ease, border-color .15s ease;
}
.ap-wiz-recap:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.ap-wiz-recap-enter { opacity: 0; transform: translateY(-8px); }
.ap-wiz-recap-lbl { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: var(--muted, rgba(0,0,0,.4)); flex-shrink: 0; }
.ap-wiz-recap-val { font-size: 13px; font-weight: 600; color: var(--charcoal, #18181A); flex: 1; }
body.dark-mode .ap-wiz-recap-val { color: var(--text, #e8e8e8); }
.ap-wiz-recap-edit { font-size: 11.5px; color: var(--green-text); font-weight: 600; }
body.dark-mode .ap-wiz-recap-edit { color: var(--green); }

/* Selectable cards — platform / campaign / metric / action. Premium but
   restrained motion: a small lift + scale on hover, a clear but calm
   selected state. Selected state always uses dark text on the light-green
   tint (never white-on-green — see Autopilot Refinement contrast audit). */
.ap-wiz-cards { display: flex; flex-wrap: wrap; gap: 10px; }
.ap-wiz-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: 6px;
  min-width: 150px; flex: 1 1 150px; max-width: 220px;
  padding: 14px 16px; border-radius: 14px; border: 1px solid var(--border, rgba(0,0,0,.09));
  background: var(--surface, #fff); cursor: pointer; text-align: left;
  transition: transform .16s cubic-bezier(.16,1,.3,1), box-shadow .16s ease, border-color .16s ease, background .16s ease;
}
.ap-wiz-card:hover { transform: translateY(-2px) scale(1.015); box-shadow: 0 8px 20px rgba(0,0,0,.07); border-color: color-mix(in srgb, var(--green) 45%, transparent); }
.ap-wiz-card-selected, .ap-wiz-card-selected:hover {
  background: color-mix(in srgb, var(--green) 10%, transparent); border-color: var(--green); box-shadow: 0 0 0 1px var(--green);
}
.ap-wiz-card-icon { width: 26px; height: 26px; display: flex; align-items: center; justify-content: center; }
.ap-wiz-card-title { font-size: 13.5px; font-weight: 700; color: var(--charcoal, #18181A); }
body.dark-mode .ap-wiz-card-title { color: var(--text, #e8e8e8); }
.ap-wiz-card-desc { font-size: 11.5px; color: var(--muted, rgba(0,0,0,.45)); line-height: 1.4; }
.ap-wiz-card-disabled { opacity: .4; cursor: not-allowed; }
.ap-wiz-card-disabled:hover { transform: none; box-shadow: none; border-color: var(--border, rgba(0,0,0,.09)); }

/* Inline detail row revealed after selecting a metric/action card
   (operator + value, or a budget percentage) */
.ap-wiz-detail {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 14px;
  padding-top: 14px; border-top: 1px solid var(--border, rgba(0,0,0,.08));
}
.ap-wiz-detail-inp { width: auto; max-width: 110px; }
.ap-wiz-op-pills { display: flex; gap: 6px; flex-wrap: wrap; }
.ap-wiz-op-pill {
  font-size: 12px; padding: 6px 12px; border-radius: 20px; border: 1px solid var(--border, rgba(0,0,0,.12));
  background: transparent; color: var(--muted, rgba(0,0,0,.5)); cursor: pointer; transition: background .14s, color .14s, border-color .14s;
}
.ap-wiz-op-pill:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.ap-wiz-op-pill-active { background: color-mix(in srgb, var(--green) 14%, transparent); color: var(--charcoal, #18181A); border-color: color-mix(in srgb, var(--green) 35%, transparent); font-weight: 600; }
body.dark-mode .ap-wiz-op-pill-active { color: var(--text, #e8e8e8); }

/* Step 5 — the AI summary card. The centrepiece of Review: one confident
   sentence, never JSON, never a technical rule dump. */
.ap-wiz-review-card {
  display: flex; gap: 14px; align-items: flex-start; padding: 20px 22px; border-radius: 16px;
  background: color-mix(in srgb, var(--green) 7%, transparent); border: 1px solid color-mix(in srgb, var(--green) 24%, transparent);
}
body.dark-mode .ap-wiz-review-card { background: color-mix(in srgb, var(--green) 5%, transparent); border-color: color-mix(in srgb, var(--green) 20%, transparent); }
.ap-wiz-review-emoji { font-size: 22px; line-height: 1; flex-shrink: 0; }
.ap-wiz-review-text { font-size: 14.5px; line-height: 1.7; color: var(--charcoal, #18181A); }
body.dark-mode .ap-wiz-review-text { color: var(--text, #e8e8e8); }
.ap-wiz-review-text strong { color: var(--green-text); }
body.dark-mode .ap-wiz-review-text strong { color: var(--green); }

.ap-wiz-mode-row { margin-top: 18px; }
.ap-wiz-mode-q { font-size: 12.5px; font-weight: 600; color: var(--charcoal, #18181A); margin-bottom: 8px; }
body.dark-mode .ap-wiz-mode-q { color: var(--text, #e8e8e8); }
.ap-wiz-mode-cards { display: flex; gap: 8px; flex-wrap: wrap; }
.ap-wiz-mode-card {
  font-size: 12.5px; font-weight: 600; padding: 9px 14px; border-radius: 10px;
  border: 1px solid var(--border, rgba(0,0,0,.09)); background: var(--surface, #fff);
  color: var(--charcoal, #18181A); cursor: pointer; transition: border-color .14s, background .14s, transform .14s;
}
body.dark-mode .ap-wiz-mode-card { color: var(--text, #e8e8e8); }
.ap-wiz-mode-card:hover { transform: translateY(-1px); border-color: color-mix(in srgb, var(--green) 40%, transparent); }
.ap-wiz-mode-card-selected { background: color-mix(in srgb, var(--green) 10%, transparent); border-color: var(--green); box-shadow: 0 0 0 1px var(--green); }

@media (max-width: 640px) {
  .ap-wiz-card { max-width: none; }
}

/* Active Automations — narrative "story" cards, not field dumps. */
.ap-story-card {
  padding: 16px 18px; border-radius: 14px; border: 1px solid var(--border, rgba(0,0,0,.08));
  background: var(--surface, #fff); display: flex; flex-direction: column; gap: 10px;
  transition: border-color var(--orv-t, .16s), transform var(--orv-t, .16s), box-shadow var(--orv-t, .16s);
}
.ap-story-card:hover { border-color: color-mix(in srgb, var(--green) 28%, var(--b2, rgba(0,0,0,.14))); box-shadow: 0 6px 16px rgba(0,0,0,.06), 0 0 0 1px color-mix(in srgb, var(--green) 8%, transparent); transform: translateY(var(--orv-lift)) scale(var(--orv-scale)); }
body.dark-mode .ap-story-card:hover { border-color: color-mix(in srgb, var(--green) 32%, rgba(255,255,255,.14)); box-shadow: 0 6px 16px rgba(0,0,0,.25), 0 0 0 1px color-mix(in srgb, var(--green) 12%, transparent); }
.ap-story-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.ap-story-title { font-size: 14px; font-weight: 700; color: var(--charcoal, #18181A); }
body.dark-mode .ap-story-title { color: var(--text, #e8e8e8); }
.ap-story-meta { font-size: 11.5px; color: var(--muted, rgba(0,0,0,.45)); margin-top: 2px; }
.ap-story-sentence { font-size: 13.5px; line-height: 1.6; color: var(--charcoal, #18181A); }
body.dark-mode .ap-story-sentence { color: rgba(255,255,255,.8); }
.ap-story-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; padding-top: 8px; border-top: 1px solid var(--border, rgba(0,0,0,.07)); }
