/* ════════════════════════════════════════════════════════════════
   AUTOPILOT — Complete UX/UI Overhaul.
   Page-scoped override only (not the shared .ap-op-outer default other
   markup might still reference) — reuses --camp-content-maxw, the same
   token Campaigns/Intelligence already share, so all three sit on one
   real width value instead of a fourth independently-tuned one.
   ════════════════════════════════════════════════════════════════ */
#page-autopilot .ap-op-outer { max-width: var(--camp-content-maxw); padding-top: 68px; }

/* ── Hero ──────────────────────────────────────────────────────── */
.ap-hero-hdr { display: flex; align-items: flex-start; justify-content: space-between; gap: 32px; margin-bottom: var(--orv-title-gap); }
.ap-hero-copy { max-width: 560px; }
.ap-eyebrow { display: block; font-size: 11px; font-weight: 800; letter-spacing: .12em; color: var(--green-text); margin-bottom: 10px; }
body.dark-mode .ap-eyebrow { color: var(--green); }
.ap-hero-headline { font-size: 28px; font-weight: 800; letter-spacing: -.02em; line-height: 1.2; color: var(--charcoal, #18181A); margin: 0 0 8px; }
body.dark-mode .ap-hero-headline { color: rgba(255,255,255,.95); }
.ap-hero-sub { font-size: 14px; color: var(--muted); line-height: 1.55; margin: 0 0 18px; }
.ap-hero-status-row { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.ap-hero-status-pill {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 10.5px; font-weight: 800; letter-spacing: .07em; color: var(--green-text);
  background: color-mix(in srgb, var(--green) 10%, transparent); border: 1px solid color-mix(in srgb, var(--green) 22%, transparent);
  padding: 5px 11px; border-radius: 20px;
}
body.dark-mode .ap-hero-status-pill { color: var(--green); }
.ap-hero-status-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); animation: apStatusDotPulse 2.4s ease-in-out infinite; }
@keyframes apStatusDotPulse { 0%, 100% { opacity: 1; } 50% { opacity: .5; } }
.ap-hero-fact { font-size: 12px; color: var(--muted); }
.ap-hero-right { display: flex; flex-direction: column; align-items: flex-end; gap: 16px; flex-shrink: 0; }
.ap-hero-visual { color: rgba(255,255,255,.4); opacity: .85; }
body:not(.dark-mode) .ap-hero-visual { color: rgba(0,0,0,.32); opacity: 1; }
.ap-hero-flow-pulse { filter: drop-shadow(0 0 3px color-mix(in srgb, var(--green) 70%, transparent)); }
@media (prefers-reduced-motion: reduce) { .ap-hero-flow-pulse animateMotion, .ap-hero-flow-pulse { animation: none !important; } }
@media (max-width: 900px) {
  .ap-hero-hdr { flex-direction: column; gap: 18px; }
  .ap-hero-right { align-items: flex-start; width: 100%; }
  .ap-hero-visual { display: none; }
}

/* ── Automation Engine — Trigger -> AI decision -> Action ─────────
   Always a near-black surface (matches Intelligence's hero precedent),
   with the SAME ambient box-shadow glow technique learned building
   Intelligence (a child ::before clipped by overflow:hidden cannot glow
   "around" the block; box-shadow on the element itself, unaffected by its
   own overflow:hidden, can) — kept a little stronger here per the brief
   ("mag een iets sterkere glow hebben"), still always secondary to the
   content. */
.ap-engine {
  position: relative; overflow: hidden;
  background: #0e0e10; border: 1px solid rgba(255,255,255,.08); border-radius: 16px;
  padding: 26px 28px;
  display: flex; align-items: center; gap: 0; flex-wrap: wrap;
  box-shadow:
    0 20px 60px -28px rgba(0,0,0,.6),
    0 0 40px 0 color-mix(in srgb, var(--green) 16%, transparent),
    0 0 100px 0 color-mix(in srgb, var(--green) 8%, transparent);
  animation: apEngineGlowBreathe 5s ease-in-out infinite;
}
@keyframes apEngineGlowBreathe {
  0%, 100% { box-shadow: 0 20px 60px -28px rgba(0,0,0,.6), 0 0 40px 0 color-mix(in srgb, var(--green) 16%, transparent), 0 0 100px 0 color-mix(in srgb, var(--green) 8%, transparent); }
  50%      { box-shadow: 0 20px 60px -28px rgba(0,0,0,.6), 0 0 40px 0 color-mix(in srgb, var(--green) 11%, transparent), 0 0 100px 0 color-mix(in srgb, var(--green) 5%, transparent); }
}
.ap-engine-node {
  display: flex; flex-direction: column; gap: 5px; flex: 1 1 160px; min-width: 140px;
  padding: 14px 16px; border-radius: 12px; background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.08);
}
.ap-engine-node-lbl { font-size: 9.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.4); }
.ap-engine-node-val { font-size: 13.5px; font-weight: 700; color: rgba(255,255,255,.92); }
.ap-engine-node-ai .ap-engine-node-lbl { color: color-mix(in srgb, var(--green) 70%, rgba(255,255,255,.4)); }
.ap-engine-node-action { background: color-mix(in srgb, var(--green) 9%, transparent); border-color: color-mix(in srgb, var(--green) 30%, transparent); }
.ap-engine-node-action .ap-engine-node-lbl { color: var(--green); }
.ap-engine-node-action .ap-engine-node-val { color: var(--green); }
.ap-engine-connector { flex: 0 0 40px; height: 2px; margin: 0 4px; background: rgba(255,255,255,.12); position: relative; align-self: center; }
.ap-engine-connector-pulse {
  position: absolute; top: 50%; left: 0; width: 8px; height: 8px; margin-top: -4px; border-radius: 50%;
  background: var(--green); box-shadow: 0 0 6px color-mix(in srgb, var(--green) 80%, transparent);
  animation: apConnectorPulse 2.6s ease-in-out infinite;
}
@keyframes apConnectorPulse { 0% { left: 0; opacity: 0; } 15% { opacity: 1; } 85% { opacity: 1; } 100% { left: calc(100% - 8px); opacity: 0; } }
@media (max-width: 780px) {
  .ap-engine { flex-direction: column; align-items: stretch; }
  .ap-engine-connector { width: 2px; height: 24px; flex: 0 0 24px; margin: 0 auto; }
  .ap-engine-connector-pulse { top: 0; left: 50%; margin-left: -4px; margin-top: 0; animation-name: apConnectorPulseV; }
  @keyframes apConnectorPulseV { 0% { top: 0; opacity: 0; } 15% { opacity: 1; } 85% { opacity: 1; } 100% { top: calc(100% - 8px); opacity: 0; } }
}
@media (prefers-reduced-motion: reduce) {
  .ap-engine { animation: none !important; }
  .ap-engine-connector-pulse { animation: none !important; opacity: .6 !important; }
}

/* ── Monitoring Sources ────────────────────────────────────────── */
.ap-sources-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
@media (max-width: 900px) { .ap-sources-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) { .ap-sources-grid { grid-template-columns: 1fr; } }
.ap-source-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: 8px; text-align: left;
  padding: 16px 18px; border-radius: 14px; border: 1px solid var(--border, rgba(0,0,0,.08)); background: var(--surface, #fff);
  cursor: pointer; font-family: inherit; transition: border-color .16s, background .16s, transform .16s;
}
.ap-source-card:hover { transform: translateY(-2px); border-color: color-mix(in srgb, var(--green) 35%, var(--border)); background: color-mix(in srgb, var(--green) 4%, var(--surface)); }
body.dark-mode .ap-source-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.08); }
body.dark-mode .ap-source-card:hover { background: rgba(255,255,255,.05); border-color: color-mix(in srgb, var(--green) 40%, rgba(255,255,255,.14)); }
.ap-source-top { display: flex; align-items: center; gap: 8px; }
.ap-source-name { font-size: 13px; font-weight: 700; color: var(--charcoal, #18181A); }
body.dark-mode .ap-source-name { color: rgba(255,255,255,.92); }
.ap-source-body { font-size: 12px; color: var(--charcoal, #18181A); }
body.dark-mode .ap-source-body { color: rgba(255,255,255,.75); }
.ap-source-body-muted { color: var(--muted); }
.ap-sources-empty { grid-column: 1 / -1; display: flex; flex-direction: column; align-items: center; text-align: center; padding: 40px 20px; }
.ap-sources-empty-title { font-size: 11px; font-weight: 800; letter-spacing: .1em; color: var(--green-text); margin-bottom: 10px; }
body.dark-mode .ap-sources-empty-title { color: var(--green); }
.ap-sources-empty-sub { font-size: 15px; font-weight: 700; color: var(--charcoal, #18181A); margin-bottom: 6px; }
body.dark-mode .ap-sources-empty-sub { color: rgba(255,255,255,.92); }
.ap-sources-empty-sub2 { font-size: 12.5px; color: var(--muted); max-width: 380px; line-height: 1.55; margin-bottom: 18px; }

/* ── Active Automations — redesigned cards with a trigger->action flow,
   subtle status dot, and a real toggle. 3-column grid (Master Dashboard
   layout spec), matching Monitoring Sources' .ap-sources-grid pattern. ── */
.ap-active-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; align-items: start; }
@media (max-width: 1024px) { .ap-active-list { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 640px) { .ap-active-list { grid-template-columns: 1fr; } }
/* Empty-state text + example chips aren't wrapped in a card, so as direct
   children of the now-grid list they'd otherwise each claim one column. */
.ap-active-list > .ap-empty-text, .ap-active-list > .ap-wiz-cards { grid-column: 1 / -1; }
.ap-auto-card {
  padding: 16px 18px; border-radius: 14px; border: 1px solid var(--border, rgba(0,0,0,.08)); background: var(--surface, #fff);
  display: flex; flex-direction: column; gap: 10px;
  transition: border-color .16s, box-shadow .16s;
}
.ap-auto-card:hover { border-color: color-mix(in srgb, var(--green) 30%, var(--border)); box-shadow: 0 6px 18px rgba(0,0,0,.06), 0 0 0 1px color-mix(in srgb, var(--green) 10%, transparent); }
body.dark-mode .ap-auto-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.08); }
body.dark-mode .ap-auto-card:hover { border-color: color-mix(in srgb, var(--green) 32%, rgba(255,255,255,.14)); box-shadow: 0 6px 18px rgba(0,0,0,.25), 0 0 0 1px color-mix(in srgb, var(--green) 14%, transparent); }
.ap-auto-top { display: flex; align-items: center; gap: 8px; }
.ap-auto-icon { font-size: 13px; color: var(--green-text); flex-shrink: 0; }
body.dark-mode .ap-auto-icon { color: var(--green); }
.ap-auto-title { font-size: 14px; font-weight: 700; color: var(--charcoal, #18181A); }
body.dark-mode .ap-auto-title { color: rgba(255,255,255,.92); }
.ap-auto-meta { font-size: 11.5px; color: var(--muted); margin-top: -4px; }
.ap-auto-flow { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 13px; padding: 10px 12px; border-radius: 10px; background: color-mix(in srgb, var(--green) 4%, transparent); }
body.dark-mode .ap-auto-flow { background: rgba(255,255,255,.03); }
.ap-auto-flow-trigger { font-weight: 600; color: var(--charcoal, #18181A); }
body.dark-mode .ap-auto-flow-trigger { color: rgba(255,255,255,.85); }
.ap-auto-flow-arrow { color: var(--muted); }
.ap-auto-flow-action { font-weight: 700; color: var(--green-text); }
body.dark-mode .ap-auto-flow-action { color: var(--green); }
.ap-auto-foot { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; padding-top: 8px; border-top: 1px solid var(--border, rgba(0,0,0,.07)); }
body.dark-mode .ap-auto-foot { border-top-color: rgba(255,255,255,.06); }
.ap-auto-status { display: inline-flex; align-items: center; gap: 6px; font-size: 10.5px; font-weight: 800; letter-spacing: .06em; }
.ap-auto-status-dot { width: 6px; height: 6px; border-radius: 50%; }
.ap-status-active .ap-auto-status-dot { background: var(--green); }
.ap-status-active { color: var(--green-text); }
body.dark-mode .ap-status-active { color: var(--green); }
.ap-status-approval .ap-auto-status-dot { background: #f59e0b; }
.ap-status-approval { color: #b45309; }
body.dark-mode .ap-status-approval { color: #fbbf24; }
.ap-status-paused .ap-auto-status-dot { background: var(--muted); }
.ap-status-paused { color: var(--muted); }
.ap-status-failed .ap-auto-status-dot { background: #ef4444; }
.ap-status-failed { color: #dc2626; }
body.dark-mode .ap-status-failed { color: #f87171; }
.ap-auto-lastrun { font-size: 11.5px; color: var(--muted); }
.ap-auto-toggle { position: relative; display: inline-flex; align-items: center; cursor: pointer; margin-left: auto; }
.ap-auto-toggle input { position: absolute; opacity: 0; width: 0; height: 0; }
.ap-auto-toggle-track { width: 30px; height: 17px; border-radius: 10px; background: var(--border, rgba(0,0,0,.15)); position: relative; transition: background .16s; flex-shrink: 0; }
body.dark-mode .ap-auto-toggle-track { background: rgba(255,255,255,.14); }
.ap-auto-toggle-thumb { position: absolute; top: 2px; left: 2px; width: 13px; height: 13px; border-radius: 50%; background: #fff; transition: transform .16s; box-shadow: 0 1px 2px rgba(0,0,0,.2); }
.ap-auto-toggle input:checked + .ap-auto-toggle-track { background: var(--green); }
.ap-auto-toggle input:checked + .ap-auto-toggle-track .ap-auto-toggle-thumb { transform: translateX(13px); }
.ap-auto-toggle input:focus-visible + .ap-auto-toggle-track { outline: 2px solid var(--green); outline-offset: 2px; }

/* ── Autopilot Activity — timeline (was "Automation History") ─────── */
.ap-hist-daygroup { margin-bottom: 18px; }
.ap-hist-daylbl { display: flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 800; letter-spacing: .08em; color: var(--muted); margin-bottom: 8px; }
.ap-hist-daydot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); flex-shrink: 0; }
.ap-hist-row { display: flex; align-items: center; gap: 10px; padding: 8px 4px; font-size: 12.5px; color: var(--charcoal, #18181A); border-bottom: 1px solid var(--border, rgba(0,0,0,.05)); }
.ap-hist-row:last-child { border-bottom: none; }
body.dark-mode .ap-hist-row { color: rgba(255,255,255,.82); border-bottom-color: rgba(255,255,255,.05); }
.ap-hist-dot { width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0; }
.ap-hist-dot-done { background: var(--green); }
.ap-hist-dot-failed { background: #ef4444; }
.ap-hist-dot-neutral { background: var(--muted); }
.ap-hist-title { flex: 1; }
.ap-hist-time { font-size: 11px; color: var(--muted); flex-shrink: 0; }

/* ── Activity filter pills ─────────────────────────────────────── */
.ap-activity-filters { display: flex; gap: 6px; margin-bottom: 14px; flex-wrap: wrap; }
.ap-af-pill {
  font-size: 11.5px; font-weight: 600; padding: 5px 12px; border-radius: 20px;
  border: 1px solid var(--border, rgba(0,0,0,.1)); background: transparent; color: var(--muted); cursor: pointer;
  transition: background .14s, border-color .14s, color .14s;
}
.ap-af-pill:hover { border-color: color-mix(in srgb, var(--green) 35%, var(--border)); color: var(--charcoal, #18181A); }
body.dark-mode .ap-af-pill:hover { color: rgba(255,255,255,.85); }
.ap-af-pill-active { background: color-mix(in srgb, var(--green) 12%, transparent); border-color: var(--green); color: var(--green-text); }
body.dark-mode .ap-af-pill-active { color: var(--green); }

/* ── Compact settings link ─────────────────────────────────────── */
.ap-settings-link-row { padding: 4px 0 40px; }
.ap-settings-link-btn {
  font-size: 12.5px; font-weight: 600; color: var(--muted); background: none;
  border: 1px solid var(--border, rgba(0,0,0,.1)); border-radius: 9px; padding: 8px 14px; cursor: pointer;
  transition: color .14s, border-color .14s, background .14s;
}
.ap-settings-link-btn:hover { color: var(--charcoal, #18181A); border-color: color-mix(in srgb, var(--green) 35%, var(--border)); background: color-mix(in srgb, var(--green) 4%, transparent); }
body.dark-mode .ap-settings-link-btn { color: rgba(255,255,255,.5); }
body.dark-mode .ap-settings-link-btn:hover { color: rgba(255,255,255,.9); }

/* ── Create Automation / Settings modals — reuse the exact same premium
   dark panel chrome Intelligence's Monitored Campaigns selector already
   established (.intel-mon-panel); .ap-modal-panel only adds the light-
   theme-appropriate content color overrides the RELOCATED sections (which
   carry their own light/dark-aware .ap-wiz-*/.ap-builder-* styles, meant
   for a normal page background, not this always-dark panel) need once
   they're moved inside it. The relocated sections' own redundant "Create
   Automation Builder"/"Automation Settings" .ov3-sh header is hidden here
   since the modal's own topbar title already says the same thing. */
.ap-modal-panel { max-width: 640px; }
.ap-builder-modal-panel { max-width: 680px; }
.ap-builder-modal-body, .ap-settings-modal-body { padding: 20px 24px 24px; overflow-y: auto; max-height: calc(90vh - 60px); }
.ap-builder-modal-body #apBuilderSection > .ov3-sh,
.ap-settings-modal-body #apSettingsSection > .ov3-sh { display: none; }
.ap-builder-modal-body .ap-wiz-q,
.ap-builder-modal-body .ap-wiz-recap-val,
.ap-builder-modal-body .ap-wiz-card-title,
.ap-builder-modal-body .ap-wiz-review-text,
.ap-settings-modal-body .ap-builder-lbl { color: rgba(255,255,255,.92) !important; }
.ap-builder-modal-body .ap-wiz-card-desc,
.ap-builder-modal-body .ap-wiz-recap-lbl { color: rgba(255,255,255,.4) !important; }
.ap-builder-modal-body .ap-wiz-card { background: rgba(255,255,255,.03) !important; border-color: rgba(255,255,255,.1) !important; }
.ap-builder-modal-body .ap-wiz-recap { background: rgba(255,255,255,.03) !important; border-color: rgba(255,255,255,.1) !important; }
.ap-builder-modal-body .ap-wiz-mode-card { background: rgba(255,255,255,.03) !important; border-color: rgba(255,255,255,.1) !important; color: rgba(255,255,255,.85) !important; }
.ap-builder-modal-body .crws-select,
.ap-settings-modal-body .crws-select,
.ap-builder-modal-body input[type="text"],
.ap-builder-modal-body input[type="number"] {
  background: rgba(255,255,255,.04) !important; border-color: rgba(255,255,255,.14) !important; color: rgba(255,255,255,.9) !important;
}

/* ── Entrance animation — same split-trigger pattern as Intelligence
   (header/engine visible immediately; card lists stagger separately once
   their own real data has loaded), reusing the existing @keyframes
   intelFadeUp rather than a near-duplicate. ────────────────────────── */
.ap-anim-hdr, .ap-anim-hero { opacity: 0; }
.ap-anim-play .ap-anim-hdr  { animation: intelFadeUp .4s cubic-bezier(.22,1,.36,1) forwards; }
.ap-anim-play .ap-anim-hero { animation: intelFadeUp .5s cubic-bezier(.22,1,.36,1) .08s forwards; }
.ap-auto-card, .ap-hist-row { opacity: 0; }
.ap-anim-cards-apActiveList .ap-auto-card { animation: intelFadeUp .4s cubic-bezier(.22,1,.36,1) forwards; }
.ap-anim-cards-apHistoryList .ap-hist-row { animation: intelFadeUp .3s cubic-bezier(.22,1,.36,1) forwards; }

@media (prefers-reduced-motion: reduce) {
  .ap-anim-hdr, .ap-anim-hero, .ap-auto-card, .ap-hist-row { opacity: 1 !important; animation: none !important; transform: none !important; }
  .ap-hero-status-dot { animation: none !important; }
  .ap-source-card, .ap-auto-card, .ap-af-pill, .ap-settings-link-btn, .ap-auto-toggle-track, .ap-auto-toggle-thumb { transition: none !important; }
  .ap-source-card:hover, .ap-auto-card:hover { transform: none !important; }
}

/* ════════════════════════════════════════════════════════════════
   BUSINESS EXPERIENCE REDESIGN (Oriven 1.0) — Business Brain feels
   like teaching Oriven about the company, not filling in a form.
   Reuses .oi-card-btn / var(--surface) / var(--border) tokens already
   established elsewhere — no parallel design system.
   ════════════════════════════════════════════════════════════════ */

/* Business Final Polish — helper guidance as plain text, no mascot, no
   pill/card decoration. The AI already exists globally via the floating
   assistant; Business doesn't need to keep reintroducing it. */
.biz-ai-feedback {
  margin-bottom: 16px;
  font-size: 12.5px; line-height: 1.6; color: var(--muted);
  animation: bizFadeIn .3s ease;
}
body.dark-mode .biz-ai-feedback { color: rgba(255,255,255,.55); }
@keyframes bizFadeIn { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }

/* Knowledge card grid (Company / Goals / Brand Voice) */
.biz-card-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; align-items: start; }
.biz-card-grid .biz-kcard-wide { grid-column: 1 / -1; }
@media (max-width: 720px) { .biz-card-grid { grid-template-columns: 1fr; } }

.biz-kcard {
  background: var(--surface); border: 1px solid var(--border); border-radius: 16px;
  padding: 20px 22px; display: flex; flex-direction: column; gap: 14px;
  transition: border-color var(--orv-t, .16s), transform var(--orv-t, .16s), box-shadow var(--orv-t, .16s);
  animation: bizFadeIn .35s ease;
}
.biz-kcard:hover { border-color: color-mix(in srgb, var(--green) 30%, var(--b2)); box-shadow: 0 8px 20px rgba(0,0,0,.05), 0 0 0 1px color-mix(in srgb, var(--green) 10%, transparent); transform: translateY(var(--orv-lift)) scale(var(--orv-scale)); }
body.dark-mode .biz-kcard { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
body.dark-mode .biz-kcard:hover { border-color: color-mix(in srgb, var(--green) 35%, rgba(255,255,255,.14)); box-shadow: 0 8px 20px rgba(0,0,0,.28), 0 0 0 1px color-mix(in srgb, var(--green) 14%, transparent); }

.biz-kcard-hd { display: flex; align-items: center; gap: 9px; }
.biz-kcard-ico {
  width: 30px; height: 30px; border-radius: 9px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--green) 14%, transparent); color: var(--green-text);
}
body.dark-mode .biz-kcard-ico { background: color-mix(in srgb, var(--green) 10%, transparent); color: var(--green); }
.biz-kcard-title { font-size: 14.5px; font-weight: 700; color: var(--charcoal); letter-spacing: -.01em; }
body.dark-mode .biz-kcard-title { color: rgba(255,255,255,.92); }
.biz-kcard-sub { font-size: 11.5px; color: var(--muted); margin: -8px 0 0; line-height: 1.5; }

.biz-field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 12px; }
.biz-field-grid.biz-field-1col { grid-template-columns: 1fr; }
.biz-field {
  display: flex; flex-direction: column; gap: 4px; font-size: 11px; color: var(--muted);
}
.biz-field-wide { grid-column: 1 / -1; }
.biz-field input, .biz-field textarea {
  font-size: 12.5px; padding: 8px 10px; border-radius: 8px;
  border: 1px solid var(--border); background: var(--sf2); color: var(--charcoal);
  font-family: inherit; transition: border-color var(--orv-t, .16s), background var(--orv-t, .16s), box-shadow var(--orv-t, .16s);
}
.biz-field input:focus, .biz-field textarea:focus {
  outline: none; border-color: color-mix(in srgb, var(--green) 55%, transparent); background: var(--surface);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 14%, transparent);
}
body.dark-mode .biz-field input, body.dark-mode .biz-field textarea {
  background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.9);
}
body.dark-mode .biz-field input:focus, body.dark-mode .biz-field textarea:focus {
  border-color: color-mix(in srgb, var(--green) 45%, transparent); background: rgba(255,255,255,.05);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 16%, transparent);
}
.biz-field textarea { resize: vertical; min-height: 52px; line-height: 1.5; }

.biz-kcard-foot { display: flex; gap: 8px; margin-top: 2px; }

/* Brand Voice chips */
.biz-chip-row { display: flex; flex-wrap: wrap; gap: 8px; }
.biz-chip {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 6px 13px; border-radius: 100px; font-size: 12px; font-weight: 600;
  border: 1px solid var(--border); background: var(--sf2); color: var(--muted);
  cursor: pointer; transition: all .15s;
}
.biz-chip:hover { border-color: var(--b2); color: var(--charcoal); transform: translateY(-1px); }
.biz-chip-on {
  background: var(--green); border-color: var(--green); color: #0A0A0A;
}
.biz-chip-on:hover { opacity: .88; transform: translateY(-1px); color: #0A0A0A; }
body.dark-mode .biz-chip { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.5); }
body.dark-mode .biz-chip:hover { border-color: rgba(255,255,255,.22); color: rgba(255,255,255,.85); }
body.dark-mode .biz-chip-on { background: var(--green); border-color: var(--green); color: #0A0A0A; }
.biz-chip-x { font-size: 12px; line-height: 1; opacity: .7; }

/* Knowledge Completeness — motivational hero */
.biz-know-hero {
  display: flex; align-items: center; gap: 20px; padding: 22px 24px; border-radius: 16px;
  background: var(--surface); border: 1px solid var(--border); margin-bottom: 16px;
}
body.dark-mode .biz-know-hero { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
.biz-know-num { font-size: 34px; font-weight: 800; color: var(--charcoal); letter-spacing: -.03em; flex-shrink: 0; }
body.dark-mode .biz-know-num { color: #fff; }
.biz-know-num span { font-size: 15px; font-weight: 600; color: var(--muted); }
.biz-know-body { display: flex; flex-direction: column; gap: 4px; }
.biz-know-lbl { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.biz-know-msg { font-size: 13px; line-height: 1.55; color: var(--charcoal); max-width: 560px; }
body.dark-mode .biz-know-msg { color: rgba(255,255,255,.8); }

.biz-cat-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px,1fr)); gap: 8px; }
.biz-cat-card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; }
body.dark-mode .biz-cat-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
.biz-cat-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.biz-cat-name { font-size: 12px; font-weight: 600; color: var(--charcoal); }
body.dark-mode .biz-cat-name { color: rgba(255,255,255,.85); }
.biz-cat-pct { font-size: 11px; font-weight: 700; color: var(--muted); font-variant-numeric: tabular-nums; }
.biz-cat-track { height: 5px; border-radius: 4px; background: rgba(0,0,0,.06); overflow: hidden; }
body.dark-mode .biz-cat-track { background: rgba(255,255,255,.08); }
.biz-cat-fill { height: 100%; border-radius: 4px; background: var(--green-text); transition: width .5s ease; }
.biz-cat-fill.biz-cat-hi { background: #4ade80; }
.biz-cat-fill.biz-cat-lo { background: #f59e0b; }
.biz-cat-fill.biz-cat-crit { background: #f87171; }
.biz-stat-tile-val { font-size: 15px; font-weight: 700; color: var(--charcoal); }
body.dark-mode .biz-stat-tile-val { color: rgba(255,255,255,.85); }

/* Product / Audience / Competitor visual cards */
.biz-vcard-list { display: flex; flex-direction: column; gap: 10px; }
/* Products — 3-column grid (Master Dashboard layout spec). Audiences/
   Competitors keep the vertical list; they carry many more tag rows and sit
   side-by-side in Market's own 2-column layout instead of a per-card grid. */
.biz-vcard-grid3 { display: grid; grid-template-columns: repeat(3, 1fr); align-items: start; }
@media (max-width: 1024px) { .biz-vcard-grid3 { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 640px) { .biz-vcard-grid3 { grid-template-columns: 1fr; } }
/* Market tab — Audience and Competitors as two side-by-side columns. */
.biz-market-grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: start; }
@media (max-width: 900px) { .biz-market-grid2 { grid-template-columns: 1fr; gap: 28px; } }
/* Memory — 2-column grid instead of one long vertical list. */
.biz-mem-grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
@media (max-width: 720px) { .biz-mem-grid2 { grid-template-columns: 1fr; } }
.biz-mem-grid2 > .biz-empty { grid-column: 1 / -1; }
.biz-vcard {
  background: var(--surface); border: 1px solid var(--border); border-radius: 14px;
  padding: 16px 18px; transition: border-color var(--orv-t, .16s), box-shadow var(--orv-t, .16s), transform var(--orv-t, .16s);
  animation: bizFadeIn .35s ease;
}
.biz-vcard:hover { border-color: color-mix(in srgb, var(--green) 28%, var(--b2)); box-shadow: 0 6px 16px rgba(0,0,0,.06), 0 0 0 1px color-mix(in srgb, var(--green) 8%, transparent); transform: translateY(var(--orv-lift)) scale(var(--orv-scale)); }
body.dark-mode .biz-vcard { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
body.dark-mode .biz-vcard:hover { border-color: color-mix(in srgb, var(--green) 32%, rgba(255,255,255,.14)); box-shadow: 0 6px 16px rgba(0,0,0,.25), 0 0 0 1px color-mix(in srgb, var(--green) 12%, transparent); }

.biz-vcard-top { display: flex; align-items: center; gap: 12px; }
.biz-avatar {
  width: 40px; height: 40px; border-radius: 11px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; font-weight: 700; color: #0A0A0A;
}
.biz-vcard-name { font-size: 14.5px; font-weight: 700; color: var(--charcoal); letter-spacing: -.01em; }
body.dark-mode .biz-vcard-name { color: rgba(255,255,255,.92); }
.biz-vcard-badge {
  font-size: 10.5px; font-weight: 600; padding: 2px 9px; border-radius: 100px;
  background: rgba(0,0,0,.05); color: var(--muted); white-space: nowrap;
}
body.dark-mode .biz-vcard-badge { background: rgba(255,255,255,.07); color: rgba(255,255,255,.6); }
.biz-vcard-meta { font-size: 12px; color: var(--muted); margin-top: 2px; }
body.dark-mode .biz-vcard-meta { color: rgba(255,255,255,.45); }
.biz-vcard-actions { display: flex; gap: 6px; margin-left: auto; flex-shrink: 0; }

.biz-vcard-edit { margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--border); display: flex; flex-direction: column; gap: 12px; }
body.dark-mode .biz-vcard-edit { border-top-color: rgba(255,255,255,.08); }

/* Fact chips + tags (Audience/Competitor visual grouping) */
.biz-fact-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px,1fr)); gap: 8px; margin-top: 12px; }
.biz-fact-chip { background: rgba(0,0,0,.025); border: 1px solid var(--border); border-radius: 10px; padding: 8px 10px; }
body.dark-mode .biz-fact-chip { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
.biz-fact-lbl { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); margin-bottom: 2px; }
.biz-fact-val { font-size: 12.5px; font-weight: 600; color: var(--charcoal); }
body.dark-mode .biz-fact-val { color: rgba(255,255,255,.85); }
.biz-tag-block { margin-top: 10px; }
.biz-tag-lbl { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); margin-bottom: 6px; }
.biz-tag-row { display: flex; flex-wrap: wrap; gap: 6px; }
.biz-tag {
  font-size: 11.5px; padding: 4px 10px; border-radius: 100px;
  background: rgba(0,0,0,.04); color: var(--c2); border: 1px solid transparent;
}
body.dark-mode .biz-tag { background: rgba(255,255,255,.06); color: rgba(255,255,255,.75); }

.biz-vcard-empty { font-size: 12.5px; color: var(--muted); font-style: italic; }

.biz-add-btn {
  display: inline-flex; align-items: center; gap: 6px; margin-bottom: 14px;
  font-size: 12.5px; font-weight: 600; padding: 8px 15px; border-radius: 10px;
  border: 1px dashed var(--b2); background: transparent; color: var(--muted); cursor: pointer;
  transition: all .15s;
}
.biz-add-btn:hover { border-color: rgba(120,175,20,.5); color: var(--green-text); background: color-mix(in srgb, var(--green) 5%, transparent); }
body.dark-mode .biz-add-btn { border-color: rgba(255,255,255,.16); color: rgba(255,255,255,.5); }
body.dark-mode .biz-add-btn:hover { border-color: color-mix(in srgb, var(--green) 40%, transparent); color: var(--green); background: color-mix(in srgb, var(--green) 5%, transparent); }

/* Business Consolidation — Market tab (Audience + Competitors, one
   flowing section instead of two separate destinations). */
.biz-market-hd { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.biz-add-btn-inline { margin-bottom: 0; padding: 6px 12px; font-size: 12px; }

/* Audience vs Competitor "add" button parity. Root cause of the visible
   size mismatch was NOT just differing CSS classes (those were already
   unified) -- it was (a) two different text sources depending on empty vs.
   populated state ("Add Audience" vs "Add an audience", different lengths)
   and (b) the empty state's own container (.biz-empty) capping itself at
   max-width:460px while the populated state's plain div had no such cap --
   so even with identical classes, an inline-flex content-hugging button
   still rendered at two different widths. Forcing both to width:100% of
   their (already-equal, 1fr 1fr) grid column, and removing the empty
   state's max-width within this context, makes them pixel-identical
   regardless of which state either column is in. Scoped to
   .biz-market-section so Memory's own empty-state button (a different
   class, .biz-empty-cta) is unaffected. */
.biz-market-section .biz-empty { max-width: none; align-items: stretch; }
.biz-market-section .biz-add-btn {
  width: 100%;
  justify-content: center;
  align-self: stretch;
  margin-top: 12px;
}

/* ══════════════════════════════════════════════════════════════════
   BUSINESS — Command Center redesign. Reuses every existing .biz-*/
   .oi-card/.ov3-* primitive and real data source (business/health,
   business/insights, business/validate, {platform}/status,
   business/memory) — this block is visual language + a few new
   sections (Connected Ecosystem, Intelligence Map descriptions/
   actions), not a parallel design system or new backend. ══════════ */

/* Shell — same content width/top padding Campaigns and Intelligence
   already use, so Business's title sits on the same gridline. Merged into
   this block (was its own standalone rule immediately above) after a live
   browser check found the standalone rule never made it into the parsed
   CSSOM — every rule around it parsed fine (confirmed via
   document.styleSheets[].cssRules), so rather than chase the one-off
   drop, the fix is written directly into a block already proven to load. */
#page-business-brain .orv-page-wrap { max-width: var(--camp-content-maxw); padding-top: 68px; }

/* Segmented nav — mirrors #orvHubTabsCampaigns' track treatment (same
   .orv-tab-row/.prf-ptab elements, scoped override only, so nothing
   else that uses .prf-ptab is touched) turning 7 loose pills into one
   dark, rounded, cohesive control. */
#page-business-brain .orv-tab-row {
  display: inline-flex; gap: 2px; margin-bottom: var(--orv-title-gap);
  background: rgba(0,0,0,.035); border: 1px solid rgba(0,0,0,.08);
  border-radius: 10px; padding: 3px; max-width: 100%; overflow-x: auto; scrollbar-width: none;
}
#page-business-brain .orv-tab-row::-webkit-scrollbar { display: none; }
body.dark-mode #page-business-brain .orv-tab-row { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
#page-business-brain .prf-ptab {
  border-radius: 7px; border: 1px solid transparent; background: transparent; padding: 7px 15px;
  transition: background .2s ease, color .2s ease, box-shadow .2s ease;
}
#page-business-brain .prf-ptab:hover { background: color-mix(in srgb, var(--green) 8%, transparent); color: var(--charcoal, #18181A); }
#page-business-brain .prf-ptab.active {
  background: var(--green); color: #0B0B0C; border-color: transparent;
  box-shadow: 0 1px 4px rgba(0,0,0,.18), 0 0 0 1px color-mix(in srgb, var(--green) 35%, transparent), 0 0 12px color-mix(in srgb, var(--green) 30%, transparent);
}
body.dark-mode #page-business-brain .prf-ptab { color: rgba(255,255,255,.45); }
body.dark-mode #page-business-brain .prf-ptab:hover { background: color-mix(in srgb, var(--green) 10%, transparent); color: #fff; }
body.dark-mode #page-business-brain .prf-ptab.active { background: var(--green); color: #0B0B0C; }
/* Segmented control shouldn't nudge neighbours like the loose pill row
   does elsewhere on this page's shared .orv-tab-row base rule. */
#page-business-brain .orv-tab-row > button,
#page-business-brain .orv-tab-row > button:hover,
#page-business-brain .orv-tab-row > button:hover + button,
#page-business-brain .orv-tab-row > button:has(+ button:hover) { transform: none; }

/* Overview section rhythm */
.biz-ov-section { margin-top: 28px; }
.biz-ov-section-last { margin-bottom: 8px; }
.biz-ov-sh { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; }
.biz-ov-sh-col { display: flex; flex-direction: column; gap: 3px; }
.biz-ov-sh-sub { font-size: 12px; color: var(--muted); margin: 0; line-height: 1.5; }

/* Business Intelligence hero — same box-shadow-breathing-glow technique
   proven on .intel-hero: an element's own box-shadow (spread 0, real px
   blur) radiates evenly around every edge and is never clipped by its
   own overflow:hidden, unlike a child ::before radial-gradient. Own
   keyframe (not a reuse of intelHeroGlowBreathe) so this page's timing
   can evolve independently, matching the precedent already set when
   Autopilot built its own apEngineGlowBreathe rather than importing
   Intelligence's. */
.biz-hero {
  position: relative; overflow: hidden;
  background: #0e0e10; border: 1px solid rgba(255,255,255,.08);
  border-radius: 16px; padding: 24px 26px; margin-bottom: 16px;
  box-shadow:
    0 20px 60px -28px rgba(0,0,0,.6),
    0 0 36px 0 color-mix(in srgb, var(--green) 13%, transparent),
    0 0 90px 0 color-mix(in srgb, var(--green) 6%, transparent);
  animation: bizHeroGlowBreathe 5.5s ease-in-out infinite;
}
@media (prefers-reduced-motion: reduce) { .biz-hero { animation: none; } }
@keyframes bizHeroGlowBreathe {
  0%, 100% {
    box-shadow: 0 20px 60px -28px rgba(0,0,0,.6), 0 0 36px 0 color-mix(in srgb, var(--green) 13%, transparent), 0 0 90px 0 color-mix(in srgb, var(--green) 6%, transparent);
  }
  50% {
    box-shadow: 0 20px 60px -28px rgba(0,0,0,.6), 0 0 36px 0 color-mix(in srgb, var(--green) 9%, transparent), 0 0 90px 0 color-mix(in srgb, var(--green) 3%, transparent);
  }
}
.biz-hero-eyebrow { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .09em; color: rgba(255,255,255,.4); margin-bottom: 16px; position: relative; z-index: 1; }
.biz-hero-main { display: flex; align-items: center; gap: 26px; position: relative; z-index: 1; }
.biz-hero-score { display: flex; align-items: baseline; flex-shrink: 0; }
.biz-hero-num { font-size: 44px; font-weight: 800; color: #fff; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.biz-hero-max { font-size: 17px; font-weight: 600; color: rgba(255,255,255,.35); margin-left: 2px; }
.biz-hero-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 7px; }
.biz-hero-lbl { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: rgba(255,255,255,.45); }
.biz-hero-track { height: 6px; border-radius: 4px; background: rgba(255,255,255,.08); overflow: hidden; max-width: 420px; }
.biz-hero-fill { height: 100%; border-radius: 4px; background: var(--green); transition: width .8s cubic-bezier(.16,1,.3,1); }
@media (prefers-reduced-motion: reduce) { .biz-hero-fill { transition: none; } }
.biz-hero-msg { font-size: 13px; line-height: 1.55; color: rgba(255,255,255,.7); max-width: 520px; }
.biz-hero-side { flex-shrink: 0; text-align: right; padding-left: 22px; border-left: 1px solid rgba(255,255,255,.1); }
.biz-hero-side-num { font-size: 19px; font-weight: 700; color: var(--green); font-variant-numeric: tabular-nums; }
.biz-hero-side-lbl { font-size: 10.5px; color: rgba(255,255,255,.4); margin-top: 2px; }
@media (max-width: 720px) {
  .biz-hero-main { flex-wrap: wrap; }
  .biz-hero-side { border-left: none; padding-left: 0; text-align: left; border-top: 1px solid rgba(255,255,255,.1); padding-top: 12px; width: 100%; }
}

/* Business Intelligence Map — same category cards as before, now with
   real hierarchy: description + a real next action per area instead of
   a flat percentage grid. */
.biz-map-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
@media (max-width: 1024px) { .biz-map-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 640px) { .biz-map-grid { grid-template-columns: 1fr; } }
/* Master Dashboard Layout Pass — six distinct, substantial cards (not six
   tiny rows): real height (~200px) via generous padding + a large lead
   number, not fabricated content. */
.biz-map-card {
  background: var(--surface); border: 1px solid var(--border); border-radius: 16px; padding: 22px 24px;
  display: flex; flex-direction: column; gap: 14px; min-height: 200px;
  transition: border-color .16s, box-shadow .16s, transform .16s;
  animation: bizFadeIn .35s ease;
}
.biz-map-card:hover { border-color: color-mix(in srgb, var(--green) 26%, var(--b2)); box-shadow: 0 8px 22px rgba(0,0,0,.07); transform: translateY(-2px); }
body.dark-mode .biz-map-card { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
body.dark-mode .biz-map-card:hover { border-color: color-mix(in srgb, var(--green) 30%, rgba(255,255,255,.14)); box-shadow: 0 8px 22px rgba(0,0,0,.3); }
.biz-map-card .biz-cat-name { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; }
.biz-map-card .biz-cat-pct { font-size: 30px; font-weight: 800; color: var(--charcoal); letter-spacing: -.02em; }
body.dark-mode .biz-map-card .biz-cat-pct { color: rgba(255,255,255,.94); }
.biz-map-card .biz-cat-track { height: 6px; margin-top: 2px; }
.biz-map-desc { font-size: 12.5px; color: var(--muted); line-height: 1.5; margin: 0; flex: 1; }
.biz-map-action {
  align-self: flex-start; font-size: 11.5px; font-weight: 600; color: var(--green-text);
  background: none; border: none; padding: 0; cursor: pointer; text-align: left;
}
.biz-map-action:hover { text-decoration: underline; }
body.dark-mode .biz-map-action { color: var(--green); }

/* Connected Ecosystem — same {platform}/status endpoints + platform
   icons as Connections/Autopilot; system-state rows, not a second
   connection UI. */
.biz-eco-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
