.biz-ov-row-7-5 { display: grid; grid-template-columns: 7fr 5fr; gap: 20px; align-items: stretch; }
@media (max-width: 1024px) { .biz-ov-row-7-5 { grid-template-columns: 1fr; } }
.biz-ov-col7, .biz-ov-col5 { display: flex; flex-direction: column; min-width: 0; }
