.intel-row-2-1 { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; align-items: start; }
@media (max-width: 1024px) { .intel-row-2-1 { grid-template-columns: 1fr; } }
.intel-col2, .intel-col1 { padding-left: 0; padding-right: 0; }
.intel-mon-sidebar {
