  display: flex; flex-direction: column; gap: 4px; min-height: 160px;
}
body.dark-mode .intel-mon-sidebar { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.07); }
.intel-mon-sb-row { display: flex; align-items: center; gap: 9px; padding: 8px 0; border-bottom: 1px solid var(--border); font-size: 12.5px; color: var(--charcoal); }
body.dark-mode .intel-mon-sb-row { border-color: rgba(255,255,255,.07); color: rgba(255,255,255,.85); }
.intel-mon-sb-row:last-child { border-bottom: none; }
