.orv-sb-nav { padding: 8px 10px !important; }
.orv-sb .orv-ni { padding: 9px 10px; gap: 10px; font-size: 13px; }

/* Platform shortcuts — belong visually to Campaigns: indented, smaller
   type, no icon/label size competing with the real nav items above. */
.orv-ni-plat-group { display: flex; flex-direction: column; gap: 1px; margin: 2px 0 6px 8px; padding-left: 14px; border-left: 1px solid var(--border, rgba(0,0,0,.08)); }
body.dark-mode .orv-ni-plat-group { border-left-color: rgba(255,255,255,.08); }
.orv-ni-plat {
  display: flex; align-items: center; gap: 8px; width: 100%; text-align: left;
  padding: 6px 8px; border-radius: 7px; border: none; background: none; cursor: pointer;
  font-size: 11.5px; font-weight: 500; color: var(--muted, rgba(0,0,0,.45));
  transition: background .12s, color .12s;
}
.orv-ni-plat:hover { background: color-mix(in srgb, var(--green) 7%, transparent); color: var(--charcoal, #18181A); }
body.dark-mode .orv-ni-plat:hover { color: rgba(255,255,255,.85); }
.orv-ni-plat-ico { width: 13px; height: 13px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; opacity: .85; }
.orv-ni-plat-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
