.ov-brand-card.ov-brand-google .ov-brand-ico { background: rgba(251,188,5,.09); color: rgba(251,188,5,.9); }
.ov-brand-card.ov-brand-google { border-color: rgba(251,188,5,.13); }
.ov-brand-card.ov-brand-google:hover { border-color: rgba(251,188,5,.4); background: rgba(255,255,255,.045); }

.ov-brand-card.ov-brand-meta .ov-brand-ico { background: rgba(8,102,255,.1); color: rgba(64,140,255,.95); }
.ov-brand-card.ov-brand-meta { border-color: rgba(8,102,255,.14); }
.ov-brand-card.ov-brand-meta:hover { border-color: rgba(8,102,255,.42); background: rgba(255,255,255,.045); }

.ov-brand-card.ov-brand-tiktok .ov-brand-ico { background: rgba(238,29,82,.1); color: rgba(238,60,100,.95); }
.ov-brand-card.ov-brand-tiktok { border-color: rgba(238,29,82,.13); }
