.ov-sp-glow::before { content: none !important; animation: none !important; }

.ov-sp-network { width: 100%; max-width: 900px; margin: 0 auto 28px; opacity: 0; transform: translateY(10px); transition: opacity .6s ease, transform .6s ease; }
.ov-sp-network.ov-vis { opacity: .85; transform: translateY(0); }
.ov-sp-network svg { width: 100%; height: auto; display: block; }
