/* ══════════════════════════════════════════════════════════════════
   REDESIGN v9 — Ad showcase rebuilt as generated creatives (no image
   assets). Every visual is inline SVG + CSS; see index.html's _advKind
   library and AD_DATA for the 30 cards. Only .ov-wall-card's own
   internal layout changes here — the marquee/track/animation mechanics
   above (ovWallSlide, fade transition, hover-pause) are untouched.
   ══════════════════════════════════════════════════════════════════ */

/* Base override: the old rule centered a single <img>/placeholder span;
   generated cards need normal top-to-bottom flow instead. */
.adv-card {
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  text-align: left;
  background: #0c0c10;
  /* Skips paint/layout work for the many off-screen duplicate cards the
     infinite-loop marquee keeps in the DOM (each row doubles its 10-card
     set) — a real perf win for 30 cards x SVG + animated children x 2
     duplicates x 2 rows, with zero visual difference. */
  content-visibility: auto;
  contain-intrinsic-size: 340px 220px;
}
.adv-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

/* ── Shared decorative-animation vocabulary used across every _advKind
   composition — small, slow, staggered by inline animation-delay where
   it matters (chart bars) so a card never reads as "everything moving
   at once". ── */
@keyframes advFloat      { 0%, 100% { transform: translateY(0); }     50% { transform: translateY(-6px); } }
@keyframes advFloatSlow  { 0%, 100% { transform: translateY(0) rotate(0deg); } 50% { transform: translateY(-4px) rotate(1.5deg); } }
@keyframes advPulse      { 0%, 100% { opacity: .6; transform: scale(1); } 50% { opacity: 1; transform: scale(1.35); } }
@keyframes advSpin       { to { transform: rotate(360deg); } }
@keyframes advSteam      { 0% { opacity: 0; transform: translateY(2px); } 35% { opacity: .6; } 100% { opacity: 0; transform: translateY(-16px); } }
@keyframes advGrow       { from { transform: scaleY(0); } to { transform: scaleY(1); } }
@keyframes advProgress   { 0% { width: 4%; } 100% { width: 96%; } }

.adv-float      { animation: advFloat 5s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
.adv-float-slow { animation: advFloatSlow 7s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
.adv-pulse      { animation: advPulse 2.4s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
.adv-spin-slow  { animation: advSpin 20s linear infinite; transform-box: fill-box; transform-origin: center; }
.adv-steam path { animation: advSteam 3s ease-in-out infinite; transform-box: fill-box; }
.adv-steam path:nth-child(2) { animation-delay: .5s; }
.adv-steam path:nth-child(3) { animation-delay: 1s; }
.adv-grow       { transform-box: fill-box; transform-origin: bottom; animation: advGrow 1.4s cubic-bezier(.16,1,.3,1) both; }

@media (prefers-reduced-motion: reduce) {
  .adv-float, .adv-float-slow, .adv-pulse, .adv-spin-slow, .adv-steam path, .adv-t-progress span { animation: none !important; }
  .adv-grow { animation: none !important; transform: scaleY(1) !important; }
}

/* ── Google Ads card — text-forward, search-ad language, with a
   compact generated visual as a secondary accent (not full-bleed). ── */
.adv-card-google { padding: 16px 18px 14px; gap: 8px; }
.adv-g-top { display: flex; align-items: center; gap: 6px; font-size: 11px; }
.adv-g-sponsored { border: 1px solid rgba(255,255,255,.28); border-radius: 3px; padding: 1px 5px 0; font-size: 9.5px; font-weight: 700; letter-spacing: .03em; color: rgba(255,255,255,.6); line-height: 1.5; }
.adv-g-dot { color: rgba(255,255,255,.3); }
.adv-g-adv { font-weight: 500; color: rgba(255,255,255,.55); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.adv-g-body { flex: 1; display: flex; gap: 14px; align-items: flex-start; min-height: 0; }
.adv-g-text { flex: 1; min-width: 0; }
/* Both bounded to a fixed number of lines regardless of how long the
   generated category/headline text is -- the mobile overlap bug (CTA
   footer rendering on top of the headline's 2nd line) traced back to
   these two having no such cap: a long uppercase, letter-spaced category
   string would wrap to 2 lines with nothing to stop it, silently eating
   the vertical budget a fixed-height card never accounted for, and
   .adv-g-body's flex-shrunk box let its own children overflow past it
   uncontained (only the outer .ov-wall-card clips, and only below its
   own edge -- not what was overlapping mid-card). */
.adv-g-cat { font-size: 10px; color: rgba(255,255,255,.35); margin-bottom: 4px; text-transform: uppercase; letter-spacing: .03em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.adv-g-headline { font-size: 15px; font-weight: 700; color: #fff; line-height: 1.26; margin-bottom: 5px; letter-spacing: -.01em; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.adv-g-desc { font-size: 12px; color: rgba(255,255,255,.5); line-height: 1.45; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.adv-g-visual { width: 62px; height: 62px; flex-shrink: 0; border-radius: 12px; background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.07); position: relative; overflow: hidden; display: flex; align-items: center; justify-content: center; }
.adv-g-foot { display: flex; align-items: center; justify-content: space-between; margin-top: auto; padding-top: 10px; border-top: 1px solid rgba(255,255,255,.07); }
.adv-g-cta { display: inline-flex; align-items: center; gap: 5px; font-size: 12.5px; font-weight: 600; color: var(--green, #B7FF2A); }
.adv-g-cta svg { transition: transform .2s ease; }
.ov-wall-card:hover .adv-g-cta svg { transform: translateX(2px); }
.adv-g-stat { font-size: 11px; color: #FBBC05; font-weight: 600; }

/* ── Meta Ads card — social-feed language, the generated visual is the
