.adv-m-head { display: flex; align-items: center; gap: 8px; padding: 10px 12px 8px; }
.adv-m-avatar { width: 22px; height: 22px; border-radius: 50%; background: linear-gradient(135deg, var(--green, #B7FF2A), #3B82F6); display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; color: #07070A; flex-shrink: 0; }
.adv-m-who { display: flex; flex-direction: column; line-height: 1.25; flex: 1; min-width: 0; }
.adv-m-name { font-size: 12px; font-weight: 600; color: #fff; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.adv-m-sponsored { font-size: 10px; color: rgba(255,255,255,.4); }
.adv-m-globe { color: rgba(255,255,255,.35); flex-shrink: 0; }
.adv-m-visual { position: relative; flex: 1; min-height: 0; background: rgba(255,255,255,.025); overflow: hidden; margin: 0 2px; }
