.adv-m-body { padding: 9px 12px 5px; display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.adv-m-copy { font-size: 11.5px; line-height: 1.4; color: rgba(255,255,255,.65); flex: 1; min-width: 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.adv-m-copy strong { color: #fff; font-weight: 700; }
.adv-m-cta { flex-shrink: 0; font-size: 11px; font-weight: 700; color: #07070A; background: var(--green, #B7FF2A); padding: 6px 11px; border-radius: 7px; white-space: nowrap; }
.adv-m-meta { padding: 0 12px 10px; display: flex; align-items: center; gap: 4px; font-size: 10.5px; color: rgba(255,255,255,.4); }
.adv-m-likes { display: flex; align-items: center; gap: 4px; color: rgba(238,29,82,.75); }

/* ── TikTok Ads card — vertical (9:16), full-bleed animated visual,
