/* ══════════════════════════════════════════════════════════════════
   REDESIGN v10 — Autopilot workflow card: the timeline previously sat
   flush against the card's left edge, stretched to the full width of
   the (very wide, 1.15fr) visual column with nothing to its right —
   a large dead zone on wide screens. Merely centering a shrink-wrapped
   text column left the same problem in miniature (a narrow strip of
   text floating in empty space either side). Instead each step becomes
   a bordered row panel — reusing the exact neutral background/border
   values already used by .ov-launch-mock itself and by .ov-conn-card
   in the Business section below, so the panel genuinely fills a
   deliberate width instead of just adding invisible margin. Only
   layout changes here: no step text, no text/icon colors, no
   typography, no animation timing touched — the new background/border
   is copied verbatim from components already on this exact page.
   ══════════════════════════════════════════════════════════════════ */
.ov-lm-timeline {
  /* Sized relative to its own parent (never a fixed px that could exceed
     the card's actual available space) and capped so it doesn't stretch
     edge-to-edge on very wide cards. */
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
}
.ov-lm-step {
  width: 100%;
  gap: 32px !important;
  padding: 18px 22px !important;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 12px;
  box-sizing: border-box;
}
.ov-lm-num { width: 38px !important; height: 38px !important; font-size: 13px !important; }
.ov-lm-connector { margin-left: 41px !important; }
@media (max-width: 900px) {
  .ov-lm-step { gap: 18px !important; padding: 14px 16px !important; }
  .ov-lm-num { width: 30px !important; height: 30px !important; }
  .ov-lm-connector { margin-left: 31px !important; }
}

/* ══════════════════════════════════════════════════════════════════
   AD EDITING WORKSPACE — the three-column conversational workspace
   (app.html#page-ad-workspace) that opens after a campaign package is
   generated. Follows the same light/body.dark-mode override convention
   as every other app.html component in this file (.orv-ai-*, .cr2-box)
   rather than a separate theme system — reuses --green/--border/
   --surface/--charcoal/--muted/--t, no new tokens invented.
   ══════════════════════════════════════════════════════════════════ */

#page-ad-workspace {
  background-image:
    linear-gradient(rgba(0,0,0,.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0,0,0,.02) 1px, transparent 1px);
  background-size: 56px 56px;
}
body.dark-mode #page-ad-workspace {
  background-image:
    linear-gradient(rgba(255,255,255,.022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.022) 1px, transparent 1px);
}

/* .page{min-height:100%} (base rule) is a floor, not a ceiling -- with
   only that, a tall chat conversation grows the whole page instead of
   scrolling internally, and .mc (height:100vh;overflow-y:auto) ends up
   scrolling chat+preview+details as one blob. Pinning a firm height
   down the chain (#page-ad-workspace -> .aw-shell -> .aw-col) lets each
   column's own overflow:auto actually activate instead. */
#page-ad-workspace.active { height: 100%; overflow: hidden; }
.aw-shell { display: grid; grid-template-columns: 340px 1fr 320px; height: 100%; min-height: 0; align-items: stretch; }
.aw-col { display: flex; flex-direction: column; min-width: 0; min-height: 0; height: 100%; overflow: hidden; }
.aw-col-chat { border-right: 1px solid var(--border); }
.aw-col-details { border-left: 1px solid var(--border); }
body.dark-mode .aw-col-chat, body.dark-mode .aw-col-details { border-color: rgba(255,255,255,.08); }

/* ── Chat (left) ─────────────────────────────────────────────────── */
.aw-chat-head { flex-shrink: 0; padding: 20px 20px 14px; border-bottom: 1px solid var(--border); }
body.dark-mode .aw-chat-head { border-color: rgba(255,255,255,.08); }
.aw-chat-title { font-size: 13px; font-weight: 700; letter-spacing: .04em; color: var(--charcoal); }
body.dark-mode .aw-chat-title { color: rgba(255,255,255,.9); }
.aw-chat-status { font-size: 12px; color: var(--green); margin-top: 3px; font-weight: 600; }

.aw-chat-feed { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 18px 20px; display: flex; flex-direction: column; gap: 12px; scrollbar-width: thin; scrollbar-color: var(--b2) transparent; min-height: 0; }

.aw-msg { display: flex; flex-direction: column; gap: 4px; }
.aw-msg-user .aw-msg-bubble { align-self: flex-end; background: color-mix(in srgb, var(--green) 12%, transparent); color: var(--charcoal); border-radius: 12px 12px 3px 12px; }
body.dark-mode .aw-msg-user .aw-msg-bubble { color: rgba(255,255,255,.92); }
.aw-msg-ai .aw-msg-bubble { align-self: flex-start; background: var(--surface); border: 1px solid var(--border); border-radius: 3px 12px 12px 12px; color: var(--charcoal); }
body.dark-mode .aw-msg-ai .aw-msg-bubble { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.85); }
.aw-msg-bubble { padding: 9px 13px; font-size: 13px; line-height: 1.55; max-width: 90%; white-space: pre-wrap; }

.aw-chat-inputrow { flex-shrink: 0; display: flex; gap: 8px; align-items: center; padding: 14px 16px; border-top: 1px solid var(--border); }
body.dark-mode .aw-chat-inputrow { border-color: rgba(255,255,255,.08); }
.aw-chat-input { flex: 1; font-size: 13px; padding: 9px 13px; border-radius: 10px; border: 1.5px solid var(--border); background: var(--surface); color: var(--charcoal); outline: none; transition: border-color var(--t); }
.aw-chat-input:focus { border-color: var(--green); }
body.dark-mode .aw-chat-input { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.92); }
.aw-chat-send { flex-shrink: 0; width: 34px; height: 34px; border-radius: 9px; border: none; background: var(--green); color: #000; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: opacity var(--t), transform var(--t); }
.aw-chat-send:hover { opacity: .88; transform: scale(1.03); }
.aw-chat-send:disabled { opacity: .5; cursor: default; transform: none; }

/* ── Preview (center) ────────────────────────────────────────────── */
.aw-preview-toolbar { flex-shrink: 0; display: flex; align-items: center; justify-content: space-between; padding: 18px 28px 0; }
.aw-preview-platform { font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; padding: 4px 10px; border-radius: 20px; border: 1px solid var(--border); color: var(--muted); }
body.dark-mode .aw-preview-platform { border-color: rgba(255,255,255,.12); color: rgba(255,255,255,.55); }
.aw-preview-platform[data-plat="google"] { color: #b8860b; border-color: rgba(251,188,5,.4); }
.aw-preview-platform[data-plat="meta"]   { color: #0866FF; border-color: rgba(8,102,255,.35); }
.aw-preview-platform[data-plat="tiktok"] { color: #EE1D52; border-color: rgba(238,29,82,.35); }
/* Labeled placement/preview-format switcher — replaces the old anonymous
   concept-variant dots. Same creative, different layout; switching is a
   pure client-side re-layout (see _awSwitchPlacement), never a network
   call or credit charge. */
.aw-placement-tabs { display: flex; gap: 4px; background: var(--surface); border: 1px solid var(--border); border-radius: 9px; padding: 3px; }
body.dark-mode .aw-placement-tabs { background: rgba(255,255,255,.03); border-color: rgba(255,255,255,.08); }
.aw-placement-tab { font-size: 11.5px; font-weight: 600; color: var(--muted); background: none; border: none; border-radius: 6px; padding: 5px 11px; cursor: pointer; transition: background var(--t), color var(--t); }
body.dark-mode .aw-placement-tab { color: rgba(255,255,255,.5); }
.aw-placement-tab:hover { color: var(--charcoal); }
body.dark-mode .aw-placement-tab:hover { color: rgba(255,255,255,.8); }
.aw-placement-tab-active { background: var(--green); color: #000 !important; }

.aw-preview-stage { flex: 1; display: flex; align-items: center; justify-content: center; padding: 28px; opacity: 0; transform: translateY(6px) scale(.99); transition: opacity .32s ease, transform .32s ease; }
.aw-preview-stage.aw-stage-in { opacity: 1; transform: translateY(0) scale(1); }
.aw-preview-stage.aw-stage-out { opacity: 0; transform: translateY(-4px) scale(.99); transition: opacity .2s ease, transform .2s ease; }

/* The sizer is the persistent element whose width/height animate on
   placement switch (a real resize/morph, not just a crossfade) — its
   inner .aw-pv card always fills it exactly. Target sizes come from the
   AW_PLACEMENT_SIZE table in JS. ~380ms, matching the "300-500ms,
   restrained" ask alongside the stage's own opacity fade. */
.aw-pv-sizer { position: relative; max-width: 100%; border-radius: 16px; overflow: hidden; transition: width .38s cubic-bezier(.4,0,.2,1), height .38s cubic-bezier(.4,0,.2,1); }
.aw-pv { position: relative; width: 100%; height: 100%; border-radius: 16px; overflow: hidden; box-sizing: border-box; }

/* Google — search-ad style, text only (real Google Search ads have no image) */
.aw-pv-google { background: var(--surface); border: 1px solid var(--border); padding: 18px 20px; display: flex; flex-direction: column; justify-content: center; box-sizing: border-box; }
body.dark-mode .aw-pv-google { background: rgba(255,255,255,.025); border-color: rgba(255,255,255,.08); }
.aw-pv-g-top { display: flex; align-items: center; gap: 6px; font-size: 12px; margin-bottom: 6px; }
.aw-pv-g-ad { border: 1px solid var(--muted); border-radius: 3px; padding: 0 4px; font-size: 10.5px; font-weight: 700; color: var(--muted); }
.aw-pv-g-dot { color: var(--muted); }
.aw-pv-g-url { color: var(--charcoal); }
body.dark-mode .aw-pv-g-url { color: rgba(255,255,255,.7); }
.aw-pv-g-headline { font-size: 19px; font-weight: 500; color: #1a0dab; line-height: 1.3; margin-bottom: 5px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
body.dark-mode .aw-pv-g-headline { color: #8ab4f8; }
.aw-pv-g-desc { font-size: 13.5px; color: var(--charcoal); line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
body.dark-mode .aw-pv-g-desc { color: rgba(255,255,255,.68); }

/* Google — YouTube (video-thumbnail style) */
.aw-pv-g-yt { background: #0b0b0b; display: flex; flex-direction: column; }
.aw-pv-g-yt-visual { position: relative; flex: 1; min-height: 0; background: var(--bg2); }
.aw-pv-g-yt-play { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); width: 44px; height: 44px; border-radius: 50%; background: rgba(0,0,0,.55); display: flex; align-items: center; justify-content: center; z-index: 1; }
.aw-pv-g-yt-badge { position: absolute; left: 8px; bottom: 8px; font-size: 10.5px; font-weight: 600; color: #fff; background: rgba(0,0,0,.6); padding: 2px 7px; border-radius: 4px; z-index: 1; }
.aw-pv-g-yt-foot { flex-shrink: 0; display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 14px; background: #181818; }
.aw-pv-g-yt-title { font-size: 12.5px; font-weight: 600; color: #fff; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.aw-pv-g-yt-cta { flex-shrink: 0; font-size: 11px; font-weight: 700; color: #fff; border: 1px solid rgba(255,255,255,.3); padding: 5px 11px; border-radius: 4px; }

/* Google — Display (banner-style, image-led) */
.aw-pv-g-disp { background: var(--bg2); }
.aw-pv-g-disp-scrim { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,.82) 0%, rgba(0,0,0,.15) 55%, transparent 100%); }
.aw-pv-g-disp-foot { position: absolute; left: 12px; right: 12px; bottom: 12px; z-index: 1; }
.aw-pv-g-disp-ad { display: inline-block; font-size: 9.5px; font-weight: 700; color: rgba(255,255,255,.6); border: 1px solid rgba(255,255,255,.4); border-radius: 3px; padding: 0 4px; margin-bottom: 6px; }
.aw-pv-g-disp-headline { font-size: 15px; font-weight: 700; color: #fff; line-height: 1.25; margin-bottom: 8px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.aw-pv-g-disp-cta { font-size: 11.5px; font-weight: 700; color: #000; background: var(--green); padding: 6px 13px; border-radius: 6px; border: none; }

/* Google — Shopping (product tile) */
.aw-pv-g-shop { background: var(--surface); border: 1px solid var(--border); display: flex; flex-direction: column; }
body.dark-mode .aw-pv-g-shop { background: rgba(255,255,255,.025); border-color: rgba(255,255,255,.08); }
.aw-pv-g-shop-visual { position: relative; flex: 1; min-height: 0; background: var(--bg2); }
.aw-pv-g-shop-body { flex-shrink: 0; padding: 10px 12px 12px; }
.aw-pv-g-shop-title { font-size: 12.5px; font-weight: 600; color: var(--charcoal); line-height: 1.35; margin-bottom: 3px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
body.dark-mode .aw-pv-g-shop-title { color: rgba(255,255,255,.92); }
.aw-pv-g-shop-store { font-size: 10.5px; color: var(--muted); margin-bottom: 8px; }
.aw-pv-g-shop-cta { display: inline-block; font-size: 11px; font-weight: 700; color: #000; background: var(--green); padding: 5px 11px; border-radius: 6px; }

/* Meta — social feed card, dominant visual */
.aw-pv-meta { background: var(--surface); border: 1px solid var(--border); display: flex; flex-direction: column; }
body.dark-mode .aw-pv-meta { background: rgba(255,255,255,.025); border-color: rgba(255,255,255,.08); }
.aw-pv-m-head { display: flex; align-items: center; gap: 9px; padding: 12px 14px; }
.aw-pv-m-avatar { width: 30px; height: 30px; border-radius: 50%; background: linear-gradient(135deg, var(--green), #0866FF); display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; color: #000; flex-shrink: 0; }
.aw-pv-m-name { font-size: 13px; font-weight: 600; color: var(--charcoal); }
body.dark-mode .aw-pv-m-name { color: rgba(255,255,255,.92); }
.aw-pv-m-sponsored { font-size: 11px; color: var(--muted); }
.aw-pv-m-visual { position: relative; width: 100%; aspect-ratio: 1/1; background: var(--bg2); overflow: hidden; flex-shrink: 0; }
.aw-pv-img { width: 100%; height: 100%; object-fit: cover; display: block; transition: opacity .25s ease, transform .4s ease; }
.aw-pv-img-empty { background: linear-gradient(135deg, var(--bg2), var(--bg3)); animation: awShimmer 1.8s ease-in-out infinite; }
body.dark-mode .aw-pv-img-empty { background: linear-gradient(135deg, rgba(255,255,255,.03), rgba(255,255,255,.06)); }
@keyframes awShimmer { 0%, 100% { opacity: .6; } 50% { opacity: 1; } }
.aw-pv-m-body { padding: 12px 14px 16px; flex-shrink: 0; }
.aw-pv-m-primary { font-size: 12.5px; color: var(--charcoal); line-height: 1.5; margin-bottom: 8px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
body.dark-mode .aw-pv-m-primary { color: rgba(255,255,255,.7); }
.aw-pv-m-headline { font-size: 14.5px; font-weight: 700; color: var(--charcoal); margin-bottom: 10px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
body.dark-mode .aw-pv-m-headline { color: rgba(255,255,255,.92); }
.aw-pv-m-cta { font-size: 12.5px; font-weight: 700; color: #000; background: var(--green); padding: 7px 14px; border-radius: 8px; border: none; cursor: default; }

/* Meta — Story / Reels (vertical, full-bleed image, overlay chrome) */
.aw-pv-m-vert { background: #000; }
.aw-pv-m-vert-bar { position: absolute; top: 8px; left: 10px; right: 10px; display: flex; gap: 4px; z-index: 2; }
.aw-pv-m-vert-bar span { flex: 1; height: 2px; border-radius: 2px; background: rgba(255,255,255,.9); }
.aw-pv-m-vert-bar span:last-child { background: rgba(255,255,255,.3); }
.aw-pv-m-vert-head { position: absolute; top: 16px; left: 10px; right: 10px; display: flex; align-items: center; gap: 7px; z-index: 2; }
.aw-pv-m-avatar-sm { width: 22px; height: 22px; font-size: 10px; }
.aw-pv-m-vert-name { font-size: 11.5px; font-weight: 600; color: #fff; }
.aw-pv-m-vert-spon { font-size: 10px; color: rgba(255,255,255,.65); }
.aw-pv-m-vert-scrim { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.35) 0%, transparent 22%, transparent 55%, rgba(0,0,0,.85) 100%); }
.aw-pv-m-vert-foot { position: absolute; left: 12px; right: 40px; bottom: 14px; z-index: 1; }
.aw-pv-m-vert-headline { font-size: 13.5px; font-weight: 700; color: #fff; line-height: 1.28; margin-bottom: 8px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.aw-pv-m-vert-cta { font-size: 11px; font-weight: 700; color: #000; background: var(--green); padding: 6px 12px; border-radius: 6px; border: none; }
.aw-pv-m-reels .aw-pv-m-vert-sidebar { position: absolute; right: 8px; bottom: 60px; display: flex; flex-direction: column; gap: 12px; z-index: 1; }
.aw-pv-m-vert-ico { width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 15px; }

/* TikTok — vertical, full-bleed */
.aw-pv-tiktok { background: #000; }
.aw-pv-t-visual { position: absolute; inset: 0; }
.aw-pv-t-scrim { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.1) 0%, rgba(0,0,0,.08) 40%, rgba(0,0,0,.9) 100%); }
.aw-pv-t-foot { position: absolute; left: 14px; right: 14px; bottom: 16px; z-index: 1; }
.aw-pv-t-hook { font-size: 15px; font-weight: 800; color: #fff; line-height: 1.25; margin-bottom: 4px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.aw-pv-t-desc { font-size: 11.5px; color: rgba(255,255,255,.72); margin-bottom: 10px; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.aw-pv-t-cta { display: inline-block; font-size: 11.5px; font-weight: 700; color: #fff; border: 1.5px solid #fff; padding: 6px 15px; border-radius: 22px; background: transparent; cursor: default; }
.aw-pv-t-progress { position: absolute; top: 8px; left: 10px; right: 10px; height: 2px; background: rgba(255,255,255,.25); border-radius: 2px; z-index: 2; overflow: hidden; }
.aw-pv-t-progress span { display: block; height: 100%; width: 38%; background: #fff; border-radius: 2px; }
.aw-pv-t-play { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); z-index: 2; opacity: .9; }

/* Wipe / creative-swap effect — a soft light band sweeps across the
   image, old opacity fades under it, new image settles in with a
   gentle scale-down. No flash, no shake, no glow, per spec. */
.aw-wipe { position: absolute; inset: 0; pointer-events: none; z-index: 2; overflow: hidden; }
.aw-wipe::before { content: ''; position: absolute; top: 0; bottom: 0; left: -40%; width: 40%; background: linear-gradient(100deg, transparent, rgba(255,255,255,.32), transparent); }
.aw-wipe.aw-wipe-play::before { animation: awWipeSweep 1.3s cubic-bezier(.4,0,.2,1) 1; }
@keyframes awWipeSweep { from { left: -40%; } to { left: 100%; } }
.aw-img-settle { animation: awImgSettle .5s cubic-bezier(.16,1,.3,1) both; }
@keyframes awImgSettle { from { opacity: 0; transform: scale(1.04); } to { opacity: 1; transform: scale(1); } }

/* Typing cursor, used briefly by the delete/retype text-swap animation */
.aw-typing::after { content: ''; display: inline-block; width: 2px; height: 1em; margin-left: 1px; background: var(--green); vertical-align: text-bottom; animation: awCursorBlink .8s steps(1) infinite; }
@keyframes awCursorBlink { 50% { opacity: 0; } }

/* ── Details (right) ─────────────────────────────────────────────── */
.aw-details-head { flex-shrink: 0; padding: 20px 20px 14px; font-size: 12px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); border-bottom: 1px solid var(--border); }
body.dark-mode .aw-details-head { border-color: rgba(255,255,255,.08); color: rgba(255,255,255,.4); }
.aw-details-body { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 8px 20px 20px; transition: opacity .2s ease; scrollbar-width: thin; scrollbar-color: var(--b2) transparent; min-height: 0; }
.aw-details-body.aw-details-out { opacity: 0; }

.aw-field { padding: 12px 0; border-bottom: 1px solid var(--border); opacity: 0; transform: translateY(4px); transition: opacity .3s ease, transform .3s ease, background-color .5s ease; border-radius: 6px; }
body.dark-mode .aw-field { border-color: rgba(255,255,255,.06); }
.aw-field.aw-field-in { opacity: 1; transform: translateY(0); }
.aw-field:last-child { border-bottom: none; }
.aw-field-label { font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); margin-bottom: 4px; }
.aw-field-val { font-size: 13px; color: var(--charcoal); line-height: 1.5; }
body.dark-mode .aw-field-val { color: rgba(255,255,255,.85); }
.aw-field-list { color: var(--muted); }
.aw-field-more { color: var(--green); font-weight: 600; }
.aw-field-pulse { animation: awFieldPulse .5s ease; }
@keyframes awFieldPulse { 0%, 100% { background: transparent; } 35% { background: color-mix(in srgb, var(--green) 8%, transparent); } }

/* ── Mobile: stacked tabs (Chat / Preview / Details), Preview default ── */
.aw-mobile-tabs { display: none; }
@media (max-width: 900px) {
  .aw-shell { display: block; }
  .aw-col { display: none; min-height: calc(100vh - 120px); }
  .aw-col.aw-col-mactive { display: flex; }
  .aw-col-chat, .aw-col-details { border: none; }
  .aw-mobile-tabs { display: flex; position: sticky; top: 0; z-index: 5; background: var(--bg); border-bottom: 1px solid var(--border); }
  body.dark-mode .aw-mobile-tabs { border-color: rgba(255,255,255,.08); }
  .aw-mtab { flex: 1; padding: 12px 0; font-size: 12.5px; font-weight: 600; color: var(--muted); background: none; border: none; border-bottom: 2px solid transparent; cursor: pointer; }
  .aw-mtab-active { color: var(--green); border-bottom-color: var(--green); }
}

@media (prefers-reduced-motion: reduce) {
  .aw-preview-stage, .aw-pv-sizer, .aw-field, .aw-pv-img, .aw-wipe::before, .aw-img-settle, .aw-typing::after, .aw-field-pulse {
    transition: none !important; animation: none !important;
  }
  .aw-preview-stage, .aw-field { opacity: 1 !important; transform: none !important; }
}
